window.BARALHOS = window.BARALHOS || {};
window.BARALHOS['fr'] = {"versao":1,"idioma":"fr","curso":"fr-en","audiencia":"en","leva":"8671daf4","total":1440,"cards":[{"idioma":"fr","id":"fr-b001","tipo":"frase","fr":"Bonjour !","aceitasFr":["Bonjour.","Bonjour, madame.","Bonjour, monsieur."],"en":"Hello!","aceitasEn":["hello","good morning","good afternoon","good day"],"distratoresEn":["Good night!","See you tomorrow!","Welcome!","Good luck!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"It works from morning until evening: good morning and good afternoon in one word. In France, saying «Bonjour» as you walk into a shop is close to mandatory.","requerTodas":[],"v":"4c50d50d"},{"idioma":"fr","id":"fr-b002","tipo":"frase","fr":"Bonsoir !","aceitasFr":["Bonsoir.","Bonsoir, madame.","Bonsoir, monsieur."],"en":"Good evening!","aceitasEn":["good evening","evening"],"distratoresEn":["Good morning!","Good afternoon!","See you tomorrow!","Have a good trip!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"The greeting when you arrive in the evening. When someone goes to bed, French says «Bonne nuit» instead.","requerTodas":[],"v":"49b42210"},{"idioma":"fr","id":"fr-b003","tipo":"frase","fr":"Salut !","aceitasFr":["Salut.","Coucou !"],"en":"Hi!","aceitasEn":["hi","hey","hiya"],"distratoresEn":["Thanks!","Careful!","Congratulations!","Help!"],"nivel":"A1","tags":["primeiros passos","social","gíria"],"notaEn":"The casual hello among friends and colleagues; with strangers, use «Bonjour». It also works as a casual bye. The final «t» is silent.","requerTodas":[],"v":"123d5ee1"},{"idioma":"fr","id":"fr-b004","tipo":"frase","fr":"Au revoir !","aceitasFr":["Au revoir.","Au revoir, madame.","Au revoir, monsieur."],"en":"Goodbye!","aceitasEn":["goodbye","good bye","bye","bye bye"],"distratoresEn":["Welcome!","Thank you!","Congratulations!","Cheers!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"The goodbye that works with anyone, at any time. Literally «until seeing again». «Au» sounds like «oh».","requerTodas":[],"v":"8d6af516"},{"idioma":"fr","id":"fr-b005","tipo":"frase","fr":"Merci !","aceitasFr":["Merci.","Merci bien !"],"en":"Thank you!","aceitasEn":["thank you","thanks"],"distratoresEn":["Please!","You're welcome!","Sorry!","Congratulations!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"The stress falls at the end: «mehr-SEE», with the throaty French «r».","requerTodas":[],"v":"349d0e6c"},{"idioma":"fr","id":"fr-b006","tipo":"frase","fr":"Merci beaucoup !","aceitasFr":["Merci beaucoup.","Merci mille fois !"],"en":"Thank you very much!","aceitasEn":["thank you very much","thank you so much","thanks a lot","thanks so much","many thanks"],"distratoresEn":["Nice to meet you!","Very well done!","Of course, go ahead!","Everything's fine here!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"«Beaucoup» means a lot, and it goes after: «merci beaucoup», never «beaucoup merci». Say «boh-KOO».","requerTodas":[],"v":"419a49d1"},{"idioma":"fr","id":"fr-b007","tipo":"frase","fr":"De rien !","aceitasFr":["De rien.","Je vous en prie.","Je t'en prie.","Avec plaisir !"],"en":"You're welcome!","aceitasEn":["you are welcome","youre welcome","no problem","dont mention it","not at all","my pleasure"],"distratoresEn":["Once again!","Please!","Whatever!","Not bad!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"Literally «of nothing»: «rien» means nothing. More formal: «Je vous en prie».","requerTodas":[],"v":"3c158524"},{"idioma":"fr","id":"fr-b008","tipo":"frase","fr":"S'il vous plaît.","aceitasFr":["S'il te plaît.","SVP"],"en":"Please.","aceitasEn":["please"],"distratoresEn":["Excuse me.","Thank you.","Sorry.","See you."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"Literally «if it pleases you». With people you call «tu» (friends, family, children) it becomes «s'il te plaît». In writing: «SVP».","requerTodas":[],"v":"dad0a242"},{"idioma":"fr","id":"fr-b009","tipo":"frase","fr":"Excusez-moi.","aceitasFr":["Excuse-moi.","Pardon."],"en":"Excuse me.","aceitasEn":["excuse me","pardon me","sorry"],"distratoresEn":["Please.","Thank you.","See you later.","Welcome."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"To get someone's attention, get past people, or apologize for something small. With «tu»: «Excuse-moi». «Pardon» does the same job.","requerTodas":[],"v":"446da295"},{"idioma":"fr","id":"fr-b010","tipo":"frase","fr":"Je suis désolé.","aceitasFr":["Je suis désolée.","Désolé.","Désolée."],"en":"I'm sorry.","aceitasEn":["i am sorry","sorry","im so sorry","i am so sorry"],"distratoresEn":["I'm tired.","I'm late.","Nice to meet you.","I don't know."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"A woman writes «désolée»; it sounds the same. It is the everyday apology, not a dramatic word.","requerTodas":[],"v":"7ca213a2"},{"idioma":"fr","id":"fr-b011","tipo":"frase","fr":"Oui, bien sûr.","aceitasFr":["Bien sûr.","Oui, bien sûr !","Oui, évidemment."],"en":"Yes, of course.","aceitasEn":["yes of course","of course","sure","yes sure","yes certainly","certainly"],"distratoresEn":["No, thank you.","Yes, maybe.","No, never.","Yes, later."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"«Bien sûr» means of course; literally «well sure». «Oui» sounds like «wee».","requerTodas":[],"v":"fc252c17"},{"idioma":"fr","id":"fr-b012","tipo":"frase","fr":"Non, merci.","aceitasFr":["Non merci."],"en":"No, thank you.","aceitasEn":["no thank you","no thanks"],"distratoresEn":["Yes, please.","No, never.","Yes, thank you.","Not now."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"The polite refusal, to a waiter or anyone offering something. To accept: «Oui, merci» or «Oui, s'il vous plaît».","requerTodas":[],"v":"76959b07"},{"idioma":"fr","id":"fr-b013","tipo":"frase","fr":"Je ne comprends pas.","aceitasFr":["Je comprends pas."],"en":"I don't understand.","aceitasEn":["i do not understand","i dont understand","i dont get it"],"distratoresEn":["I don't agree.","I don't remember.","I can't.","I don't want to."],"nivel":"A1","tags":["primeiros passos","gramática"],"notaEn":"French negation has two parts: «ne» before the verb and «pas» after it. In speech the «ne» often drops («Je comprends pas»), but «pas» never does.","requerTodas":[],"v":"5ab567d0"},{"idioma":"fr","id":"fr-b014","tipo":"frase","fr":"Vous pouvez répéter, s'il vous plaît ?","aceitasFr":["Pouvez-vous répéter, s'il vous plaît ?","Tu peux répéter, s'il te plaît ?","Vous pouvez répéter ?"],"en":"Could you repeat that, please?","aceitasEn":["could you repeat that please","can you repeat that please","could you repeat please","can you say that again please","could you say that again please"],"distratoresEn":["Could you wait a moment, please?","Could you come in, please?","Could you write it down, please?","Could you sit down, please?"],"nivel":"A1","tags":["primeiros passos","escola"],"notaEn":"«Vous» is the polite you, for one person, and also the plural you. With friends: «Tu peux répéter ?».","requerTodas":[],"v":"edec3654"},{"idioma":"fr","id":"fr-b015","tipo":"frase","fr":"Vous parlez anglais ?","aceitasFr":["Parlez-vous anglais ?","Tu parles anglais ?","Est-ce que vous parlez anglais ?"],"en":"Do you speak English?","aceitasEn":["do you speak english","you speak english","can you speak english"],"distratoresEn":["Do you study English?","Do you understand English?","Do you teach English?","Do you like English?"],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"Languages are lowercase in French: «anglais», «français». Asking with just a rising tone, no inversion, is the everyday way.","requerTodas":[],"v":"777691a9"},{"idioma":"fr","id":"fr-b016","tipo":"frase","fr":"Je parle un peu français.","aceitasFr":["Je parle un petit peu français.","Je parle un peu le français."],"en":"I speak a little French.","aceitasEn":["i speak a little french","i speak a bit of french","i speak some french"],"distratoresEn":["I speak French very well.","I understand a little French.","I study a little French.","I speak a little English."],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"«Un peu» is a little; «parler français» needs no article in this phrase.","requerTodas":[],"v":"b75ba417"},{"idioma":"fr","id":"fr-b017","tipo":"frase","fr":"Parlez plus lentement, s'il vous plaît.","aceitasFr":["Parle plus lentement, s'il te plaît.","Plus lentement, s'il vous plaît.","Vous pouvez parler plus lentement ?"],"en":"Please speak more slowly.","aceitasEn":["please speak more slowly","speak more slowly please","speak slower please","please speak slower","could you speak more slowly","slower please"],"distratoresEn":["Please speak louder.","Please speak more quietly.","Please walk more slowly.","Please write more slowly."],"nivel":"A1","tags":["primeiros passos","escola"],"notaEn":"«Parlez» is the «vous» imperative. «-ment» makes adverbs, like English «-ly»: «lentement», slowly.","requerTodas":[],"v":"6fc86399"},{"idioma":"fr","id":"fr-b018","tipo":"frase","fr":"Comment vous appelez-vous ?","aceitasFr":["Comment tu t'appelles ?","Tu t'appelles comment ?","Vous vous appelez comment ?","Quel est votre nom ?"],"en":"What's your name?","aceitasEn":["what is your name","whats your name","may i have your name"],"distratoresEn":["Where are you from?","Where do you live?","How old are you?","How are you doing?"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"Literally «how do you call yourself?»: the verb is «s'appeler», to be called. Casually: «Tu t'appelles comment ?».","requerTodas":[],"v":"01c4665d"},{"idioma":"fr","id":"fr-b019","tipo":"frase","fr":"Je m'appelle Ana.","aceitasFr":["Moi, c'est Ana.","Mon nom est Ana.","Je suis Ana."],"en":"My name is Ana.","aceitasEn":["my name is ana","im ana","i am ana","my names ana"],"distratoresEn":["I live with Ana.","I'm calling Ana.","I'm Ana's friend.","Ana called me."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"«Je m'appelle» is literally «I call myself». Without the «m'», «J'appelle Ana» means I'm calling Ana. You also hear «Moi, c'est Ana».","requerTodas":[],"v":"51c43a18"},{"idioma":"fr","id":"fr-b020","tipo":"frase","fr":"Enchanté.","aceitasFr":["Enchantée.","Enchanté de vous connaître.","Ravi de vous rencontrer."],"en":"Nice to meet you.","aceitasEn":["nice to meet you","pleased to meet you","good to meet you","nice meeting you"],"distratoresEn":["Very tired.","Welcome.","See you soon.","Excuse me."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"A woman writes «enchantée»; it sounds the same. It is what you say when introduced; among young people «Salut» is enough.","requerTodas":[],"v":"99f1bf28"},{"idioma":"fr","id":"fr-b021","tipo":"frase","fr":"Ça va ?","aceitasFr":["Comment ça va ?","Ça va bien ?"],"en":"How's it going?","aceitasEn":["hows it going","how is it going","how are things"],"distratoresEn":["Is everything ready?","Are you leaving?","Who is it?","Where is it?"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"It is both the question and the answer: «— Ça va ? — Ça va.» Literally «it goes». Casual; with strangers, «Comment allez-vous ?».","requerTodas":[],"v":"2d61f16c"},{"idioma":"fr","id":"fr-b022","tipo":"frase","fr":"Ça va bien, merci.","aceitasFr":["Ça va, merci.","Très bien, merci.","Bien, merci.","Je vais bien, merci."],"en":"I'm fine, thanks.","aceitasEn":["im fine thanks","i am fine thanks","im fine thank you","i am fine thank you","fine thanks","fine thank you","im good thanks","good thanks","im well thanks"],"distratoresEn":["All set, thanks.","So-so, thanks.","I'm fine, and you?","I'm tired, thanks."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"«Ça va» is also the answer. Great: «Ça va très bien». So-so: «Comme ci, comme ça».","requerTodas":[],"v":"4c1fab22"},{"idioma":"fr","id":"fr-b023","tipo":"frase","fr":"Comment allez-vous ?","aceitasFr":["Vous allez bien ?","Comment vas-tu ?"],"en":"How are you?","aceitasEn":["how are you","how are you doing","how do you do"],"distratoresEn":["What is your name?","Where do you live?","Where are you going?","How did you get here?"],"nivel":"A1","tags":["primeiros passos","social","formal"],"notaEn":"The polite form, for people you call «vous». The verb is «aller», to go: «Où allez-vous ?» would be where are you going. Answer: «Je vais bien, merci».","requerTodas":[],"v":"6c0d7dfb"},{"idioma":"fr","id":"fr-b024","tipo":"frase","fr":"Et vous ?","aceitasFr":["Et toi ?","Et vous-même ?"],"en":"And you?","aceitasEn":["and you","what about you","how about you","and yourself"],"distratoresEn":["And then?","And so?","And now?","And why?"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"It bounces the question back: «— Ça va ? — Ça va, et toi ?». «Vous» is polite or plural; «toi» is for friends.","requerTodas":[],"v":"c60e1dbc"},{"idioma":"fr","id":"fr-b025","tipo":"frase","fr":"Où sont les toilettes ?","aceitasFr":["Où sont les toilettes, s'il vous plaît ?","Les toilettes, s'il vous plaît ?","Où se trouvent les toilettes ?"],"en":"Where is the restroom?","aceitasEn":["where is the restroom","wheres the restroom","where is the bathroom","wheres the bathroom","where are the restrooms","where is the toilet"],"distratoresEn":["Where is the exit?","Where is the kitchen?","Where is the bedroom?","Where is the elevator?"],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"The French word is always plural, «les toilettes», even for a single restroom. «Où» with the accent means where; «ou» without it means or.","requerTodas":[],"v":"73f27ec0"},{"idioma":"fr","id":"fr-b026","tipo":"frase","fr":"C'est combien ?","aceitasFr":["Ça coûte combien ?","Combien ça coûte ?","Combien ?"],"en":"How much is it?","aceitasEn":["how much is it","how much","how much does it cost","how much is this","how much does this cost"],"distratoresEn":["How much is left?","How long does it take?","When does it open?","Where is it?"],"nivel":"A1","tags":["primeiros passos","compras"],"notaEn":"Literally «it's how much?», with «combien» at the end, which is how people ask in conversation.","requerTodas":[],"v":"d5589339"},{"idioma":"fr","id":"fr-b027","tipo":"frase","fr":"L'addition, s'il vous plaît.","aceitasFr":["L'addition, s'il te plaît.","L'addition !"],"en":"The check, please.","aceitasEn":["the check please","check please","can i have the check please","could we have the check please"],"regionaisEn":{"The bill, please.":"no Reino Unido"},"distratoresEn":["The menu, please.","Some water, please.","My change, please.","A table, please."],"nivel":"A1","tags":["primeiros passos","comida"],"notaEn":"At a restaurant the check is «l'addition», literally the sum. A bank account is «le compte».","requerTodas":[],"v":"a9d76f97"},{"idioma":"fr","id":"fr-b028","tipo":"frase","fr":"Je voudrais un café, s'il vous plaît.","aceitasFr":["Un café, s'il vous plaît.","Je voudrais un café.","Je prendrais un café, s'il vous plaît."],"en":"I'd like a coffee, please.","aceitasEn":["id like a coffee please","i would like a coffee please","a coffee please","can i have a coffee please","could i have a coffee please","coffee please"],"distratoresEn":["I'd like a tea, please.","I had a coffee, thanks.","I'll pay for the coffee.","I'd like some water, please."],"nivel":"A1","tags":["primeiros passos","comida"],"notaEn":"«Je voudrais» is the conditional of «vouloir», to want: the polite request, like I'd like. «Je veux» sounds blunt. In France «un café» is an espresso.","requerTodas":[],"v":"a63f101d"},{"idioma":"fr","id":"fr-b029","tipo":"frase","fr":"Une table pour deux, s'il vous plaît.","aceitasFr":["Une table pour deux personnes, s'il vous plaît.","Une table pour deux."],"en":"A table for two, please.","aceitasEn":["a table for two please","table for two please","a table for two","a table for two people please"],"distratoresEn":["A table for three, please.","A chair for two, please.","A room for two, please.","A table by the window, please."],"nivel":"A1","tags":["primeiros passos","comida"],"notaEn":"«La table» is feminine. The «x» in «deux» is silent.","requerTodas":[],"v":"9ab6a148"},{"idioma":"fr","id":"fr-b030","tipo":"frase","fr":"Où est la gare ?","aceitasFr":["Où se trouve la gare ?","La gare, c'est où ?","Où est la gare, s'il vous plaît ?"],"en":"Where is the train station?","aceitasEn":["where is the train station","wheres the train station","where is the station","wheres the station","where is the railway station"],"distratoresEn":["Where is the hotel?","Where is the beach?","Where is the bus stop?","Where is the garage?"],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"«La gare» is the train station; a subway station is «la station». A garage is «le garage».","requerTodas":[],"v":"5becc440"},{"idioma":"fr","id":"fr-b031","tipo":"frase","fr":"Je suis perdu.","aceitasFr":["Je suis perdue."],"en":"I'm lost.","aceitasEn":["im lost","i am lost"],"distratoresEn":["I'm tired.","I'm late.","I'm ready.","I'm hungry."],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"A woman writes «perdue»; it sounds the same.","requerTodas":[],"v":"c7484a34"},{"idioma":"fr","id":"fr-b032","tipo":"frase","fr":"J'ai faim.","aceitasFr":["J'ai très faim."],"en":"I'm hungry.","aceitasEn":["im hungry","i am hungry"],"distratoresEn":["I'm thirsty.","I'm cold.","I'm sleepy.","I'm in a hurry."],"nivel":"A1","tags":["primeiros passos","comida"],"notaEn":"French «has» hunger: «avoir faim», literally to have hunger. Likewise «avoir soif» (thirsty), «avoir froid» (cold), «avoir sommeil» (sleepy).","requerTodas":[],"v":"7207b812"},{"idioma":"fr","id":"fr-b033","tipo":"frase","fr":"Je ne sais pas.","aceitasFr":["Je sais pas."],"en":"I don't know.","aceitasEn":["i dont know","i do not know","no idea","dunno"],"distratoresEn":["I can't.","I don't want to.","I don't remember.","I don't like it."],"nivel":"A1","tags":["primeiros passos","gramática"],"notaEn":"«Savoir» is to know: «je sais», I know. In speech the «ne» drops: «Je sais pas».","requerTodas":[],"v":"52c3a0e2"},{"idioma":"fr","id":"fr-b034","tipo":"frase","fr":"Aidez-moi, s'il vous plaît !","aceitasFr":["Aide-moi, s'il te plaît !","Vous pouvez m'aider, s'il vous plaît ?","Aidez-moi !"],"en":"Please help me!","aceitasEn":["please help me","help me please","can you help me please","could you help me please","help me"],"distratoresEn":["Please wait for me!","Please call me!","Please forgive me!","Please listen to me!"],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"«Aider» is to help. With «tu»: «Aide-moi». In an emergency, shout «Au secours !».","requerTodas":[],"v":"ad337e09"},{"idioma":"fr","id":"fr-b035","tipo":"frase","fr":"Vous venez d'où ?","aceitasFr":["Tu viens d'où ?","D'où venez-vous ?","Vous êtes d'où ?"],"en":"Where are you from?","aceitasEn":["where are you from","where do you come from","where you from"],"distratoresEn":["Where do you live?","Where are you going?","Where have you been?","Where do you work?"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"Literally «you come from where?»: «venir» is to come. In conversation the question word goes at the end.","requerTodas":[],"v":"a1f04bb2"},{"idioma":"fr","id":"fr-b036","tipo":"frase","fr":"Je viens du Brésil.","aceitasFr":["Je suis du Brésil.","Je suis brésilien.","Je suis brésilienne."],"en":"I'm from Brazil.","aceitasEn":["im from brazil","i am from brazil","i come from brazil","im brazilian","i am brazilian"],"distratoresEn":["I live in Brazil.","I'm going to Brazil.","I'm back from Brazil.","I like Brazil."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"Masculine countries take «du»: «du Brésil», «du Canada»; feminine ones take «de»: «de France», «d'Angleterre». «Je viens» means I come.","requerTodas":[],"v":"1edad4f2"},{"idioma":"fr","id":"fr-b037","tipo":"frase","fr":"Quelle heure est-il ?","aceitasFr":["Il est quelle heure ?","Vous avez l'heure ?","Tu as l'heure ?"],"en":"What time is it?","aceitasEn":["what time is it","whats the time","what is the time","do you have the time"],"distratoresEn":["How old are you?","What day is it today?","What time does it open?","How much time is left?"],"nivel":"A1","tags":["primeiros passos","cotidiano"],"notaEn":"Literally «what hour is it?». The answer uses the same frame: «Il est trois heures», it's three o'clock.","requerTodas":[],"v":"b23dfd08"},{"idioma":"fr","id":"fr-b038","tipo":"frase","fr":"À bientôt !","aceitasFr":["À plus tard !","À la prochaine !","À plus !"],"en":"See you soon!","aceitasEn":["see you soon","see you","see you later","talk soon"],"distratoresEn":["See you tomorrow!","Welcome!","Have a good trip!","Enjoy your meal!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"«Bientôt» means soon. For tomorrow: «À demain !». Among friends, the short «À plus !» (the «s» is pronounced).","requerTodas":[],"v":"8ea86a8a"},{"idioma":"fr","id":"fr-b039","tipo":"frase","fr":"Bon appétit !","aceitasFr":["Bon appétit."],"en":"Enjoy your meal!","aceitasEn":["enjoy your meal","enjoy","bon appetit"],"distratoresEn":["Have a nice trip!","Good luck!","Cheers!","Sleep well!"],"nivel":"A1","tags":["primeiros passos","comida"],"notaEn":"Said before eating; English borrowed it as is. The final «t» is silent.","requerTodas":[],"v":"15dea5d1"},{"idioma":"fr","id":"fr-b040","tipo":"frase","fr":"Bonne journée !","aceitasFr":["Bonne journée.","Passez une bonne journée !","Bonne journée à vous !"],"en":"Have a nice day!","aceitasEn":["have a nice day","have a good day","have a great day","enjoy your day"],"distratoresEn":["Have a nice evening!","Have a nice trip!","Have a nice weekend!","Have a nice lunch!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"It's a goodbye, not a greeting: «Bonjour» when you arrive, «Bonne journée» when you leave. In the evening, «Bonne soirée».","requerTodas":[],"v":"da6a32ad"},{"idioma":"fr","id":"fr-p001","tipo":"palavra","fr":"être","en":"to be","aceitasEn":["to be","be"],"distratoresEn":["to have","to do","to stay","to give"],"nivel":"A1","tags":["verbo","gramática"],"notaEn":"Irregular: je suis, tu es, il est, nous sommes, vous êtes, ils sont. It is also the helper verb of some past tenses: «je suis allé», I went.","v":"e2b9cdca","pos":1},{"idioma":"fr","id":"fr-p002","tipo":"palavra","fr":"avoir","en":"to have","aceitasEn":["to have","have","to have got"],"distratoresEn":["to hear","to owe","to be worth","to know"],"nivel":"A1","tags":["verbo","gramática"],"notaEn":"French uses it for age and sensations: «j'ai vingt ans» (I'm twenty), «j'ai faim» (I'm hungry). Forms: j'ai, tu as, il a, nous avons, vous avez, ils ont.","v":"88bb5dcd","pos":2},{"idioma":"fr","id":"fr-p003","tipo":"palavra","fr":"aller","en":"to go","aceitasEn":["to go","go"],"distratoresEn":["to rent","to stay","to take","to look"],"nivel":"A1","tags":["verbo"],"notaEn":"Very irregular: je vais, tu vas, il va, nous allons, vous allez, ils vont. It is in «Ça va ?» and in the near future: «je vais manger», I'm going to eat.","v":"6fc8aa32","pos":5},{"idioma":"fr","id":"fr-p004","tipo":"palavra","fr":"faire","en":"to do / to make","aceitasEn":["to do","to make","do","make"],"distratoresEn":["to speak / to say","to hurt / to injure","to boil / to heat","to close / to shut"],"nivel":"A1","tags":["verbo"],"notaEn":"Both to do and to make, and also the weather verb: «il fait beau» (it's nice out), «il fait froid» (it's cold). Forms: je fais, nous faisons, vous faites, ils font.","v":"f0f41628","pos":4},{"idioma":"fr","id":"fr-p005","tipo":"palavra","fr":"dire","en":"to say","aceitasEn":["to say","say","to tell","tell"],"distratoresEn":["to drive","to last","to leave","to owe"],"nivel":"A1","tags":["verbo"],"notaEn":"To say or tell something; to speak a language, or to talk, is «parler». Forms: je dis, nous disons, vous dites, ils disent.","v":"fe7eef1f","pos":6},{"idioma":"fr","id":"fr-p006","tipo":"palavra","fr":"pouvoir","en":"can / to be able to","aceitasEn":["can","to be able to","be able to","to be able"],"distratoresEn":["must / to have to","to be worth / to cost","to put / to place","to know / to know how"],"nivel":"A1","tags":["verbo"],"notaEn":"Forms: je peux, tu peux, il peut, nous pouvons, vous pouvez, ils peuvent. To ask permission: «Je peux… ?», or formally «Puis-je… ?».","v":"1c72f625","pos":7},{"idioma":"fr","id":"fr-p007","tipo":"palavra","fr":"vouloir","en":"to want","aceitasEn":["to want","want","to wish"],"distratoresEn":["to fly","to be worth","to return","to live"],"nivel":"A1","tags":["verbo"],"notaEn":"Forms: je veux, tu veux, il veut, nous voulons, ils veulent. Polite requests use the conditional: «je voudrais», I'd like. «Vouloir dire» means to mean.","v":"b3c5e3ae","pos":8},{"idioma":"fr","id":"fr-p008","tipo":"palavra","fr":"savoir","en":"to know","aceitasEn":["to know","know","to know how to"],"distratoresEn":["to meet","to save","to serve","to follow"],"nivel":"A1","tags":["verbo"],"notaEn":"To know a fact, or how to do something: «je sais nager», I can swim. Knowing a person or a place is another verb, «connaître». Forms: je sais, nous savons, ils savent.","v":"92ac684b","pos":11},{"idioma":"fr","id":"fr-p009","tipo":"palavra","fr":"venir","en":"to come","aceitasEn":["to come","come"],"distratoresEn":["to sell","to win","to see","to dress"],"nivel":"A1","tags":["verbo"],"notaEn":"Forms: je viens, nous venons, ils viennent. «Venir de» + infinitive means to have just: «je viens de manger», I've just eaten.","v":"2f117e21","pos":16},{"idioma":"fr","id":"fr-p010","tipo":"palavra","fr":"voir","en":"to see","aceitasEn":["to see","see"],"distratoresEn":["to fly","to come","to be worth","to dress"],"nivel":"A1","tags":["verbo"],"notaEn":"Forms: je vois, nous voyons, ils voient. To look at or watch is «regarder». «On verra», we'll see.","v":"b7d5b90d","pos":13},{"idioma":"fr","id":"fr-p011","tipo":"palavra","fr":"prendre","en":"to take","aceitasEn":["to take","take","to grab"],"distratoresEn":["to learn","to lose","to ask for","to lend"],"nivel":"A1","tags":["verbo","falso-amigo"],"notaEn":"To take: «prendre le bus», to take the bus; «prendre un café», to have a coffee. With «ap-», «apprendre» means to learn. Forms: je prends, nous prenons, ils prennent.","v":"786aaff8","pos":19},{"idioma":"fr","id":"fr-p012","tipo":"palavra","fr":"parler","en":"to speak","aceitasEn":["to speak","speak","to talk","talk"],"distratoresEn":["to stop","to leave","to pay","to jump"],"nivel":"A1","tags":["verbo"],"notaEn":"Regular «-er» verb, the pattern most verbs follow: je parle, tu parles, il parle (all three sound the same), nous parlons, vous parlez, ils parlent.","v":"31194517","pos":23},{"idioma":"fr","id":"fr-p013","tipo":"palavra","fr":"manger","en":"to eat","aceitasEn":["to eat","eat"],"distratoresEn":["to send","to move","to change","to bite"],"nivel":"A1","tags":["verbo","comida"],"notaEn":"Regular «-er» verb, with an extra «e» in «nous mangeons» to keep the soft «g». A meal is «un repas».","v":"924863aa","pos":140},{"idioma":"fr","id":"fr-p014","tipo":"palavra","fr":"boire","en":"to drink","aceitasEn":["to drink","drink"],"distratoresEn":["to beat","to kiss","to play","to look for"],"nivel":"A1","tags":["verbo","comida"],"notaEn":"Irregular: je bois, nous buvons, ils boivent; past participle «bu». A drink is «une boisson».","v":"af44509e","pos":212},{"idioma":"fr","id":"fr-p015","tipo":"palavra","fr":"aimer","en":"to love / to like","aceitasEn":["to love","to like"],"distratoresEn":["to help / to support","to accept / to admit","to find / to discover","to hate / to detest"],"nivel":"A1","tags":["verbo","família"],"notaEn":"Both to love and to like: «je t'aime» (I love you), «j'aime le café» (I like coffee). Things you like take the article: «j'aime le café», not «j'aime café».","v":"d136d30f","pos":28},{"idioma":"fr","id":"fr-p016","tipo":"palavra","fr":"habiter","en":"to live (somewhere)","aceitasEn":["to live","live","to reside","reside","to live in"],"distratoresEn":["to hesitate (to doubt)","to inherit (property)","to host (a guest)","to shelter (from cold)"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"To live somewhere: «j'habite à Paris», I live in Paris. The «h» is silent, hence the apostrophe: «j'habite». «Vivre» is to live in the broader sense.","v":"ff2f69e2","pos":454},{"idioma":"fr","id":"fr-p017","tipo":"palavra","fr":"travailler","en":"to work","aceitasEn":["to work","work"],"distratoresEn":["to block","to treat","to travel","to swap"],"nivel":"A1","tags":["verbo","trabalho"],"notaEn":"Regular «-er» verb: je travaille, nous travaillons. The «-ill-» sounds like «y»: «tra-va-YAY». Work, the noun, is «le travail».","v":"ab9766f3","pos":88},{"idioma":"fr","id":"fr-p018","tipo":"palavra","fr":"attendre","en":"to wait","aceitasEn":["to wait","wait","to wait for","wait for"],"distratoresEn":["to attend","to understand","to extend","to tend"],"nivel":"A1","tags":["verbo","falso-amigo"],"notaEn":"Not to attend: it means to wait for, with no preposition: «j'attends le bus», I'm waiting for the bus. To attend is «assister à».","v":"8639d0d0","pos":50},{"idioma":"fr","id":"fr-p019","tipo":"palavra","fr":"le jour","en":"the day","aceitasEn":["the day","day"],"distratoresEn":["the game","the newspaper","the month","the year"],"nivel":"A1","tags":["cotidiano"],"notaEn":"A day on the calendar. The day as you live it, the daytime, is «la journée»: «bonne journée». «Bonjour» is literally good day.","v":"e87a7825","pos":36},{"idioma":"fr","id":"fr-p020","tipo":"palavra","fr":"la maison","en":"the house","aceitasEn":["the house","house","the home","home"],"distratoresEn":["the table","the mansion","the dough","the apple"],"nivel":"A1","tags":["casa"],"notaEn":"«À la maison» means at home: «je suis à la maison». «Chez moi» also means at my place.","v":"bde2f8bf","pos":74},{"idioma":"fr","id":"fr-p021","tipo":"palavra","fr":"l'homme","aceitasFr":["un homme"],"en":"the man","aceitasEn":["the man","man"],"distratoresEn":["the name","the shoulder","the guest","the anthem"],"nivel":"A1","tags":["família"],"notaEn":"Masculine, with the article shortened before the silent «h»: «l'homme», «un homme».","v":"510c8580","pos":25},{"idioma":"fr","id":"fr-p022","tipo":"palavra","fr":"la femme","en":"the woman","aceitasEn":["the woman","woman","the wife","wife"],"distratoresEn":["the hunger","the daughter","the company","the shape"],"nivel":"A1","tags":["família"],"notaEn":"Also wife: «ma femme», my wife. Pronounced «fam», with an «a».","v":"ff3b66a3","pos":56},{"idioma":"fr","id":"fr-p023","tipo":"palavra","fr":"l'enfant","aceitasFr":["un enfant","une enfant"],"en":"the child","aceitasEn":["the child","child","the kid","kid"],"distratoresEn":["the childhood","the patient","the godson","the nephew"],"nivel":"A1","tags":["família"],"notaEn":"For a boy or a girl: «un enfant», «une enfant». «Les enfants» also means your children: «j'ai deux enfants». Childhood is «l'enfance».","v":"e5c1633d","pos":66},{"idioma":"fr","id":"fr-p024","tipo":"palavra","fr":"l'ami","aceitasFr":["l'amie","un ami","une amie"],"en":"the friend","aceitasEn":["the friend","friend"],"distratoresEn":["the love","the lunch","the student","the neighbor"],"nivel":"A1","tags":["família","social"],"notaEn":"A female friend is «l'amie»; it sounds the same. Boyfriend and girlfriend are «le petit ami» and «la petite amie».","v":"43fe5878","pos":75},{"idioma":"fr","id":"fr-p025","tipo":"palavra","fr":"le temps","en":"time / weather","aceitasEn":["time","the time","weather","the weather"],"distratoresEn":["temple / church","seasoning / spice","ceiling / roof","topic / theme"],"nivel":"A1","tags":["cotidiano","natureza"],"notaEn":"Both time and weather: «je n'ai pas le temps» (I don't have time), «quel temps fait-il ?» (what's the weather like?). The «p» and «s» are silent.","v":"e46e6345","pos":32},{"idioma":"fr","id":"fr-p026","tipo":"palavra","fr":"l'eau","aceitasFr":["une eau"],"en":"the water","aceitasEn":["the water","water"],"distratoresEn":["the wave","the bird","the island","the grape"],"nivel":"A1","tags":["comida","natureza"],"notaEn":"Feminine: «une eau», «l'eau minérale». Three letters for one vowel sound: «oh».","v":"af06924e","pos":186},{"idioma":"fr","id":"fr-p027","tipo":"palavra","fr":"le pain","en":"the bread","aceitasEn":["the bread","bread"],"distratoresEn":["the cloth","the father","the foot","the pine"],"nivel":"A1","tags":["comida"],"notaEn":"«Ain» is a nasal vowel, with no «n» sound at the end. A baguette is «une baguette»; the baker is «le boulanger», in the «boulangerie».","v":"d1e9e55a","pos":939},{"idioma":"fr","id":"fr-p028","tipo":"palavra","fr":"la ville","en":"the city","aceitasEn":["the city","city","the town","town"],"distratoresEn":["the village","the life","the candle","the track"],"nivel":"A1","tags":["cidade","falso-amigo"],"notaEn":"A city or town of any size. A village is «le village»; a big country house is «une villa». «En ville», downtown.","v":"a2347337","pos":123},{"idioma":"fr","id":"fr-p029","tipo":"palavra","fr":"le travail","en":"work","aceitasEn":["work","the work"],"distratoresEn":["clover","pillow","journey","theater"],"nivel":"A1","tags":["trabalho"],"notaEn":"Work and job: «je vais au travail», I'm going to work. Irregular plural: «les travaux», roadworks or renovations.","v":"2c2af9e6","pos":96},{"idioma":"fr","id":"fr-p030","tipo":"palavra","fr":"la nuit","en":"the night","aceitasEn":["the night","night"],"distratoresEn":["the cloud","the snow","the note","the nape"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Bonne nuit» is what you say at bedtime; arriving in the evening, it's «Bonsoir». The evening, after work, is «le soir».","v":"46f21d60","pos":94},{"idioma":"fr","id":"fr-p031","tipo":"palavra","fr":"l'année","aceitasFr":["une année"],"en":"the year","aceitasEn":["the year","year"],"distratoresEn":["the ring","the owner","the nest","the month"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine. French has two words for year: «l'an» for counting («j'ai vingt ans», I'm twenty) and «l'année» for the year as lived («bonne année !», happy new year).","v":"a8bbbecc","pos":100},{"idioma":"fr","id":"fr-p032","tipo":"palavra","fr":"la rue","en":"the street","aceitasEn":["the street","street"],"distratoresEn":["the wheel","the clothes","the wrinkle","the ruler"],"nivel":"A1","tags":["cidade"],"notaEn":"A city street; a road out of town is «la route». «Dans la rue», in the street.","v":"0e832e13","pos":259},{"idioma":"fr","id":"fr-p033","tipo":"palavra","fr":"le livre","en":"the book","aceitasEn":["the book","book"],"distratoresEn":["the lily","the liter","the lip","the canvas"],"nivel":"A1","tags":["escola"],"notaEn":"Masculine. Feminine «la livre» is the pound (money or weight). Free is «libre».","v":"135ab3cb","pos":268},{"idioma":"fr","id":"fr-p034","tipo":"palavra","fr":"la voiture","en":"the car","aceitasEn":["the car","car"],"distratoresEn":["the bus","the truck","the train","the flight"],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"Feminine in French: «une voiture», «ma voiture». To drive is «conduire».","v":"319b1e05","pos":117},{"idioma":"fr","id":"fr-p035","tipo":"palavra","fr":"l'argent","en":"money","aceitasEn":["money","the money","silver"],"distratoresEn":["gold","argument","change","card"],"nivel":"A1","tags":["compras","economia"],"notaEn":"Masculine. It means money and also silver, the metal.","v":"a03959da","pos":134},{"idioma":"fr","id":"fr-p036","tipo":"palavra","fr":"bon","aceitasFr":["bonne"],"en":"good","aceitasEn":["good","tasty"],"distratoresEn":["pretty","cheap","brief","brave"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «bonne». For food it means tasty: «c'est bon !». The adverb, well, is «bien».","v":"e4bdf42a","pos":39},{"idioma":"fr","id":"fr-p037","tipo":"palavra","fr":"grand","aceitasFr":["grande"],"en":"big","aceitasEn":["big","large","tall"],"distratoresEn":["thick","fat","free","serious"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «grande». For people it also means tall: «il est grand», he is tall. The «d» is only heard in the feminine.","v":"897161a1","pos":57},{"idioma":"fr","id":"fr-p038","tipo":"palavra","fr":"petit","aceitasFr":["petite"],"en":"small","aceitasEn":["small","little","short"],"distratoresEn":["few","heavy","slow","poor"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «petite». Before nouns it can sound affectionate: «un petit café». Breakfast is «le petit déjeuner».","v":"49a164cb","pos":33},{"idioma":"fr","id":"fr-p039","tipo":"palavra","fr":"nouveau","aceitasFr":["nouvelle","nouvel"],"en":"new","aceitasEn":["new"],"distratoresEn":["nine","engaged","cloudy","noble"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Three forms: «nouveau»; «nouvel» before a vowel («un nouvel ami»); feminine «nouvelle». Brand-new, unused, is «neuf».","v":"9350aae7","pos":77},{"idioma":"fr","id":"fr-p040","tipo":"palavra","fr":"beau","aceitasFr":["belle","bel"],"en":"beautiful","aceitasEn":["beautiful","pretty","handsome","lovely"],"distratoresEn":["good","short","cheap","brave"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «belle»; before a vowel, «bel» («un bel homme»). Also nice weather: «il fait beau», it's a lovely day.","v":"15edc663","pos":89},{"idioma":"fr","id":"fr-p041","tipo":"palavra","fr":"vieux","aceitasFr":["vieille","vieil"],"en":"old","aceitasEn":["old","elderly","aged"],"distratoresEn":["empty","widowed","alive","brave"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «vieille»; before a vowel, «vieil» («un vieil ami», an old friend). For people, «âgé» (elderly) is more polite.","v":"eaf559c6","pos":179},{"idioma":"fr","id":"fr-p042","tipo":"palavra","fr":"content","aceitasFr":["contente"],"en":"happy","aceitasEn":["happy","glad","pleased","content"],"distratoresEn":["tired","known","restrained","hot"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «contente». With «de»: «je suis content de te voir», I'm glad to see you.","v":"09fc7831","pos":371},{"idioma":"fr","id":"fr-p043","tipo":"palavra","fr":"très","en":"very","aceitasEn":["very","really"],"distratoresEn":["three","behind","late","so much"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Goes before adjectives and adverbs: «très bien», «très grand». The number three is «trois».","v":"4dc405f6","pos":18},{"idioma":"fr","id":"fr-p044","tipo":"palavra","fr":"bien","en":"well","aceitasEn":["well","fine"],"distratoresEn":["soon","badly","far","early"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The adverb: «je vais bien», I'm well. The adjective is «bon»: «un bon livre». With «c'est» it praises: «c'est bien», that's good.","v":"fd01d39d","pos":10},{"idioma":"fr","id":"fr-p045","tipo":"palavra","fr":"aussi","en":"also","aceitasEn":["also","too","as well"],"distratoresEn":["like this","still","then","only"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Also, too: «moi aussi», me too. In comparisons it means as: «aussi grand que moi», as tall as me.","v":"194f7966","pos":22},{"idioma":"fr","id":"fr-p046","tipo":"palavra","fr":"toujours","en":"always / still","aceitasEn":["always","still"],"distratoresEn":["never / ever","sometimes / rarely","today / now","afterwards / finally"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Always, and also still: «il habite toujours ici», he still lives here. It comes from «tous les jours», every day.","v":"bb5b9bed","pos":40},{"idioma":"fr","id":"fr-p047","tipo":"palavra","fr":"maintenant","en":"now","aceitasEn":["now","right now"],"distratoresEn":["tomorrow","before","afterwards","yesterday"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Now. Right away is «tout de suite».","v":"107fbbd9","pos":63},{"idioma":"fr","id":"fr-p048","tipo":"palavra","fr":"ici","en":"here","aceitasEn":["here"],"distratoresEn":["there","like this","over there","nearby"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Here. In conversation French also uses «là» this way: «je suis là», I'm here.","v":"9e8a712d","pos":46},{"idioma":"fr","id":"fr-p049","tipo":"palavra","fr":"aujourd'hui","en":"today","aceitasEn":["today"],"distratoresEn":["yesterday","tomorrow","now","later"],"nivel":"A1","tags":["cotidiano"],"notaEn":"One word, with an apostrophe. Yesterday is «hier»; tomorrow, «demain».","v":"a48d791b","pos":105},{"idioma":"fr","id":"fr-p050","tipo":"palavra","fr":"déjà","en":"already","aceitasEn":["already","yet","ever"],"distratoresEn":["still","afterwards","soon","before"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Already: «j'ai déjà mangé», I've already eaten. In questions it means ever: «tu es déjà allé à Paris ?», have you ever been to Paris?","v":"3c6a193b","pos":84},{"idioma":"fr","id":"fr-u001","tipo":"frase","requer":"fr-p001","fr":"Elle est très contente.","en":"She's very happy.","aceitasEn":["shes very happy","she is very happy","shes really happy","she is really happy","shes very glad","she is very pleased"],"distratoresEn":["She seems very happy.","She gets very happy.","She's still very happy.","She used to be very happy."],"nivel":"A1","tags":["gramática","social"],"notaEn":"«Est» is the «il»/«elle» form of «être»; the «st» is silent, so it sounds like «et» (and). The adjective agrees: «contente», with an «e», because she is the subject.","requerTodas":["fr-p001","fr-p043","fr-p042"],"v":"5c05a823"},{"idioma":"fr","id":"fr-u002","tipo":"frase","requer":"fr-p001","fr":"Je suis à la maison.","aceitasFr":["Je suis chez moi."],"en":"I'm at home.","aceitasEn":["im at home","i am at home","im home","i am home"],"distratoresEn":["I'm staying home.","I work at home.","I eat at home.","I sleep at home."],"nivel":"A1","tags":["gramática","casa"],"notaEn":"«Être» also covers location. «À la maison», at home; «chez moi», at my place.","requerTodas":["fr-p001","fr-p020"],"v":"2f4c02b0"},{"idioma":"fr","id":"fr-u003","tipo":"frase","requer":"fr-p001","fr":"C'est un bon livre.","en":"It's a good book.","aceitasEn":["its a good book","it is a good book","this is a good book","thats a good book"],"distratoresEn":["It was a good book.","It seems like a good book.","It's been a good book.","It will be a good book."],"nivel":"A1","tags":["gramática","escola"],"notaEn":"«C'est» (it is, this is) introduces things: «c'est un bon livre», «c'est mon ami». «Bon» goes before the noun.","requerTodas":["fr-p001","fr-p036","fr-p033"],"v":"fa795f29"},{"idioma":"fr","id":"fr-u004","tipo":"frase","requer":"fr-p002","fr":"J'ai vingt ans.","en":"I'm twenty years old.","aceitasEn":["im twenty years old","i am twenty years old","im twenty","i am twenty","im 20","im 20 years old"],"distratoresEn":["I'm turning twenty.","I'm twenty months old.","Twenty years ago.","I'm twenty days old."],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"In French you have an age instead of being it: «j'ai vingt ans», literally I have twenty years. For counting years the word is «an», not «année».","requerTodas":["fr-p002","fr-p051","fr-p052"],"v":"c80f662e"},{"idioma":"fr","id":"fr-u005","tipo":"frase","requer":"fr-p002","fr":"Il y a un problème.","en":"There's a problem.","aceitasEn":["theres a problem","there is a problem"],"distratoresEn":["It's a problem.","I see a problem.","It was a problem.","I have a problem."],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«Il y a» is there is / there are. The verb is «avoir», and «il» refers to nobody. «C'est un problème» would be it's a problem.","requerTodas":["fr-p002","fr-p053"],"v":"1d4431e5"},{"idioma":"fr","id":"fr-u006","tipo":"frase","requer":"fr-p003","fr":"Je vais au travail.","en":"I'm going to work.","aceitasEn":["im going to work","i am going to work","i go to work","im off to work"],"distratoresEn":["I'm coming back from work.","I'm leaving work.","I'm getting to work.","I'm staying at work."],"nivel":"A1","tags":["gramática","trabalho"],"notaEn":"«Au» is «à» + «le» fused. Before a feminine noun there's no fusion: «à la maison».","requerTodas":["fr-p003","fr-p029"],"v":"7fccba40"},{"idioma":"fr","id":"fr-u007","tipo":"frase","requer":"fr-p004","fr":"Il fait beau aujourd'hui.","aceitasFr":["Aujourd'hui, il fait beau."],"en":"The weather is nice today.","aceitasEn":["the weather is nice today","its nice out today","its a nice day today","the weather is good today","its beautiful today","the weather is lovely today"],"distratoresEn":["The weather is bad today.","It's cold today.","It's hot today.","It's cloudy today."],"nivel":"A1","tags":["natureza","cotidiano"],"notaEn":"French «makes» the weather: «il fait beau» (it's nice), «il fait froid» (it's cold), «il fait chaud» (it's hot). The «il» is a dummy subject, like English it.","requerTodas":["fr-p004","fr-p040","fr-p049"],"v":"d7c9038a"},{"idioma":"fr","id":"fr-u008","tipo":"frase","requer":"fr-p004","fr":"Qu'est-ce que tu fais ?","aceitasFr":["Tu fais quoi ?","Que fais-tu ?"],"en":"What are you doing?","aceitasEn":["what are you doing","what do you do","what are you up to"],"distratoresEn":["What are you saying?","What are you looking at?","What are you eating?","What do you want?"],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«Qu'est-ce que» (what is it that) is the everyday way to ask what. The French present covers both what do you do and what are you doing.","requerTodas":["fr-p004"],"v":"c246341b"},{"idioma":"fr","id":"fr-u009","tipo":"frase","requer":"fr-p005","fr":"Comment on dit ça en français ?","aceitasFr":["Comment dit-on ça en français ?","Comment est-ce qu'on dit ça en français ?"],"en":"How do you say this in French?","aceitasEn":["how do you say this in french","how do you say that in french","how do we say this in french","how is this said in french","whats this in french","what is this in french"],"distratoresEn":["How do you spell this in French?","How do you read this in French?","How do you use this in French?","How do you pronounce this in French?"],"nivel":"A1","tags":["escola"],"notaEn":"«On» is the impersonal one or people, and the casual we: «on dit», people say. It takes the «il» form of the verb.","requerTodas":["fr-p005","fr-p054"],"v":"8b2ec7b8"},{"idioma":"fr","id":"fr-u010","tipo":"frase","requer":"fr-p005","fr":"Elle dit toujours la vérité.","en":"She always tells the truth.","aceitasEn":["she always tells the truth"],"distratoresEn":["She always asks for the truth.","She always knows the truth.","She always wants the truth.","She always hides the truth."],"nivel":"A1","tags":["social"],"notaEn":"«Toujours» comes after the verb: «elle dit toujours», never «elle toujours dit».","requerTodas":["fr-p005","fr-p046","fr-p055"],"v":"a2b2e01d"},{"idioma":"fr","id":"fr-u011","tipo":"frase","requer":"fr-p006","fr":"Je peux entrer ?","aceitasFr":["Puis-je entrer ?","Est-ce que je peux entrer ?"],"en":"Can I come in?","aceitasEn":["can i come in","may i come in","could i come in","can i go in"],"distratoresEn":["Should I come in?","Can I go out?","Can I sit down?","Can I wait?"],"nivel":"A1","tags":["social"],"notaEn":"A rising tone is enough to ask permission: «Je peux… ?». More formal: «Puis-je entrer ?».","requerTodas":["fr-p006","fr-p056"],"v":"c27feba8"},{"idioma":"fr","id":"fr-u012","tipo":"frase","requer":"fr-p006","fr":"On ne peut pas parler ici.","en":"You can't talk here.","aceitasEn":["you cant talk here","you cannot talk here","we cant talk here","you cant speak here","no talking here"],"distratoresEn":["You shouldn't talk here.","People don't usually talk here.","You can't smoke here.","You can't eat here."],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«On» is the impersonal subject: «on ne peut pas», one can't. The negation wraps the conjugated verb, leaving the infinitive outside: «ne peut pas parler».","requerTodas":["fr-p006","fr-p012","fr-p048"],"v":"3d7cdb5b"},{"idioma":"fr","id":"fr-u013","tipo":"frase","requer":"fr-p007","fr":"Tu veux un café ?","aceitasFr":["Vous voulez un café ?","Tu veux du café ?"],"en":"Do you want a coffee?","aceitasEn":["do you want a coffee","do you want some coffee","want a coffee","would you like a coffee","you want a coffee"],"distratoresEn":["Do you have a coffee?","Are you having a coffee?","Are you making a coffee?","Are you paying for a coffee?"],"nivel":"A1","tags":["comida","social"],"notaEn":"«Tu» for people you're close to; «vous» for everyone else: «Vous voulez un café ?». Even more polite: «Tu voudrais un café ?».","requerTodas":["fr-p007","fr-p057"],"v":"42de145b"},{"idioma":"fr","id":"fr-u014","tipo":"frase","requer":"fr-p007","fr":"Qu'est-ce que ça veut dire ?","aceitasFr":["Ça veut dire quoi ?","Qu'est-ce que cela veut dire ?"],"en":"What does that mean?","aceitasEn":["what does that mean","what does this mean","whats that mean","what does it mean"],"distratoresEn":["What does that have to do with it?","What do you mean?","What does he want to do?","Where is that going?"],"nivel":"A1","tags":["escola"],"notaEn":"«Vouloir dire», literally to want to say, is the everyday to mean. «Ça» is that. Compare «Qu'est-ce que tu veux dire ?», what do you mean?","requerTodas":["fr-p007","fr-p005"],"v":"d63c0c98"},{"idioma":"fr","id":"fr-u015","tipo":"frase","requer":"fr-p008","fr":"Je sais nager.","en":"I can swim.","aceitasEn":["i can swim","i know how to swim"],"distratoresEn":["I'm allowed to swim.","I want to swim.","I'm going to swim.","I like swimming."],"nivel":"A1","tags":["cotidiano"],"notaEn":"A learned skill takes «savoir», to know: «je sais nager», I can swim. «Je peux nager» means I'm able or allowed to.","requerTodas":["fr-p008","fr-p058"],"v":"8d32e2fc"},{"idioma":"fr","id":"fr-u016","tipo":"frase","requer":"fr-p016","fr":"Je ne sais pas où il habite.","en":"I don't know where he lives.","aceitasEn":["i dont know where he lives","i do not know where he lives"],"distratoresEn":["I don't know where he works.","I don't know where he is.","I don't know where he eats.","I don't know where he studies."],"nivel":"A1","tags":["casa"],"notaEn":"«Où», with the accent, is where. In an indirect question the word order stays normal: «où il habite».","requerTodas":["fr-p008","fr-p016"],"v":"5cf93057"},{"idioma":"fr","id":"fr-u017","tipo":"frase","requer":"fr-p009","fr":"Viens ici !","aceitasFr":["Venez ici !","Viens là !"],"en":"Come here!","aceitasEn":["come here","come over here"],"distratoresEn":["Stay here!","Sit here!","Wait here!","Stop here!"],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«Tu» imperative: «viens», the present form without «tu». With «vous»: «Venez ici !».","requerTodas":["fr-p009","fr-p048"],"v":"550a83c3"},{"idioma":"fr","id":"fr-u018","tipo":"frase","requer":"fr-p010","fr":"On se voit demain !","aceitasFr":["On se voit demain."],"en":"See you tomorrow!","aceitasEn":["see you tomorrow","well see each other tomorrow","see ya tomorrow"],"distratoresEn":["Talk to you tomorrow!","I'll call you tomorrow!","See you today!","See you later!"],"nivel":"A1","tags":["social"],"notaEn":"«On se voit», literally one sees each other: «on» is the casual we. The present stands in for the future, as in English «see you».","requerTodas":["fr-p010","fr-p059"],"v":"72d9bf0e"},{"idioma":"fr","id":"fr-u019","tipo":"frase","requer":"fr-p010","fr":"Je ne vois rien.","aceitasFr":["Je vois rien."],"en":"I can't see anything.","aceitasEn":["i cant see anything","i cannot see anything","i dont see anything","i see nothing","i can see nothing"],"distratoresEn":["I can't hear anything.","I don't know anything.","I don't want anything.","I'm not eating anything."],"nivel":"A1","tags":["gramática"],"notaEn":"With «rien» (nothing), «pas» drops out: «ne… rien», not… anything. In speech, «Je vois rien».","requerTodas":["fr-p010"],"v":"a4be660f"},{"idioma":"fr","id":"fr-u020","tipo":"frase","requer":"fr-p011","fr":"Je prends le bus.","en":"I take the bus.","aceitasEn":["i take the bus","im taking the bus","i am taking the bus","i catch the bus","i go by bus"],"distratoresEn":["I miss the bus.","I wait for the bus.","I pay for the bus.","I stop the bus."],"nivel":"A1","tags":["cidade","viagem","falso-amigo"],"notaEn":"Transport takes «prendre», to take: «prendre le bus», «prendre le train».","requerTodas":["fr-p011","fr-p060"],"v":"9e452f90"},{"idioma":"fr","id":"fr-u021","tipo":"frase","requer":"fr-p011","fr":"Je prends ça.","aceitasFr":["Je vais prendre ça.","Je le prends."],"en":"I'll take this.","aceitasEn":["ill take this","i will take this","ill take it","ill take this one"],"distratoresEn":["I'll pay for this.","I'll try this on.","I'll exchange this.","I'll return this."],"nivel":"A1","tags":["compras"],"notaEn":"In a shop, «je prends» means I'll take it. «Ça» is this or that.","requerTodas":["fr-p011"],"v":"33333335"},{"idioma":"fr","id":"fr-u022","tipo":"frase","requer":"fr-p012","fr":"Vous parlez trop vite.","aceitasFr":["Tu parles trop vite."],"en":"You're speaking too fast.","aceitasEn":["youre speaking too fast","you are speaking too fast","you speak too fast","youre talking too fast","you talk too fast","you speak too quickly"],"distratoresEn":["You're walking too fast.","You're eating too fast.","You're reading too fast.","You're driving too fast."],"nivel":"A1","tags":["escola"],"notaEn":"«Trop» means too and goes before the word: «trop vite», too fast.","requerTodas":["fr-p012","fr-p061","fr-p062"],"v":"9bada5b8"},{"idioma":"fr","id":"fr-u023","tipo":"frase","requer":"fr-p012","fr":"Je parle à ma mère.","en":"I'm talking to my mother.","aceitasEn":["im talking to my mother","i am talking to my mother","im talking to my mom","im talking with my mother","im speaking to my mother","i talk to my mother"],"distratoresEn":["I'm calling my mother.","I'm writing to my mother.","I'm waiting for my mother.","I'm listening to my mother."],"nivel":"A1","tags":["família"],"notaEn":"You talk «à» someone: «parler à quelqu'un». «Parler avec» also exists, more for chatting with.","requerTodas":["fr-p012","fr-p063"],"v":"6a9a1906"},{"idioma":"fr","id":"fr-u024","tipo":"frase","requer":"fr-p013","fr":"On mange à midi.","aceitasFr":["Nous mangeons à midi."],"en":"We eat at noon.","aceitasEn":["we eat at noon","we have lunch at noon","we eat at midday","we eat lunch at noon"],"distratoresEn":["We leave at noon.","We arrive at noon.","We sleep at noon.","We drink at noon."],"nivel":"A1","tags":["comida","cotidiano"],"notaEn":"«On» is the casual we, but it takes the «il» form: «on mange», we eat.","requerTodas":["fr-p013","fr-p064"],"v":"8e02ad87"},{"idioma":"fr","id":"fr-u025","tipo":"frase","requer":"fr-p013","fr":"Je ne mange pas de viande.","aceitasFr":["Je mange pas de viande."],"en":"I don't eat meat.","aceitasEn":["i dont eat meat","i do not eat meat"],"distratoresEn":["I don't buy meat.","I don't sell meat.","I don't cut meat.","I don't like meat."],"nivel":"A1","tags":["comida","gramática"],"notaEn":"After a negative, «du», «de la» and «des» become «de»: «je mange de la viande», but «je ne mange pas de viande».","requerTodas":["fr-p013","fr-p065"],"v":"345e9202"},{"idioma":"fr","id":"fr-u026","tipo":"frase","requer":"fr-p014","fr":"Je bois de l'eau.","en":"I drink water.","aceitasEn":["i drink water","im drinking water","i am drinking water","i drink some water"],"distratoresEn":["I buy water.","I ask for water.","I bring water.","I want water."],"nivel":"A1","tags":["comida","gramática"],"notaEn":"Uncountable things take the partitive: «de l'eau», «du pain», «de la viande», where English says some or nothing.","requerTodas":["fr-p014","fr-p026"],"v":"85816d3e"},{"idioma":"fr","id":"fr-u027","tipo":"frase","requer":"fr-p014","fr":"On boit un verre ?","aceitasFr":["On va boire un verre ?","Tu veux boire un verre ?"],"en":"Shall we grab a drink?","aceitasEn":["shall we grab a drink","shall we have a drink","lets have a drink","lets grab a drink","how about a drink","want to grab a drink"],"distratoresEn":["Shall we grab a bite?","Shall we go shopping?","Shall we do something?","Shall we watch a movie?"],"nivel":"A2","tags":["comida","social","expressão"],"notaEn":"Literally «do we drink a glass?»: «boire un verre» means to go for a drink, alcoholic or not.","requerTodas":["fr-p014","fr-p066"],"v":"69c4ef67"},{"idioma":"fr","id":"fr-u028","tipo":"frase","requer":"fr-p015","fr":"J'aime beaucoup le chocolat.","en":"I really like chocolate.","aceitasEn":["i really like chocolate","i like chocolate a lot","i love chocolate","i like chocolate very much"],"distratoresEn":["I don't like chocolate.","I don't really like chocolate.","I really like coffee.","I really like cake."],"nivel":"A1","tags":["comida"],"notaEn":"What you like takes the article: «j'aime le chocolat». «Beaucoup» goes right after the verb.","requerTodas":["fr-p015","fr-p067","fr-p068"],"v":"dddd4695"},{"idioma":"fr","id":"fr-u029","tipo":"frase","requer":"fr-p015","fr":"Je t'aime.","en":"I love you.","aceitasEn":["i love you"],"distratoresEn":["I'll help you.","I'll wait for you.","I see you.","I hear you."],"nivel":"A1","tags":["família","social"],"notaEn":"With people, plain «aimer» is love. To say you like someone as a friend, add «bien»: «je t'aime bien».","requerTodas":["fr-p015"],"v":"1bf47f32"},{"idioma":"fr","id":"fr-u030","tipo":"frase","requer":"fr-p016","fr":"J'habite à Rio.","en":"I live in Rio.","aceitasEn":["i live in rio","i live in rio de janeiro"],"distratoresEn":["I work in Rio.","I was born in Rio.","I study in Rio.","I'm staying in Rio."],"nivel":"A1","tags":["casa","cidade"],"notaEn":"Cities take «à»: «à Rio», «à Paris». Feminine countries take «en»: «j'habite en France».","requerTodas":["fr-p016"],"v":"741b534c"},{"idioma":"fr","id":"fr-u031","tipo":"frase","requer":"fr-p017","fr":"Elle travaille dans un hôpital.","en":"She works at a hospital.","aceitasEn":["she works at a hospital","she works in a hospital","she works at the hospital"],"distratoresEn":["She lives in a hospital.","She studies at a hospital.","She sleeps in a hospital.","She eats at a hospital."],"nivel":"A1","tags":["trabalho","saúde"],"notaEn":"«Dans» means in, inside. The «h» of «hôpital» is silent: «l'hôpital».","requerTodas":["fr-p017","fr-p069"],"v":"57a6875a"},{"idioma":"fr","id":"fr-u032","tipo":"frase","requer":"fr-p018","fr":"Attends-moi !","aceitasFr":["Attendez-moi !"],"en":"Wait for me!","aceitasEn":["wait for me","wait up"],"distratoresEn":["Help me!","Understand me!","Listen to me!","Call me!"],"nivel":"A1","tags":["cotidiano","falso-amigo"],"notaEn":"«Attendre» means to wait for, with no preposition. In positive commands the pronoun follows, with a hyphen: «attends-moi».","requerTodas":["fr-p018"],"v":"789d1724"},{"idioma":"fr","id":"fr-u033","tipo":"frase","requer":"fr-p019","fr":"Je travaille tous les jours.","en":"I work every day.","aceitasEn":["i work every day","i work everyday","i work daily"],"distratoresEn":["I work every month.","I work every year.","I work every night.","I work every Sunday."],"nivel":"A1","tags":["trabalho","cotidiano"],"notaEn":"«Tous les jours», every day (literally all the days): «tout» agrees, becoming «tous» in the masculine plural.","requerTodas":["fr-p017","fr-p070","fr-p019"],"v":"3fd9214d"},{"idioma":"fr","id":"fr-u034","tipo":"frase","requer":"fr-p020","fr":"Je rentre à la maison.","aceitasFr":["Je rentre chez moi."],"en":"I'm going home.","aceitasEn":["im going home","i am going home","im heading home","im going back home","i go home"],"distratoresEn":["I'm leaving home.","I'm staying home.","I'm cleaning the house.","I'm selling my house."],"nivel":"A1","tags":["casa"],"notaEn":"«Rentrer» is to go back home, or back inside. Being at home is «je suis à la maison».","requerTodas":["fr-p071","fr-p020"],"v":"2b418513"},{"idioma":"fr","id":"fr-u035","tipo":"frase","requer":"fr-p021","fr":"Cet homme est mon voisin.","en":"That man is my neighbor.","aceitasEn":["that man is my neighbor","this man is my neighbor","that man is my neighbour"],"distratoresEn":["That boy is my neighbor.","That student is my neighbor.","That doctor is my neighbor.","That waiter is my neighbor."],"nivel":"A1","tags":["família","casa"],"notaEn":"Before a vowel or silent «h», «ce» (this, that) becomes «cet»: «cet homme», «cet ami». Feminine: «cette femme».","requerTodas":["fr-p021","fr-p001","fr-p072"],"v":"cc4e46a1"},{"idioma":"fr","id":"fr-u036","tipo":"frase","requer":"fr-p022","fr":"Sa femme est française.","en":"His wife is French.","aceitasEn":["his wife is french","her wife is french"],"distratoresEn":["His daughter is French.","His sister is French.","His mother is French.","His friend is French."],"nivel":"A1","tags":["família"],"notaEn":"«Sa» agrees with the thing owned, not the owner: «sa femme» is his wife or her wife. Nationality adjectives are lowercase.","requerTodas":["fr-p022","fr-p001","fr-p054"],"v":"5dfd357a"},{"idioma":"fr","id":"fr-u037","tipo":"frase","requer":"fr-p023","fr":"Les enfants jouent dans la rue.","en":"The children are playing in the street.","aceitasEn":["the children are playing in the street","the kids are playing in the street","the children play in the street","the kids play in the street"],"distratoresEn":["The children are sleeping in the street.","The children are eating in the street.","The children live in the street.","The children are waiting in the street."],"nivel":"A1","tags":["família","cidade"],"notaEn":"«Jouer» is to play, games or instruments: «jouer au foot», «jouer du piano». The «-ent» ending of «jouent» is silent.","requerTodas":["fr-p023","fr-p073","fr-p032"],"v":"63168176"},{"idioma":"fr","id":"fr-u038","tipo":"frase","requer":"fr-p024","fr":"C'est mon meilleur ami.","en":"He's my best friend.","aceitasEn":["hes my best friend","he is my best friend"],"distratoresEn":["He's my best student.","He's my best neighbor.","He's my new friend.","He's my old friend."],"nivel":"A1","tags":["social"],"notaEn":"«Meilleur» is best or better; feminine «ma meilleure amie» sounds the same.","requerTodas":["fr-p001","fr-p074","fr-p024"],"v":"80ef1335"},{"idioma":"fr","id":"fr-u039","tipo":"frase","requer":"fr-p025","fr":"Je n'ai pas le temps.","aceitasFr":["J'ai pas le temps."],"en":"I don't have time.","aceitasEn":["i dont have time","i do not have time","i have no time","i dont have the time"],"distratoresEn":["I don't have money.","I'm not hungry.","I don't have a car.","I don't have a house."],"nivel":"A1","tags":["cotidiano"],"notaEn":"French uses the article here: «avoir le temps», to have (the) time.","requerTodas":["fr-p002","fr-p025"],"v":"4d2db924"},{"idioma":"fr","id":"fr-u040","tipo":"frase","requer":"fr-p025","fr":"Quel temps fait-il ?","aceitasFr":["Il fait quel temps ?"],"en":"What's the weather like?","aceitasEn":["whats the weather like","what is the weather like","hows the weather","how is the weather"],"distratoresEn":["How much time is left?","What time is it?","How long does it take?","What day is it today?"],"nivel":"A1","tags":["natureza"],"notaEn":"Literally «what weather does it make?». Asking the time is «Quelle heure est-il ?».","requerTodas":["fr-p025","fr-p004"],"v":"2d772968"},{"idioma":"fr","id":"fr-u041","tipo":"frase","requer":"fr-p026","fr":"Un verre d'eau, s'il vous plaît.","en":"A glass of water, please.","aceitasEn":["a glass of water please","glass of water please","a glass of water","could i have a glass of water"],"distratoresEn":["A glass of milk, please.","A glass of wine, please.","A bottle of water, please.","A bowl of soup, please."],"nivel":"A1","tags":["comida"],"notaEn":"«Le verre» is a glass, for drinking or the material. A glass of water: «un verre d'eau», with «de» and no article.","requerTodas":["fr-p066","fr-p026"],"v":"cb9ce708"},{"idioma":"fr","id":"fr-u042","tipo":"frase","requer":"fr-p027","fr":"J'achète du pain.","en":"I'm buying bread.","aceitasEn":["im buying bread","i am buying bread","i buy bread","i buy some bread","im buying some bread"],"distratoresEn":["I'm buying milk.","I'm buying cheese.","I'm buying rice.","I'm buying coffee."],"nivel":"A1","tags":["comida","compras"],"notaEn":"Bread with no quantity takes the partitive: «du pain», some bread. «Acheter» gets a grave accent before a silent ending: «j'achète», but «nous achetons».","requerTodas":["fr-p075","fr-p027"],"v":"f45530d8"},{"idioma":"fr","id":"fr-u043","tipo":"frase","requer":"fr-p028","fr":"Paris est une grande ville.","en":"Paris is a big city.","aceitasEn":["paris is a big city","paris is a large city","paris is a great city"],"distratoresEn":["Paris is a big village.","Paris is a big island.","Paris is a big square.","Paris is a big street."],"nivel":"A1","tags":["cidade"],"notaEn":"«Grand» usually goes before the noun: «une grande ville». The feminine adds «e», and then the «d» is pronounced.","requerTodas":["fr-p001","fr-p037","fr-p028"],"v":"eea5e1a7"},{"idioma":"fr","id":"fr-u044","tipo":"frase","requer":"fr-p029","fr":"J'aime mon travail.","en":"I like my job.","aceitasEn":["i like my job","i love my job","i like my work","i love my work"],"distratoresEn":["I like my neighborhood.","I like my car.","I like my boss.","I like my room."],"nivel":"A1","tags":["trabalho"],"notaEn":"«Mon travail»: masculine possessive, because «travail» is masculine.","requerTodas":["fr-p015","fr-p029"],"v":"1f7d37ef"},{"idioma":"fr","id":"fr-u045","tipo":"frase","requer":"fr-p030","fr":"Bonne nuit, à demain !","en":"Good night, see you tomorrow!","aceitasEn":["good night see you tomorrow","goodnight see you tomorrow","night see you tomorrow"],"distratoresEn":["Good morning, see you tomorrow!","Good afternoon, see you tomorrow!","Good night, see you later!","Have a good trip, see you tomorrow!"],"nivel":"A1","tags":["social"],"notaEn":"«Bonne nuit» is for bedtime; arriving in the evening, say «Bonsoir».","requerTodas":["fr-p036","fr-p030","fr-p059"],"v":"8ccdc042"},{"idioma":"fr","id":"fr-u046","tipo":"frase","requer":"fr-p030","fr":"Il travaille la nuit.","en":"He works at night.","aceitasEn":["he works at night","he works nights","he works during the night"],"distratoresEn":["He works during the day.","He works in the afternoon.","He works early.","He works alone."],"nivel":"A1","tags":["trabalho","cotidiano"],"notaEn":"With the article and no preposition, «la nuit» means at night, as a habit.","requerTodas":["fr-p017","fr-p030"],"v":"368432ce"},{"idioma":"fr","id":"fr-u047","tipo":"frase","requer":"fr-p031","fr":"Bonne année !","en":"Happy New Year!","aceitasEn":["happy new year"],"distratoresEn":["Happy birthday!","Merry Christmas!","Good luck!","Enjoy your vacation!"],"nivel":"A1","tags":["social","cultura"],"notaEn":"Said from January 1st, and through the whole month. It's «année», not «an», because you wish someone the year as lived.","requerTodas":["fr-p036","fr-p031"],"v":"749578ec"},{"idioma":"fr","id":"fr-u048","tipo":"frase","requer":"fr-p031","fr":"Cette année, je vais en France.","en":"This year I'm going to France.","aceitasEn":["this year im going to france","this year i am going to france","im going to france this year","this year i go to france"],"distratoresEn":["This month I'm going to France.","This summer I'm going to France.","This winter I'm going to France.","This Sunday I'm going to France."],"nivel":"A1","tags":["viagem"],"notaEn":"«Cette» is the feminine of «ce» (this), because «année» is feminine. Feminine countries take «en»: «en France».","requerTodas":["fr-p031","fr-p003"],"v":"1006048d"},{"idioma":"fr","id":"fr-u049","tipo":"frase","requer":"fr-p032","fr":"J'habite dans cette rue.","en":"I live on this street.","aceitasEn":["i live on this street","i live in this street"],"distratoresEn":["I live in this city.","I live in this house.","I live on this square.","I live in this village."],"nivel":"A1","tags":["cidade","casa"],"notaEn":"On a street is «dans la rue». In an address, no preposition or article: «j'habite rue Victor-Hugo».","requerTodas":["fr-p016","fr-p032"],"v":"a02797f6"},{"idioma":"fr","id":"fr-u050","tipo":"frase","requer":"fr-p033","fr":"Je lis un livre.","en":"I'm reading a book.","aceitasEn":["im reading a book","i am reading a book","i read a book"],"distratoresEn":["I'm reading a newspaper.","I'm reading a poem.","I'm reading an email.","I'm reading a note."],"nivel":"A1","tags":["escola"],"notaEn":"«Lire» is to read: je lis, tu lis, il lit, nous lisons. The present also means I'm reading.","requerTodas":["fr-p076","fr-p033"],"v":"8203ae4c"},{"idioma":"fr","id":"fr-u051","tipo":"frase","requer":"fr-p034","fr":"Ma voiture est en panne.","en":"My car has broken down.","aceitasEn":["my car has broken down","my car broke down","my car is broken down","my car isnt working"],"distratoresEn":["My car has been washed.","My car has been sold.","My car is parked.","My car is dirty."],"nivel":"A2","tags":["cidade","viagem"],"notaEn":"«Ma voiture»: feminine possessive, because «voiture» is feminine. «En panne» works for anything that stops working.","requerTodas":["fr-p034","fr-p001","fr-p077"],"v":"941bf898"},{"idioma":"fr","id":"fr-u052","tipo":"frase","requer":"fr-p035","fr":"Je n'ai pas d'argent.","aceitasFr":["J'ai pas d'argent."],"en":"I don't have any money.","aceitasEn":["i dont have any money","i dont have money","i have no money","i do not have any money"],"distratoresEn":["I don't have any time.","I don't have any change.","I don't have a card.","I don't have any work."],"nivel":"A1","tags":["compras","economia"],"notaEn":"After a negative, just «de»: «pas d'argent». In the positive, the partitive: «j'ai de l'argent», I have (some) money.","requerTodas":["fr-p002","fr-p035"],"v":"ee886767"},{"idioma":"fr","id":"fr-u053","tipo":"frase","requer":"fr-p036","fr":"C'est très bon !","en":"It's really good!","aceitasEn":["its really good","its very good","it is very good","its delicious","its so good","its really tasty"],"distratoresEn":["It's really salty!","It's really hot!","It's really sweet!","It's really expensive!"],"nivel":"A1","tags":["comida"],"notaEn":"For food, «bon» means tasty. Hot, as in temperature, is «chaud».","requerTodas":["fr-p001","fr-p043","fr-p036"],"v":"20734602"},{"idioma":"fr","id":"fr-u054","tipo":"frase","requer":"fr-p037","fr":"Mon frère est très grand.","en":"My brother is very tall.","aceitasEn":["my brother is very tall","my brother is really tall","my brother is very big"],"distratoresEn":["My brother is very short.","My brother is very young.","My brother is very thin.","My brother is very strong."],"nivel":"A1","tags":["família"],"notaEn":"For people, «grand» is tall and «petit» is short.","requerTodas":["fr-p078","fr-p001","fr-p043","fr-p037"],"v":"b766b7e6"},{"idioma":"fr","id":"fr-u055","tipo":"frase","requer":"fr-p038","fr":"Mon appartement est petit.","en":"My apartment is small.","aceitasEn":["my apartment is small","my flat is small","my apartment is little"],"distratoresEn":["My apartment is new.","My apartment is expensive.","My apartment is old.","My apartment is pretty."],"nivel":"A1","tags":["casa"],"notaEn":"«Petit» can follow «être», as here, or go before the noun: «un petit appartement».","requerTodas":["fr-p079","fr-p001","fr-p038"],"v":"2a590e34"},{"idioma":"fr","id":"fr-u056","tipo":"frase","requer":"fr-p039","fr":"J'ai une nouvelle voiture.","en":"I have a new car.","aceitasEn":["i have a new car","ive got a new car","i got a new car"],"distratoresEn":["I have an old car.","I have an expensive car.","I have a nice car.","I have a small car."],"nivel":"A1","tags":["cidade"],"notaEn":"«Nouvelle» agrees with «voiture» and goes before it. «Une voiture neuve» is a brand-new car, never used.","requerTodas":["fr-p002","fr-p039","fr-p034"],"v":"0711218d"},{"idioma":"fr","id":"fr-u057","tipo":"frase","requer":"fr-p040","fr":"Quelle belle maison !","en":"What a beautiful house!","aceitasEn":["what a beautiful house","what a lovely house","what a pretty house"],"distratoresEn":["What a big house!","What an old house!","What a small house!","What an expensive house!"],"nivel":"A1","tags":["casa"],"notaEn":"«Belle» is the feminine of «beau». Exclamatory «quel» (what a) agrees too: «quelle maison», «quel livre».","requerTodas":["fr-p040","fr-p020"],"v":"9657bf10"},{"idioma":"fr","id":"fr-u058","tipo":"frase","requer":"fr-p041","fr":"C'est un vieil ami.","en":"He's an old friend.","aceitasEn":["hes an old friend","he is an old friend","its an old friend"],"distratoresEn":["He's a new friend.","He's a good friend.","He's a great friend.","He's a false friend."],"nivel":"A2","tags":["social"],"notaEn":"Before a vowel, «vieux» becomes «vieil»: «un vieil ami», «un vieil homme». It sounds like «vieille».","requerTodas":["fr-p001","fr-p041","fr-p024"],"v":"cd54833a"},{"idioma":"fr","id":"fr-u059","tipo":"frase","requer":"fr-p042","fr":"Je suis content de te voir.","aceitasFr":["Je suis contente de te voir."],"en":"I'm glad to see you.","aceitasEn":["im glad to see you","im happy to see you","i am glad to see you","i am happy to see you","good to see you","nice to see you","its good to see you"],"distratoresEn":["I'm sad to see you.","I'm glad to hear from you.","I'm glad to help you.","I'm glad to meet you."],"nivel":"A1","tags":["social"],"notaEn":"«Content de» + infinitive: glad to. A woman says «contente».","requerTodas":["fr-p001","fr-p042","fr-p010"],"v":"c7f09ccf"},{"idioma":"fr","id":"fr-u060","tipo":"frase","requer":"fr-p043","fr":"Il fait très froid.","en":"It's very cold.","aceitasEn":["its very cold","it is very cold","its really cold","its freezing"],"distratoresEn":["It's very hot.","It's a bit cold.","It's kind of cold.","It's very humid."],"nivel":"A1","tags":["natureza"],"notaEn":"«Froid» is an adjective here, so it takes «très»: «il fait très froid».","requerTodas":["fr-p004","fr-p043","fr-p080"],"v":"9a172c42"},{"idioma":"fr","id":"fr-u061","tipo":"frase","requer":"fr-p044","fr":"Tu parles très bien français !","aceitasFr":["Vous parlez très bien français !","Tu parles très bien le français !"],"en":"You speak French very well!","aceitasEn":["you speak french very well","you speak very good french","your french is very good","you speak french really well"],"distratoresEn":["You speak French very badly!","You speak French very fast!","You speak French very loudly!","You speak very little French!"],"nivel":"A1","tags":["escola"],"notaEn":"«Bien» modifies the verb. «Bon» is the adjective: «un bon livre».","requerTodas":["fr-p012","fr-p043","fr-p044","fr-p054"],"v":"6038d70b"},{"idioma":"fr","id":"fr-u062","tipo":"frase","requer":"fr-p045","fr":"Elle parle aussi anglais.","aceitasFr":["Elle parle anglais aussi.","Elle parle aussi l'anglais."],"en":"She also speaks English.","aceitasEn":["she also speaks english","she speaks english too","she speaks english as well"],"distratoresEn":["She only speaks English.","She still speaks English.","She already speaks English.","She doesn't speak English."],"nivel":"A1","tags":["escola"],"notaEn":"«Aussi» comes after the verb: «elle parle aussi anglais». With a pronoun alone: «moi aussi», me too.","requerTodas":["fr-p045","fr-p012","fr-p081"],"v":"964165b4"},{"idioma":"fr","id":"fr-u063","tipo":"frase","requer":"fr-p046","fr":"Il habite toujours ici.","en":"He still lives here.","aceitasEn":["he still lives here"],"distratoresEn":["He already lives here.","He doesn't live here anymore.","He almost lives here.","He only lives here."],"nivel":"A2","tags":["casa"],"notaEn":"Here «toujours» means still. The opposite is «ne… plus»: «il n'habite plus ici», he doesn't live here anymore.","requerTodas":["fr-p016","fr-p046","fr-p048"],"v":"db312dc7"},{"idioma":"fr","id":"fr-u064","tipo":"frase","requer":"fr-p047","fr":"Je dois partir maintenant.","en":"I have to leave now.","aceitasEn":["i have to leave now","i have to go now","i need to go now","i need to leave now","i must go now","i must leave now","i gotta go now"],"distratoresEn":["I have to leave tomorrow.","I have to leave soon.","I have to leave early.","I have to leave later."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Devoir» is to have to, must. «Partir» is to leave, go away.","requerTodas":["fr-p082","fr-p083","fr-p047"],"v":"c7b5424a"},{"idioma":"fr","id":"fr-u065","tipo":"frase","requer":"fr-p048","fr":"Ici, on parle français.","en":"French is spoken here.","aceitasEn":["french is spoken here","we speak french here","here we speak french","here people speak french"],"distratoresEn":["French is spoken there.","French is spoken over there.","French is spoken like this.","French is spoken nearby."],"nivel":"A1","tags":["viagem"],"notaEn":"«On» works as the impersonal subject: «on parle», one speaks, is spoken. After «parler», the language needs no article.","requerTodas":["fr-p048","fr-p012","fr-p054"],"v":"824e6541"},{"idioma":"fr","id":"fr-u066","tipo":"frase","requer":"fr-p049","fr":"Aujourd'hui, c'est lundi.","aceitasFr":["Aujourd'hui, on est lundi.","On est lundi aujourd'hui."],"en":"Today is Monday.","aceitasEn":["today is monday","its monday today","it is monday today","today its monday"],"distratoresEn":["Yesterday was Monday.","Tomorrow is Monday.","Today is Tuesday.","Today is Sunday."],"nivel":"A1","tags":["cotidiano"],"notaEn":"Days of the week are lowercase in French and take no article here: «c'est lundi». People also say «on est lundi».","requerTodas":["fr-p049","fr-p001","fr-p084"],"v":"76e78760"},{"idioma":"fr","id":"fr-u067","tipo":"frase","requer":"fr-p050","fr":"J'ai déjà mangé.","en":"I've already eaten.","aceitasEn":["ive already eaten","i have already eaten","i already ate","ive eaten already"],"distratoresEn":["I haven't eaten yet.","I'm about to eat.","I've never eaten.","I ate very little."],"nivel":"A1","tags":["comida","gramática"],"notaEn":"«Déjà» sits between the helper verb and the participle: «j'ai déjà mangé».","requerTodas":["fr-p002","fr-p050","fr-p013"],"v":"3cf8da8a"},{"idioma":"fr","id":"fr-v001","tipo":"frase","fr":"Je suis en retard.","en":"I'm late.","aceitasEn":["im late","i am late","im running late","i am running late"],"distratoresEn":["I was late.","I've been late.","I'll be late.","I would be late."],"formasFr":{"J'étais en retard":"imperfect","J'ai été en retard":"passé composé","Je serai en retard":"future","Je serais en retard":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular"],"notaEn":"«En retard» doesn't change for gender. Present of «être»: je suis, tu es, il est, nous sommes, vous êtes, ils sont.","requerTodas":["fr-p001","fr-p085"],"v":"f62716a4"},{"idioma":"fr","id":"fr-v002","tipo":"frase","fr":"Ils ont faim.","aceitasFr":["Elles ont faim."],"en":"They're hungry.","aceitasEn":["theyre hungry","they are hungry"],"distratoresEn":["They were hungry.","They got hungry.","They'll be hungry.","They'd be hungry."],"formasFr":{"Ils avaient faim":"imperfect","Ils ont eu faim":"passé composé","Ils auront faim":"future","Ils auraient faim":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular"],"notaEn":"«Ils ont» (they have) links with a «z» sound: «eel-ZON». «Ils sont» (they are) has an «s» sound: watch the difference.","requerTodas":["fr-p002","fr-p086"],"v":"d93491f3"},{"idioma":"fr","id":"fr-v003","tipo":"frase","fr":"Je vais à la plage.","en":"I'm going to the beach.","aceitasEn":["im going to the beach","i am going to the beach","i go to the beach"],"distratoresEn":["I was going to the beach.","I went to the beach.","I'll go to the beach.","I would go to the beach."],"formasFr":{"J'allais à la plage":"imperfect","Je suis allé à la plage":"passé composé","J'irai à la plage":"future","J'irais à la plage":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","viagem"],"notaEn":"Present of «aller»: je vais, tu vas, il va, nous allons, vous allez, ils vont. The future switches stems: «j'irai».","requerTodas":["fr-p003","fr-p087"],"v":"f09313a4"},{"idioma":"fr","id":"fr-v004","tipo":"frase","fr":"Elle fait du sport.","en":"She does sports.","aceitasEn":["she does sports","she plays sports","she does sport","she exercises","she works out"],"distratoresEn":["She used to do sports.","She did sports.","She'll do sports.","She would do sports."],"formasFr":{"Elle faisait du sport":"imperfect","Elle a fait du sport":"passé composé","Elle fera du sport":"future","Elle ferait du sport":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","saúde"],"notaEn":"«Faire du sport», with the partitive, is to do sports. Present of «faire»: je fais, nous faisons, vous faites, ils font; future «elle fera».","requerTodas":["fr-p004","fr-p161"],"v":"222a81f0"},{"idioma":"fr","id":"fr-v005","tipo":"frase","fr":"Ils prennent le train.","aceitasFr":["Elles prennent le train."],"en":"They take the train.","aceitasEn":["they take the train","theyre taking the train","they are taking the train","they go by train"],"distratoresEn":["They used to take the train.","They took the train.","They'll take the train.","They would take the train."],"formasFr":{"Ils prenaient le train":"imperfect","Ils ont pris le train":"passé composé","Ils prendront le train":"future","Ils prendraient le train":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","viagem"],"notaEn":"Present of «prendre»: je prends, nous prenons, ils prennent (double «n»). Past participle: «pris».","requerTodas":["fr-p011","fr-p089"],"v":"8c99020a"},{"idioma":"fr","id":"fr-v006","tipo":"frase","fr":"Il ne peut pas venir.","aceitasFr":["Il peut pas venir."],"en":"He can't come.","aceitasEn":["he cant come","he cannot come","he is not able to come","he isnt able to come"],"distratoresEn":["He couldn't come.","He wasn't able to come.","He won't be able to come.","He wouldn't be able to come."],"formasFr":{"Il ne pouvait pas venir":"imperfect","Il n'a pas pu venir":"passé composé","Il ne pourra pas venir":"future","Il ne pourrait pas venir":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular"],"notaEn":"The future and conditional of «pouvoir» have a double «r»: «il pourra», «il pourrait». Past participle: «pu».","requerTodas":["fr-p006","fr-p009"],"v":"4db35ee9"},{"idioma":"fr","id":"fr-v007","tipo":"frase","fr":"Elle veut un chien.","en":"She wants a dog.","aceitasEn":["she wants a dog"],"distratoresEn":["She used to want a dog.","She wanted a dog.","She'll want a dog.","She would like a dog."],"formasFr":{"Elle voulait un chien":"imperfect","Elle a voulu un chien":"passé composé","Elle voudra un chien":"future","Elle voudrait un chien":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","animais"],"notaEn":"Present of «vouloir»: je veux, tu veux, il veut, nous voulons, ils veulent. The conditional, «elle voudrait», is would like.","requerTodas":["fr-p007","fr-p090"],"v":"6fc4f26d"},{"idioma":"fr","id":"fr-v008","tipo":"frase","fr":"Je sais la réponse.","aceitasFr":["Je connais la réponse."],"en":"I know the answer.","aceitasEn":["i know the answer"],"distratoresEn":["I knew the answer.","I found out the answer.","I'll know the answer.","I would know the answer."],"formasFr":{"Je savais la réponse":"imperfect","J'ai su la réponse":"passé composé","Je saurai la réponse":"future","Je saurais la réponse":"conditional"},"nivel":"A2","tags":["conjugação","presente","irregular"],"notaEn":"Irregular future: «je saurai». In the passé composé, «j'ai su» means I found out.","requerTodas":["fr-p008","fr-p091"],"v":"63e9a8b2"},{"idioma":"fr","id":"fr-v009","tipo":"frase","fr":"Il vient avec nous.","en":"He's coming with us.","aceitasEn":["hes coming with us","he is coming with us","he comes with us"],"distratoresEn":["He was coming with us.","He came with us.","He'll come with us.","He would come with us."],"formasFr":{"Il venait avec nous":"imperfect","Il est venu avec nous":"passé composé","Il viendra avec nous":"future","Il viendrait avec nous":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular"],"notaEn":"«Venir» forms the passé composé with «être»: «il est venu». The future adds a «d»: «il viendra».","requerTodas":["fr-p009"],"v":"77b9eb82"},{"idioma":"fr","id":"fr-v010","tipo":"frase","fr":"Il m'a dit non.","en":"He told me no.","aceitasEn":["he told me no","he said no to me","he said no"],"distratoresEn":["He tells me no.","He used to tell me no.","He'll tell me no.","He would tell me no."],"formasFr":{"Il me dit non":"present","Il me disait non":"imperfect","Il me dira non":"future","Il me dirait non":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular"],"notaEn":"The past participle of «dire» is «dit». The pronoun goes before the helper verb: «il m'a dit», he told me.","requerTodas":["fr-p005"],"v":"53201d87"},{"idioma":"fr","id":"fr-v011","tipo":"frase","fr":"Je vois la mer.","en":"I can see the sea.","aceitasEn":["i can see the sea","i see the sea","i can see the ocean","i see the ocean"],"distratoresEn":["I could see the sea.","I saw the sea.","I'll see the sea.","I would see the sea."],"formasFr":{"Je voyais la mer":"imperfect","J'ai vu la mer":"passé composé","Je verrai la mer":"future","Je verrais la mer":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","natureza"],"notaEn":"«La mer» is feminine. The future of «voir» has a double «r»: «je verrai». Past participle: «vu».","requerTodas":["fr-p010","fr-p092"],"v":"8d07ad9e"},{"idioma":"fr","id":"fr-v012","tipo":"frase","fr":"Il boit du vin.","en":"He drinks wine.","aceitasEn":["he drinks wine","hes drinking wine","he is drinking wine"],"distratoresEn":["He used to drink wine.","He drank wine.","He'll drink wine.","He would drink wine."],"formasFr":{"Il buvait du vin":"imperfect","Il a bu du vin":"passé composé","Il boira du vin":"future","Il boirait du vin":"conditional"},"nivel":"A2","tags":["conjugação","presente","irregular","comida"],"notaEn":"«Boire» changes stem in the plural and the imperfect: «nous buvons», «il buvait». Past participle: «bu».","requerTodas":["fr-p014","fr-p093"],"v":"cbb102cd"},{"idioma":"fr","id":"fr-v013","tipo":"frase","fr":"Elle parle trois langues.","en":"She speaks three languages.","aceitasEn":["she speaks three languages","she speaks 3 languages"],"distratoresEn":["She used to speak three languages.","She spoke three languages.","She'll speak three languages.","She would speak three languages."],"formasFr":{"Elle parlait trois langues":"imperfect","Elle a parlé trois langues":"passé composé","Elle parlera trois langues":"future","Elle parlerait trois langues":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular"],"notaEn":"The regular «-er» pattern: future and conditional are built on the whole infinitive, «parler-a», «parler-ait».","requerTodas":["fr-p012","fr-p094","fr-p095"],"v":"254d23f4"},{"idioma":"fr","id":"fr-v014","tipo":"frase","fr":"J'ai mangé une pomme.","en":"I ate an apple.","aceitasEn":["i ate an apple","ive eaten an apple","i have eaten an apple","i had an apple"],"distratoresEn":["I'm eating an apple.","I was eating an apple.","I'm going to eat an apple.","I'll eat an apple."],"formasFr":{"Je mange une pomme":"present","Je mangeais une pomme":"imperfect","Je vais manger une pomme":"near future","Je mangerai une pomme":"future"},"nivel":"A1","tags":["conjugação","pretérito","regular","comida"],"notaEn":"The everyday past is the passé composé: «avoir» + participle, used for both I ate and I have eaten. In «-er» verbs the participle ends in «-é».","requerTodas":["fr-p013","fr-p096"],"v":"fa586b22"},{"idioma":"fr","id":"fr-v015","tipo":"frase","fr":"Nous sommes allés au cinéma.","aceitasFr":["Nous sommes allées au cinéma.","On est allés au cinéma."],"en":"We went to the movies.","aceitasEn":["we went to the movies","we went to the cinema","we went to see a movie"],"distratoresEn":["We're going to the movies.","We used to go to the movies.","We'll go to the movies.","We would go to the movies."],"formasFr":{"Nous allons au cinéma":"present","Nous allions au cinéma":"imperfect","Nous irons au cinéma":"future","Nous irions au cinéma":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","irregular","cultura"],"notaEn":"Verbs of motion (aller, venir, partir, arriver…) take «être» in the passé composé, and the participle agrees: «nous sommes allés», «elles sont allées».","requerTodas":["fr-p001","fr-p003","fr-p097"],"v":"a94a88ae"},{"idioma":"fr","id":"fr-v016","tipo":"frase","fr":"Elle est partie.","en":"She left.","aceitasEn":["she left","she has left","she went away","she has gone"],"distratoresEn":["She's leaving.","She was leaving.","She's going to leave.","She'll leave."],"formasFr":{"Elle part":"present","Elle partait":"imperfect","Elle va partir":"near future","Elle partira":"future"},"nivel":"A1","tags":["conjugação","pretérito","irregular"],"notaEn":"«Partir» takes «être» in the passé composé, and the participle agrees with her: «elle est partie».","requerTodas":["fr-p001","fr-p083"],"v":"64be71e1"},{"idioma":"fr","id":"fr-v017","tipo":"frase","fr":"Je travaillais à Paris.","en":"I used to work in Paris.","aceitasEn":["i used to work in paris","i was working in paris"],"distratoresEn":["I work in Paris.","I worked in Paris.","I'll work in Paris.","I would work in Paris."],"formasFr":{"Je travaille à Paris":"present","J'ai travaillé à Paris":"passé composé","Je travaillerai à Paris":"future","Je travaillerais à Paris":"conditional"},"nivel":"A2","tags":["conjugação","imperfeito","regular","trabalho"],"notaEn":"The imperfect tells what used to happen. Its endings are the same for every verb: -ais, -ais, -ait, -ions, -iez, -aient.","requerTodas":["fr-p017"],"v":"ca1acc28"},{"idioma":"fr","id":"fr-v018","tipo":"frase","fr":"Il faisait froid.","en":"It was cold.","aceitasEn":["it was cold"],"distratoresEn":["It's cold.","It's been cold.","It'll be cold.","It would be cold."],"formasFr":{"Il fait froid":"present","Il a fait froid":"passé composé","Il fera froid":"future","Il ferait froid":"conditional"},"nivel":"A2","tags":["conjugação","imperfeito","irregular","natureza"],"notaEn":"The imperfect describes the background: what the weather was like. The passé composé, «il a fait froid», reports a closed period.","requerTodas":["fr-p004","fr-p080"],"v":"9e9cdb8c"},{"idioma":"fr","id":"fr-v019","tipo":"frase","fr":"On va manger au restaurant.","aceitasFr":["Nous allons manger au restaurant."],"en":"We're going to eat at the restaurant.","aceitasEn":["we are going to eat at the restaurant","were going to eat at the restaurant","were going to eat at a restaurant","we are going to eat at a restaurant"],"distratoresEn":["We eat at the restaurant.","We ate at the restaurant.","We used to eat at the restaurant.","We would eat at the restaurant."],"formasFr":{"On mange au restaurant":"present","On a mangé au restaurant":"passé composé","On mangeait au restaurant":"imperfect","On mangerait au restaurant":"conditional"},"nivel":"A1","tags":["conjugação","futuro","comida"],"notaEn":"The near future is «aller» + infinitive, just like going to: «on va manger». It's the most common future in speech.","requerTodas":["fr-p003","fr-p013","fr-p098"],"v":"51f52dc1"},{"idioma":"fr","id":"fr-v020","tipo":"frase","fr":"Tu verras.","en":"You'll see.","aceitasEn":["youll see","you will see","you are going to see"],"distratoresEn":["You see.","You saw.","You used to see.","You would see."],"formasFr":{"Tu vois":"present","Tu as vu":"passé composé","Tu voyais":"imperfect","Tu verrais":"conditional"},"nivel":"A2","tags":["conjugação","futuro","irregular"],"notaEn":"The simple future adds the endings of «avoir» to the infinitive: «tu parleras». Some verbs change stem: «tu verras», «tu seras», «tu auras», «tu iras».","requerTodas":["fr-p010"],"v":"79a0aaf4"},{"idioma":"fr","id":"fr-v021","tipo":"frase","fr":"Ce serait génial !","en":"That would be great!","aceitasEn":["that would be great","it would be great","thatd be great","that would be awesome"],"distratoresEn":["That's great!","That was great!","It's been great!","That'll be great!"],"formasFr":{"C'est génial":"present","C'était génial":"imperfect","Ça a été génial":"passé composé","Ce sera génial":"future"},"nivel":"A2","tags":["conjugação","condicional","irregular"],"notaEn":"The conditional joins the future stem and the imperfect endings: «ser-» + «-ait» = «serait».","requerTodas":["fr-p001","fr-p099"],"v":"286d5e2f"},{"idioma":"fr","id":"fr-v022","tipo":"frase","fr":"Tu as vu ce film ?","aceitasFr":["Vous avez vu ce film ?"],"en":"Did you see this movie?","aceitasEn":["did you see this movie","have you seen this movie","did you see that movie","have you seen this film","did you watch this movie"],"distratoresEn":["Are you watching this movie?","Did you use to watch this movie?","Are you going to see this movie?","Will you see this movie?"],"formasFr":{"Tu vois ce film":"present","Tu voyais ce film":"imperfect","Tu vas voir ce film":"near future","Tu verras ce film":"future"},"nivel":"A1","tags":["conjugação","pretérito","irregular","cultura"],"notaEn":"Irregular participle of «voir»: «vu». «Ce film»: «ce» means this or that.","requerTodas":["fr-p002","fr-p010","fr-p100"],"v":"26338564"},{"idioma":"fr","id":"fr-v023","tipo":"frase","fr":"J'ai pris le métro.","en":"I took the subway.","aceitasEn":["i took the subway","i took the metro","ive taken the subway","i have taken the subway","i took the underground"],"distratoresEn":["I take the subway.","I used to take the subway.","I'm going to take the subway.","I'll take the subway."],"formasFr":{"Je prends le métro":"present","Je prenais le métro":"imperfect","Je vais prendre le métro":"near future","Je prendrai le métro":"future"},"nivel":"A1","tags":["conjugação","pretérito","irregular","cidade"],"notaEn":"Irregular participle of «prendre»: «pris», silent «s». Same in «apprendre», «appris», and «comprendre», «compris».","requerTodas":["fr-p002","fr-p011","fr-p101"],"v":"c4da3cc5"},{"idioma":"fr","id":"fr-v024","tipo":"frase","fr":"J'ai eu peur.","en":"I got scared.","aceitasEn":["i got scared","i was scared","i was afraid","i got frightened"],"distratoresEn":["I'm scared.","I used to be scared.","I'll be scared.","I would be scared."],"formasFr":{"J'ai peur":"present","J'avais peur":"imperfect","J'aurai peur":"future","J'aurais peur":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular"],"notaEn":"Fear is something you have: «avoir peur». The participle of «avoir» is «eu», pronounced like the «u» in «tu».","requerTodas":["fr-p002","fr-p102"],"v":"ebff2f27"},{"idioma":"fr","id":"fr-p051","tipo":"palavra","fr":"vingt","en":"twenty","aceitasEn":["twenty","20"],"distratoresEn":["thirty","twelve","two","a hundred"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The «gt» is silent: «vingt» sounds like «vin» (wine). The «t» is heard again in «vingt et un» and from «vingt-deux» to «vingt-neuf».","v":"a8828f4e","pos":407},{"idioma":"fr","id":"fr-p052","tipo":"palavra","fr":"l'an","aceitasFr":["un an"],"en":"the year (counting)","aceitasEn":["year","the year","years"],"distratoresEn":["the month (calendar)","the day (of the week)","the ring (gold)","the nest (bird)"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Masculine. The year you count with: age («vingt ans»), duration («deux ans»), dates («l'an 2000»). The year as lived is «l'année».","v":"807ad884","pos":42},{"idioma":"fr","id":"fr-p053","tipo":"palavra","fr":"le problème","en":"the problem","aceitasEn":["problem","the problem","the issue","the trouble"],"distratoresEn":["the poem","the prize","the program","the purpose"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Masculine. «Pas de problème», no problem.","v":"a54e78ea","transp":"parecida","pos":124},{"idioma":"fr","id":"fr-p054","tipo":"palavra","fr":"français","aceitasFr":["française","le français"],"en":"French","aceitasEn":["french"],"distratoresEn":["fresh","frank","Flemish","English"],"nivel":"A1","tags":["adjetivo","cultura"],"notaEn":"Adjective and language: «un livre français», «parler français». Lowercase; only the people are capitalized: «les Français».","v":"4479a36b","pos":806},{"idioma":"fr","id":"fr-p055","tipo":"palavra","fr":"la vérité","en":"the truth","aceitasEn":["truth","the truth"],"distratoresEn":["the vegetable","the variety","the will","the lie"],"nivel":"A1","tags":["cotidiano"],"notaEn":"French «-té» often matches English «-ty»: «la liberté», liberty; «la société», society.","v":"2f6e227f","pos":418},{"idioma":"fr","id":"fr-p056","tipo":"palavra","fr":"entrer","en":"to enter","aceitasEn":["to enter","enter","to come in","to go in"],"distratoresEn":["to bury","to deliver","to entertain","to meet"],"nivel":"A1","tags":["verbo"],"notaEn":"Regular «-er» verb, with «être» in the passé composé: «je suis entré». The entrance is «l'entrée», which on a menu is the starter.","v":"c8acaf30","transp":"parecida","pos":116},{"idioma":"fr","id":"fr-p057","tipo":"palavra","fr":"le café","en":"coffee","aceitasEn":["coffee","the coffee","cafe","the cafe","a cafe"],"distratoresEn":["tea","cocoa","milk","sugar"],"nivel":"A1","tags":["comida","cidade"],"notaEn":"Both the drink and the place: «on se retrouve au café», let's meet at the café. Ordered on its own, «un café» is an espresso.","v":"5e1fa861","pos":340},{"idioma":"fr","id":"fr-p058","tipo":"palavra","fr":"nager","en":"to swim","aceitasEn":["to swim","swim"],"distratoresEn":["to deny","to sail","to be born","to dive"],"nivel":"A1","tags":["verbo","natureza"],"notaEn":"Like «manger», it adds an «e» in «nous nageons». Swimming, the sport, is «la natation».","v":"bab4d405","pos":1830},{"idioma":"fr","id":"fr-p059","tipo":"palavra","fr":"demain","en":"tomorrow","aceitasEn":["tomorrow"],"distratoresEn":["yesterday","afterwards","in the morning","today"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Tomorrow. The morning is «le matin». «À demain !», see you tomorrow.","v":"f980ac54","pos":221},{"idioma":"fr","id":"fr-p060","tipo":"palavra","fr":"le bus","en":"the bus","aceitasEn":["bus","the bus"],"distratoresEn":["the streetcar","the boat","the taxi","the bust"],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"The final «s» is pronounced. A long-distance coach is «le car».","v":"0bf078c2","transp":"total","pos":1040},{"idioma":"fr","id":"fr-p061","tipo":"palavra","fr":"trop","en":"too / too much","aceitasEn":["too","too much","too many"],"distratoresEn":["little / not much","late / later","so much / so","almost / nearly"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Before an adjective, «trop» is too: «trop cher», too expensive. With a noun it takes «de»: «trop de gens», too many people.","v":"62e9e03d","pos":73},{"idioma":"fr","id":"fr-p062","tipo":"palavra","fr":"vite","en":"fast / quickly","aceitasEn":["fast","quickly","quick"],"distratoresEn":["slowly / slow","early / ahead","far / away","late / later"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Adverb: «parler vite», to talk fast. The adjective is «rapide». «Vite !», quick!","v":"a5bae2f8","pos":144},{"idioma":"fr","id":"fr-p063","tipo":"palavra","fr":"la mère","en":"the mother","aceitasEn":["mother","the mother","mom","the mom"],"distratoresEn":["the table","the girl","the sister","the grandmother"],"nivel":"A1","tags":["família"],"notaEn":"It sounds exactly like «la mer» (the sea). Mom is «maman».","v":"eb47714d","pos":121},{"idioma":"fr","id":"fr-p064","tipo":"palavra","fr":"midi","en":"noon","aceitasEn":["noon","midday"],"distratoresEn":["middle","month","Sunday","dusk"],"nivel":"A1","tags":["cotidiano"],"notaEn":"No article: «à midi», at noon. Capitalized, «le Midi» is the south of France.","v":"4f63560a","pos":1145},{"idioma":"fr","id":"fr-p065","tipo":"palavra","fr":"la viande","en":"meat","aceitasEn":["meat","the meat"],"distratoresEn":["fruit","vegetables","vineyard","pasta"],"nivel":"A1","tags":["comida"],"notaEn":"Meat as food. Flesh is «la chair».","v":"a492d682","pos":1209},{"idioma":"fr","id":"fr-p066","tipo":"palavra","fr":"le verre","en":"the glass","aceitasEn":["glass","the glass"],"distratoresEn":["the plate","the vase","the fork","the verse"],"nivel":"A1","tags":["comida","casa"],"notaEn":"Both a drinking glass and the material: «un verre d'eau», «une table en verre». Eyeglasses are «les lunettes».","v":"49bf339f","pos":414},{"idioma":"fr","id":"fr-p067","tipo":"palavra","fr":"beaucoup","en":"a lot","aceitasEn":["a lot","much","very much","lots"],"distratoresEn":["a little","nicely","cheaply","too much"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Beaucoup» is a lot, very much: «j'aime beaucoup»; with a noun, «beaucoup de»: «beaucoup d'amis». Before adjectives, very is «très».","v":"2422a4d6","pos":65},{"idioma":"fr","id":"fr-p068","tipo":"palavra","fr":"le chocolat","en":"chocolate","aceitasEn":["chocolate","the chocolate"],"distratoresEn":["cocoa","chewing gum","caramel","rattle"],"nivel":"A1","tags":["comida"],"notaEn":"The final «t» is silent. Hot chocolate is «un chocolat chaud»; the pastry is «un pain au chocolat».","v":"684a87fd","transp":"parecida","pos":1284},{"idioma":"fr","id":"fr-p069","tipo":"palavra","fr":"l'hôpital","en":"the hospital","aceitasEn":["hospital","the hospital"],"distratoresEn":["the hotel","the hospice","the guest","the post office"],"nivel":"A1","tags":["saúde","cidade"],"notaEn":"The circumflex marks a lost «s»: «hospital» became «hôpital». Same in «forêt» (forest) and «fête» (feast).","v":"477ec586","transp":"parecida","pos":611},{"idioma":"fr","id":"fr-p070","tipo":"palavra","fr":"tout","aceitasFr":["toute","tous","toutes"],"en":"all / every","aceitasEn":["all","every","everything","whole"],"distratoresEn":["so much / so many","other / another","none / no","few / little"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Four forms: «tout», «toute», «tous», «toutes». Alone, it means everything: «c'est tout», that's all.","v":"65a6e1ba","pos":12},{"idioma":"fr","id":"fr-p071","tipo":"palavra","fr":"rentrer","en":"to go back (home)","aceitasEn":["to go back","to go home","to come home","to come back","to get home","to return"],"distratoresEn":["to go in (somewhere)","to yield (a profit)","to withdraw (take out)","to go out (of the house)"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"To go back home, or back inside. It takes «être» in the passé composé: «je suis rentré tard», I got home late.","v":"60a5f752","pos":130},{"idioma":"fr","id":"fr-p072","tipo":"palavra","fr":"le voisin","aceitasFr":["la voisine"],"en":"the neighbor","aceitasEn":["neighbor","the neighbor","the neighbour","neighbour"],"distratoresEn":["the visitor","the poison","the cousin","the colleague"],"nivel":"A1","tags":["casa","social"],"notaEn":"Feminine «la voisine». The neighborhood is «le quartier».","v":"212136c4","pos":815},{"idioma":"fr","id":"fr-p073","tipo":"palavra","fr":"jouer","en":"to play","aceitasEn":["to play","play"],"distratoresEn":["to judge","to join","to swear","to roll"],"nivel":"A1","tags":["verbo"],"notaEn":"To play games («jouer au foot», with «à») or instruments («jouer du piano», with «de»).","v":"e0a4644c","pos":112},{"idioma":"fr","id":"fr-p074","tipo":"palavra","fr":"meilleur","aceitasFr":["meilleure"],"en":"better / best","aceitasEn":["better","best","the best"],"distratoresEn":["bigger / biggest","smaller / smallest","worse / worst","more / most"],"nivel":"A1","tags":["adjetivo"],"notaEn":"The adjective: «un meilleur prix», a better price. The adverb, better with verbs, is «mieux»: «ça va mieux», things are better.","v":"86232186","pos":223},{"idioma":"fr","id":"fr-p075","tipo":"palavra","fr":"acheter","en":"to buy","aceitasEn":["to buy","buy","to purchase"],"distratoresEn":["to find","to accept","to guess right","to sell"],"nivel":"A1","tags":["verbo","compras"],"notaEn":"It takes a grave accent before a silent ending: «j'achète», but «nous achetons». To find is «trouver».","v":"7a6fdc72","pos":234},{"idioma":"fr","id":"fr-p076","tipo":"palavra","fr":"lire","en":"to read","aceitasEn":["to read","read"],"distratoresEn":["to laugh","to tie","to free","to write"],"nivel":"A1","tags":["verbo","escola"],"notaEn":"Irregular: je lis, il lit, nous lisons, ils lisent; past participle «lu». To laugh is «rire».","v":"dfbdb944","pos":190},{"idioma":"fr","id":"fr-p077","tipo":"palavra","fr":"la panne","en":"the breakdown","aceitasEn":["breakdown","the breakdown","failure","the failure"],"distratoresEn":["the pity","the pan","the pause","the part"],"nivel":"A2","tags":["cidade","tecnologia"],"notaEn":"«En panne», broken down, out of order: for cars, elevators, machines. A power outage is «la panne de courant».","v":"a306c5d3","pos":2550},{"idioma":"fr","id":"fr-p078","tipo":"palavra","fr":"le frère","en":"the brother","aceitasEn":["brother","the brother"],"distratoresEn":["the brake","the freight","the cousin","the son"],"nivel":"A1","tags":["família"],"notaEn":"Big brother, «le grand frère»; little brother, «le petit frère».","v":"3b9845ad","pos":255},{"idioma":"fr","id":"fr-p079","tipo":"palavra","fr":"l'appartement","en":"the apartment","aceitasEn":["apartment","the apartment","the flat","flat"],"distratoresEn":["the device","the office","the closet","the chamber"],"nivel":"A1","tags":["casa"],"notaEn":"Masculine. Double «p»: «appartement».","v":"bf69ca4f","transp":"parecida","pos":584},{"idioma":"fr","id":"fr-p080","tipo":"palavra","fr":"froid","aceitasFr":["froide","le froid"],"en":"cold","aceitasEn":["cold","the cold"],"distratoresEn":["weak","fried","strong","cool"],"nivel":"A1","tags":["adjetivo","natureza"],"notaEn":"Feminine «froide». Weather takes «faire»: «il fait froid»; people take «avoir»: «j'ai froid», I'm cold.","v":"19a4871d","pos":541},{"idioma":"fr","id":"fr-p081","tipo":"palavra","fr":"anglais","aceitasFr":["anglaise","l'anglais"],"en":"English","aceitasEn":["english"],"distratoresEn":["Angolan","German","Spanish","French"],"nivel":"A1","tags":["adjetivo","cultura"],"notaEn":"Adjective and language, lowercase: «parler anglais». The people are capitalized: «les Anglais».","v":"981c1da3","pos":741},{"idioma":"fr","id":"fr-p082","tipo":"palavra","fr":"devoir","en":"must / to have to","aceitasEn":["must","to have to","have to","to owe","owe"],"distratoresEn":["to leave / to drop","to hurt / to ache","to give / to hand","to doubt / to hesitate"],"nivel":"A1","tags":["verbo"],"notaEn":"Obligation and debt: «je dois partir» (I have to go), «je te dois dix euros» (I owe you ten euros). Forms: je dois, nous devons, ils doivent; participle «dû».","v":"2e752405","pos":14},{"idioma":"fr","id":"fr-p083","tipo":"palavra","fr":"partir","en":"to leave","aceitasEn":["to leave","leave","to go away","to depart"],"distratoresEn":["to share","to stop","to jump","to lose"],"nivel":"A1","tags":["verbo","viagem","falso-amigo"],"notaEn":"To leave, set off: «je pars demain», I'm leaving tomorrow. To share is «partager». It takes «être» in the passé composé: «elle est partie».","v":"e2ef6cc0","pos":49},{"idioma":"fr","id":"fr-p084","tipo":"palavra","fr":"le lundi","aceitasFr":["lundi"],"en":"Monday","aceitasEn":["monday"],"distratoresEn":["Tuesday","Friday","Wednesday","Thursday"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Moon day. Without an article it's one Monday: «lundi», on Monday. With one, every Monday: «le lundi». Lowercase.","v":"ea938997","pos":1120},{"idioma":"fr","id":"fr-p085","tipo":"palavra","fr":"le retard","en":"the delay","aceitasEn":["delay","the delay","lateness"],"distratoresEn":["the portrait","the return","the message","the rest"],"nivel":"A2","tags":["cotidiano","viagem"],"notaEn":"«Être en retard», to be late; «le train a du retard», the train is delayed.","v":"edade308","pos":673},{"idioma":"fr","id":"fr-p086","tipo":"palavra","fr":"la faim","en":"hunger","aceitasEn":["hunger","the hunger"],"distratoresEn":["fame","faith","fever","thirst"],"nivel":"A1","tags":["comida","corpo"],"notaEn":"It sounds like «la fin» (the end). With «avoir» and no article: «j'ai faim», I'm hungry.","v":"09db4cd0","pos":863},{"idioma":"fr","id":"fr-p087","tipo":"palavra","fr":"la plage","en":"the beach","aceitasEn":["beach","the beach"],"distratoresEn":["the plague","the page","the plate","the pool"],"nivel":"A1","tags":["viagem","natureza"],"notaEn":"Feminine. «À la plage», at the beach. A page is «la page».","v":"f9886c74","pos":1065},{"idioma":"fr","id":"fr-p088","tipo":"palavra","fr":"la cuisine","en":"kitchen / cooking","aceitasEn":["kitchen","the kitchen","cooking","cuisine"],"distratoresEn":["curtain / drape","cook / chef","living room / lounge","laundry / washroom"],"nivel":"A1","tags":["casa","comida"],"notaEn":"Both the room and the cooking: «la cuisine française». To cook is «faire la cuisine».","v":"23a542ff","pos":562},{"idioma":"fr","id":"fr-p089","tipo":"palavra","fr":"le train","en":"the train","aceitasEn":["train","the train"],"distratoresEn":["the rail","the training","the suit","the wheat"],"nivel":"A1","tags":["viagem"],"notaEn":"«En train de» + infinitive means in the middle of doing: «je suis en train de manger», I'm eating right now.","v":"97a2c251","transp":"total","pos":239},{"idioma":"fr","id":"fr-p090","tipo":"palavra","fr":"le chien","en":"the dog","aceitasEn":["dog","the dog"],"distratoresEn":["the cat","the smell","the boss","the duck"],"nivel":"A1","tags":["animais"],"notaEn":"Feminine «la chienne». A cat is «le chat».","v":"44736268","pos":383},{"idioma":"fr","id":"fr-p091","tipo":"palavra","fr":"la réponse","en":"the answer","aceitasEn":["answer","the answer","the reply","the response"],"distratoresEn":["the question","the rent","the reservation","the refusal"],"nivel":"A1","tags":["escola"],"notaEn":"To answer is «répondre». A question is «la question».","v":"3783e2bc","pos":477},{"idioma":"fr","id":"fr-p092","tipo":"palavra","fr":"la mer","en":"the sea","aceitasEn":["sea","the sea","the ocean"],"distratoresEn":["the river","the lake","the month","the pier"],"nivel":"A1","tags":["natureza","viagem"],"notaEn":"Feminine in French, and it sounds just like «la mère» (the mother). «Au bord de la mer», at the seaside.","v":"040e3f11","pos":556},{"idioma":"fr","id":"fr-p093","tipo":"palavra","fr":"le vin","en":"wine","aceitasEn":["wine","the wine"],"distratoresEn":["vinegar","wind","soda","wicker"],"nivel":"A1","tags":["comida"],"notaEn":"«Vin rouge», red; «vin blanc», white. It sounds like «vingt» (twenty).","v":"9ee834b7","pos":613},{"idioma":"fr","id":"fr-p094","tipo":"palavra","fr":"trois","en":"three","aceitasEn":["three","3"],"distratoresEn":["thirteen","thirty","two","six"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The «s» is heard only before a vowel: «trois amis», «trwah-zah-MEE». Don't mix it up with «très», very.","v":"01781a3c","pos":326},{"idioma":"fr","id":"fr-p095","tipo":"palavra","fr":"la langue","en":"language / tongue","aceitasEn":["language","tongue","the language","the tongue"],"distratoresEn":["firewood / logs","spear / lance","moon / moonlight","glove / mitten"],"nivel":"A1","tags":["escola","corpo"],"notaEn":"Both a language and the tongue in your mouth. «Ma langue maternelle», my mother tongue.","v":"9008f4a9","pos":578},{"idioma":"fr","id":"fr-p096","tipo":"palavra","fr":"la pomme","en":"the apple","aceitasEn":["apple","the apple"],"distratoresEn":["the ointment","the plum","the pear","the dove"],"nivel":"A1","tags":["comida"],"notaEn":"A potato is «la pomme de terre», literally earth apple; fries are «les frites».","v":"0b7f78f9","pos":1233},{"idioma":"fr","id":"fr-p097","tipo":"palavra","fr":"le cinéma","en":"the movie theater","aceitasEn":["movie theater","the movie theater","the movies","movies","cinema","the cinema"],"distratoresEn":["the theater","the museum","the circus","the stage"],"nivel":"A1","tags":["cultura","cidade"],"notaEn":"«Aller au cinéma», to go to the movies. Casually, «le ciné».","v":"aea2a93e","pos":829},{"idioma":"fr","id":"fr-p098","tipo":"palavra","fr":"le restaurant","en":"the restaurant","aceitasEn":["restaurant","the restaurant"],"distratoresEn":["the rest","the market","the hotel","the bar"],"nivel":"A1","tags":["comida","cidade"],"notaEn":"English took the word as is; in French the final «t» is silent.","v":"872f063c","transp":"total","pos":710},{"idioma":"fr","id":"fr-p099","tipo":"palavra","fr":"génial","aceitasFr":["géniale"],"en":"great","aceitasEn":["great","brilliant","awesome","fantastic"],"distratoresEn":["kind","general","frozen","genuine"],"nivel":"A2","tags":["adjetivo","gíria"],"notaEn":"In conversation, great or awesome: «c'est génial !». Kind is «gentil».","v":"c29c095c","pos":711},{"idioma":"fr","id":"fr-p100","tipo":"palavra","fr":"le film","en":"the movie","aceitasEn":["movie","the movie","film","the film"],"distratoresEn":["the son","the thread","the end","the book"],"nivel":"A1","tags":["cultura"],"notaEn":"The thread is «le fil»; the end, «la fin»; the son, «le fils».","v":"6520086d","pos":247},{"idioma":"fr","id":"fr-p101","tipo":"palavra","fr":"le métro","en":"the subway","aceitasEn":["subway","the subway","the metro","metro","the underground","the tube"],"distratoresEn":["the train","the streetcar","the tunnel","the bus"],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"«Prendre le métro», to take the subway. A station is «la station de métro».","v":"67f2943c","pos":1700},{"idioma":"fr","id":"fr-p102","tipo":"palavra","fr":"la peur","en":"fear","aceitasEn":["fear","the fear","fright"],"distratoresEn":["hair","danger","weight","modesty"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine in French. With «avoir» and no article: «j'ai peur», I'm scared. «Avoir peur de», to be afraid of.","v":"6e2445fa","pos":131},{"idioma":"fr","id":"fr-p103","tipo":"palavra","fr":"le père","en":"the father","aceitasEn":["father","the father","dad","the dad"],"distratoresEn":["the turkey","the forgiveness","the grandfather","the uncle"],"nivel":"A1","tags":["família"],"notaEn":"Dad is «papa». Parents, mother and father, are «les parents».","v":"1a2ea87f","pos":64},{"idioma":"fr","id":"fr-p104","tipo":"palavra","fr":"la sœur","en":"the sister","aceitasEn":["sister","the sister"],"distratoresEn":["the luck","the lady","the cousin","the daughter"],"nivel":"A1","tags":["família"],"notaEn":"Spelled with the «œ» ligature. It also means a nun, like Sister in English.","v":"b82296d8","pos":365},{"idioma":"fr","id":"fr-p105","tipo":"palavra","fr":"la famille","en":"the family","aceitasEn":["family","the family"],"distratoresEn":["the row","the fault","the firm","the factory"],"nivel":"A1","tags":["família"],"notaEn":"The «-ille» sounds like «-ee-y»: «fa-MEE-y». «En famille», with the family.","v":"864041ab","pos":103},{"idioma":"fr","id":"fr-p106","tipo":"palavra","fr":"l'école","aceitasFr":["une école"],"en":"the school","aceitasEn":["school","the school"],"distratoresEn":["the stairs","the corner","the lock","the church"],"nivel":"A1","tags":["escola"],"notaEn":"Feminine. The initial «é» often marks a lost «s»: school, «école»; state, «état». A church is «l'église».","v":"703526fb","pos":205},{"idioma":"fr","id":"fr-p107","tipo":"palavra","fr":"la chambre","en":"the bedroom","aceitasEn":["bedroom","the bedroom","the room","room"],"distratoresEn":["the bed","the kitchen","the living room","the office"],"nivel":"A1","tags":["casa","viagem"],"notaEn":"A bedroom, or a hotel room. The living room is «le salon»; the bed, «le lit».","v":"2ada2fb5","pos":163},{"idioma":"fr","id":"fr-p108","tipo":"palavra","fr":"sortir","en":"to go out","aceitasEn":["to go out","go out","to get out","to come out"],"distratoresEn":["to draw lots","to have an effect","to go up","to go in"],"nivel":"A1","tags":["verbo","cidade"],"notaEn":"To go out of a place, or out for fun: «on sort ce soir ?». It takes «être»: «je suis sorti». The exit is «la sortie».","v":"76d1cf67","pos":67},{"idioma":"fr","id":"fr-p109","tipo":"palavra","fr":"dormir","en":"to sleep","aceitasEn":["to sleep","sleep"],"distratoresEn":["to dwell","to last","to tame","to wake up"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"Irregular singular: je dors, tu dors, il dort; regular plural: nous dormons.","v":"6d018eef","pos":244},{"idioma":"fr","id":"fr-p110","tipo":"palavra","fr":"comprendre","en":"to understand","aceitasEn":["to understand","understand"],"distratoresEn":["to buy","to arrest","to learn","to complete"],"nivel":"A1","tags":["verbo","escola"],"notaEn":"Conjugated like «prendre»: je comprends, nous comprenons; participle «compris». «Compris !», got it!","v":"4b957ad8","pos":72},{"idioma":"fr","id":"fr-p111","tipo":"palavra","fr":"aider","en":"to help","aceitasEn":["to help","help"],"distratoresEn":["to postpone","to hate","to act","to wait"],"nivel":"A1","tags":["verbo"],"notaEn":"Regular «-er» verb, taking a direct object: «aider quelqu'un», to help someone. Help, the noun, is «l'aide».","v":"d54d0848","pos":106},{"idioma":"fr","id":"fr-p112","tipo":"palavra","fr":"chaud","aceitasFr":["chaude","le chaud"],"en":"hot / warm","aceitasEn":["hot","warm"],"distratoresEn":["flat / dull","dear / pricey","lukewarm / tepid","cold / chilly"],"nivel":"A1","tags":["adjetivo","natureza"],"notaEn":"Feminine «chaude». Weather: «il fait chaud», it's hot; people: «j'ai chaud», I'm hot.","v":"9ff016c9","pos":660},{"idioma":"fr","id":"fr-p113","tipo":"palavra","fr":"fatigué","aceitasFr":["fatiguée"],"en":"tired","aceitasEn":["tired","exhausted","weary"],"distratoresEn":["sliced","starving","furious","injured"],"nivel":"A1","tags":["adjetivo","saúde"],"notaEn":"Feminine «fatiguée»; it sounds the same. «Je suis fatigué», I'm tired.","v":"26222f99","pos":861},{"idioma":"fr","id":"fr-p114","tipo":"palavra","fr":"souvent","en":"often","aceitasEn":["often","frequently"],"distratoresEn":["rarely","sometimes","never again","again"],"nivel":"A1","tags":["cotidiano"],"notaEn":"It goes after the verb: «je vais souvent au cinéma», I often go to the movies. Sometimes is «parfois».","v":"83b5f1d1","pos":280},{"idioma":"fr","id":"fr-u068","tipo":"frase","requer":"fr-p088","fr":"Elle est dans la cuisine.","aceitasFr":["Elle est à la cuisine."],"en":"She's in the kitchen.","aceitasEn":["shes in the kitchen","she is in the kitchen"],"distratoresEn":["She's in the living room.","She's on the balcony.","She's in the garage.","She's in the laundry room."],"nivel":"A1","tags":["casa"],"notaEn":"«Dans», inside: «dans la cuisine», in the kitchen («à la cuisine» is also heard). The same word means cooking or cuisine: «la cuisine française».","requerTodas":["fr-p001","fr-p088"],"v":"00760b7f"},{"idioma":"fr","id":"fr-u069","tipo":"frase","requer":"fr-p103","fr":"Mon père fait la cuisine.","en":"My father does the cooking.","aceitasEn":["my father does the cooking","my dad does the cooking","my father cooks","my dad cooks"],"distratoresEn":["My father does the cleaning.","My father does the laundry.","My father does the shopping.","My father does the ironing."],"nivel":"A1","tags":["família","casa","comida"],"notaEn":"To cook is «faire la cuisine»: «la cuisine» is both the kitchen and the cooking. Dad, in conversation, is «papa».","requerTodas":["fr-p103","fr-p004","fr-p088"],"v":"119bcc10"},{"idioma":"fr","id":"fr-u070","tipo":"frase","requer":"fr-p104","fr":"J'ai deux sœurs.","en":"I have two sisters.","aceitasEn":["i have two sisters","ive got two sisters","i have got two sisters","i have 2 sisters"],"distratoresEn":["I have two daughters.","I have two cousins.","I have two aunts.","I have two nieces."],"nivel":"A1","tags":["família"],"notaEn":"«Sœur» is written with the joined «œ». The «x» of «deux» is silent except before a vowel: «deux amis», «duh-zah-MEE».","requerTodas":["fr-p002","fr-p120","fr-p104"],"v":"4ede65f9"},{"idioma":"fr","id":"fr-u071","tipo":"frase","requer":"fr-p105","fr":"Ma famille habite à Lyon.","en":"My family lives in Lyon.","aceitasEn":["my family lives in lyon"],"distratoresEn":["My sister lives in Lyon.","My aunt lives in Lyon.","My grandmother lives in Lyon.","My cousin lives in Lyon."],"nivel":"A1","tags":["família","casa"],"notaEn":"«Ma famille», with the feminine possessive. The «-ille» ending sounds like «-ee-y»: «fa-MEE-y». The verb is singular, as in English.","requerTodas":["fr-p105","fr-p016"],"v":"7a488721"},{"idioma":"fr","id":"fr-u072","tipo":"frase","requer":"fr-p106","fr":"Les enfants sont à l'école.","en":"The children are at school.","aceitasEn":["the children are at school","the kids are at school","the children are in school","the kids are in school"],"distratoresEn":["The children are at the beach.","The children are at church.","The children are at the pool.","The children are at daycare."],"nivel":"A1","tags":["escola","família"],"notaEn":"At school is «à l'école», with «à». «École» is feminine; before a vowel the article shrinks to «l'».","requerTodas":["fr-p023","fr-p001","fr-p106"],"v":"b8f92d6f"},{"idioma":"fr","id":"fr-u073","tipo":"frase","requer":"fr-p107","fr":"Ma chambre est très petite.","en":"My bedroom is very small.","aceitasEn":["my bedroom is very small","my room is very small","my bedroom is really small","my room is really small","my bedroom is tiny","my room is tiny"],"distratoresEn":["My bathroom is very small.","My office is very small.","My garden is very small.","My hallway is very small."],"nivel":"A1","tags":["casa"],"notaEn":"«Chambre» is feminine: «ma chambre», «petite». It's a bedroom, or a hotel room — the old English «chamber».","requerTodas":["fr-p107","fr-p001","fr-p043","fr-p038"],"v":"7aac5ca2"},{"idioma":"fr","id":"fr-u074","tipo":"frase","requer":"fr-p108","fr":"On sort ce soir ?","en":"Shall we go out tonight?","aceitasEn":["shall we go out tonight","should we go out tonight","do you want to go out tonight","want to go out tonight","lets go out tonight","are we going out tonight"],"distratoresEn":["Shall we have dinner tonight?","Shall we go dancing tonight?","Shall we work out tonight?","Shall we study tonight?"],"nivel":"A1","tags":["social","cidade"],"notaEn":"«Sortir» on its own means to go out and have fun. «Ce soir» is tonight: «le soir» is the evening, «la nuit» the night you sleep through.","requerTodas":["fr-p108","fr-p160"],"v":"4a723680"},{"idioma":"fr","id":"fr-u075","tipo":"frase","requer":"fr-p108","fr":"Je sors du travail à six heures.","en":"I leave work at six.","aceitasEn":["i leave work at six","i leave work at 6","i get off work at six","i get out of work at six","i finish work at six"],"distratoresEn":["I get to work at six.","I start work at six.","I have dinner at work at six.","I'm at work at six."],"nivel":"A1","tags":["trabalho","cotidiano"],"notaEn":"Leaving a place is «sortir de»; «du» is «de» + «le». Clock times need «heures»: «à six heures», at six (o'clock).","requerTodas":["fr-p108","fr-p029","fr-p179","fr-p129"],"v":"1a313285"},{"idioma":"fr","id":"fr-u076","tipo":"frase","requer":"fr-p109","fr":"Tu as bien dormi ?","aceitasFr":["Vous avez bien dormi ?"],"en":"Did you sleep well?","aceitasEn":["did you sleep well","did you sleep ok","did you sleep alright","have you slept well"],"distratoresEn":["Did you eat well?","Did you have a good dinner?","Did you have a good trip?","Did you get there safely?"],"nivel":"A1","tags":["casa","cotidiano"],"notaEn":"The participle of «dormir» is «dormi». In the passé composé, «bien» sits between the helper verb and the participle: «tu as bien dormi».","requerTodas":["fr-p002","fr-p044","fr-p109"],"v":"275bdda3"},{"idioma":"fr","id":"fr-u077","tipo":"frase","requer":"fr-p110","fr":"Je n'ai pas compris la question.","aceitasFr":["J'ai pas compris la question."],"en":"I didn't understand the question.","aceitasEn":["i didnt understand the question","i did not understand the question","i didnt get the question"],"distratoresEn":["I didn't hear the question.","I didn't read the question.","I didn't see the question.","I didn't ask the question."],"nivel":"A1","tags":["escola"],"notaEn":"The participle of «comprendre» is «compris», like «pris» from «prendre». The negation wraps the helper verb: «je n'ai pas compris».","requerTodas":["fr-p002","fr-p110","fr-p140"],"v":"1a4dafc6"},{"idioma":"fr","id":"fr-u078","tipo":"frase","requer":"fr-p111","fr":"Tu peux m'aider ?","aceitasFr":["Vous pouvez m'aider ?","Tu pourrais m'aider ?"],"en":"Can you help me?","aceitasEn":["can you help me","could you help me","will you help me","can you give me a hand"],"distratoresEn":["Can you hear me?","Can you wait for me?","Can you call me?","Can you give me a ride?"],"nivel":"A1","tags":["cotidiano","social"],"notaEn":"«Aider» takes a direct object: «aider quelqu'un». The pronoun goes before the infinitive: «m'aider», help me.","requerTodas":["fr-p006","fr-p111"],"v":"9687d263"},{"idioma":"fr","id":"fr-u079","tipo":"frase","requer":"fr-p112","fr":"J'ai chaud.","en":"I'm hot.","aceitasEn":["im hot","i am hot","im warm","i am warm","i feel hot"],"distratoresEn":["I'm cold.","I'm sleepy.","I'm thirsty.","I'm scared."],"nivel":"A1","tags":["corpo","natureza"],"notaEn":"In French you have heat instead of being hot: «j'ai chaud», «j'ai froid». With «être», «chaud» describes things: «le café est chaud».","requerTodas":["fr-p002","fr-p112"],"v":"763375ff"},{"idioma":"fr","id":"fr-u080","tipo":"frase","requer":"fr-p112","fr":"Le café est trop chaud.","en":"The coffee is too hot.","aceitasEn":["the coffee is too hot","the coffees too hot"],"distratoresEn":["The coffee is too cold.","The coffee is too sweet.","The coffee is too strong.","The coffee is too bitter."],"nivel":"A1","tags":["comida"],"notaEn":"For things, «chaud» is hot; for weather, «il fait chaud», it's hot out. «Trop», too, goes before the adjective.","requerTodas":["fr-p057","fr-p001","fr-p061","fr-p112"],"v":"ac304ae9"},{"idioma":"fr","id":"fr-u081","tipo":"frase","requer":"fr-p113","fr":"Je suis très fatigué.","aceitasFr":["Je suis très fatiguée."],"en":"I'm very tired.","aceitasEn":["im very tired","i am very tired","im really tired","i am really tired","im so tired"],"distratoresEn":["I'm very busy.","I'm very sick.","I'm very nervous.","I'm very bored."],"nivel":"A1","tags":["saúde","cotidiano"],"notaEn":"A woman writes «fatiguée», pronounced the same. Think of English fatigue.","requerTodas":["fr-p001","fr-p043","fr-p113"],"v":"9f20e841"},{"idioma":"fr","id":"fr-u082","tipo":"frase","requer":"fr-p114","fr":"Je vais souvent au cinéma.","en":"I often go to the movies.","aceitasEn":["i often go to the movies","i go to the movies often","i go to the movies a lot","i often go to the cinema","i go to the cinema a lot","i frequently go to the movies"],"distratoresEn":["I rarely go to the movies.","I sometimes go to the movies.","I hardly ever go to the movies.","I never go to the movies."],"nivel":"A1","tags":["cultura","cotidiano"],"notaEn":"«Souvent» comes right after the verb: «je vais souvent». Sometimes is «parfois»; rarely, «rarement».","requerTodas":["fr-p003","fr-p114","fr-p097"],"v":"666916f4"},{"idioma":"fr","id":"fr-u083","tipo":"frase","requer":"fr-p002","fr":"J'ai besoin de dormir.","en":"I need to sleep.","aceitasEn":["i need to sleep","i need some sleep","i need sleep","i need to get some sleep"],"distratoresEn":["I want to sleep.","I'm going to sleep.","I'm trying to sleep.","I like sleeping."],"nivel":"A1","tags":["cotidiano","gramática"],"notaEn":"To need is «avoir besoin de», literally to have need of: «j'ai besoin de toi», I need you; «j'ai besoin d'un café».","requerTodas":["fr-p002","fr-p146","fr-p109"],"v":"de40a7e4"},{"idioma":"fr","id":"fr-u084","tipo":"frase","requer":"fr-p002","fr":"J'ai mal à la tête.","en":"I have a headache.","aceitasEn":["i have a headache","ive got a headache","i have got a headache","my head hurts"],"distratoresEn":["I have a toothache.","I have a stomachache.","I have a sore throat.","I have an earache."],"nivel":"A1","tags":["saúde","corpo"],"notaEn":"Pain is something you have: «avoir mal à» + the body part, with the article. «J'ai mal au dos», my back hurts; «j'ai mal aux dents», I have a toothache.","requerTodas":["fr-p002","fr-p151","fr-p144"],"v":"ed1231af"},{"idioma":"fr","id":"fr-u085","tipo":"frase","requer":"fr-p001","fr":"Nous sommes brésiliens.","aceitasFr":["Nous sommes brésiliennes.","On est brésiliens."],"en":"We're Brazilian.","aceitasEn":["were brazilian","we are brazilian","were from brazil","we are from brazil"],"distratoresEn":["We're Argentinian.","We're Portuguese.","We're Italian.","We're Chilean."],"nivel":"A1","tags":["social","cultura"],"notaEn":"Unlike English, the nationality adjective is lowercase: «nous sommes brésiliens». Capitalized, it's the people: «les Brésiliens».","requerTodas":["fr-p001","fr-p116"],"v":"49d50d43"},{"idioma":"fr","id":"fr-u086","tipo":"frase","requer":"fr-p001","fr":"Elle est médecin.","en":"She's a doctor.","aceitasEn":["shes a doctor","she is a doctor","shes a physician"],"distratoresEn":["She's a nurse.","She's a teacher.","She's a lawyer.","She's a dentist."],"nivel":"A1","tags":["profissões","saúde"],"notaEn":"After «être», a profession takes no article: «elle est médecin», she's a doctor. «Médecin» is used for men and women alike.","requerTodas":["fr-p001","fr-p155"],"v":"35090bd0"},{"idioma":"fr","id":"fr-u087","tipo":"frase","requer":"fr-p003","fr":"Je vais au travail à pied.","en":"I walk to work.","aceitasEn":["i walk to work","i go to work on foot","im walking to work"],"distratoresEn":["I drive to work.","I take the bus to work.","I bike to work.","I take the subway to work."],"nivel":"A1","tags":["cidade","trabalho"],"notaEn":"On foot is «à pied»; by car or bus, «en voiture», «en bus». In «le pied», the foot, the «d» is silent.","requerTodas":["fr-p003","fr-p029","fr-p158"],"v":"68876c47"},{"idioma":"fr","id":"fr-u088","tipo":"frase","requer":"fr-p003","fr":"Cette robe te va bien.","en":"That dress looks good on you.","aceitasEn":["that dress looks good on you","this dress looks good on you","that dress looks nice on you","that dress looks great on you","that dress suits you"],"distratoresEn":["That coat looks good on you.","That hat looks good on you.","That suit looks good on you.","That haircut looks good on you."],"nivel":"A2","tags":["roupa","falso-amigo"],"notaEn":"«Aller bien à quelqu'un» is to suit someone. «La robe» is a dress; a bathrobe is «le peignoir».","requerTodas":["fr-p142","fr-p003","fr-p044"],"v":"ba7f6e9c"},{"idioma":"fr","id":"fr-u089","tipo":"frase","requer":"fr-p003","fr":"Je vais chez le médecin.","en":"I'm going to the doctor.","aceitasEn":["im going to the doctor","i am going to the doctor","im going to the doctors","im going to see the doctor","i go to the doctor"],"distratoresEn":["I'm going to the dentist.","I'm going to the bank.","I'm going to the hairdresser.","I'm going to the market."],"nivel":"A1","tags":["saúde","cidade"],"notaEn":"To someone's place or office you go «chez»: «chez le médecin», «chez moi», «chez Paul». To a place, «à»: «à la banque».","requerTodas":["fr-p003","fr-p155"],"v":"6e8a1662"},{"idioma":"fr","id":"fr-u090","tipo":"frase","requer":"fr-p004","fr":"Fais attention !","aceitasFr":["Faites attention !"],"en":"Be careful!","aceitasEn":["be careful","careful","watch out","look out","pay attention"],"distratoresEn":["Stay calm!","Be patient!","Keep still!","Don't worry!"],"nivel":"A1","tags":["cotidiano","expressão"],"notaEn":"Literally «make attention»: it covers both be careful and pay attention. «Fais» is the «tu» form; «faites», the «vous» form.","requerTodas":["fr-p004","fr-p127"],"v":"b13810d0"},{"idioma":"fr","id":"fr-u091","tipo":"frase","requer":"fr-p004","fr":"Je fais les courses le samedi.","en":"I do the shopping on Saturdays.","aceitasEn":["i do the shopping on saturdays","i do the shopping on saturday","i do the grocery shopping on saturdays","i go grocery shopping on saturdays","i do my shopping on saturdays"],"distratoresEn":["I do the cleaning on Saturdays.","I make lunch on Saturdays.","I work out on Saturdays.","I do my nails on Saturdays."],"nivel":"A1","tags":["compras","cotidiano"],"notaEn":"«Faire les courses» is the everyday grocery shopping. «Le samedi», with the article, means every Saturday; «samedi» alone, a single Saturday.","requerTodas":["fr-p004","fr-p162","fr-p159"],"v":"92649ff2"},{"idioma":"fr","id":"fr-u092","tipo":"frase","requer":"fr-p004","fr":"Je fais la vaisselle.","en":"I do the dishes.","aceitasEn":["i do the dishes","i wash the dishes","im doing the dishes","i do the washing up","i wash up"],"distratoresEn":["I dry the dishes.","I do the laundry.","I put away the dishes.","I mop the floor."],"nivel":"A1","tags":["casa"],"notaEn":"«La vaisselle» is the dishes, and «faire la vaisselle» is doing them. Laundry is «faire la lessive».","requerTodas":["fr-p004","fr-p145"],"v":"2900f08b"},{"idioma":"fr","id":"fr-u093","tipo":"frase","requer":"fr-p011","fr":"Je prends une douche le matin.","en":"I shower in the morning.","aceitasEn":["i shower in the morning","i shower in the mornings","i take a shower in the morning","i have a shower in the morning"],"distratoresEn":["I have breakfast in the morning.","I sunbathe in the morning.","I take my medicine in the morning.","I drink tea in the morning."],"nivel":"A1","tags":["casa","cotidiano"],"notaEn":"You «take» a shower with «prendre»: «prendre une douche»; a bath, «prendre un bain». «Le matin», with the article, means in the mornings.","requerTodas":["fr-p011","fr-p134","fr-p153"],"v":"5741c8ee"},{"idioma":"fr","id":"fr-u094","tipo":"frase","requer":"fr-p011","fr":"On prend le petit déjeuner à huit heures.","aceitasFr":["Nous prenons le petit déjeuner à huit heures.","On prend le petit-déjeuner à huit heures."],"en":"We have breakfast at eight.","aceitasEn":["we have breakfast at eight","we have breakfast at 8","we eat breakfast at eight","we have breakfast at eight oclock"],"distratoresEn":["We have lunch at eight.","We have dinner at eight.","We have a snack at eight.","We have a meeting at eight."],"nivel":"A1","tags":["comida","cotidiano"],"notaEn":"Breakfast is «le petit déjeuner», literally the little lunch, and you «take» it with «prendre». Lunch is «le déjeuner»; dinner, «le dîner».","requerTodas":["fr-p011","fr-p156","fr-p126","fr-p129"],"v":"45d885e0"},{"idioma":"fr","id":"fr-u095","tipo":"frase","requer":"fr-p010","fr":"Tu as vu mes clés ?","aceitasFr":["Vous avez vu mes clés ?","Tu n'as pas vu mes clés ?"],"en":"Have you seen my keys?","aceitasEn":["have you seen my keys","did you see my keys"],"distratoresEn":["Have you seen my socks?","Have you seen my gloves?","Have you seen my photos?","Have you seen my stuff?"],"nivel":"A1","tags":["casa","objetos"],"notaEn":"«Mes» is the plural of both «mon» and «ma». «La clé» is also spelled «la clef», pronounced the same.","requerTodas":["fr-p002","fr-p010","fr-p133"],"v":"45840dfd"},{"idioma":"fr","id":"fr-u096","tipo":"frase","requer":"fr-p100","fr":"On regarde un film ce soir ?","en":"Shall we watch a movie tonight?","aceitasEn":["shall we watch a movie tonight","should we watch a movie tonight","do you want to watch a movie tonight","want to watch a movie tonight","lets watch a movie tonight","shall we watch a film tonight"],"distratoresEn":["Shall we watch a game tonight?","Shall we watch a show tonight?","Shall we watch a documentary tonight?","Shall we watch cartoons tonight?"],"nivel":"A1","tags":["cultura","social"],"notaEn":"«Regarder» is to watch or look at; «voir» is to see. Films and TV are «regardés», though «voir un film» is common too, especially at the cinema.","requerTodas":["fr-p172","fr-p100","fr-p160"],"v":"c651e3c9"},{"idioma":"fr","id":"fr-u097","tipo":"frase","requer":"fr-p005","fr":"Qu'est-ce que tu as dit ?","aceitasFr":["Tu as dit quoi ?","Qu'est-ce que vous avez dit ?"],"en":"What did you say?","aceitasEn":["what did you say","what have you said"],"distratoresEn":["What did you do?","What did you see?","What did you eat?","What did you buy?"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The participle of «dire» is «dit», silent «t». To ask someone to repeat, «Pardon ?» or «Comment ?» is enough.","requerTodas":["fr-p002","fr-p005"],"v":"d44ed43a"},{"idioma":"fr","id":"fr-u098","tipo":"frase","requer":"fr-p005","fr":"Je vais le dire à mon frère.","en":"I'm going to tell my brother.","aceitasEn":["im going to tell my brother","i am going to tell my brother","im gonna tell my brother","ill tell my brother","i will tell my brother"],"distratoresEn":["I'm going to tell my father.","I'm going to tell my cousin.","I'm going to tell my boss.","I'm going to tell my neighbor."],"nivel":"A1","tags":["família"],"notaEn":"You say something «à» someone: «dire quelque chose à quelqu'un», to tell someone something. «Le» (it) goes before the infinitive.","requerTodas":["fr-p003","fr-p005","fr-p078"],"v":"cbf424cc"},{"idioma":"fr","id":"fr-u099","tipo":"frase","requer":"fr-p009","fr":"Je viens d'arriver.","en":"I just arrived.","aceitasEn":["i just arrived","ive just arrived","i have just arrived","i just got here","ive just got here","i just got in"],"distratoresEn":["I'm arriving.","I'll be there soon.","I arrived a long time ago.","I haven't arrived yet."],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«Venir de» + infinitive is the recent past: «je viens d'arriver», I've just arrived. Nobody is coming from anywhere.","requerTodas":["fr-p009","fr-p115"],"v":"6142cce6"},{"idioma":"fr","id":"fr-u100","tipo":"frase","requer":"fr-p104","fr":"Je ne connais pas sa sœur.","aceitasFr":["Je connais pas sa sœur."],"en":"I don't know his sister.","aceitasEn":["i dont know his sister","i dont know her sister","i do not know his sister","i do not know her sister","ive never met his sister","ive never met her sister"],"distratoresEn":["I don't know his mother.","I don't know his daughter.","I don't know his wife.","I don't know his girlfriend."],"nivel":"A1","tags":["família","social"],"notaEn":"People and places take «connaître»: «je connais Paris». Facts and skills take «savoir»: «je sais nager». «Sa sœur» can be his or her sister.","requerTodas":["fr-p119","fr-p104"],"v":"1fdbdcd6"},{"idioma":"fr","id":"fr-u101","tipo":"frase","requer":"fr-p006","fr":"Je peux payer par carte ?","aceitasFr":["Est-ce que je peux payer par carte ?","Je peux payer avec la carte ?","Je peux payer par carte bancaire ?"],"en":"Can I pay by card?","aceitasEn":["can i pay by card","can i pay with a card","can i pay with card","can i pay by credit card","could i pay by card","do you take cards"],"distratoresEn":["Can I pay in cash?","Can I pay by check?","Can I pay in dollars?","Can I pay in euros?"],"nivel":"A1","tags":["compras"],"notaEn":"You pay «par carte» or «en espèces», in cash. «La carte» is also a map and a menu.","requerTodas":["fr-p006","fr-p170","fr-p131"],"v":"ce7f93a7"},{"idioma":"fr","id":"fr-u102","tipo":"frase","requer":"fr-p082","fr":"Il doit être malade.","en":"He must be sick.","aceitasEn":["he must be sick","he must be ill","he must be unwell","hes probably sick","he is probably sick"],"distratoresEn":["He's going to get sick.","He was sick.","He isn't sick.","He's pretending to be sick."],"nivel":"A2","tags":["gramática","saúde"],"notaEn":"«Devoir» also expresses a guess, just like must: «il doit être malade». Only context separates it from have to.","requerTodas":["fr-p082","fr-p001","fr-p166"],"v":"4786f3cb"},{"idioma":"fr","id":"fr-u103","tipo":"frase","requer":"fr-p082","fr":"Je te dois dix euros.","aceitasFr":["Je vous dois dix euros."],"en":"I owe you ten euros.","aceitasEn":["i owe you ten euros","i owe you 10 euros"],"distratoresEn":["I'll give you ten euros.","I'll lend you ten euros.","I'll pay you ten euros.","I'll send you ten euros."],"nivel":"A1","tags":["compras","economia"],"notaEn":"With an object, «devoir» means to owe: «je te dois dix euros». The «x» of «dix» sounds like «z» before a vowel: «dix euros», «dee-zuh-ROH».","requerTodas":["fr-p082","fr-p121","fr-p128"],"v":"20e45c61"},{"idioma":"fr","id":"fr-u104","tipo":"frase","requer":"fr-p070","fr":"Tout le monde est là.","en":"Everyone is here.","aceitasEn":["everyone is here","everybody is here","everyones here","everybodys here","everyone is there"],"distratoresEn":["Nobody is here.","Few people are here.","Lots of people are here.","Hardly anyone is here."],"nivel":"A1","tags":["cotidiano","social"],"notaEn":"«Tout le monde» (literally all the world) takes a singular verb. «Là» means there, but in speech it often means here: «je suis là», I'm here.","requerTodas":["fr-p070","fr-p154","fr-p001","fr-p165"],"v":"be7f792f"},{"idioma":"fr","id":"fr-u105","tipo":"frase","requer":"fr-p070","fr":"J'ai tout mangé.","en":"I ate everything.","aceitasEn":["i ate everything","i ate it all","i ate all of it","ive eaten everything","i have eaten everything"],"distratoresEn":["I ate very little.","I ate half.","I ate too much.","I didn't eat anything."],"nivel":"A1","tags":["comida"],"notaEn":"«Tout», everything, sits between the helper verb and the participle, like «déjà» and «bien»: «j'ai tout mangé».","requerTodas":["fr-p002","fr-p070","fr-p013"],"v":"edbc927c"},{"idioma":"fr","id":"fr-u106","tipo":"frase","requer":"fr-p070","fr":"J'ai dormi toute la journée.","en":"I slept all day.","aceitasEn":["i slept all day","i slept all day long","i slept the whole day","ive slept all day","i have slept all day"],"distratoresEn":["I slept all afternoon.","I slept all night.","I slept all Sunday.","I slept the whole flight."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Toute la journée», all day: «tout» agrees with the feminine «journée». «La journée» is the day as lived, start to finish; «le jour», the calendar day.","requerTodas":["fr-p002","fr-p109","fr-p070","fr-p137"],"v":"e7b0d027"},{"idioma":"fr","id":"fr-u107","tipo":"frase","requer":"fr-p067","fr":"Il y a beaucoup de monde.","en":"There are a lot of people.","aceitasEn":["there are a lot of people","there are lots of people","there are many people","theres a lot of people","its crowded","its very crowded"],"distratoresEn":["There are few people.","There's nobody here.","There are too many people.","There's a lot of noise."],"nivel":"A1","tags":["cotidiano","cidade"],"notaEn":"«Le monde» is the world and, in speech, people: «beaucoup de monde», lots of people. After «beaucoup», just «de», no article.","requerTodas":["fr-p002","fr-p067","fr-p154"],"v":"5f861c79"},{"idioma":"fr","id":"fr-u108","tipo":"frase","requer":"fr-p061","fr":"J'ai trop de travail.","en":"I have too much work.","aceitasEn":["i have too much work","ive got too much work","i have got too much work"],"distratoresEn":["I have little work.","I don't have any work.","I have more work.","I have less work."],"nivel":"A1","tags":["trabalho"],"notaEn":"«Trop de», too much, works like «beaucoup de», a lot of: just «de», no article. «Trop» means excess; «beaucoup», just quantity.","requerTodas":["fr-p002","fr-p061","fr-p029"],"v":"19ec4afe"},{"idioma":"fr","id":"fr-u109","tipo":"frase","requer":"fr-p083","fr":"Nous partons en vacances demain.","aceitasFr":["On part en vacances demain.","Demain, nous partons en vacances."],"en":"We're going on vacation tomorrow.","aceitasEn":["were going on vacation tomorrow","we are going on vacation tomorrow","were leaving on vacation tomorrow","we are leaving on vacation tomorrow","were off on vacation tomorrow","were going on holiday tomorrow","we leave on vacation tomorrow"],"distratoresEn":["We're back from vacation tomorrow.","We're leaving home tomorrow.","We're leaving the hotel tomorrow.","We're on vacation tomorrow."],"nivel":"A1","tags":["viagem"],"notaEn":"«Partir en vacances», to go (off) on vacation. «Les vacances» is always plural; «les grandes vacances» is the summer break.","requerTodas":["fr-p083","fr-p163","fr-p059"],"v":"8b571a56"},{"idioma":"fr","id":"fr-u110","tipo":"frase","requer":"fr-p071","fr":"Je suis rentré tard hier.","aceitasFr":["Je suis rentrée tard hier.","Hier, je suis rentré tard."],"en":"I got home late yesterday.","aceitasEn":["i got home late yesterday","i came home late yesterday","i got back late yesterday","i went home late yesterday","yesterday i got home late"],"distratoresEn":["I got home early yesterday.","I got home alone yesterday.","I got home tired yesterday.","I got home soaked yesterday."],"nivel":"A1","tags":["casa","cotidiano"],"notaEn":"«Rentrer» takes «être» in the passé composé, and a woman writes «rentrée». «Tard» is late; «en retard» is late for something.","requerTodas":["fr-p001","fr-p071","fr-p180","fr-p125"],"v":"8b59c9b6"},{"idioma":"fr","id":"fr-u111","tipo":"frase","requer":"fr-p073","fr":"Il joue au foot.","aceitasFr":["Il joue au football."],"en":"He plays soccer.","aceitasEn":["he plays soccer","he plays football","hes playing soccer","hes playing football"],"distratoresEn":["He plays volleyball.","He plays tennis.","He plays basketball.","He plays chess."],"nivel":"A1","tags":["cotidiano","cultura"],"notaEn":"Games and sports take «jouer à», which fuses with «le» into «au»: «jouer au foot», «jouer aux cartes». Instruments take «de»: «jouer du piano».","requerTodas":["fr-p073","fr-p149"],"v":"5b73fece"},{"idioma":"fr","id":"fr-u112","tipo":"frase","requer":"fr-p073","fr":"Elle joue du piano.","en":"She plays the piano.","aceitasEn":["she plays the piano","she plays piano","shes playing the piano"],"distratoresEn":["She plays the guitar.","She plays the flute.","She plays the drums.","She plays the violin."],"nivel":"A1","tags":["cultura"],"notaEn":"Instruments take «jouer de»: «jouer du piano», «jouer de la guitare». Games take «jouer à».","requerTodas":["fr-p073","fr-p157"],"v":"540825a4"},{"idioma":"fr","id":"fr-u113","tipo":"frase","requer":"fr-p015","fr":"J'aime lire.","en":"I like reading.","aceitasEn":["i like reading","i like to read","i love reading","i love to read","i enjoy reading"],"distratoresEn":["I like writing.","I like swimming.","I like cooking.","I like sleeping."],"nivel":"A1","tags":["escola","cotidiano"],"notaEn":"«Aimer» + bare infinitive: «j'aime lire», I like reading.","requerTodas":["fr-p015","fr-p076"],"v":"3a77876c"},{"idioma":"fr","id":"fr-u114","tipo":"frase","requer":"fr-p007","fr":"Je voudrais réserver une table.","en":"I'd like to book a table.","aceitasEn":["id like to book a table","i would like to book a table","id like to reserve a table","i would like to reserve a table","i want to book a table","i want to reserve a table"],"distratoresEn":["I'd like to book a room.","I'd like to book a taxi.","I'd like to book a meeting room.","I'd like to book a ticket."],"nivel":"A1","tags":["comida","viagem"],"notaEn":"«Je voudrais», the conditional of «vouloir», is the polite I'd like.","requerTodas":["fr-p007","fr-p174","fr-p143"],"v":"82cca79a"},{"idioma":"fr","id":"fr-u115","tipo":"frase","requer":"fr-p007","fr":"Oui, je veux bien.","en":"Yes, please.","aceitasEn":["yes please","yes id love to","yes i would love to","yes id like that","yes thank you"],"distratoresEn":["Yes, I know.","Yes, I'm coming.","No, I'll pass.","Yes, but later."],"nivel":"A2","tags":["social","expressão"],"notaEn":"To accept an offer, «je veux bien» is the polite yes: «bien» softens the «I want». A bare «je veux» would sound blunt.","requerTodas":["fr-p007","fr-p044"],"v":"79b17832"},{"idioma":"fr","id":"fr-u116","tipo":"frase","requer":"fr-p002","fr":"Tu as raison.","aceitasFr":["Vous avez raison."],"en":"You're right.","aceitasEn":["youre right","you are right","youre correct","you are correct"],"distratoresEn":["You're wrong.","You're lucky.","You're in a hurry.","You're scared."],"nivel":"A1","tags":["social"],"notaEn":"In French you have reason: «avoir raison», to be right. Being wrong is also had: «avoir tort».","requerTodas":["fr-p002","fr-p141"],"v":"0e81a211"},{"idioma":"fr","id":"fr-u117","tipo":"frase","requer":"fr-p010","fr":"Ah, je vois.","en":"Oh, I see.","aceitasEn":["oh i see","i see","ah i see","oh i get it","i get it","oh i understand"],"distratoresEn":["Oh, I forgot.","Oh, I remember.","Oh, sorry.","Oh, what a shame."],"nivel":"A1","tags":["cotidiano","expressão"],"notaEn":"«Je vois» works just like English I see: I understand.","requerTodas":["fr-p010"],"v":"a882ad59"},{"idioma":"fr","id":"fr-u118","tipo":"frase","requer":"fr-p018","fr":"J'attends le bus depuis vingt minutes.","en":"I've been waiting for the bus for twenty minutes.","aceitasEn":["ive been waiting for the bus for twenty minutes","i have been waiting for the bus for twenty minutes","ive been waiting for the bus for 20 minutes"],"distratoresEn":["I waited for the bus for twenty minutes.","I'll wait for the bus for twenty minutes.","The bus comes in twenty minutes.","I'll wait for the bus twenty more minutes."],"nivel":"A2","tags":["cidade","gramática"],"notaEn":"«Depuis» + present tense is the French have been doing: «j'attends depuis vingt minutes», and the wait is still going on.","requerTodas":["fr-p018","fr-p060","fr-p051","fr-p139"],"v":"9d47bc9c"},{"idioma":"fr","id":"fr-u119","tipo":"frase","requer":"fr-p023","fr":"Vous avez des enfants ?","aceitasFr":["Tu as des enfants ?","Est-ce que vous avez des enfants ?"],"en":"Do you have children?","aceitasEn":["do you have children","do you have kids","do you have any children","do you have any kids","have you got children","have you got any children"],"distratoresEn":["Do you have siblings?","Do you have grandchildren?","Do you have nephews?","Do you have cousins?"],"nivel":"A1","tags":["família","social"],"notaEn":"«Les enfants» means both children in general and someone's own children, at any age. A son is «le fils».","requerTodas":["fr-p002","fr-p023"],"v":"e145ad65"},{"idioma":"fr","id":"fr-u120","tipo":"frase","requer":"fr-p025","fr":"Je vais à la plage de temps en temps.","en":"I go to the beach from time to time.","aceitasEn":["i go to the beach from time to time","i go to the beach now and then","i go to the beach every now and then","i go to the beach once in a while","i go to the beach sometimes","i sometimes go to the beach"],"distratoresEn":["I go to the beach every weekend.","I go to the beach almost every day.","I only go to the beach in summer.","I go to the beach once a year."],"nivel":"A2","tags":["viagem","expressão"],"notaEn":"«De temps en temps», literally from time in time: now and then. Here «le temps» is time, not weather.","requerTodas":["fr-p003","fr-p087","fr-p025"],"v":"b4f0dd3a"},{"idioma":"fr","id":"fr-u121","tipo":"frase","requer":"fr-p028","fr":"Je vais en ville.","en":"I'm going into town.","aceitasEn":["im going into town","i am going into town","im going to town","im going downtown","i am going downtown","im going into the city","im going to the city center","im going to the city centre"],"distratoresEn":["I'm going to the market.","I'm going to the countryside.","I'm going to the bank.","I'm going to the park."],"nivel":"A1","tags":["cidade"],"notaEn":"«En ville» means into town, downtown. «La ville» is the city or town; a village is «le village».","requerTodas":["fr-p003","fr-p028"],"v":"922d57f4"},{"idioma":"fr","id":"fr-u122","tipo":"frase","requer":"fr-p034","fr":"On y va en voiture ?","en":"Shall we go by car?","aceitasEn":["shall we go by car","should we go by car","shall we drive","should we drive","are we going by car","are we driving","shall we take the car","should we take the car"],"distratoresEn":["Shall we take the bus?","Shall we take a taxi?","Shall we take the subway?","Shall we go by bike?"],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"Vehicles you get into take «en»: «en voiture», «en bus», «en train». On foot and by bike: «à pied», «à vélo». «On y va ?», shall we go?","requerTodas":["fr-p003","fr-p034"],"v":"8262206e"},{"idioma":"fr","id":"fr-u123","tipo":"frase","requer":"fr-p036","fr":"Bonne chance !","en":"Good luck!","aceitasEn":["good luck","best of luck","lots of luck"],"distratoresEn":["Have a good trip!","Have a good week!","Good job!","Have a nice vacation!"],"nivel":"A1","tags":["social","falso-amigo"],"notaEn":"«La chance» is luck: «avoir de la chance», to be lucky. A chance, an opportunity, is «l'occasion».","requerTodas":["fr-p036","fr-p132"],"v":"5819d36d"},{"idioma":"fr","id":"fr-u124","tipo":"frase","requer":"fr-p038","fr":"C'est ma petite sœur.","en":"She's my little sister.","aceitasEn":["shes my little sister","she is my little sister","shes my younger sister","she is my younger sister","shes my baby sister","this is my little sister","this is my younger sister"],"distratoresEn":["She's my big sister.","She's my middle sister.","She's my twin sister.","She's my adopted sister."],"nivel":"A1","tags":["família"],"notaEn":"Between siblings, «petit» means younger and «grand» older: «ma petite sœur», «mon grand frère», at any age.","requerTodas":["fr-p001","fr-p038","fr-p104"],"v":"4ec670ba"},{"idioma":"fr","id":"fr-u125","tipo":"frase","requer":"fr-p045","fr":"Il est aussi grand que son père.","en":"He's as tall as his father.","aceitasEn":["hes as tall as his father","he is as tall as his father","hes as tall as his dad","he is as tall as his dad"],"distratoresEn":["He's taller than his father.","He's shorter than his father.","He's almost as tall as his father.","He's much taller than his father."],"nivel":"A2","tags":["família","gramática"],"notaEn":"Equality: «aussi… que», as… as. More: «plus… que»; less: «moins… que». Here «aussi» doesn't mean also.","requerTodas":["fr-p001","fr-p045","fr-p037","fr-p103"],"v":"20ac8fc5"},{"idioma":"fr","id":"fr-u126","tipo":"frase","requer":"fr-p050","fr":"Tu es déjà allé à Paris ?","aceitasFr":["Tu es déjà allée à Paris ?","Vous êtes déjà allé à Paris ?","Est-ce que tu es déjà allé à Paris ?"],"en":"Have you ever been to Paris?","aceitasEn":["have you ever been to paris","have you been to paris","have you been to paris before","have you ever gone to paris","did you ever go to paris"],"distratoresEn":["Did you go to Paris yesterday?","Do you still go to Paris?","Did you go back to Paris?","Do you want to go to Paris?"],"nivel":"A1","tags":["viagem"],"notaEn":"In a question, «déjà» means ever. «Aller» takes «être» in the passé composé, and a woman writes «allée».","requerTodas":["fr-p001","fr-p050","fr-p003"],"v":"7a7f5f8c"},{"idioma":"fr","id":"fr-u127","tipo":"frase","requer":"fr-p053","fr":"Pas de problème !","en":"No problem!","aceitasEn":["no problem","not a problem","no worries","no prob"],"distratoresEn":["No doubt!","No rush!","No way!","No kidding!"],"nivel":"A1","tags":["social","expressão"],"notaEn":"No article, just «de», as after any negative: «pas de problème». In speech, «pas de souci» means the same. To answer a thank-you, French says «De rien».","requerTodas":["fr-p053"],"v":"9432cad6"},{"idioma":"fr","id":"fr-u128","tipo":"frase","requer":"fr-p056","fr":"Entrez !","aceitasFr":["Entre !"],"en":"Come in!","aceitasEn":["come in","come on in","please come in","do come in"],"distratoresEn":["Sit down!","Wait!","Come up!","Hold on!"],"nivel":"A1","tags":["social"],"notaEn":"Knock on a door and you'll hear «Entrez !», the «vous» form, even for one person. With «tu»: «Entre !». To enter a place is «entrer dans».","requerTodas":["fr-p056"],"v":"b59bd366"},{"idioma":"fr","id":"fr-u129","tipo":"frase","requer":"fr-p089","fr":"Le train part à huit heures.","en":"The train leaves at eight.","aceitasEn":["the train leaves at eight","the train leaves at 8","the train departs at eight","the train goes at eight"],"distratoresEn":["The train arrives at eight.","The train comes by at eight.","The train stops at eight.","The train comes back at eight."],"nivel":"A1","tags":["viagem"],"notaEn":"Trains, planes and buses «partent»: they leave, depart. Arriving is «arriver».","requerTodas":["fr-p089","fr-p083","fr-p126","fr-p129"],"v":"8d2bed89"},{"idioma":"fr","id":"fr-u130","tipo":"frase","requer":"fr-p085","fr":"Le train a du retard.","aceitasFr":["Le train est en retard."],"en":"The train is late.","aceitasEn":["the train is late","the trains late","the train is delayed","the trains delayed","the train is running late"],"distratoresEn":["The train is early.","The train is full.","The train is stopped.","The train is empty."],"nivel":"A2","tags":["viagem"],"notaEn":"Something delayed «a du retard», has delay; a person who is late «est en retard». To delay is «retarder».","requerTodas":["fr-p089","fr-p002","fr-p085"],"v":"e1b38ed9"},{"idioma":"fr","id":"fr-u131","tipo":"frase","requer":"fr-p102","fr":"J'ai peur des chiens.","en":"I'm afraid of dogs.","aceitasEn":["im afraid of dogs","i am afraid of dogs","im scared of dogs","i am scared of dogs","dogs scare me"],"distratoresEn":["I'm afraid of cats.","I'm afraid of mice.","I'm afraid of insects.","I'm afraid of bats."],"nivel":"A1","tags":["animais"],"notaEn":"To be afraid of is «avoir peur de», to have fear of. «Des» is «de» + «les»: «peur des chiens».","requerTodas":["fr-p002","fr-p102","fr-p090"],"v":"c6e565e4"},{"idioma":"fr","id":"fr-u132","tipo":"frase","requer":"fr-p093","fr":"Un verre de vin rouge, s'il vous plaît.","en":"A glass of red wine, please.","aceitasEn":["a glass of red wine please","a glass of red wine","a glass of red please","a red wine please"],"distratoresEn":["A glass of white wine, please.","A glass of rosé wine, please.","A glass of sweet wine, please.","A glass of dry wine, please."],"nivel":"A1","tags":["comida"],"notaEn":"Red wine is «vin rouge»; white, «vin blanc»; rosé, «vin rosé». Any drinking glass is «un verre».","requerTodas":["fr-p066","fr-p093","fr-p173"],"v":"cd00c720"},{"idioma":"fr","id":"fr-u133","tipo":"frase","requer":"fr-p108","fr":"Elle sort avec mon frère.","en":"She's going out with my brother.","aceitasEn":["shes going out with my brother","she is going out with my brother","she goes out with my brother","shes dating my brother","she is dating my brother","shes seeing my brother"],"distratoresEn":["She's helping my brother.","She's waiting for my brother.","She's avoiding my brother.","She's calling my brother."],"nivel":"A2","tags":["social","família"],"notaEn":"«Sortir avec quelqu'un», just like going out with someone, means dating. «Sortir avec des amis» is just going out with friends.","requerTodas":["fr-p108","fr-p078"],"v":"e699f186"},{"idioma":"fr","id":"fr-u134","tipo":"frase","requer":"fr-p075","fr":"Il faut acheter du pain.","en":"We need to buy bread.","aceitasEn":["we need to buy bread","we need to buy some bread","we have to buy bread","we have to buy some bread","we need to get bread","we need to get some bread","someone has to buy bread"],"distratoresEn":["We need to make bread.","We need to put the bread away.","We need to warm up the bread.","We need to cut the bread."],"nivel":"A1","tags":["compras","gramática"],"notaEn":"«Il faut» + infinitive is an impersonal must: we, you, someone has to. The verb, «falloir», only exists with «il».","requerTodas":["fr-p122","fr-p075","fr-p027"],"v":"46843b5a"},{"idioma":"fr","id":"fr-u135","tipo":"frase","requer":"fr-p002","fr":"Quel âge as-tu ?","aceitasFr":["Tu as quel âge ?","Quel âge tu as ?","Quel âge avez-vous ?","Vous avez quel âge ?"],"en":"How old are you?","aceitasEn":["how old are you","whats your age","what is your age"],"distratoresEn":["How tall are you?","How much do you weigh?","How many kids do you have?","How many siblings do you have?"],"nivel":"A1","tags":["social"],"notaEn":"In French you have an age: «j'ai vingt ans». The question uses «l'âge» (masculine): «quel âge». Casually: «Tu as quel âge ?».","requerTodas":["fr-p130","fr-p002"],"v":"8c248dad"},{"idioma":"fr","id":"fr-u136","tipo":"frase","requer":"fr-p017","fr":"Je suis en train de travailler.","en":"I'm working.","aceitasEn":["im working","i am working","im busy working"],"distratoresEn":["I'm going to work.","I worked.","I was working.","I just finished working."],"nivel":"A2","tags":["gramática","trabalho"],"notaEn":"«Être en train de» + infinitive stresses an action in progress: I'm busy working. No train involved.","requerTodas":["fr-p001","fr-p089","fr-p017"],"v":"b1b9eb20"},{"idioma":"fr","id":"fr-u137","tipo":"frase","requer":"fr-p011","fr":"Ça prend du temps.","en":"That takes time.","aceitasEn":["that takes time","it takes time","this takes time","that takes a while","it takes a while"],"distratoresEn":["That saves time.","There's enough time.","That passes the time.","That was a long time ago."],"nivel":"A2","tags":["cotidiano","expressão"],"notaEn":"«Prendre du temps» works like take time: «ça prend deux heures», it takes two hours.","requerTodas":["fr-p011","fr-p025"],"v":"ce292afd"},{"idioma":"fr","id":"fr-u138","tipo":"frase","requer":"fr-p080","fr":"L'eau est froide.","en":"The water is cold.","aceitasEn":["the water is cold","the waters cold"],"distratoresEn":["The water is hot.","The water is dirty.","The water is clean.","The water is salty."],"nivel":"A1","tags":["natureza"],"notaEn":"«Froid» agrees: «eau» is feminine, so «froide», and the «d» is now pronounced.","requerTodas":["fr-p026","fr-p001","fr-p080"],"v":"df1f9a37"},{"idioma":"fr","id":"fr-u139","tipo":"frase","requer":"fr-p066","fr":"J'ai cassé un verre.","en":"I broke a glass.","aceitasEn":["i broke a glass","ive broken a glass","i have broken a glass"],"distratoresEn":["I broke a plate.","I broke a mirror.","I broke a jar.","I broke a jug."],"nivel":"A1","tags":["casa"],"notaEn":"To break is «casser»: «j'ai cassé un verre». «Le verre» is a drinking glass, and glass the material.","requerTodas":["fr-p002","fr-p117","fr-p066"],"v":"aaaad71c"},{"idioma":"fr","id":"fr-u140","tipo":"frase","requer":"fr-p010","fr":"Je vais voir ma grand-mère.","en":"I'm going to see my grandmother.","aceitasEn":["im going to see my grandmother","i am going to see my grandmother","im going to visit my grandmother","i am going to visit my grandmother","im going to see my grandma","im going to visit my grandma"],"distratoresEn":["I'm going to call my grandmother.","I'm going to help my grandmother.","I'm going to wait for my grandmother.","I'm going to pick up my grandmother."],"nivel":"A1","tags":["família"],"notaEn":"«Aller voir quelqu'un» is to visit someone; «visiter» is mostly for places: «visiter un musée».","requerTodas":["fr-p003","fr-p010","fr-p136"],"v":"f69791d3"},{"idioma":"fr","id":"fr-u141","tipo":"frase","requer":"fr-p029","fr":"Je cherche du travail.","en":"I'm looking for work.","aceitasEn":["im looking for work","i am looking for work","im looking for a job","i am looking for a job","im job hunting"],"distratoresEn":["I'm looking for an apartment.","I'm looking for an internship.","I'm looking for a school.","I'm looking for a hotel."],"nivel":"A1","tags":["trabalho"],"notaEn":"To look for is «chercher», with no preposition: «je cherche du travail», «je cherche mes clés». To find is «trouver».","requerTodas":["fr-p118","fr-p029"],"v":"71e3b189"},{"idioma":"fr","id":"fr-v025","tipo":"frase","fr":"Les cours finissent à midi.","en":"Classes end at noon.","aceitasEn":["classes end at noon","classes finish at noon","class ends at noon","lessons end at noon"],"distratoresEn":["Classes used to end at noon.","Classes ended at noon.","Classes would end at noon.","Classes had ended at noon."],"formasFr":{"Les cours finissaient à midi":"imperfect","Les cours ont fini à midi":"passé composé","Les cours finiraient à midi":"conditional","Les cours avaient fini à midi":"pluperfect"},"nivel":"A2","tags":["conjugação","presente","regular","escola"],"notaEn":"«-ir» verbs like «finir» add «-iss-» in the plural: je finis, tu finis, il finit, nous finissons, vous finissez, ils finissent. «Le cours», a class, ends in «s» even in the singular.","requerTodas":["fr-p148","fr-p123","fr-p064"],"v":"67209931"},{"idioma":"fr","id":"fr-v026","tipo":"frase","fr":"Ils attendent le train.","aceitasFr":["Elles attendent le train."],"en":"They're waiting for the train.","aceitasEn":["theyre waiting for the train","they are waiting for the train","they wait for the train"],"distratoresEn":["They were waiting for the train.","They waited for the train.","They'll wait for the train.","They would wait for the train."],"formasFr":{"Ils attendaient le train":"imperfect","Ils ont attendu le train":"passé composé","Ils attendront le train":"future","Ils attendraient le train":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular","viagem"],"notaEn":"The «-re» verb pattern: j'attends, tu attends, il attend (no «t»), nous attendons, vous attendez, ils attendent. The «d» is silent in the singular. Participle: «attendu».","requerTodas":["fr-p018","fr-p089"],"v":"20207457"},{"idioma":"fr","id":"fr-v027","tipo":"frase","fr":"Il vend sa voiture.","en":"He's selling his car.","aceitasEn":["hes selling his car","he is selling his car","he sells his car"],"distratoresEn":["He was selling his car.","He sold his car.","He'll sell his car.","He would sell his car."],"formasFr":{"Il vendait sa voiture":"imperfect","Il a vendu sa voiture":"passé composé","Il vendra sa voiture":"future","Il vendrait sa voiture":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular","compras"],"notaEn":"«Vendre» follows «attendre»: je vends, il vend, nous vendons, ils vendent; participle «vendu». «Sa voiture»: the possessive agrees with «voiture», not with the owner.","requerTodas":["fr-p182","fr-p034"],"v":"e96e3b96"},{"idioma":"fr","id":"fr-v028","tipo":"frase","fr":"Son chien est mort.","en":"His dog died.","aceitasEn":["his dog died","her dog died","his dog has died","her dog has died","his dog is dead","her dog is dead"],"distratoresEn":["His dog is dying.","His dog was dying.","His dog will die.","His dog would die."],"formasFr":{"Son chien meurt":"present","Son chien mourait":"imperfect","Son chien mourra":"future","Son chien mourrait":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular","animais"],"notaEn":"«Mourir» takes «être» in the passé composé, and its participle is irregular: «mort», dead. The present changes stem: il meurt, nous mourons.","requerTodas":["fr-p090","fr-p001","fr-p168"],"v":"d0b38b35"},{"idioma":"fr","id":"fr-v029","tipo":"frase","fr":"Ils sont venus en voiture.","aceitasFr":["Elles sont venues en voiture."],"en":"They came by car.","aceitasEn":["they came by car","they came in the car","they drove here","theyve come by car","they have come by car"],"distratoresEn":["They're coming by car.","They used to come by car.","They'll come by car.","They would come by car."],"formasFr":{"Ils viennent en voiture":"present","Ils venaient en voiture":"imperfect","Ils viendront en voiture":"future","Ils viendraient en voiture":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","irregular","viagem"],"notaEn":"«Venir» takes «être» in the passé composé, and the participle agrees with the subject: «ils sont venus», «elles sont venues».","requerTodas":["fr-p001","fr-p009","fr-p034"],"v":"316ad1ff"},{"idioma":"fr","id":"fr-v030","tipo":"frase","fr":"J'ai fait un gâteau.","en":"I made a cake.","aceitasEn":["i made a cake","i baked a cake","ive made a cake","i have made a cake","ive baked a cake"],"distratoresEn":["I'm making a cake.","I was making a cake.","I'll make a cake.","I would make a cake."],"formasFr":{"Je fais un gâteau":"present","Je faisais un gâteau":"imperfect","Je vais faire un gâteau":"near future","Je ferais un gâteau":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","irregular","comida"],"notaEn":"The participle of «faire» is «fait», silent «t». «Le gâteau», cake, is masculine.","requerTodas":["fr-p002","fr-p004","fr-p150"],"v":"2489ab53"},{"idioma":"fr","id":"fr-v031","tipo":"frase","fr":"J'ai mis la clé sur la table.","en":"I put the key on the table.","aceitasEn":["i put the key on the table","ive put the key on the table","i have put the key on the table","i left the key on the table","i placed the key on the table"],"distratoresEn":["I'm putting the key on the table.","I used to put the key on the table.","I'll put the key on the table.","I would put the key on the table."],"formasFr":{"Je mets la clé sur la table":"present","Je mettais la clé sur la table":"imperfect","Je vais mettre la clé sur la table":"near future","Je mettrais la clé sur la table":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular","casa"],"notaEn":"«Mettre», to put, has an irregular participle: «mis». «Sur la table», on the table.","requerTodas":["fr-p002","fr-p167","fr-p133","fr-p143"],"v":"319c4dd2"},{"idioma":"fr","id":"fr-v032","tipo":"frase","fr":"Elle a écrit une lettre.","en":"She wrote a letter.","aceitasEn":["she wrote a letter","shes written a letter","she has written a letter"],"distratoresEn":["She's writing a letter.","She was writing a letter.","She'll write a letter.","She would write a letter."],"formasFr":{"Elle écrit une lettre":"present","Elle écrivait une lettre":"imperfect","Elle écrira une lettre":"future","Elle écrirait une lettre":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","irregular","escola"],"notaEn":"The participle of «écrire» is «écrit», the same as the present «il» form. «La lettre» is a letter, of mail or of the alphabet.","requerTodas":["fr-p002","fr-p184","fr-p138"],"v":"f9253b64"},{"idioma":"fr","id":"fr-v033","tipo":"frase","fr":"Qui a ouvert la fenêtre ?","en":"Who opened the window?","aceitasEn":["who opened the window","who has opened the window"],"distratoresEn":["Who's opening the window?","Who used to open the window?","Who will open the window?","Who would open the window?"],"formasFr":{"Qui ouvre la fenêtre":"present","Qui ouvrait la fenêtre":"imperfect","Qui ouvrira la fenêtre":"future","Qui ouvrirait la fenêtre":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular","casa"],"notaEn":"«Ouvrir», to open, takes «-er» endings in the present (j'ouvre, il ouvre), and its participle is irregular: «ouvert».","requerTodas":["fr-p002","fr-p169","fr-p135"],"v":"a5809d44"},{"idioma":"fr","id":"fr-v034","tipo":"frase","fr":"Il a été très gentil avec moi.","en":"He was very nice to me.","aceitasEn":["he was very nice to me","he was really nice to me","he was very kind to me","hes been very nice to me","he has been very nice to me","hes been very kind to me"],"distratoresEn":["He's very nice to me.","He used to be very nice to me.","He'll be very nice to me.","He would be very nice to me."],"formasFr":{"Il est très gentil avec moi":"present","Il était très gentil avec moi":"imperfect","Il sera très gentil avec moi":"future","Il serait très gentil avec moi":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular","social"],"notaEn":"The participle of «être» is «été», spelled like «l'été», summer. The passé composé reports one occasion; «il était gentil» would describe how he used to be.","requerTodas":["fr-p002","fr-p001","fr-p043","fr-p124"],"v":"b25c39cb"},{"idioma":"fr","id":"fr-v035","tipo":"frase","fr":"Tu as eu de la chance.","aceitasFr":["Vous avez eu de la chance."],"en":"You were lucky.","aceitasEn":["you were lucky","you got lucky","youve been lucky","you have been lucky"],"distratoresEn":["You're lucky.","You used to be lucky.","You'll be lucky.","You'd be lucky."],"formasFr":{"Tu as de la chance":"present","Tu avais de la chance":"imperfect","Tu auras de la chance":"future","Tu aurais de la chance":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular"],"notaEn":"To be lucky is «avoir de la chance», to have (some) luck. The participle of «avoir» is «eu»: «tu as eu», you had.","requerTodas":["fr-p002","fr-p132"],"v":"c84b8a11"},{"idioma":"fr","id":"fr-v036","tipo":"frase","fr":"J'ai dû partir.","en":"I had to leave.","aceitasEn":["i had to leave","i had to go","ive had to leave","i have had to leave"],"distratoresEn":["I have to leave.","I was supposed to leave.","I'll have to leave.","I should leave."],"formasFr":{"Je dois partir":"present","Je devais partir":"imperfect","Je vais devoir partir":"near future","Je devrais partir":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular"],"notaEn":"The participle of «devoir» is «dû», accented to tell it apart from «du». «J'ai dû» is I had to; «je devais», I was supposed to.","requerTodas":["fr-p002","fr-p082","fr-p083"],"v":"ad977898"},{"idioma":"fr","id":"fr-v037","tipo":"frase","fr":"Je n'ai pas pu dormir.","aceitasFr":["J'ai pas pu dormir."],"en":"I couldn't sleep.","aceitasEn":["i couldnt sleep","i could not sleep","i wasnt able to sleep","i was not able to sleep","i havent been able to sleep"],"distratoresEn":["I can't sleep.","I won't be able to sleep.","I wouldn't be able to sleep.","I hadn't been able to sleep."],"formasFr":{"Je ne peux pas dormir":"present","Je ne vais pas pouvoir dormir":"near future","Je ne pourrais pas dormir":"conditional","Je n'avais pas pu dormir":"pluperfect"},"nivel":"A2","tags":["conjugação","pretérito","irregular"],"notaEn":"In a negative passé composé, «ne… pas» wraps the helper verb: «je n'ai pas pu». The participle of «pouvoir» is «pu».","requerTodas":["fr-p002","fr-p006","fr-p109"],"v":"d1221f6b"},{"idioma":"fr","id":"fr-v038","tipo":"frase","fr":"Il n'a rien dit.","aceitasFr":["Il a rien dit."],"en":"He didn't say anything.","aceitasEn":["he didnt say anything","he did not say anything","he said nothing","he didnt say a word","he hasnt said anything"],"distratoresEn":["He doesn't say anything.","He wasn't saying anything.","He won't say anything.","He wouldn't say anything."],"formasFr":{"Il ne dit rien":"present","Il ne disait rien":"imperfect","Il ne dira rien":"future","Il ne dirait rien":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular"],"notaEn":"In the passé composé, «rien» goes before the participle: «il n'a rien dit». «Personne» goes after: «je n'ai vu personne».","requerTodas":["fr-p002","fr-p005"],"v":"fae192b4"},{"idioma":"fr","id":"fr-v039","tipo":"frase","fr":"Tu as lu ce livre ?","aceitasFr":["Vous avez lu ce livre ?"],"en":"Have you read this book?","aceitasEn":["have you read this book","have you read that book","did you read this book","did you read that book"],"distratoresEn":["Are you reading this book?","Did you use to read this book?","Will you read this book?","Would you read this book?"],"formasFr":{"Tu lis ce livre":"present","Tu lisais ce livre":"imperfect","Tu liras ce livre":"future","Tu lirais ce livre":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","irregular","escola"],"notaEn":"The participle of «lire» is «lu», short like «vu», «bu», «su» and «pu».","requerTodas":["fr-p002","fr-p076","fr-p033"],"v":"b5b14641"},{"idioma":"fr","id":"fr-v040","tipo":"frase","fr":"Il pleuvait.","en":"It was raining.","aceitasEn":["it was raining"],"distratoresEn":["It's raining.","It rained.","It's going to rain.","It would rain."],"formasFr":{"Il pleut":"present","Il a plu":"passé composé","Il pleuvra":"future","Il pleuvrait":"conditional"},"nivel":"A2","tags":["conjugação","imperfeito","irregular","natureza"],"notaEn":"The imperfect sets the scene; the passé composé tells what happened in it: «il pleuvait quand je suis sorti», it was raining when I went out. The participle of «pleuvoir» is «plu».","requerTodas":["fr-p171"],"v":"eaa5f362"},{"idioma":"fr","id":"fr-v041","tipo":"frase","fr":"Tu seras un bon père.","en":"You'll be a good father.","aceitasEn":["youll be a good father","you will be a good father","youre going to be a good father","you are going to be a good father","youll be a good dad","youll make a good father"],"distratoresEn":["You're a good father.","You used to be a good father.","You've been a good father.","You would be a good father."],"formasFr":{"Tu es un bon père":"present","Tu étais un bon père":"imperfect","Tu as été un bon père":"passé composé","Tu serais un bon père":"conditional"},"nivel":"A1","tags":["conjugação","futuro","irregular","família"],"notaEn":"Irregular future of «être»: je serai, tu seras, il sera, nous serons, vous serez, ils seront. The endings are those of every future.","requerTodas":["fr-p001","fr-p036","fr-p103"],"v":"f55a3a35"},{"idioma":"fr","id":"fr-v042","tipo":"frase","fr":"On aura le temps.","aceitasFr":["Nous aurons le temps."],"en":"We'll have time.","aceitasEn":["well have time","we will have time","were going to have time","we are going to have time"],"distratoresEn":["We have time.","We used to have time.","We had time.","We'd have time."],"formasFr":{"On a le temps":"present","On avait le temps":"imperfect","On a eu le temps":"passé composé","On aurait le temps":"conditional"},"nivel":"A1","tags":["conjugação","futuro","irregular"],"notaEn":"Irregular future of «avoir»: j'aurai, tu auras, il aura, nous aurons. «On», the casual we, takes the «il» form: «on aura».","requerTodas":["fr-p002","fr-p025"],"v":"a2c90959"},{"idioma":"fr","id":"fr-v043","tipo":"frase","fr":"Il fera chaud.","en":"It'll be hot.","aceitasEn":["itll be hot","it will be hot","its going to be hot","it is going to be hot","itll be warm","it will be warm"],"distratoresEn":["It's hot.","It was hot.","It's been hot.","It would be hot."],"formasFr":{"Il fait chaud":"present","Il faisait chaud":"imperfect","Il a fait chaud":"passé composé","Il ferait chaud":"conditional"},"nivel":"A1","tags":["conjugação","futuro","irregular","natureza"],"notaEn":"Irregular future of «faire»: je ferai, il fera, with «e» instead of «ai». Weather is made: «il fait chaud», «il fera froid».","requerTodas":["fr-p004","fr-p112"],"v":"9de0edb6"},{"idioma":"fr","id":"fr-v044","tipo":"frase","fr":"Tu iras loin.","aceitasFr":["Vous irez loin."],"en":"You'll go far.","aceitasEn":["youll go far","you will go far","youre going to go far","you are going to go far","youll go a long way"],"distratoresEn":["You went far.","You used to go far.","You'd go far.","You had gone far."],"formasFr":{"Tu allais loin":"imperfect","Tu es allé loin":"passé composé","Tu irais loin":"conditional","Tu étais allé loin":"pluperfect"},"nivel":"A2","tags":["conjugação","futuro","irregular"],"notaEn":"In the future, «aller» switches to the stem «ir-»: j'irai, tu iras, il ira. «Aller loin», to go far, means to succeed.","requerTodas":["fr-p003","fr-p164"],"v":"bb19d801"},{"idioma":"fr","id":"fr-v045","tipo":"frase","fr":"Elle viendra avec son mari.","en":"She'll come with her husband.","aceitasEn":["shell come with her husband","she will come with her husband","shes going to come with her husband","she is going to come with her husband"],"distratoresEn":["She used to come with her husband.","She came with her husband.","She would come with her husband.","She had come with her husband."],"formasFr":{"Elle venait avec son mari":"imperfect","Elle est venue avec son mari":"passé composé","Elle viendrait avec son mari":"conditional","Elle était venue avec son mari":"pluperfect"},"nivel":"A2","tags":["conjugação","futuro","irregular","família"],"notaEn":"Future of «venir», with a «d»: je viendrai, elle viendra, ils viendront. «Le mari» is the husband; a wife is «la femme».","requerTodas":["fr-p009","fr-p152"],"v":"5ac459e1"},{"idioma":"fr","id":"fr-v046","tipo":"frase","fr":"Il pourra t'aider.","aceitasFr":["Il pourra vous aider."],"en":"He'll be able to help you.","aceitasEn":["hell be able to help you","he will be able to help you","hell be able to help","he will be able to help"],"distratoresEn":["He can help you.","He used to be able to help you.","He was able to help you.","He could help you."],"formasFr":{"Il peut t'aider":"present","Il pouvait t'aider":"imperfect","Il a pu t'aider":"passé composé","Il pourrait t'aider":"conditional"},"nivel":"A2","tags":["conjugação","futuro","irregular"],"notaEn":"Future of «pouvoir», with a double «r»: je pourrai, il pourra. The conditional, «il pourrait», only changes the ending.","requerTodas":["fr-p006","fr-p111"],"v":"2ed8c445"},{"idioma":"fr","id":"fr-v047","tipo":"frase","fr":"On saura la vérité.","aceitasFr":["Nous saurons la vérité."],"en":"We'll know the truth.","aceitasEn":["well know the truth","we will know the truth","were going to know the truth","well find out the truth","we will find out the truth"],"distratoresEn":["We know the truth.","We used to know the truth.","We found out the truth.","We'd know the truth."],"formasFr":{"On sait la vérité":"present","On savait la vérité":"imperfect","On a su la vérité":"passé composé","On saurait la vérité":"conditional"},"nivel":"A2","tags":["conjugação","futuro","irregular"],"notaEn":"Irregular future of «savoir»: je saurai, tu sauras, on saura. The same «saur-» stem makes the conditional: «on saurait».","requerTodas":["fr-p008","fr-p055"],"v":"f05ad967"},{"idioma":"fr","id":"fr-v048","tipo":"frase","fr":"Tu devras attendre.","aceitasFr":["Vous devrez attendre."],"en":"You'll have to wait.","aceitasEn":["youll have to wait","you will have to wait","youre going to have to wait","you are going to have to wait"],"distratoresEn":["You have to wait.","You were supposed to wait.","You had to wait.","You should wait."],"formasFr":{"Tu dois attendre":"present","Tu devais attendre":"imperfect","Tu as dû attendre":"passé composé","Tu devrais attendre":"conditional"},"nivel":"A2","tags":["conjugação","futuro","irregular"],"notaEn":"Future of «devoir»: je devrai, tu devras. Don't mix it up with the conditional «tu devrais», you should: one letter apart.","requerTodas":["fr-p082","fr-p018"],"v":"5554ec7f"},{"idioma":"fr","id":"fr-v049","tipo":"frase","fr":"J'aimerais voyager.","en":"I'd like to travel.","aceitasEn":["id like to travel","i would like to travel","id love to travel","i would love to travel"],"distratoresEn":["I like to travel.","I liked traveling.","I'll like traveling.","I had liked traveling."],"formasFr":{"J'aime voyager":"present","J'ai aimé voyager":"passé composé","J'aimais voyager":"imperfect","J'avais aimé voyager":"pluperfect"},"nivel":"A2","tags":["conjugação","condicional","regular","viagem"],"notaEn":"The conditional joins the future stem and the imperfect endings: «aimer-» + «-ais». «J'aimerais» is the polite wish, like «je voudrais».","requerTodas":["fr-p015","fr-p183"],"v":"b0d13e00"},{"idioma":"fr","id":"fr-v050","tipo":"frase","fr":"Tu devrais dormir.","aceitasFr":["Vous devriez dormir."],"en":"You should sleep.","aceitasEn":["you should sleep","you ought to sleep","you should get some sleep","you should go to sleep"],"distratoresEn":["You have to sleep.","You were supposed to sleep.","You had to sleep.","You'll have to sleep."],"formasFr":{"Tu dois dormir":"present","Tu devais dormir":"imperfect","Tu as dû dormir":"passé composé","Tu devras dormir":"future"},"nivel":"A2","tags":["conjugação","condicional","irregular","saúde"],"notaEn":"Advice uses the conditional of «devoir»: «tu devrais», you should. Without the middle «r», «tu devais» is the imperfect: you were supposed to.","requerTodas":["fr-p082","fr-p109"],"v":"16616938"},{"idioma":"fr","id":"fr-v051","tipo":"frase","fr":"Je me lève à sept heures.","en":"I get up at seven.","aceitasEn":["i get up at seven","i get up at 7","i get up at seven oclock"],"distratoresEn":["I used to get up at seven.","I got up at seven.","I'll get up at seven.","I would get up at seven."],"formasFr":{"Je me levais à sept heures":"imperfect","Je me suis levé à sept heures":"passé composé","Je vais me lever à sept heures":"near future","Je me lèverais à sept heures":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular","pronomes","cotidiano"],"notaEn":"A reflexive verb: «je me lève», «tu te lèves», «nous nous levons». The «e» takes a grave accent before a silent ending. To wake up is «se réveiller».","requerTodas":["fr-p177","fr-p178","fr-p129"],"v":"36930868"},{"idioma":"fr","id":"fr-v052","tipo":"frase","fr":"Le bébé s'appellera Louis.","en":"The baby will be called Louis.","aceitasEn":["the baby will be called louis","the baby will be named louis","the baby is going to be called louis","the baby is going to be named louis"],"distratoresEn":["The baby is called Louis.","The baby used to be called Louis.","The baby was called Louis.","The baby would be called Louis."],"formasFr":{"Le bébé s'appelle Louis":"present","Le bébé s'appelait Louis":"imperfect","Le bébé s'est appelé Louis":"passé composé","Le bébé s'appellerait Louis":"conditional"},"nivel":"A2","tags":["conjugação","futuro","regular","pronomes","família"],"notaEn":"«S'appeler» doubles the «l» before a silent ending: «il s'appelle», «il s'appellera», but «nous nous appelons». «Louis» sounds like «lwee».","requerTodas":["fr-p147","fr-p175"],"v":"0d31f220"},{"idioma":"fr","id":"fr-v053","tipo":"frase","fr":"Les enfants se couchent tôt.","en":"The children go to bed early.","aceitasEn":["the children go to bed early","the kids go to bed early"],"distratoresEn":["The children used to go to bed early.","The children went to bed early.","The children will go to bed early.","The children would go to bed early."],"formasFr":{"Les enfants se couchaient tôt":"imperfect","Les enfants se sont couchés tôt":"passé composé","Les enfants se coucheront tôt":"future","Les enfants se coucheraient tôt":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular","pronomes","casa"],"notaEn":"«Se coucher» is to go to bed; sleeping is «dormir». In the passé composé every reflexive verb takes «être»: «ils se sont couchés».","requerTodas":["fr-p023","fr-p176","fr-p181"],"v":"b246ffa6"},{"idioma":"fr","id":"fr-v054","tipo":"frase","fr":"Je n'ai pas mangé à midi.","aceitasFr":["J'ai pas mangé à midi."],"en":"I didn't eat at noon.","aceitasEn":["i didnt eat at noon","i did not eat at noon","i didnt have lunch","i didnt eat lunch","i skipped lunch"],"distratoresEn":["I don't eat at noon.","I didn't use to eat at noon.","I won't eat at noon.","I wouldn't eat at noon."],"formasFr":{"Je ne mange pas à midi":"present","Je ne mangeais pas à midi":"imperfect","Je ne vais pas manger à midi":"near future","Je ne mangerais pas à midi":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","comida"],"notaEn":"In a negative passé composé, «ne… pas» wraps only the helper verb, leaving the participle outside: «je n'ai pas mangé».","requerTodas":["fr-p002","fr-p013","fr-p064"],"v":"9126ed63"},{"idioma":"fr","id":"fr-p115","tipo":"palavra","fr":"arriver","en":"to arrive / to happen","aceitasEn":["to arrive","arrive","to get","to happen","happen"],"distratoresEn":["to arrange / to tidy","to risk / to dare","to drag / to pull","to leave / to go away"],"nivel":"A1","tags":["verbo","viagem"],"notaEn":"To arrive, and also to happen: «qu'est-ce qui est arrivé ?», what happened? With «à» it means to manage: «je n'arrive pas à dormir», I can't get to sleep. It takes «être» in the passé composé.","v":"ef1d0f8a","pos":37},{"idioma":"fr","id":"fr-p116","tipo":"palavra","fr":"brésilien","aceitasFr":["brésilienne"],"en":"Brazilian","aceitasEn":["brazilian"],"distratoresEn":["Portuguese","Argentine","Bolivian","Paraguayan"],"nivel":"A1","tags":["adjetivo","cultura"],"notaEn":"Feminine «brésilienne», with a double «n». Lowercase; only the people are capitalized: «les Brésiliens». Brazil is «le Brésil», with the article.","v":"dab6dcc8","pos":4338},{"idioma":"fr","id":"fr-p117","tipo":"palavra","fr":"casser","en":"to break","aceitasEn":["to break","break","to smash"],"distratoresEn":["to cash","to marry","to hunt","to fix"],"nivel":"A2","tags":["verbo","casa"],"notaEn":"To break: «j'ai cassé un verre», I broke a glass; «se casser la jambe», to break your leg. Nothing to do with cash, which is «les espèces».","v":"1afce86c","pos":749},{"idioma":"fr","id":"fr-p118","tipo":"palavra","fr":"chercher","en":"to look for","aceitasEn":["to look for","look for","to search","search","to search for","search for","to seek","to fetch"],"distratoresEn":["to find","to smell","to arrive","to check"],"nivel":"A1","tags":["verbo"],"notaEn":"To look for, with no preposition: «je cherche mes clés», I'm looking for my keys. «Aller chercher» is to go and get: «je vais chercher le pain». To find is «trouver».","v":"13e0e8a1","pos":79},{"idioma":"fr","id":"fr-p119","tipo":"palavra","fr":"connaître","en":"to know (people, places)","aceitasEn":["to know","know","to be familiar with","to be acquainted with"],"distratoresEn":["to connect (two things)","to count (numbers)","to conquer (a land)","to consent (agree)"],"nivel":"A1","tags":["verbo","social"],"notaEn":"To know a person or a place: «je connais Paris». Knowing a fact, or how to do something, is «savoir». Forms: je connais, il connaît, nous connaissons; participle «connu».","v":"39919da3","pos":60},{"idioma":"fr","id":"fr-p120","tipo":"palavra","fr":"deux","en":"two","aceitasEn":["two","2"],"distratoresEn":["twelve","ten","six","eleven"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The «x» is silent, except before a vowel, where it sounds like «z»: «deux amis». Twelve is «douze».","v":"bc2e8495","pos":439},{"idioma":"fr","id":"fr-p121","tipo":"palavra","fr":"dix","en":"ten","aceitasEn":["ten","10"],"distratoresEn":["two","twelve","six","nine"],"nivel":"A1","tags":["cotidiano"],"notaEn":"On its own it sounds like «deess». Before a consonant the «x» goes silent: «dix livres»; before a vowel it sounds like «z»: «dix euros».","v":"ac1f42fb","pos":313},{"idioma":"fr","id":"fr-p122","tipo":"palavra","fr":"falloir","en":"to be necessary","aceitasEn":["to be necessary","be necessary","must","to have to","to need"],"distratoresEn":["to fail","to fall","to be worth","to follow"],"nivel":"A1","tags":["verbo","gramática"],"notaEn":"Only used with an impersonal «il»: «il faut partir», we have to go, one must go. Past «il a fallu»; future «il faudra».","v":"025c2cf5","pos":31},{"idioma":"fr","id":"fr-p123","tipo":"palavra","fr":"finir","en":"to finish","aceitasEn":["to finish","finish","to end","end"],"distratoresEn":["to pretend","to sign","to fix","to start"],"nivel":"A1","tags":["verbo"],"notaEn":"The model for «-ir» verbs that add «-iss-» in the plural: je finis, nous finissons, ils finissent; participle «fini». To pretend is «faire semblant».","v":"2b0aef5d","pos":135},{"idioma":"fr","id":"fr-p124","tipo":"palavra","fr":"gentil","aceitasFr":["gentille"],"en":"kind","aceitasEn":["nice","sweet"],"distratoresEn":["brilliant","rude","frozen","fat"],"nivel":"A1","tags":["adjetivo","social"],"notaEn":"Feminine «gentille». Kind, nice: «c'est gentil !», that's so kind! For children, well-behaved. Gentle is «doux».","v":"81a97026","pos":448},{"idioma":"fr","id":"fr-p125","tipo":"palavra","fr":"hier","en":"yesterday","aceitasEn":["yesterday"],"distratoresEn":["here","today","tomorrow","now"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The «h» is silent. «Hier soir», last night. The day before yesterday is «avant-hier».","v":"cc71aa1f","pos":355},{"idioma":"fr","id":"fr-p126","tipo":"palavra","fr":"huit","en":"eight","aceitasEn":["eight","8"],"distratoresEn":["eighty","four","eighteen","nine"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Sounds like «weet»; before a consonant the «t» goes silent: «huit livres». «Dans huit jours», in a week.","v":"11bf7078","pos":152},{"idioma":"fr","id":"fr-p127","tipo":"palavra","fr":"l'attention","en":"attention","aceitasEn":["attention","the attention","care"],"distratoresEn":["tension","intention","temptation","attempt"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine. «Faire attention», to pay attention, to be careful; on its own, «Attention !» means watch out!","v":"23c20588","transp":"total","pos":339},{"idioma":"fr","id":"fr-p128","tipo":"palavra","fr":"l'euro","aceitasFr":["un euro"],"en":"the euro","aceitasEn":["euro","the euro"],"distratoresEn":["the dollar","the cent","the pound","the yen"],"nivel":"A1","tags":["compras","economia"],"notaEn":"Masculine, linked in the plural: «dix euros», «dee-zuh-ROH». A cent is «le centime».","v":"cef20a51","transp":"total","pos":1516},{"idioma":"fr","id":"fr-p129","tipo":"palavra","fr":"l'heure","aceitasFr":["une heure"],"en":"the hour","aceitasEn":["hour","the hour","time","the time","o'clock"],"distratoresEn":["the minute","the honor","the week","the hair"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine, with a silent «h». In clock times it is never dropped: «à six heures», at six o'clock. «Quelle heure est-il ?», what time is it?","v":"294ad81b","pos":61},{"idioma":"fr","id":"fr-p130","tipo":"palavra","fr":"l'âge","en":"age","aceitasEn":["age","the age"],"distratoresEn":["height","weight","agenda","edge"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Masculine: «quel âge as-tu ?», how old are you? Age is something you have: «j'ai vingt ans», I'm twenty.","v":"0b4bf45c","transp":"total","pos":372},{"idioma":"fr","id":"fr-p131","tipo":"palavra","fr":"la carte","en":"the card / the map","aceitasEn":["card","the card","map","the map","menu","the menu"],"distratoresEn":["the cart / the trolley","the letter / the envelope","the poster / the sign","the bill / the receipt"],"nivel":"A1","tags":["compras","falso-amigo"],"notaEn":"A card, a map or a menu: «payer par carte», to pay by card; «à la carte». A cart is «un chariot», and a letter in the mail is «une lettre».","v":"c75e35cf","pos":330},{"idioma":"fr","id":"fr-p132","tipo":"palavra","fr":"la chance","en":"luck","aceitasEn":["luck","the luck","fortune"],"distratoresEn":["flame","dance","calm","misfortune"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Luck: «avoir de la chance», to be lucky; «bonne chance !», good luck! A chance in the sense of an opportunity is usually «l'occasion».","v":"8fa43934","pos":272},{"idioma":"fr","id":"fr-p133","tipo":"palavra","fr":"la clé","aceitasFr":["la clef"],"en":"the key","aceitasEn":["key","the key"],"distratoresEn":["the lock","the door","the clay","the padlock"],"nivel":"A1","tags":["casa"],"notaEn":"Also spelled «la clef», pronounced the same. «Fermer à clé», to lock. The lock itself is «la serrure».","v":"2af52afc","pos":674},{"idioma":"fr","id":"fr-p134","tipo":"palavra","fr":"la douche","en":"the shower","aceitasEn":["shower","the shower"],"distratoresEn":["the bath","the sink","the candy","the towel"],"nivel":"A1","tags":["casa"],"notaEn":"Feminine. You take it, as in English: «prendre une douche». A bath is «un bain».","v":"4a12b73d","pos":1398},{"idioma":"fr","id":"fr-p135","tipo":"palavra","fr":"la fenêtre","en":"the window","aceitasEn":["window","the window"],"distratoresEn":["the door","the wall","the crack","the curtain"],"nivel":"A1","tags":["casa"],"notaEn":"Feminine. The circumflex marks a lost «s»: it comes from Latin «fenestra», as in «defenestrate».","v":"48f1f1fa","pos":496},{"idioma":"fr","id":"fr-p136","tipo":"palavra","fr":"la grand-mère","en":"the grandmother","aceitasEn":["grandmother","the grandmother","grandma","granny"],"distratoresEn":["the aunt","the godmother","the mother-in-law","the granddaughter"],"nivel":"A1","tags":["família"],"notaEn":"Hyphenated, and «grand» takes no feminine «e»: «ma grand-mère». Grandma is «mamie»; grandfather, «le grand-père».","v":"4a45897e","pos":949},{"idioma":"fr","id":"fr-p137","tipo":"palavra","fr":"la journée","en":"the day (as a whole)","aceitasEn":["day","the day","daytime","the daytime"],"distratoresEn":["the journey (a long trip)","the night (as a whole)","the newspaper (a daily)","the knee (a joint)"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine. The day as you live it, from morning to night: «toute la journée», all day; «bonne journée !». A calendar day is «le jour», and a journey is «un voyage».","v":"c710b13b","pos":241},{"idioma":"fr","id":"fr-p138","tipo":"palavra","fr":"la lettre","en":"the letter","aceitasEn":["letter","the letter"],"distratoresEn":["the card","the reading","the liter","the stamp"],"nivel":"A1","tags":["cotidiano","escola"],"notaEn":"Both a letter you mail and a letter of the alphabet: «écrire une lettre», «la lettre A». A card is «la carte».","v":"e7a1efc9","pos":376},{"idioma":"fr","id":"fr-p139","tipo":"palavra","fr":"la minute","en":"the minute","aceitasEn":["minute","the minute"],"distratoresEn":["the second","the minimum","the mine","the month"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine: «une minute», «vingt minutes». «Une minute !», just a minute!","v":"5d848b4e","transp":"total","pos":187},{"idioma":"fr","id":"fr-p140","tipo":"palavra","fr":"la question","en":"the question","aceitasEn":["question","the question"],"distratoresEn":["the answer","the complaint","the amount","the quest"],"nivel":"A1","tags":["escola"],"notaEn":"A question, and also a matter: «c'est une question de temps», it's a matter of time. To ask one is «poser une question».","v":"885381ca","transp":"total","pos":109},{"idioma":"fr","id":"fr-p141","tipo":"palavra","fr":"la raison","en":"the reason","aceitasEn":["reason","the reason"],"distratoresEn":["the raisin","the ration","the reaction","the region"],"nivel":"A1","tags":["cotidiano"],"notaEn":"French «has» it: «tu as raison», you're right; «avoir tort», to be wrong. A raisin is «un raisin sec»; «le raisin» is the grape.","v":"c752c68a","pos":129},{"idioma":"fr","id":"fr-p142","tipo":"palavra","fr":"la robe","en":"the dress","aceitasEn":["dress","the dress"],"distratoresEn":["the robe","the skirt","the blouse","the clothes"],"nivel":"A1","tags":["roupa","falso-amigo"],"notaEn":"Not a robe: it's a dress. A bathrobe is «le peignoir»; clothes in general are «les vêtements».","v":"f25a80ff","pos":2175},{"idioma":"fr","id":"fr-p143","tipo":"palavra","fr":"la table","en":"the table","aceitasEn":["table","the table"],"distratoresEn":["the chair","the tablecloth","the bed","the shelf"],"nivel":"A1","tags":["casa","comida"],"notaEn":"«Mettre la table», to set the table; «à table !», dinner's ready! «La table des matières» is the table of contents.","v":"bb56191b","transp":"total","pos":409},{"idioma":"fr","id":"fr-p144","tipo":"palavra","fr":"la tête","en":"the head","aceitasEn":["head","the head"],"distratoresEn":["the forehead","the ceiling","the chest","the neck"],"nivel":"A1","tags":["corpo"],"notaEn":"From Latin «testa»; the circumflex marks a lost «s». «J'ai mal à la tête», I have a headache. The forehead is «le front».","v":"389e1fd4","pos":113},{"idioma":"fr","id":"fr-p145","tipo":"palavra","fr":"la vaisselle","en":"the dishes","aceitasEn":["dishes","the dishes","dishware","crockery"],"distratoresEn":["the vase","the broom","the laundry","the tablecloth"],"nivel":"A2","tags":["casa"],"notaEn":"Feminine and singular, for all the dishes at once. «Faire la vaisselle», to do the dishes.","v":"db4d1b28","pos":3232},{"idioma":"fr","id":"fr-p146","tipo":"palavra","fr":"le besoin","en":"the need","aceitasEn":["need","the need"],"distratoresEn":["the desire","the wish","the duty","the bison"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Masculine. Almost always with «avoir»: «j'ai besoin de toi», I need you. Feeling like something is «avoir envie de».","v":"bffd22e9","pos":102},{"idioma":"fr","id":"fr-p147","tipo":"palavra","fr":"le bébé","en":"the baby","aceitasEn":["baby","the baby"],"distratoresEn":["the drink","the crib","the doll","the calf"],"nivel":"A1","tags":["família"],"notaEn":"Masculine even for a girl: «c'est un beau bébé». Two acute accents: «bébé».","v":"e4da68f7","pos":853},{"idioma":"fr","id":"fr-p148","tipo":"palavra","fr":"le cours","en":"the class / the course","aceitasEn":["class","the class","course","the course","lesson","the lesson"],"distratoresEn":["the yard / the courtyard","the race / the run","the body / the trunk","the test / the exam"],"nivel":"A1","tags":["escola"],"notaEn":"Masculine, with an «s» even in the singular: «un cours de français», a French class. It sounds just like «la cour», the courtyard, and «le corps», the body.","v":"c54c30c3","pos":594},{"idioma":"fr","id":"fr-p149","tipo":"palavra","fr":"le foot","aceitasFr":["le football"],"en":"soccer","aceitasEn":["soccer","football"],"distratoresEn":["foot","basketball","volleyball","tennis"],"nivel":"A1","tags":["cultura"],"notaEn":"Short for «le football», and that's what everyone says. Played with «à»: «jouer au foot». A foot is «un pied».","v":"a75e01ff","pos":1838},{"idioma":"fr","id":"fr-p150","tipo":"palavra","fr":"le gâteau","en":"the cake","aceitasEn":["cake","the cake"],"distratoresEn":["the cat","the pie","the bread","the ice cream"],"nivel":"A1","tags":["comida"],"notaEn":"Plural with «x»: «les gâteaux». Cookies are «les petits gâteaux» or «les biscuits».","v":"ce1ec5d9","pos":1063},{"idioma":"fr","id":"fr-p151","tipo":"palavra","fr":"le mal","en":"pain / evil","aceitasEn":["pain","the pain","ache","evil","harm","difficulty"],"distratoresEn":["good / virtue","suitcase / bag","fear / fright","hunger / thirst"],"nivel":"A1","tags":["saúde","corpo"],"notaEn":"Pain is something you have: «avoir mal à» plus the body part, «j'ai mal au dos», my back hurts. It is also evil, and difficulty: «j'ai du mal à dormir», I have trouble sleeping.","v":"7051eff9","pos":180},{"idioma":"fr","id":"fr-p152","tipo":"palavra","fr":"le mari","en":"the husband","aceitasEn":["husband","the husband"],"distratoresEn":["the groom","the boyfriend","the sailor","the father-in-law"],"nivel":"A1","tags":["família"],"notaEn":"«Mon mari», my husband; a wife is «ma femme». The groom on the wedding day is «le marié».","v":"ef0a7f3a","pos":214},{"idioma":"fr","id":"fr-p153","tipo":"palavra","fr":"le matin","en":"the morning","aceitasEn":["morning","the morning"],"distratoresEn":["the afternoon","the evening","the dawn","the matinee"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Le matin», with the article, means in the morning, every day: «je cours le matin». A whole morning is «la matinée».","v":"725a28c5","pos":169},{"idioma":"fr","id":"fr-p154","tipo":"palavra","fr":"le monde","en":"the world / people","aceitasEn":["world","the world","people"],"distratoresEn":["the mountain / the hill","the coin / the change","the way / the manner","the month / the week"],"nivel":"A1","tags":["social"],"notaEn":"The world and, in everyday speech, people: «tout le monde», everyone; «il y a du monde», it's crowded.","v":"c0072a38","pos":48},{"idioma":"fr","id":"fr-p155","tipo":"palavra","fr":"le médecin","en":"the doctor","aceitasEn":["doctor","the doctor","physician","the physician"],"distratoresEn":["the medicine","the nurse","the dentist","the patient"],"nivel":"A1","tags":["saúde","profissões"],"notaEn":"Used for men and women alike: «elle est médecin», she's a doctor. Medicine as a field is «la médecine»; a drug is «le médicament».","v":"0d00ade9","pos":452},{"idioma":"fr","id":"fr-p156","tipo":"palavra","fr":"le petit déjeuner","en":"breakfast","aceitasEn":["breakfast","the breakfast"],"distratoresEn":["lunch","dinner","a snack","an appetizer"],"nivel":"A1","tags":["comida"],"notaEn":"Literally little lunch: «le déjeuner» is lunch, and «le dîner» is dinner. You «take» it: «prendre le petit déjeuner». In Quebec, «le déjeuner» is breakfast.","v":"6e202d54","pos":874},{"idioma":"fr","id":"fr-p157","tipo":"palavra","fr":"le piano","en":"the piano","aceitasEn":["piano","the piano"],"distratoresEn":["the guitar","the violin","the organ","the tambourine"],"nivel":"A1","tags":["cultura"],"notaEn":"Played with «jouer de»: «jouer du piano», to play the piano.","v":"625ee355","transp":"total","pos":1925},{"idioma":"fr","id":"fr-p158","tipo":"palavra","fr":"le pied","en":"the foot","aceitasEn":["foot","the foot"],"distratoresEn":["the leg","the hand","the knee","the chest"],"nivel":"A1","tags":["corpo"],"notaEn":"The final «d» is silent. «À pied», on foot: «je vais au travail à pied», I walk to work.","v":"a7a5bda9","pos":267},{"idioma":"fr","id":"fr-p159","tipo":"palavra","fr":"le samedi","aceitasFr":["samedi"],"en":"Saturday","aceitasEn":["saturday"],"distratoresEn":["Sunday","Friday","Thursday","Tuesday"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Without the article it's one Saturday: «samedi», on Saturday. With it, every Saturday: «le samedi». Lowercase.","v":"60cdc098","pos":1003},{"idioma":"fr","id":"fr-p160","tipo":"palavra","fr":"le soir","en":"the evening","aceitasEn":["evening","the evening"],"distratoresEn":["the afternoon","the morning","the dawn","the weekend"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The evening, until bedtime: «ce soir», tonight; «bonsoir», good evening. The night you sleep through is «la nuit».","v":"91d82d97","pos":87},{"idioma":"fr","id":"fr-p161","tipo":"palavra","fr":"le sport","en":"sport","aceitasEn":["sport","sports","the sport"],"distratoresEn":["port","support","transport","passport"],"nivel":"A1","tags":["cultura","saúde"],"notaEn":"The final «t» is silent. «Faire du sport», to play sports or work out, with the partitive.","v":"4d76c67b","transp":"total","pos":899},{"idioma":"fr","id":"fr-p162","tipo":"palavra","fr":"les courses","en":"the shopping","aceitasEn":["shopping","the shopping","groceries","the groceries","grocery shopping"],"distratoresEn":["the classes","the bills","the colors","the chores"],"nivel":"A1","tags":["compras"],"notaEn":"Everyday shopping, mostly groceries: «faire les courses», to do the shopping. In the singular, «la course» is a race or a run.","v":"27a33324","pos":1948},{"idioma":"fr","id":"fr-p163","tipo":"palavra","fr":"les vacances","en":"vacation","aceitasEn":["vacation","the vacation","vacations","holidays","the holidays","holiday"],"distratoresEn":["vacancies","fairs","parties","trips"],"nivel":"A1","tags":["viagem"],"notaEn":"Always plural in this sense: «partir en vacances», to go on vacation (British: on holiday). Summer vacation is «les grandes vacances».","v":"e785754f","pos":618},{"idioma":"fr","id":"fr-p164","tipo":"palavra","fr":"loin","en":"far","aceitasEn":["far","far away"],"distratoresEn":["near","slow","soon","deep"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Loin de», far from: «c'est loin d'ici ?», is it far from here? Near is «près».","v":"d8945603","pos":204},{"idioma":"fr","id":"fr-p165","tipo":"palavra","fr":"là","en":"there","aceitasEn":["there","over there","here"],"distratoresEn":["far","near","like this","inside"],"nivel":"A1","tags":["cotidiano"],"notaEn":"There, and in everyday speech also here: «je suis là», I'm here; «il n'est pas là», he's not in. The accent sets it apart from the article «la».","v":"d6194272","pos":20},{"idioma":"fr","id":"fr-p166","tipo":"palavra","fr":"malade","en":"sick","aceitasEn":["sick","ill"],"distratoresEn":["evil","crazy","tired","injured"],"nivel":"A1","tags":["adjetivo","saúde"],"notaEn":"Same form for masculine and feminine: «il est malade», «elle est malade». An illness is «la maladie», like English «malady».","v":"4b4312f5","pos":621},{"idioma":"fr","id":"fr-p167","tipo":"palavra","fr":"mettre","en":"to put","aceitasEn":["to put","put","to place","to put on","put on"],"distratoresEn":["to meet","to measure","to kill","to remove"],"nivel":"A1","tags":["verbo"],"notaEn":"To put, and also to put on clothes: «mettre un manteau». Irregular: je mets, nous mettons; participle «mis».","v":"61232edf","pos":44},{"idioma":"fr","id":"fr-p168","tipo":"palavra","fr":"mourir","en":"to die","aceitasEn":["to die","die","to pass away"],"distratoresEn":["to live","to be born","to move","to murmur"],"nivel":"A2","tags":["verbo"],"notaEn":"It takes «être», with an irregular participle: «il est mort», he died. The stem changes in the present: je meurs, nous mourons.","v":"562f7109","pos":104},{"idioma":"fr","id":"fr-p169","tipo":"palavra","fr":"ouvrir","en":"to open","aceitasEn":["to open","open"],"distratoresEn":["to hear","to close","to cover","to offer"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"Conjugated like an «-er» verb in the present (j'ouvre, il ouvre); past participle «ouvert». «Offrir» and «couvrir» work the same way.","v":"318c9992","pos":166},{"idioma":"fr","id":"fr-p170","tipo":"palavra","fr":"payer","en":"to pay","aceitasEn":["to pay","pay","to pay for","pay for"],"distratoresEn":["to weigh","to charge","to spend","to borrow"],"nivel":"A1","tags":["verbo","compras"],"notaEn":"No «for»: «payer le café», to pay for the coffee. Both «je paie» and «je paye» are correct.","v":"7a07a6cb","pos":548},{"idioma":"fr","id":"fr-p171","tipo":"palavra","fr":"pleuvoir","en":"to rain","aceitasEn":["to rain","rain"],"distratoresEn":["to cry","to snow","to thunder","to blow"],"nivel":"A1","tags":["verbo","natureza"],"notaEn":"Only with «il»: «il pleut», it's raining; participle «plu». Don't mix it up with «pleurer», to cry.","v":"652da57e","pos":1444},{"idioma":"fr","id":"fr-p172","tipo":"palavra","fr":"regarder","en":"to look at / to watch","aceitasEn":["to look","look","to look at","look at","to watch","watch"],"distratoresEn":["to guard / to keep","to remember / to recall","to hear / to listen","to search / to seek"],"nivel":"A1","tags":["verbo"],"notaEn":"To look at and to watch, with no preposition: «regarde-moi», look at me; «regarder la télé», to watch TV. To see is «voir».","v":"fc310df9","pos":43},{"idioma":"fr","id":"fr-p173","tipo":"palavra","fr":"rouge","en":"red","aceitasEn":["red"],"distratoresEn":["purple","pink","orange","rough"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Same form for masculine and feminine. Red wine is «vin rouge»; lipstick, «le rouge à lèvres».","v":"66d1a20b","pos":498},{"idioma":"fr","id":"fr-p174","tipo":"palavra","fr":"réserver","en":"to book","aceitasEn":["to book","to reserve","reserve"],"distratoresEn":["to solve","to reveal","to receive","to cancel"],"nivel":"A1","tags":["verbo","viagem"],"notaEn":"For tables, rooms and tickets: «réserver une table». A booking is «la réservation».","v":"50879dd3","pos":1043},{"idioma":"fr","id":"fr-p175","tipo":"palavra","fr":"s'appeler","en":"to be called","aceitasEn":["to be called","be called","to be named","be named"],"distratoresEn":["to appeal","to keep quiet","to remember","to complain"],"nivel":"A1","tags":["verbo","social"],"notaEn":"The «l» doubles before a silent ending: je m'appelle, il s'appelle, but nous nous appelons. Without the pronoun, «appeler» means to call.","v":"b49d93fb","pos":53},{"idioma":"fr","id":"fr-p176","tipo":"palavra","fr":"se coucher","en":"to go to bed","aceitasEn":["to go to bed","go to bed","to lie down","lie down"],"distratoresEn":["to get up","to sit down","to hide","to get dressed"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"To go to bed or lie down; actually sleeping is «dormir». The sun «se couche» too: it sets. Past tense with «être»: «ils se sont couchés».","v":"7c2d8277","pos":387},{"idioma":"fr","id":"fr-p177","tipo":"palavra","fr":"se lever","en":"to get up","aceitasEn":["to get up","get up","to stand up","stand up","to rise"],"distratoresEn":["to go to bed","to wake up","to sit down","to wash up"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"Out of bed or out of a chair: «je me lève à sept heures». Waking up is a different verb, «se réveiller». The «e» takes a grave accent before a silent ending: «je me lève», but «nous nous levons».","v":"5efcae60","pos":308},{"idioma":"fr","id":"fr-p178","tipo":"palavra","fr":"sept","en":"seven","aceitasEn":["seven","7"],"distratoresEn":["seventy","six","seventeen","eight"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The «p» is silent and the «t» is heard: «set». In September, «septembre», the «p» is pronounced.","v":"f715b47e","pos":4181},{"idioma":"fr","id":"fr-p179","tipo":"palavra","fr":"six","en":"six","aceitasEn":["six","6"],"distratoresEn":["seven","ten","sixteen","sixty"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Like «dix»: on its own it sounds like «seess»; before a consonant the «x» goes silent («six livres»); before a vowel it sounds like «z» («six heures»).","v":"9e4ede42","transp":"total","pos":706},{"idioma":"fr","id":"fr-p180","tipo":"palavra","fr":"tard","en":"late","aceitasEn":["late"],"distratoresEn":["early","soon","slow","before"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The adverb: «je suis rentré tard», I got home late. «Plus tard», later. Being late for something is «être en retard».","v":"27f63f4b","pos":137},{"idioma":"fr","id":"fr-p181","tipo":"palavra","fr":"tôt","en":"early","aceitasEn":["early"],"distratoresEn":["late","all","near","slowly"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Early: «je me lève tôt», I get up early. «Tôt ou tard», sooner or later; «plus tôt», earlier.","v":"c966c2bc","pos":461},{"idioma":"fr","id":"fr-p182","tipo":"palavra","fr":"vendre","en":"to sell","aceitasEn":["to sell","sell"],"distratoresEn":["to win","to lend","to buy","to rent"],"nivel":"A1","tags":["verbo","compras"],"notaEn":"Conjugated like «attendre»: je vends, il vend, nous vendons; participle «vendu». «À vendre», for sale.","v":"cc0aad29","pos":333},{"idioma":"fr","id":"fr-p183","tipo":"palavra","fr":"voyager","en":"to travel","aceitasEn":["to travel","travel"],"distratoresEn":["to watch over","to fly","to wander","to visit"],"nivel":"A1","tags":["verbo","viagem"],"notaEn":"Like «manger», it adds an «e» in «nous voyageons». A trip is «le voyage»: «bon voyage !».","v":"d42d9165","pos":911},{"idioma":"fr","id":"fr-p184","tipo":"palavra","fr":"écrire","en":"to write","aceitasEn":["to write","write"],"distratoresEn":["to choose","to listen","to hide","to read"],"nivel":"A1","tags":["verbo","escola"],"notaEn":"The initial «é» marks a lost «s», as in «scribe». Irregular: j'écris, nous écrivons; participle «écrit».","v":"849bda16","pos":168},{"idioma":"fr","id":"fr-p185","tipo":"palavra","fr":"le lit","en":"the bed","aceitasEn":["bed","the bed"],"distratoresEn":["the list","the hammock","the pillow","the chair"],"nivel":"A1","tags":["casa"],"notaEn":"The «t» is silent: «lee». «Aller au lit», to go to bed. A riverbed is «le lit» too.","v":"ae176e13","pos":349},{"idioma":"fr","id":"fr-p186","tipo":"palavra","fr":"la porte","en":"the door","aceitasEn":["door","the door"],"distratoresEn":["the port","the wall","the window","the bridge"],"nivel":"A1","tags":["casa"],"notaEn":"Feminine. «Fermer la porte», to close the door. A port is «le port»; the verb «porter» means to carry or wear.","v":"958d3216","pos":132},{"idioma":"fr","id":"fr-p187","tipo":"palavra","fr":"le chat","en":"the cat","aceitasEn":["cat","the cat"],"distratoresEn":["the dog","the mouse","the duck","the hat"],"nivel":"A1","tags":["animais"],"notaEn":"The «t» is silent: «shah». A kitten is «le chaton».","v":"94837d9c","pos":655},{"idioma":"fr","id":"fr-p188","tipo":"palavra","fr":"la gare","en":"the train station","aceitasEn":["train station","the station","station","the railway station","railway station"],"distratoresEn":["the garage","the season","the airport","the bus stop"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"Feminine. A train station; a subway station is «la station». «La gare routière», the bus station.","v":"c4d5b8e5","pos":1301},{"idioma":"fr","id":"fr-p189","tipo":"palavra","fr":"le lait","en":"milk","aceitasEn":["milk","the milk"],"distratoresEn":["cheese","juice","yogurt","lake"],"nivel":"A1","tags":["comida"],"notaEn":"The final «t» is silent. «Un café au lait», a coffee with milk.","v":"7aa7dbd5","pos":1191},{"idioma":"fr","id":"fr-p190","tipo":"palavra","fr":"la semaine","en":"the week","aceitasEn":["week","the week"],"distratoresEn":["the seed","the fortnight","the session","the season"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«La semaine prochaine», next week; «en semaine», on weekdays. The weekend is «le week-end».","v":"bb7dd311","pos":165},{"idioma":"fr","id":"fr-p191","tipo":"palavra","fr":"la main","en":"the hand","aceitasEn":["hand","the hand"],"distratoresEn":["the arm","the finger","the sleeve","the mane"],"nivel":"A1","tags":["corpo"],"notaEn":"Feminine. «À la main», by hand; «se serrer la main», to shake hands.","v":"3f94ae8b","pos":99},{"idioma":"fr","id":"fr-p192","tipo":"palavra","fr":"le prix","en":"the price / the prize","aceitasEn":["price","the price","prize","the prize","the award"],"distratoresEn":["the prison / the jail","the deadline / the date","the rush / the hurry","the change / the bill"],"nivel":"A1","tags":["compras"],"notaEn":"Both price and prize: «le prix du pain», «le prix Nobel». The «x» is silent, and the plural is the same: «les prix».","v":"964ea02a","pos":406},{"idioma":"fr","id":"fr-p193","tipo":"palavra","fr":"trouver","en":"to find","aceitasEn":["to find","find"],"distratoresEn":["to trade","to trip","to bring","to lose"],"nivel":"A1","tags":["verbo"],"notaEn":"To find: «j'ai trouvé mes clés». Also for opinions: «je trouve que c'est cher», I find it expensive. To look for is «chercher».","v":"8056b24c","pos":27},{"idioma":"fr","id":"fr-p194","tipo":"palavra","fr":"demander","en":"to ask / to ask for","aceitasEn":["to ask","ask","to ask for","ask for"],"distratoresEn":["to send / to order","to answer / to reply","to give / to offer","to delay / to linger"],"nivel":"A1","tags":["verbo"],"notaEn":"Both to ask and to ask for: «demander l'addition», to ask for the check; «demander l'heure», to ask the time. To demand forcefully is «exiger».","v":"1b9abe50","pos":52},{"idioma":"fr","id":"fr-p195","tipo":"palavra","fr":"donner","en":"to give","aceitasEn":["to give","give","to hand","to donate"],"distratoresEn":["to dominate","to tame","to take","to fold"],"nivel":"A1","tags":["verbo"],"notaEn":"Regular «-er» verb: je donne, nous donnons. «Donner sur», to look out onto: «la chambre donne sur la mer», the room faces the sea.","v":"a57a8a48","pos":34},{"idioma":"fr","id":"fr-p196","tipo":"palavra","fr":"commencer","en":"to begin","aceitasEn":["to begin","begin","to start","start"],"distratoresEn":["to comment","to trade","to combine","to finish"],"nivel":"A1","tags":["verbo"],"notaEn":"The «c» takes a cedilla before «a» and «o»: «nous commençons». Before an infinitive, use «à»: «il commence à pleuvoir», it's starting to rain.","v":"6eeceead","pos":101},{"idioma":"fr","id":"fr-p197","tipo":"palavra","fr":"oublier","en":"to forget","aceitasEn":["to forget","forget"],"distratoresEn":["to oblige","to obey","to remember","to publish"],"nivel":"A1","tags":["verbo"],"notaEn":"Things come straight after it: «j'ai oublié mes clés», I forgot my keys. Before an infinitive, «de»: «j'ai oublié de payer», I forgot to pay.","v":"a5ce69bc","pos":159},{"idioma":"fr","id":"fr-p198","tipo":"palavra","fr":"penser","en":"to think","aceitasEn":["to think","think"],"distratoresEn":["to weigh","to comb","to stroll","to fish"],"nivel":"A1","tags":["verbo"],"notaEn":"«Je pense que oui», I think so. «Penser à» is to think about, and also to remember to: «pense à acheter du pain», remember to buy bread.","v":"8ccfb16b","pos":30},{"idioma":"fr","id":"fr-p199","tipo":"palavra","fr":"cher","aceitasFr":["chère"],"en":"expensive / dear","aceitasEn":["expensive","dear","pricey"],"distratoresEn":["cheap / affordable","clear / obvious","full / crowded","boring / dull"],"nivel":"A1","tags":["adjetivo","compras"],"notaEn":"Feminine «chère». Expensive: «c'est trop cher». Before a name, dear: «chère Marie», at the start of a letter.","v":"12a5869f","pos":487},{"idioma":"fr","id":"fr-p200","tipo":"palavra","fr":"facile","en":"easy","aceitasEn":["easy"],"distratoresEn":["difficult","fragile","faithful","fertile"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Same form for masculine and feminine. The opposite is «difficile». «C'est facile à dire», easier said than done.","v":"03f27634","pos":455},{"idioma":"fr","id":"fr-p201","tipo":"palavra","fr":"libre","en":"free","aceitasEn":["free","available","vacant"],"distratoresEn":["light","clean","pretty","slow"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Same form for masculine and feminine: «la place est libre ?», is this seat free? Free of charge is «gratuit».","v":"24e89a45","pos":429},{"idioma":"fr","id":"fr-p202","tipo":"palavra","fr":"encore","en":"still / again","aceitasEn":["still","again","more","yet"],"distratoresEn":["now / today","before / after","never / ever","soon / early"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Still («il dort encore», he's still asleep; «pas encore», not yet), again («encore une fois») and more («encore du café ?»).","v":"3363b894","pos":35},{"idioma":"fr","id":"fr-p203","tipo":"palavra","fr":"peut-être","en":"maybe","aceitasEn":["maybe","perhaps"],"distratoresEn":["surely","never","also","later"],"nivel":"A1","tags":["cotidiano"],"notaEn":"With a hyphen. Without it, «peut être» is the verb, can be: «il peut être malade», he may be sick.","v":"89451953","pos":78},{"idioma":"fr","id":"fr-p204","tipo":"palavra","fr":"parfois","en":"sometimes","aceitasEn":["sometimes","at times","occasionally"],"distratoresEn":["always","never","often","rarely"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Parfois je cuisine», sometimes I cook. «Quelquefois» means the same; often is «souvent».","v":"09bb8f91","pos":321},{"idioma":"fr","id":"fr-u142","tipo":"frase","requer":"fr-p185","fr":"Il est encore au lit.","en":"He's still in bed.","aceitasEn":["hes still in bed","he is still in bed","hes still lying in bed"],"distratoresEn":["He's still in the living room.","He's still in the kitchen.","He's still at school.","He's still at the beach."],"nivel":"A1","tags":["casa","cotidiano"],"notaEn":"In bed is «au lit» («à» + «le»): «aller au lit», to go to bed. «Encore» here means still; it can also mean again.","requerTodas":["fr-p001","fr-p202","fr-p185"],"v":"7e72bbe2"},{"idioma":"fr","id":"fr-u143","tipo":"frase","requer":"fr-p187","fr":"Le chat dort sur le canapé.","en":"The cat is sleeping on the couch.","aceitasEn":["the cat is sleeping on the couch","the cats sleeping on the couch","the cat is sleeping on the sofa","the cat sleeps on the couch","the cat sleeps on the sofa"],"distratoresEn":["The dog is sleeping on the couch.","The baby is sleeping on the couch.","Grandpa is sleeping on the couch.","The boy is sleeping on the couch."],"nivel":"A1","tags":["animais","casa"],"notaEn":"«Chat» is pronounced «shah», with a silent «t». «Sur» means on: «sur le canapé», on the couch; «sur la table», on the table.","requerTodas":["fr-p187","fr-p109","fr-p205"],"v":"e9fe495c"},{"idioma":"fr","id":"fr-u144","tipo":"frase","requer":"fr-p186","fr":"Ferme la porte, s'il te plaît.","en":"Close the door, please.","aceitasEn":["close the door please","please close the door","shut the door please","close the door","please shut the door"],"distratoresEn":["Close the window, please.","Close the box, please.","Close the suitcase, please.","Close the curtain, please."],"nivel":"A1","tags":["casa"],"notaEn":"«Ferme», from «fermer», is the «tu» imperative, hence «s'il te plaît». With «vous»: «fermez la porte, s'il vous plaît».","requerTodas":["fr-p206","fr-p186"],"v":"7b60b4d7"},{"idioma":"fr","id":"fr-u145","tipo":"frase","requer":"fr-p188","fr":"Je t'attends à la gare.","en":"I'll wait for you at the station.","aceitasEn":["ill wait for you at the station","i will wait for you at the station","im waiting for you at the station","ill wait for you at the train station","ill meet you at the station","ill be waiting for you at the station"],"distratoresEn":["I'll wait for you at the square.","I'll wait for you on the corner.","I'll wait for you at the bakery.","I'll wait for you at school."],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"«La gare» is only the train station; a subway station is «la station», and the bus station «la gare routière». «Attendre» takes no «for»: «je t'attends».","requerTodas":["fr-p018","fr-p188"],"v":"2a168a9c"},{"idioma":"fr","id":"fr-u146","tipo":"frase","requer":"fr-p189","fr":"Il n'y a plus de lait dans le frigo.","en":"There's no more milk in the fridge.","aceitasEn":["theres no more milk in the fridge","there is no more milk in the fridge","theres no milk left in the fridge","there isnt any more milk in the fridge","were out of milk","we are out of milk"],"distratoresEn":["There's no more juice in the fridge.","There's no more cheese in the fridge.","There's no more yogurt in the fridge.","There's no more ham in the fridge."],"nivel":"A1","tags":["comida","casa"],"notaEn":"«Ne… plus» means no more: «il n'y a plus de lait». After a negative, «du» becomes «de». «Le frigo» is the everyday word for fridge.","requerTodas":["fr-p002","fr-p189","fr-p207"],"v":"846b8f2f"},{"idioma":"fr","id":"fr-u147","tipo":"frase","requer":"fr-p190","fr":"Je suis là toute la semaine.","en":"I'm here all week.","aceitasEn":["im here all week","i am here all week","im here the whole week","ill be here all week","i will be here all week"],"distratoresEn":["I'm here all night.","I'm here all afternoon.","I'm here all morning.","I'm here all season."],"nivel":"A1","tags":["cotidiano"],"notaEn":"All week is «toute la semaine», with «tout» in the feminine. Every week is «chaque semaine» or «toutes les semaines».","requerTodas":["fr-p001","fr-p165","fr-p070","fr-p190"],"v":"3ade17ae"},{"idioma":"fr","id":"fr-u148","tipo":"frase","requer":"fr-p191","fr":"Lave-toi les mains !","en":"Wash your hands!","aceitasEn":["wash your hands","go wash your hands"],"distratoresEn":["Wash your ears!","Wash your legs!","Wash your feet!","Wash your knees!"],"nivel":"A1","tags":["corpo","casa"],"notaEn":"With body parts, French uses a reflexive verb and «les», not «your»: «lave-toi les mains», literally wash yourself the hands.","requerTodas":["fr-p208","fr-p191"],"v":"b896f527"},{"idioma":"fr","id":"fr-u149","tipo":"frase","requer":"fr-p192","fr":"Quel est le prix de cette chemise ?","en":"What's the price of this shirt?","aceitasEn":["whats the price of this shirt","what is the price of this shirt","how much is this shirt","how much does this shirt cost"],"distratoresEn":["What's the size of this shirt?","What's the fabric of this shirt?","What's the style of this shirt?","What's the number of this shirt?"],"nivel":"A1","tags":["compras","roupa"],"notaEn":"«Le prix» is both the price and the prize: «le prix Nobel». «La chemise» is a shirt; a T-shirt is «le t-shirt».","requerTodas":["fr-p001","fr-p192","fr-p209"],"v":"8044bb8b"},{"idioma":"fr","id":"fr-u150","tipo":"frase","requer":"fr-p192","fr":"Elle a gagné le premier prix.","en":"She won first prize.","aceitasEn":["she won first prize","she won the first prize","she took first prize","shes won first prize"],"distratoresEn":["She won the first game.","She won the first round.","She won the first set.","She won the first challenge."],"nivel":"A2","tags":["cotidiano","cultura"],"notaEn":"Here «le prix» is the prize, not the price. «Gagner» is to win and also to earn: «gagner sa vie», to earn a living.","requerTodas":["fr-p002","fr-p210","fr-p211","fr-p192"],"v":"415a5f8d"},{"idioma":"fr","id":"fr-u151","tipo":"frase","requer":"fr-p193","fr":"Je ne trouve pas mon portable.","en":"I can't find my phone.","aceitasEn":["i cant find my phone","i cant find my cell phone","i cannot find my phone","i cant find my cellphone","i cant find my mobile"],"distratoresEn":["I can't find my charger.","I can't find my coat.","I can't find my umbrella.","I can't find my passport."],"nivel":"A1","tags":["objetos","tecnologia"],"notaEn":"To find is «trouver»; to look for is «chercher». «Le portable» is a cell phone; in Quebec, «le cellulaire».","requerTodas":["fr-p193","fr-p212"],"v":"4461e816"},{"idioma":"fr","id":"fr-u152","tipo":"frase","requer":"fr-p193","fr":"Je trouve ce film génial.","en":"I think this movie is great.","aceitasEn":["i think this movie is great","i find this movie great","i think this film is great","i find this film great","i think this movie is amazing","i think this movie is brilliant"],"distratoresEn":["I think this movie is boring.","I think this movie is long.","I think this movie is sad.","I think this movie is weird."],"nivel":"A2","tags":["cultura"],"notaEn":"«Trouver» also gives an opinion, like to find in English: «je trouve ce film génial», I find this movie great. «Tu trouves ?» is do you think so?","requerTodas":["fr-p193","fr-p100","fr-p099"],"v":"5c66e912"},{"idioma":"fr","id":"fr-u153","tipo":"frase","requer":"fr-p194","fr":"Je peux te demander quelque chose ?","en":"Can I ask you something?","aceitasEn":["can i ask you something","can i ask you a question","could i ask you something","may i ask you something"],"distratoresEn":["Can I tell you something?","Can I show you something?","Can I give you something?","Can I bring you something?"],"nivel":"A1","tags":["social"],"notaEn":"«Demander» is to ask, both a question and for something: «demander l'heure», to ask the time; «demander de l'aide», to ask for help. It doesn't mean to demand.","requerTodas":["fr-p006","fr-p194"],"v":"a2b97e77"},{"idioma":"fr","id":"fr-u154","tipo":"frase","requer":"fr-p194","fr":"Je vais demander de l'aide.","en":"I'm going to ask for help.","aceitasEn":["im going to ask for help","i am going to ask for help","ill ask for help","i will ask for help","im gonna ask for help"],"distratoresEn":["I'm going to offer help.","I'm going to accept help.","I'm going to refuse help.","I'm going to look for help."],"nivel":"A1","tags":["social","cotidiano"],"notaEn":"To ask for something is «demander quelque chose», with no «for»; the person takes «à»: «demander de l'aide à un ami».","requerTodas":["fr-p003","fr-p194","fr-p213"],"v":"6415b66b"},{"idioma":"fr","id":"fr-u155","tipo":"frase","requer":"fr-p195","fr":"Tu peux me donner un coup de main ?","en":"Can you give me a hand?","aceitasEn":["can you give me a hand","could you give me a hand","can you lend me a hand","could you lend me a hand"],"distratoresEn":["Can you give me a hug?","Can you give me a ride?","Can you give me a minute?","Can you give me a push?"],"nivel":"A2","tags":["social","expressão"],"notaEn":"«Un coup de main» is a hand, some quick help. «Le coup» is a blow, and it turns up in many expressions: «un coup de fil», a phone call.","requerTodas":["fr-p006","fr-p195","fr-p214","fr-p191"],"v":"9d3e88c7"},{"idioma":"fr","id":"fr-u156","tipo":"frase","requer":"fr-p195","fr":"Il m'a donné son numéro.","en":"He gave me his number.","aceitasEn":["he gave me his number","he gave me his phone number","hes given me his number","he has given me his number"],"distratoresEn":["He gave me his address.","He gave me his email.","He gave me his coat.","He gave me his book."],"nivel":"A1","tags":["social","tecnologia"],"notaEn":"«Son» can mean his or her: the possessive agrees with the thing («le numéro»), not with the owner. «Me» becomes «m'» before a vowel.","requerTodas":["fr-p002","fr-p195","fr-p215"],"v":"83c35c88"},{"idioma":"fr","id":"fr-u157","tipo":"frase","requer":"fr-p196","fr":"Le film commence à huit heures.","en":"The movie starts at eight.","aceitasEn":["the movie starts at eight","the movie begins at eight","the film starts at eight","the film begins at eight","the movie starts at 8","the movie starts at eight oclock"],"distratoresEn":["The movie ends at eight.","The movie restarts at eight.","The movie stops at eight.","The movie comes back at eight."],"nivel":"A1","tags":["cultura","cotidiano"],"notaEn":"To start is «commencer», like commence. Before «a» and «o», the «c» takes a cedilla to keep its «s» sound: «nous commençons».","requerTodas":["fr-p100","fr-p196","fr-p126","fr-p129"],"v":"29ebfeb6"},{"idioma":"fr","id":"fr-u158","tipo":"frase","requer":"fr-p196","fr":"Il commence à pleuvoir.","en":"It's starting to rain.","aceitasEn":["its starting to rain","it is starting to rain","its beginning to rain","it is beginning to rain","its starting to rain now"],"distratoresEn":["The rain is stopping.","It's raining again.","It looks like rain.","It's about to rain."],"nivel":"A1","tags":["natureza"],"notaEn":"To start doing something is «commencer à» + infinitive. «Pleuvoir» only exists with «il»: «il pleut», it's raining.","requerTodas":["fr-p196","fr-p171"],"v":"7c41871f"},{"idioma":"fr","id":"fr-u159","tipo":"frase","requer":"fr-p197","fr":"N'oublie pas ton passeport !","en":"Don't forget your passport!","aceitasEn":["dont forget your passport","do not forget your passport","dont forget the passport"],"distratoresEn":["Don't forget your coat!","Don't forget your phone!","Don't forget your umbrella!","Don't forget your charger!"],"nivel":"A1","tags":["viagem"],"notaEn":"In a negative command, «ne… pas» wraps the verb: «n'oublie pas». It's the «tu» form, without the «s» of the present: «tu oublies».","requerTodas":["fr-p197","fr-p216"],"v":"a48a903f"},{"idioma":"fr","id":"fr-u160","tipo":"frase","requer":"fr-p197","fr":"J'ai oublié son nom.","en":"I forgot his name.","aceitasEn":["i forgot his name","i forgot her name","ive forgotten his name","ive forgotten her name","i have forgotten his name","i have forgotten her name"],"distratoresEn":["I forgot his number.","I forgot his birthday.","I forgot his face.","I forgot his address."],"nivel":"A1","tags":["social"],"notaEn":"«Son nom» can be his or her name. «Le nom» is also the surname: on a form, «nom et prénom» means last name and first name.","requerTodas":["fr-p002","fr-p197","fr-p217"],"v":"99b3252a"},{"idioma":"fr","id":"fr-u161","tipo":"frase","requer":"fr-p198","fr":"Je pense que oui.","en":"I think so.","aceitasEn":["i think so","i believe so","i guess so"],"distratoresEn":["I hope so.","I know.","Of course.","I doubt it."],"nivel":"A1","tags":["social","cotidiano"],"notaEn":"I think so is «je pense que oui», literally I think that yes; I don't think so is «je pense que non».","requerTodas":["fr-p198"],"v":"b03827c2"},{"idioma":"fr","id":"fr-u162","tipo":"frase","requer":"fr-p198","fr":"Je pense à toi.","en":"I'm thinking of you.","aceitasEn":["im thinking of you","i am thinking of you","im thinking about you","i am thinking about you","i think of you","i think about you"],"distratoresEn":["I trust you.","I believe in you.","I need you.","I dream of you."],"nivel":"A1","tags":["social","família"],"notaEn":"To think of or about is «penser à»: «je pense à toi», «je pense à mes vacances». After a preposition, you is «toi», not «tu».","requerTodas":["fr-p198"],"v":"d39e7091"},{"idioma":"fr","id":"fr-u163","tipo":"frase","requer":"fr-p199","fr":"C'est trop cher.","en":"It's too expensive.","aceitasEn":["its too expensive","it is too expensive","thats too expensive","that is too expensive","its way too expensive"],"distratoresEn":["It's too cheap.","It's too small.","It's too heavy.","It's too big."],"nivel":"A1","tags":["compras"],"notaEn":"«Cher» means expensive, and also dear: «cher ami». Cheap is «pas cher», or «bon marché».","requerTodas":["fr-p001","fr-p061","fr-p199"],"v":"e7bd40e5"},{"idioma":"fr","id":"fr-u164","tipo":"frase","requer":"fr-p199","fr":"Chère Julie, je t'écris de Paris.","en":"Dear Julie, I'm writing to you from Paris.","aceitasEn":["dear julie im writing to you from paris","dear julie im writing from paris","dear julie i am writing to you from paris","dear julie i am writing from paris"],"distratoresEn":["Hi Julie, I'm writing to you from Paris.","Poor Julie, I'm writing to you from Paris.","Lovely Julie, I'm writing to you from Paris.","Little Julie, I'm writing to you from Paris."],"nivel":"A2","tags":["social","cotidiano"],"notaEn":"Opening a letter, «cher» is dear, and it agrees: «cher Paul», «chère Julie». To write to someone is «écrire à»: «je t'écris», I'm writing to you.","requerTodas":["fr-p199","fr-p184"],"v":"850d7785"},{"idioma":"fr","id":"fr-u165","tipo":"frase","requer":"fr-p200","fr":"Ce n'est pas facile.","aceitasFr":["C'est pas facile."],"en":"It's not easy.","aceitasEn":["its not easy","it isnt easy","it is not easy","thats not easy","that is not easy","that isnt easy"],"distratoresEn":["It's not hard.","It's not possible.","It's not fair.","It's not normal."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Ce n'est pas» is the negative of «c'est»; in speech it's often «c'est pas facile». «Facile» is the same in the masculine and feminine.","requerTodas":["fr-p001","fr-p200"],"v":"fea9afb2"},{"idioma":"fr","id":"fr-u166","tipo":"frase","requer":"fr-p201","fr":"Cette place est libre ?","en":"Is this seat free?","aceitasEn":["is this seat free","is this seat available","is this seat empty","is this place free"],"distratoresEn":["Is this seat clean?","Is this seat comfortable?","Is this seat broken?","Is this seat wet?"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"«La place» is a seat or a spot — and also a town square: «la place de la Concorde». A parking space is «une place» too.","requerTodas":["fr-p218","fr-p001","fr-p201"],"v":"ed831a08"},{"idioma":"fr","id":"fr-u167","tipo":"frase","requer":"fr-p201","fr":"Tu es libre ce soir ?","en":"Are you free tonight?","aceitasEn":["are you free tonight","are you free this evening","you free tonight"],"distratoresEn":["Are you tired tonight?","Are you alone tonight?","Are you excited tonight?","Are you nervous tonight?"],"nivel":"A1","tags":["social"],"notaEn":"Having no plans is «être libre». Tonight is «ce soir»; «cette nuit» is the night you sleep through.","requerTodas":["fr-p001","fr-p201","fr-p160"],"v":"6aa5254e"},{"idioma":"fr","id":"fr-u168","tipo":"frase","requer":"fr-p203","fr":"Il va peut-être pleuvoir.","aceitasFr":["Peut-être qu'il va pleuvoir.","Il pleuvra peut-être."],"en":"It might rain.","aceitasEn":["it might rain","maybe itll rain","maybe it will rain","it may rain","it could rain","maybe its going to rain","maybe it is going to rain"],"distratoresEn":["I doubt it'll rain.","I hope it rains.","It shouldn't rain.","It's definitely going to rain."],"nivel":"A1","tags":["natureza"],"notaEn":"«Peut-être», maybe, goes between the helper verb and the infinitive: «il va peut-être pleuvoir». At the start of the sentence it takes «que»: «peut-être qu'il va pleuvoir».","requerTodas":["fr-p003","fr-p203","fr-p171"],"v":"3b1fdfbf"},{"idioma":"fr","id":"fr-u169","tipo":"frase","requer":"fr-p204","fr":"Parfois, je viens à vélo.","aceitasFr":["Je viens parfois à vélo.","Parfois, je viens en vélo."],"en":"Sometimes I come by bike.","aceitasEn":["sometimes i come by bike","sometimes i come by bicycle","i sometimes come by bike","sometimes i bike here","sometimes i ride my bike here"],"distratoresEn":["I always come by bike.","I never come by bike.","I rarely come by bike.","I come by bike every day."],"nivel":"A1","tags":["cotidiano","cidade"],"notaEn":"Sometimes is «parfois», one word. By bike is «à vélo», like «à pied»; by car, «en voiture».","requerTodas":["fr-p204","fr-p009","fr-p219"],"v":"a8808d24"},{"idioma":"fr","id":"fr-u170","tipo":"frase","requer":"fr-p202","fr":"Je n'ai pas encore mangé.","en":"I haven't eaten yet.","aceitasEn":["i havent eaten yet","i have not eaten yet","i didnt eat yet","i still havent eaten"],"distratoresEn":["I haven't eaten today.","I've hardly eaten.","I haven't eaten either.","I didn't eat yesterday."],"nivel":"A1","tags":["comida","gramática"],"notaEn":"Not yet is «pas encore», with «encore» right after «pas»: «je n'ai pas encore mangé». The opposite is «déjà»: «j'ai déjà mangé».","requerTodas":["fr-p002","fr-p202","fr-p013"],"v":"30b74d3a"},{"idioma":"fr","id":"fr-u171","tipo":"frase","requer":"fr-p202","fr":"Tu es encore en retard !","en":"You're late again!","aceitasEn":["youre late again","you are late again","late again"],"distratoresEn":["You're very late!","You're a little late!","You're late today!","You're always late!"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Encore» also means again: «encore en retard», late again. «Être en retard» is to be late.","requerTodas":["fr-p001","fr-p202","fr-p085"],"v":"d043f153"},{"idioma":"fr","id":"fr-u172","tipo":"frase","requer":"fr-p118","fr":"Je vais chercher ma fille à l'école.","en":"I'm going to pick up my daughter from school.","aceitasEn":["im going to pick up my daughter from school","im going to pick my daughter up from school","ill pick up my daughter from school","im picking up my daughter from school","im going to get my daughter from school","im going to pick up my daughter at school"],"distratoresEn":["I'm going to take my daughter to school.","I'm going to drop my daughter off at school.","I'm going to visit my daughter at school.","I'm going to wait for my daughter at school."],"nivel":"A1","tags":["família","escola"],"notaEn":"«Aller chercher» is to go and get, to pick someone up: «je vais chercher ma fille». «La fille» means daughter and also girl.","requerTodas":["fr-p003","fr-p118","fr-p220","fr-p106"],"v":"0f9bf477"},{"idioma":"fr","id":"fr-u173","tipo":"frase","requer":"fr-p119","fr":"Tu connais bien Paris ?","en":"Do you know Paris well?","aceitasEn":["do you know paris well","you know paris well"],"distratoresEn":["Do you like Paris?","Do you live in Paris?","Do you visit Paris?","Do you miss Paris?"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"To know a person or a place is «connaître»; to know a fact or how to do something is «savoir». The «î» only shows up before a «t»: «il connaît», but «tu connais».","requerTodas":["fr-p119","fr-p044"],"v":"02286460"},{"idioma":"fr","id":"fr-u174","tipo":"frase","requer":"fr-p122","fr":"Il ne faut pas fumer ici.","en":"You can't smoke here.","aceitasEn":["you cant smoke here","you cannot smoke here","no smoking here","smoking is not allowed here","you mustnt smoke here","you are not allowed to smoke here","youre not allowed to smoke here"],"distratoresEn":["You don't have to smoke here.","You can smoke here.","You have to smoke here.","People usually smoke here."],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«Il ne faut pas» means you mustn't — not you don't have to. For that, French says «ce n'est pas la peine» or «pas besoin».","requerTodas":["fr-p122","fr-p221","fr-p048"],"v":"b6359f66"},{"idioma":"fr","id":"fr-u175","tipo":"frase","requer":"fr-p123","fr":"Tu as fini de manger ?","en":"Have you finished eating?","aceitasEn":["have you finished eating","are you done eating","did you finish eating","are you finished eating","have you finished"],"distratoresEn":["Have you stopped eating?","Have you started eating?","Have you tried eating?","Have you quit eating?"],"nivel":"A1","tags":["comida"],"notaEn":"To finish doing something is «finir de» + infinitive: «tu as fini de manger ?». The past participle of «finir» is «fini».","requerTodas":["fr-p002","fr-p123","fr-p013"],"v":"75774537"},{"idioma":"fr","id":"fr-u176","tipo":"frase","requer":"fr-p167","fr":"Mets ton manteau, il fait froid.","en":"Put your coat on, it's cold.","aceitasEn":["put your coat on its cold","put on your coat its cold","put your coat on it is cold","wear your coat its cold","put your coat on its cold out"],"distratoresEn":["Put your hat on, it's cold.","Put your sweater on, it's cold.","Put your vest on, it's cold.","Put your scarf on, it's cold."],"nivel":"A1","tags":["roupa","natureza"],"notaEn":"To put on clothes is «mettre»: «mets ton manteau». Cold weather takes «faire»: «il fait froid».","requerTodas":["fr-p167","fr-p222","fr-p004","fr-p080"],"v":"264b7338"},{"idioma":"fr","id":"fr-u177","tipo":"frase","requer":"fr-p167","fr":"Tu peux mettre la table ?","en":"Can you set the table?","aceitasEn":["can you set the table","could you set the table","can you lay the table","will you set the table"],"distratoresEn":["Can you clean the table?","Can you clear the table?","Can you dry the table?","Can you move the table?"],"nivel":"A1","tags":["casa","comida"],"notaEn":"To set the table is «mettre la table»; to clear it is «débarrasser la table».","requerTodas":["fr-p006","fr-p167","fr-p143"],"v":"e0748349"},{"idioma":"fr","id":"fr-u178","tipo":"frase","requer":"fr-p169","fr":"Le magasin ouvre à neuf heures.","en":"The store opens at nine.","aceitasEn":["the store opens at nine","the shop opens at nine","the store opens at 9","the store opens at nine oclock"],"distratoresEn":["The store closes at nine.","The store fills up at nine.","The store empties out at nine.","The store reopens at nine."],"nivel":"A1","tags":["compras","cidade"],"notaEn":"«Le magasin» is a store; «le magazine» is a magazine. «Ouvrir» is conjugated like an -er verb: «j'ouvre», «il ouvre».","requerTodas":["fr-p223","fr-p169","fr-p224","fr-p129"],"v":"661b502c"},{"idioma":"fr","id":"fr-u179","tipo":"frase","requer":"fr-p170","fr":"C'est moi qui paie.","aceitasFr":["C'est moi qui paye."],"en":"I'm paying.","aceitasEn":["im paying","i am paying","ill pay","i will pay","its on me","this is on me","ill get this","let me pay"],"distratoresEn":["I'm driving.","I'm cooking.","I'm choosing.","I'm in charge."],"nivel":"A1","tags":["compras","social"],"notaEn":"«C'est moi qui» stresses the I, and the verb agrees with «moi»: «c'est moi qui paie». «Payer» has two spellings: «je paie» and «je paye».","requerTodas":["fr-p001","fr-p170"],"v":"bae19b8e"},{"idioma":"fr","id":"fr-u180","tipo":"frase","requer":"fr-p172","fr":"Il regarde la télé.","en":"He's watching TV.","aceitasEn":["hes watching tv","he is watching tv","he watches tv","hes watching television","he is watching television"],"distratoresEn":["He's watching a soap opera.","He's watching soccer.","He's watching a series.","He's watching cartoons."],"nivel":"A1","tags":["casa","cotidiano"],"notaEn":"To watch is «regarder», with no preposition: «regarder la télé», «regarder un film». «La télé» is the everyday word for TV.","requerTodas":["fr-p172","fr-p225"],"v":"3a78bcc1"},{"idioma":"fr","id":"fr-u181","tipo":"frase","requer":"fr-p172","fr":"Je regarde seulement.","aceitasFr":["Je regarde juste.","Je ne fais que regarder."],"en":"I'm just looking.","aceitasEn":["im just looking","i am just looking","im only looking","just looking"],"distratoresEn":["I'm just trying it on.","I'm just asking.","I'm just waiting.","I'm just passing through."],"nivel":"A1","tags":["compras"],"notaEn":"The shop phrase to wave off a salesperson. «Seulement», only, goes after the verb; people also just say «je regarde, merci».","requerTodas":["fr-p172","fr-p226"],"v":"f6e743cd"},{"idioma":"fr","id":"fr-u182","tipo":"frase","requer":"fr-p174","fr":"J'ai réservé une chambre à l'hôtel.","en":"I booked a room at the hotel.","aceitasEn":["i booked a room at the hotel","i reserved a room at the hotel","ive booked a room at the hotel","i have booked a room at the hotel","i booked a hotel room","ive reserved a room at the hotel"],"distratoresEn":["I booked a taxi at the hotel.","I booked a tour at the hotel.","I booked a dinner at the hotel.","I booked a hall at the hotel."],"nivel":"A1","tags":["viagem"],"notaEn":"«La chambre» is a room — at a hotel, «une chambre simple» or «double». The «h» of «hôtel» is silent, hence «l'hôtel».","requerTodas":["fr-p002","fr-p174","fr-p107","fr-p227"],"v":"a93a4b5c"},{"idioma":"fr","id":"fr-u183","tipo":"frase","requer":"fr-p184","fr":"Comment ça s'écrit ?","en":"How do you spell that?","aceitasEn":["how do you spell that","how do you spell it","how is that spelled","how is it spelled","how do you write that","how do you write it"],"distratoresEn":["How do you say that?","How do you read that?","How do you pronounce that?","What do you call that?"],"nivel":"A1","tags":["escola"],"notaEn":"The «se» of «s'écrire» makes it passive: «ça s'écrit», literally it writes itself. To spell out letter by letter is «épeler».","requerTodas":["fr-p184"],"v":"549e4c3f"},{"idioma":"fr","id":"fr-u184","tipo":"frase","requer":"fr-p158","fr":"J'ai mal aux pieds.","en":"My feet hurt.","aceitasEn":["my feet hurt","my feet are hurting","my feet are sore","my foot hurts"],"distratoresEn":["My knees hurt.","My shoulders hurt.","My eyes hurt.","My arms hurt."],"nivel":"A1","tags":["saúde","corpo"],"notaEn":"In the plural, «à» + «les» becomes «aux»: «j'ai mal aux pieds», «aux dents». In the singular: «au pied», «à la tête».","requerTodas":["fr-p002","fr-p151","fr-p158"],"v":"3fb81614"},{"idioma":"fr","id":"fr-u185","tipo":"frase","requer":"fr-p166","fr":"Je suis tombé malade.","aceitasFr":["Je suis tombée malade."],"en":"I got sick.","aceitasEn":["i got sick","i fell ill","i became sick","i became ill","i got ill"],"distratoresEn":["I got tired.","I got nervous.","I got sad.","I got angry."],"nivel":"A1","tags":["saúde"],"notaEn":"To get sick is «tomber malade», literally to fall sick. «Tomber» takes «être» in the passé composé, and a woman writes «tombée».","requerTodas":["fr-p001","fr-p228","fr-p166"],"v":"ee4e66ab"},{"idioma":"fr","id":"fr-u186","tipo":"frase","requer":"fr-p121","fr":"Ça fait dix euros.","en":"That's ten euros.","aceitasEn":["thats ten euros","that is ten euros","that comes to ten euros","its ten euros","it is ten euros","that will be ten euros","thatll be ten euros","thats 10 euros"],"distratoresEn":["That's six euros.","That's eight euros.","That's seven euros.","That's three euros."],"nivel":"A1","tags":["compras"],"notaEn":"At the till, «ça fait» gives the total: «ça fait dix euros». The «x» of «dix» sounds like «s» at the end of a sentence and like «z» before a vowel: «dix euros».","requerTodas":["fr-p004","fr-p121","fr-p128"],"v":"745a94b0"},{"idioma":"fr","id":"fr-u187","tipo":"frase","requer":"fr-p094","fr":"Il est trois heures.","en":"It's three o'clock.","aceitasEn":["its three oclock","its three","it is three oclock","its 3 oclock","it is three","its 3"],"distratoresEn":["It's two o'clock.","It's six o'clock.","It's eight o'clock.","It's ten o'clock."],"nivel":"A1","tags":["cotidiano"],"notaEn":"Time is told with «il est» and the word «heures», which is never dropped: «il est trois heures». One o'clock is «il est une heure».","requerTodas":["fr-p001","fr-p094","fr-p129"],"v":"a3eb932e"},{"idioma":"fr","id":"fr-u188","tipo":"frase","requer":"fr-p115","fr":"J'arrive dans dix minutes.","en":"I'll be there in ten minutes.","aceitasEn":["ill be there in ten minutes","i will be there in ten minutes","ill arrive in ten minutes","ill be there in 10 minutes","im arriving in ten minutes","ill get there in ten minutes","ill be there in ten","ill be here in ten minutes"],"distratoresEn":["I got there ten minutes ago.","I'm leaving in ten minutes.","I'll be there at ten.","I'll be ten minutes late."],"nivel":"A1","tags":["cotidiano","viagem"],"notaEn":"«Dans» + a length of time means in: «dans dix minutes». Ten minutes ago is «il y a dix minutes». The present works for the near future: «j'arrive».","requerTodas":["fr-p115","fr-p121","fr-p139"],"v":"5f1d160d"},{"idioma":"fr","id":"fr-u189","tipo":"frase","requer":"fr-p115","fr":"J'arrive !","en":"Coming!","aceitasEn":["coming","im coming","i am coming","be right there","ill be right there","on my way","im on my way"],"distratoresEn":["I'm here!","Be right back!","I'm done!","I've left!"],"nivel":"A1","tags":["cotidiano","expressão"],"notaEn":"«J'arrive !» is what you call out when someone calls you: coming! It doesn't mean you've arrived — that's «je suis arrivé».","requerTodas":["fr-p115"],"v":"2f82bb98"},{"idioma":"fr","id":"fr-u190","tipo":"frase","requer":"fr-p115","fr":"Qu'est-ce qui est arrivé ?","aceitasFr":["Qu'est-ce qui s'est passé ?"],"en":"What happened?","aceitasEn":["what happened","what has happened","whats happened"],"distratoresEn":["What changed?","What fell?","What broke?","What disappeared?"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Arriver» means to arrive and also to happen: «qu'est-ce qui est arrivé ?», what happened? It takes «être» in the passé composé.","requerTodas":["fr-p001","fr-p115"],"v":"1cd883db"},{"idioma":"fr","id":"fr-u191","tipo":"frase","requer":"fr-p129","fr":"Il arrive toujours à l'heure.","en":"He's always on time.","aceitasEn":["hes always on time","he is always on time","he always arrives on time","he always gets here on time","he always gets there on time","hes always punctual"],"distratoresEn":["He's always early.","He's always late.","He's always in a hurry.","He's always tired."],"nivel":"A1","tags":["cotidiano"],"notaEn":"On time is «à l'heure»; late, «en retard»; early, «en avance». «Toujours» goes after the verb: «il arrive toujours».","requerTodas":["fr-p115","fr-p046","fr-p129"],"v":"557ed0e2"},{"idioma":"fr","id":"fr-u192","tipo":"frase","requer":"fr-p129","fr":"À quelle heure on mange ?","aceitasFr":["On mange à quelle heure ?","À quelle heure est-ce qu'on mange ?","À quelle heure mange-t-on ?"],"en":"What time do we eat?","aceitasEn":["what time do we eat","what time are we eating","at what time do we eat","what time are we going to eat"],"distratoresEn":["Where do we eat?","Who do we eat with?","What do we eat?","How much do we eat?"],"nivel":"A1","tags":["comida","cotidiano"],"notaEn":"What time, for when something happens, is «à quelle heure», with «heure» singular. Asking the current time is «quelle heure est-il ?».","requerTodas":["fr-p129","fr-p013"],"v":"31725da5"},{"idioma":"fr","id":"fr-u193","tipo":"frase","requer":"fr-p148","fr":"J'ai cours de français le lundi.","en":"I have French class on Mondays.","aceitasEn":["i have french class on mondays","i have french on mondays","i have a french class on mondays","ive got french class on mondays","on mondays i have french class","i have french class every monday"],"distratoresEn":["I have a French test on Mondays.","I have French homework on Mondays.","I have a French talk on Mondays.","I have French review on Mondays."],"nivel":"A1","tags":["escola"],"notaEn":"«Avoir cours» is to have class, with no article. «Le lundi», with the article, means on Mondays; plain «lundi» means this coming Monday.","requerTodas":["fr-p002","fr-p148","fr-p054","fr-p084"],"v":"f8f2af02"},{"idioma":"fr","id":"fr-u194","tipo":"frase","requer":"fr-p140","fr":"J'ai une question.","en":"I have a question.","aceitasEn":["i have a question","ive got a question","i have got a question"],"distratoresEn":["I have an answer.","I have an idea.","I have a suggestion.","I have a complaint."],"nivel":"A1","tags":["escola"],"notaEn":"«La question» is a question; to ask one is «poser une question», literally to put a question.","requerTodas":["fr-p002","fr-p140"],"v":"6d07a9e6"},{"idioma":"fr","id":"fr-u195","tipo":"frase","requer":"fr-p151","fr":"Ça fait mal !","en":"It hurts!","aceitasEn":["it hurts","that hurts","ouch that hurts"],"distratoresEn":["It itches!","It burns!","It's tight!","It tickles!"],"nivel":"A1","tags":["saúde","corpo"],"notaEn":"To hurt is «faire mal»: «ça fait mal», it hurts; «tu me fais mal», you're hurting me. With a body part, «avoir mal à».","requerTodas":["fr-p004","fr-p151"],"v":"2fa24914"},{"idioma":"fr","id":"fr-u196","tipo":"frase","requer":"fr-p155","fr":"Il faut appeler un médecin.","en":"We need to call a doctor.","aceitasEn":["we need to call a doctor","we have to call a doctor","someone needs to call a doctor","we need to get a doctor","we must call a doctor","we need to call the doctor"],"distratoresEn":["We need to call a lawyer.","We need to call a firefighter.","We need to call a technician.","We need to call an electrician."],"nivel":"A1","tags":["saúde"],"notaEn":"To call, also on the phone, is «appeler»: «appeler un médecin», «je t'appelle demain». Two «p»s, and in «j'appelle» two «l»s as well.","requerTodas":["fr-p122","fr-p229","fr-p155"],"v":"c85cadc0"},{"idioma":"fr","id":"fr-u197","tipo":"frase","requer":"fr-p165","fr":"Il n'est pas là.","en":"He's not here.","aceitasEn":["hes not here","he isnt here","he is not here","hes not in","he isnt in","hes out"],"distratoresEn":["He's not well.","He's not ready.","He's not awake.","He's not alone."],"nivel":"A1","tags":["cotidiano","social"],"notaEn":"On the phone or at the door, «il n'est pas là» means he's not in. «Là» works for here as well as there: «je suis là», I'm here.","requerTodas":["fr-p001","fr-p165"],"v":"ade198ac"},{"idioma":"fr","id":"fr-u198","tipo":"frase","requer":"fr-p139","fr":"Une minute, s'il vous plaît.","en":"One minute, please.","aceitasEn":["one minute please","just a minute please","one moment please","just a moment please","wait a minute please"],"distratoresEn":["One glass, please.","One ticket, please.","One receipt, please.","One fork, please."],"nivel":"A1","tags":["cotidiano","social"],"notaEn":"«Minute» is feminine: «une minute». To ask someone to hang on, you can also say «un instant» or «une seconde».","requerTodas":["fr-p139"],"v":"28e2a1c2"},{"idioma":"fr","id":"fr-u199","tipo":"frase","requer":"fr-p168","fr":"Je meurs de faim !","en":"I'm starving!","aceitasEn":["im starving","i am starving","im dying of hunger","im so hungry","im really hungry","im famished"],"distratoresEn":["I'm so sleepy!","I'm freezing!","I'm boiling!","I'm dying of laughter!"],"nivel":"A1","tags":["comida","expressão"],"notaEn":"French exaggerates with «mourir de», to die of: «je meurs de faim», I'm starving; «je meurs de froid», I'm freezing. Present: je meurs, nous mourons, ils meurent.","requerTodas":["fr-p168","fr-p086"],"v":"c56ed9d5"},{"idioma":"fr","id":"fr-u200","tipo":"frase","requer":"fr-p004","fr":"Ça fait longtemps !","en":"Long time no see!","aceitasEn":["long time no see","its been a long time","it has been a long time","its been a while","it has been a while","long time"],"distratoresEn":["That took forever!","What a surprise!","Just in time!","What nice weather!"],"nivel":"A1","tags":["social","expressão"],"notaEn":"«Ça fait longtemps», it's been a long time, is the greeting for someone you haven't seen in ages. «Longtemps», a long time, is one word.","requerTodas":["fr-p004","fr-p230"],"v":"d4ade9c2"},{"idioma":"fr","id":"fr-u201","tipo":"frase","requer":"fr-p003","fr":"Je vais bien.","en":"I'm fine.","aceitasEn":["im fine","i am fine","im good","im well","i am well","im ok","im okay","im doing well"],"distratoresEn":["I'm sad.","I'm tired.","I'm busy.","I'm sick."],"nivel":"A1","tags":["social"],"notaEn":"To say how you are, French uses «aller», to go: «je vais bien», I'm fine; «comment vas-tu ?», how are you?","requerTodas":["fr-p003","fr-p044"],"v":"d4c16ef3"},{"idioma":"fr","id":"fr-u202","tipo":"frase","requer":"fr-p070","fr":"Tout va bien.","en":"Everything's fine.","aceitasEn":["everythings fine","everything is fine","everythings ok","everything is ok","everythings okay","its all good","all is well","everything is going well"],"distratoresEn":["Everything's ready.","Everything's wrong.","Everything's quiet.","Everything's clean."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Tout va bien», literally all goes well, is how you reassure someone. «Tout» here stands alone, with no article.","requerTodas":["fr-p070","fr-p003","fr-p044"],"v":"b793e6a2"},{"idioma":"fr","id":"fr-u203","tipo":"frase","requer":"fr-p131","fr":"Vous avez une carte de la ville ?","aceitasFr":["Vous avez un plan de la ville ?","Avez-vous une carte de la ville ?"],"en":"Do you have a map of the city?","aceitasEn":["do you have a map of the city","do you have a city map","have you got a map of the city","do you have a map of the town","do you have a town map"],"distratoresEn":["Do you have a photo of the city?","Do you have a drawing of the city?","Do you have a model of the city?","Do you have a brochure of the city?"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"«La carte» means a map, a card and a menu. A street map of a city is also «le plan».","requerTodas":["fr-p002","fr-p131","fr-p028"],"v":"785c112f"},{"idioma":"fr","id":"fr-u204","tipo":"frase","requer":"fr-p131","fr":"La carte, s'il vous plaît.","en":"The menu, please.","aceitasEn":["the menu please","can i see the menu please","could we have the menu please","menu please","can we have the menu please"],"distratoresEn":["The salt, please.","The change, please.","The receipt, please.","The waiter, please."],"nivel":"A1","tags":["comida"],"notaEn":"In a restaurant, «la carte» is the menu; «le menu» is the set menu at a fixed price.","requerTodas":["fr-p131"],"v":"18ada5fc"},{"idioma":"fr","id":"fr-u205","tipo":"frase","requer":"fr-p183","fr":"J'aime voyager en avion.","en":"I like traveling by plane.","aceitasEn":["i like traveling by plane","i like to travel by plane","i love traveling by plane","i like travelling by plane","i like flying","i like to fly"],"distratoresEn":["I like traveling by train.","I like traveling by car.","I like traveling by bus.","I like traveling by boat."],"nivel":"A1","tags":["viagem"],"notaEn":"By plane is «en avion», like «en train», «en voiture». On foot and by bike take «à»: «à pied», «à vélo».","requerTodas":["fr-p015","fr-p183","fr-p231"],"v":"22ea3982"},{"idioma":"fr","id":"fr-u206","tipo":"frase","requer":"fr-p173","fr":"Elle porte une robe rouge.","en":"She's wearing a red dress.","aceitasEn":["shes wearing a red dress","she is wearing a red dress","she wears a red dress","shes got a red dress on","she has a red dress on"],"distratoresEn":["She's wearing a blue dress.","She's wearing a green dress.","She's wearing a black dress.","She's wearing a white dress."],"nivel":"A1","tags":["roupa"],"notaEn":"To wear is «porter»: «elle porte une robe rouge». Colors go after the noun and agree: «une robe verte»; «rouge» stays the same.","requerTodas":["fr-p232","fr-p142","fr-p173"],"v":"1ec8f488"},{"idioma":"fr","id":"fr-u207","tipo":"frase","requer":"fr-p163","fr":"Bonnes vacances !","en":"Have a good vacation!","aceitasEn":["have a good vacation","have a nice vacation","enjoy your vacation","have a great vacation","have a good holiday","enjoy your holiday"],"distratoresEn":["Have a good trip!","Have a good rest!","Have a good weekend!","Have a good stay!"],"nivel":"A1","tags":["viagem","social"],"notaEn":"«Les vacances» is always plural, so the adjective is too: «bonnes vacances».","requerTodas":["fr-p036","fr-p163"],"v":"015d990b"},{"idioma":"fr","id":"fr-u208","tipo":"frase","requer":"fr-p163","fr":"Je suis en vacances.","en":"I'm on vacation.","aceitasEn":["im on vacation","i am on vacation","im on holiday","i am on holiday"],"distratoresEn":["I'm on call.","I'm grounded.","I'm on my way out.","I'm moving."],"nivel":"A1","tags":["viagem"],"notaEn":"To be on vacation is «être en vacances», with «en»; to go on vacation is «partir en vacances».","requerTodas":["fr-p001","fr-p163"],"v":"514737eb"},{"idioma":"fr","id":"fr-u209","tipo":"frase","requer":"fr-p154","fr":"Je veux faire le tour du monde.","en":"I want to go around the world.","aceitasEn":["i want to go around the world","i want to travel around the world","i want to travel the world","i want to go round the world"],"distratoresEn":["I want to go around the city.","I want to go around the island.","I want to go around the lake.","I want to go around the block."],"nivel":"A1","tags":["viagem"],"notaEn":"To go around is «faire le tour»: «faire le tour du monde», «faire le tour du quartier». «Le monde» is the world; «tout le monde», everyone.","requerTodas":["fr-p007","fr-p004","fr-p233","fr-p154"],"v":"33e6aabf"},{"idioma":"fr","id":"fr-u210","tipo":"frase","requer":"fr-p084","fr":"Le musée est fermé le lundi.","en":"The museum is closed on Mondays.","aceitasEn":["the museum is closed on mondays","the museum closes on mondays","the museums closed on mondays","the museum is closed mondays"],"distratoresEn":["The museum is closed on Saturdays.","The museum is closed on Tuesdays.","The museum is closed on Sundays.","The museum is closed on Fridays."],"nivel":"A1","tags":["cultura","cidade"],"notaEn":"With «le», a weekday becomes a habit: «le lundi», on Mondays. French weekdays are masculine and lowercase.","requerTodas":["fr-p234","fr-p001","fr-p206","fr-p084"],"v":"a5ce9249"},{"idioma":"fr","id":"fr-u211","tipo":"frase","requer":"fr-p144","fr":"Il fait la tête.","en":"He's sulking.","aceitasEn":["hes sulking","he is sulking","hes in a sulk","hes pouting","he is pouting"],"distratoresEn":["He has a migraine.","He's downcast.","He's thoughtful.","He's distracted."],"nivel":"A2","tags":["expressão","social"],"notaEn":"«Faire la tête» is to sulk, to give someone the silent treatment. It has nothing to do with a headache, which is «avoir mal à la tête».","requerTodas":["fr-p004","fr-p144"],"v":"f1b561f3"},{"idioma":"fr","id":"fr-u212","tipo":"frase","requer":"fr-p160","fr":"Hier soir, je suis sorti avec des amis.","aceitasFr":["Hier soir, je suis sortie avec des amis.","Je suis sorti avec des amis hier soir.","Je suis sortie avec des amis hier soir."],"en":"Last night I went out with some friends.","aceitasEn":["last night i went out with some friends","last night i went out with friends","i went out with some friends last night","i went out with friends last night","yesterday evening i went out with some friends"],"distratoresEn":["Yesterday morning I went out with some friends.","Yesterday afternoon I went out with some friends.","The day before yesterday I went out with some friends.","On Saturday night I went out with some friends."],"nivel":"A1","tags":["social","cotidiano"],"notaEn":"Last night is «hier soir», with no preposition; tomorrow morning, «demain matin». «Sortir» takes «être» in the passé composé.","requerTodas":["fr-p125","fr-p160","fr-p001","fr-p108","fr-p024"],"v":"bcbc56a4"},{"idioma":"fr","id":"fr-u213","tipo":"frase","requer":"fr-p153","fr":"Je pars demain matin.","en":"I'm leaving tomorrow morning.","aceitasEn":["im leaving tomorrow morning","i am leaving tomorrow morning","ill leave tomorrow morning","i leave tomorrow morning","im off tomorrow morning"],"distratoresEn":["I'm leaving tomorrow afternoon.","I'm leaving tomorrow night.","I'm leaving this morning.","I'm leaving Sunday morning."],"nivel":"A1","tags":["viagem","cotidiano"],"notaEn":"Tomorrow morning is «demain matin», with no preposition, like «hier soir». «Partir» is to leave.","requerTodas":["fr-p083","fr-p059","fr-p153"],"v":"83bb0a08"},{"idioma":"fr","id":"fr-u214","tipo":"frase","requer":"fr-p153","fr":"Le matin, je bois un jus d'orange.","aceitasFr":["Le matin, je prends un jus d'orange."],"en":"In the morning I have an orange juice.","aceitasEn":["in the morning i have an orange juice","in the morning i drink orange juice","i drink orange juice in the morning","i have orange juice in the morning","in the morning i have orange juice","in the mornings i drink orange juice","in the morning i drink an orange juice"],"distratoresEn":["In the afternoon I have an orange juice.","In the evening I have an orange juice.","At lunch I have an orange juice.","On Sundays I have an orange juice."],"nivel":"A1","tags":["comida","cotidiano"],"notaEn":"«Le matin», with the article, means in the morning, every morning. Orange juice is «jus d'orange», with «de» and no article.","requerTodas":["fr-p153","fr-p014","fr-p235","fr-p236"],"v":"8ed7df11"},{"idioma":"fr","id":"fr-u215","tipo":"frase","requer":"fr-p030","fr":"Il fait déjà nuit.","en":"It's already dark.","aceitasEn":["its already dark","it is already dark","its dark already","it is already night","its already night","its already nighttime"],"distratoresEn":["It's already light.","It's already cold.","It's already late.","It's already hot."],"nivel":"A1","tags":["natureza","cotidiano"],"notaEn":"Darkness, like the weather, takes «faire»: «il fait nuit», it's dark; «il fait jour», it's light.","requerTodas":["fr-p004","fr-p050","fr-p030"],"v":"d3961b05"},{"idioma":"fr","id":"fr-u216","tipo":"frase","requer":"fr-p037","fr":"Vous avez une taille plus grande ?","aceitasFr":["Vous avez la taille au-dessus ?"],"en":"Do you have a bigger size?","aceitasEn":["do you have a bigger size","do you have this in a bigger size","do you have a larger size","have you got a bigger size"],"distratoresEn":["Do you have a smaller size?","Do you have a looser size?","Do you have a tighter size?","Do you have a shorter size?"],"nivel":"A1","tags":["compras","roupa"],"notaEn":"In a clothing store, «la taille» is the size; for shoes, it's «la pointure». Bigger is «plus grand», feminine here because of «taille»: «plus grande».","requerTodas":["fr-p002","fr-p237","fr-p037"],"v":"0609739b"},{"idioma":"fr","id":"fr-u217","tipo":"frase","requer":"fr-p089","fr":"Le prochain train part à quelle heure ?","aceitasFr":["À quelle heure part le prochain train ?"],"en":"What time does the next train leave?","aceitasEn":["what time does the next train leave","when does the next train leave","at what time does the next train leave","what time is the next train"],"distratoresEn":["What time does the next bus leave?","What time does the next plane leave?","What time does the next subway leave?","What time does the next boat leave?"],"nivel":"A1","tags":["viagem"],"notaEn":"«Prochain», next, goes before the noun: «le prochain train». With days and weeks it goes after: «lundi prochain», «la semaine prochaine».","requerTodas":["fr-p238","fr-p089","fr-p083","fr-p129"],"v":"b13e2481"},{"idioma":"fr","id":"fr-u218","tipo":"frase","requer":"fr-p003","fr":"Allez tout droit.","en":"Go straight ahead.","aceitasEn":["go straight ahead","go straight","keep going straight","go straight on","continue straight ahead"],"distratoresEn":["Turn right.","Turn left.","Go back.","Stop here."],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"Straight ahead is «tout droit». To the right is «à droite»: don't mix up «droit», straight, and «droite», right.","requerTodas":["fr-p003","fr-p239"],"v":"eba72622"},{"idioma":"fr","id":"fr-u219","tipo":"frase","requer":"fr-p032","fr":"C'est la deuxième rue à gauche.","en":"It's the second street on the left.","aceitasEn":["its the second street on the left","its the second street to the left","second street on the left","its the second left"],"distratoresEn":["It's the second avenue on the left.","It's the second square on the left.","It's the second corner on the left.","It's the second exit on the left."],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"Left is «la gauche»: «à gauche». Ordinals add «-ième»: «deuxième», «troisième»; only first is different, «premier».","requerTodas":["fr-p001","fr-p240","fr-p032","fr-p241"],"v":"0378c772"},{"idioma":"fr","id":"fr-u220","tipo":"frase","requer":"fr-p011","fr":"Je vais prendre un thé.","en":"I'll have a tea.","aceitasEn":["ill have a tea","ill have tea","ill have some tea","i will have a tea","i will have tea","im going to have a tea","ill take a tea"],"distratoresEn":["I'll have a juice.","I'll have a wine.","I'll have an ice cream.","I'll have a soda."],"nivel":"A1","tags":["comida"],"notaEn":"Ordering in a café or restaurant uses «prendre»: «je vais prendre un thé», I'll have a tea. The «h» of «thé» is silent.","requerTodas":["fr-p003","fr-p011","fr-p242"],"v":"db674d90"},{"idioma":"fr","id":"fr-u221","tipo":"frase","requer":"fr-p017","fr":"Je travaille de chez moi.","en":"I work from home.","aceitasEn":["i work from home","i work at home","im working from home","i am working from home"],"distratoresEn":["I work near home.","I work far from home.","I work away from home.","I work around the corner."],"nivel":"A1","tags":["trabalho","casa"],"notaEn":"At someone's place is «chez»: «chez moi», at my place; «chez Paul», at Paul's. Working from home is «travailler de chez soi».","requerTodas":["fr-p017"],"v":"c7607880"},{"idioma":"fr","id":"fr-u222","tipo":"frase","requer":"fr-p147","fr":"Chut, le bébé dort !","en":"Shh, the baby's sleeping!","aceitasEn":["shh the babys sleeping","shh the baby is sleeping","shh the babys asleep","shh the baby is asleep","quiet the baby is sleeping"],"distratoresEn":["Shh, Grandpa's sleeping!","Shh, Dad's sleeping!","Shh, the dog's sleeping!","Shh, the cat's sleeping!"],"nivel":"A1","tags":["família","casa"],"notaEn":"«Chut !» is French for shh. «Le bébé» is always masculine, even for a baby girl.","requerTodas":["fr-p243","fr-p147","fr-p109"],"v":"e8ce2566"},{"idioma":"fr","id":"fr-u223","tipo":"frase","requer":"fr-p180","fr":"Il est tard, je rentre.","en":"It's late, I'm going home.","aceitasEn":["its late im going home","it is late im going home","its late im heading home","its getting late im going home","its late ill go home","it is late i am going home"],"distratoresEn":["It's cold, I'm going home.","It's dark, I'm going home.","It's early, I'm going home.","It's crowded, I'm going home."],"nivel":"A1","tags":["casa","cotidiano"],"notaEn":"It's late is «il est tard», with «être», like telling the time. Late for something is «en retard».","requerTodas":["fr-p001","fr-p180","fr-p071"],"v":"7f7c29ec"},{"idioma":"fr","id":"fr-u224","tipo":"frase","requer":"fr-p181","fr":"Il est encore tôt.","en":"It's still early.","aceitasEn":["its still early","it is still early","its early still","its early yet"],"distratoresEn":["It's still daytime.","It's still night.","It's still Monday.","It's still summer."],"nivel":"A1","tags":["cotidiano"],"notaEn":"Early is «tôt», with a silent final «t». «Encore» here means still; not yet is «pas encore».","requerTodas":["fr-p001","fr-p202","fr-p181"],"v":"fadea2e6"},{"idioma":"fr","id":"fr-u225","tipo":"frase","requer":"fr-p019","fr":"On est quel jour aujourd'hui ?","aceitasFr":["Quel jour sommes-nous ?","Quel jour sommes-nous aujourd'hui ?","On est quel jour ?","Quel jour on est aujourd'hui ?"],"en":"What day is today?","aceitasEn":["what day is today","what day is it today","what day is it"],"distratoresEn":["What game is today?","What class is today?","What test is today?","What holiday is today?"],"nivel":"A1","tags":["cotidiano"],"notaEn":"In speech it's «on est quel jour ?», literally we are which day; more formally, «quel jour sommes-nous ?».","requerTodas":["fr-p001","fr-p019","fr-p049"],"v":"8a0034e1"},{"idioma":"fr","id":"fr-u226","tipo":"frase","requer":"fr-p167","fr":"J'ai mis une heure pour venir.","en":"It took me an hour to get here.","aceitasEn":["it took me an hour to get here","it took me an hour to come","it took me one hour to get here","i took an hour to get here"],"distratoresEn":["I walked an hour to get here.","I drove an hour to get here.","I biked an hour to get here.","I ran an hour to get here."],"nivel":"A2","tags":["viagem","cotidiano"],"notaEn":"«Mettre» + a length of time means it took: «j'ai mis une heure», it took me an hour. The participle is irregular: «mis».","requerTodas":["fr-p002","fr-p167","fr-p129","fr-p009"],"v":"784bcac2"},{"idioma":"fr","id":"fr-u227","tipo":"frase","requer":"fr-p118","fr":"Je cherche une pharmacie.","en":"I'm looking for a pharmacy.","aceitasEn":["im looking for a pharmacy","i am looking for a pharmacy","im looking for a drugstore","i am looking for a drugstore","im looking for a chemist"],"distratoresEn":["I'm looking for a bakery.","I'm looking for a school.","I'm looking for a beach.","I'm looking for a church."],"nivel":"A1","tags":["saúde","cidade"],"notaEn":"French pharmacies have a green cross outside. To look for is «chercher», with no «for»; to find is «trouver».","requerTodas":["fr-p118","fr-p244"],"v":"31ab106f"},{"idioma":"fr","id":"fr-u228","tipo":"frase","requer":"fr-p048","fr":"Il y a une boulangerie près d'ici ?","aceitasFr":["Est-ce qu'il y a une boulangerie près d'ici ?","Y a-t-il une boulangerie près d'ici ?"],"en":"Is there a bakery near here?","aceitasEn":["is there a bakery near here","is there a bakery nearby","is there a bakery around here","is there a bakery close by"],"distratoresEn":["Is there a laundromat near here?","Is there a bookstore near here?","Is there a stationery store near here?","Is there an ice cream shop near here?"],"nivel":"A1","tags":["compras","cidade"],"notaEn":"«La boulangerie» is the bakery, where you buy «la baguette». Near is «près», and near here, «près d'ici».","requerTodas":["fr-p002","fr-p245","fr-p246","fr-p048"],"v":"303ebc79"},{"idioma":"fr","id":"fr-u229","tipo":"frase","requer":"fr-p064","fr":"Il est midi.","en":"It's noon.","aceitasEn":["its noon","it is noon","its twelve oclock","its midday","it is twelve","its twelve noon"],"distratoresEn":["It's midnight.","It's one in the afternoon.","It's lunchtime.","It's half past twelve."],"nivel":"A1","tags":["cotidiano"],"notaEn":"Noon is «midi», no article: «il est midi». Midnight is «minuit». «Le Midi», capitalized, is also the south of France.","requerTodas":["fr-p001","fr-p064"],"v":"fce93c00"},{"idioma":"fr","id":"fr-u230","tipo":"frase","requer":"fr-p164","fr":"La gare est loin d'ici ?","aceitasFr":["Est-ce que la gare est loin d'ici ?"],"en":"Is the station far from here?","aceitasEn":["is the station far from here","is the train station far from here","is the station far"],"distratoresEn":["Is the station near here?","Is the station on the right?","Is the station on the left?","Is the station down there?"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"Far from is «loin de», and «de» shortens to «d'» before a vowel: «loin d'ici». Near is «près de».","requerTodas":["fr-p188","fr-p001","fr-p164","fr-p048"],"v":"d52073dd"},{"idioma":"fr","id":"fr-u231","tipo":"frase","requer":"fr-p164","fr":"Mes parents habitent loin.","en":"My parents live far away.","aceitasEn":["my parents live far away","my parents live far","my parents live far from here","my parents live a long way away"],"distratoresEn":["My parents live nearby.","My parents live together.","My parents live alone.","My parents live abroad."],"nivel":"A1","tags":["família","casa"],"notaEn":"«Les parents» are your parents — and also relatives in general. Far away is «loin»; far from, «loin de».","requerTodas":["fr-p247","fr-p016","fr-p164"],"v":"a44a3c12"},{"idioma":"fr","id":"fr-u232","tipo":"frase","requer":"fr-p044","fr":"Je ne me sens pas bien.","en":"I don't feel well.","aceitasEn":["i dont feel well","i do not feel well","im not feeling well","i am not feeling well","i dont feel good"],"distratoresEn":["I don't feel lonely.","I don't feel tired.","I don't feel better.","I don't feel comfortable."],"nivel":"A1","tags":["saúde"],"notaEn":"To feel is «se sentir»: «je me sens bien», I feel fine. Present: je me sens, tu te sens, il se sent.","requerTodas":["fr-p248","fr-p044"],"v":"311b31c1"},{"idioma":"fr","id":"fr-u233","tipo":"frase","requer":"fr-p176","fr":"Ne te couche pas trop tard !","en":"Don't go to bed too late!","aceitasEn":["dont go to bed too late","do not go to bed too late","dont stay up too late"],"distratoresEn":["Don't have dinner too late!","Don't go out too late!","Don't get home too late!","Don't get up too late!"],"nivel":"A1","tags":["casa","gramática"],"notaEn":"In a negative command, the pronoun moves back before the verb: «couche-toi», go to bed, but «ne te couche pas», don't go to bed.","requerTodas":["fr-p176","fr-p061","fr-p180"],"v":"885c59aa"},{"idioma":"fr","id":"fr-u234","tipo":"frase","requer":"fr-p023","fr":"Ils ont deux enfants.","aceitasFr":["Elles ont deux enfants."],"en":"They have two children.","aceitasEn":["they have two children","they have two kids","theyve got two kids","they have got two children","they have 2 children","theyve got two children"],"distratoresEn":["They have two grandchildren.","They have two nephews.","They have two brothers.","They have two cousins."],"nivel":"A1","tags":["família"],"notaEn":"«L'enfant» means child, including someone's child: «ils ont deux enfants». A son is «le fils».","requerTodas":["fr-p002","fr-p120","fr-p023"],"v":"9e807bb0"},{"idioma":"fr","id":"fr-u235","tipo":"frase","requer":"fr-p152","fr":"Je te présente mon mari.","aceitasFr":["Je vous présente mon mari."],"en":"This is my husband.","aceitasEn":["this is my husband","let me introduce my husband","id like you to meet my husband","meet my husband","i want you to meet my husband"],"distratoresEn":["This is my brother.","This is my father.","This is my boss.","This is my neighbor."],"nivel":"A1","tags":["família","social"],"notaEn":"To introduce someone: «je te présente», or more formally «je vous présente». «Mon mari», my husband; «ma femme», my wife.","requerTodas":["fr-p249","fr-p152"],"v":"a3cbb5ab"},{"idioma":"fr","id":"fr-u236","tipo":"frase","requer":"fr-p004","fr":"Qu'est-ce que vous faites dans la vie ?","aceitasFr":["Qu'est-ce que tu fais dans la vie ?","Que faites-vous dans la vie ?"],"en":"What do you do for a living?","aceitasEn":["what do you do for a living","what is your job","whats your job","what line of work are you in","what do you do for work"],"distratoresEn":["What do you do on weekends?","What do you do on vacation?","What do you do in the morning?","What do you do for dinner?"],"nivel":"A1","tags":["trabalho","social"],"notaEn":"The polite way to ask someone's job, literally what do you do in life. With «tu», «qu'est-ce que tu fais dans la vie ?».","requerTodas":["fr-p004","fr-p250"],"v":"589db7fb"},{"idioma":"fr","id":"fr-u237","tipo":"frase","requer":"fr-p002","fr":"J'ai de la fièvre.","en":"I have a fever.","aceitasEn":["i have a fever","ive got a fever","i have got a fever","i have a temperature","ive got a temperature","im running a fever","i am running a fever"],"distratoresEn":["I have a cough.","I'm thirsty.","I'm sleepy.","I have the flu."],"nivel":"A1","tags":["saúde"],"notaEn":"French uses «avoir», to have, for many states: «j'ai de la fièvre», «j'ai faim», «j'ai soif». Fever takes the partitive, «de la».","requerTodas":["fr-p002","fr-p251"],"v":"15a792b9"},{"idioma":"fr","id":"fr-u238","tipo":"frase","requer":"fr-p060","fr":"J'ai raté le bus.","aceitasFr":["J'ai manqué le bus."],"en":"I missed the bus.","aceitasEn":["i missed the bus","ive missed the bus","i have missed the bus"],"distratoresEn":["I missed the train.","I missed the subway.","I missed the plane.","I missed the boat."],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"To miss the bus is «rater le bus» (or «manquer le bus»); «perdre» is to lose something: «j'ai perdu mes clés».","requerTodas":["fr-p002","fr-p252","fr-p060"],"v":"bf69b066"},{"idioma":"fr","id":"fr-u239","tipo":"frase","requer":"fr-p101","fr":"Un ticket de métro, s'il vous plaît.","en":"A subway ticket, please.","aceitasEn":["a subway ticket please","one subway ticket please","a metro ticket please","a ticket for the subway please","one metro ticket please","an underground ticket please","a tube ticket please"],"distratoresEn":["A bus ticket, please.","A train ticket, please.","A movie ticket, please.","A museum ticket, please."],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"A subway or bus ticket is «le ticket»; a train, plane or concert ticket is «le billet».","requerTodas":["fr-p253","fr-p101"],"v":"50b3383b"},{"idioma":"fr","id":"fr-u240","tipo":"frase","requer":"fr-p001","fr":"Je suis en avance.","en":"I'm early.","aceitasEn":["im early","i am early","im ahead of time","i got here early"],"distratoresEn":["I'm late.","I'm busy.","I'm ready.","I'm alone."],"nivel":"A1","tags":["cotidiano"],"notaEn":"Early, ahead of time, is «en avance»; late, «en retard»; on time, «à l'heure».","requerTodas":["fr-p001","fr-p254"],"v":"da266175"},{"idioma":"fr","id":"fr-u241","tipo":"frase","requer":"fr-p049","fr":"Il y a du vent aujourd'hui.","aceitasFr":["Aujourd'hui, il y a du vent."],"en":"It's windy today.","aceitasEn":["its windy today","it is windy today","today its windy","its windy"],"distratoresEn":["It's rainy today.","It's cloudy today.","It's snowy today.","It's muggy today."],"nivel":"A1","tags":["natureza"],"notaEn":"Wind and sun take «il y a»: «il y a du vent», «il y a du soleil». Cold and heat take «il fait».","requerTodas":["fr-p002","fr-p255","fr-p049"],"v":"1e854b59"},{"idioma":"fr","id":"fr-u242","tipo":"frase","requer":"fr-p179","fr":"Mon fils a six ans.","en":"My son is six.","aceitasEn":["my son is six","my son is six years old","my son is 6","my son is 6 years old","my sons six"],"distratoresEn":["My son is seven.","My son is eight.","My son is ten.","My son is three."],"nivel":"A1","tags":["família"],"notaEn":"Age is something you have: «il a six ans», and «ans» can't be dropped. In «fils» the «l» is silent and the «s» is pronounced: «feess».","requerTodas":["fr-p256","fr-p002","fr-p179","fr-p052"],"v":"9a0167be"},{"idioma":"fr","id":"fr-u243","tipo":"frase","requer":"fr-p169","fr":"Ouvrez vos livres à la page dix.","en":"Open your books to page ten.","aceitasEn":["open your books to page ten","open your books at page ten","open your books on page ten","open your books to page 10"],"distratoresEn":["Open your books to page six.","Open your books to page eight.","Open your books to page seven.","Open your books to page three."],"nivel":"A1","tags":["escola"],"notaEn":"On page ten is «à la page dix». The «vous» imperative is just the present without the pronoun: «vous ouvrez», «ouvrez».","requerTodas":["fr-p169","fr-p033","fr-p257","fr-p121"],"v":"b84ad0ce"},{"idioma":"fr","id":"fr-u244","tipo":"frase","requer":"fr-p001","fr":"Où est la caisse ?","en":"Where's the checkout?","aceitasEn":["wheres the checkout","where is the checkout","where is the register","wheres the cash register","where do i pay","where is the cash desk"],"distratoresEn":["Where's the elevator?","Where's the fitting room?","Where's the parking lot?","Where's the exit?"],"nivel":"A1","tags":["compras"],"notaEn":"In a store, «la caisse» is the checkout; the person working it is «le caissier» or «la caissière».","requerTodas":["fr-p001","fr-p258"],"v":"28e2392b"},{"idioma":"fr","id":"fr-u245","tipo":"frase","requer":"fr-p007","fr":"Je voudrais un kilo de tomates.","en":"I'd like a kilo of tomatoes.","aceitasEn":["id like a kilo of tomatoes","i would like a kilo of tomatoes","can i have a kilo of tomatoes","a kilo of tomatoes please","id like one kilo of tomatoes"],"distratoresEn":["I'd like a kilo of onions.","I'd like a kilo of carrots.","I'd like a kilo of oranges.","I'd like a kilo of apples."],"nivel":"A1","tags":["compras","comida"],"notaEn":"At a market, you order with the conditional of «vouloir»: «je voudrais». After a quantity, just «de», no article: «un kilo de tomates».","requerTodas":["fr-p007","fr-p259","fr-p260"],"v":"6746975b"},{"idioma":"fr","id":"fr-u246","tipo":"frase","requer":"fr-p001","fr":"Je suis en réunion.","en":"I'm in a meeting.","aceitasEn":["im in a meeting","i am in a meeting"],"distratoresEn":["I'm in class.","I'm on a trip.","I'm on strike.","I'm at the doctor's."],"nivel":"A1","tags":["trabalho"],"notaEn":"«La réunion» is a meeting. Being busy with something is «être en»: «en réunion», «en vacances», «en cours».","requerTodas":["fr-p001","fr-p261"],"v":"48e63a43"},{"idioma":"fr","id":"fr-u247","tipo":"frase","requer":"fr-p104","fr":"Ma sœur est mariée.","en":"My sister is married.","aceitasEn":["my sister is married","my sisters married"],"distratoresEn":["My cousin is married.","My aunt is married.","My daughter is married.","My neighbor is married."],"nivel":"A1","tags":["família"],"notaEn":"«Marié» agrees: «il est marié», «elle est mariée». To get married is «se marier», to someone «se marier avec».","requerTodas":["fr-p104","fr-p001","fr-p262"],"v":"dc0a353c"},{"idioma":"fr","id":"fr-u248","tipo":"frase","requer":"fr-p124","fr":"Mon chef est très gentil.","en":"My boss is very nice.","aceitasEn":["my boss is very nice","my boss is really nice","my boss is very kind","my boss is really kind"],"distratoresEn":["My boss is very demanding.","My boss is very serious.","My boss is very annoying.","My boss is very young."],"nivel":"A1","tags":["trabalho"],"notaEn":"«Gentil» means nice or kind, not gentle. «Le chef» is the boss — and also the head chef.","requerTodas":["fr-p263","fr-p001","fr-p043","fr-p124"],"v":"6df0b2e7"},{"idioma":"fr","id":"fr-u249","tipo":"frase","requer":"fr-p059","fr":"J'ai un examen demain.","en":"I have a test tomorrow.","aceitasEn":["i have a test tomorrow","i have an exam tomorrow","ive got a test tomorrow","ive got an exam tomorrow","i have got an exam tomorrow"],"distratoresEn":["I have a test today.","I have a test on Friday.","I have a test the day after tomorrow.","I have a test next week."],"nivel":"A1","tags":["escola"],"notaEn":"A test is «l'examen» or, a smaller one, «le contrôle». «Passer un examen» just means to take it; to pass is «réussir».","requerTodas":["fr-p002","fr-p264","fr-p059"],"v":"1bf5d9ef"},{"idioma":"fr","id":"fr-u250","tipo":"frase","requer":"fr-p082","fr":"Je dois prendre ce médicament.","en":"I have to take this medicine.","aceitasEn":["i have to take this medicine","i have to take this medication","i need to take this medicine","i must take this medicine","ive got to take this medicine"],"distratoresEn":["I can take this medicine.","I want to take this medicine.","I'm going to take this medicine.","I'd rather take this medicine."],"nivel":"A1","tags":["saúde"],"notaEn":"Medicine is «le médicament»; taking it is «prendre». «Devoir» + infinitive means to have to.","requerTodas":["fr-p082","fr-p011","fr-p265"],"v":"325dfd3f"},{"idioma":"fr","id":"fr-u251","tipo":"frase","requer":"fr-p011","fr":"On prend l'ascenseur ?","en":"Shall we take the elevator?","aceitasEn":["shall we take the elevator","should we take the elevator","lets take the elevator","shall we take the lift","do we take the elevator"],"distratoresEn":["Shall we take the subway?","Shall we take the bus?","Shall we take the taxi?","Shall we take the train?"],"nivel":"A1","tags":["cidade","casa"],"notaEn":"Taking the elevator, the bus or the subway is always «prendre». The stairs are «l'escalier».","requerTodas":["fr-p011","fr-p266"],"v":"7caeabd4"},{"idioma":"fr","id":"fr-u252","tipo":"frase","requer":"fr-p040","fr":"Il fait beau, on va au parc ?","en":"The weather's nice, shall we go to the park?","aceitasEn":["the weathers nice shall we go to the park","its nice out shall we go to the park","the weather is nice shall we go to the park","its a nice day shall we go to the park","its nice outside lets go to the park"],"distratoresEn":["The weather's cool, shall we go to the park?","The weather's cloudy, shall we go to the park?","The weather's hot, shall we go to the park?","The weather's cold, shall we go to the park?"],"nivel":"A1","tags":["natureza","cidade"],"notaEn":"«Il fait beau» is nice weather; bad weather is «il fait mauvais». «On va au parc ?», with «on», is the casual shall we.","requerTodas":["fr-p004","fr-p040","fr-p003","fr-p267"],"v":"54b8ab8a"},{"idioma":"fr","id":"fr-v055","tipo":"frase","fr":"Elle est arrivée en retard.","en":"She arrived late.","aceitasEn":["she arrived late","she got here late","she came late","she showed up late","she got there late"],"distratoresEn":["She arrives late.","She used to arrive late.","She'll arrive late.","She would arrive late."],"formasFr":{"Elle arrive en retard":"present","Elle arrivait en retard":"imperfect","Elle arrivera en retard":"future","Elle arriverait en retard":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","viagem"],"notaEn":"«Arriver» takes «être» in the passé composé, and the participle agrees with the subject: «il est arrivé», «elle est arrivée», «ils sont arrivés».","requerTodas":["fr-p001","fr-p115","fr-p085"],"v":"73d8547f"},{"idioma":"fr","id":"fr-v056","tipo":"frase","fr":"Elle est née en France.","en":"She was born in France.","aceitasEn":["she was born in france"],"distratoresEn":["She's born in France.","She was being born in France.","She'll be born in France.","She would be born in France."],"formasFr":{"Elle naît en France":"present","Elle naissait en France":"imperfect","Elle naîtra en France":"future","Elle naîtrait en France":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","irregular","família"],"notaEn":"To be born is the single verb «naître», which takes «être» in the passé composé: «je suis né», «elle est née». Years take «en»: «née en 1990».","requerTodas":["fr-p001","fr-p268"],"v":"bf63ba65"},{"idioma":"fr","id":"fr-v057","tipo":"frase","fr":"Elles sont restées à la maison.","en":"They stayed home.","aceitasEn":["they stayed home","they stayed at home","theyve stayed home","they have stayed at home"],"distratoresEn":["They stay home.","They used to stay home.","They'll stay home.","They'd stay home."],"formasFr":{"Elles restent à la maison":"present","Elles restaient à la maison":"imperfect","Elles resteront à la maison":"future","Elles resteraient à la maison":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","casa"],"notaEn":"«Rester» means to stay, not to rest. It takes «être», so with «elles» the participle adds «-es»: «elles sont restées».","requerTodas":["fr-p001","fr-p269","fr-p020"],"v":"2b3c9a9d"},{"idioma":"fr","id":"fr-v058","tipo":"frase","fr":"Elle était très fatiguée.","en":"She was very tired.","aceitasEn":["she was very tired","she was really tired"],"distratoresEn":["She's very tired.","She'll be very tired.","She'd be very tired.","She had been very tired."],"formasFr":{"Elle est très fatiguée":"present","Elle sera très fatiguée":"future","Elle serait très fatiguée":"conditional","Elle avait été très fatiguée":"pluperfect"},"nivel":"A1","tags":["conjugação","imperfeito","irregular","saúde"],"notaEn":"Imperfect of «être»: j'étais, tu étais, il était, nous étions, vous étiez, ils étaient. Only the stem «ét-» is irregular; the endings are the usual ones.","requerTodas":["fr-p001","fr-p043","fr-p113"],"v":"39462994"},{"idioma":"fr","id":"fr-v059","tipo":"frase","fr":"Il y avait beaucoup de monde à la plage.","en":"There were a lot of people at the beach.","aceitasEn":["there were a lot of people at the beach","there were lots of people at the beach","there were many people at the beach","there were a lot of people on the beach"],"distratoresEn":["There are a lot of people at the beach.","There will be a lot of people at the beach.","There would be a lot of people at the beach.","There had been a lot of people at the beach."],"formasFr":{"Il y a beaucoup de monde à la plage":"present","Il y aura beaucoup de monde à la plage":"future","Il y aurait beaucoup de monde à la plage":"conditional","Il y avait eu beaucoup de monde à la plage":"pluperfect"},"nivel":"A2","tags":["conjugação","imperfeito","irregular","viagem"],"notaEn":"«Il y a» in the imperfect is «il y avait», there was, there were. People, in this sense, is «du monde»: «beaucoup de monde».","requerTodas":["fr-p002","fr-p067","fr-p154","fr-p087"],"v":"7e1e01b6"},{"idioma":"fr","id":"fr-v060","tipo":"frase","fr":"Ça ne va pas marcher.","aceitasFr":["Ça va pas marcher."],"en":"That won't work.","aceitasEn":["that wont work","that will not work","thats not going to work","that is not going to work","thats not gonna work","that isnt going to work","its not going to work","it wont work"],"distratoresEn":["That doesn't work.","That wasn't working.","That didn't work.","That wouldn't work."],"formasFr":{"Ça ne marche pas":"present","Ça ne marchait pas":"imperfect","Ça n'a pas marché":"passé composé","Ça ne marcherait pas":"conditional"},"nivel":"A2","tags":["conjugação","futuro","regular"],"notaEn":"In the negative near future, «ne… pas» wraps «aller»: «ça ne va pas marcher». «Marcher» means to walk and also to work, to function.","requerTodas":["fr-p003","fr-p270"],"v":"15bd7559"},{"idioma":"fr","id":"fr-v061","tipo":"frase","fr":"Qu'est-ce que tu cherches ?","aceitasFr":["Tu cherches quoi ?"],"en":"What are you looking for?","aceitasEn":["what are you looking for","what are you searching for"],"distratoresEn":["What were you looking for?","What did you look for?","What will you look for?","What would you look for?"],"formasFr":{"Qu'est-ce que tu cherchais":"imperfect","Qu'est-ce que tu as cherché":"passé composé","Qu'est-ce que tu chercheras":"future","Qu'est-ce que tu chercherais":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular"],"notaEn":"Present of «chercher», a regular -er verb: je cherche, tu cherches, il cherche, nous cherchons, vous cherchez, ils cherchent. The «-es» of «tu cherches» is silent.","requerTodas":["fr-p118"],"v":"cd6c7683"},{"idioma":"fr","id":"fr-v062","tipo":"frase","fr":"Je connaissais bien cette ville.","en":"I knew this city well.","aceitasEn":["i knew this city well","i used to know this city well","i knew that city well","i used to know that city well"],"distratoresEn":["I know this city well.","I'll know this city well.","I'd know this city well.","I had known this city well."],"formasFr":{"Je connais bien cette ville":"present","Je connaîtrai bien cette ville":"future","Je connaîtrais bien cette ville":"conditional","J'avais bien connu cette ville":"pluperfect"},"nivel":"A2","tags":["conjugação","imperfeito","irregular","cidade"],"notaEn":"The imperfect comes from the «nous» form of the present: «nous connaissons» gives «je connaissais». The «ss» shows up in the whole plural and the imperfect.","requerTodas":["fr-p119","fr-p044","fr-p028"],"v":"230386fa"},{"idioma":"fr","id":"fr-v063","tipo":"frase","fr":"J'ai fini mes devoirs.","en":"I finished my homework.","aceitasEn":["i finished my homework","ive finished my homework","i have finished my homework","im done with my homework","i am done with my homework"],"distratoresEn":["I'm finishing my homework.","I was finishing my homework.","I'll finish my homework.","I would finish my homework."],"formasFr":{"Je finis mes devoirs":"present","Je finissais mes devoirs":"imperfect","Je finirai mes devoirs":"future","Je finirais mes devoirs":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","escola"],"notaEn":"«Fini» and «finis» sound the same; the «ai» is what separates «j'ai fini» from «je finis». «Les devoirs» is homework.","requerTodas":["fr-p002","fr-p123","fr-p271"],"v":"5cb8d7aa"},{"idioma":"fr","id":"fr-v064","tipo":"frase","fr":"Ils mettent la table.","aceitasFr":["Elles mettent la table."],"en":"They're setting the table.","aceitasEn":["theyre setting the table","they are setting the table"],"distratoresEn":["They used to set the table.","They've set the table.","They'll set the table.","They would set the table."],"formasFr":{"Ils mettaient la table":"imperfect","Ils ont mis la table":"passé composé","Ils mettront la table":"future","Ils mettraient la table":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","casa"],"notaEn":"Present of «mettre»: je mets, tu mets, il met, nous mettons, vous mettez, ils mettent. One «t» in the singular, two in the plural.","requerTodas":["fr-p167","fr-p143"],"v":"78d77dc8"},{"idioma":"fr","id":"fr-v065","tipo":"frase","fr":"On ouvre les cadeaux ?","en":"Shall we open the presents?","aceitasEn":["shall we open the presents","should we open the presents","shall we open the gifts","lets open the presents","should we open the gifts"],"distratoresEn":["Did we use to open the presents?","Did we open the presents?","Would we open the presents?","Had we opened the presents?"],"formasFr":{"On ouvrait les cadeaux":"imperfect","On a ouvert les cadeaux":"passé composé","On ouvrirait les cadeaux":"conditional","On avait ouvert les cadeaux":"pluperfect"},"nivel":"A1","tags":["conjugação","presente","irregular","família"],"notaEn":"In the present, «ouvrir» is conjugated like an -er verb: «on ouvre», «j'ouvre»; the participle is irregular, «ouvert». With «on» and a rising tone, it's a suggestion.","requerTodas":["fr-p169","fr-p272"],"v":"f5d0164a"},{"idioma":"fr","id":"fr-v066","tipo":"frase","fr":"J'ai payé cent euros.","en":"I paid a hundred euros.","aceitasEn":["i paid a hundred euros","i paid one hundred euros","ive paid a hundred euros","i paid 100 euros"],"distratoresEn":["I pay a hundred euros.","I used to pay a hundred euros.","I'll pay a hundred euros.","I would pay a hundred euros."],"formasFr":{"Je paie cent euros":"present","Je payais cent euros":"imperfect","Je paierai cent euros":"future","Je paierais cent euros":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","compras"],"notaEn":"In «payer», the «y» may become «i» before a silent «e»: «je paie» or «je paye», «je paierai». The passé composé keeps it: «j'ai payé».","requerTodas":["fr-p002","fr-p170","fr-p273","fr-p128"],"v":"fde61d21"},{"idioma":"fr","id":"fr-v067","tipo":"frase","fr":"On regardait un film.","en":"We were watching a movie.","aceitasEn":["we were watching a movie","we were watching a film"],"distratoresEn":["We watch a movie.","We watched a movie.","We'll watch a movie.","We had watched a movie."],"formasFr":{"On regarde un film":"present","On a regardé un film":"passé composé","On regardera un film":"future","On avait regardé un film":"pluperfect"},"nivel":"A1","tags":["conjugação","imperfeito","regular","cultura"],"notaEn":"The imperfect describes something in progress: «on regardait un film». The endings are the same for every verb: -ais, -ais, -ait, -ions, -iez, -aient.","requerTodas":["fr-p172","fr-p100"],"v":"e31e1529"},{"idioma":"fr","id":"fr-v068","tipo":"frase","fr":"Mes parents m'écrivent souvent.","en":"My parents often write to me.","aceitasEn":["my parents often write to me","my parents write to me often","my parents write me often","my parents often write me"],"distratoresEn":["My parents used to write to me often.","My parents wrote to me often.","My parents will often write to me.","My parents would often write to me."],"formasFr":{"Mes parents m'écrivaient souvent":"imperfect","Mes parents m'ont souvent écrit":"passé composé","Mes parents m'écriront souvent":"future","Mes parents m'écriraient souvent":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","família"],"notaEn":"In the plural, «écrire» picks up a «v»: nous écrivons, vous écrivez, ils écrivent. Not in the singular: j'écris, tu écris, il écrit.","requerTodas":["fr-p247","fr-p184","fr-p114"],"v":"9fc366ec"},{"idioma":"fr","id":"fr-v069","tipo":"frase","fr":"Ils ont vendu leur maison.","aceitasFr":["Elles ont vendu leur maison."],"en":"They sold their house.","aceitasEn":["they sold their house","theyve sold their house","they have sold their house"],"distratoresEn":["They're selling their house.","They were selling their house.","They'll sell their house.","They would sell their house."],"formasFr":{"Ils vendent leur maison":"present","Ils vendaient leur maison":"imperfect","Ils vendront leur maison":"future","Ils vendraient leur maison":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","casa"],"notaEn":"Verbs in -re like «vendre» form the participle in «-u»: «vendu», «attendu», «perdu». «Leur», their, has no «s» when there's only one thing.","requerTodas":["fr-p002","fr-p182","fr-p020"],"v":"7863eadd"},{"idioma":"fr","id":"fr-v070","tipo":"frase","fr":"Elle voyage beaucoup pour son travail.","en":"She travels a lot for work.","aceitasEn":["she travels a lot for work","she travels a lot for her job","she travels a lot for her work","she does a lot of traveling for work"],"distratoresEn":["She used to travel a lot for work.","She traveled a lot for work.","She'll travel a lot for work.","She would travel a lot for work."],"formasFr":{"Elle voyageait beaucoup pour son travail":"imperfect","Elle a beaucoup voyagé pour son travail":"passé composé","Elle voyagera beaucoup pour son travail":"future","Elle voyagerait beaucoup pour son travail":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular","trabalho","viagem"],"notaEn":"Verbs in «-ger» keep the «e» before «a» and «o» so the «g» stays soft: «nous voyageons», «elle voyageait». In the passé composé, «beaucoup» goes between the helper and the participle: «elle a beaucoup voyagé».","requerTodas":["fr-p183","fr-p067","fr-p029"],"v":"78fa795c"},{"idioma":"fr","id":"fr-v071","tipo":"frase","fr":"Elle s'est levée tard.","en":"She got up late.","aceitasEn":["she got up late","she got out of bed late"],"distratoresEn":["She gets up late.","She used to get up late.","She'll get up late.","She would get up late."],"formasFr":{"Elle se lève tard":"present","Elle se levait tard":"imperfect","Elle se lèvera tard":"future","Elle se lèverait tard":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","pronomes","casa"],"notaEn":"Reflexive verbs take «être» in the passé composé, and the participle agrees: «il s'est levé», «elle s'est levée». Watch the accent: «je me lève», «je me lèverai».","requerTodas":["fr-p001","fr-p177","fr-p180"],"v":"4b0fba2e"},{"idioma":"fr","id":"fr-v072","tipo":"frase","fr":"Je vais me coucher.","en":"I'm going to bed.","aceitasEn":["im going to bed","i am going to bed","im going to go to bed","im off to bed","im heading to bed"],"distratoresEn":["I was going to bed.","I went to bed.","I would go to bed.","I had gone to bed."],"formasFr":{"Je me couchais":"imperfect","Je me suis couché":"passé composé","Je me coucherais":"conditional","Je m'étais couché":"pluperfect"},"nivel":"A1","tags":["conjugação","futuro","regular","pronomes","casa"],"notaEn":"In the near future, the reflexive pronoun sits right before the infinitive: «je vais me coucher», «tu vas te coucher». Negative: «je ne vais pas me coucher».","requerTodas":["fr-p003","fr-p176"],"v":"cfc9e8fc"},{"idioma":"fr","id":"fr-v073","tipo":"frase","fr":"Il a plu toute la nuit.","en":"It rained all night.","aceitasEn":["it rained all night","it rained the whole night","its rained all night","it has rained all night","it rained all night long"],"distratoresEn":["It rains all night.","It'll rain all night.","It would rain all night.","It had rained all night."],"formasFr":{"Il pleut toute la nuit":"present","Il pleuvra toute la nuit":"future","Il pleuvrait toute la nuit":"conditional","Il avait plu toute la nuit":"pluperfect"},"nivel":"A2","tags":["conjugação","pretérito","irregular","natureza"],"notaEn":"The participle of «pleuvoir» is «plu»: «il a plu». All night is «toute la nuit», with «tout» in the feminine.","requerTodas":["fr-p002","fr-p171","fr-p070","fr-p030"],"v":"9c7e8dfc"},{"idioma":"fr","id":"fr-v074","tipo":"frase","fr":"Il faudra partir tôt.","en":"We'll have to leave early.","aceitasEn":["well have to leave early","we will have to leave early","well need to leave early","we will need to leave early","were going to have to leave early","we are going to have to leave early"],"distratoresEn":["We have to leave early.","We had to leave early.","We'd have to leave early.","We had had to leave early."],"formasFr":{"Il faut partir tôt":"present","Il a fallu partir tôt":"passé composé","Il faudrait partir tôt":"conditional","Il avait fallu partir tôt":"pluperfect"},"nivel":"A2","tags":["conjugação","futuro","irregular","viagem"],"notaEn":"«Falloir» only exists with «il»: «il faut», «il fallait», «il a fallu», «il faudra», «il faudrait». The future stem is «faudr-».","requerTodas":["fr-p122","fr-p083","fr-p181"],"v":"1cb9702d"},{"idioma":"fr","id":"fr-v075","tipo":"frase","fr":"J'ai trouvé un bon restaurant.","en":"I found a good restaurant.","aceitasEn":["i found a good restaurant","ive found a good restaurant","i have found a good restaurant"],"distratoresEn":["I find a good restaurant.","I'll find a good restaurant.","I'd find a good restaurant.","I had found a good restaurant."],"formasFr":{"Je trouve un bon restaurant":"present","Je trouverai un bon restaurant":"future","Je trouverais un bon restaurant":"conditional","J'avais trouvé un bon restaurant":"pluperfect"},"nivel":"A1","tags":["conjugação","pretérito","regular","comida"],"notaEn":"«Bon» goes before the noun: «un bon restaurant». To find is «trouver»; to look for, «chercher»: «j'ai cherché et j'ai trouvé».","requerTodas":["fr-p002","fr-p193","fr-p036","fr-p098"],"v":"75536948"},{"idioma":"fr","id":"fr-v076","tipo":"frase","fr":"Elle donne des cours de piano.","en":"She gives piano lessons.","aceitasEn":["she gives piano lessons","she teaches piano","she gives piano classes"],"distratoresEn":["She used to give piano lessons.","She gave piano lessons.","She'll give piano lessons.","She would give piano lessons."],"formasFr":{"Elle donnait des cours de piano":"imperfect","Elle a donné des cours de piano":"passé composé","Elle donnera des cours de piano":"future","Elle donnerait des cours de piano":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular","escola","cultura"],"notaEn":"To teach classes is «donner des cours»; to have class, «avoir cours». Present of «donner», regular: je donne, tu donnes, il donne, nous donnons, ils donnent.","requerTodas":["fr-p195","fr-p148","fr-p157"],"v":"b5d94fb9"},{"idioma":"fr","id":"fr-v077","tipo":"frase","fr":"Je n'oublierai jamais ce jour.","en":"I'll never forget this day.","aceitasEn":["ill never forget this day","i will never forget this day","ill never forget that day","i will never forget that day"],"distratoresEn":["I never forget this day.","I never used to forget this day.","I've never forgotten this day.","I'd never forget this day."],"formasFr":{"Je n'oublie jamais ce jour":"present","Je n'oubliais jamais ce jour":"imperfect","Je n'ai jamais oublié ce jour":"passé composé","Je n'oublierais jamais ce jour":"conditional"},"nivel":"A2","tags":["conjugação","futuro","regular"],"notaEn":"In the future, -er verbs keep the whole infinitive: «oublier» gives «j'oublierai». «Ne… jamais» means never.","requerTodas":["fr-p197","fr-p019"],"v":"ca0e5e83"},{"idioma":"fr","id":"fr-v078","tipo":"frase","fr":"Qu'est-ce que tu en penses ?","aceitasFr":["Tu en penses quoi ?"],"en":"What do you think of it?","aceitasEn":["what do you think of it","what do you think","what do you think about it","what do you think of that","what do you think about that"],"distratoresEn":["What did you think of it?","What will you think of it?","What would you think of it?","What had you thought of it?"],"formasFr":{"Qu'est-ce que tu en as pensé":"passé composé","Qu'est-ce que tu en penseras":"future","Qu'est-ce que tu en penserais":"conditional","Qu'est-ce que tu en avais pensé":"pluperfect"},"nivel":"A1","tags":["conjugação","presente","regular","social"],"notaEn":"Having an opinion of something is «penser de», and «en» stands for «of it»: «qu'est-ce que tu en penses ?». Thinking about is different: «penser à».","requerTodas":["fr-p198"],"v":"f9fcf333"},{"idioma":"fr","id":"fr-v079","tipo":"frase","fr":"Je lui ai demandé l'heure.","en":"I asked him the time.","aceitasEn":["i asked him the time","i asked her the time","i asked him what time it was","i asked her what time it was","ive asked him the time"],"distratoresEn":["I ask him the time.","I used to ask him the time.","I'll ask him the time.","I would ask him the time."],"formasFr":{"Je lui demande l'heure":"present","Je lui demandais l'heure":"imperfect","Je lui demanderai l'heure":"future","Je lui demanderais l'heure":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular"],"notaEn":"«Lui» means to him or to her: «je lui ai demandé», I asked him or her. Asking the time is «demander l'heure».","requerTodas":["fr-p002","fr-p194","fr-p129"],"v":"1abd152c"},{"idioma":"fr","id":"fr-v080","tipo":"frase","fr":"J'ai commencé un nouveau travail.","en":"I started a new job.","aceitasEn":["i started a new job","ive started a new job","i have started a new job","i began a new job"],"distratoresEn":["I'm starting a new job.","I was starting a new job.","I'll start a new job.","I would start a new job."],"formasFr":{"Je commence un nouveau travail":"present","Je commençais un nouveau travail":"imperfect","Je commencerai un nouveau travail":"future","Je commencerais un nouveau travail":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","trabalho"],"notaEn":"In the imperfect, «commencer» takes a cedilla: «je commençais». The passé composé doesn't need one: «j'ai commencé». «Nouveau» goes before the noun.","requerTodas":["fr-p002","fr-p196","fr-p039","fr-p029"],"v":"5d5d7b0e"},{"idioma":"fr","id":"fr-v081","tipo":"frase","fr":"J'avais froid.","en":"I felt cold.","aceitasEn":["i felt cold","i was feeling cold"],"distratoresEn":["I feel cold.","I'll feel cold.","I'd feel cold.","I had felt cold."],"formasFr":{"J'ai froid":"present","J'aurai froid":"future","J'aurais froid":"conditional","J'avais eu froid":"pluperfect"},"nivel":"A1","tags":["conjugação","imperfeito","irregular","natureza","corpo"],"notaEn":"Cold is something you have: «j'ai froid», I'm cold; «j'avais froid», I was cold, I felt cold. Imperfect of «avoir»: j'avais, tu avais, il avait, nous avions, vous aviez, ils avaient.","requerTodas":["fr-p002","fr-p080"],"v":"69975706"},{"idioma":"fr","id":"fr-p205","tipo":"palavra","fr":"le canapé","sinonimosFr":["le sofa"],"en":"the couch","aceitasEn":["couch","sofa","the sofa"],"distratoresEn":["the armchair","the cushion","the rug","the curtain"],"nivel":"A1","tags":["casa"],"notaEn":"Masculine. The couch in the living room; at a party, «les canapés» are also the little appetizers, as in English. «Le sofa» means the same.","v":"0f585918","pos":3082},{"idioma":"fr","id":"fr-p206","tipo":"palavra","fr":"fermer","en":"to close","aceitasEn":["to close","close","to shut","shut"],"distratoresEn":["to sign","to boil","to drill","to open"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"Regular «-er» verb: «ferme la porte», close the door. To lock is «fermer à clé»; the opposite is «ouvrir».","v":"781d2f5d","pos":322},{"idioma":"fr","id":"fr-p207","tipo":"palavra","fr":"le frigo","sinonimosFr":["le réfrigérateur","le frigidaire"],"en":"the fridge","aceitasEn":["fridge","refrigerator","the refrigerator"],"distratoresEn":["the stove","the freezer","the oven","the cupboard"],"nivel":"A1","tags":["casa"],"notaEn":"Masculine and informal, short for «le réfrigérateur», just like fridge. The freezer is «le congélateur».","v":"80074865","pos":2624},{"idioma":"fr","id":"fr-p208","tipo":"palavra","fr":"se laver","en":"to wash","aceitasEn":["to wash","wash","to wash oneself","to get washed","to wash up"],"distratoresEn":["to get dressed","to comb","to get up","to dry off"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"French uses the article, not «my», with body parts: «je me lave les mains», I wash my hands. Without «se», «laver» is to wash something: «laver la voiture».","v":"5ec181fd","pos":963},{"idioma":"fr","id":"fr-p209","tipo":"palavra","fr":"la chemise","en":"the shirt","aceitasEn":["shirt","the shirt"],"distratoresEn":["the T-shirt","the skirt","the tie","the jacket"],"nivel":"A1","tags":["roupa"],"notaEn":"Feminine. Not a chemise: a button-up shirt. A T-shirt is «un tee-shirt»; «la chemise de nuit» is a nightgown.","v":"bd645491","pos":1225},{"idioma":"fr","id":"fr-p210","tipo":"palavra","fr":"gagner","en":"to win / to earn","aceitasEn":["to win","win","to earn","earn","to gain","gain"],"distratoresEn":["to lose / to miss","to bet / to gamble","to spend / to use up","to pay / to settle"],"nivel":"A1","tags":["verbo","trabalho"],"notaEn":"Both to win («gagner le match») and to earn («gagner de l'argent»). «Gagner sa vie», to earn a living.","v":"b9d7dd34","pos":222},{"idioma":"fr","id":"fr-p211","tipo":"palavra","fr":"premier","aceitasFr":["première"],"en":"first","aceitasEn":["first"],"distratoresEn":["last","second","next","only"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «première». In dates only the 1st takes the ordinal: «le premier mai», but «le deux mai», May 2nd.","v":"2131fce2","pos":318},{"idioma":"fr","id":"fr-p212","tipo":"palavra","fr":"le portable","aceitasFr":["le téléphone portable","le mobile"],"regionaisFr":{"le cellulaire":"no Quebec","le GSM":"na Bélgica","le natel":"na Suíça"},"en":"the cell phone","aceitasEn":["cell phone","cellphone","the cellphone","phone","the phone","mobile","mobile phone","the mobile","cell","laptop","the laptop"],"distratoresEn":["the charger","the tablet","the watch","the wallet"],"nivel":"A1","tags":["tecnologia","objetos"],"notaEn":"Masculine. A cell phone, and sometimes a laptop («l'ordinateur portable»). As an adjective, «portable» means the same as in English.","v":"a777f975","pos":774},{"idioma":"fr","id":"fr-p213","tipo":"palavra","fr":"l'aide","aceitasFr":["une aide"],"en":"help (assistance)","aceitasEn":["help","the help","aid","assistance"],"distratoresEn":["idea (a thought)","advice (a tip)","order (a command)","hint (a clue)"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine. «À l'aide !», help! The verb is «aider»: «demander de l'aide», to ask for help. A person who assists is «un assistant».","v":"38a547a6","pos":391},{"idioma":"fr","id":"fr-p214","tipo":"palavra","fr":"le coup","en":"the blow","aceitasEn":["blow","hit","the hit","knock","the knock","stroke","shot"],"distratoresEn":["the cup","the coat","the cost","the body"],"nivel":"A2","tags":["cotidiano"],"notaEn":"Mostly in set phrases: «un coup de main», a hand (help); «un coup de fil», a phone call; «tout à coup», suddenly. The «p» is silent, as in «coup d'État».","v":"9392bf59","pos":115},{"idioma":"fr","id":"fr-p215","tipo":"palavra","fr":"le numéro","en":"the number","aceitasEn":["number","the number"],"distratoresEn":["the address","the name","the message","the schedule"],"nivel":"A1","tags":["cotidiano"],"notaEn":"A phone number, a house number, an issue of a magazine. A digit is «le chiffre», and an amount, «le nombre».","v":"6386d1e7","pos":503},{"idioma":"fr","id":"fr-p216","tipo":"palavra","fr":"le passeport","en":"the passport","aceitasEn":["passport","the passport"],"distratoresEn":["the ticket","the visa","the badge","the suitcase"],"nivel":"A1","tags":["viagem"],"notaEn":"Masculine. At the border: «le contrôle des passeports». An ID card is «la carte d'identité».","v":"fe710a05","transp":"parecida","pos":1844},{"idioma":"fr","id":"fr-p217","tipo":"palavra","fr":"le nom","en":"the name","aceitasEn":["name","the name","surname","last name","the last name","noun"],"distratoresEn":["the number","the address","the signature","the age"],"nivel":"A1","tags":["social"],"notaEn":"On a form, «nom» is the last name, next to «prénom», the first name. To say your name: «je m'appelle…».","v":"9392b9dc","pos":98},{"idioma":"fr","id":"fr-p218","tipo":"palavra","fr":"la place","en":"the seat / the square","aceitasEn":["seat","the seat","square","the square","room","space","spot","the spot"],"distratoresEn":["the beach / the port","the plate / the dish","the building / the street","the line / the table"],"nivel":"A1","tags":["cidade","cotidiano"],"notaEn":"Feminine. A seat or room («cette place est libre ?», is this seat free?; «il n'y a pas de place», there's no room) and a town square. A place in general is «un endroit».","v":"6339857a","pos":141},{"idioma":"fr","id":"fr-p219","tipo":"palavra","fr":"le vélo","sinonimosFr":["la bicyclette"],"en":"the bike","aceitasEn":["bike","bicycle","the bicycle"],"distratoresEn":["the motorcycle","the scooter","the sailboat","the skateboard"],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"Masculine. You go «à vélo», by bike; «faire du vélo», to ride a bike. «La bicyclette» is the more formal word.","v":"0c70cf12","pos":1170},{"idioma":"fr","id":"fr-p220","tipo":"palavra","fr":"la fille","en":"the daughter / the girl","aceitasEn":["daughter","the daughter","girl","the girl"],"distratoresEn":["the niece / the cousin","the granddaughter / the lady","the line / the row","the wife / the bride"],"nivel":"A1","tags":["família"],"notaEn":"With a possessive it is a daughter («ma fille»); otherwise a girl («une fille»). A son is «le fils».","v":"d576a6d0","pos":81},{"idioma":"fr","id":"fr-p221","tipo":"palavra","fr":"fumer","en":"to smoke","aceitasEn":["to smoke","smoke"],"distratoresEn":["to cough","to smell","to spit","to blow"],"nivel":"A1","tags":["verbo","saúde"],"notaEn":"Regular «-er» verb. On signs: «défense de fumer», no smoking; «non-fumeur», non-smoking. It also means to smoke food: «saumon fumé».","v":"755bbc13","pos":821},{"idioma":"fr","id":"fr-p222","tipo":"palavra","fr":"le manteau","en":"the coat","aceitasEn":["coat","overcoat","the overcoat"],"distratoresEn":["the blanket","the scarf","the vest","the glove"],"nivel":"A1","tags":["roupa"],"notaEn":"Masculine, plural «manteaux». A long winter coat, not a mantle; a jacket is «une veste».","v":"eb757bdc","pos":1342},{"idioma":"fr","id":"fr-p223","tipo":"palavra","fr":"le magasin","en":"the store","aceitasEn":["store","shop","the shop"],"distratoresEn":["the magazine","the fair","the factory","the workshop"],"nivel":"A1","tags":["compras","cidade"],"notaEn":"Masculine. Not a magazine (that's «le magazine» or «la revue»): a store. «Le grand magasin», the department store.","v":"e908d756","pos":684},{"idioma":"fr","id":"fr-p224","tipo":"palavra","fr":"neuf","aceitasFr":["neuve"],"en":"nine / new (brand-new)","aceitasEn":["nine","new","brand new","brand-new"],"distratoresEn":["ten / used (secondhand)","eleven / old (from long ago)","ninety / clean (washed)","ninth / empty (with nothing)"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The number 9 and, as an adjective, never used: «une voiture neuve» (feminine «neuve»). New in the sense of another, recent, is «nouveau». «Quoi de neuf ?», what's new?","v":"50e30479","pos":902},{"idioma":"fr","id":"fr-p225","tipo":"palavra","fr":"la télé","aceitasFr":["la télévision"],"en":"TV","aceitasEn":["the tv","television","the television"],"distratoresEn":["the radio","the phone","the movies","the computer"],"nivel":"A1","tags":["mídia","casa"],"notaEn":"Feminine, short for «la télévision»: «regarder la télé», to watch TV; «à la télé», on TV.","v":"e6bf19c7","pos":810},{"idioma":"fr","id":"fr-p226","tipo":"palavra","fr":"seulement","en":"only","aceitasEn":["only","just","merely"],"distratoresEn":["alone","almost","also","always"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Only, just: «je regarde seulement», I'm just looking. Alone is the adjective «seul»: «je suis seul».","v":"0db95683","pos":151},{"idioma":"fr","id":"fr-p227","tipo":"palavra","fr":"l'hôtel","aceitasFr":["un hôtel"],"en":"the hotel","aceitasEn":["hotel","the hotel"],"distratoresEn":["the hospital","the hostel","the restaurant","the building"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"Masculine, with a silent «h» and a circumflex. Careful: «l'hôtel de ville» is not a hotel but city hall.","v":"cdb51ef1","transp":"total","pos":444},{"idioma":"fr","id":"fr-p228","tipo":"palavra","fr":"tomber","en":"to fall","aceitasEn":["to fall","fall","to fall down","fall down"],"distratoresEn":["to take","to touch","to climb","to push"],"nivel":"A1","tags":["verbo"],"notaEn":"Its passé composé takes «être»: «je suis tombé», I fell. «Tomber malade», to get sick; «tomber amoureux», to fall in love.","v":"ca402547","pos":160},{"idioma":"fr","id":"fr-p229","tipo":"palavra","fr":"appeler","en":"to call","aceitasEn":["to call","call","to phone","phone","to call up"],"distratoresEn":["to turn off","to applaud","to listen","to reach"],"nivel":"A1","tags":["verbo","social"],"notaEn":"To call someone, in person or on the phone: «je t'appelle ce soir». The «l» doubles before a silent ending: j'appelle, nous appelons.","v":"bb37ff44","pos":51},{"idioma":"fr","id":"fr-p230","tipo":"palavra","fr":"longtemps","en":"for a long time","aceitasEn":["a long time","long","for a long while","a long while"],"distratoresEn":["for a short time","all the time","sometimes","very early"],"nivel":"A1","tags":["cotidiano"],"notaEn":"One word: «j'ai attendu longtemps», I waited a long time. «Ça fait longtemps !», long time no see!","v":"bd9e97a5","pos":184},{"idioma":"fr","id":"fr-p231","tipo":"palavra","fr":"l'avion","aceitasFr":["un avion"],"en":"the plane","aceitasEn":["plane","airplane","the airplane","aircraft"],"distratoresEn":["the flight","the ship","the helicopter","the airport"],"nivel":"A1","tags":["viagem"],"notaEn":"Masculine. You travel «en avion», by plane; «par avion» on an envelope means airmail.","v":"3ff59992","pos":689},{"idioma":"fr","id":"fr-p232","tipo":"palavra","fr":"porter","en":"to carry / to wear","aceitasEn":["to carry","carry","to wear","wear","to bear"],"distratoresEn":["to take off / to undress","to push / to hit","to weigh / to measure","to keep / to hide"],"nivel":"A1","tags":["verbo","roupa"],"notaEn":"To carry («porter un sac») and to wear: «elle porte des lunettes», she wears glasses. A door is «la porte».","v":"d8ff52fd","pos":147},{"idioma":"fr","id":"fr-p233","tipo":"palavra","fr":"le tour","en":"the tour / the turn","aceitasEn":["tour","the tour","turn","the turn","trip","lap","round","go"],"distratoresEn":["the tower / the building","the team / the group","the task / the duty","the break / the pause"],"nivel":"A1","tags":["viagem","cotidiano"],"notaEn":"Masculine. A trip around («faire le tour du monde»; «faire un tour», to go for a walk or a ride) and a turn: «c'est ton tour», it's your turn. Feminine «la tour» is a tower.","v":"e104e02c","pos":271},{"idioma":"fr","id":"fr-p234","tipo":"palavra","fr":"le musée","en":"the museum","aceitasEn":["museum","the museum"],"distratoresEn":["the theater","the library","the church","the castle"],"nivel":"A1","tags":["cultura","cidade"],"notaEn":"Masculine, even though «-ée» usually looks feminine: «le musée du Louvre».","v":"2ba5b0b5","pos":1172},{"idioma":"fr","id":"fr-p235","tipo":"palavra","fr":"le jus","en":"juice","aceitasEn":["juice","the juice"],"distratoresEn":["milk","soda","tea","syrup"],"nivel":"A1","tags":["comida"],"notaEn":"Masculine, with a silent «s»: «un jus d'orange», an orange juice. It is also the juice from cooked meat, as in «au jus».","v":"b4edf636","pos":1576},{"idioma":"fr","id":"fr-p236","tipo":"palavra","fr":"l'orange","aceitasFr":["une orange"],"en":"the orange","aceitasEn":["orange","the orange"],"distratoresEn":["the tangerine","the lemon","the apple","the peach"],"nivel":"A1","tags":["comida"],"notaEn":"Feminine. It is also the color, which never changes form: «des chaussures orange».","v":"a27452f0","transp":"total","pos":2185},{"idioma":"fr","id":"fr-p237","tipo":"palavra","fr":"la taille","en":"the size","aceitasEn":["size","the size","height","waist"],"distratoresEn":["the color","the weight","the style","the fabric"],"nivel":"A1","tags":["roupa","compras"],"notaEn":"Feminine. Clothing size («quelle taille faites-vous ?»), and also a person's height or waist. Shoe size is «la pointure».","v":"57839882","pos":1070},{"idioma":"fr","id":"fr-p238","tipo":"palavra","fr":"prochain","aceitasFr":["prochaine"],"en":"next","aceitasEn":["next","following"],"distratoresEn":["last","past","previous","nearby"],"nivel":"A1","tags":["adjetivo","cotidiano"],"notaEn":"Feminine «prochaine». Next in time or in line: «la semaine prochaine», next week. Near is «proche».","v":"a5bfe419","pos":438},{"idioma":"fr","id":"fr-p239","tipo":"palavra","fr":"tout droit","en":"straight ahead","aceitasEn":["straight ahead","straight on","straight"],"distratoresEn":["to the right","to the left","backward","upstairs"],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"For directions: «allez tout droit», go straight ahead. «Droit» means straight; right is «la droite»: «à droite», on the right.","v":"f7b0adce","pos":236},{"idioma":"fr","id":"fr-p240","tipo":"palavra","fr":"deuxième","en":"second","aceitasEn":["second"],"distratoresEn":["double","third","last","next"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Same form for masculine and feminine: «la deuxième rue». Ordinals end in «-ième»: troisième, quatrième; only «premier» is different.","v":"f8880475","pos":1321},{"idioma":"fr","id":"fr-p241","tipo":"palavra","fr":"la gauche","en":"the left (side)","aceitasEn":["left","the left","left side","the left side","left-hand side","the left-hand side"],"distratoresEn":["the right (side)","the front (side)","the back (side)","the top (side)"],"nivel":"A1","tags":["cidade"],"notaEn":"«À gauche», on the left; right is «la droite». As an adjective, «gauche» also means clumsy, as in English.","v":"e2f3d015","pos":820},{"idioma":"fr","id":"fr-p242","tipo":"palavra","fr":"le thé","en":"tea","aceitasEn":["tea","the tea"],"distratoresEn":["coffee","milk","juice","cocoa"],"nivel":"A1","tags":["comida"],"notaEn":"Masculine: «un thé», «le thé vert», green tea. Herbal tea is «la tisane».","v":"a7919e86","pos":1192},{"idioma":"fr","id":"fr-p243","tipo":"palavra","fr":"chut","en":"shh","aceitasEn":["shh","sh","shush","hush","quiet"],"distratoresEn":["phew","oops","ouch","yay"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Asks for silence, finger on the lips. The «t» is pronounced: «shoot», with a French «u».","v":"6b4b7f3a","pos":1803},{"idioma":"fr","id":"fr-p244","tipo":"palavra","fr":"la pharmacie","en":"the pharmacy","aceitasEn":["pharmacy","drugstore","the drugstore","chemist's"],"distratoresEn":["the clinic","the bakery","the bookstore","the grocery store"],"nivel":"A1","tags":["saúde","cidade"],"notaEn":"Feminine; look for the green cross. The pharmacist is «le pharmacien».","v":"dad42783","transp":"parecida","pos":2611},{"idioma":"fr","id":"fr-p245","tipo":"palavra","fr":"la boulangerie","en":"the bakery","aceitasEn":["bakery","the bakery"],"distratoresEn":["the pastry shop","the butcher shop","the grocery store","the pharmacy"],"nivel":"A1","tags":["comida","compras","cidade"],"notaEn":"Feminine. Where you buy your baguette; the baker is «le boulanger». A pastry shop is «la pâtisserie», a butcher's «la boucherie».","v":"a6f2718f","pos":3757},{"idioma":"fr","id":"fr-p246","tipo":"palavra","fr":"près","en":"near","aceitasEn":["near","close","nearby","close by"],"distratoresEn":["far","inside","behind","quickly"],"nivel":"A1","tags":["cidade","cotidiano"],"notaEn":"With «de»: «près de la gare», near the station; «près d'ici», near here. The opposite is «loin». Don't mix it up with «prêt», ready.","v":"c31fc5d5","pos":302},{"idioma":"fr","id":"fr-p247","tipo":"palavra","fr":"les parents","en":"parents","aceitasEn":["parents","the parents","relatives","the relatives"],"distratoresEn":["grandparents","cousins","godparents","siblings"],"nivel":"A1","tags":["família"],"notaEn":"Mother and father: «mes parents», my parents. «Un parent» can also be any relative.","v":"d3223b36","transp":"total","pos":460},{"idioma":"fr","id":"fr-p248","tipo":"palavra","fr":"se sentir","en":"to feel","aceitasEn":["to feel","feel"],"distratoresEn":["to sit down","to get tired","to complain","to calm down"],"nivel":"A1","tags":["verbo","saúde"],"notaEn":"For how you feel: «je me sens bien», I feel good. Without «se», «sentir» means to smell: «ça sent bon», it smells good.","v":"18ae8ddd","pos":128},{"idioma":"fr","id":"fr-p249","tipo":"palavra","fr":"présenter","en":"to introduce","aceitasEn":["to introduce","introduce","to present","present"],"distratoresEn":["to gift","to sense","to lend","to invite"],"nivel":"A1","tags":["verbo","social"],"notaEn":"To introduce someone: «je te présente mon mari», this is my husband. To give a present is «offrir».","v":"47ec6869","pos":297},{"idioma":"fr","id":"fr-p250","tipo":"palavra","fr":"la vie","en":"life","aceitasEn":["life","the life"],"distratoresEn":["the way","the view","death","health"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine: «c'est la vie», that's life. «Gagner sa vie», to earn a living; «dans la vie», for a living.","v":"44461cbf","pos":41},{"idioma":"fr","id":"fr-p251","tipo":"palavra","fr":"la fièvre","en":"fever","aceitasEn":["fever","the fever","a fever","temperature"],"distratoresEn":["the flu","the cough","the fiber","the wound"],"nivel":"A1","tags":["saúde"],"notaEn":"Feminine. You «have» it: «avoir de la fièvre», to have a fever.","v":"5f5c25e4","pos":2268},{"idioma":"fr","id":"fr-p252","tipo":"palavra","fr":"rater","en":"to miss / to fail","aceitasEn":["to miss","miss","to fail","fail"],"distratoresEn":["to tear / to cut","to catch / to reach","to delay / to be late","to rate / to rank"],"nivel":"A1","tags":["verbo","viagem"],"notaEn":"To miss («rater le bus») and to fail or mess up: «j'ai raté mon gâteau», my cake didn't turn out. To lose something is «perdre».","v":"f27705c8","pos":1757},{"idioma":"fr","id":"fr-p253","tipo":"palavra","fr":"le ticket","en":"the ticket","aceitasEn":["ticket","the ticket","receipt","the receipt"],"distratoresEn":["the label","the change","the coin","the line"],"nivel":"A1","tags":["viagem","compras"],"notaEn":"Masculine. A subway or bus ticket, and also a store receipt. Train, plane and theater tickets are usually «le billet».","v":"934f3fd1","transp":"total","pos":1756},{"idioma":"fr","id":"fr-p254","tipo":"palavra","fr":"l'avance","aceitasFr":["une avance"],"en":"the advance","aceitasEn":["advance","the advance","lead","the lead","head start"],"distratoresEn":["the delay","the debt","the reminder","the inheritance"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine, and mostly in set phrases: «en avance», early; «à l'avance», in advance. The opposite is «en retard», late.","v":"5bb06932","transp":"parecida","pos":978},{"idioma":"fr","id":"fr-p255","tipo":"palavra","fr":"le vent","en":"the wind","aceitasEn":["wind","the wind"],"distratoresEn":["the sale","the rain","the snow","the cloud"],"nivel":"A1","tags":["natureza"],"notaEn":"Masculine, with a silent «t»: «il y a du vent», it's windy. Feminine «la vente» is a sale.","v":"5d44ff04","pos":798},{"idioma":"fr","id":"fr-p256","tipo":"palavra","fr":"le fils","en":"the son","aceitasEn":["son","the son"],"distratoresEn":["the thread","the grandson","the nephew","the son-in-law"],"nivel":"A1","tags":["família"],"notaEn":"Pronounced «fees»: the «l» is silent and the «s» is heard, singular and plural alike. Without the «s», «le fil» is a thread.","v":"2a90bdbf","pos":175},{"idioma":"fr","id":"fr-p257","tipo":"palavra","fr":"la page","en":"the page","aceitasEn":["page","the page"],"distratoresEn":["the line","the cover","the chapter","the paragraph"],"nivel":"A1","tags":["escola"],"notaEn":"Feminine: «à la page dix», on page ten. «Tourner la page», to turn the page, also figuratively.","v":"ef381dab","transp":"total","pos":969},{"idioma":"fr","id":"fr-p258","tipo":"palavra","fr":"la caisse","en":"the checkout","aceitasEn":["checkout","the register","register","cash register","the cash register","till","the till","the box","box","crate","the crate"],"distratoresEn":["the basket","the line","the cart","the bag"],"nivel":"A1","tags":["compras"],"notaEn":"Feminine: «à la caisse», at the checkout. It is also a big box or crate. An ATM is «le distributeur».","v":"5ea95fa4","pos":1351},{"idioma":"fr","id":"fr-p259","tipo":"palavra","fr":"le kilo","en":"the kilo","aceitasEn":["kilo","the kilo","kilogram","kg"],"distratoresEn":["the liter","the meter","the gram","the pound"],"nivel":"A1","tags":["compras","comida"],"notaEn":"After a quantity comes plain «de», no article: «un kilo de tomates». At the market, «une livre» is half a kilo.","v":"b127c5e1","transp":"total","pos":1651},{"idioma":"fr","id":"fr-p260","tipo":"palavra","fr":"la tomate","en":"the tomato","aceitasEn":["tomato","the tomato"],"distratoresEn":["the potato","the onion","the cucumber","the pepper"],"nivel":"A1","tags":["comida"],"notaEn":"Feminine: «une tomate», «la sauce tomate».","v":"31475c9e","transp":"parecida","pos":2292},{"idioma":"fr","id":"fr-p261","tipo":"palavra","fr":"la réunion","en":"the meeting","aceitasEn":["meeting","the meeting"],"distratoresEn":["the lecture","the party","the trip","the interview"],"nivel":"A1","tags":["trabalho"],"notaEn":"Feminine. Not a reunion: a meeting. «Je suis en réunion», I'm in a meeting. A reunion is «les retrouvailles».","v":"fb0877db","pos":906},{"idioma":"fr","id":"fr-p262","tipo":"palavra","fr":"marié","aceitasFr":["mariée"],"en":"married","aceitasEn":["married"],"distratoresEn":["single","separated","widowed","divorced"],"nivel":"A1","tags":["adjetivo","família"],"notaEn":"Feminine «mariée»; it sounds the same. To marry is «se marier avec». At a wedding, «la mariée» is the bride.","v":"c0a4f739","pos":2126},{"idioma":"fr","id":"fr-p263","tipo":"palavra","fr":"le chef","en":"the boss","aceitasEn":["boss","the boss","chief","the chief","leader","chef","the chef"],"distratoresEn":["the coworker","the client","the employee","the partner"],"nivel":"A1","tags":["trabalho"],"notaEn":"Any boss, not just a cook: «mon chef», my boss. The head cook is also «le chef»; the owner is «le patron».","v":"282466b3","pos":1332},{"idioma":"fr","id":"fr-p264","tipo":"palavra","fr":"l'examen","aceitasFr":["un examen"],"en":"the exam","aceitasEn":["exam","the exam","test","the test","examination"],"distratoresEn":["the grade","the lesson","the diploma","the enrollment"],"nivel":"A1","tags":["escola"],"notaEn":"Masculine. Careful: «passer un examen» means to take an exam, not to pass it; to pass is «réussir».","v":"a655edd6","pos":1207},{"idioma":"fr","id":"fr-p265","tipo":"palavra","fr":"le médicament","en":"the medicine","aceitasEn":["medicine","the medicine","medication","the medication","drug"],"distratoresEn":["the prescription","the doctor","the vaccine","the bandage"],"nivel":"A1","tags":["saúde"],"notaEn":"Masculine. «Prendre un médicament», to take a medicine. The doctor is «le médecin», and medicine as a science, «la médecine».","v":"40e5a332","pos":1228},{"idioma":"fr","id":"fr-p266","tipo":"palavra","fr":"l'ascenseur","aceitasFr":["un ascenseur"],"en":"the elevator","aceitasEn":["elevator","lift","the lift"],"distratoresEn":["the stairs","the floor","the escalator","the hallway"],"nivel":"A1","tags":["casa","cidade"],"notaEn":"Masculine: «l'ascenseur est en panne», the elevator is out of order. The stairs are «l'escalier».","v":"bcd98247","pos":1570},{"idioma":"fr","id":"fr-p267","tipo":"palavra","fr":"le parc","en":"the park","aceitasEn":["park","the park"],"distratoresEn":["the square","the woods","the zoo","the court"],"nivel":"A1","tags":["cidade","natureza"],"notaEn":"Masculine, with the «c» pronounced: «au parc», at the park. A parking lot is «le parking».","v":"49d528d6","pos":929},{"idioma":"fr","id":"fr-p268","tipo":"palavra","fr":"naître","en":"to be born","aceitasEn":["to be born","be born"],"distratoresEn":["to die","to grow up","to know","to live"],"nivel":"A1","tags":["verbo","família"],"notaEn":"Mostly used in the passé composé, with «être»: «je suis né en 1990», I was born in 1990. Irregular participle: «né».","v":"50dd20a2","pos":462},{"idioma":"fr","id":"fr-p269","tipo":"palavra","fr":"rester","en":"to stay","aceitasEn":["to stay","stay","to remain","remain","to be left"],"distratoresEn":["to rest","to go out","to come back","to run away"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"Not to rest (that's «se reposer»): to stay («je reste à la maison») or be left: «il reste du pain», there's some bread left. Passé composé with «être».","v":"6d3d5f9a","pos":55},{"idioma":"fr","id":"fr-p270","tipo":"palavra","fr":"marcher","en":"to walk / to function","aceitasEn":["to walk","walk","to function","function","to work","to march"],"distratoresEn":["to mark / to note","to limp / to trip","to jump / to climb","to stop / to break"],"nivel":"A1","tags":["verbo"],"notaEn":"To walk («j'aime marcher») and to work, to function: «ça marche !», deal!; «ça ne marche pas», it doesn't work.","v":"984c8093","pos":199},{"idioma":"fr","id":"fr-p271","tipo":"palavra","fr":"les devoirs","en":"the homework","aceitasEn":["homework","schoolwork"],"distratoresEn":["the housework","the school vacation","the school supplies","the report card"],"nivel":"A1","tags":["escola"],"notaEn":"Plural for homework: «faire ses devoirs», to do your homework. In the singular, «le devoir» is a duty.","v":"d2d536ff","pos":2408},{"idioma":"fr","id":"fr-p272","tipo":"palavra","fr":"le cadeau","en":"the gift","aceitasEn":["gift","the gift","present","the present"],"distratoresEn":["the padlock","the package","the bow","the cake"],"nivel":"A1","tags":["social"],"notaEn":"Plural with «-x»: «les cadeaux». «Faire un cadeau», to give a gift.","v":"80ac19dd","pos":653},{"idioma":"fr","id":"fr-p273","tipo":"palavra","fr":"cent","en":"a hundred","aceitasEn":["a hundred","hundred","one hundred","100"],"distratoresEn":["five","a thousand","fifty","ninety"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The «t» is silent. It takes an «s» in «deux cents», two hundred, but not when another number follows: «deux cent un».","v":"816b7723","pos":245},{"idioma":"fr","id":"fr-p274","tipo":"palavra","fr":"la bouche","en":"the mouth","aceitasEn":["mouth","the mouth"],"distratoresEn":["the cheek","the nose","the lip","the throat"],"nivel":"A1","tags":["corpo"],"notaEn":"Feminine. The cheek is «la joue». «Le bouche-à-oreille», word of mouth.","v":"f4fd1d78","pos":802},{"idioma":"fr","id":"fr-p275","tipo":"palavra","fr":"l'œil","aceitasFr":["un œil","l'oeil","un oeil"],"en":"the eye","aceitasEn":["eye","the eye"],"distratoresEn":["the ear","the eyebrow","the eyelash","the nose"],"nivel":"A1","tags":["corpo"],"notaEn":"Masculine, with a completely different plural: «un œil», «des yeux». The «œ» is one letter, but «oe» works too.","v":"0e9d2547","pos":110},{"idioma":"fr","id":"fr-p276","tipo":"palavra","fr":"le bras","en":"the arm","aceitasEn":["arm","the arm"],"distratoresEn":["the leg","the shoulder","the ember","the wrist"],"nivel":"A1","tags":["corpo"],"notaEn":"The «s» is silent and not a plural: «le bras», «les bras». «Bras dessus, bras dessous», arm in arm.","v":"2041e91b","pos":398},{"idioma":"fr","id":"fr-p277","tipo":"palavra","fr":"le dos","en":"the back","aceitasEn":["back","the back"],"distratoresEn":["the shoulders","the thighs","the neck","the belly"],"nivel":"A1","tags":["corpo"],"notaEn":"Masculine, with a silent «s»: «j'ai mal au dos», my back hurts.","v":"540f9cbc","pos":559},{"idioma":"fr","id":"fr-p278","tipo":"palavra","fr":"la chaussure","en":"the shoe","aceitasEn":["shoe","the shoe","footwear"],"distratoresEn":["the sock","the flip-flop","the belt","the glove"],"nivel":"A1","tags":["roupa"],"notaEn":"Feminine: «une chaussure», «des chaussures de sport», sneakers. A sock is «la chaussette».","v":"7c8327d7","pos":852},{"idioma":"fr","id":"fr-p279","tipo":"palavra","fr":"le pantalon","en":"the pants","aceitasEn":["pants","trousers","the trousers"],"distratoresEn":["the skirt","the vest","the jacket","the dress"],"nivel":"A1","tags":["roupa"],"notaEn":"Masculine and singular: «un pantalon», a pair of pants. Shorts are «un short».","v":"a4912e45","pos":1279},{"idioma":"fr","id":"fr-p280","tipo":"palavra","fr":"le fromage","en":"cheese","aceitasEn":["cheese","the cheese"],"distratoresEn":["butter","ham","yogurt","cream"],"nivel":"A1","tags":["comida"],"notaEn":"Masculine. In a French meal, «le fromage» comes before dessert. Grated cheese is «fromage râpé».","v":"a7c17526","pos":164},{"idioma":"fr","id":"fr-p281","tipo":"palavra","fr":"l'œuf","aceitasFr":["un œuf","l'oeuf","un oeuf"],"en":"the egg","aceitasEn":["egg","the egg"],"distratoresEn":["the flour","the sugar","the bone","the butter"],"nivel":"A1","tags":["comida"],"notaEn":"Masculine. The «f» is heard in the singular («un œuf») but not in the plural: «des œufs». A hard-boiled egg is «un œuf dur».","v":"cf499dbb","pos":1121},{"idioma":"fr","id":"fr-p282","tipo":"palavra","fr":"le poisson","en":"the fish","aceitasEn":["fish","the fish"],"distratoresEn":["the poison","the peach","the chicken","the shrimp"],"nivel":"A1","tags":["comida","animais"],"notaEn":"Masculine, with «ss» sounding like «s». With a single «s», «le poison» means poison, as in English.","v":"db66e0cd","pos":854},{"idioma":"fr","id":"fr-p283","tipo":"palavra","fr":"le poulet","en":"chicken","aceitasEn":["chicken","the chicken"],"distratoresEn":["octopus","turkey","duck","pork"],"nivel":"A1","tags":["comida","animais"],"notaEn":"Masculine: «poulet rôti», roast chicken. A hen is «la poule», and an octopus, «le poulpe».","v":"39e242a9","pos":1251},{"idioma":"fr","id":"fr-p284","tipo":"palavra","fr":"l'hiver","aceitasFr":["un hiver"],"en":"winter","aceitasEn":["winter","the winter"],"distratoresEn":["fall","spring","summer","frost"],"nivel":"A1","tags":["natureza","cotidiano"],"notaEn":"Masculine, like all four seasons. «En hiver», in winter; but «au printemps», in spring.","v":"10062046","pos":1155},{"idioma":"fr","id":"fr-p285","tipo":"palavra","fr":"l'été","aceitasFr":["un été"],"en":"summer","aceitasEn":["summer","the summer"],"distratoresEn":["winter","fall","spring","the holiday"],"nivel":"A1","tags":["natureza","cotidiano"],"notaEn":"Masculine: «en été», in summer. Without the article, «été» is also the past participle of «être»: «j'ai été malade», I was sick.","v":"97d7048e","pos":690},{"idioma":"fr","id":"fr-p286","tipo":"palavra","fr":"le mois","en":"the month","aceitasEn":["month","the month"],"distratoresEn":["the week","the year","the time","the hour"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Masculine, with an «s» even in the singular: «le mois», «les mois». «Le mois prochain», next month.","v":"fe43e1f6","pos":299},{"idioma":"fr","id":"fr-p287","tipo":"palavra","fr":"la salle de bains","aceitasFr":["la salle de bain"],"en":"the bathroom","aceitasEn":["bathroom","the bathroom"],"distratoresEn":["the living room","the kitchen","the bedroom","the laundry room"],"nivel":"A1","tags":["casa"],"notaEn":"Literally «room of baths»: where the shower and sink are. In France the toilet is often separate, in «les toilettes».","v":"9768e371","pos":291},{"idioma":"fr","id":"fr-p288","tipo":"palavra","fr":"l'église","aceitasFr":["une église"],"en":"the church","aceitasEn":["church","the church"],"distratoresEn":["the school","the museum","city hall","the castle"],"nivel":"A1","tags":["cidade","cultura"],"notaEn":"Feminine. It comes from Latin «ecclesia», like English «ecclesiastical».","v":"9b976af4","pos":867},{"idioma":"fr","id":"fr-p289","tipo":"palavra","fr":"chanter","en":"to sing","aceitasEn":["to sing","sing"],"distratoresEn":["to blackmail","to dance","to count","to enchant"],"nivel":"A1","tags":["verbo","cultura"],"notaEn":"Regular «-er» verb: je chante, nous chantons. A singer is «un chanteur», and a song, «une chanson».","v":"34bbd67e","pos":504},{"idioma":"fr","id":"fr-p290","tipo":"palavra","fr":"apprendre","en":"to learn / to teach","aceitasEn":["to learn","learn","to teach","teach","to find out"],"distratoresEn":["to arrest / to hold","to ask / to answer","to press / to squeeze","to hand in / to return"],"nivel":"A1","tags":["verbo","escola"],"notaEn":"Conjugated like «prendre»: j'apprends, nous apprenons. To learn («apprendre le français») and to teach someone («apprendre à quelqu'un»).","v":"771dfb73","pos":200},{"idioma":"fr","id":"fr-p291","tipo":"palavra","fr":"courir","en":"to run","aceitasEn":["to run","run"],"distratoresEn":["to cure","to cut","to jump","to swim"],"nivel":"A1","tags":["verbo"],"notaEn":"Irregular: je cours, nous courons; past participle «couru». «Courir un risque», to run a risk.","v":"9cede2bb","pos":392},{"idioma":"fr","id":"fr-p292","tipo":"palavra","fr":"écouter","en":"to listen","aceitasEn":["to listen","listen","to listen to","listen to"],"distratoresEn":["to choose","to brush","to hide","to write"],"nivel":"A1","tags":["verbo"],"notaEn":"No preposition: «écouter de la musique», to listen to music. To hear is «entendre».","v":"0a1430cb","pos":148},{"idioma":"fr","id":"fr-p293","tipo":"palavra","fr":"vivre","en":"to live (in general)","aceitasEn":["to live","live"],"distratoresEn":["to see (with the eyes)","to free (from something)","to travel (abroad)","to dress (in clothes)"],"nivel":"A1","tags":["verbo"],"notaEn":"Irregular: je vis, nous vivons; past participle «vécu». To live in general («la joie de vivre»); for where you live, «habiter» is more usual.","v":"4e021298","pos":92},{"idioma":"fr","id":"fr-p294","tipo":"palavra","fr":"fort","aceitasFr":["forte"],"en":"strong","aceitasEn":["strong"],"distratoresEn":["weak","thin","short","slow"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «forte». Also good at something («fort en maths») and, as an adverb, loud: «parle plus fort», speak up.","v":"5df29ab2","pos":285},{"idioma":"fr","id":"fr-p295","tipo":"palavra","fr":"jeune","en":"young","aceitasEn":["young"],"distratoresEn":["old","adult","cheerful","pretty"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Same form for masculine and feminine: «un jeune homme», «une jeune fille». «Les jeunes», young people.","v":"eb47e979","pos":138},{"idioma":"fr","id":"fr-p296","tipo":"palavra","fr":"propre","en":"clean / own","aceitasEn":["clean","own","neat","tidy"],"distratoresEn":["dirty / stained","ready / prepared","poor / humble","rare / strange"],"nivel":"A2","tags":["adjetivo","casa"],"notaEn":"After the noun, clean: «une chemise propre». Before it, own: «ma propre chambre», my own room. Same form in the feminine.","v":"6c3603b5","pos":331},{"idioma":"fr","id":"fr-p297","tipo":"palavra","fr":"vide","en":"empty","aceitasEn":["empty"],"distratoresEn":["full","alive","open","light"],"nivel":"A2","tags":["adjetivo"],"notaEn":"Same form for masculine and feminine: «la bouteille est vide», the bottle is empty. The opposite is «plein».","v":"f70b024b","pos":968},{"idioma":"fr","id":"fr-p298","tipo":"palavra","fr":"ensemble","en":"together","aceitasEn":["together"],"distratoresEn":["alone","apart","later","also"],"nivel":"A1","tags":["cotidiano"],"notaEn":"An adverb, so it never changes: «on mange ensemble ?», shall we eat together? As a noun, «l'ensemble» is the whole, a set.","v":"de3dfc17","pos":240},{"idioma":"fr","id":"fr-p299","tipo":"palavra","fr":"bientôt","en":"soon","aceitasEn":["soon","shortly"],"distratoresEn":["very early","a while ago","sometimes","very late"],"nivel":"A1","tags":["cotidiano"],"notaEn":"One word: «à bientôt !», see you soon! Written apart, «bien tôt» means very early.","v":"394b2c9e","pos":343},{"idioma":"fr","id":"fr-p300","tipo":"palavra","fr":"assez","en":"enough / quite","aceitasEn":["enough","quite","fairly","rather","pretty"],"distratoresEn":["too much / too","little / few","almost / nearly","so much / so"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Enough («j'ai assez d'argent», I have enough money) and fairly: «c'est assez loin», it's quite far. «J'en ai assez !», I've had enough!","v":"a09f7bf3","pos":162},{"idioma":"fr","id":"fr-u253","tipo":"frase","requer":"fr-p274","fr":"Ouvrez la bouche, s'il vous plaît.","aceitasFr":["Ouvre la bouche, s'il te plaît."],"en":"Open your mouth, please.","aceitasEn":["open your mouth please","please open your mouth","open your mouth","open wide please"],"distratoresEn":["Open your hand, please.","Open your bag, please.","Open your suitcase, please.","Open your book, please."],"nivel":"A1","tags":["saúde","corpo"],"notaEn":"What the doctor or dentist says. With body parts French uses «la», not «your»: «ouvrez la bouche», «fermez les yeux».","requerTodas":["fr-p169","fr-p274"],"v":"52f9e61a"},{"idioma":"fr","id":"fr-u254","tipo":"frase","requer":"fr-p275","fr":"J'ai quelque chose dans l'œil.","en":"I have something in my eye.","aceitasEn":["i have something in my eye","ive got something in my eye","theres something in my eye","i got something in my eye"],"distratoresEn":["I have something in my ear.","I have something in my nose.","I have something in my tooth.","I have something in my shoe."],"nivel":"A1","tags":["corpo","saúde"],"notaEn":"«L'œil» has an irregular plural: «les yeux», the eyes. «Quelque chose», something, is always two words.","requerTodas":["fr-p002","fr-p275"],"v":"958547f9"},{"idioma":"fr","id":"fr-u255","tipo":"frase","requer":"fr-p276","fr":"Je me suis cassé le bras.","aceitasFr":["Je me suis cassée le bras.","Je me suis cassé le bras !"],"en":"I broke my arm.","aceitasEn":["i broke my arm","ive broken my arm","i have broken my arm"],"distratoresEn":["I broke my foot.","I broke my nose.","I broke my finger.","I broke my knee."],"nivel":"A1","tags":["corpo","saúde"],"notaEn":"Breaking a body part is «se casser le bras», literally to break oneself the arm, with «la/le» instead of «my». Being reflexive, it takes «être».","requerTodas":["fr-p001","fr-p117","fr-p276"],"v":"e8d79e21"},{"idioma":"fr","id":"fr-u256","tipo":"frase","requer":"fr-p277","fr":"J'ai mal au dos.","en":"My back hurts.","aceitasEn":["my back hurts","i have a backache","ive got a backache","i have back pain","my back is hurting","my back aches"],"distratoresEn":["My leg hurts.","My hand hurts.","My knee hurts.","My neck hurts."],"nivel":"A1","tags":["saúde","corpo"],"notaEn":"«Avoir mal à», to have pain in, is how French says something hurts: «j'ai mal au dos». «À» + «le» contracts to «au».","requerTodas":["fr-p002","fr-p151","fr-p277"],"v":"8046f616"},{"idioma":"fr","id":"fr-u257","tipo":"frase","requer":"fr-p278","fr":"Ces chaussures sont trop petites.","en":"These shoes are too small.","aceitasEn":["these shoes are too small","those shoes are too small","these shoes are too tight"],"distratoresEn":["These socks are too small.","These gloves are too small.","These boots are too small.","These coats are too small."],"nivel":"A1","tags":["roupa","compras"],"notaEn":"«La chaussure» is feminine, so the adjective agrees: «petites». «Trop», too, goes before the adjective.","requerTodas":["fr-p278","fr-p001","fr-p061","fr-p038"],"v":"96b27b10"},{"idioma":"fr","id":"fr-u258","tipo":"frase","requer":"fr-p279","fr":"Je peux essayer ce pantalon ?","aceitasFr":["Est-ce que je peux essayer ce pantalon ?","Je pourrais essayer ce pantalon ?"],"en":"Can I try on these pants?","aceitasEn":["can i try on these pants","can i try these pants on","could i try on these pants","may i try on these pants","can i try on these trousers","can i try these trousers on"],"distratoresEn":["Can I try on this skirt?","Can I try on this jacket?","Can I try on this blouse?","Can I try on this T-shirt?"],"nivel":"A1","tags":["roupa","compras"],"notaEn":"«Le pantalon» is singular: «ce pantalon», these pants. To try on is «essayer», which also means to try.","requerTodas":["fr-p006","fr-p301","fr-p279"],"v":"556cb854"},{"idioma":"fr","id":"fr-u259","tipo":"frase","requer":"fr-p280","fr":"Un sandwich au fromage, s'il vous plaît.","en":"A cheese sandwich, please.","aceitasEn":["a cheese sandwich please","a cheese sandwich","one cheese sandwich please","can i have a cheese sandwich please","id like a cheese sandwich please"],"distratoresEn":["A ham sandwich, please.","A tuna sandwich, please.","A turkey sandwich, please.","An egg sandwich, please."],"nivel":"A1","tags":["comida"],"notaEn":"Fillings and flavors take «à» + article: «au fromage», cheese; «une glace au chocolat», a chocolate ice cream.","requerTodas":["fr-p302","fr-p280"],"v":"6775c78f"},{"idioma":"fr","id":"fr-u260","tipo":"frase","requer":"fr-p281","fr":"Je mange deux œufs au petit déjeuner.","en":"I eat two eggs for breakfast.","aceitasEn":["i eat two eggs for breakfast","i have two eggs for breakfast","i have two eggs at breakfast","i eat two eggs at breakfast"],"distratoresEn":["I eat two yogurts for breakfast.","I eat two rolls for breakfast.","I eat two cookies for breakfast.","I eat two croissants for breakfast."],"nivel":"A1","tags":["comida","cotidiano"],"notaEn":"In the plural, «œufs» drops the «f» sound. Meals take «au»: «au petit déjeuner», for breakfast.","requerTodas":["fr-p013","fr-p120","fr-p281","fr-p156"],"v":"c0bdd0fa"},{"idioma":"fr","id":"fr-u261","tipo":"frase","requer":"fr-p282","fr":"Le poisson est frais ?","aceitasFr":["Est-ce que le poisson est frais ?"],"en":"Is the fish fresh?","aceitasEn":["is the fish fresh","is this fish fresh","is the fish fresh today"],"distratoresEn":["Is the bread fresh?","Is the milk fresh?","Is the juice fresh?","Is the cheese fresh?"],"nivel":"A1","tags":["comida","compras"],"notaEn":"With one «s», «le poison» is poison: the «ss» in «poisson» sounds like «s», the «s» in «poison» like «z». «Frais» is fresh and also cool.","requerTodas":["fr-p282","fr-p001","fr-p303"],"v":"a47c1150"},{"idioma":"fr","id":"fr-u262","tipo":"frase","requer":"fr-p282","fr":"Mon fils a un poisson rouge.","en":"My son has a goldfish.","aceitasEn":["my son has a goldfish","my son has got a goldfish","my son has a pet fish"],"distratoresEn":["My son has a hamster.","My son has a parrot.","My son has a rabbit.","My son has a puppy."],"nivel":"A1","tags":["animais","família"],"notaEn":"A goldfish is «un poisson rouge», a red fish. «Le poisson» is both the live animal and the food.","requerTodas":["fr-p256","fr-p002","fr-p282","fr-p173"],"v":"e36c5b2f"},{"idioma":"fr","id":"fr-u263","tipo":"frase","requer":"fr-p283","fr":"On mange du poulet ce soir ?","en":"Shall we have chicken tonight?","aceitasEn":["shall we have chicken tonight","should we have chicken tonight","how about chicken tonight","shall we eat chicken tonight","should we eat chicken tonight","lets have chicken tonight"],"distratoresEn":["Shall we have pork tonight?","Shall we have steak tonight?","Shall we have rice tonight?","Shall we have pasta tonight?"],"nivel":"A1","tags":["comida"],"notaEn":"For an unspecified amount of food, French needs the partitive: «du poulet», «de la viande», where English uses no article.","requerTodas":["fr-p013","fr-p283","fr-p160"],"v":"d3c38ff0"},{"idioma":"fr","id":"fr-u264","tipo":"frase","requer":"fr-p284","fr":"En hiver, il fait très froid ici.","aceitasFr":["Il fait très froid ici en hiver."],"en":"In winter it's very cold here.","aceitasEn":["in winter its very cold here","its very cold here in winter","in the winter its very cold here","its very cold here in the winter","in winter it is very cold here"],"distratoresEn":["In the fall it's very cold here.","In summer it's very cold here.","At Christmas it's very cold here.","In spring it's very cold here."],"nivel":"A1","tags":["natureza","cotidiano"],"notaEn":"Seasons take «en»: «en hiver», «en été», «en automne»; only spring is different: «au printemps».","requerTodas":["fr-p284","fr-p004","fr-p043","fr-p080","fr-p048"],"v":"78c716cb"},{"idioma":"fr","id":"fr-u265","tipo":"frase","requer":"fr-p285","fr":"Cet été, je vais à la mer.","aceitasFr":["Je vais à la mer cet été."],"en":"This summer I'm going to the beach.","aceitasEn":["this summer im going to the beach","im going to the beach this summer","this summer im going to the seaside","this summer i am going to the beach","this summer ill go to the beach","this summer im going to the sea"],"distratoresEn":["This winter I'm going to the beach.","This fall I'm going to the beach.","This month I'm going to the beach.","This weekend I'm going to the beach."],"nivel":"A1","tags":["viagem","natureza"],"notaEn":"«Cet été», this summer: «ce» becomes «cet» before a vowel or silent «h». «Aller à la mer» is going to the seaside.","requerTodas":["fr-p285","fr-p003","fr-p092"],"v":"928937a6"},{"idioma":"fr","id":"fr-u266","tipo":"frase","requer":"fr-p286","fr":"Je pars en vacances le mois prochain.","en":"I'm going on vacation next month.","aceitasEn":["im going on vacation next month","im going on holiday next month","i am going on vacation next month","ill go on vacation next month","im leaving on vacation next month","i go on vacation next month"],"distratoresEn":["I'm going on vacation next year.","I'm going on vacation next Saturday.","I'm going on vacation next summer.","I'm going on vacation next Sunday."],"nivel":"A1","tags":["viagem","cotidiano"],"notaEn":"«Le mois prochain», next month, with the article and no preposition. «Mois» ends in «s» even in the singular.","requerTodas":["fr-p083","fr-p163","fr-p286","fr-p238"],"v":"2d9cb944"},{"idioma":"fr","id":"fr-u267","tipo":"frase","requer":"fr-p287","fr":"La chambre a une salle de bains ?","aceitasFr":["Est-ce que la chambre a une salle de bains ?","Il y a une salle de bains dans la chambre ?"],"en":"Does the room have a bathroom?","aceitasEn":["does the room have a bathroom","does the room have its own bathroom","is there a bathroom in the room","does the room have a private bathroom","does the room come with a bathroom","has the room got a bathroom"],"distratoresEn":["Does the room have a minibar?","Does the room have air conditioning?","Does the room have a safe?","Does the room have a closet?"],"nivel":"A1","tags":["viagem","casa"],"notaEn":"«La salle de bains» is the room with the shower and sink; the toilet is often separate, in «les toilettes». In a hotel, «la chambre» is the room.","requerTodas":["fr-p107","fr-p002","fr-p287"],"v":"f50289b1"},{"idioma":"fr","id":"fr-u268","tipo":"frase","requer":"fr-p288","fr":"On va à l'église le dimanche.","aceitasFr":["Nous allons à l'église le dimanche."],"en":"We go to church on Sundays.","aceitasEn":["we go to church on sundays","we go to church every sunday","on sundays we go to church","we go to the church on sundays","we go to church on sunday"],"distratoresEn":["We go to the market on Sundays.","We go to the beach on Sundays.","We go to the pool on Sundays.","We go to the gym on Sundays."],"nivel":"A1","tags":["cultura","cidade"],"notaEn":"With «le», a weekday means a habit: «le dimanche», on Sundays. «À la» becomes «à l'» before a vowel.","requerTodas":["fr-p003","fr-p288","fr-p304"],"v":"414e41a5"},{"idioma":"fr","id":"fr-u269","tipo":"frase","requer":"fr-p289","fr":"Elle chante très bien.","en":"She sings very well.","aceitasEn":["she sings very well","she sings really well","shes a very good singer","she is a very good singer","shes a great singer","she sings beautifully"],"distratoresEn":["She dances very well.","She draws very well.","She cooks very well.","She writes very well."],"nivel":"A1","tags":["cultura"],"notaEn":"«Chanter» is a regular «-er» verb; «chante», «chantes» and «chantent» all sound the same. A song is «une chanson».","requerTodas":["fr-p289","fr-p043","fr-p044"],"v":"d4117f21"},{"idioma":"fr","id":"fr-u270","tipo":"frase","requer":"fr-p290","fr":"Elle apprend vite.","en":"She learns fast.","aceitasEn":["she learns fast","she learns quickly","shes a fast learner","she is a fast learner","shes a quick learner","she is a quick learner"],"distratoresEn":["She forgets fast.","She talks fast.","She eats fast.","She walks fast."],"nivel":"A1","tags":["escola"],"notaEn":"«Apprendre» is conjugated like «prendre»: j'apprends, il apprend, nous apprenons, ils apprennent.","requerTodas":["fr-p290","fr-p062"],"v":"e853ea64"},{"idioma":"fr","id":"fr-u271","tipo":"frase","requer":"fr-p290","fr":"Mon père m'a appris à nager.","en":"My father taught me to swim.","aceitasEn":["my father taught me to swim","my dad taught me to swim","my father taught me how to swim","my dad taught me how to swim","i learned to swim from my father","i learned to swim from my dad"],"distratoresEn":["My father made me swim.","My father helped me swim.","My father encouraged me to swim.","My father challenged me to swim."],"nivel":"A1","tags":["família","escola"],"notaEn":"«Apprendre» also means to teach: «apprendre quelque chose à quelqu'un». «Il m'a appris à nager», he taught me to swim. The participle is «appris».","requerTodas":["fr-p103","fr-p002","fr-p290","fr-p058"],"v":"a7cb2449"},{"idioma":"fr","id":"fr-u272","tipo":"frase","requer":"fr-p291","fr":"Je cours tous les matins.","en":"I run every morning.","aceitasEn":["i run every morning","i go running every morning","i go for a run every morning","i jog every morning","i go jogging every morning","i run each morning"],"distratoresEn":["I swim every morning.","I walk every morning.","I read every morning.","I study every morning."],"nivel":"A1","tags":["saúde","cotidiano"],"notaEn":"«Courir» is irregular: je cours, tu cours, il court, nous courons. Every morning is «tous les matins», literally all the mornings.","requerTodas":["fr-p291","fr-p070","fr-p153"],"v":"3f3d3762"},{"idioma":"fr","id":"fr-u273","tipo":"frase","requer":"fr-p292","fr":"Écoute-moi !","aceitasFr":["Écoutez-moi !"],"en":"Listen to me!","aceitasEn":["listen to me","listen","listen to me please","hear me out"],"distratoresEn":["Look at me!","Help me!","Hug me!","Follow me!"],"nivel":"A1","tags":["cotidiano"],"notaEn":"In a positive command the pronoun follows with a hyphen, and «me» becomes «moi»: «écoute-moi». «Écouter» needs no preposition: no «to».","requerTodas":["fr-p292"],"v":"f8874208"},{"idioma":"fr","id":"fr-u274","tipo":"frase","requer":"fr-p292","fr":"J'aime écouter de la musique.","en":"I like listening to music.","aceitasEn":["i like listening to music","i like to listen to music","i love listening to music","i enjoy listening to music","i love to listen to music"],"distratoresEn":["I like playing music.","I like writing music.","I like downloading music.","I like studying music."],"nivel":"A1","tags":["cultura","cotidiano"],"notaEn":"«Écouter» takes no preposition: «écouter de la musique», listen to music. To hear a sound is «entendre».","requerTodas":["fr-p015","fr-p292","fr-p305"],"v":"9ff9a10f"},{"idioma":"fr","id":"fr-u275","tipo":"frase","requer":"fr-p293","fr":"Je vis seul.","aceitasFr":["Je vis seule.","J'habite seul.","J'habite seule."],"en":"I live alone.","aceitasEn":["i live alone","i live by myself","i live on my own"],"distratoresEn":["I travel alone.","I work alone.","I eat alone.","I sleep alone."],"nivel":"A1","tags":["casa","social"],"notaEn":"«Vivre» is irregular: je vis, tu vis, il vit, nous vivons. «Seul» means alone; feminine «seule». Only, just, is «seulement».","requerTodas":["fr-p293","fr-p306"],"v":"5b239802"},{"idioma":"fr","id":"fr-u276","tipo":"frase","requer":"fr-p293","fr":"On ne vit qu'une fois.","en":"You only live once.","aceitasEn":["you only live once","we only live once","one only lives once"],"distratoresEn":["You only die once.","You only love once.","You're only born once.","You only marry once."],"nivel":"A2","tags":["expressão","cotidiano"],"notaEn":"«Ne… que» means only: «je n'ai que dix euros», I only have ten euros. A time, when counting, is «la fois»: «une fois», once.","requerTodas":["fr-p293","fr-p307"],"v":"bc6bee4f"},{"idioma":"fr","id":"fr-u277","tipo":"frase","requer":"fr-p294","fr":"Le café est trop fort.","en":"The coffee is too strong.","aceitasEn":["the coffee is too strong","this coffee is too strong","the coffee is way too strong"],"distratoresEn":["The coffee is too sweet.","The coffee is too bitter.","The coffee is too weak.","The coffee is too cold."],"nivel":"A1","tags":["comida"],"notaEn":"«Fort» is strong, for people and drinks alike; weak coffee is «léger». Feminine «forte».","requerTodas":["fr-p057","fr-p001","fr-p061","fr-p294"],"v":"3aa28f96"},{"idioma":"fr","id":"fr-u278","tipo":"frase","requer":"fr-p294","fr":"Parle plus fort !","aceitasFr":["Parlez plus fort !"],"en":"Speak up!","aceitasEn":["speak up","speak louder","talk louder","speak more loudly","speak up please","talk more loudly"],"distratoresEn":["Speak more quietly!","Speak more slowly!","Speak faster!","Speak more clearly!"],"nivel":"A1","tags":["cotidiano","escola"],"notaEn":"As an adverb, «fort» means loud: «parler fort», to speak loudly. Quietly is «doucement».","requerTodas":["fr-p012","fr-p294"],"v":"bc19ae57"},{"idioma":"fr","id":"fr-u279","tipo":"frase","requer":"fr-p295","fr":"Il est encore jeune.","en":"He's still young.","aceitasEn":["hes still young","he is still young","hes young still"],"distratoresEn":["He's still single.","He's still shy.","He's still thin.","He's still short."],"nivel":"A1","tags":["família","social"],"notaEn":"Young is «jeune», the same in the masculine and feminine. «Les jeunes», young people.","requerTodas":["fr-p001","fr-p202","fr-p295"],"v":"d4f9edc5"},{"idioma":"fr","id":"fr-u280","tipo":"frase","requer":"fr-p296","fr":"Ta chemise n'est pas propre.","en":"Your shirt isn't clean.","aceitasEn":["your shirt isnt clean","your shirt is not clean","your shirt is dirty","your shirts not clean","your shirts dirty"],"distratoresEn":["Your shirt isn't ironed.","Your shirt isn't dry.","Your shirt isn't folded.","Your shirt isn't new."],"nivel":"A2","tags":["roupa","casa"],"notaEn":"After the noun, «propre» means clean: «une chemise propre». Before it, own: «ma propre chambre». Dirty is «sale».","requerTodas":["fr-p209","fr-p001","fr-p296"],"v":"60eec718"},{"idioma":"fr","id":"fr-u281","tipo":"frase","requer":"fr-p296","fr":"Elle a sa propre chambre.","en":"She has her own room.","aceitasEn":["she has her own room","she has a room of her own","shes got her own room","she has got her own room"],"distratoresEn":["She has a tidy room.","She has a dark room.","She has a messy room.","She has a crowded room."],"nivel":"A2","tags":["casa","família"],"notaEn":"Before the noun, «propre» means own: «sa propre chambre», her own room. After it, clean: «une chambre propre», a clean room.","requerTodas":["fr-p002","fr-p296","fr-p107"],"v":"d99f3340"},{"idioma":"fr","id":"fr-u282","tipo":"frase","requer":"fr-p297","fr":"Le frigo est vide.","en":"The fridge is empty.","aceitasEn":["the fridge is empty","the fridges empty","the refrigerator is empty","theres nothing in the fridge"],"distratoresEn":["The fridge is full.","The fridge is broken.","The fridge is open.","The fridge is off."],"nivel":"A2","tags":["casa","comida"],"notaEn":"«Vide» is the same in the masculine and feminine. The opposite is «plein», full.","requerTodas":["fr-p207","fr-p001","fr-p297"],"v":"281d861a"},{"idioma":"fr","id":"fr-u283","tipo":"frase","requer":"fr-p298","fr":"On mange ensemble ?","en":"Shall we eat together?","aceitasEn":["shall we eat together","should we eat together","lets eat together","do you want to eat together","want to eat together"],"distratoresEn":["Shall we eat out?","Shall we eat now?","Shall we eat later?","Shall we eat here?"],"nivel":"A1","tags":["social","comida"],"notaEn":"«Ensemble» is an adverb and never changes. «On» with a third-person verb is the everyday «we».","requerTodas":["fr-p013","fr-p298"],"v":"10e9c5e5"},{"idioma":"fr","id":"fr-u284","tipo":"frase","requer":"fr-p299","fr":"Le bus arrive bientôt.","en":"The bus will be here soon.","aceitasEn":["the bus will be here soon","the bus is coming soon","the bus arrives soon","the bus will arrive soon","the bus is almost here","the bus will come soon"],"distratoresEn":["The bus will be here late.","The bus will be here early.","The bus will be here tomorrow.","The bus will be here tonight."],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"«Bientôt», soon, is one word; written apart, «bien tôt» means very early. Ready is «prêt».","requerTodas":["fr-p060","fr-p115","fr-p299"],"v":"ef8c7ef1"},{"idioma":"fr","id":"fr-u285","tipo":"frase","requer":"fr-p300","fr":"Je n'ai pas assez d'argent.","en":"I don't have enough money.","aceitasEn":["i dont have enough money","i do not have enough money","i havent got enough money","i havent enough money"],"distratoresEn":["I don't have any change.","I don't have any cash.","I don't have any savings.","I don't have money on me."],"nivel":"A1","tags":["compras","economia"],"notaEn":"After «assez», as after any quantity, comes plain «de»: «assez d'argent», enough money; «assez de temps», enough time.","requerTodas":["fr-p002","fr-p300","fr-p035"],"v":"d7280323"},{"idioma":"fr","id":"fr-u286","tipo":"frase","requer":"fr-p300","fr":"C'est assez loin d'ici.","en":"It's quite far from here.","aceitasEn":["its quite far from here","its pretty far from here","its fairly far from here","its rather far from here","its a bit far from here","it is quite far from here"],"distratoresEn":["It's very far from here.","It's too far from here.","It's not that far from here.","It's very close to here."],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"Before an adjective or adverb, «assez» means quite, fairly: «assez loin», «assez cher». Very is «très»; too, «trop».","requerTodas":["fr-p001","fr-p300","fr-p164","fr-p048"],"v":"6b9208f8"},{"idioma":"fr","id":"fr-u287","tipo":"frase","requer":"fr-p206","fr":"Le magasin ferme à quelle heure ?","aceitasFr":["À quelle heure ferme le magasin ?","Le magasin ferme à quelle heure ?"],"en":"What time does the store close?","aceitasEn":["what time does the store close","when does the store close","what time does the shop close","when does the shop close","what time is the store closing"],"distratoresEn":["What time does the store open?","What time does the store reopen?","What time does the store fill up?","What time does the store empty out?"],"nivel":"A1","tags":["compras","cidade"],"notaEn":"In speech the question word can come last: «le magasin ferme à quelle heure ?». The opposite of «fermer» is «ouvrir».","requerTodas":["fr-p223","fr-p206","fr-p129"],"v":"0ddd7607"},{"idioma":"fr","id":"fr-u288","tipo":"frase","requer":"fr-p229","fr":"Je t'appelle ce soir.","en":"I'll call you tonight.","aceitasEn":["ill call you tonight","i will call you tonight","ill call you this evening","ill give you a call tonight","ill phone you tonight","ill ring you tonight"],"distratoresEn":["I'll write to you tonight.","I'll visit you tonight.","I'll pick you up tonight.","I'll see you tonight."],"nivel":"A1","tags":["social","tecnologia"],"notaEn":"«Appeler» is to call, in person or by phone. The «l» doubles before a silent ending: «j'appelle», but «nous appelons».","requerTodas":["fr-p229","fr-p160"],"v":"0835817a"},{"idioma":"fr","id":"fr-u289","tipo":"frase","requer":"fr-p269","fr":"Ce soir, je reste à la maison.","aceitasFr":["Je reste à la maison ce soir."],"en":"I'm staying home tonight.","aceitasEn":["im staying home tonight","im staying at home tonight","tonight im staying home","ill stay home tonight","ill stay at home tonight","i am staying home tonight"],"distratoresEn":["I'm sleeping at home tonight.","I'm having dinner at home tonight.","I'm working from home tonight.","I'm studying at home tonight."],"nivel":"A1","tags":["casa","cotidiano"],"notaEn":"«Rester» means to stay, not to rest («se reposer»). The present tense works for near plans: «ce soir, je reste».","requerTodas":["fr-p160","fr-p269","fr-p020"],"v":"2477b0d0"},{"idioma":"fr","id":"fr-u290","tipo":"frase","requer":"fr-p269","fr":"Il reste du pain ?","aceitasFr":["Est-ce qu'il reste du pain ?"],"en":"Is there any bread left?","aceitasEn":["is there any bread left","is there bread left","is there any bread left over","do we have any bread left","is there still bread","any bread left"],"distratoresEn":["Did any bread arrive?","Did any bread burn?","Is there any bread missing?","Did any bread go bad?"],"nivel":"A2","tags":["comida","casa"],"notaEn":"«Il reste» means there's some left: «il reste du pain», «il me reste dix euros», I have ten euros left. The «il» is impersonal, as in «il y a».","requerTodas":["fr-p269","fr-p027"],"v":"4c30ffce"},{"idioma":"fr","id":"fr-u291","tipo":"frase","requer":"fr-p228","fr":"Attention, tu vas tomber !","en":"Careful, you're going to fall!","aceitasEn":["careful youre going to fall","careful youll fall","watch out youre going to fall","be careful youre going to fall","careful youre gonna fall","watch out youll fall"],"distratoresEn":["Careful, you're going to cut yourself!","Careful, you're going to burn yourself!","Careful, you're going to get wet!","Careful, you're going to get lost!"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Tomber» is to fall. «Attention !» on its own means careful!, watch out!","requerTodas":["fr-p127","fr-p003","fr-p228"],"v":"10850c1d"},{"idioma":"fr","id":"fr-u292","tipo":"frase","requer":"fr-p228","fr":"Il est tombé amoureux d'elle.","en":"He fell in love with her.","aceitasEn":["he fell in love with her","he fell for her","he has fallen in love with her","hes fallen in love with her"],"distratoresEn":["He took an interest in her.","He took a risk for her.","He got tired of her.","He remembered her."],"nivel":"A2","tags":["social","família"],"notaEn":"To fall in love is «tomber amoureux de», just as in English. With «être», the participle agrees: «elle est tombée amoureuse».","requerTodas":["fr-p001","fr-p228","fr-p308"],"v":"1e1e7e27"},{"idioma":"fr","id":"fr-u293","tipo":"frase","requer":"fr-p232","fr":"Je peux porter ta valise ?","en":"Can I carry your suitcase?","aceitasEn":["can i carry your suitcase","can i carry your bag","could i carry your suitcase","shall i carry your suitcase","let me carry your suitcase","can i take your suitcase"],"distratoresEn":["Can I open your suitcase?","Can I close your suitcase?","Can I store your suitcase?","Can I weigh your suitcase?"],"nivel":"A1","tags":["viagem"],"notaEn":"«Porter» is to carry and also to wear. A suitcase is «la valise».","requerTodas":["fr-p006","fr-p232","fr-p309"],"v":"3ed813e8"},{"idioma":"fr","id":"fr-u294","tipo":"frase","requer":"fr-p232","fr":"Il porte des lunettes.","en":"He wears glasses.","aceitasEn":["he wears glasses","he is wearing glasses","hes wearing glasses","he has glasses"],"distratoresEn":["He wears braces.","He uses a cane.","He wears a wig.","He wears a cap."],"nivel":"A1","tags":["roupa","saúde"],"notaEn":"To wear clothes, glasses or accessories is «porter». «Les lunettes», glasses, is always plural and feminine.","requerTodas":["fr-p232","fr-p310"],"v":"a44e1014"},{"idioma":"fr","id":"fr-u295","tipo":"frase","requer":"fr-p270","fr":"Je marche une heure par jour.","en":"I walk for an hour a day.","aceitasEn":["i walk for an hour a day","i walk an hour a day","i walk for an hour every day","i walk one hour a day","i go walking for an hour a day"],"distratoresEn":["I swim for an hour a day.","I read for an hour a day.","I sleep for an hour a day.","I study for an hour a day."],"nivel":"A1","tags":["saúde","cotidiano"],"notaEn":"«Marcher» is to walk. A day, per day, is «par jour»: «trois fois par jour», three times a day.","requerTodas":["fr-p270","fr-p129","fr-p019"],"v":"f6288499"},{"idioma":"fr","id":"fr-u296","tipo":"frase","requer":"fr-p270","fr":"Mon portable ne marche plus.","en":"My phone doesn't work anymore.","aceitasEn":["my phone doesnt work anymore","my phone does not work anymore","my phone isnt working anymore","my cell phone doesnt work anymore","my phone stopped working","my phone has stopped working","my mobile doesnt work anymore"],"distratoresEn":["My phone doesn't charge anymore.","My phone doesn't turn on anymore.","My phone doesn't ring anymore.","My phone doesn't vibrate anymore."],"nivel":"A1","tags":["tecnologia","objetos"],"notaEn":"For a device, «marcher» means to work: «ça marche», it works, and also OK, deal! «Ne… plus» means no longer.","requerTodas":["fr-p212","fr-p270"],"v":"ba25a53e"},{"idioma":"fr","id":"fr-u297","tipo":"frase","requer":"fr-p210","fr":"On a gagné le match !","aceitasFr":["Nous avons gagné le match !"],"en":"We won the game!","aceitasEn":["we won the game","we won the match","weve won the game","we have won the game","we won"],"distratoresEn":["We lost the game!","We tied the game!","We postponed the game!","We watched the game!"],"nivel":"A1","tags":["cultura","social"],"notaEn":"«Gagner» is to win. The opposite is «perdre»: «on a perdu», we lost. A sports game is «le match».","requerTodas":["fr-p002","fr-p210","fr-p311"],"v":"ad2811e4"},{"idioma":"fr","id":"fr-u298","tipo":"frase","requer":"fr-p210","fr":"Elle gagne beaucoup d'argent.","en":"She earns a lot of money.","aceitasEn":["she earns a lot of money","she makes a lot of money","she earns lots of money","she makes lots of money","she earns good money"],"distratoresEn":["She spends a lot of money.","She owes a lot of money.","She lends a lot of money.","She saves a lot of money."],"nivel":"A1","tags":["trabalho","economia"],"notaEn":"«Gagner» also means to earn: «gagner sa vie», to earn a living. After «beaucoup» comes plain «de»: «beaucoup d'argent».","requerTodas":["fr-p210","fr-p067","fr-p035"],"v":"7b69b4e3"},{"idioma":"fr","id":"fr-u299","tipo":"frase","requer":"fr-p252","fr":"Vite, on va rater le train !","en":"Hurry, we'll miss the train!","aceitasEn":["hurry well miss the train","hurry we are going to miss the train","quick we will miss the train","hurry we will miss the train","hurry up we are going to miss the train"],"distratoresEn":["Hurry, we'll catch the train!","Hurry, we'll wait for the train!","Hurry, we'll stop the train!","Hurry, we'll see the train!"],"nivel":"A1","tags":["viagem"],"notaEn":"«Rater» is to miss something that goes by: a train, a bus, a chance. To lose something you had is «perdre».","requerTodas":["fr-p062","fr-p003","fr-p252","fr-p089"],"v":"3fcdc9b7"},{"idioma":"fr","id":"fr-u300","tipo":"frase","requer":"fr-p252","fr":"J'ai raté mon examen.","en":"I failed my exam.","aceitasEn":["i failed my exam","i failed the exam","i flunked my exam","i flunked the exam","i did badly on my exam"],"distratoresEn":["I passed my exam.","I finished my exam.","I took my exam.","I postponed my exam."],"nivel":"A2","tags":["escola"],"notaEn":"«Rater» also means to fail, to mess up: «rater un examen». Careful: «passer un examen» is just to take it; to pass is «réussir».","requerTodas":["fr-p002","fr-p252","fr-p264"],"v":"21e7cf1a"},{"idioma":"fr","id":"fr-u301","tipo":"frase","requer":"fr-p218","fr":"Il n'y a plus de place.","en":"There's no more room.","aceitasEn":["theres no more room","there is no more room","theres no room left","there are no more seats","theres no more space","there is no room left"],"distratoresEn":["There's no more time.","There's no more change.","There's no more signal.","There's no more ice."],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"«La place» is a seat or room to fit: «il n'y a plus de place», there's no room. A place in general is «l'endroit».","requerTodas":["fr-p002","fr-p218"],"v":"c86e3480"},{"idioma":"fr","id":"fr-u302","tipo":"frase","requer":"fr-p218","fr":"Le marché est sur la place.","en":"The market is in the square.","aceitasEn":["the market is in the square","the market is on the square","the market is in the town square","the markets in the square","the market is in the main square"],"distratoresEn":["The market is on the street.","The market is on the corner.","The market is at the school.","The market is at the church."],"nivel":"A1","tags":["cidade","compras"],"notaEn":"«La place» is also a town square: «sur la place», in the square. «Le marché» is an open-air market.","requerTodas":["fr-p312","fr-p001","fr-p218"],"v":"296ab91d"},{"idioma":"fr","id":"fr-u303","tipo":"frase","requer":"fr-p233","fr":"C'est ton tour.","aceitasFr":["C'est à ton tour.","C'est votre tour.","C'est à toi."],"en":"It's your turn.","aceitasEn":["its your turn","your turn","its your go","youre up","it is your turn"],"distratoresEn":["It's your chance.","It's your house.","It's your table.","It's your key."],"nivel":"A1","tags":["cotidiano","social"],"notaEn":"Masculine «le tour» is a turn or a trip around; feminine «la tour» is a tower: «la tour Eiffel».","requerTodas":["fr-p001","fr-p233"],"v":"c29b2a25"},{"idioma":"fr","id":"fr-u304","tipo":"frase","requer":"fr-p233","fr":"On fait un tour ?","en":"Shall we go for a walk?","aceitasEn":["shall we go for a walk","should we go for a walk","lets go for a walk","shall we take a walk","want to go for a walk","shall we go for a spin","lets go for a ride","shall we go for a ride"],"distratoresEn":["Shall we go for a run?","Shall we go for a swim?","Shall we go for a drink?","Shall we go for a coffee?"],"nivel":"A1","tags":["social","cidade"],"notaEn":"«Faire un tour» is to go for a walk, a drive or a ride. «On» is the everyday «we», and the question is an invitation.","requerTodas":["fr-p004","fr-p233"],"v":"b4ff7f3b"},{"idioma":"fr","id":"fr-u305","tipo":"frase","requer":"fr-p241","fr":"Tournez à gauche.","aceitasFr":["Tourne à gauche."],"en":"Turn left.","aceitasEn":["turn left","turn to the left","take a left","make a left","go left","turn left please"],"distratoresEn":["Turn right.","Turn at the corner.","Turn at the roundabout.","Turn at the square."],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"«À gauche», left, and «à droite», right. To turn is «tourner»; «tournez» is the polite command.","requerTodas":["fr-p313","fr-p241"],"v":"fa8c0f7b"},{"idioma":"fr","id":"fr-u306","tipo":"frase","requer":"fr-p244","fr":"La pharmacie est à droite.","en":"The pharmacy is on the right.","aceitasEn":["the pharmacy is on the right","the drugstore is on the right","the pharmacys on the right","the pharmacy is to the right","the drugstores on the right"],"distratoresEn":["The bakery is on the right.","The school is on the right.","The church is on the right.","The station is on the right."],"nivel":"A1","tags":["saúde","cidade"],"notaEn":"On the right is «à droite», with an «e»; without it, «droit» means straight: «tout droit», straight ahead.","requerTodas":["fr-p244","fr-p001","fr-p314"],"v":"69ee0fff"},{"idioma":"fr","id":"fr-u307","tipo":"frase","requer":"fr-p245","fr":"Je vais à la boulangerie.","en":"I'm going to the bakery.","aceitasEn":["im going to the bakery","i am going to the bakery","im off to the bakery","im going to the bakers","im heading to the bakery"],"distratoresEn":["I'm going to the pharmacy.","I'm going to the school.","I'm going to the market.","I'm going to the gym."],"nivel":"A1","tags":["compras","cidade"],"notaEn":"«La boulangerie» sells bread; «la pâtisserie», pastries. «À la» stays as two words; only «à le» contracts to «au».","requerTodas":["fr-p003","fr-p245"],"v":"726d5293"},{"idioma":"fr","id":"fr-u308","tipo":"frase","requer":"fr-p246","fr":"J'habite près de la gare.","en":"I live near the station.","aceitasEn":["i live near the station","i live close to the station","i live near the train station","i live close to the train station"],"distratoresEn":["I live far from the station.","I live behind the station.","I live across from the station.","I live above the station."],"nivel":"A1","tags":["cidade","casa"],"notaEn":"Near is «près de», and «de» + «le» becomes «du»: «près du parc». Don't confuse it with «prêt», ready.","requerTodas":["fr-p016","fr-p246","fr-p188"],"v":"9b6bf022"},{"idioma":"fr","id":"fr-u309","tipo":"frase","requer":"fr-p238","fr":"Je descends au prochain arrêt.","en":"I'm getting off at the next stop.","aceitasEn":["im getting off at the next stop","ill get off at the next stop","i get off at the next stop","i am getting off at the next stop"],"distratoresEn":["I'm getting off at the last stop.","I'm getting off at the first stop.","I'm getting off at the second stop.","I'm getting off at the third stop."],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"«Prochain» means next: «le prochain arrêt», the next stop. Near is «proche». To get off a bus is «descendre».","requerTodas":["fr-p315","fr-p238","fr-p316"],"v":"0675e61d"},{"idioma":"fr","id":"fr-u310","tipo":"frase","requer":"fr-p211","fr":"C'est la première fois que je viens ici.","en":"It's the first time I've come here.","aceitasEn":["its the first time ive come here","its my first time here","this is my first time here","its the first time ive been here","this is the first time ive been here","its the first time i have come here"],"distratoresEn":["It's the last time I've come here.","It's the second time I've come here.","It's the third time I've come here.","It's the fifth time I've come here."],"nivel":"A1","tags":["viagem","social"],"notaEn":"Feminine «première»: «la première fois». French uses the present here: «je viens», where English says «I've come».","requerTodas":["fr-p001","fr-p211","fr-p307","fr-p009","fr-p048"],"v":"199f766b"},{"idioma":"fr","id":"fr-u311","tipo":"frase","requer":"fr-p240","fr":"J'habite au deuxième étage.","en":"I live on the third floor.","aceitasEn":["i live on the third floor","i live on the second floor"],"distratoresEn":["I live on the fourth floor.","I live on the fifth floor.","I live on the top floor.","I live on the ground floor."],"nivel":"A1","tags":["casa","cidade"],"notaEn":"France counts floors from the ground floor, «le rez-de-chaussée», which is floor zero: «le deuxième étage» is what Americans call the third floor (the British second floor).","requerTodas":["fr-p016","fr-p240","fr-p317"],"v":"7cf92a2c"},{"idioma":"fr","id":"fr-u312","tipo":"frase","requer":"fr-p248","fr":"Je me sens mieux.","en":"I feel better.","aceitasEn":["i feel better","im feeling better","i am feeling better","im better","i am better"],"distratoresEn":["I feel worse.","I feel lonely.","I feel tired.","I feel guilty."],"nivel":"A1","tags":["saúde"],"notaEn":"«Mieux» is better as an adverb («je me sens mieux»); «meilleur» is the adjective: «un meilleur restaurant».","requerTodas":["fr-p248","fr-p318"],"v":"1e27d7ad"},{"idioma":"fr","id":"fr-u313","tipo":"frase","requer":"fr-p249","fr":"Tu peux me présenter ton ami ?","en":"Can you introduce me to your friend?","aceitasEn":["can you introduce me to your friend","could you introduce me to your friend","will you introduce me to your friend","can you introduce your friend to me"],"distratoresEn":["Can you show me your friend?","Can you describe your friend to me?","Can you bring me your friend?","Can you recommend your friend to me?"],"nivel":"A1","tags":["social"],"notaEn":"«Présenter» is to introduce someone; it takes no «to»: «me présenter ton ami». The pronoun goes before the infinitive.","requerTodas":["fr-p006","fr-p249","fr-p024"],"v":"af4983b3"},{"idioma":"fr","id":"fr-u314","tipo":"frase","requer":"fr-p247","fr":"Je vais chez mes parents ce week-end.","en":"I'm going to my parents' this weekend.","aceitasEn":["im going to my parents this weekend","im going to my parents place this weekend","im going to my parents house this weekend","this weekend im going to my parents","im visiting my parents this weekend","i am going to my parents this weekend"],"distratoresEn":["I'm going to my grandparents' this weekend.","I'm going to my cousins' this weekend.","I'm going to my in-laws' this weekend.","I'm going to my uncle's this weekend."],"nivel":"A1","tags":["família"],"notaEn":"«Chez» means at or to someone's place: «chez mes parents». «Le week-end» is borrowed from English.","requerTodas":["fr-p003","fr-p247","fr-p319"],"v":"7310c29e"},{"idioma":"fr","id":"fr-u315","tipo":"frase","requer":"fr-p220","fr":"J'ai une fille et un fils.","en":"I have a daughter and a son.","aceitasEn":["i have a daughter and a son","ive got a daughter and a son","i have a son and a daughter"],"distratoresEn":["I have a niece and a son.","I have a stepdaughter and a son.","I have a granddaughter and a son.","I have a goddaughter and a son."],"nivel":"A1","tags":["família"],"notaEn":"«La fille» is a daughter; «le fils», a son, pronounced «fees». They look alike in writing: «fille», «fils».","requerTodas":["fr-p002","fr-p220","fr-p256"],"v":"9cb56048"},{"idioma":"fr","id":"fr-u316","tipo":"frase","requer":"fr-p220","fr":"Qui est cette fille ?","en":"Who's that girl?","aceitasEn":["whos that girl","who is that girl","who is this girl","whos this girl"],"distratoresEn":["Who's that lady?","Who's that woman?","Who's that teacher?","Who's that neighbor?"],"nivel":"A1","tags":["social"],"notaEn":"Without a possessive, «une fille» is a girl; with one, «ma fille», a daughter. A boy is «un garçon».","requerTodas":["fr-p001","fr-p220"],"v":"d3c2b558"},{"idioma":"fr","id":"fr-u317","tipo":"frase","requer":"fr-p256","fr":"Son fils est médecin.","en":"His son is a doctor.","aceitasEn":["his son is a doctor","her son is a doctor","his sons a doctor","her sons a doctor"],"distratoresEn":["His brother is a doctor.","His uncle is a doctor.","His grandson is a doctor.","His nephew is a doctor."],"nivel":"A1","tags":["família","profissões"],"notaEn":"«Son fils» means his son or her son: the possessive agrees with the thing owned. Professions take no article: «il est médecin».","requerTodas":["fr-p256","fr-p001","fr-p155"],"v":"59353f6e"},{"idioma":"fr","id":"fr-u318","tipo":"frase","requer":"fr-p231","fr":"Je prends l'avion demain.","en":"I'm taking the plane tomorrow.","aceitasEn":["im taking the plane tomorrow","im flying tomorrow","i am flying tomorrow","i take the plane tomorrow","im catching a plane tomorrow","ill take the plane tomorrow"],"distratoresEn":["I'm taking the boat tomorrow.","I'm taking the train tomorrow.","I'm taking the bus tomorrow.","I'm taking the subway tomorrow."],"nivel":"A1","tags":["viagem"],"notaEn":"To take a means of transport is «prendre»: «prendre l'avion». The present with «demain» already refers to the future.","requerTodas":["fr-p011","fr-p231","fr-p059"],"v":"1c8538db"},{"idioma":"fr","id":"fr-u319","tipo":"frase","requer":"fr-p234","fr":"On va au musée demain ?","en":"Shall we go to the museum tomorrow?","aceitasEn":["shall we go to the museum tomorrow","should we go to the museum tomorrow","lets go to the museum tomorrow","do you want to go to the museum tomorrow","are we going to the museum tomorrow"],"distratoresEn":["Shall we go to the park tomorrow?","Shall we go to the movies tomorrow?","Shall we go to the theater tomorrow?","Shall we go to the zoo tomorrow?"],"nivel":"A1","tags":["cultura","cidade"],"notaEn":"«Le musée» is masculine despite its «-ée» ending, hence «au musée». A question with «on» is an invitation.","requerTodas":["fr-p003","fr-p234","fr-p059"],"v":"44de2c49"},{"idioma":"fr","id":"fr-u320","tipo":"frase","requer":"fr-p213","fr":"À l'aide !","en":"Help!","aceitasEn":["help","somebody help","somebody help me","help me"],"distratoresEn":["Fire!","Careful!","Stop, thief!","Quiet!"],"nivel":"A1","tags":["cotidiano","saúde"],"notaEn":"The cry for help. «Au secours !» means the same. Fire! is «Au feu !».","requerTodas":["fr-p213"],"v":"3e576ca4"},{"idioma":"fr","id":"fr-u321","tipo":"frase","requer":"fr-p214","fr":"Donne-moi un coup de fil !","aceitasFr":["Passe-moi un coup de fil !","Donnez-moi un coup de fil !"],"en":"Give me a call!","aceitasEn":["give me a call","call me","give me a ring","give me a buzz","call me up"],"distratoresEn":["Give me a ride!","Give me a chance!","Give me a hint!","Give me an answer!"],"nivel":"A2","tags":["expressão","tecnologia"],"notaEn":"«Un coup de fil», literally a blow of wire, is a phone call. «Coup» lives in set phrases: «un coup de main», a hand; «tout à coup», suddenly.","requerTodas":["fr-p195","fr-p214","fr-p320"],"v":"a046495f"},{"idioma":"fr","id":"fr-u322","tipo":"frase","requer":"fr-p215","fr":"Quel est ton numéro ?","aceitasFr":["C'est quoi ton numéro ?","Quel est votre numéro ?"],"en":"What's your number?","aceitasEn":["whats your number","what is your number","whats your phone number","what is your phone number","can i have your number"],"distratoresEn":["What's your address?","What's your email?","What's your sign?","What's your schedule?"],"nivel":"A1","tags":["social","tecnologia"],"notaEn":"«Le numéro» is a phone, house or room number. «Quel» agrees: «quel numéro», «quelle adresse».","requerTodas":["fr-p001","fr-p215"],"v":"c24f3ee6"},{"idioma":"fr","id":"fr-u323","tipo":"frase","requer":"fr-p216","fr":"Votre passeport, s'il vous plaît.","en":"Your passport, please.","aceitasEn":["your passport please","passport please","may i see your passport please","can i see your passport please","your passport"],"distratoresEn":["Your ticket, please.","Your visa, please.","Your receipt, please.","Your boarding pass, please."],"nivel":"A1","tags":["viagem"],"notaEn":"What you hear at the border and at hotel check-in. «Votre» is the possessive of formal «vous».","requerTodas":["fr-p216"],"v":"701b5b2e"},{"idioma":"fr","id":"fr-u324","tipo":"frase","requer":"fr-p217","fr":"C'est à quel nom ?","aceitasFr":["À quel nom ?","C'est à quel nom, s'il vous plaît ?"],"en":"What name is it under?","aceitasEn":["what name is it under","under what name","what name is the reservation under","whose name is it under","under whose name","what name is the booking under"],"distratoresEn":["What time is it for?","How many people is it for?","Who is it for?","What day is it for?"],"nivel":"A2","tags":["viagem","comida"],"notaEn":"For a hotel or restaurant booking: «c'est à quel nom ?», answered «au nom de Silva». On a form, «nom» is the last name.","requerTodas":["fr-p001","fr-p217"],"v":"9fb1adc2"},{"idioma":"fr","id":"fr-u325","tipo":"frase","requer":"fr-p219","fr":"Tu sais faire du vélo ?","en":"Can you ride a bike?","aceitasEn":["can you ride a bike","do you know how to ride a bike","can you ride a bicycle","do you know how to ride a bicycle"],"distratoresEn":["Can you ride a skateboard?","Can you ride a horse?","Can you ride a motorcycle?","Can you ride a scooter?"],"nivel":"A1","tags":["cidade","cultura"],"notaEn":"Riding a bike is «faire du vélo», like «faire du sport». Knowing how is «savoir», not «pouvoir».","requerTodas":["fr-p008","fr-p004","fr-p219"],"v":"f8b90d06"},{"idioma":"fr","id":"fr-u326","tipo":"frase","requer":"fr-p224","fr":"Ma voiture est neuve.","en":"My car is brand-new.","aceitasEn":["my car is brand new","my car is new","my cars brand new"],"distratoresEn":["My car is used.","My car is imported.","My car is rented.","My car is electric."],"nivel":"A1","tags":["cidade","compras"],"notaEn":"«Neuf» means never used, brand-new; feminine «neuve». «Nouveau» is new in the sense of different, recent: «ma nouvelle voiture» may be secondhand.","requerTodas":["fr-p034","fr-p001","fr-p224"],"v":"81ba459b"},{"idioma":"fr","id":"fr-u327","tipo":"frase","requer":"fr-p224","fr":"Quoi de neuf ?","en":"What's new?","aceitasEn":["whats new","what is new","anything new","whats up"],"distratoresEn":["What's wrong?","What's missing?","What's for dinner?","What's the plan?"],"nivel":"A2","tags":["social","expressão"],"notaEn":"A casual greeting between friends. Here «neuf» is the adjective new, not the number nine.","requerTodas":["fr-p224"],"v":"a1829353"},{"idioma":"fr","id":"fr-u328","tipo":"frase","requer":"fr-p225","fr":"Qu'est-ce qu'il y a à la télé ce soir ?","aceitasFr":["Il y a quoi à la télé ce soir ?"],"en":"What's on TV tonight?","aceitasEn":["whats on tv tonight","what is on tv tonight","whats on television tonight","whats on the tv tonight"],"distratoresEn":["What's on the radio tonight?","What's on at the square tonight?","What's on at the club tonight?","What's on at the church tonight?"],"nivel":"A1","tags":["mídia","casa"],"notaEn":"On TV is «à la télé». «Qu'est-ce qu'il y a ?» means what's there?, and also what's wrong?, depending on the tone.","requerTodas":["fr-p002","fr-p225","fr-p160"],"v":"72752dfb"},{"idioma":"fr","id":"fr-u329","tipo":"frase","requer":"fr-p227","fr":"Notre hôtel est près de la plage.","en":"Our hotel is near the beach.","aceitasEn":["our hotel is near the beach","our hotel is close to the beach","our hotels near the beach","our hotel is by the beach"],"distratoresEn":["Our apartment is near the beach.","Our restaurant is near the beach.","Our hostel is near the beach.","Our campsite is near the beach."],"nivel":"A1","tags":["viagem"],"notaEn":"«Notre» is our with a singular noun; with a plural, «nos». «L'hôtel» is masculine, with a silent «h».","requerTodas":["fr-p227","fr-p001","fr-p246","fr-p087"],"v":"a2c1d1b4"},{"idioma":"fr","id":"fr-u330","tipo":"frase","requer":"fr-p230","fr":"Tu habites ici depuis longtemps ?","en":"Have you lived here long?","aceitasEn":["have you lived here long","have you lived here for a long time","have you been living here long","have you been living here for a long time"],"distratoresEn":["Have you lived here before?","Have you lived here alone?","Have you lived here since May?","Have you lived here a week?"],"nivel":"A1","tags":["casa","social"],"notaEn":"French uses the present with «depuis» for something still going on: «j'habite ici depuis longtemps», where English says «have lived».","requerTodas":["fr-p016","fr-p048","fr-p230"],"v":"e04d8b2b"},{"idioma":"fr","id":"fr-u331","tipo":"frase","requer":"fr-p237","fr":"Quelle taille faites-vous ?","aceitasFr":["Vous faites quelle taille ?","Tu fais quelle taille ?"],"en":"What size do you wear?","aceitasEn":["what size do you wear","what size are you","what is your size","whats your size","what size do you take"],"distratoresEn":["What style do you wear?","What model do you wear?","What fabric do you wear?","What uniform do you wear?"],"nivel":"A1","tags":["roupa","compras"],"notaEn":"In a store, French says you «make» a size: «je fais du 40», I wear a 40. Shoe size is a different word: «la pointure».","requerTodas":["fr-p237","fr-p004"],"v":"60cc5bfd"},{"idioma":"fr","id":"fr-u332","tipo":"frase","requer":"fr-p242","fr":"Vous voulez du thé ou du café ?","aceitasFr":["Tu veux du thé ou du café ?"],"en":"Would you like tea or coffee?","aceitasEn":["would you like tea or coffee","do you want tea or coffee","would you like some tea or coffee","do you want some tea or coffee","tea or coffee"],"distratoresEn":["Would you like juice or coffee?","Would you like milk or coffee?","Would you like water or coffee?","Would you like wine or coffee?"],"nivel":"A1","tags":["comida","social"],"notaEn":"For an unspecified amount of a drink, French uses the partitive: «du thé», «du café», «de l'eau».","requerTodas":["fr-p007","fr-p242","fr-p057"],"v":"1b279d84"},{"idioma":"fr","id":"fr-u333","tipo":"frase","requer":"fr-p250","fr":"C'est la vie !","en":"That's life!","aceitasEn":["thats life","such is life","thats how life is","c est la vie"],"distratoresEn":["That's fate!","That's luck!","That's the rule!","That's the world!"],"nivel":"A1","tags":["expressão","cotidiano"],"notaEn":"Said with a shrug about things you can't change; English borrowed it as is. «La vie» is feminine: «la belle vie», the good life.","requerTodas":["fr-p001","fr-p250"],"v":"0c0a617c"},{"idioma":"fr","id":"fr-u334","tipo":"frase","requer":"fr-p254","fr":"Il faut réserver à l'avance.","en":"You have to book in advance.","aceitasEn":["you have to book in advance","you need to book in advance","you must book in advance","you have to reserve in advance","you need to reserve in advance","you have to book ahead","you need to book ahead"],"distratoresEn":["You have to book online.","You have to book by phone.","You have to book in person.","You have to book at the front desk."],"nivel":"A1","tags":["viagem","comida"],"notaEn":"«À l'avance» means in advance; «en avance» means early. The opposite of «en avance» is «en retard», late.","requerTodas":["fr-p122","fr-p174","fr-p254"],"v":"2c74e048"},{"idioma":"fr","id":"fr-u335","tipo":"frase","requer":"fr-p258","fr":"Payez à la caisse, s'il vous plaît.","en":"Please pay at the checkout.","aceitasEn":["please pay at the checkout","pay at the checkout please","pay at the register please","please pay at the register","please pay at the till","pay at the cash register"],"distratoresEn":["Please pay at the door.","Please pay in the app.","Please pay by card.","Please pay at the end."],"nivel":"A1","tags":["compras"],"notaEn":"«La caisse» is the checkout, the register: «à la caisse». The cashier is «le caissier», «la caissière».","requerTodas":["fr-p170","fr-p258"],"v":"4df375a2"},{"idioma":"fr","id":"fr-u336","tipo":"frase","requer":"fr-p261","fr":"La réunion commence à dix heures.","en":"The meeting starts at ten.","aceitasEn":["the meeting starts at ten","the meeting begins at ten","the meeting starts at ten oclock","the meeting is at ten","the meetings at ten"],"distratoresEn":["The class starts at ten.","The talk starts at ten.","The exam starts at ten.","The appointment starts at ten."],"nivel":"A1","tags":["trabalho"],"notaEn":"French always says «heures» with the time: «à dix heures», at ten. «La réunion» is a meeting, not a reunion.","requerTodas":["fr-p261","fr-p196","fr-p121","fr-p129"],"v":"50f4d939"},{"idioma":"fr","id":"fr-u337","tipo":"frase","requer":"fr-p262","fr":"Tu es marié ?","aceitasFr":["Tu es mariée ?","Vous êtes marié ?","Vous êtes mariée ?","Est-ce que tu es marié ?"],"en":"Are you married?","aceitasEn":["are you married"],"distratoresEn":["Are you single?","Are you divorced?","Are you widowed?","Are you engaged?"],"nivel":"A1","tags":["família","social"],"notaEn":"Feminine «mariée» sounds the same. To get married is «se marier»: «ils se sont mariés en mai».","requerTodas":["fr-p001","fr-p262"],"v":"4a7e1594"},{"idioma":"fr","id":"fr-u338","tipo":"frase","requer":"fr-p266","fr":"L'ascenseur est en panne.","en":"The elevator is out of order.","aceitasEn":["the elevator is out of order","the elevator is broken","the elevator isnt working","the elevator doesnt work","the lift is out of order","the lift is broken","the elevators broken"],"distratoresEn":["The intercom is out of order.","The heater is out of order.","The gate is out of order.","The doorbell is out of order."],"nivel":"A1","tags":["casa","cidade"],"notaEn":"«En panne» is for anything that breaks down: a car, an elevator, a machine. The stairs are «l'escalier».","requerTodas":["fr-p266","fr-p001","fr-p077"],"v":"87346f55"},{"idioma":"fr","id":"fr-u339","tipo":"frase","requer":"fr-p271","fr":"Tu as fait tes devoirs ?","en":"Did you do your homework?","aceitasEn":["did you do your homework","have you done your homework","did you finish your homework","have you finished your homework"],"distratoresEn":["Did you make your bed?","Did you pack your suitcase?","Did you take your test?","Did you make dinner?"],"nivel":"A1","tags":["escola","família"],"notaEn":"Homework is «les devoirs», plural, and you «do» it: «faire ses devoirs». In the singular, «le devoir» is a duty.","requerTodas":["fr-p002","fr-p004","fr-p271"],"v":"bfb183aa"},{"idioma":"fr","id":"fr-u340","tipo":"frase","requer":"fr-p272","fr":"C'est un cadeau pour toi.","en":"It's a present for you.","aceitasEn":["its a present for you","its a gift for you","this is a present for you","this is a gift for you","it is a present for you"],"distratoresEn":["It's a cake for you.","It's a message for you.","It's a note for you.","It's a package for you."],"nivel":"A1","tags":["social","família"],"notaEn":"«Le cadeau», plural «cadeaux», is a gift. «Le présent» is only the present time, not a gift.","requerTodas":["fr-p001","fr-p272"],"v":"3beb9994"},{"idioma":"fr","id":"fr-u341","tipo":"frase","requer":"fr-p253","fr":"Le ticket coûte deux euros.","en":"The ticket costs two euros.","aceitasEn":["the ticket costs two euros","a ticket costs two euros","the ticket is two euros","tickets cost two euros"],"distratoresEn":["The coffee costs two euros.","The newspaper costs two euros.","The bread costs two euros.","The chocolate costs two euros."],"nivel":"A1","tags":["viagem","compras"],"notaEn":"«Le ticket» is a subway, bus or parking ticket. To cost is «coûter»: «ça coûte combien ?», how much is it?","requerTodas":["fr-p253","fr-p321","fr-p120","fr-p128"],"v":"e3ea3b31"},{"idioma":"fr","id":"fr-u342","tipo":"frase","requer":"fr-p263","fr":"Je dois parler à mon chef.","en":"I have to talk to my boss.","aceitasEn":["i have to talk to my boss","i need to talk to my boss","i have to speak to my boss","i must talk to my boss","i need to speak to my boss","i have to speak with my boss","i have to talk with my boss"],"distratoresEn":["I have to talk to my doctor.","I have to talk to my teacher.","I have to talk to my neighbor.","I have to talk to my lawyer."],"nivel":"A1","tags":["trabalho"],"notaEn":"To talk to someone is «parler à»: «parler à mon chef». «Le chef» is any boss, not just a head cook.","requerTodas":["fr-p082","fr-p012","fr-p263"],"v":"1200c7e0"},{"idioma":"fr","id":"fr-u343","tipo":"frase","requer":"fr-p226","fr":"J'ai seulement dix minutes.","aceitasFr":["Je n'ai que dix minutes."],"en":"I only have ten minutes.","aceitasEn":["i only have ten minutes","ive only got ten minutes","i have only ten minutes","i just have ten minutes","i have just ten minutes"],"distratoresEn":["I still have ten minutes.","I have ten more minutes.","I have about ten minutes.","I have almost ten minutes."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Seulement» means only; «ne… que» says the same: «je n'ai que dix minutes». Alone is «seul».","requerTodas":["fr-p002","fr-p226","fr-p121","fr-p139"],"v":"14c89098"},{"idioma":"fr","id":"fr-u344","tipo":"frase","requer":"fr-p222","fr":"Je peux prendre votre manteau ?","en":"May I take your coat?","aceitasEn":["may i take your coat","can i take your coat","could i take your coat"],"distratoresEn":["May I take your umbrella?","May I take your hat?","May I take your scarf?","May I take your plate?"],"nivel":"A1","tags":["roupa","social"],"notaEn":"What a host or a restaurant says. «Le manteau» is a long coat; a jacket is «la veste».","requerTodas":["fr-p006","fr-p011","fr-p222"],"v":"81b06a8c"},{"idioma":"fr","id":"fr-u345","tipo":"frase","requer":"fr-p235","fr":"Un jus de pomme, s'il vous plaît.","en":"An apple juice, please.","aceitasEn":["an apple juice please","apple juice please","one apple juice please","can i have an apple juice please","id like an apple juice please"],"distratoresEn":["An apple tea, please.","An apple cake, please.","An apple candy, please.","An apple yogurt, please."],"nivel":"A1","tags":["comida"],"notaEn":"«Le jus» has a silent «s». The fruit takes «de» with no article: «jus de pomme», «jus d'orange».","requerTodas":["fr-p235","fr-p096"],"v":"f29aebc2"},{"idioma":"fr","id":"fr-u346","tipo":"frase","requer":"fr-p156","fr":"Le petit déjeuner est compris ?","aceitasFr":["Est-ce que le petit déjeuner est compris ?","Le petit déjeuner est inclus ?"],"en":"Is breakfast included?","aceitasEn":["is breakfast included","is the breakfast included","does that include breakfast","is breakfast included in the price"],"distratoresEn":["Is lunch included?","Is dinner included?","Is parking included?","Is Wi-Fi included?"],"nivel":"A1","tags":["viagem","comida"],"notaEn":"«Compris», from «comprendre», also means included: «service compris», service included.","requerTodas":["fr-p156","fr-p001","fr-p322"],"v":"17c6bc2c"},{"idioma":"fr","id":"fr-u347","tipo":"frase","requer":"fr-p133","fr":"J'ai perdu ma clé.","aceitasFr":["J'ai perdu mes clés.","J'ai perdu ma clef."],"en":"I lost my key.","aceitasEn":["i lost my key","ive lost my key","i have lost my key","i lost the key","i lost my keys","ive lost my keys"],"distratoresEn":["I lost my wallet.","I lost my bag.","I lost my password.","I lost my suitcase."],"nivel":"A1","tags":["casa","viagem"],"notaEn":"To lose something is «perdre» (participle «perdu»); to miss a train is «rater». «La clé» is also spelled «la clef».","requerTodas":["fr-p002","fr-p323","fr-p133"],"v":"f970ff47"},{"idioma":"fr","id":"fr-u348","tipo":"frase","requer":"fr-p134","fr":"La douche ne marche pas.","en":"The shower doesn't work.","aceitasEn":["the shower doesnt work","the shower isnt working","the shower is broken","the showers broken","the shower does not work"],"distratoresEn":["The heater doesn't work.","The hair dryer doesn't work.","The minibar doesn't work.","The fan doesn't work."],"nivel":"A1","tags":["casa","viagem"],"notaEn":"«La douche» is the shower: «prendre une douche», to take a shower. For a device, «marcher» means to work.","requerTodas":["fr-p134","fr-p270"],"v":"6b9ade1b"},{"idioma":"fr","id":"fr-u349","tipo":"frase","requer":"fr-p135","fr":"Une table près de la fenêtre, s'il vous plaît.","en":"A table by the window, please.","aceitasEn":["a table by the window please","a table near the window please","a table next to the window please","can we have a table by the window","a window table please","a table by the window"],"distratoresEn":["A table by the door, please.","A table by the kitchen, please.","A table by the entrance, please.","A table by the fireplace, please."],"nivel":"A1","tags":["comida"],"notaEn":"«La fenêtre» is the window. Near is «près de»; «de» + «la» doesn't contract: «près de la fenêtre».","requerTodas":["fr-p143","fr-p246","fr-p135"],"v":"8a202c47"},{"idioma":"fr","id":"fr-u350","tipo":"frase","requer":"fr-p001","fr":"C'était délicieux !","en":"That was delicious!","aceitasEn":["that was delicious","it was delicious","that was really good","it was really good","that was great","it was great"],"distratoresEn":["That was salty!","That was cold!","That was spicy!","That was raw!"],"nivel":"A1","tags":["comida","social"],"notaEn":"«C'était» is the imperfect of «c'est»: the compliment at the end of a meal. Feminine «délicieuse».","requerTodas":["fr-p001","fr-p324"],"v":"93e27918"},{"idioma":"fr","id":"fr-u351","tipo":"frase","requer":"fr-p051","fr":"Je vais prendre le menu à vingt euros.","en":"I'll have the twenty-euro set menu.","aceitasEn":["ill have the twenty euro set menu","ill have the twenty euro menu","ill take the twenty euro set menu","i will have the twenty euro set menu","ill have the 20 euro set menu","ill have the 20 euro menu"],"distratoresEn":["I'll have the fifteen-euro set menu.","I'll have the thirty-euro set menu.","I'll have the twelve-euro set menu.","I'll have the fifty-euro set menu."],"nivel":"A1","tags":["comida"],"notaEn":"«Le menu» is a fixed-price set meal; the menu itself is «la carte». The price takes «à»: «le menu à vingt euros».","requerTodas":["fr-p003","fr-p011","fr-p325","fr-p051","fr-p128"],"v":"6d5a2d17"},{"idioma":"fr","id":"fr-u352","tipo":"frase","requer":"fr-p142","fr":"Vous avez cette robe en rouge ?","aceitasFr":["Est-ce que vous avez cette robe en rouge ?","Vous avez cette robe en rouge, s'il vous plaît ?"],"en":"Do you have this dress in red?","aceitasEn":["do you have this dress in red","have you got this dress in red","does this dress come in red","do you have this dress in red please"],"distratoresEn":["Do you have this coat in red?","Do you have this sweater in red?","Do you have this hat in red?","Do you have this bikini in red?"],"nivel":"A1","tags":["roupa","compras"],"notaEn":"«La robe» is a dress, not a robe (that's «la robe de chambre»). Colors take «en»: «en rouge», in red.","requerTodas":["fr-p002","fr-p142","fr-p173"],"v":"9c61e0b7"},{"idioma":"fr","id":"fr-u353","tipo":"frase","requer":"fr-p063","fr":"Je cherche un cadeau pour ma mère.","en":"I'm looking for a present for my mother.","aceitasEn":["im looking for a present for my mother","im looking for a gift for my mother","im looking for a gift for my mom","im looking for a present for my mom","i am looking for a present for my mother","im looking for a gift for my mum"],"distratoresEn":["I'm looking for a present for my aunt.","I'm looking for a present for my mother-in-law.","I'm looking for a present for my godmother.","I'm looking for a present for my grandmother."],"nivel":"A1","tags":["compras","família"],"notaEn":"«Chercher», to look for, takes no preposition: «je cherche un cadeau». Mom is «maman».","requerTodas":["fr-p118","fr-p272","fr-p063"],"v":"2c3b911b"},{"idioma":"fr","id":"fr-u354","tipo":"frase","requer":"fr-p094","fr":"Je tousse depuis trois jours.","en":"I've been coughing for three days.","aceitasEn":["ive been coughing for three days","i have been coughing for three days","ive had a cough for three days","i have had a cough for three days"],"distratoresEn":["I've been coughing for two days.","I've been coughing for four days.","I've been coughing for five days.","I've been coughing for ten days."],"nivel":"A1","tags":["saúde"],"notaEn":"Something still going on takes the present with «depuis»: «je tousse depuis trois jours». A cough is «la toux».","requerTodas":["fr-p326","fr-p094","fr-p019"],"v":"c284edbe"},{"idioma":"fr","id":"fr-u355","tipo":"frase","requer":"fr-p069","fr":"Où est l'hôpital le plus proche ?","en":"Where's the nearest hospital?","aceitasEn":["wheres the nearest hospital","where is the nearest hospital","where is the closest hospital","wheres the closest hospital"],"distratoresEn":["Where's the nearest bank?","Where's the nearest hotel?","Where's the nearest market?","Where's the nearest post office?"],"nivel":"A1","tags":["saúde","cidade"],"notaEn":"The superlative repeats the article: «l'hôpital le plus proche», the nearest hospital. «Proche» is near; «prochain», next.","requerTodas":["fr-p001","fr-p069","fr-p327"],"v":"c6be0cee"},{"idioma":"fr","id":"fr-u356","tipo":"frase","requer":"fr-p180","fr":"Tu peux me rappeler plus tard ?","aceitasFr":["Vous pouvez me rappeler plus tard ?"],"en":"Can you call me back later?","aceitasEn":["can you call me back later","could you call me back later","can you call me later","will you call me back later","call me back later"],"distratoresEn":["Can you call me back earlier?","Can you call me back tomorrow?","Can you call me back now?","Can you call me back tonight?"],"nivel":"A1","tags":["tecnologia","social"],"notaEn":"«Rappeler» is to call back, and also to remind: «rappelle-moi», remind me. Later is «plus tard».","requerTodas":["fr-p006","fr-p328","fr-p180"],"v":"abf8c87c"},{"idioma":"fr","id":"fr-u357","tipo":"frase","requer":"fr-p158","fr":"C'est à dix minutes à pied.","en":"It's a ten-minute walk.","aceitasEn":["its a ten minute walk","its ten minutes on foot","its ten minutes walking","its ten minutes walk","it is a ten minute walk","its a ten minute walk from here"],"distratoresEn":["It's a ten-minute drive.","It's ten minutes by bus.","It's ten minutes by bike.","It's a ten-minute subway ride."],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"Distance takes «à»: «à dix minutes», ten minutes away. On foot is «à pied»; by car, «en voiture».","requerTodas":["fr-p001","fr-p121","fr-p139","fr-p158"],"v":"1834679c"},{"idioma":"fr","id":"fr-u358","tipo":"frase","requer":"fr-p131","fr":"Vous pouvez me montrer sur la carte ?","aceitasFr":["Tu peux me montrer sur la carte ?","Vous pouvez me le montrer sur la carte ?"],"en":"Can you show me on the map?","aceitasEn":["can you show me on the map","could you show me on the map","can you show me on the map please","could you show me on the map please"],"distratoresEn":["Can you show me on your phone?","Can you show me on paper?","Can you show me in the guidebook?","Can you show me on the sign?"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"On the map is «sur la carte». To show is «montrer»; a wristwatch is «la montre».","requerTodas":["fr-p006","fr-p329","fr-p131"],"v":"b159b244"},{"idioma":"fr","id":"fr-u359","tipo":"frase","requer":"fr-p178","fr":"Il est sept heures et demie.","en":"It's seven thirty.","aceitasEn":["its seven thirty","its half past seven","it is seven thirty","it is half past seven","its seven thirty now"],"distratoresEn":["It's six thirty.","It's eight thirty.","It's nine thirty.","It's five thirty."],"nivel":"A1","tags":["cotidiano"],"notaEn":"Time is always «il est … heures». Half past is «et demie», feminine because «l'heure» is.","requerTodas":["fr-p001","fr-p178","fr-p129","fr-p330"],"v":"be9d53e8"},{"idioma":"fr","id":"fr-u360","tipo":"frase","requer":"fr-p126","fr":"J'arrive vers huit heures.","en":"I'll get there around eight.","aceitasEn":["ill get there around eight","ill be there around eight","ill arrive around eight","ill be there at about eight","ill get there at around eight","i arrive around eight","ill be there around eight oclock"],"distratoresEn":["I'll get there around seven.","I'll get there around nine.","I'll get there around six.","I'll get there around ten."],"nivel":"A1","tags":["cotidiano","viagem"],"notaEn":"«Vers» means around: «vers huit heures». At an exact time it's «à»: «à huit heures». The present «j'arrive» covers the near future.","requerTodas":["fr-p115","fr-p126","fr-p129"],"v":"b483ade1"},{"idioma":"fr","id":"fr-u361","tipo":"frase","requer":"fr-p159","fr":"On se voit samedi ?","en":"See you on Saturday?","aceitasEn":["see you on saturday","see you saturday","shall we meet on saturday","will i see you on saturday","are we meeting on saturday"],"distratoresEn":["See you on Sunday?","See you on the holiday?","See you on the weekend?","See you at dinner?"],"nivel":"A1","tags":["social","cotidiano"],"notaEn":"Without the article, «samedi» is this coming Saturday; «le samedi» means every Saturday. «On se voit», we'll see each other.","requerTodas":["fr-p010","fr-p159"],"v":"228b41ec"},{"idioma":"fr","id":"fr-u362","tipo":"frase","requer":"fr-p171","fr":"Il pleut depuis ce matin.","en":"It's been raining since this morning.","aceitasEn":["its been raining since this morning","it has been raining since this morning","its been raining since the morning","it has been raining since the morning"],"distratoresEn":["It's been snowing since this morning.","It's been thundering since this morning.","It's been windy since this morning.","It's been getting colder since this morning."],"nivel":"A1","tags":["natureza","cotidiano"],"notaEn":"Something still going on takes the present with «depuis»: «il pleut depuis ce matin», where English says «has been raining».","requerTodas":["fr-p171","fr-p153"],"v":"5cf30fa1"},{"idioma":"fr","id":"fr-u363","tipo":"frase","requer":"fr-p091","fr":"Quelle est la bonne réponse ?","en":"What's the right answer?","aceitasEn":["whats the right answer","what is the right answer","whats the correct answer","what is the correct answer","which is the right answer"],"distratoresEn":["What's the right question?","What's the right word?","What's the right date?","What's the right time?"],"nivel":"A1","tags":["escola"],"notaEn":"«Bon» also means right, correct: «la bonne réponse», «le bon chemin», the right way.","requerTodas":["fr-p001","fr-p036","fr-p091"],"v":"dcf3cff4"},{"idioma":"fr","id":"fr-u364","tipo":"frase","requer":"fr-p098","fr":"Ce restaurant est toujours plein.","en":"This restaurant is always full.","aceitasEn":["this restaurant is always full","this restaurant is always packed","that restaurant is always full","this restaurant is always busy","this restaurant is always crowded","that restaurant is always packed"],"distratoresEn":["This bar is always full.","This hotel is always full.","This café is always full.","This movie theater is always full."],"nivel":"A1","tags":["comida","cidade"],"notaEn":"«Plein» means full; the opposite is «vide». «Toujours» goes right after the verb: «il est toujours plein».","requerTodas":["fr-p098","fr-p001","fr-p046","fr-p331"],"v":"f9a36655"},{"idioma":"fr","id":"fr-u365","tipo":"frase","requer":"fr-p132","fr":"Quelle chance !","en":"What luck!","aceitasEn":["what luck","how lucky","lucky you","youre so lucky","so lucky"],"distratoresEn":["What a shame!","What a scare!","Bad luck!","What a relief!"],"nivel":"A1","tags":["social","expressão"],"notaEn":"«La chance» means luck, not a chance (that's «l'occasion»). «Quel», «quelle» also means what a! in exclamations.","requerTodas":["fr-p132"],"v":"0b65f15b"},{"idioma":"fr","id":"fr-u366","tipo":"frase","requer":"fr-p042","fr":"Je suis très content pour toi.","aceitasFr":["Je suis très contente pour toi.","Je suis très content pour vous."],"en":"I'm very happy for you.","aceitasEn":["im very happy for you","im really happy for you","im so happy for you","i am very happy for you","im very glad for you","im really glad for you"],"distratoresEn":["I'm very sad for you.","I'm very worried about you.","I'm very proud of you.","I'm very angry with you."],"nivel":"A1","tags":["social"],"notaEn":"Happy for someone is «content pour»; happy to do something, «content de»: «content de te voir».","requerTodas":["fr-p001","fr-p043","fr-p042"],"v":"572fb454"},{"idioma":"fr","id":"fr-u367","tipo":"frase","requer":"fr-p102","fr":"Ça me fait peur.","en":"That scares me.","aceitasEn":["that scares me","that frightens me","it scares me","that makes me scared","this scares me","it frightens me"],"distratoresEn":["That makes me sleepy.","That disgusts me.","That makes me hungry.","That makes me cold."],"nivel":"A1","tags":["cotidiano"],"notaEn":"To scare is «faire peur», with no article: «ça me fait peur». To be afraid is «avoir peur».","requerTodas":["fr-p004","fr-p102"],"v":"5bd41896"},{"idioma":"fr","id":"fr-u368","tipo":"frase","requer":"fr-p136","fr":"Ma grand-mère habite à la campagne.","en":"My grandmother lives in the country.","aceitasEn":["my grandmother lives in the country","my grandma lives in the country","my grandmother lives in the countryside","my grandma lives in the countryside"],"distratoresEn":["My aunt lives in the country.","My godmother lives in the country.","My mother-in-law lives in the country.","My neighbor lives in the country."],"nivel":"A1","tags":["família","natureza"],"notaEn":"«La campagne» is the countryside. Grandma is «mamie»; grandpa, «papi».","requerTodas":["fr-p136","fr-p016","fr-p332"],"v":"2d4932ba"},{"idioma":"fr","id":"fr-u369","tipo":"frase","requer":"fr-p072","fr":"Mon voisin est très sympa.","en":"My neighbor is really nice.","aceitasEn":["my neighbor is really nice","my neighbor is very nice","my neighbour is very nice","my neighbor is really friendly","my neighbors really nice","my neighbour is really nice"],"distratoresEn":["My coworker is really nice.","My boss is really nice.","My teacher is really nice.","My brother-in-law is really nice."],"nivel":"A1","tags":["casa","social"],"notaEn":"«Sympa», short for «sympathique», means nice, friendly — not sympathetic. It doesn't change in the feminine.","requerTodas":["fr-p072","fr-p001","fr-p043","fr-p333"],"v":"f15e234c"},{"idioma":"fr","id":"fr-u370","tipo":"frase","requer":"fr-p149","fr":"Je regarde le foot à la télé.","en":"I watch soccer on TV.","aceitasEn":["i watch soccer on tv","im watching soccer on tv","i watch football on tv","im watching football on tv","i watch soccer on television"],"distratoresEn":["I watch tennis on TV.","I watch volleyball on TV.","I watch basketball on TV.","I watch cycling on TV."],"nivel":"A1","tags":["cultura","mídia"],"notaEn":"«Le foot» is soccer, short for «le football». To watch is «regarder», with no preposition.","requerTodas":["fr-p172","fr-p149","fr-p225"],"v":"bf2f013b"},{"idioma":"fr","id":"fr-u371","tipo":"frase","requer":"fr-p182","fr":"Je vends mon vélo.","en":"I'm selling my bike.","aceitasEn":["im selling my bike","im selling my bicycle","i am selling my bike","i sell my bike"],"distratoresEn":["I'm fixing my bike.","I'm painting my bike.","I'm washing my bike.","I'm lending my bike."],"nivel":"A1","tags":["compras","cidade"],"notaEn":"«Vendre»: je vends, il vend, nous vendons, ils vendent. «Le vélo» is masculine: «mon vélo».","requerTodas":["fr-p182","fr-p219"],"v":"c3d5d7cb"},{"idioma":"fr","id":"fr-u372","tipo":"frase","requer":"fr-p104","fr":"C'est l'anniversaire de ma sœur.","en":"It's my sister's birthday.","aceitasEn":["its my sisters birthday","it is my sisters birthday","today is my sisters birthday","its my sisters birthday today"],"distratoresEn":["It's my cousin's birthday.","It's my aunt's birthday.","It's my grandmother's birthday.","It's my sister-in-law's birthday."],"nivel":"A1","tags":["família","social"],"notaEn":"«L'anniversaire» is a birthday: «joyeux anniversaire !», happy birthday! It also covers anniversaries.","requerTodas":["fr-p001","fr-p334","fr-p104"],"v":"50b2992c"},{"idioma":"fr","id":"fr-u373","tipo":"frase","requer":"fr-p079","fr":"Je cherche un appartement à louer.","en":"I'm looking for an apartment to rent.","aceitasEn":["im looking for an apartment to rent","im looking for a flat to rent","i am looking for an apartment to rent","im looking for an apartment for rent"],"distratoresEn":["I'm looking for a room to rent.","I'm looking for a car to rent.","I'm looking for an office to rent.","I'm looking for a studio to rent."],"nivel":"A1","tags":["casa"],"notaEn":"To rent is «louer». Signs say «à louer», for rent: «appartement à louer».","requerTodas":["fr-p118","fr-p079","fr-p335"],"v":"c9661087"},{"idioma":"fr","id":"fr-u374","tipo":"frase","requer":"fr-p057","fr":"On prend un café ?","en":"Shall we get a coffee?","aceitasEn":["shall we get a coffee","should we get a coffee","lets get a coffee","how about a coffee","shall we have a coffee","want to grab a coffee","lets grab a coffee"],"distratoresEn":["Shall we get a tea?","Shall we get a juice?","Shall we get an ice cream?","Shall we get a beer?"],"nivel":"A1","tags":["comida","social"],"notaEn":"To have a drink is «prendre»: «prendre un café». In France, «un café» is a small espresso.","requerTodas":["fr-p011","fr-p057"],"v":"f32669d1"},{"idioma":"fr","id":"fr-u375","tipo":"frase","requer":"fr-p030","fr":"Je voudrais une chambre pour deux nuits.","en":"I'd like a room for two nights.","aceitasEn":["id like a room for two nights","i would like a room for two nights","id like a room for 2 nights"],"distratoresEn":["I'd like a room for two weeks.","I'd like a room for two people.","I'd like a room with two beds.","I'd like a room for two hours."],"nivel":"A1","tags":["viagem"],"notaEn":"«Je voudrais», the conditional of «vouloir», is the polite way to ask. A hotel room is «la chambre».","requerTodas":["fr-p007","fr-p107","fr-p120","fr-p030"],"v":"ecc4df44"},{"idioma":"fr","id":"fr-u376","tipo":"frase","requer":"fr-p151","fr":"J'ai mal à la gorge.","en":"I have a sore throat.","aceitasEn":["i have a sore throat","my throat hurts","ive got a sore throat","my throat is sore"],"distratoresEn":["I have a toothache.","I have an earache.","I have a stomachache.","I have a sore knee."],"nivel":"A1","tags":["saúde","corpo"],"notaEn":"Pain takes «avoir mal à»: «j'ai mal à la gorge», I have a sore throat; «j'ai mal au ventre», I have a stomachache.","requerTodas":["fr-p002","fr-p151","fr-p336"],"v":"5738dfcf"},{"idioma":"fr","id":"fr-u377","tipo":"frase","requer":"fr-p011","fr":"Je voudrais prendre rendez-vous.","en":"I'd like to make an appointment.","aceitasEn":["id like to make an appointment","i would like to make an appointment","id like to book an appointment","i would like to book an appointment"],"distratoresEn":["I'd like to cancel an appointment.","I'd like to change an appointment.","I'd like to confirm an appointment.","I'd like to postpone an appointment."],"nivel":"A1","tags":["saúde","trabalho"],"notaEn":"To make an appointment is «prendre rendez-vous», with no article. «Un rendez-vous» is also a date with someone.","requerTodas":["fr-p007","fr-p011","fr-p337"],"v":"e3a680b4"},{"idioma":"fr","id":"fr-u378","tipo":"frase","requer":"fr-p055","fr":"Je te dis la vérité.","en":"I'm telling you the truth.","aceitasEn":["im telling you the truth","i am telling you the truth","im telling the truth","i tell you the truth"],"distratoresEn":["I'm telling you the answer.","I'm telling you the password.","I'm telling you the recipe.","I'm telling you the date."],"nivel":"A1","tags":["social"],"notaEn":"To tell the truth is «dire la vérité»; to lie is «mentir». Words in «-té» are feminine.","requerTodas":["fr-p005","fr-p055"],"v":"36601050"},{"idioma":"fr","id":"fr-v082","tipo":"frase","fr":"J'ai fermé la fenêtre.","en":"I closed the window.","aceitasEn":["i closed the window","ive closed the window","i shut the window","i have closed the window","ive shut the window"],"distratoresEn":["I close the window.","I'll close the window.","I would close the window.","I had closed the window."],"formasFr":{"Je ferme la fenêtre":"present","Je fermerai la fenêtre":"future","Je fermerais la fenêtre":"conditional","J'avais fermé la fenêtre":"pluperfect"},"nivel":"A1","tags":["conjugação","pretérito","regular","casa"],"notaEn":"A regular «-er» verb: the participle ends in «-é», «fermé». The passé composé takes «avoir».","requerTodas":["fr-p002","fr-p206","fr-p135"],"v":"3976aaf8"},{"idioma":"fr","id":"fr-v083","tipo":"frase","fr":"Il gagnait bien sa vie.","en":"He used to make a good living.","aceitasEn":["he used to make a good living","he used to earn a good living","he was making a good living","he was earning good money","he used to earn good money"],"distratoresEn":["He makes a good living.","He has made a good living.","He'll make a good living.","He had made a good living."],"formasFr":{"Il gagne bien sa vie":"present","Il a bien gagné sa vie":"passé composé","Il gagnera bien sa vie":"future","Il gagnerait bien sa vie":"conditional"},"nivel":"A1","tags":["conjugação","imperfeito","regular","trabalho"],"notaEn":"«Gagner sa vie» is to earn a living. The imperfect describes the past as it used to be: «il gagnait».","requerTodas":["fr-p210","fr-p044","fr-p250"],"v":"74019f94"},{"idioma":"fr","id":"fr-v084","tipo":"frase","fr":"Je t'appellerai.","en":"I'll call you.","aceitasEn":["ill call you","i will call you","im going to call you","ill give you a call","ill phone you"],"distratoresEn":["I was calling you.","I called you.","I would call you.","I had called you."],"formasFr":{"Je t'appelais":"imperfect","Je t'ai appelé":"passé composé","Je t'appellerais":"conditional","Je t'avais appelé":"pluperfect"},"nivel":"A1","tags":["conjugação","futuro","regular","social"],"notaEn":"«Appeler» doubles the «l» throughout the future: j'appellerai, tu appelleras, nous appellerons. The infinitive and «nous appelons» keep one «l».","requerTodas":["fr-p229"],"v":"7476bb95"},{"idioma":"fr","id":"fr-v085","tipo":"frase","fr":"L'enfant est tombé.","en":"The child fell.","aceitasEn":["the child fell","the child fell down","the kid fell","the kid fell down","the child has fallen"],"distratoresEn":["The child falls.","The child will fall.","The child would fall.","The child had fallen."],"formasFr":{"L'enfant tombe":"present","L'enfant tombera":"future","L'enfant tomberait":"conditional","L'enfant était tombé":"pluperfect"},"nivel":"A1","tags":["conjugação","pretérito","regular","família"],"notaEn":"«Tomber» takes «être» in the passé composé, like verbs of motion: «il est tombé», «elle est tombée».","requerTodas":["fr-p023","fr-p001","fr-p228"],"v":"f8004555"},{"idioma":"fr","id":"fr-v086","tipo":"frase","fr":"Il portait un manteau rouge.","en":"He was wearing a red coat.","aceitasEn":["he was wearing a red coat","he had a red coat on","he had on a red coat"],"distratoresEn":["He's wearing a red coat.","He has worn a red coat.","He'll wear a red coat.","He had worn a red coat."],"formasFr":{"Il porte un manteau rouge":"present","Il a porté un manteau rouge":"passé composé","Il portera un manteau rouge":"future","Il porterait un manteau rouge":"conditional"},"nivel":"A1","tags":["conjugação","imperfeito","regular","roupa"],"notaEn":"The imperfect describes the scene: what someone was wearing, what the weather was like. The passé composé tells what happened.","requerTodas":["fr-p232","fr-p222","fr-p173"],"v":"10cc0da1"},{"idioma":"fr","id":"fr-v087","tipo":"frase","fr":"Je resterai ici.","en":"I'll stay here.","aceitasEn":["ill stay here","i will stay here","im going to stay here"],"distratoresEn":["I was staying here.","I stayed here.","I would stay here.","I had stayed here."],"formasFr":{"Je restais ici":"imperfect","Je suis resté ici":"passé composé","Je resterais ici":"conditional","J'étais resté ici":"pluperfect"},"nivel":"A1","tags":["conjugação","futuro","regular","casa"],"notaEn":"In the future of «-er» verbs, the ending is added to the infinitive: rester + ai = «je resterai». The conditional just adds an «s»: «je resterais».","requerTodas":["fr-p269","fr-p048"],"v":"63a53236"},{"idioma":"fr","id":"fr-v088","tipo":"frase","fr":"Je marchais beaucoup.","en":"I used to walk a lot.","aceitasEn":["i used to walk a lot","i was walking a lot"],"distratoresEn":["I walk a lot.","I've walked a lot.","I'll walk a lot.","I had walked a lot."],"formasFr":{"Je marche beaucoup":"present","J'ai beaucoup marché":"passé composé","Je marcherai beaucoup":"future","Je marcherais beaucoup":"conditional"},"nivel":"A1","tags":["conjugação","imperfeito","regular","saúde"],"notaEn":"The imperfect tells a habit: «je marchais beaucoup», I used to walk a lot. In the passé composé, «beaucoup» sits between auxiliary and participle: «j'ai beaucoup marché».","requerTodas":["fr-p270","fr-p067"],"v":"18836b6e"},{"idioma":"fr","id":"fr-v089","tipo":"frase","fr":"Je me suis senti seul.","aceitasFr":["Je me suis sentie seule."],"en":"I felt lonely.","aceitasEn":["i felt lonely","i felt alone","ive felt lonely","i have felt lonely"],"distratoresEn":["I feel lonely.","I'll feel lonely.","I'd feel lonely.","I had felt lonely."],"formasFr":{"Je me sens seul":"present","Je me sentirai seul":"future","Je me sentirais seul":"conditional","Je m'étais senti seul":"pluperfect"},"nivel":"A1","tags":["conjugação","pretérito","irregular","pronomes","saúde"],"notaEn":"Being reflexive, «se sentir» takes «être», and the participle agrees: «elle s'est sentie seule». Present: je me sens, il se sent, nous nous sentons.","requerTodas":["fr-p001","fr-p248","fr-p306"],"v":"412f5519"},{"idioma":"fr","id":"fr-v090","tipo":"frase","fr":"Il m'a présenté sa famille.","en":"He introduced me to his family.","aceitasEn":["he introduced me to his family","he introduced his family to me","hes introduced me to his family","he has introduced me to his family"],"distratoresEn":["He introduces me to his family.","He'll introduce me to his family.","He would introduce me to his family.","He had introduced me to his family."],"formasFr":{"Il me présente sa famille":"present","Il me présentera sa famille":"future","Il me présenterait sa famille":"conditional","Il m'avait présenté sa famille":"pluperfect"},"nivel":"A1","tags":["conjugação","pretérito","regular","família","social"],"notaEn":"The object pronoun goes before the auxiliary: «il m'a présenté». «Sa famille» can mean his or her family.","requerTodas":["fr-p002","fr-p249","fr-p105"],"v":"4718f7ac"},{"idioma":"fr","id":"fr-v091","tipo":"frase","fr":"Ils ont vécu à Paris.","en":"They lived in Paris.","aceitasEn":["they lived in paris","theyve lived in paris","they have lived in paris"],"distratoresEn":["They live in Paris.","They'll live in Paris.","They would live in Paris.","They had lived in Paris."],"formasFr":{"Ils vivent à Paris":"present","Ils vivront à Paris":"future","Ils vivraient à Paris":"conditional","Ils avaient vécu à Paris":"pluperfect"},"nivel":"A1","tags":["conjugação","pretérito","irregular","cidade"],"notaEn":"«Vivre» has an irregular participle: «vécu». The future drops the «e»: «ils vivront».","requerTodas":["fr-p002","fr-p293"],"v":"5d7883c5"},{"idioma":"fr","id":"fr-v092","tipo":"frase","fr":"Ils apprennent le français.","en":"They're learning French.","aceitasEn":["theyre learning french","they are learning french","they learn french"],"distratoresEn":["They were learning French.","They learned French.","They'll learn French.","They would learn French."],"formasFr":{"Ils apprenaient le français":"imperfect","Ils ont appris le français":"passé composé","Ils apprendront le français":"future","Ils apprendraient le français":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","escola"],"notaEn":"In the «ils» form, «apprendre» doubles the «n»: «ils apprennent». The others: j'apprends, nous apprenons, vous apprenez.","requerTodas":["fr-p290","fr-p054"],"v":"653546a8"},{"idioma":"fr","id":"fr-v093","tipo":"frase","fr":"Je courrai avec toi.","en":"I'll run with you.","aceitasEn":["ill run with you","i will run with you","im going to run with you"],"distratoresEn":["I used to run with you.","I ran with you.","I would run with you.","I had run with you."],"formasFr":{"Je courais avec toi":"imperfect","J'ai couru avec toi":"passé composé","Je courrais avec toi":"conditional","J'avais couru avec toi":"pluperfect"},"nivel":"A1","tags":["conjugação","futuro","irregular","saúde"],"notaEn":"The future of «courir» has a double «r»: «je courrai». The imperfect has one: «je courais». The conditional has both: «je courrais».","requerTodas":["fr-p291"],"v":"4ed401aa"},{"idioma":"fr","id":"fr-v094","tipo":"frase","fr":"On écoutait de la musique.","aceitasFr":["Nous écoutions de la musique."],"en":"We were listening to music.","aceitasEn":["we were listening to music","we used to listen to music"],"distratoresEn":["We listen to music.","We've listened to music.","We'll listen to music.","We had listened to music."],"formasFr":{"On écoute de la musique":"present","On a écouté de la musique":"passé composé","On écoutera de la musique":"future","On écouterait de la musique":"conditional"},"nivel":"A1","tags":["conjugação","imperfeito","regular","cultura"],"notaEn":"With «on», the verb is third-person singular: «on écoutait». The imperfect shows what was going on.","requerTodas":["fr-p292","fr-p305"],"v":"d16abd2b"},{"idioma":"fr","id":"fr-v095","tipo":"frase","fr":"Elle chantera à l'église.","en":"She'll sing at church.","aceitasEn":["shell sing at church","she will sing at church","shes going to sing at church","she will sing in the church","shell sing in church","shell sing at the church"],"distratoresEn":["She used to sing at church.","She sang at church.","She would sing at church.","She had sung at church."],"formasFr":{"Elle chantait à l'église":"imperfect","Elle a chanté à l'église":"passé composé","Elle chanterait à l'église":"conditional","Elle avait chanté à l'église":"pluperfect"},"nivel":"A1","tags":["conjugação","futuro","regular","cultura"],"notaEn":"The future adds the endings of «avoir» to the infinitive: chanter + a = «elle chantera». «Chantera» and «chanterait» differ only at the end.","requerTodas":["fr-p289","fr-p288"],"v":"5b370333"},{"idioma":"fr","id":"fr-v096","tipo":"frase","fr":"Mon père fumait beaucoup.","en":"My father used to smoke a lot.","aceitasEn":["my father used to smoke a lot","my dad used to smoke a lot","my father was a heavy smoker","my dad was a heavy smoker"],"distratoresEn":["My father smokes a lot.","My father has smoked a lot.","My father will smoke a lot.","My father had smoked a lot."],"formasFr":{"Mon père fume beaucoup":"present","Mon père a beaucoup fumé":"passé composé","Mon père fumera beaucoup":"future","Mon père fumerait beaucoup":"conditional"},"nivel":"A1","tags":["conjugação","imperfeito","regular","família","saúde"],"notaEn":"The imperfect is a past habit, English «used to». The endings -ais, -ait, -aient all sound the same.","requerTodas":["fr-p103","fr-p221","fr-p067"],"v":"a37da937"},{"idioma":"fr","id":"fr-v097","tipo":"frase","fr":"Le train était parti.","aceitasFr":["Le train était déjà parti."],"en":"The train had left.","aceitasEn":["the train had left","the train had already left","the train had gone"],"distratoresEn":["The train leaves.","The train was leaving.","The train left.","The train will leave."],"formasFr":{"Le train part":"present","Le train partait":"imperfect","Le train est parti":"passé composé","Le train partira":"future"},"nivel":"A1","tags":["conjugação","mais-que-perfeito","irregular","viagem"],"notaEn":"The pluperfect is the imperfect of the auxiliary plus the participle: «il était parti», it had left. Verbs that take «être» keep it here.","requerTodas":["fr-p089","fr-p001","fr-p083"],"v":"5abdab66"},{"idioma":"fr","id":"fr-v098","tipo":"frase","fr":"J'avais oublié mon passeport.","en":"I had forgotten my passport.","aceitasEn":["i had forgotten my passport","id forgotten my passport","i had forgotten the passport"],"distratoresEn":["I forget my passport.","I was forgetting my passport.","I forgot my passport.","I'll forget my passport."],"formasFr":{"J'oublie mon passeport":"present","J'oubliais mon passeport":"imperfect","J'ai oublié mon passeport":"passé composé","J'oublierai mon passeport":"future"},"nivel":"A1","tags":["conjugação","mais-que-perfeito","regular","viagem"],"notaEn":"With «avoir»: j'avais, tu avais, il avait + participle. It's the past before another past, just like English «had forgotten».","requerTodas":["fr-p002","fr-p197","fr-p216"],"v":"74744003"},{"idioma":"fr","id":"fr-v099","tipo":"frase","fr":"Elle n'avait jamais vu la mer.","en":"She had never seen the sea.","aceitasEn":["she had never seen the sea","she had never seen the ocean","shed never seen the sea","shed never seen the ocean"],"distratoresEn":["She never sees the sea.","She never used to see the sea.","She has never seen the sea.","She'll never see the sea."],"formasFr":{"Elle ne voit jamais la mer":"present","Elle ne voyait jamais la mer":"imperfect","Elle n'a jamais vu la mer":"passé composé","Elle ne verra jamais la mer":"future"},"nivel":"A1","tags":["conjugação","mais-que-perfeito","irregular","natureza"],"notaEn":"In compound tenses, «ne… jamais» wraps the auxiliary: «elle n'avait jamais vu». The participle of «voir» is «vu».","requerTodas":["fr-p002","fr-p010","fr-p092"],"v":"96c164ba"},{"idioma":"fr","id":"fr-v100","tipo":"frase","fr":"Il avait trop mangé.","en":"He had eaten too much.","aceitasEn":["he had eaten too much","hed eaten too much","he had overeaten"],"distratoresEn":["He eats too much.","He used to eat too much.","He ate too much.","He'll eat too much."],"formasFr":{"Il mange trop":"present","Il mangeait trop":"imperfect","Il a trop mangé":"passé composé","Il mangera trop":"future"},"nivel":"A1","tags":["conjugação","mais-que-perfeito","regular","comida"],"notaEn":"«Trop» goes between the auxiliary and the participle: «il avait trop mangé». «Mangé» sounds just like «manger».","requerTodas":["fr-p002","fr-p061","fr-p013"],"v":"242eacd5"},{"idioma":"fr","id":"fr-v101","tipo":"frase","fr":"Ils s'étaient levés tôt.","en":"They had gotten up early.","aceitasEn":["they had gotten up early","they had got up early","theyd gotten up early","theyd got up early"],"distratoresEn":["They get up early.","They used to get up early.","They got up early.","They'll get up early."],"formasFr":{"Ils se lèvent tôt":"present","Ils se levaient tôt":"imperfect","Ils se sont levés tôt":"passé composé","Ils se lèveront tôt":"future"},"nivel":"A1","tags":["conjugação","mais-que-perfeito","regular","pronomes","casa"],"notaEn":"Reflexive verbs take «être» in the pluperfect too, and the participle agrees: «ils s'étaient levés», «elles s'étaient levées».","requerTodas":["fr-p001","fr-p177","fr-p181"],"v":"3a42e48a"},{"idioma":"fr","id":"fr-v102","tipo":"frase","fr":"J'avais fini mon travail.","en":"I had finished my work.","aceitasEn":["i had finished my work","id finished my work","i had already finished my work","i had finished work"],"distratoresEn":["I finish my work.","I was finishing my work.","I finished my work.","I'll finish my work."],"formasFr":{"Je finis mon travail":"present","Je finissais mon travail":"imperfect","J'ai fini mon travail":"passé composé","Je finirai mon travail":"future"},"nivel":"A1","tags":["conjugação","mais-que-perfeito","regular","trabalho"],"notaEn":"«-ir» verbs like «finir» have participles in «-i»: «fini». The imperfect adds «-iss-»: «je finissais».","requerTodas":["fr-p002","fr-p123","fr-p029"],"v":"f9198623"},{"idioma":"fr","id":"fr-v103","tipo":"frase","fr":"J'achèterai du pain.","en":"I'll buy some bread.","aceitasEn":["ill buy some bread","i will buy some bread","ill buy bread","im going to buy some bread","im going to buy bread","ill get some bread"],"distratoresEn":["I used to buy bread.","I bought some bread.","I would buy some bread.","I had bought some bread."],"formasFr":{"J'achetais du pain":"imperfect","J'ai acheté du pain":"passé composé","J'achèterais du pain":"conditional","J'avais acheté du pain":"pluperfect"},"nivel":"A1","tags":["conjugação","futuro","irregular","compras"],"notaEn":"«Acheter» takes a grave accent when the next syllable is silent: «j'achète», «j'achèterai». The imperfect has none: «j'achetais».","requerTodas":["fr-p075","fr-p027"],"v":"68b9d092"},{"idioma":"fr","id":"fr-v104","tipo":"frase","fr":"Qui a cassé le verre ?","en":"Who broke the glass?","aceitasEn":["who broke the glass","whos broken the glass","who has broken the glass"],"distratoresEn":["Who breaks the glass?","Who will break the glass?","Who would break the glass?","Who had broken the glass?"],"formasFr":{"Qui casse le verre":"present","Qui cassera le verre":"future","Qui casserait le verre":"conditional","Qui avait cassé le verre":"pluperfect"},"nivel":"A1","tags":["conjugação","pretérito","regular","casa"],"notaEn":"With «qui» as subject, the verb is third-person singular: «qui a cassé». «Le verre» is a glass and also glass, the material.","requerTodas":["fr-p002","fr-p117","fr-p066"],"v":"184e426d"},{"idioma":"fr","id":"fr-v105","tipo":"frase","fr":"Ils sortaient tous les soirs.","en":"They used to go out every night.","aceitasEn":["they used to go out every night","they used to go out every evening"],"distratoresEn":["They go out every night.","They've gone out every night.","They'll go out every night.","They had gone out every night."],"formasFr":{"Ils sortent tous les soirs":"present","Ils sont sortis tous les soirs":"passé composé","Ils sortiront tous les soirs":"future","Ils sortiraient tous les soirs":"conditional"},"nivel":"A1","tags":["conjugação","imperfeito","irregular","social"],"notaEn":"The imperfect is built on the present «nous» form: «nous sortons» → «ils sortaient». It's the tense of habits.","requerTodas":["fr-p108","fr-p070","fr-p160"],"v":"983369da"},{"idioma":"fr","id":"fr-v106","tipo":"frase","fr":"À ta place, je resterais.","aceitasFr":["À votre place, je resterais.","Moi, à ta place, je resterais."],"en":"If I were you, I'd stay.","aceitasEn":["if i were you id stay","if i were you i would stay","in your place id stay","in your shoes id stay","if i was you id stay"],"distratoresEn":["In your place, I stayed.","In your place, I'll stay.","In your place, I had stayed.","In your place, I would have stayed."],"formasFr":{"À ta place, je suis resté":"passé composé","À ta place, je resterai":"future","À ta place, j'étais resté":"pluperfect","À ta place, je serais resté":"past conditional"},"nivel":"A1","tags":["conjugação","condicional","regular","social"],"notaEn":"To give advice: «à ta place», in your place, + conditional. The conditional is the future stem with imperfect endings: «je resterais».","requerTodas":["fr-p218","fr-p269"],"v":"1a462f17"},{"idioma":"fr","id":"fr-p301","tipo":"palavra","fr":"essayer","en":"to try / to try on","aceitasEn":["to try","try","to try on","try on","to attempt","attempt"],"distratoresEn":["to manage / to achieve","to give up / to quit","to choose / to decide","to exchange / to return"],"nivel":"A1","tags":["verbo","compras"],"notaEn":"To try, with «de» before an infinitive: «j'essaie de dormir», I'm trying to sleep. In a store, to try on: «je peux essayer ce pantalon ?». The «y» becomes «i» before a silent ending: j'essaie, nous essayons.","v":"43a02498","pos":284},{"idioma":"fr","id":"fr-p302","tipo":"palavra","fr":"le sandwich","en":"the sandwich","aceitasEn":["sandwich","the sandwich"],"distratoresEn":["the toast","the pizza","the hamburger","the salad"],"nivel":"A1","tags":["comida"],"notaEn":"Masculine, and the filling takes «à»: «un sandwich au fromage», a cheese sandwich. The Paris classic is the «jambon-beurre», a baguette with ham and butter.","v":"4a9608d2","transp":"total","pos":2276},{"idioma":"fr","id":"fr-p303","tipo":"palavra","fr":"frais","aceitasFr":["fraîche"],"en":"fresh","aceitasEn":["fresh","cool","chilly"],"distratoresEn":["fried","weak","rotten","dry"],"nivel":"A1","tags":["adjetivo","comida"],"notaEn":"Feminine «fraîche». Fresh («du poisson frais») and cool, of weather: «il fait frais», it's chilly. A cold drink is «une boisson fraîche».","v":"654d408d","pos":1077},{"idioma":"fr","id":"fr-p304","tipo":"palavra","fr":"le dimanche","aceitasFr":["dimanche"],"en":"Sunday","aceitasEn":["sunday"],"distratoresEn":["Saturday","Monday","Friday","Thursday"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The Lord's day. Without an article it's one Sunday: «dimanche», on Sunday. With it, every Sunday: «le dimanche». Lowercase.","v":"00723d08","pos":923},{"idioma":"fr","id":"fr-p305","tipo":"palavra","fr":"la musique","en":"music","aceitasEn":["music","the music"],"distratoresEn":["dance","noise","painting","theater"],"nivel":"A1","tags":["cultura"],"notaEn":"Feminine, and it takes «de la»: «écouter de la musique», to listen to music. A song is «une chanson».","v":"3309b3c3","pos":324},{"idioma":"fr","id":"fr-p306","tipo":"palavra","fr":"seul","aceitasFr":["seule"],"en":"alone","aceitasEn":["alone","lonely","on my own","by myself","by oneself","on one's own","single"],"distratoresEn":["accompanied","tired","married","quiet"],"nivel":"A1","tags":["adjetivo","social"],"notaEn":"Feminine «seule». Alone («je vis seul»), lonely («je me sens seul») and single: «un seul billet», just one ticket. The adverb only is «seulement».","v":"f683a0b3","pos":68},{"idioma":"fr","id":"fr-p307","tipo":"palavra","fr":"la fois","en":"time (occasion)","aceitasEn":["time","the time","occasion"],"distratoresEn":["hour (on the clock)","faith (religious)","liver (in the body)","season (of the year)"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine, for counting occurrences: «une fois», once; «deux fois», twice; «la première fois», the first time. Time as duration is «le temps».","v":"44e851a3","pos":91},{"idioma":"fr","id":"fr-p308","tipo":"palavra","fr":"amoureux","aceitasFr":["amoureuse"],"en":"in love","aceitasEn":["in love","in love with","amorous"],"distratoresEn":["jealous","bitter","excited","scared"],"nivel":"A2","tags":["adjetivo","social"],"notaEn":"Feminine «amoureuse». «Tomber amoureux de», to fall in love with — «de», not «avec». As a noun, «les amoureux» are a couple in love.","v":"dd78de50","pos":624},{"idioma":"fr","id":"fr-p309","tipo":"palavra","fr":"la valise","en":"the suitcase","aceitasEn":["suitcase","the suitcase","case","valise"],"distratoresEn":["the backpack","the purse","the envelope","the wallet"],"nivel":"A1","tags":["viagem"],"notaEn":"Feminine. «Faire sa valise», to pack your suitcase. A car trunk is «le coffre».","v":"9e9811a8","pos":2178},{"idioma":"fr","id":"fr-p310","tipo":"palavra","fr":"les lunettes","en":"eyeglasses","aceitasEn":["glasses","the glasses","eyeglasses","spectacles","a pair of glasses"],"distratoresEn":["earrings","eyelashes","gloves","flip-flops"],"nivel":"A1","tags":["objetos","saúde"],"notaEn":"Always plural: «porter des lunettes», to wear glasses. Sunglasses are «les lunettes de soleil». A drinking glass is «un verre».","v":"3520a377","pos":1909},{"idioma":"fr","id":"fr-p311","tipo":"palavra","fr":"le match","en":"the game","aceitasEn":["game","the game","match","the match"],"distratoresEn":["the team","the practice","the score","the tournament"],"nivel":"A1","tags":["cultura"],"notaEn":"Masculine, from English: «un match de foot», a soccer game. A tie is «un match nul».","v":"f36fa552","pos":1366},{"idioma":"fr","id":"fr-p312","tipo":"palavra","fr":"le marché","en":"the market","aceitasEn":["market","the market","marketplace","farmers market","the farmers market"],"distratoresEn":["the march","the mall","the butcher shop","the square"],"nivel":"A1","tags":["compras","cidade"],"notaEn":"Masculine. An open-air market («le marché du dimanche») or a market in general. «Bon marché» means cheap; a supermarket is «le supermarché».","v":"2be1e6e9","pos":515},{"idioma":"fr","id":"fr-p313","tipo":"palavra","fr":"tourner","en":"to turn","aceitasEn":["to turn","turn","to spin","spin","to shoot","to film"],"distratoresEn":["to touch","to cough","to stop","to climb"],"nivel":"A1","tags":["verbo","cidade"],"notaEn":"Regular «-er» verb. For directions: «tournez à gauche», turn left. Also to spin («la Terre tourne») and to shoot a movie: «tourner un film».","v":"876a93ef","pos":278},{"idioma":"fr","id":"fr-p314","tipo":"palavra","fr":"la droite","en":"the right (side)","aceitasEn":["right","the right","right side","the right side","right-hand side","the right-hand side"],"distratoresEn":["the left (side)","the front (side)","the back (side)","the top (side)"],"nivel":"A1","tags":["cidade"],"notaEn":"Feminine: «à droite», on the right. Without the «e», «droit» means straight («tout droit») or a right, the law: «le droit». In politics, «la droite» is the right wing.","v":"9abea3cb","pos":1325},{"idioma":"fr","id":"fr-p315","tipo":"palavra","fr":"descendre","en":"to go down","aceitasEn":["to go down","go down","to come down","come down","to get off","get off","to descend","descend","to take down","take down"],"distratoresEn":["to go up","to rest","to decide","to draw"],"nivel":"A1","tags":["verbo","viagem"],"notaEn":"Passé composé with «être»: «je suis descendu». To go down the stairs and to get off a bus or train: «je descends au prochain arrêt». To go up is «monter».","v":"47c6c377","pos":348},{"idioma":"fr","id":"fr-p316","tipo":"palavra","fr":"l'arrêt","aceitasFr":["un arrêt","l'arrêt de bus"],"en":"the stop","aceitasEn":["stop","the stop","bus stop","the bus stop"],"distratoresEn":["the station","the exit","the corner","the arrival"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"Masculine: «un arrêt de bus», a bus stop. Not an arrest: it comes from «arrêter», to stop; «sans arrêt», nonstop.","v":"5bbfc2c7","pos":1161},{"idioma":"fr","id":"fr-p317","tipo":"palavra","fr":"l'étage","aceitasFr":["un étage"],"en":"the floor (of a building)","aceitasEn":["floor","the floor","story","storey","level"],"distratoresEn":["the stairs (of a building)","the ceiling (of a room)","the basement (of a house)","the balcony (of an apartment)"],"nivel":"A1","tags":["casa","cidade"],"notaEn":"Masculine. Floors are counted above the ground floor, «le rez-de-chaussée»: «le premier étage» is the American second floor.","v":"f06d3164","pos":824},{"idioma":"fr","id":"fr-p318","tipo":"palavra","fr":"mieux","en":"better (adverb)","aceitasEn":["better","best"],"distratoresEn":["worse (adverb)","more (adverb)","less (adverb)","well (adverb)"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The adverb, used with verbs: «je me sens mieux», I feel better. With a noun, the adjective is «meilleur»: «un meilleur prix», a better price.","v":"ca23f793","pos":107},{"idioma":"fr","id":"fr-p319","tipo":"palavra","fr":"le week-end","aceitasFr":["le weekend"],"regionaisFr":{"la fin de semaine":"no Quebec"},"en":"the weekend","aceitasEn":["weekend","the weekend"],"distratoresEn":["the holiday","the weekday","the day off","the workweek"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Masculine and hyphenated: «ce week-end», this weekend; «bon week-end !», have a nice weekend! In Quebec it's «la fin de semaine».","v":"57bd72c9","transp":"parecida","pos":916},{"idioma":"fr","id":"fr-p320","tipo":"palavra","fr":"le fil","en":"the thread","aceitasEn":["thread","the thread","wire","the wire","cord"],"distratoresEn":["the son","the movie","the end","the row"],"nivel":"A2","tags":["objetos","tecnologia"],"notaEn":"Masculine, with the «l» pronounced. A thread or a wire, including the phone line: «un coup de fil», a phone call. A son is «le fils».","v":"1516ba75","pos":1641},{"idioma":"fr","id":"fr-p321","tipo":"palavra","fr":"coûter","en":"to cost","aceitasEn":["to cost","cost"],"distratoresEn":["to cut","to count","to charge","to spend"],"nivel":"A1","tags":["verbo","compras"],"notaEn":"Regular «-er» verb: «ça coûte combien ?», how much is it? «Coûter cher», to be expensive. The circumflex stands for a lost «s», as in cost.","v":"a6890714","pos":850},{"idioma":"fr","id":"fr-p322","tipo":"palavra","fr":"compris","aceitasFr":["comprise"],"en":"included","aceitasEn":["included","including","understood","inclusive"],"distratoresEn":["bought","complete","charged","promised"],"nivel":"A1","tags":["adjetivo","compras"],"notaEn":"Past participle of «comprendre», which also means to include: «le service est compris», service is included; «y compris», including. Feminine «comprise».","v":"ca1cf03b","pos":859},{"idioma":"fr","id":"fr-p323","tipo":"palavra","fr":"perdre","en":"to lose","aceitasEn":["to lose","lose","to waste","waste"],"distratoresEn":["to find","to keep","to forget","to spend"],"nivel":"A1","tags":["verbo"],"notaEn":"Regular «-re» verb: je perds, il perd; past participle «perdu». To lose («j'ai perdu ma clé», I lost my key) and to waste: «perdre son temps». To miss a bus is «rater».","v":"924b37e1","pos":118},{"idioma":"fr","id":"fr-p324","tipo":"palavra","fr":"délicieux","aceitasFr":["délicieuse"],"en":"delicious","aceitasEn":["delicious","tasty","yummy"],"distratoresEn":["delicate","awful","salty","bitter"],"nivel":"A1","tags":["adjetivo","comida"],"notaEn":"Feminine «délicieuse». «C'est délicieux !», it's delicious! Delicate is «délicat».","v":"6dc53842","transp":"parecida","pos":1472},{"idioma":"fr","id":"fr-p325","tipo":"palavra","fr":"le menu","en":"the set menu","aceitasEn":["set menu","prix fixe","fixed-price menu","menu","the menu"],"distratoresEn":["the check","the tip","the appetizer","the dessert"],"nivel":"A1","tags":["comida"],"notaEn":"Masculine. In a French restaurant, «le menu» is the fixed-price meal (starter, main, dessert); the list of dishes is «la carte», hence «à la carte».","v":"7545e0eb","pos":1920},{"idioma":"fr","id":"fr-p326","tipo":"palavra","fr":"tousser","en":"to cough","aceitasEn":["to cough","cough"],"distratoresEn":["to sneeze","to swallow","to spit","to snore"],"nivel":"A1","tags":["verbo","saúde"],"notaEn":"Regular «-er» verb: je tousse, nous toussons. A cough is «la toux», and to sneeze, «éternuer».","v":"7a45a50f","pos":3428},{"idioma":"fr","id":"fr-p327","tipo":"palavra","fr":"proche","en":"close (nearby)","aceitasEn":["close"],"distratoresEn":["far (away)","next (in line)","clean (spotless)","empty (with nothing)"],"nivel":"A1","tags":["adjetivo","cidade"],"notaEn":"Same form for masculine and feminine: «l'hôpital le plus proche», the nearest hospital; «proche de», close to. Next in line is «prochain».","v":"0d9d4da7","pos":790},{"idioma":"fr","id":"fr-p328","tipo":"palavra","fr":"rappeler","en":"to call back / to remind","aceitasEn":["to call back","call back","to call again","to remind","remind"],"distratoresEn":["to hang up / to forget","to pick up / to ignore","to leave a message / to delete","to block a number / to lose"],"nivel":"A2","tags":["verbo","tecnologia"],"notaEn":"«Re-» + «appeler»: to call back («je te rappelle», I'll call you back) and to remind: «rappelle-moi d'acheter du pain». The «l» doubles as in «appeler»: je rappelle, nous rappelons.","v":"0987cc42","pos":230},{"idioma":"fr","id":"fr-p329","tipo":"palavra","fr":"montrer","en":"to show","aceitasEn":["to show","show","to point out","point out"],"distratoresEn":["to mount","to lie","to look","to hide"],"nivel":"A1","tags":["verbo"],"notaEn":"Regular «-er» verb, with «à» for the person: «montrer le chemin à quelqu'un», to show someone the way; «montre-moi», show me. To go up, to mount is «monter».","v":"682661b7","pos":149},{"idioma":"fr","id":"fr-p330","tipo":"palavra","fr":"demi","aceitasFr":["demie"],"en":"half","aceitasEn":["half","and a half"],"distratoresEn":["whole","double","triple","third"],"nivel":"A1","tags":["cotidiano"],"notaEn":"After the noun it agrees: «sept heures et demie», half past seven; «un kilo et demi», a kilo and a half. Before it, it's invariable with a hyphen: «une demi-heure», half an hour.","v":"caeccd6e","pos":1375},{"idioma":"fr","id":"fr-p331","tipo":"palavra","fr":"plein","aceitasFr":["pleine"],"en":"full","aceitasEn":["full","packed","crowded","filled"],"distratoresEn":["empty","flat","light","closed"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «pleine». Full («le restaurant est plein»), and in set phrases: «en plein air», outdoors; «faire le plein», to fill up the tank. The opposite is «vide».","v":"64db86a0","pos":251},{"idioma":"fr","id":"fr-p332","tipo":"palavra","fr":"la campagne","en":"the countryside","aceitasEn":["countryside","the countryside","campaign","the campaign"],"distratoresEn":["the city","the mountains","the beach","the suburbs"],"nivel":"A1","tags":["natureza"],"notaEn":"Feminine. The countryside, as opposed to the city: «à la campagne», in the country. It also means a campaign: «une campagne électorale».","v":"5771c9d1","pos":825},{"idioma":"fr","id":"fr-p333","tipo":"palavra","fr":"sympa","aceitasFr":["sympathique"],"en":"nice (friendly)","aceitasEn":["nice","friendly","pleasant","likeable","cool"],"distratoresEn":["annoying (irritating)","serious (stern)","shy (quiet)","sincere (honest)"],"nivel":"A1","tags":["adjetivo","social"],"notaEn":"Short for «sympathique», informal, same for both genders: «elle est sympa». Not sympathetic: nice, friendly, of people and places: «un petit resto sympa».","v":"3cb90338","pos":693},{"idioma":"fr","id":"fr-p334","tipo":"palavra","fr":"l'anniversaire","aceitasFr":["un anniversaire"],"en":"the birthday","aceitasEn":["birthday","the birthday","anniversary","the anniversary"],"distratoresEn":["the wedding","the party","the holiday","the christening"],"nivel":"A1","tags":["social","família"],"notaEn":"Masculine. Mostly a birthday: «bon anniversaire !», happy birthday! Also an anniversary: «l'anniversaire de mariage».","v":"cb853781","pos":1027},{"idioma":"fr","id":"fr-p335","tipo":"palavra","fr":"louer","en":"to rent","aceitasEn":["to rent","rent","to rent out","rent out","to hire","hire","to let","to lease","lease"],"distratoresEn":["to wash","to buy","to sell","to lend"],"nivel":"A2","tags":["verbo","casa"],"notaEn":"Works both ways, renting and renting out: «louer un appartement». On signs, «à louer», for rent. A rental is «une location», not a location.","v":"8e631382","pos":1146},{"idioma":"fr","id":"fr-p336","tipo":"palavra","fr":"la gorge","en":"the throat","aceitasEn":["throat","the throat","gorge","the gorge"],"distratoresEn":["the neck","the nape","the shoulder","the jaw"],"nivel":"A1","tags":["corpo","saúde"],"notaEn":"Feminine: «j'ai mal à la gorge», I have a sore throat. In the mountains, «les gorges» are gorges.","v":"e0c7aac2","pos":2000},{"idioma":"fr","id":"fr-p337","tipo":"palavra","fr":"le rendez-vous","aceitasFr":["le rdv"],"en":"the appointment / the date","aceitasEn":["appointment","the appointment","date","the date"],"distratoresEn":["the invitation / the message","the party / the dinner","the delay / the wait","the trip / the outing"],"nivel":"A1","tags":["saúde","social"],"notaEn":"Masculine and invariable. «Prendre rendez-vous», to make an appointment; «un premier rendez-vous», a first date. English borrowed it as rendezvous.","v":"281b4a51","pos":575},{"idioma":"fr","id":"fr-p338","tipo":"palavra","fr":"le mardi","aceitasFr":["mardi"],"en":"Tuesday","aceitasEn":["tuesday"],"distratoresEn":["Wednesday","Thursday","Monday","Sunday"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The day of Mars. «Mardi», on Tuesday; «le mardi», on Tuesdays. «Mardi gras» is literally Fat Tuesday.","v":"78ac4143","pos":171},{"idioma":"fr","id":"fr-p339","tipo":"palavra","fr":"le mercredi","aceitasFr":["mercredi"],"en":"Wednesday","aceitasEn":["wednesday"],"distratoresEn":["Tuesday","Thursday","Friday","Saturday"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The day of Mercury. «Mercredi», on Wednesday; «le mercredi», on Wednesdays. Lowercase, like all French weekdays.","v":"cd5e8a6b","pos":195},{"idioma":"fr","id":"fr-p340","tipo":"palavra","fr":"le jeudi","aceitasFr":["jeudi"],"en":"Thursday","aceitasEn":["thursday"],"distratoresEn":["Wednesday","Friday","Tuesday","Saturday"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The day of Jupiter, Latin «Jovis dies», as Thursday is Thor's. «Jeudi», on Thursday; «le jeudi», on Thursdays.","v":"a4daa1aa","pos":145},{"idioma":"fr","id":"fr-p341","tipo":"palavra","fr":"le vendredi","aceitasFr":["vendredi"],"en":"Friday","aceitasEn":["friday"],"distratoresEn":["Thursday","Saturday","Monday","Tuesday"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The day of Venus. «Vendredi», on Friday; «le vendredi», on Fridays. «Vendredi saint», Good Friday.","v":"1c8fe87b","pos":1144},{"idioma":"fr","id":"fr-p342","tipo":"palavra","fr":"le printemps","en":"spring","aceitasEn":["spring","the spring","springtime"],"distratoresEn":["summer","fall","winter","frost"],"nivel":"A1","tags":["natureza","cotidiano"],"notaEn":"Masculine, with a silent final «s». The only season that takes «au»: «au printemps», in spring; the others take «en».","v":"b3ce54e6","pos":201},{"idioma":"fr","id":"fr-p343","tipo":"palavra","fr":"l'automne","aceitasFr":["un automne"],"en":"fall (season)","aceitasEn":["fall","the fall","autumn","the autumn"],"distratoresEn":["summer (season)","winter (season)","spring (season)","frost (weather)"],"nivel":"A1","tags":["natureza","cotidiano"],"notaEn":"Masculine, with a silent «m». «En automne», in the fall.","v":"b90dc35b","pos":2046},{"idioma":"fr","id":"fr-p344","tipo":"palavra","fr":"blanc","aceitasFr":["blanche"],"en":"white","aceitasEn":["white"],"distratoresEn":["black","gray","beige","blue"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «blanche». White wine is «le vin blanc»; «une nuit blanche» is a sleepless night.","v":"f8324119","pos":389},{"idioma":"fr","id":"fr-p345","tipo":"palavra","fr":"noir","aceitasFr":["noire"],"en":"black","aceitasEn":["black","dark"],"distratoresEn":["white","gray","brown","blue"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «noire». Also dark: «il fait noir», it's dark. «Un café noir» is black coffee.","v":"8747903f","pos":366},{"idioma":"fr","id":"fr-p346","tipo":"palavra","fr":"bleu","aceitasFr":["bleue"],"en":"blue","aceitasEn":["blue"],"distratoresEn":["green","gray","yellow","white"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «bleue», pronounced the same; plural «bleus». As a noun, «un bleu» is a bruise.","v":"04c985f6","pos":665},{"idioma":"fr","id":"fr-p347","tipo":"palavra","fr":"vert","aceitasFr":["verte"],"en":"green","aceitasEn":["green"],"distratoresEn":["blue","yellow","brown","gray"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «verte», where the «t» is heard. «Le feu vert», the green light. «Le vers», a line of poetry, sounds just like «vert».","v":"827bbc3e","pos":839},{"idioma":"fr","id":"fr-p348","tipo":"palavra","fr":"jaune","en":"yellow","aceitasEn":["yellow"],"distratoresEn":["green","blue","brown","golden"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Same form for both genders: «une robe jaune». An egg yolk is «le jaune d'œuf».","v":"7ed8af61","pos":189},{"idioma":"fr","id":"fr-p349","tipo":"palavra","fr":"la bière","en":"beer","aceitasEn":["beer","the beer"],"distratoresEn":["wine","juice","cider","vodka"],"nivel":"A1","tags":["comida"],"notaEn":"Feminine: «une bière, s'il vous plaît». A draft beer is «une pression», and a lager, «une blonde».","v":"b210a01e","pos":1019},{"idioma":"fr","id":"fr-p350","tipo":"palavra","fr":"le riz","en":"rice","aceitasEn":["rice","the rice"],"distratoresEn":["beans","wheat","corn","pasta"],"nivel":"A1","tags":["comida"],"notaEn":"Masculine, with a silent «z»: it sounds like «ree». Rice pudding is «le riz au lait».","v":"c0a7390e","pos":1952},{"idioma":"fr","id":"fr-p351","tipo":"palavra","fr":"le sucre","en":"sugar","aceitasEn":["sugar","the sugar"],"distratoresEn":["salt","flour","honey","butter"],"nivel":"A1","tags":["comida"],"notaEn":"Masculine: «sans sucre», sugar-free. A sugar cube is «un morceau de sucre».","v":"7c72a9d2","pos":1436},{"idioma":"fr","id":"fr-p352","tipo":"palavra","fr":"le sel","en":"salt","aceitasEn":["salt","the salt"],"distratoresEn":["sugar","pepper","oil","vinegar"],"nivel":"A1","tags":["comida"],"notaEn":"Masculine: «passe-moi le sel», pass me the salt. Salty is «salé»; careful: «sale», without the accent, means dirty.","v":"166c901c","pos":1843},{"idioma":"fr","id":"fr-p353","tipo":"palavra","fr":"la pomme de terre","sinonimosFr":["la patate"],"en":"the potato","aceitasEn":["potato","the potato"],"distratoresEn":["the apple","the carrot","the onion","the cassava"],"nivel":"A1","tags":["comida"],"notaEn":"Feminine, literally «earth apple». French fries are «les frites»; informally, people also say «la patate».","v":"a31d8416","pos":1235},{"idioma":"fr","id":"fr-p354","tipo":"palavra","fr":"la chaise","en":"the chair","aceitasEn":["chair","the chair"],"distratoresEn":["the armchair","the table","the shelf","the dresser"],"nivel":"A1","tags":["casa"],"notaEn":"Feminine. An armchair is «un fauteuil»; a lounge chair, «une chaise longue».","v":"c1107e31","pos":1088},{"idioma":"fr","id":"fr-p355","tipo":"palavra","fr":"l'assiette","aceitasFr":["une assiette"],"en":"the plate","aceitasEn":["plate","the plate"],"distratoresEn":["the bowl","the pot","the napkin","the tray"],"nivel":"A1","tags":["casa","comida"],"notaEn":"Feminine. The plate you eat from; a dish of food is «le plat»: «le plat du jour».","v":"87f87b0e","pos":1774},{"idioma":"fr","id":"fr-p356","tipo":"palavra","fr":"la tasse","en":"the cup","aceitasEn":["cup","the cup","mug","the mug"],"distratoresEn":["the goblet","the saucer","the jug","the bottle"],"nivel":"A1","tags":["casa","comida"],"notaEn":"Feminine: «une tasse de thé», a cup of tea. A saucer is «une soucoupe».","v":"4e068d19","pos":1710},{"idioma":"fr","id":"fr-p357","tipo":"palavra","fr":"le couteau","en":"the knife","aceitasEn":["knife","the knife"],"distratoresEn":["the fork","the spoon","the scissors","the opener"],"nivel":"A1","tags":["casa","objetos"],"notaEn":"Masculine, plural «couteaux». A fork is «une fourchette», and a spoon, «une cuillère».","v":"e7036585","pos":1608},{"idioma":"fr","id":"fr-p358","tipo":"palavra","fr":"la jupe","en":"the skirt","aceitasEn":["skirt","the skirt"],"distratoresEn":["the dress","the blouse","the pants","the shorts"],"nivel":"A1","tags":["roupa"],"notaEn":"Feminine: «une jupe longue», a long skirt. A dress is «une robe», not a robe.","v":"ed5af004","pos":2984},{"idioma":"fr","id":"fr-p359","tipo":"palavra","fr":"le chapeau","en":"the hat","aceitasEn":["hat","the hat"],"distratoresEn":["the cap","the helmet","the scarf","the wig"],"nivel":"A1","tags":["roupa"],"notaEn":"Masculine, plural «chapeaux». «Chapeau !», hats off!","v":"acd91907","pos":1021},{"idioma":"fr","id":"fr-p360","tipo":"palavra","fr":"la jambe","en":"the leg","aceitasEn":["leg","the leg"],"distratoresEn":["the knee","the ankle","the ham","the hip"],"nivel":"A1","tags":["corpo"],"notaEn":"Feminine: «j'ai mal à la jambe», my leg hurts. Ham, from the pig's leg, is «le jambon».","v":"cfbb2b8b","pos":734},{"idioma":"fr","id":"fr-p361","tipo":"palavra","fr":"le nez","en":"the nose","aceitasEn":["nose","the nose"],"distratoresEn":["the chin","the forehead","the ear","the cheek"],"nivel":"A1","tags":["corpo"],"notaEn":"Masculine, with a silent «z». «J'ai le nez qui coule», I have a runny nose.","v":"4b9d6248","pos":858},{"idioma":"fr","id":"fr-p362","tipo":"palavra","fr":"la dent","en":"the tooth","aceitasEn":["tooth","the tooth"],"distratoresEn":["the gum","the lip","the bone","the nail"],"nivel":"A1","tags":["corpo","saúde"],"notaEn":"Feminine: «une dent». «J'ai mal aux dents», I have a toothache.","v":"80060fe7","pos":951},{"idioma":"fr","id":"fr-p363","tipo":"palavra","fr":"la banque","en":"the bank","aceitasEn":["bank","the bank"],"distratoresEn":["the store","city hall","the post office","the factory"],"nivel":"A1","tags":["cidade"],"notaEn":"Feminine: «à la banque», at the bank. A bench is «un banc».","v":"616c4869","pos":881},{"idioma":"fr","id":"fr-p364","tipo":"palavra","fr":"la bibliothèque","en":"the library","aceitasEn":["library","the library","bookcase","the bookcase","bookshelf"],"distratoresEn":["the bookstore","the stationery store","the school","the archive"],"nivel":"A1","tags":["cidade","cultura"],"notaEn":"Feminine. A library, and also a bookcase. A bookstore is «une librairie», a classic trap.","v":"8e1a3454","pos":1625},{"idioma":"fr","id":"fr-p365","tipo":"palavra","fr":"l'aéroport","aceitasFr":["un aéroport"],"en":"the airport","aceitasEn":["airport","the airport"],"distratoresEn":["the port","the station","the hangar","the runway"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"Masculine: «à l'aéroport», at the airport. A flight is «un vol», and to take off, «décoller».","v":"428129b2","pos":1274},{"idioma":"fr","id":"fr-p366","tipo":"palavra","fr":"le professeur","aceitasFr":["le prof","la professeure"],"sinonimosFr":["l'enseignant"],"en":"the teacher","aceitasEn":["teacher","the teacher","professor","the professor"],"distratoresEn":["the student","the principal","the writer","the researcher"],"nivel":"A1","tags":["profissões","escola"],"notaEn":"A teacher at any level, school or university; informally «le prof». For a woman, «la professeure» or «la prof».","v":"cde023cf","pos":490},{"idioma":"fr","id":"fr-p367","tipo":"palavra","fr":"le serveur","aceitasFr":["la serveuse"],"en":"the waiter","aceitasEn":["waiter","the waiter","waitress","server","the server"],"distratoresEn":["the cook","the doorman","the servant","the manager"],"nivel":"A1","tags":["profissões","comida"],"notaEn":"Feminine «la serveuse». To get their attention, just say «s'il vous plaît»; «garçon !» sounds old-fashioned. In computing, «le serveur» is a server.","v":"b3ea08ab","pos":1397},{"idioma":"fr","id":"fr-p368","tipo":"palavra","fr":"l'avocat","aceitasFr":["un avocat"],"en":"the lawyer / the avocado","aceitasEn":["lawyer","the lawyer","avocado","the avocado","attorney","the attorney"],"distratoresEn":["the judge / the fig","the defendant / the mango","the police officer / the pear","the doctor / the persimmon"],"nivel":"A2","tags":["profissões","comida"],"notaEn":"Masculine. The same word for a lawyer and an avocado; a female lawyer is «l'avocate». Context decides: «mon avocat», «une salade d'avocat».","v":"aa27eefc","pos":747},{"idioma":"fr","id":"fr-p369","tipo":"palavra","fr":"mauvais","aceitasFr":["mauvaise"],"en":"bad","aceitasEn":["bad","wrong"],"distratoresEn":["good","soft","ugly","thin"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «mauvaise». Bad («il fait mauvais», the weather's bad) and wrong: «le mauvais numéro», the wrong number. The adverb badly is «mal».","v":"f23315f6","pos":312},{"idioma":"fr","id":"fr-p370","tipo":"palavra","fr":"difficile","en":"difficult","aceitasEn":["difficult","hard","tough"],"distratoresEn":["easy","fragile","simple","docile"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Same form for both genders: «c'est difficile», it's hard. Of a person, picky or demanding: «un enfant difficile».","v":"62ed1750","transp":"parecida","pos":311},{"idioma":"fr","id":"fr-p371","tipo":"palavra","fr":"triste","en":"sad","aceitasEn":["sad","unhappy"],"distratoresEn":["cheerful","calm","angry","nervous"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Same form for both genders: «je suis triste», I'm sad. Sadness is «la tristesse».","v":"d5d9e096","pos":492},{"idioma":"fr","id":"fr-p372","tipo":"palavra","fr":"drôle","sinonimosFr":["marrant","rigolo"],"en":"funny","aceitasEn":["funny","amusing","strange","odd","weird"],"distratoresEn":["serious","boring","sad","shy"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Same form for both genders: «c'est drôle !», that's funny! Before «de», strange: «une drôle d'idée», an odd idea.","v":"d464b2d7","pos":765},{"idioma":"fr","id":"fr-p373","tipo":"palavra","fr":"préférer","en":"to prefer","aceitasEn":["to prefer","prefer","would rather"],"distratoresEn":["to utter","to promise","to offer","to warn"],"nivel":"A1","tags":["verbo"],"notaEn":"The accent changes with the stressed syllable: je préfère, nous préférons. «Je préfère le thé», I prefer tea.","v":"62ead708","pos":351},{"idioma":"fr","id":"fr-p374","tipo":"palavra","fr":"répondre","en":"to answer","aceitasEn":["to answer","answer","to reply","reply","to respond","respond"],"distratoresEn":["to ask","to repeat","to repair","to explain"],"nivel":"A1","tags":["verbo","social"],"notaEn":"With «à»: «répondre à une question», to answer a question; «répondre au téléphone», to answer the phone. The answer is «la réponse».","v":"9cea7263","pos":142},{"idioma":"fr","id":"fr-p375","tipo":"palavra","fr":"conduire","en":"to drive","aceitasEn":["to drive","drive","to lead","lead"],"distratoresEn":["to build","to obtain","to fix","to park"],"nivel":"A1","tags":["verbo","viagem"],"notaEn":"Irregular: je conduis, nous conduisons; past participle «conduit». A driver's license is «le permis de conduire».","v":"3681eba7","pos":402},{"idioma":"fr","id":"fr-p376","tipo":"palavra","fr":"envoyer","en":"to send","aceitasEn":["to send","send","to mail","mail"],"distratoresEn":["to wrap","to receive","to pack","to keep"],"nivel":"A1","tags":["verbo","tecnologia"],"notaEn":"The «y» becomes «i» before a silent ending: j'envoie, nous envoyons. Irregular future: «j'enverrai». «Envoyer un message», to send a message.","v":"8c7e8809","pos":197},{"idioma":"fr","id":"fr-p377","tipo":"palavra","fr":"choisir","en":"to choose","aceitasEn":["to choose","choose","to pick","pick","to select","select"],"distratoresEn":["to cry","to smell","to brush","to change"],"nivel":"A1","tags":["verbo","compras"],"notaEn":"Regular «-ir» verb, like «finir»: je choisis, nous choisissons. A choice is «un choix».","v":"ec147b79","pos":248},{"idioma":"fr","id":"fr-p378","tipo":"palavra","fr":"cuisiner","sinonimosFr":["faire la cuisine"],"en":"to cook","aceitasEn":["to cook","cook"],"distratoresEn":["to sew","to wash","to clean","to have lunch"],"nivel":"A1","tags":["verbo","comida"],"notaEn":"Regular «-er» verb: «j'aime cuisiner», I love to cook. The kitchen, and cooking itself, is «la cuisine».","v":"41b85c8a","pos":1689},{"idioma":"fr","id":"fr-p379","tipo":"palavra","fr":"vraiment","en":"really (truly)","aceitasEn":["really","truly","for real","genuinely"],"distratoresEn":["rarely (seldom)","almost (nearly)","maybe (perhaps)","finally (at last)"],"nivel":"A1","tags":["cotidiano"],"notaEn":"From «vrai», true: «c'est vraiment bon», it's really good. On its own, in surprise: «Vraiment ?», really?","v":"30e824d7","pos":85},{"idioma":"fr","id":"fr-p380","tipo":"palavra","fr":"ensuite","sinonimosFr":["puis"],"en":"then","aceitasEn":["then","afterwards","afterward","after that"],"distratoresEn":["before","now","finally","never"],"nivel":"A1","tags":["cotidiano"],"notaEn":"For sequences: «d'abord… ensuite… enfin», first… then… finally. One word; «puis» means the same.","v":"4a7e96cf","pos":289},{"idioma":"fr","id":"fr-p381","tipo":"palavra","fr":"d'abord","aceitasFr":["tout d'abord"],"sinonimosFr":["premièrement"],"en":"first of all","aceitasEn":["first","first of all","firstly","to begin with","at first"],"distratoresEn":["after that","in the end","right now","once again"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Opens a sequence: «d'abord… ensuite… enfin». Also at first: «d'abord, je n'ai pas compris», at first I didn't understand.","v":"a255a50c","pos":277},{"idioma":"fr","id":"fr-p382","tipo":"palavra","fr":"presque","en":"almost","aceitasEn":["almost","nearly"],"distratoresEn":["enough","too much","only","soon"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«J'ai presque fini», I'm almost done; «presque toujours», almost always.","v":"424ba058","pos":279},{"idioma":"fr","id":"fr-p383","tipo":"palavra","fr":"le soleil","en":"the sun","aceitasEn":["sun","the sun","sunshine"],"distratoresEn":["the moon","the star","the sky","the cloud"],"nivel":"A1","tags":["natureza"],"notaEn":"Masculine: «il y a du soleil», it's sunny. Sunglasses are «les lunettes de soleil».","v":"c68ac80b","pos":525},{"idioma":"fr","id":"fr-p384","tipo":"palavra","fr":"la neige","en":"snow","aceitasEn":["snow","the snow"],"distratoresEn":["rain","ice","fog","frost"],"nivel":"A1","tags":["natureza"],"notaEn":"Feminine. To snow is «neiger»: «il neige», it's snowing.","v":"91bc4d32","pos":1255},{"idioma":"fr","id":"fr-u379","tipo":"frase","requer":"fr-p338","fr":"Mardi, je ne travaille pas.","en":"I'm not working on Tuesday.","aceitasEn":["im not working on tuesday","im not working tuesday","i am not working on tuesday","i dont work on tuesday","on tuesday im not working","i do not work on tuesday"],"distratoresEn":["I'm not working on Wednesday.","I'm not working on Thursday.","I'm not working on Friday.","I'm not working on Monday."],"nivel":"A1","tags":["cotidiano","trabalho"],"notaEn":"No article: «mardi», this coming Tuesday. With the article, «le mardi», every Tuesday. No preposition is needed, and days are lowercase.","requerTodas":["fr-p338","fr-p017"],"v":"64918f7e"},{"idioma":"fr","id":"fr-u380","tipo":"frase","requer":"fr-p339","fr":"Le mercredi, les enfants n'ont pas école.","en":"On Wednesdays, the kids don't have school.","aceitasEn":["on wednesdays the kids dont have school","on wednesdays the children dont have school","the kids dont have school on wednesdays","the children dont have school on wednesdays","on wednesdays kids dont have school","on wednesdays the children do not have school","on wednesdays the kids have no school"],"distratoresEn":["On Mondays, the kids don't have school.","On Tuesdays, the kids don't have school.","On Thursdays, the kids don't have school.","On Fridays, the kids don't have school."],"nivel":"A1","tags":["escola","cotidiano"],"notaEn":"With the article, «le mercredi» means every Wednesday. Many French schools have no classes on Wednesdays. «Avoir école» means to have school.","requerTodas":["fr-p339","fr-p023","fr-p002","fr-p106"],"v":"f577bc95"},{"idioma":"fr","id":"fr-u381","tipo":"frase","requer":"fr-p340","fr":"Je suis libre jeudi soir.","en":"I'm free Thursday evening.","aceitasEn":["im free thursday evening","im free on thursday evening","im free thursday night","im free on thursday night","i am free on thursday evening","i am free thursday evening","i am free thursday night"],"distratoresEn":["I'm free Monday evening.","I'm free Tuesday evening.","I'm free Friday evening.","I'm free Sunday evening."],"nivel":"A1","tags":["cotidiano","social"],"notaEn":"«Jeudi soir», Thursday evening: no preposition, just as in English. Likewise «jeudi matin», Thursday morning.","requerTodas":["fr-p001","fr-p201","fr-p340","fr-p160"],"v":"2411c91e"},{"idioma":"fr","id":"fr-u382","tipo":"frase","requer":"fr-p341","fr":"Le vendredi, je finis tôt.","en":"On Fridays I finish early.","aceitasEn":["on fridays i finish early","i finish early on fridays","on fridays i get off early","i get off early on fridays","on fridays i finish work early","i finish early on friday"],"distratoresEn":["On Mondays I finish early.","On Tuesdays I finish early.","On Wednesdays I finish early.","On Saturdays I finish early."],"nivel":"A1","tags":["cotidiano","trabalho"],"notaEn":"«Le vendredi», with the article, means every Friday; «vendredi» alone would be just this one. «Finir» is a regular «-ir» verb: je finis, il finit.","requerTodas":["fr-p341","fr-p123","fr-p181"],"v":"4e7bb8f8"},{"idioma":"fr","id":"fr-u383","tipo":"frase","requer":"fr-p342","fr":"Au printemps, le parc est très beau.","en":"In spring, the park is very beautiful.","aceitasEn":["in spring the park is very beautiful","in the spring the park is very beautiful","in spring the park is really beautiful","the park is very beautiful in spring","the park is very beautiful in the spring","in spring the park is very pretty","in springtime the park is very beautiful"],"distratoresEn":["In summer, the park is very beautiful.","In the fall, the park is very beautiful.","In winter, the park is very beautiful.","At Christmas, the park is very beautiful."],"nivel":"A1","tags":["natureza","cidade"],"notaEn":"Spring is the only season that takes «au»: «au printemps». The others take «en»: «en été», «en automne», «en hiver».","requerTodas":["fr-p342","fr-p267","fr-p001","fr-p043","fr-p040"],"v":"5d8bb079"},{"idioma":"fr","id":"fr-u384","tipo":"frase","requer":"fr-p343","fr":"En automne, il pleut beaucoup.","en":"It rains a lot in the fall.","aceitasEn":["it rains a lot in the fall","it rains a lot in fall","it rains a lot in autumn","it rains a lot in the autumn","in the fall it rains a lot","in autumn it rains a lot","in the fall it rains a lot"],"distratoresEn":["It rains a lot in the spring.","It rains a lot in the summer.","It rains a lot in the winter.","It rains a lot in April."],"nivel":"A1","tags":["natureza"],"notaEn":"«En automne», in the fall: «en», no article. The «m» in «automne» is silent. «Il pleut» is the present of «pleuvoir».","requerTodas":["fr-p343","fr-p171","fr-p067"],"v":"09027a46"},{"idioma":"fr","id":"fr-u385","tipo":"frase","requer":"fr-p344","fr":"Elle a une voiture blanche.","en":"She has a white car.","aceitasEn":["she has a white car","shes got a white car","she has got a white car","her car is white"],"distratoresEn":["She has a black car.","She has a red car.","She has a blue car.","She has a gray car."],"nivel":"A1","tags":["cotidiano","cidade"],"notaEn":"«Voiture» is feminine, so the color agrees: «blanc» becomes «blanche». Colors come after the noun.","requerTodas":["fr-p002","fr-p034","fr-p344"],"v":"d76c0a39"},{"idioma":"fr","id":"fr-u386","tipo":"frase","requer":"fr-p345","fr":"Il fait noir ici.","en":"It's dark in here.","aceitasEn":["its dark in here","its dark here","it is dark in here","it is dark here"],"distratoresEn":["It's cold in here.","It's hot in here.","It's humid in here.","It's stuffy in here."],"nivel":"A1","tags":["casa","cotidiano"],"notaEn":"«Noir» also means dark: «il fait noir», it's dark, just like «il fait froid», it's cold. Light and weather take «il fait».","requerTodas":["fr-p004","fr-p345","fr-p048"],"v":"4193bebc"},{"idioma":"fr","id":"fr-u387","tipo":"frase","requer":"fr-p345","fr":"J'ai un chat noir.","en":"I have a black cat.","aceitasEn":["i have a black cat","ive got a black cat","i have got a black cat"],"distratoresEn":["I have a white cat.","I have a gray cat.","I have an orange cat.","I have a tabby cat."],"nivel":"A1","tags":["animais"],"notaEn":"The color goes after the noun: «un chat noir». The feminine «noire» sounds the same: «une voiture noire».","requerTodas":["fr-p002","fr-p187","fr-p345"],"v":"b28b83e3"},{"idioma":"fr","id":"fr-u388","tipo":"frase","requer":"fr-p346","fr":"Il a les yeux bleus.","en":"He has blue eyes.","aceitasEn":["he has blue eyes","hes got blue eyes","he has got blue eyes","his eyes are blue"],"distratoresEn":["He has green eyes.","He has brown eyes.","He has dark eyes.","He has gray eyes."],"nivel":"A1","tags":["corpo"],"notaEn":"«Les yeux» is the irregular plural of «l'œil». Eye color is «avoir les yeux» + color, with the adjective in the plural: «il a les yeux bleus».","requerTodas":["fr-p002","fr-p275","fr-p346"],"v":"a3a17d5f"},{"idioma":"fr","id":"fr-u389","tipo":"frase","requer":"fr-p347","fr":"J'aime le thé vert.","en":"I like green tea.","aceitasEn":["i like green tea","i love green tea","i really like green tea"],"distratoresEn":["I like black tea.","I like white tea.","I like iced tea.","I like sweet tea."],"nivel":"A1","tags":["comida"],"notaEn":"With «aimer», French keeps the article where English drops it: «j'aime le thé vert», I like green tea.","requerTodas":["fr-p015","fr-p242","fr-p347"],"v":"bb5fdbe1"},{"idioma":"fr","id":"fr-u390","tipo":"frase","requer":"fr-p348","fr":"Ma chambre est jaune.","en":"My bedroom is yellow.","aceitasEn":["my bedroom is yellow","my room is yellow"],"distratoresEn":["My bedroom is blue.","My bedroom is green.","My bedroom is white.","My bedroom is pink."],"nivel":"A1","tags":["casa"],"notaEn":"«Jaune» has one form for both genders: «ma chambre est jaune», even though «chambre» is feminine.","requerTodas":["fr-p107","fr-p001","fr-p348"],"v":"dc0dc277"},{"idioma":"fr","id":"fr-u391","tipo":"frase","requer":"fr-p349","fr":"Une bière, s'il vous plaît.","en":"A beer, please.","aceitasEn":["a beer please","one beer please","can i have a beer please","ill have a beer please","i will have a beer please","could i have a beer please"],"distratoresEn":["A lemonade, please.","A cider, please.","A soda, please.","A vodka, please."],"nivel":"A1","tags":["comida"],"notaEn":"To order, just name it and add «s'il vous plaît». «Une bière» is feminine; a draft beer is «une pression».","requerTodas":["fr-p349"],"v":"8ad8aed0"},{"idioma":"fr","id":"fr-u392","tipo":"frase","requer":"fr-p350","fr":"Je mange du riz tous les jours.","en":"I eat rice every day.","aceitasEn":["i eat rice every day","i have rice every day","every day i eat rice","i eat rice everyday"],"distratoresEn":["I eat bread every day.","I eat pasta every day.","I eat fish every day.","I eat cheese every day."],"nivel":"A1","tags":["comida"],"notaEn":"An unspecified amount takes «du»: «je mange du riz», I eat rice. The «z» in «riz» is silent.","requerTodas":["fr-p013","fr-p350","fr-p070","fr-p019"],"v":"ea1c93a1"},{"idioma":"fr","id":"fr-u393","tipo":"frase","requer":"fr-p351","fr":"Un café sans sucre, s'il vous plaît.","en":"A coffee without sugar, please.","aceitasEn":["a coffee without sugar please","a coffee with no sugar please","one coffee without sugar please","a coffee no sugar please","coffee without sugar please","can i have a coffee without sugar please"],"distratoresEn":["A coffee without milk, please.","A coffee without cream, please.","A coffee without cinnamon, please.","A coffee without foam, please."],"nivel":"A1","tags":["comida"],"notaEn":"No article after «sans»: «sans sucre», «sans lait», without sugar, without milk.","requerTodas":["fr-p057","fr-p351"],"v":"c5e468d8"},{"idioma":"fr","id":"fr-u394","tipo":"frase","requer":"fr-p352","fr":"Il n'y a pas assez de sel.","en":"There isn't enough salt.","aceitasEn":["there isnt enough salt","there is not enough salt","theres not enough salt","it needs more salt","it doesnt have enough salt"],"distratoresEn":["There isn't enough sugar.","There isn't enough bread.","There isn't enough cheese.","There isn't enough rice."],"nivel":"A1","tags":["comida"],"notaEn":"After «assez», just «de», no article: «assez de sel», enough salt. Careful: «sale», without the accent, means dirty.","requerTodas":["fr-p002","fr-p300","fr-p352"],"v":"34d6d078"},{"idioma":"fr","id":"fr-u395","tipo":"frase","requer":"fr-p353","fr":"J'achète un kilo de pommes de terre.","en":"I'm buying a kilo of potatoes.","aceitasEn":["im buying a kilo of potatoes","i am buying a kilo of potatoes","i buy a kilo of potatoes","im getting a kilo of potatoes"],"distratoresEn":["I'm buying a kilo of onions.","I'm buying a kilo of carrots.","I'm buying a kilo of tomatoes.","I'm buying a kilo of oranges."],"nivel":"A1","tags":["comida","compras"],"notaEn":"In the plural, only «pomme» takes the «s»: «des pommes de terre». After «un kilo», just «de».","requerTodas":["fr-p075","fr-p259","fr-p353"],"v":"e3064192"},{"idioma":"fr","id":"fr-u396","tipo":"frase","requer":"fr-p354","fr":"Il y a une chaise libre ?","en":"Is there a free chair?","aceitasEn":["is there a free chair","is there an empty chair","is there a chair free","is there a spare chair","is there a chair available","are there any free chairs"],"distratoresEn":["Is there a free table?","Is there a free armchair?","Is there a free bed?","Is there a free room?"],"nivel":"A1","tags":["casa"],"notaEn":"«Il y a…?» asks whether there is something: is there…? «Libre» means free, unoccupied.","requerTodas":["fr-p002","fr-p354","fr-p201"],"v":"7322b8f3"},{"idioma":"fr","id":"fr-u397","tipo":"frase","requer":"fr-p355","fr":"Mets les assiettes sur la table.","en":"Put the plates on the table.","aceitasEn":["put the plates on the table","set the plates on the table","put the plates on the table please","lay the plates on the table"],"distratoresEn":["Put the glasses on the table.","Put the napkins on the table.","Put the forks on the table.","Put the cups on the table."],"nivel":"A1","tags":["casa","comida"],"notaEn":"«L'assiette» is the plate you eat from; a dish of food is «le plat». «Mets» is the «tu» imperative of «mettre».","requerTodas":["fr-p167","fr-p355","fr-p143"],"v":"20c82c79"},{"idioma":"fr","id":"fr-u398","tipo":"frase","requer":"fr-p356","fr":"Tu veux une tasse de thé ?","en":"Do you want a cup of tea?","aceitasEn":["do you want a cup of tea","would you like a cup of tea","want a cup of tea","do you want a mug of tea","would you like a mug of tea"],"distratoresEn":["Do you want a box of tea?","Do you want a bottle of tea?","Do you want a pitcher of tea?","Do you want a teaspoon of tea?"],"nivel":"A1","tags":["comida","casa"],"notaEn":"«Une tasse de thé», a cup of tea: container + «de», no article. An empty teacup is «une tasse à thé».","requerTodas":["fr-p007","fr-p356","fr-p242"],"v":"ca4a26a6"},{"idioma":"fr","id":"fr-u399","tipo":"frase","requer":"fr-p357","fr":"Je n'ai pas de couteau.","en":"I don't have a knife.","aceitasEn":["i dont have a knife","i do not have a knife","i havent got a knife","i have no knife","ive got no knife"],"distratoresEn":["I don't have a fork.","I don't have a spoon.","I don't have a napkin.","I don't have a glass."],"nivel":"A1","tags":["comida","casa"],"notaEn":"After a negative, «un» becomes «de»: «je n'ai pas de couteau». The plural is «couteaux», with an «x».","requerTodas":["fr-p002","fr-p357"],"v":"7eadaf05"},{"idioma":"fr","id":"fr-u400","tipo":"frase","requer":"fr-p358","fr":"J'ai acheté une jupe noire.","en":"I bought a black skirt.","aceitasEn":["i bought a black skirt","ive bought a black skirt","i have bought a black skirt","i got a black skirt","ive got a black skirt"],"distratoresEn":["I bought a black blouse.","I bought a black bag.","I bought a black shirt.","I bought a black scarf."],"nivel":"A1","tags":["roupa","compras"],"notaEn":"«J'ai acheté» is the passé composé of «acheter», with «avoir». «Jupe» is feminine, so the color is «noire».","requerTodas":["fr-p002","fr-p075","fr-p358","fr-p345"],"v":"dc218e94"},{"idioma":"fr","id":"fr-u401","tipo":"frase","requer":"fr-p359","fr":"Il porte un chapeau.","en":"He's wearing a hat.","aceitasEn":["hes wearing a hat","he is wearing a hat","he wears a hat","hes got a hat on","he has a hat on","he has got a hat on"],"distratoresEn":["He's wearing a cap.","He's wearing a tie.","He's wearing a scarf.","He's wearing a suit."],"nivel":"A1","tags":["roupa"],"notaEn":"«Porter» means to wear: «il porte un chapeau». The plural is «chapeaux», with an «x».","requerTodas":["fr-p232","fr-p359"],"v":"2d98aa3c"},{"idioma":"fr","id":"fr-u402","tipo":"frase","requer":"fr-p360","fr":"J'ai mal à la jambe.","en":"My leg hurts.","aceitasEn":["my leg hurts","my leg is hurting","my leg aches","i have a pain in my leg","ive got a pain in my leg","i have a sore leg"],"distratoresEn":["My hand hurts.","My knee hurts.","My back hurts.","My hip hurts."],"nivel":"A1","tags":["corpo","saúde"],"notaEn":"Pain is «avoir mal à» + the body part, with «la», not «my»: «j'ai mal à la jambe». Ham, «le jambon», comes from the same word.","requerTodas":["fr-p002","fr-p151","fr-p360"],"v":"30e18600"},{"idioma":"fr","id":"fr-u403","tipo":"frase","requer":"fr-p361","fr":"Il a un grand nez.","en":"He has a big nose.","aceitasEn":["he has a big nose","hes got a big nose","he has got a big nose","he has a large nose","his nose is big"],"distratoresEn":["He has a big chin.","He has a big mouth.","He has a big forehead.","He has a big beard."],"nivel":"A1","tags":["corpo"],"notaEn":"«Grand» goes before the noun: «un grand nez». The «z» in «nez» is silent.","requerTodas":["fr-p002","fr-p037","fr-p361"],"v":"d2347706"},{"idioma":"fr","id":"fr-u404","tipo":"frase","requer":"fr-p362","fr":"J'ai mal aux dents.","en":"My teeth hurt.","aceitasEn":["my teeth hurt","i have a toothache","ive got a toothache","i have toothache","my tooth hurts","my teeth are hurting"],"distratoresEn":["My ears hurt.","My eyes hurt.","My knees hurt.","My shoulders hurt."],"nivel":"A1","tags":["corpo","saúde"],"notaEn":"«Aux» is «à» + «les»: «j'ai mal aux dents», literally I have pain at the teeth.","requerTodas":["fr-p002","fr-p151","fr-p362"],"v":"5bd82e62"},{"idioma":"fr","id":"fr-u405","tipo":"frase","requer":"fr-p363","fr":"Je dois aller à la banque.","en":"I have to go to the bank.","aceitasEn":["i have to go to the bank","i need to go to the bank","ive got to go to the bank","i have got to go to the bank","i must go to the bank","i gotta go to the bank"],"distratoresEn":["I have to go to the post office.","I have to go to the market.","I have to go to the doctor.","I have to go to the dentist."],"nivel":"A1","tags":["cidade","economia"],"notaEn":"«Devoir» + infinitive means to have to: «je dois aller». A bench is «un banc».","requerTodas":["fr-p082","fr-p003","fr-p363"],"v":"5689e7a1"},{"idioma":"fr","id":"fr-u406","tipo":"frase","requer":"fr-p364","fr":"Elle travaille à la bibliothèque.","en":"She works at the library.","aceitasEn":["she works at the library","she works in the library"],"distratoresEn":["She works at the bookstore.","She works at the pharmacy.","She works at the bakery.","She works at the school."],"nivel":"A1","tags":["cidade","cultura","trabalho"],"notaEn":"A library is «une bibliothèque»; a bookstore is «une librairie», a classic trap.","requerTodas":["fr-p017","fr-p364"],"v":"2832b2c2"},{"idioma":"fr","id":"fr-u407","tipo":"frase","requer":"fr-p364","fr":"Il y a une bibliothèque dans ma chambre.","en":"There's a bookcase in my bedroom.","aceitasEn":["theres a bookcase in my bedroom","there is a bookcase in my bedroom","theres a bookshelf in my bedroom","there is a bookshelf in my bedroom","theres a bookcase in my room","there is a bookcase in my room","theres a bookshelf in my room"],"distratoresEn":["There's a dresser in my bedroom.","There's a lamp in my bedroom.","There's a rug in my bedroom.","There's a TV in my bedroom."],"nivel":"A1","tags":["casa"],"notaEn":"At home, «une bibliothèque» is a bookcase. «Il y a» means there is.","requerTodas":["fr-p002","fr-p364","fr-p107"],"v":"da9f9f60"},{"idioma":"fr","id":"fr-u408","tipo":"frase","requer":"fr-p365","fr":"Comment aller à l'aéroport ?","en":"How do I get to the airport?","aceitasEn":["how do i get to the airport","how do you get to the airport","how can i get to the airport","how do we get to the airport","how do i go to the airport","whats the way to the airport"],"distratoresEn":["How do I get to the museum?","How do I get to the hotel?","How do I get to the port?","How do I get to the stadium?"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"«Comment aller à…?», with the infinitive and no subject, is the short way to ask for directions: how do I get to…?","requerTodas":["fr-p003","fr-p365"],"v":"7738930b"},{"idioma":"fr","id":"fr-u409","tipo":"frase","requer":"fr-p366","fr":"Le professeur parle trop vite.","en":"The teacher talks too fast.","aceitasEn":["the teacher talks too fast","the teacher speaks too fast","the teacher talks too quickly","the teacher speaks too quickly","the professor talks too fast","the professor speaks too fast"],"distratoresEn":["The principal talks too fast.","The doctor talks too fast.","The guide talks too fast.","The driver talks too fast."],"nivel":"A1","tags":["escola","profissões"],"notaEn":"«Trop vite», too fast: «trop» goes first. Informally, a teacher is «le prof».","requerTodas":["fr-p366","fr-p012","fr-p061","fr-p062"],"v":"0d7f5ed0"},{"idioma":"fr","id":"fr-u410","tipo":"frase","requer":"fr-p367","fr":"Je vais demander au serveur.","en":"I'm going to ask the waiter.","aceitasEn":["im going to ask the waiter","i am going to ask the waiter","ill ask the waiter","i will ask the waiter","im gonna ask the waiter","im going to ask the server","ill ask the server"],"distratoresEn":["I'm going to ask the manager.","I'm going to ask the cook.","I'm going to ask the doorman.","I'm going to ask the driver."],"nivel":"A1","tags":["comida","profissões"],"notaEn":"«Demander à» someone: «au serveur», the waiter. To call one over, just say «s'il vous plaît»; «garçon !» sounds old-fashioned.","requerTodas":["fr-p003","fr-p194","fr-p367"],"v":"7945c782"},{"idioma":"fr","id":"fr-u411","tipo":"frase","requer":"fr-p367","fr":"Le serveur ne marche pas.","en":"The server isn't working.","aceitasEn":["the server isnt working","the server is not working","the server doesnt work","the server does not work","the server is down","the servers down"],"distratoresEn":["The router isn't working.","The keyboard isn't working.","The monitor isn't working.","The charger isn't working."],"nivel":"A1","tags":["tecnologia"],"notaEn":"In computing, «le serveur» is the server. «Ne marche pas», isn't working: «marcher» means to walk and also to work.","requerTodas":["fr-p367","fr-p270"],"v":"3672a53b"},{"idioma":"fr","id":"fr-u412","tipo":"frase","requer":"fr-p368","fr":"Je veux parler à mon avocat.","en":"I want to talk to my lawyer.","aceitasEn":["i want to talk to my lawyer","i want to speak to my lawyer","i want to speak with my lawyer","i want to talk with my lawyer","i want to talk to my attorney","i want to speak to my attorney"],"distratoresEn":["I want to talk to my boss.","I want to talk to my doctor.","I want to talk to my accountant.","I want to talk to my manager."],"nivel":"A2","tags":["profissões"],"notaEn":"«Parler à», to talk to. «Mon avocat» is my lawyer; the same word means avocado.","requerTodas":["fr-p007","fr-p012","fr-p368"],"v":"31703695"},{"idioma":"fr","id":"fr-u413","tipo":"frase","requer":"fr-p368","fr":"Un sandwich à l'avocat, s'il vous plaît.","en":"An avocado sandwich, please.","aceitasEn":["an avocado sandwich please","one avocado sandwich please","can i have an avocado sandwich please","ill have an avocado sandwich please","i will have an avocado sandwich please"],"distratoresEn":["A tuna sandwich, please.","A ham sandwich, please.","A chicken sandwich, please.","An egg sandwich, please."],"nivel":"A2","tags":["comida"],"notaEn":"Sandwich fillings take «à»: «à l'avocat», «au fromage». The same word means lawyer; context decides.","requerTodas":["fr-p302","fr-p368"],"v":"6ef58cbc"},{"idioma":"fr","id":"fr-u414","tipo":"frase","requer":"fr-p369","fr":"Il fait mauvais aujourd'hui.","en":"The weather is bad today.","aceitasEn":["the weather is bad today","the weathers bad today","today the weather is bad","its bad weather today","the weather is awful today","the weather is not good today","the weather isnt good today"],"distratoresEn":["The weather is dry today.","The weather is muggy today.","The weather is cold today.","The weather is hot today."],"nivel":"A1","tags":["natureza"],"notaEn":"«Il fait mauvais», the weather's bad; the opposite is «il fait beau». Weather takes «il fait».","requerTodas":["fr-p004","fr-p369","fr-p049"],"v":"3f145389"},{"idioma":"fr","id":"fr-u415","tipo":"frase","requer":"fr-p369","fr":"On a pris le mauvais train !","en":"We took the wrong train!","aceitasEn":["we took the wrong train","weve taken the wrong train","we have taken the wrong train","we got on the wrong train","we got the wrong train"],"distratoresEn":["We took the slow train!","We took the empty train!","We took the night train!","We took the direct train!"],"nivel":"A1","tags":["viagem"],"notaEn":"Before a noun, «mauvais» means wrong: «le mauvais train», the wrong train; «le mauvais numéro», the wrong number.","requerTodas":["fr-p002","fr-p011","fr-p369","fr-p089"],"v":"5e1178a9"},{"idioma":"fr","id":"fr-u416","tipo":"frase","requer":"fr-p370","fr":"Le français, c'est difficile ?","en":"Is French hard?","aceitasEn":["is french hard","is french difficult","is french a hard language","is french a difficult language"],"distratoresEn":["Is French boring?","Is French useful?","Is French beautiful?","Is French easy?"],"nivel":"A1","tags":["escola"],"notaEn":"In speech, the topic comes first and «c'est» picks it up: «le français, c'est difficile ?». Languages take the article: «le français».","requerTodas":["fr-p054","fr-p001","fr-p370"],"v":"c1bf83bf"},{"idioma":"fr","id":"fr-u417","tipo":"frase","requer":"fr-p371","fr":"Pourquoi tu es triste ?","en":"Why are you sad?","aceitasEn":["why are you sad","why are you so sad","how come youre sad"],"distratoresEn":["Why are you angry?","Why are you tired?","Why are you nervous?","Why are you serious?"],"nivel":"A1","tags":["social"],"notaEn":"«Pourquoi», why, opens the question; in speech the word order stays as in a statement: «pourquoi tu es triste ?».","requerTodas":["fr-p001","fr-p371"],"v":"356ee367"},{"idioma":"fr","id":"fr-u418","tipo":"frase","requer":"fr-p372","fr":"Il est très drôle.","en":"He's very funny.","aceitasEn":["hes very funny","he is very funny","hes really funny","he is really funny","hes so funny"],"distratoresEn":["He's very boring.","He's very shy.","He's very serious.","He's very polite."],"nivel":"A1","tags":["social"],"notaEn":"«Drôle» means funny, same form for both genders. Followed by «de» and a noun, it means odd: «une drôle de question».","requerTodas":["fr-p001","fr-p043","fr-p372"],"v":"d023dff3"},{"idioma":"fr","id":"fr-u419","tipo":"frase","requer":"fr-p372","fr":"Quelle drôle de question !","en":"What a strange question!","aceitasEn":["what a strange question","what an odd question","what a weird question","what a funny question"],"distratoresEn":["What a difficult question!","What a good question!","What a long question!","What an easy question!"],"nivel":"A2","tags":["social","cotidiano"],"notaEn":"«Drôle de» + noun means strange: «quelle drôle de question !». Without the «de», «drôle» means funny.","requerTodas":["fr-p372","fr-p140"],"v":"73e85aaa"},{"idioma":"fr","id":"fr-u420","tipo":"frase","requer":"fr-p373","fr":"Je préfère rester à la maison.","en":"I'd rather stay home.","aceitasEn":["id rather stay home","i would rather stay home","id rather stay at home","i would rather stay at home","i prefer to stay home","i prefer to stay at home","i prefer staying home","i prefer staying at home"],"distratoresEn":["I need to stay home.","I hate staying home.","I can stay home.","I want to stay home."],"nivel":"A1","tags":["casa"],"notaEn":"«Préférer» takes a bare infinitive: «je préfère rester». The accent shifts: je préfère, nous préférons.","requerTodas":["fr-p373","fr-p269","fr-p020"],"v":"c3168ebb"},{"idioma":"fr","id":"fr-u421","tipo":"frase","requer":"fr-p374","fr":"Je l'appelle, mais il ne répond pas.","en":"I call him, but he doesn't answer.","aceitasEn":["i call him but he doesnt answer","i call him but he does not answer","im calling him but he isnt answering","im calling him but hes not answering","im calling him but he doesnt answer","i call him but he doesnt pick up","i keep calling him but he doesnt answer"],"distratoresEn":["I call him, but he doesn't listen.","I call him, but he doesn't hang up.","I call him, but he doesn't stop.","I call him, but he doesn't leave."],"nivel":"A1","tags":["tecnologia","social"],"notaEn":"«Répondre» is also to answer the phone. The «l'» is the object pronoun, before the verb: «je l'appelle», I call him.","requerTodas":["fr-p229","fr-p374"],"v":"30f60f2f"},{"idioma":"fr","id":"fr-u422","tipo":"frase","requer":"fr-p374","fr":"Réponds-moi !","en":"Answer me!","aceitasEn":["answer me","reply to me","respond to me"],"distratoresEn":["Help me!","Forgive me!","Hug me!","Look at me!"],"nivel":"A1","tags":["social"],"notaEn":"In a positive command, the pronoun follows with a hyphen and «me» becomes «moi»: «réponds-moi». In a negative one it moves back: «ne me réponds pas».","requerTodas":["fr-p374"],"v":"4d08f84e"},{"idioma":"fr","id":"fr-u423","tipo":"frase","requer":"fr-p374","fr":"Elle n'a pas répondu à ma question.","en":"She didn't answer my question.","aceitasEn":["she didnt answer my question","she did not answer my question","she hasnt answered my question","she has not answered my question","she didnt reply to my question"],"distratoresEn":["She didn't understand my question.","She didn't hear my question.","She didn't read my question.","She didn't repeat my question."],"nivel":"A1","tags":["escola","social"],"notaEn":"«Répondre à» something: «répondre à ma question», with «à» where English has a direct object. The participle is «répondu».","requerTodas":["fr-p002","fr-p374","fr-p140"],"v":"59504129"},{"idioma":"fr","id":"fr-u424","tipo":"frase","requer":"fr-p375","fr":"Tu sais conduire ?","en":"Can you drive?","aceitasEn":["can you drive","do you know how to drive"],"distratoresEn":["Can you swim?","Can you cook?","Can you sew?","Can you skate?"],"nivel":"A1","tags":["viagem"],"notaEn":"«Savoir» + infinitive is knowing how: «tu sais conduire ?», can you drive? A driver's license is «le permis de conduire».","requerTodas":["fr-p008","fr-p375"],"v":"7be90793"},{"idioma":"fr","id":"fr-u425","tipo":"frase","requer":"fr-p375","fr":"Il conduit trop vite.","en":"He drives too fast.","aceitasEn":["he drives too fast","he drives too quickly","hes driving too fast","he is driving too fast"],"distratoresEn":["He eats too fast.","He walks too fast.","He writes too fast.","He talks too fast."],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"«Conduire» is irregular: je conduis, il conduit, nous conduisons. «Trop vite», too fast.","requerTodas":["fr-p375","fr-p061","fr-p062"],"v":"227e39ed"},{"idioma":"fr","id":"fr-u426","tipo":"frase","requer":"fr-p376","fr":"Tu peux m'envoyer ton numéro ?","en":"Can you send me your number?","aceitasEn":["can you send me your number","could you send me your number","will you send me your number","can you text me your number"],"distratoresEn":["Can you tell me your number?","Can you give me your number?","Can you repeat your number?","Can you confirm your number?"],"nivel":"A1","tags":["tecnologia","social"],"notaEn":"«M'envoyer»: the pronoun goes before the infinitive. «Envoyer» means to send.","requerTodas":["fr-p006","fr-p376","fr-p215"],"v":"c1209117"},{"idioma":"fr","id":"fr-u427","tipo":"frase","requer":"fr-p377","fr":"C'est difficile de choisir.","en":"It's hard to choose.","aceitasEn":["its hard to choose","its difficult to choose","it is hard to choose","it is difficult to choose","its hard to pick"],"distratoresEn":["It's hard to wait.","It's hard to start.","It's hard to forget.","It's hard to understand."],"nivel":"A1","tags":["compras"],"notaEn":"«C'est difficile de» + infinitive: it's hard to do something. «Choisir» is a regular «-ir» verb like «finir».","requerTodas":["fr-p001","fr-p370","fr-p377"],"v":"61bd20bd"},{"idioma":"fr","id":"fr-u428","tipo":"frase","requer":"fr-p378","fr":"Mon mari cuisine très bien.","en":"My husband cooks very well.","aceitasEn":["my husband cooks very well","my husband cooks really well","my husband is a very good cook"],"distratoresEn":["My husband sings very well.","My husband dances very well.","My husband drives very well.","My husband draws very well."],"nivel":"A1","tags":["comida","família"],"notaEn":"«Cuisiner» means to cook; «faire la cuisine» says the same. «Très bien» comes after the verb.","requerTodas":["fr-p152","fr-p378","fr-p043","fr-p044"],"v":"8655ccca"},{"idioma":"fr","id":"fr-u429","tipo":"frase","requer":"fr-p379","fr":"Tu veux vraiment partir ?","en":"Do you really want to leave?","aceitasEn":["do you really want to leave","do you really want to go","you really want to leave","do you truly want to leave"],"distratoresEn":["Do you want to leave now?","Do you want to leave early?","Do you want to leave alone?","Do you still want to leave?"],"nivel":"A1","tags":["social"],"notaEn":"«Vraiment» goes right after the conjugated verb: «tu veux vraiment partir ?». It comes from «vrai», true.","requerTodas":["fr-p007","fr-p379","fr-p083"],"v":"ecbe5dae"},{"idioma":"fr","id":"fr-u430","tipo":"frase","requer":"fr-p380","fr":"Ensuite, tournez à droite.","en":"Then turn right.","aceitasEn":["then turn right","after that turn right","next turn right","then make a right","then take a right","afterwards turn right"],"distratoresEn":["Now turn right.","Here turn right.","There turn right.","First turn right."],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"«Ensuite» links steps: then, next. Directions use «tournez», the «vous» form.","requerTodas":["fr-p380","fr-p313","fr-p314"],"v":"75b72fef"},{"idioma":"fr","id":"fr-u431","tipo":"frase","requer":"fr-p381","fr":"D'abord on mange, ensuite on va au cinéma.","en":"First we eat, then we go to the movies.","aceitasEn":["first we eat then we go to the movies","first we eat and then we go to the movies","first we eat and then go to the movies","first we eat then we go to the cinema","first well eat then well go to the movies","first we will eat then we will go to the movies"],"distratoresEn":["Now we eat, then we go to the movies.","Here we eat, then we go to the movies.","There we eat, then we go to the movies.","Today we eat, then we go to the movies."],"nivel":"A1","tags":["cotidiano","cultura"],"notaEn":"«D'abord… ensuite…», first… then…: the standard way to sequence. «On» is the everyday «we», with a third-person verb.","requerTodas":["fr-p381","fr-p013","fr-p380","fr-p003","fr-p097"],"v":"8aa2e542"},{"idioma":"fr","id":"fr-u432","tipo":"frase","requer":"fr-p381","fr":"D'abord, je n'ai pas compris.","en":"At first I didn't understand.","aceitasEn":["at first i didnt understand","at first i did not understand","at first i didnt get it","in the beginning i didnt understand","at the beginning i didnt understand","at first i didnt understand it"],"distratoresEn":["In the end I didn't understand.","Afterwards I didn't understand.","Yesterday I didn't understand.","Here I didn't understand."],"nivel":"A1","tags":["escola"],"notaEn":"«D'abord» also means at first: «d'abord, je n'ai pas compris». The participle of «comprendre» is «compris».","requerTodas":["fr-p381","fr-p002","fr-p110"],"v":"dca729d6"},{"idioma":"fr","id":"fr-u433","tipo":"frase","requer":"fr-p382","fr":"J'ai presque fini.","en":"I'm almost done.","aceitasEn":["im almost done","i am almost done","im almost finished","ive almost finished","i have almost finished","im nearly done","im nearly finished","ive nearly finished","i almost finished"],"distratoresEn":["I'm also done.","I'm finally done.","I'm already done.","I'm not done yet."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Presque» sits between the auxiliary and the participle: «j'ai presque fini». Without it, «j'ai fini», I'm done.","requerTodas":["fr-p002","fr-p382","fr-p123"],"v":"631f8db6"},{"idioma":"fr","id":"fr-u434","tipo":"frase","requer":"fr-p383","fr":"Il y a du soleil aujourd'hui.","en":"It's sunny today.","aceitasEn":["its sunny today","it is sunny today","today its sunny","the sun is out today","the suns out today"],"distratoresEn":["It's cold today.","It's hot today.","It's foggy today.","It's muggy today."],"nivel":"A1","tags":["natureza"],"notaEn":"Sunny is «il y a du soleil», literally there's some sun. Nice weather in general is «il fait beau».","requerTodas":["fr-p002","fr-p383","fr-p049"],"v":"950b91e8"},{"idioma":"fr","id":"fr-u435","tipo":"frase","requer":"fr-p384","fr":"Il y a beaucoup de neige cette année.","en":"There's a lot of snow this year.","aceitasEn":["theres a lot of snow this year","there is a lot of snow this year","theres lots of snow this year","there is lots of snow this year","weve had a lot of snow this year","there has been a lot of snow this year"],"distratoresEn":["There's a lot of rain this year.","There's a lot of frost this year.","There's a lot of fog this year.","There's a lot of humidity this year."],"nivel":"A1","tags":["natureza"],"notaEn":"«Beaucoup de» + noun, no article: «beaucoup de neige». To snow is «neiger»: «il neige».","requerTodas":["fr-p002","fr-p067","fr-p384","fr-p031"],"v":"5c2ae479"},{"idioma":"fr","id":"fr-u436","tipo":"frase","requer":"fr-p301","fr":"J'essaie de dormir.","aceitasFr":["J'essaye de dormir."],"en":"I'm trying to sleep.","aceitasEn":["im trying to sleep","i am trying to sleep","im trying to get some sleep","i try to sleep"],"distratoresEn":["I'm going to sleep.","I want to sleep.","I'm about to sleep.","I'm going back to sleep."],"nivel":"A1","tags":["casa","saúde"],"notaEn":"«Essayer de» + infinitive means to try to: «j'essaie de dormir». The «y» turns to «i» before a silent ending, though «j'essaye» is also correct.","requerTodas":["fr-p301","fr-p109"],"v":"4c287e52"},{"idioma":"fr","id":"fr-u437","tipo":"frase","requer":"fr-p303","fr":"Il fait frais ce soir.","en":"It's chilly tonight.","aceitasEn":["its chilly tonight","it is chilly tonight","its cool tonight","it is cool tonight","its a bit chilly tonight","its a little chilly tonight"],"distratoresEn":["It's hot tonight.","It's muggy tonight.","It's freezing tonight.","It's windy tonight."],"nivel":"A1","tags":["natureza"],"notaEn":"«Il fait frais», it's cool, a bit chilly: not quite cold. «Ce soir» means tonight.","requerTodas":["fr-p004","fr-p303","fr-p160"],"v":"18dffba5"},{"idioma":"fr","id":"fr-u438","tipo":"frase","requer":"fr-p306","fr":"J'ai un seul frère.","en":"I have only one brother.","aceitasEn":["i have only one brother","i only have one brother","ive only got one brother","i have just one brother","i just have one brother"],"distratoresEn":["I have an older brother.","I have a twin brother.","I have a younger brother.","I have a married brother."],"nivel":"A1","tags":["família"],"notaEn":"Before a noun, «seul» means only one: «un seul frère». After a verb it means alone: «je vis seul».","requerTodas":["fr-p002","fr-p306","fr-p078"],"v":"2a66ba66"},{"idioma":"fr","id":"fr-u439","tipo":"frase","requer":"fr-p307","fr":"Je suis allé deux fois à Paris.","aceitasFr":["Je suis allée deux fois à Paris."],"en":"I've been to Paris twice.","aceitasEn":["ive been to paris twice","i have been to paris twice","i went to paris twice","ive been twice to paris","i went twice to paris","ive been to paris two times","i went to paris two times"],"distratoresEn":["I've been to Paris three times.","I've been to Paris many times.","I've been to Paris once.","I've been to Paris several times."],"nivel":"A1","tags":["viagem"],"notaEn":"Counting occurrences uses «la fois»: «une fois», once; «deux fois», twice. «Aller» takes «être» in the passé composé: «je suis allé».","requerTodas":["fr-p001","fr-p003","fr-p120","fr-p307"],"v":"e0bc7dc8"},{"idioma":"fr","id":"fr-u440","tipo":"frase","requer":"fr-p308","fr":"Elle est amoureuse de son voisin.","en":"She's in love with her neighbor.","aceitasEn":["shes in love with her neighbor","she is in love with her neighbor","shes in love with her neighbour","she is in love with her neighbour","shes in love with the neighbor"],"distratoresEn":["She's angry with her neighbor.","She's worried about her neighbor.","She's upset with her neighbor.","She's jealous of her neighbor."],"nivel":"A1","tags":["social"],"notaEn":"«Amoureux de», in love with: «de», not «avec». The feminine is «amoureuse».","requerTodas":["fr-p001","fr-p308","fr-p072"],"v":"24ab134e"},{"idioma":"fr","id":"fr-u441","tipo":"frase","requer":"fr-p309","fr":"Je fais ma valise.","en":"I'm packing my suitcase.","aceitasEn":["im packing my suitcase","i am packing my suitcase","im packing","im packing my bag","im packing my case"],"distratoresEn":["I'm making my bed.","I'm making my dinner.","I'm doing my cleaning.","I'm doing my homework."],"nivel":"A1","tags":["viagem"],"notaEn":"To pack is «faire sa valise», literally to make one's suitcase: «je fais ma valise».","requerTodas":["fr-p004","fr-p309"],"v":"f7a278fb"},{"idioma":"fr","id":"fr-u442","tipo":"frase","requer":"fr-p310","fr":"J'ai oublié mes lunettes de soleil.","en":"I forgot my sunglasses.","aceitasEn":["i forgot my sunglasses","ive forgotten my sunglasses","i have forgotten my sunglasses","i left my sunglasses","i forgot my shades"],"distratoresEn":["I forgot my swimming goggles.","I forgot my headphones.","I forgot my beach shoes.","I forgot my travel documents."],"nivel":"A1","tags":["viagem","objetos"],"notaEn":"Sunglasses are «les lunettes de soleil», always plural. «Oublier», to forget, gives «j'ai oublié».","requerTodas":["fr-p002","fr-p197","fr-p310","fr-p383"],"v":"f4292299"},{"idioma":"fr","id":"fr-u443","tipo":"frase","requer":"fr-p311","fr":"On regarde le match ce soir ?","en":"Shall we watch the game tonight?","aceitasEn":["shall we watch the game tonight","should we watch the game tonight","do you want to watch the game tonight","want to watch the game tonight","are we watching the game tonight","lets watch the game tonight","shall we watch the match tonight"],"distratoresEn":["Shall we watch the concert tonight?","Shall we watch the parade tonight?","Shall we watch the news tonight?","Shall we watch the show tonight?"],"nivel":"A1","tags":["cultura"],"notaEn":"«On regarde…?» with rising intonation is a suggestion: shall we watch…? «Le match» is the game.","requerTodas":["fr-p172","fr-p311","fr-p160"],"v":"dac21d51"},{"idioma":"fr","id":"fr-u444","tipo":"frase","requer":"fr-p312","fr":"Ce restaurant est bon marché.","en":"This restaurant is cheap.","aceitasEn":["this restaurant is cheap","that restaurant is cheap","this restaurant is inexpensive","this restaurant is affordable"],"distratoresEn":["This restaurant is good.","This restaurant is expensive.","This restaurant is famous.","This restaurant is new."],"nivel":"A1","tags":["comida","compras"],"notaEn":"«Bon marché» means cheap and never changes form: «des chaussures bon marché». It's about price, not quality.","requerTodas":["fr-p098","fr-p001","fr-p036","fr-p312"],"v":"a415d984"},{"idioma":"fr","id":"fr-u445","tipo":"frase","requer":"fr-p313","fr":"Ils tournent un film dans ma rue.","en":"They're shooting a movie on my street.","aceitasEn":["theyre shooting a movie on my street","they are shooting a movie on my street","theyre filming a movie on my street","they are filming a movie on my street","theyre making a movie on my street","theyre shooting a film on my street"],"distratoresEn":["They're showing a movie on my street.","They're watching a movie on my street.","They're advertising a movie on my street.","They're selling a movie on my street."],"nivel":"A2","tags":["cultura","cidade"],"notaEn":"«Tourner un film» means to shoot a movie. In directions, the same verb means to turn: «tournez à gauche».","requerTodas":["fr-p313","fr-p100","fr-p032"],"v":"cbfa4cc9"},{"idioma":"fr","id":"fr-u446","tipo":"frase","requer":"fr-p315","fr":"On descend à pied ?","en":"Shall we walk down?","aceitasEn":["shall we walk down","should we walk down","lets walk down","shall we take the stairs down","shall we take the stairs","should we take the stairs","shall we go down on foot"],"distratoresEn":["Shall we walk up?","Shall we walk back?","Shall we walk across?","Shall we walk around?"],"nivel":"A1","tags":["casa","cidade"],"notaEn":"«Descendre», to go down, works for stairs and for getting off a bus. «À pied», on foot: by the stairs, not the elevator.","requerTodas":["fr-p315","fr-p158"],"v":"e1f251b0"},{"idioma":"fr","id":"fr-u447","tipo":"frase","requer":"fr-p316","fr":"Où est l'arrêt de bus ?","en":"Where's the bus stop?","aceitasEn":["wheres the bus stop","where is the bus stop","where can i find the bus stop"],"distratoresEn":["Where's the bus terminal?","Where's the bus ticket office?","Where's the bus station?","Where's the bus lane?"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"A bus stop is «l'arrêt de bus»; «arrêt» is masculine and comes from «arrêter», to stop.","requerTodas":["fr-p001","fr-p316","fr-p060"],"v":"f075463b"},{"idioma":"fr","id":"fr-u448","tipo":"frase","requer":"fr-p318","fr":"Tu parles mieux que moi.","en":"You speak better than I do.","aceitasEn":["you speak better than i do","you speak better than me","you speak better than i","you talk better than me","you talk better than i do"],"distratoresEn":["You speak worse than I do.","You speak more than I do.","You speak less than I do.","You speak faster than I do."],"nivel":"A1","tags":["escola"],"notaEn":"«Mieux» goes with verbs: «tu parles mieux que moi». With nouns it's «meilleur». After «que» it's «moi», not «je».","requerTodas":["fr-p012","fr-p318"],"v":"d6a744ab"},{"idioma":"fr","id":"fr-u449","tipo":"frase","requer":"fr-p318","fr":"Ça va mieux ?","en":"Are you feeling better?","aceitasEn":["are you feeling better","are you better","feeling better","do you feel better","are things better","is it any better"],"distratoresEn":["Are you feeling worse?","Are you feeling well?","Are you feeling tired?","Are you feeling sad?"],"nivel":"A1","tags":["saúde"],"notaEn":"«Ça va mieux ?» asks if someone is feeling better, literally does it go better?","requerTodas":["fr-p003","fr-p318"],"v":"fc35032a"},{"idioma":"fr","id":"fr-u450","tipo":"frase","requer":"fr-p319","fr":"Bon week-end !","en":"Have a nice weekend!","aceitasEn":["have a nice weekend","have a good weekend","have a great weekend","enjoy your weekend","enjoy the weekend"],"distratoresEn":["Have a nice New Year!","Have a nice evening!","Have a nice start to the week!","Have a nice long holiday!"],"nivel":"A1","tags":["social","cotidiano"],"notaEn":"«Bon week-end !» is the Friday goodbye. In Quebec it's «la fin de semaine».","requerTodas":["fr-p036","fr-p319"],"v":"f7fa75a5"},{"idioma":"fr","id":"fr-u451","tipo":"frase","requer":"fr-p321","fr":"La vie coûte cher à Paris.","en":"Life is expensive in Paris.","aceitasEn":["life is expensive in paris","life in paris is expensive","living in paris is expensive","paris is expensive to live in","the cost of living is high in paris"],"distratoresEn":["Life is cheap in Paris.","Life is hectic in Paris.","Life is calm in Paris.","Life is fun in Paris."],"nivel":"A1","tags":["compras","economia","cidade"],"notaEn":"«Coûter cher», to be expensive, literally to cost dear: «cher» doesn't agree here. Likewise «ça coûte cher», it's expensive.","requerTodas":["fr-p250","fr-p321","fr-p199"],"v":"de7cc65d"},{"idioma":"fr","id":"fr-u452","tipo":"frase","requer":"fr-p322","fr":"C'est compris ?","en":"Got it?","aceitasEn":["got it","understood","is that clear","is that understood","do you understand","you got it"],"distratoresEn":["Agreed?","Solved?","Finished?","Forbidden?"],"nivel":"A1","tags":["escola","cotidiano"],"notaEn":"«Compris», past participle of «comprendre», means understood: «c'est compris ?», got it? The answer is the same word: «compris !».","requerTodas":["fr-p001","fr-p322"],"v":"98203eaf"},{"idioma":"fr","id":"fr-u453","tipo":"frase","requer":"fr-p322","fr":"Le vin n'est pas compris.","en":"The wine isn't included.","aceitasEn":["the wine isnt included","the wine is not included","the wines not included","wine isnt included","the wine is extra"],"distratoresEn":["The wine isn't chilled.","The wine isn't open.","The wine isn't good.","The wine isn't paid for."],"nivel":"A1","tags":["comida","compras"],"notaEn":"On a bill, «compris» means included: «le vin n'est pas compris». «Service compris», service included.","requerTodas":["fr-p093","fr-p001","fr-p322"],"v":"801003f3"},{"idioma":"fr","id":"fr-u454","tipo":"frase","requer":"fr-p323","fr":"Tu perds ton temps.","en":"You're wasting your time.","aceitasEn":["youre wasting your time","you are wasting your time","youre wasting time","you are wasting time","you waste your time"],"distratoresEn":["You're saving your time.","You're enjoying your time.","You're organizing your time.","You're counting your time."],"nivel":"A1","tags":["cotidiano"],"notaEn":"To waste time is «perdre son temps», literally to lose one's time: «tu perds ton temps».","requerTodas":["fr-p323","fr-p025"],"v":"8c20bf8b"},{"idioma":"fr","id":"fr-u455","tipo":"frase","requer":"fr-p327","fr":"C'est un ami proche.","en":"He's a close friend.","aceitasEn":["hes a close friend","he is a close friend","its a close friend","thats a close friend"],"distratoresEn":["He's an old friend.","He's a distant friend.","He's a new friend.","He's a rich friend."],"nivel":"A1","tags":["social"],"notaEn":"«Proche» means close, in space or in friendship: «un ami proche». Next is «prochain».","requerTodas":["fr-p001","fr-p024","fr-p327"],"v":"e07fdb38"},{"idioma":"fr","id":"fr-u456","tipo":"frase","requer":"fr-p328","fr":"Rappelle-moi d'acheter du pain.","en":"Remind me to buy bread.","aceitasEn":["remind me to buy bread","remind me to buy some bread","remind me to get bread","remind me to get some bread"],"distratoresEn":["Help me buy bread.","Let me buy bread.","Tell me to buy bread.","Ask me to buy bread."],"nivel":"A2","tags":["compras"],"notaEn":"«Rappeler» also means to remind: «rappelle-moi de…», remind me to… To remember is «se rappeler» or «se souvenir».","requerTodas":["fr-p328","fr-p075","fr-p027"],"v":"c80c62ba"},{"idioma":"fr","id":"fr-u457","tipo":"frase","requer":"fr-p329","fr":"Je vais te montrer la maison.","en":"I'll show you the house.","aceitasEn":["ill show you the house","i will show you the house","im going to show you the house","i am going to show you the house","let me show you the house","ill show you around the house"],"distratoresEn":["I'll sell you the house.","I'll rent you the house.","I'll describe the house to you.","I'll lend you the house."],"nivel":"A1","tags":["casa"],"notaEn":"«Montrer», to show, takes the pronoun before it: «je vais te montrer». Don't mix it up with «monter», to go up.","requerTodas":["fr-p003","fr-p329","fr-p020"],"v":"0a34e451"},{"idioma":"fr","id":"fr-u458","tipo":"frase","requer":"fr-p330","fr":"J'attends depuis une demi-heure.","en":"I've been waiting for half an hour.","aceitasEn":["ive been waiting for half an hour","i have been waiting for half an hour","ive been waiting half an hour","i have been waiting half an hour","ive been waiting for thirty minutes"],"distratoresEn":["I've been waiting for an hour.","I've been waiting for two hours.","I've been waiting for a quarter of an hour.","I've been waiting for ten minutes."],"nivel":"A1","tags":["cotidiano"],"notaEn":"Before a noun, «demi» is invariable and hyphenated: «une demi-heure». «Depuis» + duration takes the present: «j'attends depuis…», I've been waiting for…","requerTodas":["fr-p018","fr-p330","fr-p129"],"v":"9e7f8c2f"},{"idioma":"fr","id":"fr-u459","tipo":"frase","requer":"fr-p331","fr":"La valise est pleine.","en":"The suitcase is full.","aceitasEn":["the suitcase is full","the suitcases full","the case is full","my suitcase is full"],"distratoresEn":["The suitcase is empty.","The suitcase is open.","The suitcase is heavy.","The suitcase is closed."],"nivel":"A1","tags":["viagem"],"notaEn":"In the feminine, «plein» becomes «pleine»: «la valise est pleine». The opposite is «vide».","requerTodas":["fr-p309","fr-p001","fr-p331"],"v":"2fd4c9cb"},{"idioma":"fr","id":"fr-u460","tipo":"frase","requer":"fr-p333","fr":"C'est un petit restaurant sympa.","en":"It's a nice little restaurant.","aceitasEn":["its a nice little restaurant","it is a nice little restaurant","its a nice small restaurant","its a cute little restaurant","its a lovely little restaurant","its a cozy little restaurant"],"distratoresEn":["It's an expensive little restaurant.","It's a noisy little restaurant.","It's a famous little restaurant.","It's an empty little restaurant."],"nivel":"A1","tags":["comida","cidade"],"notaEn":"«Sympa» also describes places: «un petit restaurant sympa». Short «petit» goes before the noun, «sympa» after.","requerTodas":["fr-p001","fr-p038","fr-p098","fr-p333"],"v":"01b550fa"},{"idioma":"fr","id":"fr-u461","tipo":"frase","requer":"fr-p334","fr":"Bon anniversaire !","aceitasFr":["Joyeux anniversaire !"],"en":"Happy birthday!","aceitasEn":["happy birthday","happy anniversary"],"distratoresEn":["Merry Christmas!","Happy Easter!","Have a good trip!","Happy holiday!"],"nivel":"A1","tags":["social","família"],"notaEn":"«Bon anniversaire !» or «joyeux anniversaire !», happy birthday. A wedding anniversary is «l'anniversaire de mariage».","requerTodas":["fr-p036","fr-p334"],"v":"063d6b9e"},{"idioma":"fr","id":"fr-u462","tipo":"frase","requer":"fr-p335","fr":"On a loué une voiture.","en":"We rented a car.","aceitasEn":["we rented a car","weve rented a car","we have rented a car","we hired a car"],"distratoresEn":["We washed a car.","We bought a car.","We sold a car.","We fixed a car."],"nivel":"A2","tags":["viagem"],"notaEn":"«Louer» means to rent, both ways: renting and renting out. Don't confuse it with «laver», to wash.","requerTodas":["fr-p002","fr-p335","fr-p034"],"v":"b0ee85cb"},{"idioma":"fr","id":"fr-u463","tipo":"frase","requer":"fr-p337","fr":"J'ai un rendez-vous ce soir.","en":"I have a date tonight.","aceitasEn":["i have a date tonight","ive got a date tonight","i have got a date tonight","im going on a date tonight","i have an appointment tonight"],"distratoresEn":["I have a dinner tonight.","I have a party tonight.","I have a shift tonight.","I have a class tonight."],"nivel":"A1","tags":["social"],"notaEn":"«Un rendez-vous» is a date or an appointment: «j'ai rendez-vous chez le médecin», I have a doctor's appointment.","requerTodas":["fr-p002","fr-p337","fr-p160"],"v":"72009133"},{"idioma":"fr","id":"fr-u464","tipo":"frase","requer":"fr-p304","fr":"Dimanche, je ne fais rien.","en":"On Sunday I'm not doing anything.","aceitasEn":["on sunday im not doing anything","im not doing anything on sunday","on sunday im doing nothing","im doing nothing on sunday","on sunday i dont do anything","on sunday i am not doing anything"],"distratoresEn":["On Saturday I'm not doing anything.","On Monday I'm not doing anything.","On Friday I'm not doing anything.","On Thursday I'm not doing anything."],"nivel":"A1","tags":["cotidiano"],"notaEn":"Without the article, «dimanche» is this Sunday. «Ne… rien», nothing, wraps the verb: «je ne fais rien».","requerTodas":["fr-p304","fr-p004"],"v":"37e9c23c"},{"idioma":"fr","id":"fr-u465","tipo":"frase","requer":"fr-p110","fr":"Je n'ai rien compris.","en":"I didn't understand anything.","aceitasEn":["i didnt understand anything","i did not understand anything","i didnt understand a thing","i understood nothing","i havent understood anything","i didnt get anything"],"distratoresEn":["I didn't see anything.","I didn't hear anything.","I didn't eat anything.","I didn't read anything."],"nivel":"A1","tags":["escola"],"notaEn":"In the passé composé, «rien» goes before the participle: «je n'ai rien compris».","requerTodas":["fr-p002","fr-p110"],"v":"464fe2a8"},{"idioma":"fr","id":"fr-u466","tipo":"frase","requer":"fr-p086","fr":"Je n'ai pas faim.","en":"I'm not hungry.","aceitasEn":["im not hungry","i am not hungry"],"distratoresEn":["I'm not sleepy.","I'm not cold.","I'm not in a hurry.","I'm not thirsty."],"nivel":"A1","tags":["comida"],"notaEn":"French has hunger rather than being hungry: «avoir faim». Negative: «je n'ai pas faim».","requerTodas":["fr-p002","fr-p086"],"v":"63db0557"},{"idioma":"fr","id":"fr-u467","tipo":"frase","requer":"fr-p238","fr":"Le prochain bus est dans vingt minutes.","en":"The next bus is in twenty minutes.","aceitasEn":["the next bus is in twenty minutes","the next bus comes in twenty minutes","the next bus leaves in twenty minutes","the next bus arrives in twenty minutes"],"distratoresEn":["The last bus is in twenty minutes.","The first bus is in twenty minutes.","The second bus is in twenty minutes.","The other bus is in twenty minutes."],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"«Prochain» goes before the noun: «le prochain bus». «Dans» + time means in: «dans vingt minutes».","requerTodas":["fr-p238","fr-p060","fr-p001","fr-p051","fr-p139"],"v":"9e2d6464"},{"idioma":"fr","id":"fr-u468","tipo":"frase","requer":"fr-p321","fr":"Ça ne coûte rien.","en":"It doesn't cost anything.","aceitasEn":["it doesnt cost anything","it does not cost anything","it costs nothing","it doesnt cost a thing","its free","it is free"],"distratoresEn":["It isn't worth anything.","It doesn't weigh anything.","It doesn't change anything.","It doesn't mean anything."],"nivel":"A1","tags":["compras"],"notaEn":"«Ne… rien» + «coûter»: it costs nothing. Free is also «gratuit».","requerTodas":["fr-p321"],"v":"15961bee"},{"idioma":"fr","id":"fr-u469","tipo":"frase","requer":"fr-p107","fr":"Vous avez une chambre pour ce soir ?","en":"Do you have a room for tonight?","aceitasEn":["do you have a room for tonight","do you have any rooms for tonight","have you got a room for tonight","is there a room for tonight","do you have a room available tonight"],"distratoresEn":["Do you have a seat for tonight?","Do you have a ticket for tonight?","Do you have a flight for tonight?","Do you have a slot for tonight?"],"nivel":"A1","tags":["viagem"],"notaEn":"At a hotel, «une chambre» is a room. «Vous avez…?», do you have…?, is how you ask.","requerTodas":["fr-p002","fr-p107","fr-p160"],"v":"35e9444c"},{"idioma":"fr","id":"fr-u470","tipo":"frase","requer":"fr-p295","fr":"Ma sœur est plus jeune que moi.","en":"My sister is younger than me.","aceitasEn":["my sister is younger than me","my sister is younger than i am","my sister is younger than i"],"distratoresEn":["My sister is older than me.","My sister is taller than me.","My sister is shorter than me.","My sister is thinner than me."],"nivel":"A1","tags":["família"],"notaEn":"Comparatives: «plus» + adjective + «que»: «plus jeune que moi». After «que», it's «moi», not «je».","requerTodas":["fr-p104","fr-p001","fr-p295"],"v":"47e983ba"},{"idioma":"fr","id":"fr-u471","tipo":"frase","requer":"fr-p061","fr":"Il fait trop chaud pour sortir.","en":"It's too hot to go out.","aceitasEn":["its too hot to go out","it is too hot to go out","its too hot to go outside","it is too hot to go outside"],"distratoresEn":["It's too cold to go out.","It's too late to go out.","It's too dark to go out.","It's too early to go out."],"nivel":"A1","tags":["natureza","cotidiano"],"notaEn":"«Trop… pour» + infinitive: too… to. Weather heat takes «il fait»: «il fait trop chaud».","requerTodas":["fr-p004","fr-p061","fr-p112","fr-p108"],"v":"04ec4357"},{"idioma":"fr","id":"fr-u472","tipo":"frase","requer":"fr-p282","fr":"Je n'aime pas le poisson.","en":"I don't like fish.","aceitasEn":["i dont like fish","i do not like fish","i dont like eating fish"],"distratoresEn":["I don't like chicken.","I don't like cheese.","I don't like meat.","I don't like eggs."],"nivel":"A1","tags":["comida"],"notaEn":"With «aimer», the article stays even in the negative: «je n'aime pas le poisson», I don't like fish.","requerTodas":["fr-p015","fr-p282"],"v":"a1f41e3e"},{"idioma":"fr","id":"fr-u473","tipo":"frase","requer":"fr-p275","fr":"Ferme les yeux !","en":"Close your eyes!","aceitasEn":["close your eyes","shut your eyes"],"distratoresEn":["Close your fists!","Close your books!","Close your lips!","Close your hands!"],"nivel":"A1","tags":["corpo"],"notaEn":"«Les yeux» is the irregular plural of «l'œil». With body parts, French uses «les», not «your»: «ferme les yeux».","requerTodas":["fr-p206","fr-p275"],"v":"6d3d7252"},{"idioma":"fr","id":"fr-v107","tipo":"frase","fr":"Mes enfants préfèrent la plage.","en":"My kids prefer the beach.","aceitasEn":["my kids prefer the beach","my children prefer the beach"],"distratoresEn":["My kids used to prefer the beach.","My kids preferred the beach.","My kids will prefer the beach.","My kids would prefer the beach."],"formasFr":{"Mes enfants préféraient la plage":"imperfect","Mes enfants ont préféré la plage":"passé composé","Mes enfants préféreront la plage":"future","Mes enfants préféreraient la plage":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","família"],"notaEn":"The accent shifts: «è» before a silent ending (je préfère, ils préfèrent), «é» in «nous préférons» and «vous préférez».","requerTodas":["fr-p023","fr-p373","fr-p087"],"v":"b7669bca"},{"idioma":"fr","id":"fr-v108","tipo":"frase","fr":"J'ai répondu à sa lettre.","en":"I answered his letter.","aceitasEn":["i answered his letter","i answered her letter","i replied to his letter","i replied to her letter","ive answered his letter","ive answered her letter"],"distratoresEn":["I'm answering his letter.","I'll answer his letter.","I would answer his letter.","I had answered his letter."],"formasFr":{"Je réponds à sa lettre":"present","Je répondrai à sa lettre":"future","Je répondrais à sa lettre":"conditional","J'avais répondu à sa lettre":"pluperfect"},"nivel":"A1","tags":["conjugação","pretérito","regular","social"],"notaEn":"«-re» verbs form the participle in «-u»: répondre → «répondu», like attendre → «attendu». «Répondre» takes «à».","requerTodas":["fr-p002","fr-p374","fr-p138"],"v":"52ccaa93"},{"idioma":"fr","id":"fr-v109","tipo":"frase","fr":"Je conduis tous les jours.","en":"I drive every day.","aceitasEn":["i drive every day","i drive everyday"],"distratoresEn":["I used to drive every day.","I drove every day.","I'll drive every day.","I would drive every day."],"formasFr":{"Je conduisais tous les jours":"imperfect","J'ai conduit tous les jours":"passé composé","Je conduirai tous les jours":"future","Je conduirais tous les jours":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","viagem"],"notaEn":"In the singular, «conduire» drops the «re»: je conduis, il conduit. The plural adds an «s»: nous conduisons, ils conduisent.","requerTodas":["fr-p375","fr-p070","fr-p019"],"v":"9ab60164"},{"idioma":"fr","id":"fr-v110","tipo":"frase","fr":"Je t'enverrai une lettre.","en":"I'll send you a letter.","aceitasEn":["ill send you a letter","i will send you a letter","im going to send you a letter","i am going to send you a letter"],"distratoresEn":["I was sending you a letter.","I sent you a letter.","I would send you a letter.","I had sent you a letter."],"formasFr":{"Je t'envoyais une lettre":"imperfect","Je t'ai envoyé une lettre":"passé composé","Je t'enverrais une lettre":"conditional","Je t'avais envoyé une lettre":"pluperfect"},"nivel":"A1","tags":["conjugação","futuro","irregular","social"],"notaEn":"«Envoyer» has an irregular future: «j'enverrai», like «je verrai» from «voir». The conditional shares the stem: «j'enverrais».","requerTodas":["fr-p376","fr-p138"],"v":"fa1c63c8"},{"idioma":"fr","id":"fr-v111","tipo":"frase","fr":"Les enfants choisissent le film.","en":"The children choose the movie.","aceitasEn":["the children choose the movie","the kids choose the movie","the kids pick the movie","the children pick the movie","the kids choose the film"],"distratoresEn":["The children used to choose the movie.","The children chose the movie.","The children will choose the movie.","The children would choose the movie."],"formasFr":{"Les enfants choisissaient le film":"imperfect","Les enfants ont choisi le film":"passé composé","Les enfants choisiront le film":"future","Les enfants choisiraient le film":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular","família"],"notaEn":"Verbs like «finir» add «-iss-» in the plural: nous choisissons, ils choisissent. The singular is just «-is», «-it»: je choisis, il choisit.","requerTodas":["fr-p023","fr-p377","fr-p100"],"v":"12f8e387"},{"idioma":"fr","id":"fr-v112","tipo":"frase","fr":"Ma grand-mère cuisinait tous les dimanches.","en":"My grandmother used to cook every Sunday.","aceitasEn":["my grandmother used to cook every sunday","my grandma used to cook every sunday","my grandmother cooked every sunday","my grandma cooked every sunday","my grandmother would cook every sunday","my grandma would cook every sunday"],"distratoresEn":["My grandmother cooks every Sunday.","My grandmother is going to cook every Sunday.","My grandmother will cook every Sunday.","My grandmother had cooked every Sunday."],"formasFr":{"Ma grand-mère cuisine tous les dimanches":"present","Ma grand-mère va cuisiner tous les dimanches":"near future","Ma grand-mère cuisinera tous les dimanches":"future","Ma grand-mère avait cuisiné tous les dimanches":"pluperfect"},"nivel":"A1","tags":["conjugação","imperfeito","regular","família","comida"],"notaEn":"The imperfect tells a habit, and «tous les dimanches», every Sunday, is the clue. Stem of the present «nous» form, «cuisin-», + «-ait».","requerTodas":["fr-p136","fr-p378","fr-p070","fr-p304"],"v":"f69304cc"},{"idioma":"fr","id":"fr-v113","tipo":"frase","fr":"Ils essaient de comprendre.","aceitasFr":["Ils essayent de comprendre."],"en":"They're trying to understand.","aceitasEn":["theyre trying to understand","they are trying to understand","they try to understand"],"distratoresEn":["They were trying to understand.","They tried to understand.","They'll try to understand.","They would try to understand."],"formasFr":{"Ils essayaient de comprendre":"imperfect","Ils ont essayé de comprendre":"passé composé","Ils essaieront de comprendre":"future","Ils essaieraient de comprendre":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","escola"],"notaEn":"Before a silent ending the «y» becomes «i»: «ils essaient». Before a sounded one it stays: «nous essayons». «Ils essayent» is also correct.","requerTodas":["fr-p301","fr-p110"],"v":"1b4355bc"},{"idioma":"fr","id":"fr-v114","tipo":"frase","fr":"On a perdu le match.","en":"We lost the game.","aceitasEn":["we lost the game","weve lost the game","we have lost the game","we lost the match"],"distratoresEn":["We're losing the game.","We'll lose the game.","We would lose the game.","We had lost the game."],"formasFr":{"On perd le match":"present","On perdra le match":"future","On perdrait le match":"conditional","On avait perdu le match":"pluperfect"},"nivel":"A1","tags":["conjugação","pretérito","regular","cultura"],"notaEn":"Participle in «-u»: «perdu». In the present, «il perd» takes no «t»: the final «d» is enough.","requerTodas":["fr-p002","fr-p323","fr-p311"],"v":"3dfe34a6"},{"idioma":"fr","id":"fr-v115","tipo":"frase","fr":"Elle m'a montré la ville.","en":"She showed me the city.","aceitasEn":["she showed me the city","shes shown me the city","she has shown me the city","she showed me around the city","she showed me the town","she showed me around town"],"distratoresEn":["She shows me the city.","She'll show me the city.","She would show me the city.","She had shown me the city."],"formasFr":{"Elle me montre la ville":"present","Elle me montrera la ville":"future","Elle me montrerait la ville":"conditional","Elle m'avait montré la ville":"pluperfect"},"nivel":"A1","tags":["conjugação","pretérito","regular","cidade"],"notaEn":"In the passé composé, the pronoun goes before the auxiliary: «elle m'a montré». «Montrer» is a regular «-er» verb.","requerTodas":["fr-p002","fr-p329","fr-p028"],"v":"a19d183f"},{"idioma":"fr","id":"fr-v116","tipo":"frase","fr":"Elle est descendue du bus.","en":"She got off the bus.","aceitasEn":["she got off the bus","shes gotten off the bus","she has gotten off the bus","she has got off the bus","she stepped off the bus"],"distratoresEn":["She gets off the bus.","She was getting off the bus.","She'll get off the bus.","She had gotten off the bus."],"formasFr":{"Elle descend du bus":"present","Elle descendait du bus":"imperfect","Elle descendra du bus":"future","Elle était descendue du bus":"pluperfect"},"nivel":"A1","tags":["conjugação","pretérito","regular","viagem"],"notaEn":"«Descendre» takes «être» in the passé composé, and the participle agrees with the subject: «elle est descendue». To get off a vehicle is «descendre de».","requerTodas":["fr-p001","fr-p315","fr-p060"],"v":"4c0b6a6a"},{"idioma":"fr","id":"fr-v117","tipo":"frase","fr":"J'ai tourné à droite.","en":"I turned right.","aceitasEn":["i turned right","ive turned right","i have turned right","i made a right","i took a right","i turned to the right"],"distratoresEn":["I'm turning right.","I'll turn right.","I would turn right.","I had turned right."],"formasFr":{"Je tourne à droite":"present","Je tournerai à droite":"future","Je tournerais à droite":"conditional","J'avais tourné à droite":"pluperfect"},"nivel":"A1","tags":["conjugação","pretérito","regular","cidade"],"notaEn":"Regular «-er» verb: «tourné», with «avoir». «À droite» is to the right; «tout droit», straight ahead: similar words, different meanings.","requerTodas":["fr-p002","fr-p313","fr-p314"],"v":"4e36fca5"},{"idioma":"fr","id":"fr-v118","tipo":"frase","fr":"Ils louaient une maison à la campagne.","en":"They used to rent a house in the country.","aceitasEn":["they used to rent a house in the country","they used to rent a house in the countryside","they used to rent a country house","they rented a house in the country","they would rent a house in the country"],"distratoresEn":["They rent a house in the country.","They're going to rent a house in the country.","They'll rent a house in the country.","They had rented a house in the country."],"formasFr":{"Ils louent une maison à la campagne":"present","Ils vont louer une maison à la campagne":"near future","Ils loueront une maison à la campagne":"future","Ils avaient loué une maison à la campagne":"pluperfect"},"nivel":"A2","tags":["conjugação","imperfeito","regular","casa"],"notaEn":"The imperfect tells a habit: «ils louaient», they used to rent. «Louer» is regular: the stem «lou-» takes «-ait», «-aient».","requerTodas":["fr-p335","fr-p020","fr-p332"],"v":"446a0480"},{"idioma":"fr","id":"fr-v119","tipo":"frase","fr":"La chambre coûtait cent euros.","en":"The room cost a hundred euros.","aceitasEn":["the room cost a hundred euros","the room was a hundred euros","the room used to cost a hundred euros"],"distratoresEn":["The room is a hundred euros.","The room will cost a hundred euros.","The room would cost a hundred euros.","The room had cost a hundred euros."],"formasFr":{"La chambre coûte cent euros":"present","La chambre coûtera cent euros":"future","La chambre coûterait cent euros":"conditional","La chambre avait coûté cent euros":"pluperfect"},"nivel":"A1","tags":["conjugação","imperfeito","regular","viagem","compras"],"notaEn":"The imperfect describes how things were: «la chambre coûtait», the room cost. Regular «-er» verb: «coût-» + «-ait».","requerTodas":["fr-p107","fr-p321","fr-p273","fr-p128"],"v":"7d0d25f2"},{"idioma":"fr","id":"fr-v120","tipo":"frase","fr":"Il ne m'a pas rappelé.","aceitasFr":["Il ne m'a pas rappelée."],"en":"He didn't call me back.","aceitasEn":["he didnt call me back","he did not call me back","he hasnt called me back","he has not called me back","he never called me back"],"distratoresEn":["He doesn't call me back.","He isn't going to call me back.","He won't call me back.","He hadn't called me back."],"formasFr":{"Il ne me rappelle pas":"present","Il ne me rappellera pas":"future","Il ne me rappellerait pas":"conditional","Il ne m'avait pas rappelé":"pluperfect"},"nivel":"A2","tags":["conjugação","pretérito","regular","tecnologia"],"notaEn":"In the negative, «ne… pas» wraps the auxiliary: «il ne m'a pas rappelé». A woman speaking writes «rappelée»: the participle agrees with the preceding «me».","requerTodas":["fr-p002","fr-p328"],"v":"e07eb34d"},{"idioma":"fr","id":"fr-v121","tipo":"frase","fr":"Les enfants dorment déjà.","en":"The kids are already asleep.","aceitasEn":["the kids are already asleep","the children are already asleep","the kids are already sleeping","the children are already sleeping"],"distratoresEn":["The kids were already asleep.","The kids have already slept.","The kids will be asleep.","The kids would be asleep."],"formasFr":{"Les enfants dormaient déjà":"imperfect","Les enfants ont déjà dormi":"passé composé","Les enfants dormiront déjà":"future","Les enfants dormiraient déjà":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","família"],"notaEn":"«Dormir» drops the «m» in the singular: je dors, il dort. It returns in the plural: nous dormons, ils dorment.","requerTodas":["fr-p023","fr-p109","fr-p050"],"v":"923a72a8"},{"idioma":"fr","id":"fr-v122","tipo":"frase","fr":"Mon frère t'aidera.","en":"My brother will help you.","aceitasEn":["my brother will help you","my brother is going to help you","my brothers going to help you"],"distratoresEn":["My brother was helping you.","My brother helped you.","My brother would help you.","My brother had helped you."],"formasFr":{"Mon frère t'aidait":"imperfect","Mon frère t'a aidé":"passé composé","Mon frère t'aiderait":"conditional","Mon frère t'avait aidé":"pluperfect"},"nivel":"A1","tags":["conjugação","futuro","regular","família"],"notaEn":"Regular future: the whole infinitive + the ending: aider + a = «il aidera». The pronoun goes before the verb: «t'aidera».","requerTodas":["fr-p078","fr-p111"],"v":"10c3e526"},{"idioma":"fr","id":"fr-v123","tipo":"frase","fr":"Vous avez choisi ?","en":"Have you chosen?","aceitasEn":["have you chosen","did you choose","have you decided","are you ready to order","have you made your choice"],"distratoresEn":["Are you choosing?","Will you choose?","Would you choose?","Had you chosen?"],"formasFr":{"Vous choisissez":"present","Vous choisirez":"future","Vous choisiriez":"conditional","Vous aviez choisi":"pluperfect"},"nivel":"A1","tags":["conjugação","pretérito","regular","comida"],"notaEn":"The waiter's question. The participle of «choisir» is «choisi», with no «s», even with «vous».","requerTodas":["fr-p002","fr-p377"],"v":"b879c65a"},{"idioma":"fr","id":"fr-v124","tipo":"frase","fr":"Je perds toujours mes clés.","en":"I always lose my keys.","aceitasEn":["i always lose my keys","im always losing my keys","i keep losing my keys","i always lose the keys"],"distratoresEn":["I always used to lose my keys.","I've always lost my keys.","I'll always lose my keys.","I'd always lose my keys."],"formasFr":{"Je perdais toujours mes clés":"imperfect","J'ai toujours perdu mes clés":"passé composé","Je perdrai toujours mes clés":"future","Je perdrais toujours mes clés":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular","casa"],"notaEn":"Regular «-re» verb: je perds, tu perds, il perd, with no «t». «Toujours» comes right after the verb.","requerTodas":["fr-p323","fr-p046","fr-p133"],"v":"21d530ea"},{"idioma":"fr","id":"fr-v125","tipo":"frase","fr":"Qui a conduit ?","en":"Who drove?","aceitasEn":["who drove","who did the driving"],"distratoresEn":["Who drives?","Who'll drive?","Who would drive?","Who had driven?"],"formasFr":{"Qui conduit":"present","Qui conduira":"future","Qui conduirait":"conditional","Qui avait conduit":"pluperfect"},"nivel":"A1","tags":["conjugação","pretérito","irregular","viagem"],"notaEn":"The participle of «conduire» is «conduit», like «dit» and «écrit». «Qui» as subject takes a third-person verb: «qui a conduit ?».","requerTodas":["fr-p002","fr-p375"],"v":"7119600e"},{"idioma":"fr","id":"fr-v126","tipo":"frase","fr":"Il toussait toute la nuit.","en":"He was coughing all night.","aceitasEn":["he was coughing all night","he was coughing all night long","he coughed all night","he coughed all night long","he used to cough all night"],"distratoresEn":["He coughs all night.","He'll cough all night.","He's going to cough all night.","He had coughed all night."],"formasFr":{"Il tousse toute la nuit":"present","Il toussera toute la nuit":"future","Il tousserait toute la nuit":"conditional","Il avait toussé toute la nuit":"pluperfect"},"nivel":"A1","tags":["conjugação","imperfeito","regular","saúde"],"notaEn":"The imperfect describes something ongoing: «il toussait», he was coughing. «Toute la nuit», all night, agrees with feminine «nuit».","requerTodas":["fr-p326","fr-p070","fr-p030"],"v":"7321637b"},{"idioma":"fr","id":"fr-p385","tipo":"palavra","fr":"comment","en":"how","aceitasEn":["how"],"distratoresEn":["when","where","why","who"],"nivel":"A1","tags":["cotidiano"],"notaEn":"For questions: «Comment ça va ?», how are you?; «Comment tu t'appelles ?», what's your name? On its own, «Comment ?» means sorry, what? A comment, the noun, is «un commentaire».","v":"18bd5f5f","pos":69},{"idioma":"fr","id":"fr-p386","tipo":"palavra","fr":"le garçon","en":"the boy","aceitasEn":["boy","the boy","young man","lad","kid"],"distratoresEn":["the cousin","the gentleman","the groom","the uncle"],"nivel":"A1","tags":["família","falso-amigo"],"notaEn":"A boy or a young man: «un petit garçon», a little boy; «mon garçon», my son. The waiter sense English borrowed is dated in France: a waiter today is «le serveur».","v":"cefccbdc","pos":167},{"idioma":"fr","id":"fr-p387","tipo":"palavra","fr":"la façon","en":"the way","aceitasEn":["way","the way","manner","the manner"],"distratoresEn":["the facade","the faction","the reason","the will"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine: «de quelle façon ?», in what way? «De toute façon», anyway. English fashion comes from it, but fashion as style is «la mode».","v":"60e26ca9","pos":218},{"idioma":"fr","id":"fr-p388","tipo":"palavra","fr":"le corps","en":"the body","aceitasEn":["body","the body","corpse","the corpse","corps"],"distratoresEn":["the soul","the skin","the bone","the heart"],"nivel":"A1","tags":["corpo"],"notaEn":"Masculine, the same in the plural: «le corps», «les corps». The «ps» is silent, as in English corps. It also means a dead body: «on a retrouvé le corps».","v":"969a9f2c","pos":265},{"idioma":"fr","id":"fr-p389","tipo":"palavra","fr":"surtout","en":"especially","aceitasEn":["especially","above all","mostly","mainly","particularly","in particular"],"distratoresEn":["only","rarely","finally","again"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Sur» + «tout», over everything: «j'aime surtout le fromage», I especially like cheese. With a request, it insists: «surtout, ne dis rien !», whatever you do, don't say anything! «Surtout pas !», definitely not!","v":"db95d925","pos":314},{"idioma":"fr","id":"fr-p390","tipo":"palavra","fr":"se souvenir","en":"to remember","aceitasEn":["to remember","remember","to recall","recall"],"distratoresEn":["to forget","to regret","to get used to","to have fun"],"nivel":"A1","tags":["verbo","cotidiano"],"notaEn":"With «de»: «je me souviens de toi», I remember you. Conjugated like «venir»: je me souviens, nous nous souvenons. «Un souvenir» is a memory as well as a keepsake.","v":"9d028eee","pos":357},{"idioma":"fr","id":"fr-p391","tipo":"palavra","fr":"le client","aceitasFr":["la cliente"],"en":"the customer","aceitasEn":["customer","the customer","client","the client"],"distratoresEn":["the seller","the supplier","the boss","the manager"],"nivel":"A1","tags":["compras","trabalho"],"notaEn":"Feminine «la cliente». Both a store's customer and a lawyer's client: «un client fidèle», a loyal customer. All of them together are «la clientèle».","v":"5b6276d6","pos":399},{"idioma":"fr","id":"fr-p392","tipo":"palavra","fr":"la sorte","en":"the sort","aceitasEn":["sort","the sort","type","the type"],"distratoresEn":["the raffle","the exit","the fate","the size"],"nivel":"B1","tags":["cotidiano","falso-amigo"],"notaEn":"Mostly in «une sorte de», a sort of: «une sorte de gâteau». «En quelque sorte», in a way. Don't mix it up with «la sortie», the exit, or «le sort», fate.","v":"08506071","pos":435},{"idioma":"fr","id":"fr-p393","tipo":"palavra","fr":"le président","aceitasFr":["la présidente"],"en":"the president","aceitasEn":["president","the president","chairman","the chairman"],"distratoresEn":["the minister","the mayor","the king","the senator"],"nivel":"A1","tags":["política"],"notaEn":"Feminine «la présidente». France's is «le président de la République»; a company's chairman and CEO is «le PDG». A mayor is «le maire».","v":"2070734a","transp":"total","pos":474},{"idioma":"fr","id":"fr-p394","tipo":"palavra","fr":"protéger","en":"to protect","aceitasEn":["to protect","protect","to shield","shield","to defend","defend"],"distratoresEn":["to abandon","to threaten","to attack","to harm"],"nivel":"A1","tags":["verbo","cotidiano"],"notaEn":"From something, with «de» or «contre»: «protéger les enfants du soleil». The accent shifts: je protège, nous protégeons; the «e» after «g» keeps it soft.","v":"e7646e14","pos":511},{"idioma":"fr","id":"fr-p395","tipo":"palavra","fr":"s'inquiéter","en":"to worry","aceitasEn":["to worry","worry","to be worried","be worried","to get worried"],"distratoresEn":["to calm down","to get angry","to be ashamed","to be late"],"nivel":"A1","tags":["verbo","cotidiano"],"notaEn":"The commonest use: «ne t'inquiète pas», don't worry. About someone, «pour»: «je m'inquiète pour toi». The adjective «inquiet» means worried, not quiet.","v":"bd6944f9","pos":544},{"idioma":"fr","id":"fr-p396","tipo":"palavra","fr":"l'image","aceitasFr":["une image"],"en":"the picture","aceitasEn":["picture","the picture","image","the image","illustration"],"distratoresEn":["the frame","the screen","the page","the color"],"nivel":"A1","tags":["cultura"],"notaEn":"Feminine: «une belle image», a beautiful picture. Also someone's public image: «soigner son image», to look after one's image. A photo is «la photo».","v":"232af05b","pos":579},{"idioma":"fr","id":"fr-p397","tipo":"palavra","fr":"le menton","en":"the chin","aceitasEn":["chin","the chin"],"distratoresEn":["the mint","the forehead","the cheek","the neck"],"nivel":"A2","tags":["corpo"],"notaEn":"Masculine: «le menton». The cheek is «la joue», the forehead «le front». Don't confuse it with «la menthe», mint.","v":"289b9e6c","pos":614},{"idioma":"fr","id":"fr-p398","tipo":"palavra","fr":"le bateau","en":"the boat","aceitasEn":["boat","the boat","ship","the ship"],"distratoresEn":["the plane","the train","the port","the island"],"nivel":"A1","tags":["viagem"],"notaEn":"Masculine; «-eau» sounds like «oh», and the plural takes «x»: «des bateaux». «En bateau», by boat. «Mener quelqu'un en bateau» is to take someone for a ride.","v":"25da7d09","pos":646},{"idioma":"fr","id":"fr-p399","tipo":"palavra","fr":"Noël","en":"Christmas","aceitasEn":["christmas","xmas"],"distratoresEn":["Easter","New Year's","Carnival","Epiphany"],"nivel":"A1","tags":["cultura"],"notaEn":"No article, capitalized: «à Noël», at Christmas; «Joyeux Noël !», Merry Christmas! The dieresis splits the vowels: «no-el». Santa Claus is «le Père Noël».","v":"8c4925d9","pos":682},{"idioma":"fr","id":"fr-p400","tipo":"palavra","fr":"l'oreille","aceitasFr":["une oreille"],"en":"the ear","aceitasEn":["ear","the ear","the inner ear"],"distratoresEn":["the eye","the nose","the cheek","the neck"],"nivel":"A1","tags":["corpo"],"notaEn":"Feminine, and it covers the whole ear, inside and out: «j'ai mal à l'oreille», I have an earache. «Dur d'oreille», hard of hearing; «avoir l'oreille musicale», to have a good ear.","v":"794c915a","pos":718},{"idioma":"fr","id":"fr-p401","tipo":"palavra","fr":"retirer","en":"to remove / to withdraw","aceitasEn":["to remove","remove","to withdraw","withdraw","to take off","take off","to take out","take out","to take away","take away","to take back","take back","to pick up","pick up"],"distratoresEn":["to put / to deposit","to hold / to keep","to save / to store","to hide / to conceal"],"nivel":"A2","tags":["verbo","cotidiano"],"notaEn":"To take something away: «retirer son manteau», to take off your coat. At the bank, to withdraw: «retirer de l'argent». Also to pick up a parcel or take back your words: «je retire ce que j'ai dit».","v":"1d957687","pos":750},{"idioma":"fr","id":"fr-p402","tipo":"palavra","fr":"mentir","en":"to lie","aceitasEn":["to lie","lie","to tell lies","tell lies","to tell a lie","tell a lie"],"distratoresEn":["to feel","to measure","to mention","to confess"],"nivel":"A2","tags":["verbo","social"],"notaEn":"Lying to someone takes «à»: «il m'a menti», he lied to me. Conjugated like «sentir»: je mens, nous mentons. A lie is «un mensonge»; lying down is «s'allonger».","v":"10ff1f4a","pos":781},{"idioma":"fr","id":"fr-p403","tipo":"palavra","fr":"posséder","en":"to own","aceitasEn":["to own","own","to possess","possess"],"distratoresEn":["to lose","to need","to lend","to borrow"],"nivel":"A2","tags":["verbo","economia"],"notaEn":"More formal than «avoir»: «il possède trois maisons», he owns three houses. The accent shifts: je possède, nous possédons. «Posséder une langue» is to master a language.","v":"ca2ff879","pos":816},{"idioma":"fr","id":"fr-p404","tipo":"palavra","fr":"la poche","en":"the pocket","aceitasEn":["pocket","the pocket"],"distratoresEn":["the sleeve","the collar","the button","the cuff"],"nivel":"A2","tags":["roupa"],"notaEn":"Feminine. «Dans ma poche», in my pocket. «Un livre de poche», a paperback; «l'argent de poche», pocket money, an allowance.","v":"d6e0d3b2","pos":851},{"idioma":"fr","id":"fr-p405","tipo":"palavra","fr":"l'emploi","aceitasFr":["un emploi"],"en":"the job","aceitasEn":["job","the job","employment","the position","use","the use"],"distratoresEn":["the loan","the salary","the pension","the boss"],"nivel":"A2","tags":["trabalho"],"notaEn":"Masculine. A job: «chercher un emploi», to look for a job. Also use: «le mode d'emploi», the instructions. «L'emploi du temps» is a schedule.","v":"f6389d81","pos":890},{"idioma":"fr","id":"fr-p406","tipo":"palavra","fr":"nécessaire","en":"necessary","aceitasEn":["necessary","needed","required"],"distratoresEn":["possible","sufficient","urgent","useless"],"nivel":"A2","tags":["adjetivo","cotidiano"],"notaEn":"Same form for masculine and feminine. «Il est nécessaire de partir», we need to leave; with «que» it takes the subjunctive: «il est nécessaire que tu viennes». «Faire le nécessaire», to do what's needed.","v":"e8628510","transp":"parecida","pos":924},{"idioma":"fr","id":"fr-p407","tipo":"palavra","fr":"inventer","en":"to invent / to make up","aceitasEn":["to invent","invent","to make up","make up","to come up with","come up with","to devise","to dream up"],"distratoresEn":["to invest / to fund","to imitate / to copy","to forget / to overlook","to admit / to confess"],"nivel":"A2","tags":["verbo","cotidiano"],"notaEn":"Both to invent and to make up: «il invente toujours des excuses», he's always making up excuses. «Je n'invente rien», I'm not making this up.","v":"cef5384c","pos":959},{"idioma":"fr","id":"fr-p408","tipo":"palavra","fr":"le métier","en":"the profession","aceitasEn":["profession","the profession","trade","the trade","occupation","the occupation","craft","line of work"],"distratoresEn":["the mystery","the degree","the office","the salary"],"nivel":"A2","tags":["trabalho"],"notaEn":"Masculine. «Quel est ton métier ?», what do you do for a living? It's a trade you learn: «apprendre un métier». «Avoir du métier», to be experienced.","v":"fc6b3f59","pos":991},{"idioma":"fr","id":"fr-p409","tipo":"palavra","fr":"le détail","en":"the detail","aceitasEn":["detail","the detail","particular"],"distratoresEn":["the flaw","the summary","the outline","the drawing"],"nivel":"A2","tags":["cotidiano"],"notaEn":"Masculine. «En détail», in detail. In shops, «au détail» means retail, by the unit; the opposite is «en gros», wholesale.","v":"558423dd","transp":"total","pos":1022},{"idioma":"fr","id":"fr-p410","tipo":"palavra","fr":"la naissance","en":"the birth","aceitasEn":["birth","the birth"],"distratoresEn":["the birthday","the wedding","the pregnancy","the baptism"],"nivel":"A2","tags":["família"],"notaEn":"Feminine. «La date de naissance», date of birth; «aveugle de naissance», blind from birth. A birthday is «un anniversaire».","v":"a1e18dc6","pos":1053},{"idioma":"fr","id":"fr-p411","tipo":"palavra","fr":"le titre","en":"the title","aceitasEn":["title","the title","headline","heading"],"distratoresEn":["the chapter","the summary","the author","the page"],"nivel":"A2","tags":["cultura"],"notaEn":"Masculine. A book's title or a champion's; «les gros titres», the headlines. «À titre d'exemple», by way of example. Official signs call a ticket «un titre de transport».","v":"8bd7c3eb","transp":"parecida","pos":1085},{"idioma":"fr","id":"fr-p412","tipo":"palavra","fr":"le tableau","en":"the painting / the board","aceitasEn":["painting","the painting","board","the board","blackboard","the blackboard","whiteboard","the whiteboard","chart","the chart"],"distratoresEn":["the frame / the edge","the desk / the shelf","the mirror / the window","the rug / the curtain"],"nivel":"A2","tags":["escola"],"notaEn":"Masculine. A painting on the wall and the board in class: «écrire au tableau», to write on the board. Also a table or chart: «un tableau Excel», a spreadsheet. A frame is «un cadre».","v":"1d97d6e5","pos":1114},{"idioma":"fr","id":"fr-p413","tipo":"palavra","fr":"l'unité","aceitasFr":["une unité"],"en":"the unit","aceitasEn":["unit","the unit","unity","the unity"],"distratoresEn":["the measure","the half","the dozen","the amount"],"nivel":"A2","tags":["cotidiano"],"notaEn":"Feminine, like most nouns in «-té», often English «-ty». Both unit and unity: «le prix à l'unité», the price per unit; «l'unité nationale», national unity.","v":"96f4ca19","pos":1143},{"idioma":"fr","id":"fr-p414","tipo":"palavra","fr":"appuyer","en":"to press / to lean","aceitasEn":["to press","press","to push","push","to lean","lean","to rest","rest","to support","support"],"distratoresEn":["to pull / to tear off","to release / to let go","to turn / to twist","to lift / to raise"],"nivel":"A2","tags":["verbo","cotidiano"],"notaEn":"Pressing takes «sur»: «appuyez sur le bouton», press the button. It's also to lean («appuyer son vélo contre le mur») and to back: «j'appuie ta demande». The «y» becomes «i» before a silent ending: j'appuie.","v":"a1647537","pos":1178},{"idioma":"fr","id":"fr-p415","tipo":"palavra","fr":"se disputer","en":"to argue","aceitasEn":["to argue","argue","to fight","fight","to quarrel","quarrel","to have a fight","have a fight","to fall out","fall out","to fight over","fight over"],"distratoresEn":["to agree","to apologize","to chat","to complain"],"nivel":"A2","tags":["verbo","social"],"notaEn":"Reciprocal, with «se»: «ils se disputent tout le temps», they're always arguing. «Se disputer quelque chose» is to fight over something. To discuss, or just to chat, is «discuter».","v":"5ed42753","pos":1210},{"idioma":"fr","id":"fr-p416","tipo":"palavra","fr":"rapprocher","en":"to bring closer","aceitasEn":["to bring closer","bring closer","to move closer","move closer","to draw closer","draw closer","to bring together","bring together","to bring nearer","bring nearer"],"distratoresEn":["to push away","to deepen","to hurry up","to delay"],"nivel":"A2","tags":["verbo","cotidiano"],"notaEn":"To move something nearer: «rapproche ta chaise», bring your chair closer. Also to bring people together: «le voyage nous a rapprochés». With «se», to get closer: «se rapprocher de la fenêtre».","v":"f091f963","pos":1242},{"idioma":"fr","id":"fr-p417","tipo":"palavra","fr":"supérieur","aceitasFr":["supérieure"],"en":"higher / superior","aceitasEn":["higher","superior","upper","greater","above"],"distratoresEn":["lower / inferior","earlier / previous","outer / external","later / subsequent"],"nivel":"A2","tags":["adjetivo","cotidiano"],"notaEn":"Feminine «supérieure». Upper, higher or better: «l'étage supérieur», the floor above; «supérieur à 10», over 10. «L'enseignement supérieur», higher education.","v":"86b83e28","pos":1271},{"idioma":"fr","id":"fr-p418","tipo":"palavra","fr":"échanger","en":"to exchange","aceitasEn":["to exchange","exchange","to swap","swap","to trade","trade","to switch","switch"],"distratoresEn":["to lend","to return","to sell","to divide"],"nivel":"A2","tags":["verbo","compras"],"notaEn":"To exchange one thing for another, with «contre»: «échanger un pull contre un autre». Also to exchange words: «on a échangé quelques mots». To change clothes or seats is «changer de».","v":"e5db9aa1","transp":"parecida","pos":1303},{"idioma":"fr","id":"fr-p419","tipo":"palavra","fr":"joyeux","aceitasFr":["joyeuse"],"en":"joyful","aceitasEn":["joyful","joyous","cheerful","merry","jolly"],"distratoresEn":["young","sad","tired","nervous"],"nivel":"A2","tags":["adjetivo","social"],"notaEn":"Feminine «joyeuse». Full of joy («un enfant joyeux»), and the word for holiday greetings: «Joyeux Noël !», Merry Christmas! «Joyeux anniversaire !», Happy birthday!","v":"1f61394e","pos":1334},{"idioma":"fr","id":"fr-p420","tipo":"palavra","fr":"interrompre","en":"to interrupt","aceitasEn":["to interrupt","interrupt","to break off","break off","to cut off","cut off","to suspend","suspend"],"distratoresEn":["to interpret","to intervene","to question","to irritate"],"nivel":"A2","tags":["verbo","social"],"notaEn":"Conjugated like «rompre», with a silent «t» in «il interrompt». «Ne m'interromps pas !», don't interrupt me! «S'interrompre», to break off.","v":"043bf5e2","pos":1367},{"idioma":"fr","id":"fr-p421","tipo":"palavra","fr":"le cabinet","en":"the office","aceitasEn":["office","the office","practice","the practice","firm","the firm","the doctor's office","surgery","the surgery"],"distratoresEn":["the cupboard","the pharmacy","the hospital","the lobby"],"nivel":"A2","tags":["saúde","falso-amigo"],"notaEn":"Not a kitchen cabinet, which is «un placard». It's a doctor's office («le cabinet médical») or a firm: «un cabinet d'avocats», a law firm. In government, a minister's staff.","v":"a63a37c0","pos":1395},{"idioma":"fr","id":"fr-p422","tipo":"palavra","fr":"la tradition","en":"the tradition","aceitasEn":["tradition","the tradition","custom"],"distratoresEn":["the translation","the betrayal","the transition","the trend"],"nivel":"A2","tags":["cultura"],"notaEn":"Feminine, like every noun in «-tion». «Par tradition», traditionally. Don't mix it up with «la traduction», a translation.","v":"a4ee118a","transp":"total","pos":1425},{"idioma":"fr","id":"fr-p423","tipo":"palavra","fr":"le garage","en":"the garage","aceitasEn":["garage","the garage","the repair shop","the auto shop","the shop"],"distratoresEn":["the basement","the porch","the warehouse","the driveway"],"nivel":"A2","tags":["casa"],"notaEn":"Masculine. Both where the car is kept and where it's fixed: «ma voiture est au garage», my car is in the shop. The mechanic is «le garagiste».","v":"bdff73e2","transp":"total","pos":1456},{"idioma":"fr","id":"fr-p424","tipo":"palavra","fr":"comparer","en":"to compare","aceitasEn":["to compare","compare","to liken","liken"],"distratoresEn":["to buy","to share","to appear","to prepare"],"nivel":"A2","tags":["verbo","cotidiano"],"notaEn":"With «à» or «avec»: «comparer les prix», to compare prices; «on le compare à son père», people compare him to his father. A comparison is «une comparaison».","v":"3377dca0","transp":"parecida","pos":1486},{"idioma":"fr","id":"fr-p425","tipo":"palavra","fr":"mystérieux","aceitasFr":["mystérieuse"],"en":"mysterious","aceitasEn":["mysterious","enigmatic"],"distratoresEn":["miraculous","miserable","meticulous","famous"],"nivel":"B1","tags":["adjetivo","cultura"],"notaEn":"Feminine «mystérieuse». From «le mystère», mystery: «un inconnu mystérieux», a mysterious stranger.","v":"bbbbb856","transp":"parecida","pos":1521},{"idioma":"fr","id":"fr-p426","tipo":"palavra","fr":"entièrement","en":"entirely","aceitasEn":["entirely","completely","fully","wholly"],"distratoresEn":["partially","rarely","slowly","certainly"],"nivel":"B1","tags":["cotidiano"],"notaEn":"From «entier», whole, with an «è»: «entièrement». «La maison est entièrement rénovée», the house has been entirely renovated.","v":"f51f83c0","pos":1559},{"idioma":"fr","id":"fr-p427","tipo":"palavra","fr":"l'urgence","en":"urgency / emergency","aceitasEn":["urgency","emergency","the emergency","an emergency","the er","er","emergency room","the emergency room"],"distratoresEn":["agency / office","demand / requirement","delay / holdup","calm / quiet"],"nivel":"B1","tags":["saúde"],"notaEn":"Feminine. Urgency («en urgence», urgently) and an emergency: «en cas d'urgence», in case of emergency. In the plural, «les urgences» is the ER.","v":"f2a5ebbc","pos":1600},{"idioma":"fr","id":"fr-p428","tipo":"palavra","fr":"douter","en":"to doubt","aceitasEn":["to doubt","doubt","to have doubts"],"distratoresEn":["to gild","to double","to last","to dare"],"nivel":"B1","tags":["verbo","cotidiano"],"notaEn":"Takes «de»: «je doute de sa sincérité», I doubt his sincerity; with «que», the subjunctive follows: «je doute qu'il vienne». Reflexive, it means to suspect: «je m'en doutais», I thought as much.","v":"0c743932","pos":1640},{"idioma":"fr","id":"fr-p429","tipo":"palavra","fr":"la monnaie","en":"the change / the currency","aceitasEn":["change","the change","currency","the currency","coins","coin","small change","loose change"],"distratoresEn":["the check / the receipt","the wallet / the purse","the salary / the payment","the discount / the sale"],"nivel":"B1","tags":["compras","falso-amigo"],"notaEn":"Not money, which is «l'argent»: it's change («rendre la monnaie», to give change) and currency: «l'euro est la monnaie de la France». A single coin is «une pièce».","v":"8537b135","pos":1680},{"idioma":"fr","id":"fr-p430","tipo":"palavra","fr":"totalement","en":"totally","aceitasEn":["totally","completely","fully","utterly","absolutely"],"distratoresEn":["normally","slightly","finally","rarely"],"nivel":"B1","tags":["cotidiano"],"notaEn":"From «total»: «tu as totalement raison», you're totally right. In casual speech, «carrément» does the same job.","v":"65118bf1","pos":1721},{"idioma":"fr","id":"fr-p431","tipo":"palavra","fr":"les habits","en":"clothes","aceitasEn":["clothes","the clothes","clothing","garments"],"distratoresEn":["housing","footwear","furniture","luggage"],"nivel":"B1","tags":["roupa","falso-amigo"],"notaEn":"Masculine, almost always plural: «mets tes habits», put your clothes on. The neutral word is «les vêtements». Not habits, which are «les habitudes»; only a monk's habit is «habit».","v":"4ac893b2","pos":1762},{"idioma":"fr","id":"fr-p432","tipo":"palavra","fr":"apparemment","en":"apparently","aceitasEn":["apparently","seemingly","it seems","by the look of it"],"distratoresEn":["rarely","deliberately","finally","immediately"],"nivel":"B1","tags":["cotidiano"],"notaEn":"From «apparent», double «p»; «-emment» sounds like «-amment». It opens a sentence to pass on what you heard: «apparemment, il a démissionné», apparently he quit.","v":"bfe3ca31","pos":1801},{"idioma":"fr","id":"fr-p433","tipo":"palavra","fr":"réduire","en":"to reduce","aceitasEn":["to reduce","reduce","to cut","to lower","to decrease","to cut down"],"distratoresEn":["to seduce","to produce","to drive","to translate"],"nivel":"B1","tags":["verbo","economia"],"notaEn":"Conjugated like «conduire»: je réduis, nous réduisons, j'ai réduit. «Réduire les dépenses», to cut spending; «une réduction» is also a discount.","v":"309607fe","pos":1842},{"idioma":"fr","id":"fr-p434","tipo":"palavra","fr":"le gaz","en":"gas","aceitasEn":["gas","the gas","natural gas"],"distratoresEn":["gauze","coal","steam","oil"],"nivel":"B1","tags":["casa"],"notaEn":"Masculine, with a «z»: «le gaz»; a gas stove is «une cuisinière à gaz». Gas for the car is «l'essence» in France (in Quebec, «le gaz»).","v":"70f659b3","pos":1883},{"idioma":"fr","id":"fr-p435","tipo":"palavra","fr":"la majorité","en":"the majority","aceitasEn":["majority","the majority","most"],"distratoresEn":["the minority","the average","the whole","the rest"],"nivel":"B1","tags":["social"],"notaEn":"Feminine, with «de»: «la majorité des gens», most people. It's also the age of majority: «à sa majorité», when he turns eighteen.","v":"44ce7b87","transp":"parecida","pos":1924},{"idioma":"fr","id":"fr-p436","tipo":"palavra","fr":"la catastrophe","en":"the disaster","aceitasEn":["disaster","the disaster","catastrophe","the catastrophe","calamity","tragedy"],"distratoresEn":["the stanza","the crisis","the threat","the feat"],"nivel":"B1","tags":["cotidiano"],"notaEn":"Feminine, and in conversation it covers any mess: «c'est la catastrophe !», it's a disaster! «Atterrir en catastrophe» is to make an emergency landing.","v":"602dbdd4","pos":1966},{"idioma":"fr","id":"fr-p437","tipo":"palavra","fr":"occupé","aceitasFr":["occupée"],"en":"busy","aceitasEn":["busy","occupied","taken","engaged"],"distratoresEn":["hidden","free","tired","late"],"nivel":"B1","tags":["adjetivo","trabalho"],"notaEn":"Feminine «occupée». Busy («je suis très occupé»), taken, of a seat («la place est occupée»), and engaged, of a phone («ça sonne occupé»). «S'occuper de» is to take care of: «je m'occupe des enfants».","v":"98dfb964","pos":2006},{"idioma":"fr","id":"fr-p438","tipo":"palavra","fr":"biologique","aceitasFr":["bio"],"en":"biological","aceitasEn":["biological","organic"],"distratoresEn":["chemical","geological","psychological","biographical"],"nivel":"B1","tags":["adjetivo","comida"],"notaEn":"Same in the feminine. Biological («le père biologique») and organic, at the market: «des légumes biologiques», casually just «bio».","v":"e352f11d","pos":2044},{"idioma":"fr","id":"fr-p439","tipo":"palavra","fr":"le pot","en":"the jar","aceitasEn":["jar","the jar","pot","the pot","flowerpot","tub","container"],"distratoresEn":["the lid","the package","the harbor","the pole"],"nivel":"B1","tags":["casa","comida"],"notaEn":"Masculine, silent «t». A jar of jam («un pot de confiture») or a flowerpot («un pot de fleurs»). Casually, «prendre un pot» is to grab a drink, and «avoir du pot», to be lucky.","v":"1348dcf7","pos":2083},{"idioma":"fr","id":"fr-p440","tipo":"palavra","fr":"gérer","en":"to manage","aceitasEn":["to manage","manage","to handle","to deal with","to cope with","to administer"],"distratoresEn":["to generate","to groan","to freeze","to keep"],"nivel":"B1","tags":["verbo","trabalho","falso-amigo"],"notaEn":"To manage, run: «gérer une entreprise». Also to handle, cope with: «gérer le stress». Casually, «je gère» means I've got this.","v":"67f5379e","pos":2123},{"idioma":"fr","id":"fr-p441","tipo":"palavra","fr":"le commandement","en":"the command / the commandment","aceitasEn":["command","the command","commandment","the commandment","leadership"],"distratoresEn":["the purchase / the delivery","the commander / the captain","the prayer / the blessing","the punishment / the penalty"],"nivel":"B1","tags":["cultura"],"notaEn":"Masculine. Command, leadership («prendre le commandement», to take command), and a commandment: «les dix commandements». An order you place is «une commande».","v":"00ff72d8","pos":2164},{"idioma":"fr","id":"fr-p442","tipo":"palavra","fr":"le beau-père","en":"the father-in-law / the stepfather","aceitasEn":["father-in-law","the father-in-law","stepfather","the stepfather","stepdad"],"distratoresEn":["the brother-in-law / the son-in-law","the godfather / the godson","the grandfather / the great-grandfather","the uncle / the cousin"],"nivel":"B1","tags":["família"],"notaEn":"Masculine, and it covers both: your spouse's father and your mother's husband. «Beau» here isn't handsome: it's the prefix for in-laws and step-relatives («la belle-mère», «le beau-frère»). Plural «beaux-pères».","v":"b1023ea2","pos":2207},{"idioma":"fr","id":"fr-p443","tipo":"palavra","fr":"la serviette","en":"the towel / the napkin","aceitasEn":["towel","the towel","napkin","the napkin","serviette","briefcase","the briefcase"],"distratoresEn":["the sheet / the pillowcase","the apron / the glove","the tray / the saucer","the rug / the curtain"],"nivel":"B1","tags":["casa"],"notaEn":"Feminine. A bath towel («la serviette de bain») and a napkin («la serviette de table»); also a briefcase. A tablecloth is «la nappe».","v":"9a47237c","pos":2245},{"idioma":"fr","id":"fr-p444","tipo":"palavra","fr":"pénible","en":"tiresome / annoying","aceitasEn":["tiresome","annoying","painful","hard","tough","exhausting","a pain","grueling","tedious"],"distratoresEn":["dangerous / risky","funny / amusing","possible / feasible","lazy / slow"],"nivel":"B1","tags":["adjetivo","cotidiano"],"notaEn":"Same in the feminine. Hard going, of what tires or hurts («un travail pénible», «une nouvelle pénible»), and annoying, of a person: «arrête, tu es pénible !», stop, you're being a pain!","v":"56fd2e24","pos":2286},{"idioma":"fr","id":"fr-p445","tipo":"palavra","fr":"l'apparence","en":"the appearance","aceitasEn":["appearance","the appearance","look","the look","looks","appearances"],"distratoresEn":["the apparition","the device","the resemblance","the transparency"],"nivel":"B1","tags":["social"],"notaEn":"Feminine. How something looks: «il ne faut pas se fier aux apparences», don't trust appearances. Showing up, as in to make an appearance, is «faire son apparition».","v":"78ff713e","transp":"parecida","pos":2326},{"idioma":"fr","id":"fr-p446","tipo":"palavra","fr":"le steak","en":"the steak","aceitasEn":["steak","the steak","beefsteak"],"distratoresEn":["the chop","the chicken","the sausage","the ham"],"nivel":"B1","tags":["comida"],"notaEn":"Masculine, said «stek». Doneness: «saignant», rare; «à point», medium; «bien cuit», well done. A «steak haché» is a hamburger patty.","v":"57c866b5","transp":"total","pos":2365},{"idioma":"fr","id":"fr-p447","tipo":"palavra","fr":"la facture","en":"the bill","aceitasEn":["bill","the bill","invoice","the invoice"],"distratoresEn":["the fracture","the fine","the estimate","the rate"],"nivel":"B1","tags":["compras"],"notaEn":"Feminine. An invoice or a utility bill: «payer la facture d'électricité». The check at a restaurant is «l'addition».","v":"d68168fe","pos":2405},{"idioma":"fr","id":"fr-p448","tipo":"palavra","fr":"le poumon","en":"the lung","aceitasEn":["lung","the lung"],"distratoresEn":["the liver","the kidney","the stomach","the heart"],"nivel":"B1","tags":["corpo","saúde"],"notaEn":"Masculine: «le poumon», plural «les poumons». «Respirer à pleins poumons», to breathe deeply.","v":"a5dbe6a9","pos":2444},{"idioma":"fr","id":"fr-p449","tipo":"palavra","fr":"le poème","en":"the poem","aceitasEn":["poem","the poem"],"distratoresEn":["the novel","the short story","the song","the essay"],"nivel":"B1","tags":["cultura"],"notaEn":"Masculine, with «è»: «le poème». Poetry as an art is «la poésie»; a line of verse, «un vers».","v":"82a11630","pos":2482},{"idioma":"fr","id":"fr-p450","tipo":"palavra","fr":"la cabine","en":"the booth","aceitasEn":["booth","the booth","cabin","the cabin","cab","the cab","fitting room","the fitting room"],"distratoresEn":["the canteen","the porch","the cellar","the cabinet"],"nivel":"B2","tags":["viagem"],"notaEn":"Feminine. A phone booth («la cabine téléphonique»), a plane or ship cabin, a truck cab. In a store, «la cabine d'essayage» is the fitting room.","v":"ec684168","pos":2526},{"idioma":"fr","id":"fr-p451","tipo":"palavra","fr":"photographier","sinonimosFr":["prendre en photo"],"en":"to photograph","aceitasEn":["to photograph","photograph","to take a picture","take a picture","to take a photo","take a photo","to take pictures","take pictures"],"distratoresEn":["to film","to draw","to print","to frame"],"nivel":"B2","tags":["verbo","viagem"],"notaEn":"In everyday speech, «prendre en photo» or «prendre une photo» is more common: «je peux te prendre en photo ?», can I take your picture? «Photographier» is more formal, the photographer's word.","v":"f37b3ac3","pos":2577},{"idioma":"fr","id":"fr-p452","tipo":"palavra","fr":"isoler","en":"to isolate","aceitasEn":["to isolate","isolate","to insulate","insulate","to cut off","cut off","to soundproof","soundproof"],"distratoresEn":["to console","to ignore","to relieve","to illustrate"],"nivel":"B2","tags":["verbo","casa"],"notaEn":"Both to isolate («isoler un malade») and to insulate: «isoler une maison». Careful with the nouns: «l'isolation» is insulation, and isolation is «l'isolement».","v":"c91e175a","pos":2628},{"idioma":"fr","id":"fr-p453","tipo":"palavra","fr":"le continent","en":"the continent","aceitasEn":["continent","the continent","the mainland","mainland"],"distratoresEn":["the content","the hemisphere","the archipelago","the ocean"],"nivel":"B2","tags":["natureza"],"notaEn":"Masculine. For islanders it means the mainland: in Corsica, «le continent» is mainland France. The adjective is «continental».","v":"77b03227","transp":"total","pos":2677},{"idioma":"fr","id":"fr-p454","tipo":"palavra","fr":"la panique","en":"panic","aceitasEn":["panic","the panic"],"distratoresEn":["anger","boredom","relief","jealousy"],"nivel":"B2","tags":["saúde"],"notaEn":"Feminine. «Pas de panique !», don't panic! The verb is «paniquer» or «s'affoler»: «ne panique pas».","v":"4cd9193c","pos":2727},{"idioma":"fr","id":"fr-p455","tipo":"palavra","fr":"fédéral","aceitasFr":["fédérale"],"en":"federal","aceitasEn":["federal"],"distratoresEn":["feudal","municipal","provincial","regional"],"nivel":"B2","tags":["adjetivo","política"],"notaEn":"Feminine «fédérale»; plural «fédéraux». In Switzerland it refers to the Confederation: «le Conseil fédéral» is the government. France isn't a federation, so the word is mostly about Switzerland, Belgium and Canada.","v":"4e1f847b","transp":"total","pos":2776},{"idioma":"fr","id":"fr-p456","tipo":"palavra","fr":"la pose","en":"the pose","aceitasEn":["pose","the pose","posture","the posture","laying","fitting","installation","the installation"],"distratoresEn":["the pause","the possession","the portrait","the frame"],"nivel":"B2","tags":["cultura"],"notaEn":"Feminine. A pose for a photo («prendre la pose», to strike a pose) and, in building work, laying or fitting: «la pose du carrelage», tiling. Don't mix it up with «la pause», a break.","v":"ed266d14","transp":"total","pos":2825},{"idioma":"fr","id":"fr-p457","tipo":"palavra","fr":"la couronne","en":"the crown","aceitasEn":["crown","the crown","wreath","the wreath"],"distratoresEn":["the throne","the scepter","the necklace","the column"],"nivel":"B2","tags":["cultura"],"notaEn":"Feminine. A king's crown, a wreath («une couronne de fleurs») and a dental crown. Capitalized, «la Couronne» is the monarchy.","v":"ba1c560e","pos":2876},{"idioma":"fr","id":"fr-p458","tipo":"palavra","fr":"le tueur","sinonimosFr":["l'assassin","le meurtrier"],"en":"the killer","aceitasEn":["killer","the killer","murderer","the murderer"],"distratoresEn":["the thief","the kidnapper","the traitor","the detective"],"nivel":"B2","tags":["mídia"],"notaEn":"From «tuer», to kill. «Un tueur en série», a serial killer; «un tueur à gages», a hitman. Feminine «tueuse».","v":"398d6bcc","pos":2925},{"idioma":"fr","id":"fr-p459","tipo":"palavra","fr":"ordinaire","sinonimosFr":["commun","habituel","courant"],"en":"ordinary","aceitasEn":["ordinary","common","usual","normal","everyday","average"],"distratoresEn":["orderly","organized","rare","old"],"nivel":"B2","tags":["adjetivo","cotidiano"],"notaEn":"Ordinary, everyday: «une journée ordinaire». It can be slightly dismissive, meaning low quality: «un vin ordinaire», a cheap table wine. «D'ordinaire», usually.","v":"76adbfcd","transp":"parecida","pos":2975},{"idioma":"fr","id":"fr-p460","tipo":"palavra","fr":"cruel","aceitasFr":["cruelle"],"en":"cruel","aceitasEn":["cruel","heartless"],"distratoresEn":["raw","gullible","stubborn","cowardly"],"nivel":"B2","tags":["adjetivo","social"],"notaEn":"Feminine «cruelle», with a double «l». It takes «avec» or «envers»: «cruel envers les animaux», cruel to animals. Cruelty is «la cruauté».","v":"c8091082","transp":"total","pos":3027},{"idioma":"fr","id":"fr-p461","tipo":"palavra","fr":"la bombe","en":"the bomb","aceitasEn":["bomb","the bomb","spray can","the spray can","aerosol","the aerosol"],"distratoresEn":["the bullet","the balloon","the dove","the light bulb"],"nivel":"B2","tags":["mídia"],"notaEn":"Feminine. Besides the explosive, it's a spray can: «une bombe de peinture», a can of spray paint. A water or gas pump is «la pompe».","v":"e1475d26","pos":3076},{"idioma":"fr","id":"fr-p462","tipo":"palavra","fr":"régulier","aceitasFr":["régulière"],"en":"regular","aceitasEn":["regular","steady","even","consistent","frequent","scheduled"],"distratoresEn":["rare","rigid","mediocre","rapid"],"nivel":"B2","tags":["adjetivo","cotidiano"],"notaEn":"Feminine «régulière». Steady or frequent: «un client régulier», a regular customer; «à intervalles réguliers», at regular intervals. «Un vol régulier» is a scheduled flight.","v":"405dfbb9","pos":3128},{"idioma":"fr","id":"fr-p463","tipo":"palavra","fr":"la librairie","en":"the bookstore","aceitasEn":["bookstore","the bookstore","bookshop","the bookshop"],"distratoresEn":["the stationery store","the print shop","the bakery","the laundromat"],"nivel":"B2","tags":["compras","falso-amigo"],"notaEn":"False friend: not a library but a bookstore, where books are sold. A library is «la bibliothèque»; a bookseller, «le libraire».","v":"febdf880","pos":3179},{"idioma":"fr","id":"fr-p464","tipo":"palavra","fr":"le verrou","sinonimosFr":["le loquet"],"en":"the bolt","aceitasEn":["bolt","the bolt","latch","the latch","deadbolt","the deadbolt","lock","the lock"],"distratoresEn":["the hinge","the handle","the glass","the screw"],"nivel":"B2","tags":["casa"],"notaEn":"Masculine. A door bolt: «mettre le verrou», to bolt the door. «Sous les verrous», behind bars. A keyed lock is «la serrure».","v":"f26657e0","pos":3228},{"idioma":"fr","id":"fr-p465","tipo":"palavra","fr":"l'étiquette","en":"the label","aceitasEn":["label","the label","tag","the tag","price tag","the price tag","sticker","the sticker","etiquette"],"distratoresEn":["the stage","the packaging","the receipt","the bag"],"nivel":"B2","tags":["compras"],"notaEn":"Feminine. A label or price tag, and also etiquette, the rules of manners. Don't confuse it with «l'étape», a stage.","v":"4259922c","pos":3281},{"idioma":"fr","id":"fr-p466","tipo":"palavra","fr":"exploiter","en":"to exploit","aceitasEn":["to exploit","exploit","to operate","operate","to make use of","make use of","to take advantage of","take advantage of"],"distratoresEn":["to explore","to export","to expel","to explain"],"nivel":"B2","tags":["verbo","economia"],"notaEn":"To exploit, and also to run or operate: «exploiter une ferme», to run a farm; «exploiter une mine», to work a mine. To explore is «explorer».","v":"47948c69","pos":3329},{"idioma":"fr","id":"fr-p467","tipo":"palavra","fr":"le recours","en":"recourse","aceitasEn":["recourse","the recourse","resort","the resort","appeal","the appeal","remedy","legal remedy"],"distratoresEn":["route","contest","speech","return"],"nivel":"B2","tags":["jurídico"],"notaEn":"Masculine. «Avoir recours à», to resort to; «en dernier recours», as a last resort. In law, an appeal against a decision. Resources are «les ressources».","v":"efbd6bb6","transp":"parecida","pos":3379},{"idioma":"fr","id":"fr-p468","tipo":"palavra","fr":"toutefois","sinonimosFr":["cependant","pourtant","néanmoins"],"en":"however","aceitasEn":["however","nevertheless","nonetheless","yet","still","even so","though"],"distratoresEn":["every time","therefore","moreover","suddenly"],"nivel":"B2","tags":["escola","formal"],"notaEn":"More formal than «mais» or «pourtant», and mostly written: «c'est cher ; toutefois, ça vaut le coup», it's expensive; however, it's worth it. It comes from «toutes fois», but doesn't mean every time.","v":"b44e2512","pos":3430},{"idioma":"fr","id":"fr-p469","tipo":"palavra","fr":"affecter","en":"to affect","aceitasEn":["to affect","affect","to upset","upset","to assign","assign","to allocate","allocate","to post"],"distratoresEn":["to carry out","to sharpen","to push away","to tune"],"nivel":"B2","tags":["verbo","trabalho"],"notaEn":"To affect («la crise affecte l'économie»), also to upset. At work it means to assign or post: «il a été affecté à Lyon», he was posted to Lyon.","v":"ad3d2672","pos":3479},{"idioma":"fr","id":"fr-p470","tipo":"palavra","fr":"la suggestion","en":"the suggestion","aceitasEn":["suggestion","the suggestion","proposal","the proposal"],"distratoresEn":["the digestion","the management","the question","the complaint"],"nivel":"B2","tags":["trabalho"],"notaEn":"Feminine, with a double «g», as in English. «Faire une suggestion», to make a suggestion; to suggest is «suggérer».","v":"e84cd864","transp":"total","pos":3528},{"idioma":"fr","id":"fr-p471","tipo":"palavra","fr":"tolérer","sinonimosFr":["supporter"],"en":"to tolerate","aceitasEn":["to tolerate","tolerate","to put up with","put up with","to bear","bear","to stand","stand"],"distratoresEn":["to hate","to fear","to demand","to forbid"],"nivel":"B2","tags":["verbo","social"],"notaEn":"To tolerate, to put up with: «je ne tolère pas le retard», I won't put up with lateness. Also to allow without authorizing: «le stationnement est toléré». The accent changes: «tolérer», but «je tolère».","v":"77e7df82","pos":3578},{"idioma":"fr","id":"fr-p472","tipo":"palavra","fr":"quelconque","en":"any / mediocre","aceitasEn":["any","some","whatever","some or other","mediocre","nondescript","unremarkable","plain"],"distratoresEn":["each / special","every / remarkable","only / excellent","same / strange"],"nivel":"B2","tags":["adjetivo","cotidiano"],"notaEn":"After a noun, it means any, some or other: «pour une raison quelconque», for some reason or other. With «très», or after a verb, it's dismissive: «un film très quelconque», a very mediocre film.","v":"89c8ce88","pos":3627},{"idioma":"fr","id":"fr-p473","tipo":"palavra","fr":"le consommateur","en":"the consumer","aceitasEn":["consumer","the consumer"],"distratoresEn":["the consumption","the supplier","the producer","the seller"],"nivel":"B2","tags":["compras","economia"],"notaEn":"Masculine; feminine «consommatrice». In a café it's also the paying customer: «terrasse réservée aux consommateurs». Consumption is «la consommation».","v":"ee66ad56","pos":3677},{"idioma":"fr","id":"fr-p474","tipo":"palavra","fr":"naviguer","en":"to sail","aceitasEn":["to sail","sail","to navigate","navigate","to browse","browse","to surf","surf"],"distratoresEn":["to swim","to dive","to sink","to anchor"],"nivel":"B2","tags":["verbo","viagem"],"notaEn":"To sail, and to browse: «naviguer sur Internet». The «u» after the «g» stays in every form: «nous naviguons». A ship is «un navire».","v":"fd8e8cc3","pos":3727},{"idioma":"fr","id":"fr-p475","tipo":"palavra","fr":"naïf","aceitasFr":["naïve"],"en":"naive","aceitasEn":["naive","naïve","innocent","gullible","credulous"],"distratoresEn":["shrewd","native","nervous","vain"],"nivel":"B2","tags":["adjetivo","social"],"notaEn":"Feminine «naïve». The diaeresis splits the vowels: na-if. «Ne sois pas si naïf», don't be so naive; in painting, «l'art naïf» is naive art.","v":"be455cfc","pos":3784},{"idioma":"fr","id":"fr-p476","tipo":"palavra","fr":"se remarier","en":"to remarry","aceitasEn":["to remarry","remarry","to marry again","marry again","to get married again","get married again"],"distratoresEn":["to divorce","to separate","to get engaged","to move house"],"nivel":"C1","tags":["verbo","família"],"notaEn":"The «re-» of doing again: «elle s'est remariée avec un collègue», she remarried a colleague. Like «se marier», it takes «avec» rather than a direct object, and «être» in the past.","v":"16836b5b","pos":3846},{"idioma":"fr","id":"fr-p477","tipo":"palavra","fr":"le tirage","aceitasFr":["un tirage"],"en":"the draw / the print run","aceitasEn":["the draw","draw","the drawing","drawing","the print run","print run","the circulation","circulation","the print","print"],"distratoresEn":["the auction / the subscription","the bet / the headline","the prize / the ink","the refund / the cover"],"nivel":"C1","tags":["mídia"],"notaEn":"From «tirer», to pull or draw: «le tirage au sort», the drawing of lots; «le tirage d'un journal», a newspaper's circulation. In photography, a print.","v":"2776a227","pos":3908},{"idioma":"fr","id":"fr-p478","tipo":"palavra","fr":"les fiançailles","en":"the engagement","aceitasEn":["engagement","the engagement","betrothal","the betrothal"],"distratoresEn":["the wedding","the divorce","the honeymoon","the christening"],"nivel":"B2","tags":["família"],"notaEn":"Plural only, and feminine: «leurs fiançailles», their engagement. The fiancé is «le fiancé», and to get engaged is «se fiancer». Careful: «l'engagement» is a commitment, not this.","v":"7f3befbe","pos":3970},{"idioma":"fr","id":"fr-p479","tipo":"palavra","fr":"le journalisme","en":"journalism","aceitasEn":["journalism","the journalism"],"distratoresEn":["advertising","photography","tourism","politics"],"nivel":"B2","tags":["mídia"],"notaEn":"Masculine, like all «-isme» nouns: «faire du journalisme», to work in journalism. A journalist is «un journaliste»; the newspaper, «le journal», from «jour», day.","v":"cb6ed6ae","transp":"parecida","pos":4032},{"idioma":"fr","id":"fr-p480","tipo":"palavra","fr":"égyptien","aceitasFr":["égyptienne"],"en":"Egyptian","aceitasEn":["egyptian"],"distratoresEn":["Ethiopian","Moroccan","Lebanese","Syrian"],"nivel":"B1","tags":["adjetivo","cultura"],"notaEn":"Feminine «égyptienne», with a double «n». Lowercase as an adjective, capitalized for the people: «les Égyptiens». The country is feminine: «l'Égypte», «en Égypte».","v":"59420100","transp":"parecida","pos":4094},{"idioma":"fr","id":"fr-p481","tipo":"palavra","fr":"susceptible","en":"touchy","aceitasEn":["touchy","oversensitive","thin-skinned","sensitive","easily offended","prickly","liable","liable to","likely","likely to"],"distratoresEn":["suspicious","suspended","sustainable","calm"],"nivel":"B2","tags":["adjetivo","social"],"notaEn":"Same form in the feminine. Mostly touchy, easily offended: «il est très susceptible». With «de», liable to: «un prix susceptible de changer», a price that may change. Prone to an illness is rather «sujet à».","v":"2e666762","pos":4157},{"idioma":"fr","id":"fr-p482","tipo":"palavra","fr":"la participation","en":"participation","aceitasEn":["participation","the participation","involvement","share","stake","contribution","turnout"],"distratoresEn":["departure","preparation","partnership","absence"],"nivel":"B2","tags":["social"],"notaEn":"Takes «à»: «la participation à la réunion». «La participation aux frais» is a share of the costs, and «le taux de participation», voter turnout.","v":"20712880","transp":"total","pos":4221},{"idioma":"fr","id":"fr-p483","tipo":"palavra","fr":"fleurir","en":"to bloom","aceitasEn":["to bloom","bloom","to flower","flower","to blossom","blossom","to flourish","flourish","to thrive","thrive"],"distratoresEn":["to wilt","to water","to harvest","to prune"],"nivel":"B2","tags":["verbo","natureza"],"notaEn":"To bloom: «les cerisiers fleurissent en avril». With an object, to decorate with flowers: «fleurir une tombe». Meaning to thrive, the imperfect changes stem: «le commerce florissait».","v":"3b49489a","pos":4283},{"idioma":"fr","id":"fr-p484","tipo":"palavra","fr":"l'agenda","aceitasFr":["un agenda"],"en":"the planner","aceitasEn":["planner","the planner","diary","the diary","datebook","the datebook","calendar","the calendar","appointment book","the appointment book","agenda","the agenda"],"distratoresEn":["the notebook","the folder","the wallet","the handout"],"nivel":"B1","tags":["trabalho"],"notaEn":"Masculine: «mon agenda est plein», my calendar is full. It's the planner, on paper or on a phone; a meeting's agenda is «l'ordre du jour».","v":"83eb6cb3","pos":4346},{"idioma":"fr","id":"fr-p485","tipo":"palavra","fr":"le disciple","aceitasFr":["un disciple","la disciple","une disciple"],"en":"the disciple","aceitasEn":["disciple","the disciple","follower","the follower","pupil","the pupil"],"distratoresEn":["the master","the prophet","the rival","the heir"],"nivel":"C1","tags":["cultura"],"notaEn":"One form for both genders: «un disciple», «une disciple». A master's follower: «les disciples de Socrate». Discipline is «la discipline».","v":"d3c5fd12","transp":"total","pos":4409},{"idioma":"fr","id":"fr-p486","tipo":"palavra","fr":"humble","en":"humble","aceitasEn":["humble","modest","lowly"],"distratoresEn":["proud","humid","honest","arrogant"],"nivel":"B2","tags":["adjetivo","social"],"notaEn":"Same form in the feminine, and the «h» is silent: «l'humble». It often comes before the noun: «à mon humble avis», in my humble opinion. Humid is «humide».","v":"5d0e1c8f","transp":"total","pos":4471},{"idioma":"fr","id":"fr-p487","tipo":"palavra","fr":"solliciter","en":"to request","aceitasEn":["to request","request","to solicit","solicit","to ask for","ask for","to apply for","apply for","to seek","seek"],"distratoresEn":["to release","to solve","to console","to refuse"],"nivel":"C1","tags":["verbo","trabalho","formal"],"notaEn":"Formal, with a double «l»: «solliciter un entretien», to request an interview; «solliciter un poste», to apply for a job. It also means to put strain on: «ce sport sollicite les genoux».","v":"320c1a79","pos":4533},{"idioma":"fr","id":"fr-p488","tipo":"palavra","fr":"la destruction","en":"destruction","aceitasEn":["destruction","the destruction"],"distratoresEn":["construction","distraction","instruction","restoration"],"nivel":"B2","tags":["cotidiano"],"notaEn":"Feminine, like every «-tion» noun. The verb is «détruire», past participle «détruit»: «la ville a été détruite», the city was destroyed.","v":"26762c50","transp":"total","pos":4595},{"idioma":"fr","id":"fr-p489","tipo":"palavra","fr":"le conduit","aceitasFr":["un conduit"],"en":"the duct","aceitasEn":["duct","the duct","conduit","the conduit","pipe","the pipe","channel","the channel","canal","the canal","tube","the tube"],"distratoresEn":["the behavior","the filter","the screw","the driver"],"nivel":"C1","tags":["casa"],"notaEn":"Masculine, no final «e»: «le conduit d'aération», the air duct; «le conduit auditif», the ear canal. With an «e», «la conduite» is behavior, and also driving.","v":"d6a16d36","pos":4658},{"idioma":"fr","id":"fr-p490","tipo":"palavra","fr":"l'automobile","aceitasFr":["une automobile","l'auto","une auto"],"en":"the automobile","aceitasEn":["automobile","the automobile","auto","the auto","motorcar"],"distratoresEn":["the truck","the bus","the boat","the airplane"],"nivel":"B2","tags":["cidade"],"notaEn":"Feminine: «une automobile». Everyday French says «la voiture»; «automobile» is for the industry: «l'industrie automobile», «le Salon de l'automobile», the motor show.","v":"e72bd9b9","transp":"total","pos":4721},{"idioma":"fr","id":"fr-p491","tipo":"palavra","fr":"infiltrer","en":"to infiltrate","aceitasEn":["to infiltrate","infiltrate","to penetrate","penetrate","to seep into","seep into","to seep","seep"],"distratoresEn":["to inflict","to inflate","to inform","to expel"],"nivel":"C1","tags":["verbo","política"],"notaEn":"With an object, for people: «infiltrer un réseau», to infiltrate a network. For liquids, it's reflexive: «l'eau s'infiltre dans le mur», water seeps into the wall.","v":"17216dfb","pos":4783},{"idioma":"fr","id":"fr-p492","tipo":"palavra","fr":"parallèle","en":"parallel","aceitasEn":["parallel"],"distratoresEn":["perpendicular","diagonal","vertical","horizontal"],"nivel":"B2","tags":["adjetivo","escola"],"notaEn":"Same form in the feminine: «une rue parallèle». Spelled with «ll» before the «è». «En parallèle», at the same time; «le marché parallèle», the black market.","v":"f4bce4f1","transp":"parecida","pos":4846},{"idioma":"fr","id":"fr-p493","tipo":"palavra","fr":"la dentelle","en":"lace (fabric)","aceitasEn":["lace","the lace"],"distratoresEn":["silk (fabric)","velvet (fabric)","linen (fabric)","gauze (fabric)"],"nivel":"C1","tags":["roupa"],"notaEn":"Feminine: «une robe en dentelle», a lace dress. «Ne pas faire dans la dentelle» means to be anything but subtle. A shoelace is «un lacet».","v":"ba583789","pos":4908},{"idioma":"fr","id":"fr-p494","tipo":"palavra","fr":"verbal","aceitasFr":["verbale"],"en":"verbal","aceitasEn":["verbal","oral","spoken"],"distratoresEn":["visual","written","nominal","mental"],"nivel":"B2","tags":["adjetivo","escola"],"notaEn":"Feminine «verbale», plural «verbaux». «Un accord verbal» is a spoken agreement, nothing on paper. «Le procès-verbal» is the minutes, and also a traffic ticket.","v":"e0c5dc66","transp":"total","pos":4970},{"idioma":"fr","id":"fr-p495","tipo":"palavra","fr":"implorer","en":"to beg","aceitasEn":["to beg","beg","to implore","implore","to plead","plead","to plead with","to beseech","beseech"],"distratoresEn":["to explore","to deplore","to refuse","to thank"],"nivel":"C2","tags":["verbo","social"],"notaEn":"The person is a direct object, and the action takes «de»: «il m'a imploré de rester», he begged me to stay. In everyday speech «supplier» is more common: «je t'en supplie», I'm begging you.","v":"25236972","pos":5013},{"idioma":"fr","id":"fr-p496","tipo":"palavra","fr":"le coiffeur","aceitasFr":["la coiffeuse"],"en":"the hairdresser","aceitasEn":["hairdresser","the hairdresser","hairstylist","the hairstylist","hair stylist","stylist"],"distratoresEn":["the cook","the tailor","the gardener","the mail carrier"],"nivel":"A2","tags":["profissões","cotidiano"],"notaEn":"Feminine «la coiffeuse», which is also a dressing table. «Aller chez le coiffeur», to go to the hairdresser's. From «coiffer», to do someone's hair; «la coiffure» is the hairstyle.","v":"e34ce48a","pos":5038},{"idioma":"fr","id":"fr-p497","tipo":"palavra","fr":"clandestin","aceitasFr":["clandestine"],"en":"clandestine","aceitasEn":["clandestine","illegal","undocumented","secret","underground","covert"],"distratoresEn":["official","authorized","dangerous","temporary"],"nivel":"B2","tags":["adjetivo","política"],"notaEn":"Feminine «clandestine». Common in the news: «un travailleur clandestin», an undocumented worker; «un passager clandestin», a stowaway. As a noun, «les clandestins» are undocumented migrants.","v":"81e3880c","transp":"parecida","pos":5061},{"idioma":"fr","id":"fr-p498","tipo":"palavra","fr":"s'aventurer","en":"to venture","aceitasEn":["to venture","venture","to venture out","venture out","to venture into","to risk","to dare","dare"],"distratoresEn":["to settle in","to hide","to have fun","to regret"],"nivel":"C1","tags":["verbo","viagem"],"notaEn":"With «dans» for a place: «s'aventurer dans la forêt», to venture into the forest; with «à» for a risky act: «je ne m'aventurerais pas à le dire», I wouldn't venture to say so. Past tense with «être»: «elle s'est aventurée».","v":"c6fbcd29","pos":5085},{"idioma":"fr","id":"fr-p499","tipo":"palavra","fr":"la rubrique","en":"the section (of a newspaper)","aceitasEn":["section","the section","column","the column","heading","category","rubric"],"distratoresEn":["the headline (of a newspaper)","the circulation (of a newspaper)","the margin (of a page)","the signature (on a document)"],"nivel":"B2","tags":["mídia","falso-amigo"],"notaEn":"A section of a newspaper, magazine or website: «la rubrique cinéma», the film section; also a heading in a list. Not a grading rubric, which is «une grille d'évaluation».","v":"487bcece","pos":5108},{"idioma":"fr","id":"fr-p500","tipo":"palavra","fr":"l'éloge","aceitasFr":["un éloge"],"en":"praise","aceitasEn":["praise","the praise","eulogy","the eulogy","tribute","acclaim"],"distratoresEn":["criticism","mockery","advice","blame"],"nivel":"C2","tags":["social"],"notaEn":"Masculine despite the «-e»: «un éloge». «Faire l'éloge de», to praise; «l'éloge funèbre», the eulogy. Everyday praise for an outfit or a dish is «un compliment».","v":"df6d2def","pos":5132},{"idioma":"fr","id":"fr-p501","tipo":"palavra","fr":"l'initiation","en":"initiation","aceitasEn":["initiation","the initiation","introduction","the introduction","induction"],"distratoresEn":["imitation","enrollment","innovation","conclusion"],"nivel":"B2","tags":["escola"],"notaEn":"Besides the rite, a first taste of a subject: «un cours d'initiation à la photo», an introductory photography course. It takes «à»: «une initiation au yoga».","v":"1897939a","transp":"total","pos":5156},{"idioma":"fr","id":"fr-p502","tipo":"palavra","fr":"le vétéran","en":"the veteran","aceitasEn":["veteran","the veteran","war veteran","old hand"],"distratoresEn":["the newcomer","the recruit","the deserter","the heir"],"nivel":"C2","tags":["social"],"notaEn":"A former soldier («un vétéran de la guerre d'Algérie») or anyone long in a field: «un vétéran du cinéma». In sports, «les vétérans» are the masters category.","v":"0024770a","transp":"total","pos":5180},{"idioma":"fr","id":"fr-p503","tipo":"palavra","fr":"la fabrication","en":"manufacturing","aceitasEn":["manufacturing","manufacture","the manufacture","production","making","fabrication"],"distratoresEn":["sales","packaging","delivery","deceit"],"nivel":"B2","tags":["trabalho","economia","falso-amigo"],"notaEn":"Making things, not making things up: «de fabrication française», made in France. A made-up story is «une invention» or «un mensonge». The verb is «fabriquer»; the factory is «l'usine».","v":"7649c5e5","pos":5203},{"idioma":"fr","id":"fr-p504","tipo":"palavra","fr":"honnêtement","en":"honestly","aceitasEn":["honestly","frankly","sincerely","truthfully","to be honest","decently","fairly"],"distratoresEn":["humbly","luckily","probably","discreetly"],"nivel":"B1","tags":["cotidiano"],"notaEn":"From «honnête», honest, with a double «n» and «ê». At the start of a sentence: «Honnêtement, je n'en sais rien», honestly, I have no idea. Also decently: «c'est honnêtement payé», the pay is fair.","v":"b528f33a","pos":5227},{"idioma":"fr","id":"fr-p505","tipo":"palavra","fr":"le livret","en":"the booklet","aceitasEn":["booklet","the booklet","passbook","bankbook","libretto","record book","little book"],"distratoresEn":["the bookstore","the label","the drawer","the folder"],"nivel":"B2","tags":["escola","economia"],"notaEn":"A small record book: «le livret scolaire», the school report book; «le livret de famille», the family record book issued at marriage; «le livret A», France's most popular savings account. In opera, the libretto.","v":"322f7dbe","pos":5251},{"idioma":"fr","id":"fr-p506","tipo":"palavra","fr":"le détecteur","en":"the detector","aceitasEn":["detector","the detector"],"distratoresEn":["the extinguisher","the projector","the regulator","the heater"],"nivel":"B2","tags":["objetos","tecnologia"],"notaEn":"«Le détecteur de fumée», the smoke detector, required in every home in France; «le détecteur de métaux», the metal detector. The verb is «détecter».","v":"36fc4f53","transp":"parecida","pos":5275},{"idioma":"fr","id":"fr-p507","tipo":"palavra","fr":"la mayonnaise","aceitasFr":["la mayo"],"en":"mayonnaise","aceitasEn":["mayonnaise","the mayonnaise","mayo"],"distratoresEn":["mustard","butter","vinegar","oil"],"nivel":"A2","tags":["comida"],"notaEn":"Feminine. «Monter une mayonnaise», to whisk up mayonnaise; figuratively, «la mayonnaise prend», things are coming together. Informally, «la mayo».","v":"6f5743aa","transp":"total","pos":5299},{"idioma":"fr","id":"fr-p508","tipo":"palavra","fr":"la vogue","sinonimosFr":["la mode"],"en":"vogue","aceitasEn":["vogue","the vogue","in vogue"],"distratoresEn":["voice","will","vanity","crisis"],"nivel":"C1","tags":["cultura"],"notaEn":"Mostly in «en vogue», as in English: «un mot très en vogue». «La vogue de», the craze for: «la vogue des séries». Everyday fashion is «la mode»; a wave is «la vague».","v":"dd0ad752","transp":"total","pos":5322},{"idioma":"fr","id":"fr-p509","tipo":"palavra","fr":"le faîte","en":"the top","aceitasEn":["top","the top","summit","the summit","peak","the peak","height","the height","pinnacle","apex","ridge","the ridge","crest"],"distratoresEn":["the fact","the party","the bottom","the base"],"nivel":"C2","tags":["natureza"],"notaEn":"A literary word for the highest point of a roof (the ridge), a tree or a mountain. Mostly figurative: «au faîte de la gloire», at the height of fame. It sounds just like «la fête», the party.","v":"872f33a3","pos":5348},{"idioma":"fr","id":"fr-u474","tipo":"frase","requer":"fr-p385","fr":"Comment tu as fait ça ?","aceitasFr":["Comment as-tu fait ça ?","Tu as fait ça comment ?","Comment est-ce que tu as fait ça ?","Comment vous avez fait ça ?","Comment avez-vous fait ça ?"],"en":"How did you do that?","aceitasEn":["how did you do that","how did you do it","how did you do this","how did you manage that","how did you manage to do that"],"distratoresEn":["Why did you do that?","When did you do that?","Where did you do that?","Who did you do that with?"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Comment» asks about the manner: how? In speech it can also go last: «Tu as fait ça comment ?». «As fait» is the passé composé, built with «avoir»: did.","requerTodas":["fr-p385","fr-p002","fr-p004"],"v":"f3201537"},{"idioma":"fr","id":"fr-u475","tipo":"frase","requer":"fr-p385","fr":"Comment est ta nouvelle maison ?","aceitasFr":["Elle est comment, ta nouvelle maison ?","Ta nouvelle maison est comment ?","Comment est votre nouvelle maison ?"],"en":"What's your new house like?","aceitasEn":["whats your new house like","what is your new house like","how is your new house","hows your new house","whats your new home like","what is your new home like","how is your new home"],"distratoresEn":["Where's your new house?","Which one is your new house?","What color is your new house?","How big is your new house?"],"nivel":"A1","tags":["casa","cotidiano"],"notaEn":"To ask what something is like, French uses «comment» + «être»: «Comment est… ?», literally how is…? In speech it often goes last: «Elle est comment, ta maison ?». «Nouvelle», the feminine of «nouveau», comes before the noun.","requerTodas":["fr-p385","fr-p001","fr-p039","fr-p020"],"v":"9e974929"},{"idioma":"fr","id":"fr-u476","tipo":"frase","requer":"fr-p386","fr":"C'est un garçon très gentil.","en":"He's a very nice boy.","aceitasEn":["hes a very nice boy","he is a very nice boy","hes a very kind boy","he is a very kind boy","hes a really nice boy","hes a very sweet boy","hes a very nice kid","hes a very nice young man","hes a very kind young man"],"distratoresEn":["He's a very nice man.","He's a very nice gentleman.","He's a very nice waiter.","He's a very nice neighbor."],"nivel":"A1","tags":["família"],"notaEn":"«Le garçon» is a boy or a young man. A waiter today is «le serveur»; «garçon» for a waiter is dated. «C'est un…» introduces someone: he's a… «Gentil» means kind, nice.","requerTodas":["fr-p001","fr-p386","fr-p043","fr-p124"],"v":"2ac75eb2"},{"idioma":"fr","id":"fr-u477","tipo":"frase","requer":"fr-p387","fr":"De toute façon, je n'ai pas le temps.","aceitasFr":["De toute façon, j'ai pas le temps."],"en":"Anyway, I don't have time.","aceitasEn":["anyway i dont have time","anyway i do not have time","anyway i have no time","anyway i havent got time","anyway i dont have the time","anyhow i dont have time","in any case i dont have time","either way i dont have time"],"distratoresEn":["That way, I don't have time.","For now, I don't have time.","That's why I don't have time.","This week, I don't have time."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«De toute façon», anyway, in any case: it closes the matter. «Façon» is feminine, and «ç» sounds like «s». French says «avoir le temps», with the article: to have time.","requerTodas":["fr-p387","fr-p070","fr-p002","fr-p025"],"v":"ba485c21"},{"idioma":"fr","id":"fr-u478","tipo":"frase","requer":"fr-p387","fr":"Je n'aime pas sa façon de parler.","aceitasFr":["J'aime pas sa façon de parler."],"en":"I don't like his way of talking.","aceitasEn":["i dont like his way of talking","i dont like her way of talking","i do not like his way of talking","i dont like his way of speaking","i dont like her way of speaking","i dont like the way he talks","i dont like the way she talks","i dont like the way he speaks","i dont like the way she speaks","i dont like how he talks","i dont like how she talks"],"distratoresEn":["I don't like his habit of talking.","I don't like his fear of talking.","I don't like his love of talking.","I don't like his reason for talking."],"nivel":"A1","tags":["cotidiano","social"],"notaEn":"«Sa façon de» + infinitive: someone's way of doing something. «Sa» agrees with «façon», which is feminine, not with the owner: it can be his or her.","requerTodas":["fr-p015","fr-p387","fr-p012"],"v":"750de02d"},{"idioma":"fr","id":"fr-u479","tipo":"frase","requer":"fr-p388","fr":"Le sport, c'est bon pour le corps.","aceitasFr":["Le sport est bon pour le corps."],"en":"Exercise is good for the body.","aceitasEn":["exercise is good for the body","exercise is good for your body","sport is good for the body","sport is good for your body","sports are good for the body","sports are good for your body","playing sports is good for the body"],"distratoresEn":["Exercise is good for the heart.","Exercise is good for the brain.","Exercise is good for the mind.","Exercise is good for the skin."],"nivel":"A1","tags":["corpo","saúde"],"notaEn":"«Le corps» ends in a silent «-ps»: it sounds like «cor». The comma plus «c'est» is very French: name the topic, then comment on it, «le sport, c'est bon».","requerTodas":["fr-p161","fr-p001","fr-p036","fr-p388"],"v":"7409b4bf"},{"idioma":"fr","id":"fr-u480","tipo":"frase","requer":"fr-p389","fr":"J'aime tous les sports, surtout le foot.","aceitasFr":["J'aime tous les sports, surtout le football."],"en":"I like all sports, especially soccer.","aceitasEn":["i like all sports especially soccer","i like all sports especially football","i love all sports especially soccer","i like every sport especially soccer","i like all sports particularly soccer","i like all sports above all soccer","i like all sports mostly soccer"],"distratoresEn":["I like all sports, except soccer.","I like all sports, but not soccer.","I like all sports, including soccer.","I like all sports, even soccer."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Surtout» singles one out: especially, above all («sur» + «tout»). It comes right before what it highlights. «Le foot» is short for «le football», soccer.","requerTodas":["fr-p015","fr-p070","fr-p161","fr-p389","fr-p149"],"v":"3422c170"},{"idioma":"fr","id":"fr-u481","tipo":"frase","requer":"fr-p389","fr":"Surtout pas !","en":"Definitely not!","aceitasEn":["definitely not","absolutely not","certainly not","no way","by no means"],"distratoresEn":["Not everything!","Not yet!","Of course!","Maybe!"],"nivel":"A1","tags":["expressão","cotidiano"],"notaEn":"«Surtout pas !», definitely not, whatever you do, don't: the firm reply to a suggestion («Je l'appelle ? — Surtout pas !»). It isn't not everything, which is «pas tout».","requerTodas":["fr-p389"],"v":"8e140319"},{"idioma":"fr","id":"fr-u482","tipo":"frase","requer":"fr-p390","fr":"Tu te souviens de moi ?","aceitasFr":["Est-ce que tu te souviens de moi ?","Te souviens-tu de moi ?","Vous vous souvenez de moi ?"],"en":"Do you remember me?","aceitasEn":["do you remember me","you remember me"],"distratoresEn":["Do you like me?","Do you need me?","Do you miss me?","Do you trust me?"],"nivel":"A1","tags":["verbo","social"],"notaEn":"«Se souvenir» is reflexive and takes «de»: «je me souviens de toi», I remember you. The pronoun changes with the person: je me, tu te, il se. It's conjugated like «venir».","requerTodas":["fr-p390"],"v":"207d2fb1"},{"idioma":"fr","id":"fr-u483","tipo":"frase","requer":"fr-p390","fr":"Je ne me souviens pas de son nom.","aceitasFr":["Je me souviens pas de son nom."],"en":"I don't remember his name.","aceitasEn":["i dont remember his name","i dont remember her name","i do not remember his name","i do not remember her name","i cant remember his name","i cant remember her name","i cannot remember his name","i cannot remember her name"],"distratoresEn":["I don't like his name.","I don't need his name.","I don't know his name.","I don't get his name."],"nivel":"A1","tags":["verbo","cotidiano"],"notaEn":"In the negative, «ne… pas» wraps around the pronoun and the verb: «je ne me souviens pas». In speech the «ne» drops: «je me souviens pas». «Son nom» can be his or her name.","requerTodas":["fr-p390","fr-p217"],"v":"7147c1ed"},{"idioma":"fr","id":"fr-u484","tipo":"frase","requer":"fr-p391","fr":"Il y a beaucoup de clients aujourd'hui.","aceitasFr":["Aujourd'hui, il y a beaucoup de clients."],"en":"There are a lot of customers today.","aceitasEn":["there are a lot of customers today","there are lots of customers today","there are many customers today","there are a lot of clients today","there are many clients today","theres a lot of customers today","today there are a lot of customers"],"distratoresEn":["There are a lot of tourists today.","There are a lot of students today.","There are a lot of patients today.","There are a lot of cars today."],"nivel":"A1","tags":["compras","trabalho"],"notaEn":"«Il y a», there is, there are: it doesn't change in the plural. After «beaucoup», just «de», no article: «beaucoup de clients». «Le client» is a customer as well as a client.","requerTodas":["fr-p002","fr-p067","fr-p391","fr-p049"],"v":"39abf0a1"},{"idioma":"fr","id":"fr-u485","tipo":"frase","requer":"fr-p391","fr":"Le client a toujours raison.","en":"The customer is always right.","aceitasEn":["the customer is always right","the client is always right","the customers always right"],"distratoresEn":["The boss is always right.","The teacher is always right.","The doctor is always right.","The waiter is always right."],"nivel":"A1","tags":["compras","trabalho"],"notaEn":"French says the customer «a raison», has reason: «avoir raison», to be right. The opposite is «avoir tort», to be wrong. «Toujours» comes right after the verb.","requerTodas":["fr-p391","fr-p002","fr-p046","fr-p141"],"v":"fe40d50e"},{"idioma":"fr","id":"fr-u486","tipo":"frase","requer":"fr-p392","fr":"C'est une sorte de gâteau au fromage.","en":"It's a sort of cheesecake.","aceitasEn":["its a sort of cheesecake","its a kind of cheesecake","its a type of cheesecake","it is a sort of cheesecake","it is a kind of cheesecake","its some kind of cheesecake","its sort of a cheesecake","its kind of a cheesecake","its a sort of cheese cake","its a kind of cheese cake"],"distratoresEn":["It's a slice of cheesecake.","It's a piece of cheesecake.","It's a bit of cheesecake.","It's a recipe for cheesecake."],"nivel":"B1","tags":["comida","cotidiano"],"notaEn":"«Une sorte de», a sort of, a kind of: that's how «la sorte» nearly always appears, and it's feminine. «Au fromage» names the main ingredient: «une tarte aux pommes», an apple tart.","requerTodas":["fr-p001","fr-p392","fr-p150","fr-p280"],"v":"f72a58a5"},{"idioma":"fr","id":"fr-u487","tipo":"frase","requer":"fr-p392","fr":"En quelque sorte, oui.","en":"In a way, yes.","aceitasEn":["in a way yes","in some ways yes","in a sense yes","in a manner of speaking yes","so to speak yes","sort of yes","kind of yes","yes in a way"],"distratoresEn":["Luckily, yes.","Sometimes, yes.","Certainly, yes.","For now, yes."],"nivel":"B1","tags":["expressão","cotidiano"],"notaEn":"«En quelque sorte», in a way, so to speak: half agreeing, or softening what you say. «Quelque» here means some, a certain: literally in some sort.","requerTodas":["fr-p392"],"v":"d5b91725"},{"idioma":"fr","id":"fr-u488","tipo":"frase","requer":"fr-p393","fr":"Le président parle à la télé ce soir.","aceitasFr":["Ce soir, le président parle à la télé.","Le président parle à la télévision ce soir.","Le président va parler à la télé ce soir."],"en":"The president is speaking on TV tonight.","aceitasEn":["the president is speaking on tv tonight","the president is talking on tv tonight","the president speaks on tv tonight","the president will speak on tv tonight","the president will be speaking on tv tonight","the president is going to speak on tv tonight","the president is speaking on television tonight","the president is on tv tonight","tonight the president is speaking on tv"],"distratoresEn":["The mayor is speaking on TV tonight.","The minister is speaking on TV tonight.","The king is speaking on TV tonight.","The pope is speaking on TV tonight."],"nivel":"A1","tags":["política","mídia"],"notaEn":"The present tense also covers what's scheduled: «il parle ce soir», he's speaking tonight. On TV is «à la télé», and tonight is «ce soir». A female president is «la présidente».","requerTodas":["fr-p393","fr-p012","fr-p225","fr-p160"],"v":"45bf902b"},{"idioma":"fr","id":"fr-u489","tipo":"frase","requer":"fr-p394","fr":"Une mère protège toujours ses enfants.","en":"A mother always protects her children.","aceitasEn":["a mother always protects her children","a mother always protects her kids","a mother will always protect her children","a mother will always protect her kids","mothers always protect their children"],"distratoresEn":["A mother always loves her children.","A mother always helps her children.","A mother always listens to her children.","A mother always understands her children."],"nivel":"A1","tags":["verbo","família"],"notaEn":"The accent shifts with the syllable: «je protège», but «nous protégeons». «Toujours» goes right after the verb, not before it as always does in English.","requerTodas":["fr-p063","fr-p394","fr-p046","fr-p023"],"v":"69047f2b"},{"idioma":"fr","id":"fr-u490","tipo":"frase","requer":"fr-p394","fr":"Il faut se protéger du froid.","aceitasFr":["Il faut se protéger contre le froid."],"en":"You have to protect yourself from the cold.","aceitasEn":["you have to protect yourself from the cold","you have to protect yourself against the cold","you need to protect yourself from the cold","you must protect yourself from the cold","youve got to protect yourself from the cold","we have to protect ourselves from the cold","one must protect oneself from the cold"],"distratoresEn":["You have to get used to the cold.","You have to get away from the cold.","You have to remember the cold.","You have to forget about the cold."],"nivel":"A1","tags":["verbo","cotidiano"],"notaEn":"«Protéger de», to protect from: «du froid» is «de» + «le». After «il faut», you have to, the verb stays in the infinitive with the pronoun in front: «se protéger». «Contre le froid» works too.","requerTodas":["fr-p122","fr-p394","fr-p080"],"v":"8836c75f"},{"idioma":"fr","id":"fr-u491","tipo":"frase","requer":"fr-p395","fr":"Ne t'inquiète pas, tout va bien.","aceitasFr":["T'inquiète pas, tout va bien.","T'inquiète, tout va bien.","Ne vous inquiétez pas, tout va bien."],"en":"Don't worry, everything's fine.","aceitasEn":["dont worry everythings fine","dont worry everything is fine","do not worry everything is fine","dont worry everythings okay","dont worry everything is okay","dont worry everythings ok","dont worry everything is ok","dont worry its all good","dont worry all is well"],"distratoresEn":["Don't rush, everything's fine.","Don't get up, everything's fine.","Don't move, everything's fine.","Don't be scared, everything's fine."],"nivel":"A1","tags":["verbo","cotidiano"],"notaEn":"«Ne t'inquiète pas», don't worry: in a negative command the pronoun goes before the verb. Casually it shrinks to «t'inquiète pas», or just «t'inquiète». «Tout va bien», everything's going well.","requerTodas":["fr-p395","fr-p070","fr-p003","fr-p044"],"v":"6413aa72"},{"idioma":"fr","id":"fr-u492","tipo":"frase","requer":"fr-p395","fr":"Ma mère s'inquiète pour moi.","en":"My mother worries about me.","aceitasEn":["my mother worries about me","my mom worries about me","my mum worries about me","my mother is worried about me","my mom is worried about me"],"distratoresEn":["My mother talks about me.","My mother asks about me.","My mother forgets about me.","My mother dreams about me."],"nivel":"A1","tags":["verbo","família"],"notaEn":"About someone takes «pour», for: «je m'inquiète pour toi», I'm worried about you. About something, «de»: «s'inquiéter de l'avenir». «Inquiet», worried, has nothing to do with quiet.","requerTodas":["fr-p063","fr-p395"],"v":"4c87f8b5"},{"idioma":"fr","id":"fr-u493","tipo":"frase","requer":"fr-p396","fr":"Ce livre a beaucoup d'images.","aceitasFr":["Il y a beaucoup d'images dans ce livre."],"en":"This book has a lot of pictures.","aceitasEn":["this book has a lot of pictures","this book has lots of pictures","this book has many pictures","this book has a lot of images","this book has lots of images","this book has many images","this book has a lot of illustrations","there are a lot of pictures in this book","that book has a lot of pictures"],"distratoresEn":["This book has a lot of pages.","This book has a lot of stories.","This book has a lot of colors.","This book has a lot of questions."],"nivel":"A1","tags":["cultura"],"notaEn":"«L'image» is feminine. After «beaucoup», just «de», which drops its «e» before a vowel: «beaucoup d'images», a lot of pictures. «Ce livre a» is literally this book has.","requerTodas":["fr-p033","fr-p002","fr-p067","fr-p396"],"v":"3d3fb30b"},{"idioma":"fr","id":"fr-u494","tipo":"frase","requer":"fr-p396","fr":"Il fait attention à son image.","en":"He looks after his image.","aceitasEn":["he looks after his image","he takes care of his image","he cares about his image","he is careful about his image","hes careful about his image","he pays attention to his image","he watches his image"],"distratoresEn":["He looks after his health.","He looks after his house.","He looks after his family.","He looks after his clothes."],"nivel":"A1","tags":["social"],"notaEn":"«L'image» is also someone's public image. «Faire attention à» is to pay attention to, to be careful with: «fais attention à toi», take care. «Image» is feminine but starts with a vowel, so it takes «son», not «sa».","requerTodas":["fr-p004","fr-p127","fr-p396"],"v":"72fdf2cb"},{"idioma":"fr","id":"fr-u495","tipo":"frase","requer":"fr-p397","fr":"Il a du chocolat sur le menton.","en":"He has chocolate on his chin.","aceitasEn":["he has chocolate on his chin","hes got chocolate on his chin","he has got chocolate on his chin","he has some chocolate on his chin","theres chocolate on his chin"],"distratoresEn":["He has chocolate on his nose.","He has chocolate on his arm.","He has chocolate on his foot.","He has chocolate on his neck."],"nivel":"A2","tags":["corpo"],"notaEn":"«Le menton», the chin, is masculine. With body parts French often uses the article, not the possessive: «sur le menton», on his chin. «Du chocolat» is the partitive: some chocolate.","requerTodas":["fr-p002","fr-p068","fr-p397"],"v":"ba148d8b"},{"idioma":"fr","id":"fr-u496","tipo":"frase","requer":"fr-p398","fr":"On y va en bateau ?","aceitasFr":["On va en bateau ?","Est-ce qu'on y va en bateau ?","Nous y allons en bateau ?"],"en":"Shall we go by boat?","aceitasEn":["shall we go by boat","should we go by boat","shall we go there by boat","are we going by boat","are we going there by boat","shall we take the boat","should we take the boat","are we taking the boat"],"distratoresEn":["Shall we go by train?","Shall we go by bus?","Shall we go by car?","Shall we go by plane?"],"nivel":"A1","tags":["viagem"],"notaEn":"Vehicles you get inside take «en», by: «en bateau», «en train», «en voiture». «Y» means there: «on y va», shall we go there. In speech, «on» is the usual we.","requerTodas":["fr-p003","fr-p398"],"v":"acd6f54e"},{"idioma":"fr","id":"fr-u497","tipo":"frase","requer":"fr-p398","fr":"Le bateau part à huit heures.","en":"The boat leaves at eight.","aceitasEn":["the boat leaves at eight","the boat leaves at eight oclock","the boat departs at eight","the boat sails at eight","the ship leaves at eight"],"distratoresEn":["The train leaves at eight.","The bus leaves at eight.","The plane leaves at eight.","The subway leaves at eight."],"nivel":"A1","tags":["viagem"],"notaEn":"«Partir» is to leave, to depart: «le bateau part». With times, «heures» isn't dropped: «à huit heures», at eight. The plural takes «x»: «les bateaux».","requerTodas":["fr-p398","fr-p083","fr-p126","fr-p129"],"v":"d8d33bd3"},{"idioma":"fr","id":"fr-u498","tipo":"frase","requer":"fr-p399","fr":"Joyeux Noël !","en":"Merry Christmas!","aceitasEn":["merry christmas","happy christmas","merry xmas"],"distratoresEn":["Happy New Year!","Happy Easter!","Happy birthday!","Have a nice weekend!"],"nivel":"A1","tags":["cultura","social"],"notaEn":"«Noël» takes no article and a capital; the dieresis splits the vowels: «no-el». «Joyeux», joyful, also appears in «joyeux anniversaire», happy birthday. Happy New Year is «bonne année».","requerTodas":["fr-p419","fr-p399"],"v":"d01c6554"},{"idioma":"fr","id":"fr-u499","tipo":"frase","requer":"fr-p399","fr":"Qu'est-ce que tu veux pour Noël ?","aceitasFr":["Tu veux quoi pour Noël ?","Que veux-tu pour Noël ?","Qu'est-ce que vous voulez pour Noël ?"],"en":"What do you want for Christmas?","aceitasEn":["what do you want for christmas","what do you want to get for christmas","what do you want for xmas"],"distratoresEn":["What do you want for your birthday?","What do you want for dessert?","What do you want for dinner?","What do you want for lunch?"],"nivel":"A1","tags":["cultura","família"],"notaEn":"«Pour Noël», for Christmas: the date of the present. «Qu'est-ce que» is the everyday way to ask what; casually, «tu veux quoi pour Noël ?».","requerTodas":["fr-p007","fr-p399"],"v":"374af7d5"},{"idioma":"fr","id":"fr-u504","tipo":"frase","requer":"fr-p400","fr":"J'ai mal à l'oreille.","en":"I have an earache.","aceitasEn":["i have an earache","ive got an earache","i have an ear ache","my ear hurts","my ears hurt","i have ear pain"],"distratoresEn":["I have a headache.","I have a toothache.","I have a stomachache.","I have a backache."],"nivel":"A1","tags":["corpo","saúde"],"notaEn":"«Avoir mal à» + body part means it hurts: «j'ai mal à l'oreille», «j'ai mal à la tête». «L'oreille» is the whole ear, inside and out.","requerTodas":["fr-p002","fr-p151","fr-p400"],"v":"2985ba3b"},{"idioma":"fr","id":"fr-u505","tipo":"frase","requer":"fr-p400","fr":"Il a de grandes oreilles.","aceitasFr":["Elle a de grandes oreilles."],"en":"He has big ears.","aceitasEn":["he has big ears","hes got big ears","he has large ears","she has big ears"],"distratoresEn":["He has big hands.","He has big feet.","He has big cheeks.","He has big nails."],"nivel":"A1","tags":["corpo"],"notaEn":"When an adjective comes before a plural noun, «des» becomes «de»: «de grandes oreilles». «Grandes» is feminine plural, agreeing with «oreilles».","requerTodas":["fr-p002","fr-p037","fr-p400"],"v":"83cbc82c"},{"idioma":"fr","id":"fr-u506","tipo":"frase","requer":"fr-p401","fr":"Je dois retirer de l'argent.","en":"I need to withdraw some money.","aceitasEn":["i need to withdraw some money","i need to withdraw money","i have to withdraw money","i have to withdraw some money","i need to take out some money","i need to take out money","i need to take some money out","i need to get some cash","i must withdraw some money"],"distratoresEn":["I need to exchange some money.","I need to save some money.","I need to deposit some money.","I need to send some money."],"nivel":"A2","tags":["economia","cotidiano"],"notaEn":"At the bank or an ATM, to withdraw is «retirer»: «retirer de l'argent», with «de l'» for an unspecified amount. An ATM is «un distributeur».","requerTodas":["fr-p082","fr-p401","fr-p035"],"v":"ecbc566f"},{"idioma":"fr","id":"fr-u507","tipo":"frase","requer":"fr-p401","fr":"Retire tes chaussures, s'il te plaît.","aceitasFr":["Retirez vos chaussures, s'il vous plaît."],"en":"Take off your shoes, please.","aceitasEn":["take off your shoes please","take your shoes off please","please take off your shoes","please take your shoes off","remove your shoes please","please remove your shoes"],"distratoresEn":["Put on your shoes, please.","Clean your shoes, please.","Change your shoes, please.","Tie your shoes, please."],"nivel":"A2","tags":["roupa","casa"],"notaEn":"Taking off clothes or shoes is «retirer» (or «enlever»). With «tu», the imperative of «-er» verbs drops the «-s»: «retire».","requerTodas":["fr-p401","fr-p278"],"v":"1be98857"},{"idioma":"fr","id":"fr-u508","tipo":"frase","requer":"fr-p402","fr":"Ne mens pas à ta mère.","aceitasFr":["Ne mentez pas à votre mère."],"en":"Don't lie to your mother.","aceitasEn":["dont lie to your mother","do not lie to your mother","dont lie to your mom","dont lie to your mum"],"distratoresEn":["Don't talk to your mother.","Don't write to your mother.","Don't listen to your mother.","Don't reply to your mother."],"nivel":"A2","tags":["família","social"],"notaEn":"Lying to someone is «mentir à». It is conjugated like «sentir»: «je mens», «tu mens»; the imperative is «mens». Lying down is «s'allonger».","requerTodas":["fr-p402","fr-p063"],"v":"458b9ec4"},{"idioma":"fr","id":"fr-u509","tipo":"frase","requer":"fr-p402","fr":"Il m'a menti.","aceitasFr":["Elle m'a menti."],"en":"He lied to me.","aceitasEn":["he lied to me","she lied to me","hes lied to me","he has lied to me"],"distratoresEn":["He called me.","He smiled at me.","He looked at me.","He waved at me."],"nivel":"A2","tags":["social"],"notaEn":"The «à» of «mentir à quelqu'un» is folded into the pronoun: «il m'a menti», he lied to me. The past participle is «menti».","requerTodas":["fr-p002","fr-p402"],"v":"2f4e23ce"},{"idioma":"fr","id":"fr-u510","tipo":"frase","requer":"fr-p403","fr":"Il possède trois maisons.","aceitasFr":["Elle possède trois maisons."],"en":"He owns three houses.","aceitasEn":["he owns three houses","she owns three houses","he has three houses","hes got three houses"],"distratoresEn":["He rents three houses.","He sells three houses.","He builds three houses.","He renovates three houses."],"nivel":"A2","tags":["economia","casa"],"notaEn":"«Posséder» is more formal than «avoir». The accent shifts with the pronunciation: «il possède», but «nous possédons».","requerTodas":["fr-p403","fr-p094","fr-p020"],"v":"b73866b3"},{"idioma":"fr","id":"fr-u511","tipo":"frase","requer":"fr-p404","fr":"Mon portable est dans ma poche.","aceitasFr":["Mon téléphone est dans ma poche."],"en":"My phone is in my pocket.","aceitasEn":["my phone is in my pocket","my phones in my pocket","my cell phone is in my pocket","my cellphone is in my pocket","my mobile is in my pocket"],"distratoresEn":["My phone is in my coat.","My phone is in my car.","My phone is in my room.","My phone is on the couch."],"nivel":"A2","tags":["roupa","tecnologia"],"notaEn":"«La poche» is feminine: «dans ma poche», in my pocket. In everyday speech, a cell phone is «un portable».","requerTodas":["fr-p212","fr-p001","fr-p404"],"v":"fc2b07f1"},{"idioma":"fr","id":"fr-u512","tipo":"frase","requer":"fr-p404","fr":"Mes parents me donnent de l'argent de poche.","en":"My parents give me pocket money.","aceitasEn":["my parents give me pocket money","my parents give me an allowance","my parents give me allowance","my parents give me spending money"],"distratoresEn":["My parents give me advice.","My parents give me rides.","My parents give me freedom.","My parents give me attention."],"nivel":"A2","tags":["família","economia"],"notaEn":"«L'argent de poche» is pocket money, an allowance. «De l'argent», with the partitive, because it is an unspecified amount.","requerTodas":["fr-p247","fr-p195","fr-p035","fr-p404"],"v":"0342c877"},{"idioma":"fr","id":"fr-u513","tipo":"frase","requer":"fr-p405","fr":"Il a trouvé un emploi à Paris.","aceitasFr":["Elle a trouvé un emploi à Paris."],"en":"He found a job in Paris.","aceitasEn":["he found a job in paris","she found a job in paris","he got a job in paris","he found work in paris","hes found a job in paris","he landed a job in paris"],"distratoresEn":["He found an apartment in Paris.","He found a hotel in Paris.","He found a course in Paris.","He found a friend in Paris."],"nivel":"A2","tags":["trabalho"],"notaEn":"«L'emploi» is a job, a position; «le travail» is work in general. It is masculine: «un emploi». Cities take «à»: «à Paris».","requerTodas":["fr-p002","fr-p193","fr-p405"],"v":"adeab63e"},{"idioma":"fr","id":"fr-u514","tipo":"frase","requer":"fr-p405","fr":"J'ai un nouvel emploi du temps.","en":"I have a new schedule.","aceitasEn":["i have a new schedule","ive got a new schedule","i have a new timetable","ive got a new timetable"],"distratoresEn":["I have a new job.","I have a new car.","I have a new phone.","I have a new boss."],"nivel":"A2","tags":["escola","trabalho"],"notaEn":"«L'emploi du temps» is a schedule or timetable, not a job. «Nouveau» becomes «nouvel» before a vowel: «un nouvel emploi».","requerTodas":["fr-p002","fr-p039","fr-p405","fr-p025"],"v":"75749d78"},{"idioma":"fr","id":"fr-u515","tipo":"frase","requer":"fr-p406","fr":"Ce n'est pas nécessaire.","en":"It's not necessary.","aceitasEn":["its not necessary","it isnt necessary","it is not necessary","thats not necessary","theres no need","no need","its not needed"],"distratoresEn":["It's not possible.","It's not difficult.","It's not important.","It's not serious."],"nivel":"A2","tags":["cotidiano"],"notaEn":"A polite way to decline: «ce n'est pas nécessaire», there's no need. «Ce n'est pas la peine» says the same.","requerTodas":["fr-p001","fr-p406"],"v":"ca0caaf8"},{"idioma":"fr","id":"fr-u516","tipo":"frase","requer":"fr-p406","fr":"Il est nécessaire de réserver.","en":"It's necessary to book.","aceitasEn":["its necessary to book","it is necessary to book","you need to book","you have to book","booking is necessary","you need a reservation","a reservation is necessary","its necessary to make a reservation","you need to make a reservation","reservations are required"],"distratoresEn":["It's possible to book.","It's difficult to book.","It's easy to book.","It's forbidden to book."],"nivel":"A2","tags":["viagem"],"notaEn":"«Il est nécessaire de» + infinitive, with «de». In everyday speech «il faut réserver» is more common.","requerTodas":["fr-p001","fr-p406","fr-p174"],"v":"8791d75c"},{"idioma":"fr","id":"fr-u517","tipo":"frase","requer":"fr-p407","fr":"Il a inventé une excuse.","aceitasFr":["Elle a inventé une excuse."],"en":"He made up an excuse.","aceitasEn":["he made up an excuse","she made up an excuse","he made an excuse up","he invented an excuse","he came up with an excuse","hes made up an excuse"],"distratoresEn":["He accepted an excuse.","He heard an excuse.","He asked for an excuse.","He rejected an excuse."],"nivel":"A2","tags":["social"],"notaEn":"«Inventer» covers both inventing and making up: «inventer une excuse». «L'excuse» is feminine; to apologize is «s'excuser».","requerTodas":["fr-p002","fr-p407","fr-p531"],"v":"3dd9c175"},{"idioma":"fr","id":"fr-u518","tipo":"frase","requer":"fr-p407","fr":"Les Français ont inventé le cinéma.","en":"The French invented cinema.","aceitasEn":["the french invented cinema","the french invented the cinema","the french invented film","cinema was invented by the french"],"distratoresEn":["The French changed cinema.","The French loved cinema.","The French saved cinema.","The French dominated cinema."],"nivel":"A2","tags":["cultura"],"notaEn":"The Lumière brothers held the first public film screening in Paris in 1895. The people take a capital, «les Français»; the language and the adjective do not.","requerTodas":["fr-p054","fr-p002","fr-p407","fr-p097"],"v":"45f0154e"},{"idioma":"fr","id":"fr-u519","tipo":"frase","requer":"fr-p408","fr":"Quel est ton métier ?","aceitasFr":["Quel est votre métier ?","C'est quoi ton métier ?","Tu fais quel métier ?"],"en":"What's your profession?","aceitasEn":["whats your profession","what is your profession","whats your job","what is your job","whats your occupation","whats your trade","what do you do"],"distratoresEn":["What's your age?","What's your city?","What's your nationality?","What's your opinion?"],"nivel":"A2","tags":["trabalho","social"],"notaEn":"«Le métier» is a trade or profession, the work you learned to do. «Quel» agrees with the noun: «quel métier», «quelle profession».","requerTodas":["fr-p001","fr-p408"],"v":"837889c2"},{"idioma":"fr","id":"fr-u520","tipo":"frase","requer":"fr-p409","fr":"Je t'envoie les détails ce soir.","aceitasFr":["Je vous envoie les détails ce soir.","Ce soir, je t'envoie les détails."],"en":"I'll send you the details tonight.","aceitasEn":["ill send you the details tonight","i will send you the details tonight","im sending you the details tonight","ill send you the details this evening","ill send the details tonight","tonight ill send you the details"],"distratoresEn":["I'll send you the documents tonight.","I'll send you the schedules tonight.","I'll send you the prices tonight.","I'll send you the tickets tonight."],"nivel":"A2","tags":["cotidiano"],"notaEn":"«Le détail» is masculine: «les détails». French uses the present for a near future where English says «I'll»: «je t'envoie».","requerTodas":["fr-p376","fr-p409","fr-p160"],"v":"de495d7b"},{"idioma":"fr","id":"fr-u521","tipo":"frase","requer":"fr-p410","fr":"Quelle est votre date de naissance ?","aceitasFr":["Quelle est ta date de naissance ?","C'est quoi ta date de naissance ?"],"en":"What's your date of birth?","aceitasEn":["whats your date of birth","what is your date of birth","whats your birth date","whats your birthdate","what is your birth date"],"distratoresEn":["What's your date of marriage?","What's your date of departure?","What's your date of payment?","What's your date of arrival?"],"nivel":"A2","tags":["cotidiano","viagem"],"notaEn":"«La date de naissance», date of birth, comes up on every form. «La date» is feminine, hence «quelle». A birthday is «un anniversaire».","requerTodas":["fr-p001","fr-p524","fr-p410"],"v":"51581571"},{"idioma":"fr","id":"fr-u522","tipo":"frase","requer":"fr-p411","fr":"Quel est le titre du livre ?","aceitasFr":["C'est quoi le titre du livre ?","Quel est le titre de ce livre ?"],"en":"What's the title of the book?","aceitasEn":["whats the title of the book","what is the title of the book","whats the books title","whats the title of this book","whats the book called","what is the book called"],"distratoresEn":["What's the price of the book?","What's the theme of the book?","What's the ending of the book?","What's the subject of the book?"],"nivel":"A2","tags":["cultura"],"notaEn":"«Le titre» is masculine, and «du» is «de» + «le». «Les gros titres» are the headlines.","requerTodas":["fr-p001","fr-p411","fr-p033"],"v":"384dc41a"},{"idioma":"fr","id":"fr-u523","tipo":"frase","requer":"fr-p412","fr":"Le professeur écrit au tableau.","aceitasFr":["La professeure écrit au tableau.","Le prof écrit au tableau."],"en":"The teacher writes on the board.","aceitasEn":["the teacher writes on the board","the teacher writes on the blackboard","the teacher writes on the whiteboard","the teacher writes on the chalkboard","the teacher is writing on the board","the teacher is writing on the blackboard"],"distratoresEn":["The teacher writes on the paper.","The teacher writes on the wall.","The teacher writes on the screen.","The teacher writes on the desk."],"nivel":"A2","tags":["escola"],"notaEn":"In class, «le tableau» is the board: «écrire au tableau», to write on the board. «Au» is «à» + «le».","requerTodas":["fr-p366","fr-p184","fr-p412"],"v":"8080b7c1"},{"idioma":"fr","id":"fr-u524","tipo":"frase","requer":"fr-p412","fr":"J'ai acheté un tableau au marché.","en":"I bought a painting at the market.","aceitasEn":["i bought a painting at the market","i bought a picture at the market","ive bought a painting at the market","i bought a painting in the market"],"distratoresEn":["I bought a rug at the market.","I bought a vase at the market.","I bought a mirror at the market.","I bought a clock at the market."],"nivel":"A2","tags":["cultura","compras"],"notaEn":"«Le tableau» is also a painting on the wall. A frame is «un cadre».","requerTodas":["fr-p002","fr-p075","fr-p412","fr-p312"],"v":"29cee688"},{"idioma":"fr","id":"fr-u525","tipo":"frase","requer":"fr-p413","fr":"Ça coûte deux euros l'unité.","aceitasFr":["C'est deux euros l'unité.","Ça coûte deux euros à l'unité."],"en":"It costs two euros each.","aceitasEn":["it costs two euros each","its two euros each","they cost two euros each","it costs two euros apiece","its two euros apiece","it costs two euros a unit","it costs two euros per unit","two euros each"],"distratoresEn":["It costs two euros an hour.","It costs two euros a box.","It costs two euros a dozen.","It costs two euros a bottle."],"nivel":"A2","tags":["compras"],"notaEn":"French gives a price per item with the article and no preposition: «deux euros l'unité», like «dix euros le kilo», ten euros a kilo.","requerTodas":["fr-p321","fr-p120","fr-p128","fr-p413"],"v":"ccd3a3eb"},{"idioma":"fr","id":"fr-u526","tipo":"frase","requer":"fr-p414","fr":"Appuie sur le bouton.","aceitasFr":["Appuyez sur le bouton."],"en":"Press the button.","aceitasEn":["press the button","push the button","hit the button","click the button","press on the button"],"distratoresEn":["Release the button.","Find the button.","Turn the button.","Clean the button."],"nivel":"A2","tags":["cotidiano","tecnologia"],"notaEn":"Pressing takes «sur»: «appuie sur le bouton». The «y» becomes «i» before a silent ending: «appuie».","requerTodas":["fr-p414","fr-p527"],"v":"17c01b8f"},{"idioma":"fr","id":"fr-u527","tipo":"frase","requer":"fr-p414","fr":"Ne t'appuie pas sur la table.","aceitasFr":["Ne vous appuyez pas sur la table."],"en":"Don't lean on the table.","aceitasEn":["dont lean on the table","do not lean on the table","dont lean against the table","dont rest on the table"],"distratoresEn":["Don't sit on the table.","Don't lie on the table.","Don't climb on the table.","Don't bang on the table."],"nivel":"A2","tags":["casa"],"notaEn":"«S'appuyer sur» means to lean on. In a negative command the pronoun goes before the verb, «ne t'appuie pas»; in a positive one, after: «appuie-toi».","requerTodas":["fr-p414","fr-p143"],"v":"08375144"},{"idioma":"fr","id":"fr-u528","tipo":"frase","requer":"fr-p415","fr":"Mes parents se disputent souvent.","en":"My parents often argue.","aceitasEn":["my parents often argue","my parents argue often","my parents argue a lot","my parents often fight","my parents fight often","my parents fight a lot"],"distratoresEn":["My parents often travel.","My parents often go out.","My parents often cook.","My parents often dance."],"nivel":"A2","tags":["família","social"],"notaEn":"«Se disputer» is to argue or quarrel, with «se» because it goes both ways. To discuss, or just to chat, is «discuter».","requerTodas":["fr-p247","fr-p415","fr-p114"],"v":"539163a1"},{"idioma":"fr","id":"fr-u529","tipo":"frase","requer":"fr-p415","fr":"Je me suis disputé avec mon frère.","aceitasFr":["Je me suis disputée avec mon frère."],"en":"I argued with my brother.","aceitasEn":["i argued with my brother","i had a fight with my brother","i fought with my brother","i had an argument with my brother","i got into a fight with my brother","ive had a fight with my brother"],"distratoresEn":["I went out with my brother.","I traveled with my brother.","I played with my brother.","I had lunch with my brother."],"nivel":"A2","tags":["família"],"notaEn":"To argue with someone is «se disputer avec». Verbs with «se» take «être» in the passé composé: «je me suis disputé», plus «-e» if a woman is speaking.","requerTodas":["fr-p001","fr-p415","fr-p078"],"v":"ba423da5"},{"idioma":"fr","id":"fr-u530","tipo":"frase","requer":"fr-p416","fr":"Les vacances nous ont rapprochés.","aceitasFr":["Les vacances nous ont rapprochées."],"en":"The vacation brought us closer.","aceitasEn":["the vacation brought us closer","the vacation brought us closer together","the holidays brought us closer","the holidays brought us closer together","our vacation brought us closer","the vacation has brought us closer"],"distratoresEn":["The vacation separated us.","The vacation tired us out.","The vacation changed us.","The vacation saved us."],"nivel":"A2","tags":["família","social"],"notaEn":"«Rapprocher» is to bring closer, people included. The participle agrees with the «nous» before it: «rapprochés». «Les vacances» is always plural.","requerTodas":["fr-p163","fr-p002","fr-p416"],"v":"04d12fbe"},{"idioma":"fr","id":"fr-u531","tipo":"frase","requer":"fr-p416","fr":"Rapproche ta chaise de la table.","aceitasFr":["Rapprochez votre chaise de la table."],"en":"Move your chair closer to the table.","aceitasEn":["move your chair closer to the table","pull your chair closer to the table","bring your chair closer to the table","pull your chair up to the table","move the chair closer to the table","bring the chair closer to the table"],"distratoresEn":["Move your chair away from the table.","Take your chair off the table.","Pull your chair out from the table.","Lift your chair off the table."],"nivel":"A2","tags":["casa"],"notaEn":"To move one thing closer to another is «rapprocher… de»: «rapproche ta chaise de la table». The opposite is «éloigner».","requerTodas":["fr-p416","fr-p354","fr-p143"],"v":"76b7a3d1"},{"idioma":"fr","id":"fr-u532","tipo":"frase","requer":"fr-p417","fr":"Les chambres sont à l'étage supérieur.","aceitasFr":["Les chambres se trouvent à l'étage supérieur."],"en":"The rooms are on the upper floor.","aceitasEn":["the rooms are on the upper floor","the bedrooms are on the upper floor","the rooms are upstairs","the bedrooms are upstairs","the rooms are on the floor above","the bedrooms are on the floor above"],"distratoresEn":["The rooms are on the lower floor.","The rooms are on the ground floor.","The rooms are on the main floor.","The rooms are on the middle floor."],"nivel":"A2","tags":["casa","viagem"],"notaEn":"«Supérieur» means upper or higher: «l'étage supérieur», the floor above. It goes after the noun, and the opposite is «inférieur».","requerTodas":["fr-p107","fr-p001","fr-p317","fr-p417"],"v":"c5bb0102"},{"idioma":"fr","id":"fr-u533","tipo":"frase","requer":"fr-p418","fr":"Je voudrais échanger ce pantalon.","aceitasFr":["J'aimerais échanger ce pantalon.","Je veux échanger ce pantalon."],"en":"I'd like to exchange these pants.","aceitasEn":["id like to exchange these pants","i would like to exchange these pants","id like to exchange these trousers","i want to exchange these pants","id like to swap these pants"],"distratoresEn":["I'd like to try on these pants.","I'd like to return these pants.","I'd like to buy these pants.","I'd like to alter these pants."],"nivel":"A2","tags":["compras","roupa"],"notaEn":"In a shop, to exchange an item is «échanger». «Je voudrais» is the polite way to ask. «Le pantalon» is singular in French: «ce pantalon», these pants.","requerTodas":["fr-p007","fr-p418","fr-p279"],"v":"2579c1b4"},{"idioma":"fr","id":"fr-u534","tipo":"frase","requer":"fr-p418","fr":"On a échangé nos numéros.","aceitasFr":["Nous avons échangé nos numéros.","On s'est échangé nos numéros."],"en":"We exchanged our numbers.","aceitasEn":["we exchanged our numbers","we exchanged numbers","we swapped numbers","we swapped our numbers","we traded numbers","weve exchanged numbers"],"distratoresEn":["We wrote down our numbers.","We forgot our numbers.","We lost our numbers.","We deleted our numbers."],"nivel":"A2","tags":["social","tecnologia"],"notaEn":"In speech, «on» stands in for «nous», with a third-person verb: «on a échangé». «Échanger» works for words too: «échanger quelques mots».","requerTodas":["fr-p002","fr-p418","fr-p215"],"v":"d2337ad4"},{"idioma":"fr","id":"fr-u535","tipo":"frase","requer":"fr-p419","fr":"C'est une musique joyeuse.","en":"It's cheerful music.","aceitasEn":["its cheerful music","its happy music","its joyful music","its upbeat music","its a cheerful song","its a happy song","its a joyful song"],"distratoresEn":["It's sad music.","It's slow music.","It's old music.","It's calm music."],"nivel":"A2","tags":["cultura"],"notaEn":"The feminine of «joyeux» is «joyeuse». It is also the holiday word: «Joyeux Noël !», Merry Christmas!","requerTodas":["fr-p001","fr-p305","fr-p419"],"v":"45f1732c"},{"idioma":"fr","id":"fr-u536","tipo":"frase","requer":"fr-p420","fr":"Ne m'interromps pas !","aceitasFr":["Ne m'interrompez pas !"],"en":"Don't interrupt me!","aceitasEn":["dont interrupt me","do not interrupt me"],"distratoresEn":["Don't ignore me!","Don't push me!","Don't rush me!","Don't forget me!"],"nivel":"A2","tags":["social"],"notaEn":"Conjugated like «rompre»: «j'interromps», «tu interromps», «il interrompt», with a silent «t». In a negative command the pronoun comes first.","requerTodas":["fr-p420"],"v":"3940633a"},{"idioma":"fr","id":"fr-u537","tipo":"frase","requer":"fr-p420","fr":"Excusez-moi de vous interrompre.","aceitasFr":["Excuse-moi de t'interrompre.","Désolé de vous interrompre.","Désolée de vous interrompre.","Pardon de vous interrompre."],"en":"Sorry to interrupt.","aceitasEn":["sorry to interrupt","sorry to interrupt you","im sorry to interrupt","sorry for interrupting","excuse me for interrupting","excuse me for interrupting you","pardon the interruption","sorry for the interruption"],"distratoresEn":["Sorry to bother you.","Sorry to ask.","Sorry to insist.","Sorry to call."],"nivel":"A2","tags":["social","formal"],"notaEn":"«Excusez-moi de» + infinitive is the polite formula: «excusez-moi de vous interrompre». With «tu»: «excuse-moi de t'interrompre».","requerTodas":["fr-p518","fr-p420"],"v":"01871295"},{"idioma":"fr","id":"fr-u538","tipo":"frase","requer":"fr-p421","fr":"Le cabinet est fermé le samedi.","en":"The office is closed on Saturdays.","aceitasEn":["the office is closed on saturdays","the office is closed saturdays","the office closes on saturdays","the office is shut on saturdays","the doctors office is closed on saturdays","the practice is closed on saturdays","the clinic is closed on saturdays"],"distratoresEn":["The bank is closed on Saturdays.","The market is closed on Saturdays.","The museum is closed on Saturdays.","The restaurant is closed on Saturdays."],"nivel":"A2","tags":["saúde","trabalho"],"notaEn":"Not a kitchen cabinet, which is «un placard»: «le cabinet» is a doctor's or dentist's office, or a lawyer's. «Le samedi», with the article, means every Saturday.","requerTodas":["fr-p421","fr-p001","fr-p206","fr-p159"],"v":"beb4538a"},{"idioma":"fr","id":"fr-u539","tipo":"frase","requer":"fr-p422","fr":"C'est une tradition de famille.","en":"It's a family tradition.","aceitasEn":["its a family tradition","it is a family tradition","thats a family tradition"],"distratoresEn":["It's a family recipe.","It's a family photo.","It's a family party.","It's a family story."],"nivel":"A2","tags":["família","cultura"],"notaEn":"«La tradition» is feminine, like every noun in «-tion». Where English puts «family» first, French uses «de»: «une tradition de famille».","requerTodas":["fr-p001","fr-p422","fr-p105"],"v":"d52f0d07"},{"idioma":"fr","id":"fr-u540","tipo":"frase","requer":"fr-p423","fr":"Ma voiture est au garage.","en":"My car is in the shop.","aceitasEn":["my car is in the shop","my cars in the shop","my car is at the shop","my car is at the garage","my car is in the garage","my car is at the mechanics","my car is at the repair shop"],"distratoresEn":["My car is on the street.","My car is on the road.","My car is at the beach.","My car is at the station."],"nivel":"A2","tags":["cotidiano"],"notaEn":"«Le garage» is both where you park and where cars get fixed: «ma voiture est au garage» usually means it is in the shop. The mechanic is «le garagiste».","requerTodas":["fr-p034","fr-p001","fr-p423"],"v":"44662ad2"},{"idioma":"fr","id":"fr-u541","tipo":"frase","requer":"fr-p423","fr":"Je rentre la voiture au garage.","en":"I'm putting the car in the garage.","aceitasEn":["im putting the car in the garage","im putting the car away in the garage","i put the car in the garage","ill put the car in the garage","im parking the car in the garage","i park the car in the garage"],"distratoresEn":["I'm putting the car in the shade.","I'm putting the car in the yard.","I'm putting the car in the driveway.","I'm putting the car in the lot."],"nivel":"A2","tags":["casa"],"notaEn":"«Rentrer la voiture» is to put the car away: «rentrer» also means to bring something inside. Here «le garage» is the one at home.","requerTodas":["fr-p071","fr-p034","fr-p423"],"v":"81fe8a6d"},{"idioma":"fr","id":"fr-u542","tipo":"frase","requer":"fr-p424","fr":"Il faut comparer les prix.","en":"You have to compare prices.","aceitasEn":["you have to compare prices","you have to compare the prices","you need to compare prices","you need to compare the prices","we have to compare prices","we need to compare prices","its necessary to compare prices"],"distratoresEn":["You have to lower prices.","You have to raise prices.","You have to change prices.","You have to write down prices."],"nivel":"A2","tags":["compras","economia"],"notaEn":"«Il faut» + infinitive means you have to, one must. «Comparer» takes «à» or «avec»: «comparer un prix avec un autre».","requerTodas":["fr-p122","fr-p424","fr-p192"],"v":"57ecfb6e"},{"idioma":"fr","id":"fr-u543","tipo":"frase","requer":"fr-p424","fr":"Ne me compare pas à mon frère !","aceitasFr":["Ne me compare pas avec mon frère !","Ne me comparez pas à mon frère !"],"en":"Don't compare me to my brother!","aceitasEn":["dont compare me to my brother","dont compare me with my brother","do not compare me to my brother","do not compare me with my brother"],"distratoresEn":["Don't confuse me with my brother!","Don't leave me with my brother!","Don't send me with my brother!","Don't mix me up with my brother!"],"nivel":"A2","tags":["família"],"notaEn":"«Comparer à» or «comparer avec», same meaning, like «to» and «with». In a negative command the pronoun comes first: «ne me compare pas».","requerTodas":["fr-p424","fr-p078"],"v":"72ee9017"},{"idioma":"fr","id":"fr-u544","tipo":"frase","requer":"fr-p425","fr":"Un homme mystérieux m'a appelé hier.","aceitasFr":["Un homme mystérieux m'a appelée hier."],"en":"A mysterious man called me yesterday.","aceitasEn":["a mysterious man called me yesterday","a mysterious man phoned me yesterday","a mysterious man rang me yesterday","yesterday a mysterious man called me","a mysterious man gave me a call yesterday"],"distratoresEn":["A friendly man called me yesterday.","A famous man called me yesterday.","A nervous man called me yesterday.","A polite man called me yesterday."],"nivel":"B1","tags":["cotidiano"],"notaEn":"«Mystérieux» is spelled with a «y», like «le mystère»; feminine «mystérieuse». Unlike English, the adjective follows the noun: «un homme mystérieux».","requerTodas":["fr-p425","fr-p021","fr-p002","fr-p229","fr-p125"],"v":"6424effc"},{"idioma":"fr","id":"fr-u545","tipo":"frase","requer":"fr-p426","fr":"Le film est entièrement en anglais.","en":"The movie is entirely in English.","aceitasEn":["the movie is entirely in english","the film is entirely in english","the movie is completely in english","the film is completely in english","the movie is all in english","the film is all in english","the whole movie is in english","the whole film is in english","the movie is totally in english"],"distratoresEn":["The movie is partly in English.","The movie is mostly in English.","The movie is also in English.","The movie is half in English."],"nivel":"B1","tags":["cultura","cotidiano"],"notaEn":"«Entièrement» comes from «entier», whole: the feminine «entière» plus «-ment», the French «-ly». Hence the grave accent: «è».","requerTodas":["fr-p100","fr-p001","fr-p426","fr-p081"],"v":"1c5f36d2"},{"idioma":"fr","id":"fr-u546","tipo":"frase","requer":"fr-p427","fr":"En cas d'urgence, appelle ce numéro.","aceitasFr":["En cas d'urgence, appelez ce numéro."],"en":"In case of emergency, call this number.","aceitasEn":["in case of emergency call this number","in an emergency call this number","in case of an emergency call this number","in case of emergency dial this number","in an emergency dial this number","in case of emergency ring this number"],"distratoresEn":["In case of doubt, call this number.","In case of rain, call this number.","In case of fire, call this number.","In case of delay, call this number."],"nivel":"B1","tags":["saúde","cotidiano"],"notaEn":"«En cas de» takes a bare noun: «en cas d'urgence», in case of emergency. With «tu», the imperative of an «-er» verb drops the «s»: «appelle».","requerTodas":["fr-p427","fr-p229","fr-p215"],"v":"646f6e65"},{"idioma":"fr","id":"fr-u547","tipo":"frase","requer":"fr-p427","fr":"Il n'y a pas d'urgence, prends ton temps.","aceitasFr":["Il n'y a pas d'urgence, prenez votre temps.","Il n'y a pas urgence, prends ton temps."],"en":"There's no rush, take your time.","aceitasEn":["theres no rush take your time","there is no rush take your time","theres no hurry take your time","there is no hurry take your time","theres no urgency take your time","no rush take your time","no hurry take your time","its not urgent take your time"],"distratoresEn":["There's no line, take your time.","There's no class, take your time.","There's no fine, take your time.","There's no meeting, take your time."],"nivel":"B1","tags":["cotidiano","trabalho"],"notaEn":"«Il n'y a pas d'urgence», literally there's no urgency, is how you say there's no rush. «Prendre son temps» is to take one's time.","requerTodas":["fr-p002","fr-p427","fr-p011","fr-p025"],"v":"6ed9bf8c"},{"idioma":"fr","id":"fr-u548","tipo":"frase","requer":"fr-p427","fr":"Il faut aller aux urgences.","en":"We need to go to the ER.","aceitasEn":["we need to go to the er","we have to go to the er","we must go to the er","we need to go to the emergency room","we have to go to the emergency room","we need to go to the emergency department","you need to go to the er","you have to go to the er","you need to go to the emergency room"],"distratoresEn":["We need to go to the bank.","We need to go to the market.","We need to go to the post office.","We need to go to the dentist."],"nivel":"B1","tags":["saúde"],"notaEn":"In the plural, «les urgences» is the hospital's emergency room: «aller aux urgences». «Il faut» + infinitive means one has to, without saying who.","requerTodas":["fr-p122","fr-p003","fr-p427"],"v":"b45c2f87"},{"idioma":"fr","id":"fr-u549","tipo":"frase","requer":"fr-p428","fr":"Je doute qu'il vienne.","en":"I doubt he'll come.","aceitasEn":["i doubt hell come","i doubt he will come","i doubt that hell come","i doubt that he will come","i doubt hes coming","i doubt that hes coming","i doubt he comes"],"distratoresEn":["I hope he'll come.","I think he'll come.","I know he'll come.","I bet he'll come."],"nivel":"B1","tags":["cotidiano","subjuntivo"],"notaEn":"«Douter que» takes the subjunctive: «je doute qu'il vienne», from «venir». English uses the future instead: I doubt he'll come.","requerTodas":["fr-p428","fr-p009"],"v":"873b1d9a"},{"idioma":"fr","id":"fr-u550","tipo":"frase","requer":"fr-p428","fr":"Je ne doute pas de toi.","aceitasFr":["Je ne doute pas de vous."],"en":"I don't doubt you.","aceitasEn":["i dont doubt you","i do not doubt you","i have no doubts about you","i have no doubt about you"],"distratoresEn":["I don't need you.","I don't like you.","I don't blame you.","I don't miss you."],"nivel":"B1","tags":["social"],"notaEn":"«Douter de» takes «de», where English takes a direct object: «je doute de toi», I doubt you. In the negative, «ne… pas» wraps the verb.","requerTodas":["fr-p428"],"v":"69a39640"},{"idioma":"fr","id":"fr-u551","tipo":"frase","requer":"fr-p429","fr":"Je n'ai pas de monnaie.","en":"I don't have any change.","aceitasEn":["i dont have any change","i dont have change","i have no change","i do not have any change","i dont have any coins","i have no coins","ive got no change","i havent got any change","i dont have any small change"],"distratoresEn":["I don't have any money.","I don't have any time.","I don't have any credit.","I don't have any signal."],"nivel":"B1","tags":["compras","falso-amigo"],"notaEn":"«La monnaie» is change, small coins: «avoir de la monnaie». It is not money in general, which is «l'argent»; a single coin is «une pièce».","requerTodas":["fr-p002","fr-p429"],"v":"723758ca"},{"idioma":"fr","id":"fr-u552","tipo":"frase","requer":"fr-p429","fr":"Gardez la monnaie.","aceitasFr":["Garde la monnaie."],"en":"Keep the change.","aceitasEn":["keep the change","you can keep the change"],"distratoresEn":["Keep the receipt.","Keep the menu.","Keep the newspaper.","Keep the umbrella."],"nivel":"B1","tags":["compras"],"notaEn":"Said when paying: «gardez la monnaie», keep the change. «Garder» means to keep; giving change back is «rendre la monnaie».","requerTodas":["fr-p513","fr-p429"],"v":"49e156b8"},{"idioma":"fr","id":"fr-u553","tipo":"frase","requer":"fr-p429","fr":"L'euro est la monnaie de la France.","en":"The euro is the currency of France.","aceitasEn":["the euro is the currency of france","the euro is frances currency","the euro is the french currency","the euro is the official currency of france","frances currency is the euro"],"distratoresEn":["The euro is the wealth of France.","The euro is the strength of France.","The euro is the economy of France.","The euro is the brand of France."],"nivel":"B1","tags":["economia","viagem"],"notaEn":"«La monnaie» is also a country's currency: «la monnaie de la France». In French, country names take the article: «la France».","requerTodas":["fr-p128","fr-p001","fr-p429"],"v":"c4be5ccd"},{"idioma":"fr","id":"fr-u554","tipo":"frase","requer":"fr-p430","fr":"Je suis totalement perdu.","aceitasFr":["Je suis totalement perdue."],"en":"I'm totally lost.","aceitasEn":["im totally lost","i am totally lost","im completely lost","i am completely lost"],"distratoresEn":["I'm almost lost.","I'm always lost.","I'm a bit lost.","I'm kind of lost."],"nivel":"B1","tags":["cotidiano","viagem"],"notaEn":"«Totalement» comes from «total» and works just like totally. «Perdu», from «perdre», is lost on the way and also lost in a conversation.","requerTodas":["fr-p001","fr-p430","fr-p323"],"v":"000aeb90"},{"idioma":"fr","id":"fr-u555","tipo":"frase","requer":"fr-p431","fr":"Mets tes habits, on va sortir.","aceitasFr":["Mettez vos habits, on va sortir."],"en":"Put your clothes on, we're going out.","aceitasEn":["put your clothes on were going out","put on your clothes were going out","put your clothes on we are going out","get dressed were going out","get dressed we are going out"],"distratoresEn":["Put your shoes on, we're going out.","Put your gloves on, we're going out.","Put your glasses on, we're going out.","Put your boots on, we're going out."],"nivel":"B1","tags":["roupa","cotidiano","falso-amigo"],"notaEn":"«Les habits», masculine and almost always plural, means clothes; the more neutral word is «les vêtements». A habit is «une habitude».","requerTodas":["fr-p167","fr-p431","fr-p003","fr-p108"],"v":"af35b0ad"},{"idioma":"fr","id":"fr-u556","tipo":"frase","requer":"fr-p432","fr":"Apparemment, le magasin est fermé.","en":"Apparently, the store is closed.","aceitasEn":["apparently the store is closed","apparently the shop is closed","apparently the store is shut","apparently the shop is shut","it seems the store is closed","it seems that the store is closed","seemingly the store is closed","the store is closed apparently"],"distratoresEn":["Unfortunately, the store is closed.","Luckily, the store is closed.","Normally, the store is closed.","Finally, the store is closed."],"nivel":"B1","tags":["compras","cotidiano"],"notaEn":"«Apparemment» opens the sentence to report what seems true or what you heard. Note the double «p»; «-emment» sounds just like «-amment».","requerTodas":["fr-p432","fr-p223","fr-p001","fr-p206"],"v":"b8fca6bf"},{"idioma":"fr","id":"fr-u557","tipo":"frase","requer":"fr-p433","fr":"J'essaie de réduire le sucre.","aceitasFr":["J'essaye de réduire le sucre."],"en":"I'm trying to cut down on sugar.","aceitasEn":["im trying to cut down on sugar","im trying to cut back on sugar","im trying to reduce sugar","im trying to reduce my sugar","im trying to cut down on my sugar","i am trying to cut down on sugar","i try to cut down on sugar","im trying to eat less sugar"],"distratoresEn":["I'm trying to measure the sugar.","I'm trying to replace the sugar.","I'm trying to hide the sugar.","I'm trying to buy the sugar."],"nivel":"B1","tags":["comida","saúde"],"notaEn":"«Réduire» is conjugated like «conduire»: je réduis, nous réduisons, j'ai réduit. «Essayer de» + infinitive means to try to.","requerTodas":["fr-p301","fr-p433","fr-p351"],"v":"094afcd5"},{"idioma":"fr","id":"fr-u558","tipo":"frase","requer":"fr-p433","fr":"Ils ont réduit les prix.","aceitasFr":["Elles ont réduit les prix."],"en":"They reduced the prices.","aceitasEn":["they reduced the prices","they reduced prices","theyve reduced the prices","they have reduced the prices","they lowered the prices","they lowered prices","theyve lowered prices","they cut the prices","they cut prices","theyve cut prices"],"distratoresEn":["They raised the prices.","They changed the prices.","They doubled the prices.","They froze the prices."],"nivel":"B1","tags":["compras","economia"],"notaEn":"The past participle of «réduire» ends in «t»: «ils ont réduit». «Une réduction» is also a store discount.","requerTodas":["fr-p002","fr-p433","fr-p192"],"v":"3a16ed5c"},{"idioma":"fr","id":"fr-u559","tipo":"frase","requer":"fr-p434","fr":"Tu as fermé le gaz ?","aceitasFr":["Vous avez fermé le gaz ?"],"en":"Did you turn off the gas?","aceitasEn":["did you turn off the gas","did you turn the gas off","have you turned off the gas","have you turned the gas off","did you shut off the gas","did you switch off the gas"],"distratoresEn":["Did you turn off the radio?","Did you turn off the heater?","Did you turn off the iron?","Did you turn off the fan?"],"nivel":"B1","tags":["casa"],"notaEn":"Masculine, with a «z»: «le gaz». «Fermer le gaz», literally to close the gas, is to turn it off. Gas for the car is «l'essence».","requerTodas":["fr-p002","fr-p206","fr-p434"],"v":"04dc6ebd"},{"idioma":"fr","id":"fr-u560","tipo":"frase","requer":"fr-p435","fr":"La majorité des enfants ont un portable.","aceitasFr":["La majorité des enfants a un portable."],"en":"Most children have a phone.","aceitasEn":["most children have a phone","most kids have a phone","the majority of children have a phone","the majority of kids have a phone","most children have a cell phone","most children have a mobile phone","most kids have a cell phone","most children have phones","most kids have phones"],"distratoresEn":["Few children have a phone.","Some children have a phone.","All children have a phone.","No children have a phone."],"nivel":"B1","tags":["social","tecnologia"],"notaEn":"«La majorité de» means most of: «la majorité des enfants». The verb can be plural or singular. It is also the age of majority: «à sa majorité».","requerTodas":["fr-p435","fr-p023","fr-p002","fr-p212"],"v":"a01dc1fa"},{"idioma":"fr","id":"fr-u561","tipo":"frase","requer":"fr-p436","fr":"C'est la catastrophe !","en":"It's a disaster!","aceitasEn":["its a disaster","its a catastrophe","what a disaster","its a total disaster","this is a disaster"],"distratoresEn":["It's a party!","It's a joke!","It's a shame!","It's a miracle!"],"nivel":"B1","tags":["cotidiano","expressão"],"notaEn":"In conversation, «c'est la catastrophe !» fits any mess, from a burnt dinner to a failed exam. Note the definite article: «la catastrophe».","requerTodas":["fr-p001","fr-p436"],"v":"06a74089"},{"idioma":"fr","id":"fr-u562","tipo":"frase","requer":"fr-p437","fr":"Je suis très occupé aujourd'hui.","aceitasFr":["Je suis très occupée aujourd'hui."],"en":"I'm very busy today.","aceitasEn":["im very busy today","i am very busy today","im really busy today","im so busy today","today im very busy","im super busy today"],"distratoresEn":["I'm very tired today.","I'm very excited today.","I'm very calm today.","I'm very nervous today."],"nivel":"B1","tags":["trabalho","cotidiano"],"notaEn":"Feminine «occupée». The related verb «s'occuper de» means to take care of: «je m'occupe des enfants».","requerTodas":["fr-p001","fr-p043","fr-p437","fr-p049"],"v":"d2cfa792"},{"idioma":"fr","id":"fr-u563","tipo":"frase","requer":"fr-p437","fr":"Cette place est occupée ?","en":"Is this seat taken?","aceitasEn":["is this seat taken","is this seat occupied","is this place taken","is this spot taken","is this chair taken","is anyone sitting here","is somebody sitting here"],"distratoresEn":["Is this seat free?","Is this seat reserved?","Is this seat clean?","Is this seat dirty?"],"nivel":"B1","tags":["viagem","cotidiano"],"notaEn":"«La place» is a seat or spot: on the train, at the movies, in a café. Hence the feminine «occupée», agreeing with «place».","requerTodas":["fr-p218","fr-p001","fr-p437"],"v":"54af84d8"},{"idioma":"fr","id":"fr-u564","tipo":"frase","requer":"fr-p438","fr":"J'achète toujours des œufs biologiques.","aceitasFr":["J'achète toujours des œufs bio."],"en":"I always buy organic eggs.","aceitasEn":["i always buy organic eggs","i always get organic eggs"],"distratoresEn":["I always buy fresh eggs.","I always buy white eggs.","I always buy large eggs.","I always buy boiled eggs."],"nivel":"B1","tags":["comida","compras"],"notaEn":"At the market, «biologique» means organic, usually shortened to «bio»: «des œufs bio». In the plural, «œufs» is said without the «f».","requerTodas":["fr-p075","fr-p046","fr-p281","fr-p438"],"v":"5705602d"},{"idioma":"fr","id":"fr-u565","tipo":"frase","requer":"fr-p438","fr":"Je ne connais pas mon père biologique.","en":"I don't know my biological father.","aceitasEn":["i dont know my biological father","i do not know my biological father","i dont know my birth father","i dont know my biological dad"],"distratoresEn":["I don't know my adoptive father.","I don't know my spiritual father.","I don't know my Brazilian father.","I don't know my French father."],"nivel":"B1","tags":["família"],"notaEn":"In a family, «biologique» is by blood, the opposite of «adoptif». «Connaître» is to know a person; «savoir», to know a fact.","requerTodas":["fr-p119","fr-p103","fr-p438"],"v":"95bef2f7"},{"idioma":"fr","id":"fr-u566","tipo":"frase","requer":"fr-p439","fr":"Le sucre est dans le pot bleu.","en":"The sugar is in the blue jar.","aceitasEn":["the sugar is in the blue jar","the sugars in the blue jar","the sugar is in the blue pot","the sugar is in the blue container","the sugar is in the blue canister"],"distratoresEn":["The sugar is in the blue glass.","The sugar is in the blue bag.","The sugar is in the blue cupboard.","The sugar is in the blue plate."],"nivel":"B1","tags":["casa","comida"],"notaEn":"«Le pot», with a silent «t», is a jar or tub: «un pot de confiture», a jar of jam. A flowerpot is «un pot de fleurs».","requerTodas":["fr-p351","fr-p001","fr-p439","fr-p346"],"v":"6ca919da"},{"idioma":"fr","id":"fr-u567","tipo":"frase","requer":"fr-p439","fr":"On prend un pot après le travail ?","aceitasFr":["On va prendre un pot après le travail ?","Tu veux prendre un pot après le travail ?"],"en":"Shall we get a drink after work?","aceitasEn":["shall we get a drink after work","shall we grab a drink after work","shall we have a drink after work","should we get a drink after work","lets get a drink after work","lets grab a drink after work","lets have a drink after work","want to grab a drink after work","how about a drink after work"],"distratoresEn":["Shall we get some air after work?","Shall we get an ice cream after work?","Shall we get a taxi after work?","Shall we get a bite after work?"],"nivel":"B1","tags":["social","expressão"],"notaEn":"Informally, «prendre un pot» is to have a drink, usually at a bar, like «boire un verre». «On» with a present-tense verb makes the suggestion: shall we?","requerTodas":["fr-p011","fr-p439","fr-p029"],"v":"a6bdbcdf"},{"idioma":"fr","id":"fr-u568","tipo":"frase","requer":"fr-p440","fr":"Il gère un restaurant.","en":"He manages a restaurant.","aceitasEn":["he manages a restaurant","he runs a restaurant"],"distratoresEn":["He opens a restaurant.","He sells a restaurant.","He owns a restaurant.","He visits a restaurant."],"nivel":"B1","tags":["trabalho","falso-amigo"],"notaEn":"«Gérer» means to manage or run. The accent shifts as it conjugates: «je gère», but «nous gérons». To generate is «générer».","requerTodas":["fr-p440","fr-p098"],"v":"27755707"},{"idioma":"fr","id":"fr-u569","tipo":"frase","requer":"fr-p440","fr":"Ne t'inquiète pas, je gère !","aceitasFr":["Ne vous inquiétez pas, je gère !","T'inquiète pas, je gère !"],"en":"Don't worry, I've got this!","aceitasEn":["dont worry ive got this","dont worry i got this","dont worry ive got it","dont worry i can handle it","dont worry ill handle it","dont worry im on it","dont worry ive got it under control","dont worry leave it to me","do not worry ive got this"],"distratoresEn":["Don't worry, I'll pay!","Don't worry, I'll drive!","Don't worry, I'll call!","Don't worry, I'll be back!"],"nivel":"B1","tags":["cotidiano","expressão"],"notaEn":"Informally, «je gère» on its own means I've got this, I can handle it. In the negative imperative «ne t'inquiète pas», the pronoun stays before the verb.","requerTodas":["fr-p395","fr-p440"],"v":"8f156fee"},{"idioma":"fr","id":"fr-u570","tipo":"frase","requer":"fr-p441","fr":"Il connaît les dix commandements.","en":"He knows the ten commandments.","aceitasEn":["he knows the ten commandments","he knows the 10 commandments"],"distratoresEn":["He knows the ten secrets.","He knows the ten chapters.","He knows the ten challenges.","He knows the ten proverbs."],"nivel":"B1","tags":["cultura"],"notaEn":"The biblical Ten Commandments are «les dix commandements». An order, in a shop or restaurant, is a different word: «la commande».","requerTodas":["fr-p119","fr-p121","fr-p441"],"v":"89e35b19"},{"idioma":"fr","id":"fr-u571","tipo":"frase","requer":"fr-p441","fr":"Elle a pris le commandement du bateau.","en":"She took command of the boat.","aceitasEn":["she took command of the boat","she took command of the ship","she took charge of the boat","she took control of the boat","she assumed command of the boat","she took over command of the boat"],"distratoresEn":["She took care of the boat.","She took pictures of the boat.","She took notice of the boat.","She took possession of the boat."],"nivel":"B1","tags":["trabalho","viagem"],"notaEn":"«Le commandement» is also command, leadership: «prendre le commandement», to take command of a ship, a unit, a team.","requerTodas":["fr-p002","fr-p011","fr-p441","fr-p398"],"v":"6fe8db63"},{"idioma":"fr","id":"fr-u572","tipo":"frase","requer":"fr-p442","fr":"Mon beau-père est médecin.","en":"My father-in-law is a doctor.","aceitasEn":["my father-in-law is a doctor","my father in law is a doctor","my stepfather is a doctor","my stepdad is a doctor"],"distratoresEn":["My brother-in-law is a doctor.","My son-in-law is a doctor.","My godfather is a doctor.","My uncle is a doctor."],"nivel":"B1","tags":["família","trabalho"],"notaEn":"«Le beau-père» is both father-in-law and stepfather: context decides. After «être», jobs take no article: «il est médecin», he's a doctor.","requerTodas":["fr-p442","fr-p001","fr-p155"],"v":"723f37ec"},{"idioma":"fr","id":"fr-u573","tipo":"frase","requer":"fr-p442","fr":"Ma mère s'est remariée, j'ai un beau-père.","en":"My mother remarried, so I have a stepfather.","aceitasEn":["my mother remarried so i have a stepfather","my mother remarried i have a stepfather","my mother remarried so i have a stepdad","my mom remarried so i have a stepfather","my mom remarried so i have a stepdad","my mum remarried so i have a stepfather","my mother got remarried so i have a stepfather","my mom got remarried so i have a stepdad","my mother has remarried so i have a stepfather"],"distratoresEn":["My mother remarried, so I have a stepbrother.","My mother remarried, so I have a half-brother.","My mother remarried, so I have a godfather.","My mother remarried, so I have a brother-in-law."],"nivel":"B1","tags":["família"],"notaEn":"Here «le beau-père» is the stepfather, the mother's husband. «Se remarier» takes «être» in the passé composé, and the participle agrees: «elle s'est remariée».","requerTodas":["fr-p063","fr-p476","fr-p001","fr-p002","fr-p442"],"v":"3e9a9287"},{"idioma":"fr","id":"fr-u574","tipo":"frase","requer":"fr-p443","fr":"N'oublie pas ta serviette pour la plage.","aceitasFr":["N'oubliez pas votre serviette pour la plage."],"en":"Don't forget your towel for the beach.","aceitasEn":["dont forget your towel for the beach","do not forget your towel for the beach","dont forget your beach towel","dont forget a towel for the beach","dont forget to bring your towel to the beach","dont forget to take your towel to the beach"],"distratoresEn":["Don't forget your bag for the beach.","Don't forget your chair for the beach.","Don't forget your board for the beach.","Don't forget your camera for the beach."],"nivel":"B1","tags":["casa","viagem"],"notaEn":"«La serviette» is a bath or beach towel, and also a napkin; a tablecloth is «la nappe». In the imperative, «tu oublies» drops the «s»: «n'oublie pas».","requerTodas":["fr-p197","fr-p443","fr-p087"],"v":"d4d02680"},{"idioma":"fr","id":"fr-u575","tipo":"frase","requer":"fr-p443","fr":"Il n'y a pas de serviettes sur la table.","en":"There are no napkins on the table.","aceitasEn":["there are no napkins on the table","there arent any napkins on the table","there are not any napkins on the table","theres no napkins on the table","there are no serviettes on the table","there arent any serviettes on the table"],"distratoresEn":["There are no forks on the table.","There are no plates on the table.","There are no glasses on the table.","There are no spoons on the table."],"nivel":"B1","tags":["casa","comida"],"notaEn":"At the table, «la serviette» is the napkin. After a negative, «des» becomes «de»: «il n'y a pas de serviettes».","requerTodas":["fr-p002","fr-p443","fr-p143"],"v":"83669d38"},{"idioma":"fr","id":"fr-u576","tipo":"frase","requer":"fr-p444","fr":"C'est un travail pénible.","en":"It's a tiring job.","aceitasEn":["its a tiring job","it is a tiring job","its a hard job","its a tough job","its an exhausting job","its a grueling job","its a gruelling job","its a painful job","its a tedious job","its a draining job","its tiring work","its hard work"],"distratoresEn":["It's a fun job.","It's a dangerous job.","It's a simple job.","It's a curious job."],"nivel":"B1","tags":["trabalho"],"notaEn":"«Pénible» describes what wears you out or hurts: «un travail pénible», a grueling job; «une nouvelle pénible», painful news. Same form in the feminine.","requerTodas":["fr-p001","fr-p029","fr-p444"],"v":"92807148"},{"idioma":"fr","id":"fr-u577","tipo":"frase","requer":"fr-p444","fr":"Ton frère est vraiment pénible.","en":"Your brother is really annoying.","aceitasEn":["your brother is really annoying","your brothers really annoying","your brother is so annoying","your brother is very annoying","your brother is really irritating","your brother is a real pain","your brother is a pain","your brother is such a pain"],"distratoresEn":["Your brother is really funny.","Your brother is really nice.","Your brother is really stubborn.","Your brother is really shy."],"nivel":"B1","tags":["família","social"],"notaEn":"Said of a person, «pénible» means annoying, a pain: «arrête, tu es pénible !», stop it, you're being a pain!","requerTodas":["fr-p078","fr-p001","fr-p379","fr-p444"],"v":"59cb560d"},{"idioma":"fr","id":"fr-u578","tipo":"frase","requer":"fr-p445","fr":"Il fait très attention à son apparence.","en":"He pays a lot of attention to his appearance.","aceitasEn":["he pays a lot of attention to his appearance","he pays close attention to his appearance","he pays great attention to his appearance","he takes great care of his appearance","he takes good care of his appearance","he cares a lot about his appearance","he really cares about his appearance","he is very careful about his appearance","hes very careful about his appearance"],"distratoresEn":["He pays a lot of attention to his health.","He pays a lot of attention to his house.","He pays a lot of attention to his family.","He pays a lot of attention to his diet."],"nivel":"B1","tags":["social"],"notaEn":"«Faire attention à» means to pay attention to, to watch: «faire attention à son apparence». Spelling: «apparence» ends in «-ence», unlike English «appearance».","requerTodas":["fr-p004","fr-p043","fr-p127","fr-p445"],"v":"9b9a269e"},{"idioma":"fr","id":"fr-u579","tipo":"frase","requer":"fr-p446","fr":"Je voudrais un steak bien cuit.","en":"I'd like a steak, well done.","aceitasEn":["id like a steak well done","id like a well done steak","id like a well-done steak","i would like a steak well done","i would like a well done steak","id like my steak well done","can i have a steak well done","can i have a well done steak"],"distratoresEn":["I'd like a salmon fillet, well done.","I'd like a pork chop, well done.","I'd like a lamb chop, well done.","I'd like a chicken breast, well done."],"nivel":"B1","tags":["comida"],"notaEn":"How it's cooked: «bien cuit», well done; «à point», medium; «saignant», rare. «Je voudrais», I would like, is the polite way to order.","requerTodas":["fr-p007","fr-p446","fr-p044","fr-p529"],"v":"619d36df"},{"idioma":"fr","id":"fr-u580","tipo":"frase","requer":"fr-p447","fr":"Tu as payé la facture ?","aceitasFr":["Vous avez payé la facture ?"],"en":"Did you pay the bill?","aceitasEn":["did you pay the bill","have you paid the bill","did you pay the invoice","have you paid the invoice"],"distratoresEn":["Did you pay the fine?","Did you pay the fare?","Did you pay the rent?","Did you pay the tip?"],"nivel":"B1","tags":["compras","casa"],"notaEn":"«La facture» is a bill for utilities or services, or an invoice. The bill at a restaurant is a different word: «l'addition».","requerTodas":["fr-p002","fr-p170","fr-p447"],"v":"bbcef43e"},{"idioma":"fr","id":"fr-u581","tipo":"frase","requer":"fr-p448","fr":"Fumer, c'est mauvais pour les poumons.","en":"Smoking is bad for your lungs.","aceitasEn":["smoking is bad for your lungs","smoking is bad for the lungs","smoking is bad for lungs","smoking harms your lungs","smoking damages your lungs"],"distratoresEn":["Smoking is bad for your teeth.","Smoking is bad for your eyes.","Smoking is bad for your kidneys.","Smoking is bad for your bones."],"nivel":"B1","tags":["saúde","corpo"],"notaEn":"«Le poumon», spelled with «ou», is masculine. The infinitive acts as subject and is picked up by «c'est»: «fumer, c'est mauvais».","requerTodas":["fr-p221","fr-p001","fr-p369","fr-p448"],"v":"8e2386d8"},{"idioma":"fr","id":"fr-u582","tipo":"frase","requer":"fr-p449","fr":"Elle a écrit un poème pour sa mère.","en":"She wrote a poem for her mother.","aceitasEn":["she wrote a poem for her mother","she wrote a poem for her mom","she wrote a poem for her mum","she wrote her mother a poem","she wrote her mom a poem","shes written a poem for her mother","she has written a poem for her mother"],"distratoresEn":["She wrote a note for her mother.","She wrote a story for her mother.","She wrote a letter for her mother.","She wrote a book for her mother."],"nivel":"B1","tags":["cultura","família"],"notaEn":"«Le poème», masculine with «è», is a poem; poetry is «la poésie». «Sa mère» can be her mother or his: the possessive agrees with «mère».","requerTodas":["fr-p002","fr-p184","fr-p449","fr-p063"],"v":"4ae59e40"},{"idioma":"fr","id":"fr-u584","tipo":"frase","requer":"fr-p450","fr":"Je vais essayer le pantalon en cabine.","en":"I'm going to try on the pants in the fitting room.","aceitasEn":["im going to try on the pants in the fitting room","im going to try the pants on in the fitting room","i am going to try on the pants in the fitting room","im going to try on the trousers in the fitting room","im going to try the trousers on in the fitting room","im going to try on the pants in the changing room","im going to try on the pants in the dressing room"],"distratoresEn":["I'm going to try on the pants in the hallway.","I'm going to try on the pants at the counter.","I'm going to try on the pants in the stockroom.","I'm going to try on the pants in the bathroom."],"nivel":"B2","tags":["compras","roupa"],"notaEn":"In a shop, «la cabine» (or «la cabine d'essayage») is the fitting room, and «en cabine» takes no article. «Essayer» is to try on, and also to try.","requerTodas":["fr-p003","fr-p301","fr-p279","fr-p450"],"v":"a8fb6bd3"},{"idioma":"fr","id":"fr-u585","tipo":"frase","requer":"fr-p450","fr":"Sur le bateau, notre cabine est petite mais propre.","en":"On the boat, our cabin is small but clean.","aceitasEn":["on the boat our cabin is small but clean","on the ship our cabin is small but clean","our cabin on the boat is small but clean","on the boat the cabin is small but clean","on the boat our cabin is small but its clean"],"distratoresEn":["On the boat, our kitchen is small but clean.","On the boat, our lounge is small but clean.","On the boat, our pool is small but clean.","On the boat, our table is small but clean."],"nivel":"B2","tags":["viagem"],"notaEn":"On a ship or a plane, «la cabine» is the cabin. After the noun or with «être», «propre» means clean; before the noun, own: «ma propre cabine».","requerTodas":["fr-p398","fr-p450","fr-p001","fr-p038","fr-p296"],"v":"2f65096a"},{"idioma":"fr","id":"fr-u586","tipo":"frase","requer":"fr-p451","fr":"On ne peut pas photographier dans le musée.","en":"You can't take pictures in the museum.","aceitasEn":["you cant take pictures in the museum","you cant take photos in the museum","you cannot take pictures in the museum","you cannot take photos in the museum","you arent allowed to take pictures in the museum","you arent allowed to take photos in the museum","you cant take pictures inside the museum","photography isnt allowed in the museum","no photography in the museum"],"distratoresEn":["You can't eat in the museum.","You can't run in the museum.","You can't smoke in the museum.","You can't shout in the museum."],"nivel":"B2","tags":["cultura","viagem"],"notaEn":"«On ne peut pas», you can't: a general rule. In conversation people also say «prendre des photos»; signs read «interdit de photographier». French has one verb where English says take pictures.","requerTodas":["fr-p006","fr-p451","fr-p234"],"v":"89b4295d"},{"idioma":"fr","id":"fr-u587","tipo":"frase","requer":"fr-p452","fr":"Il faut isoler la maison avant l'hiver.","en":"We need to insulate the house before winter.","aceitasEn":["we need to insulate the house before winter","we have to insulate the house before winter","we need to insulate the house before the winter","we must insulate the house before winter","you need to insulate the house before winter","you have to insulate the house before winter","the house needs to be insulated before winter","the house needs insulating before winter"],"distratoresEn":["We need to paint the house before winter.","We need to clean the house before winter.","We need to sell the house before winter.","We need to fix the house before winter."],"nivel":"B2","tags":["casa"],"notaEn":"English insulates a house, but French uses the same verb as for isolating: «isoler». Thermal insulation is «l'isolation». «Il faut» + infinitive: we need to, without saying who.","requerTodas":["fr-p122","fr-p452","fr-p020","fr-p284"],"v":"ee87852d"},{"idioma":"fr","id":"fr-u588","tipo":"frase","requer":"fr-p452","fr":"Le médecin a isolé le malade.","en":"The doctor isolated the patient.","aceitasEn":["the doctor isolated the patient","the doctor isolated the sick man","the doctor isolated the sick person","the doctor has isolated the patient","the doctor put the patient in isolation"],"distratoresEn":["The doctor examined the patient.","The doctor operated on the patient.","The doctor calmed the patient.","The doctor discharged the patient."],"nivel":"B2","tags":["saúde"],"notaEn":"«Le malade» is the adjective «malade» used as a noun: the sick person. Isolating a person is «l'isolement»; insulating a house, «l'isolation».","requerTodas":["fr-p155","fr-p002","fr-p452","fr-p166"],"v":"f3843226"},{"idioma":"fr","id":"fr-u589","tipo":"frase","requer":"fr-p453","fr":"Il a voyagé sur tous les continents.","en":"He has traveled to every continent.","aceitasEn":["he has traveled to every continent","hes traveled to every continent","he has travelled to every continent","hes travelled to every continent","he has been to every continent","hes been to every continent","he has traveled to all the continents","he traveled to every continent","he has traveled on every continent"],"distratoresEn":["He has traveled to every country.","He has traveled to every sea.","He has traveled to every state.","He has traveled to every ocean."],"nivel":"B2","tags":["viagem"],"notaEn":"With a continent's name, French uses «en»: «en Afrique», «en Europe». With the word «continent» itself, «sur»: «sur tous les continents».","requerTodas":["fr-p002","fr-p183","fr-p070","fr-p453"],"v":"1e390ce8"},{"idioma":"fr","id":"fr-u590","tipo":"frase","requer":"fr-p453","fr":"Demain, nous rentrons sur le continent.","en":"Tomorrow we're going back to the mainland.","aceitasEn":["tomorrow were going back to the mainland","tomorrow we are going back to the mainland","were going back to the mainland tomorrow","tomorrow we go back to the mainland","tomorrow were returning to the mainland","tomorrow were heading back to the mainland","tomorrow were going back to the continent"],"distratoresEn":["Tomorrow we're going back to the hotel.","Tomorrow we're going back to the port.","Tomorrow we're going back to the village.","Tomorrow we're going back to the boat."],"nivel":"B2","tags":["viagem"],"notaEn":"From an island, «le continent» is the mainland: from Corsica, it's mainland France. English has a separate word; French just says «continent».","requerTodas":["fr-p059","fr-p071","fr-p453"],"v":"8cf964e4"},{"idioma":"fr","id":"fr-u591","tipo":"frase","requer":"fr-p454","fr":"Dans la panique, j'ai oublié mon passeport.","en":"In the panic, I forgot my passport.","aceitasEn":["in the panic i forgot my passport","in all the panic i forgot my passport","in my panic i forgot my passport","i forgot my passport in the panic","in the panic i forgot the passport"],"distratoresEn":["In the noise, I forgot my passport.","In the heat, I forgot my passport.","In the dark, I forgot my passport.","In the rush, I forgot my passport."],"nivel":"B2","tags":["viagem"],"notaEn":"«Dans la panique», in the panic. «Pas de panique !» means don't panic. The noun is feminine: «la panique».","requerTodas":["fr-p454","fr-p002","fr-p197","fr-p216"],"v":"b0a2f75a"},{"idioma":"fr","id":"fr-u592","tipo":"frase","requer":"fr-p455","fr":"La ville attend une aide fédérale.","en":"The city is waiting for federal aid.","aceitasEn":["the city is waiting for federal aid","the city is waiting for federal help","the city awaits federal aid","the town is waiting for federal aid"],"distratoresEn":["The city is waiting for state aid.","The city is waiting for local aid.","The city is waiting for foreign aid.","The city is waiting for urgent aid."],"nivel":"B2","tags":["política"],"notaEn":"Feminine «fédérale», plural «fédéraux». You hear it mostly about Switzerland, Belgium and Canada, which are federations; France is not.","requerTodas":["fr-p028","fr-p018","fr-p213","fr-p455"],"v":"c7ce7459"},{"idioma":"fr","id":"fr-u593","tipo":"frase","requer":"fr-p456","fr":"Il prend la pose pour la photo.","en":"He poses for the photo.","aceitasEn":["he poses for the photo","he poses for the picture","hes posing for the photo","hes posing for the picture","he is posing for the photo","he strikes a pose for the photo","he strikes a pose for the picture"],"distratoresEn":["He smiles for the photo.","He waits for the photo.","He pays for the photo.","He stops for the photo."],"nivel":"B2","tags":["cultura"],"notaEn":"To pose is «prendre la pose», literally to take the pose; «poser» works too. Don't mix up «la pose» with «la pause», a break.","requerTodas":["fr-p011","fr-p456","fr-p515"],"v":"09d1421d"},{"idioma":"fr","id":"fr-u594","tipo":"frase","requer":"fr-p456","fr":"La pose de la cuisine coûte cher.","en":"Installing the kitchen is expensive.","aceitasEn":["installing the kitchen is expensive","installing the kitchen costs a lot","the kitchen installation is expensive","the kitchen installation costs a lot","the installation of the kitchen is expensive","fitting the kitchen is expensive"],"distratoresEn":["Cleaning the kitchen is expensive.","Remodeling the kitchen is expensive.","Painting the kitchen is expensive.","Demolishing the kitchen is expensive."],"nivel":"B2","tags":["casa"],"notaEn":"In building work, «la pose» is fitting, installation: «la pose du carrelage», laying the tiles. It comes from «poser», to put. In «coûter cher», to be expensive, «cher» never changes.","requerTodas":["fr-p456","fr-p088","fr-p321","fr-p199"],"v":"6addb5c5"},{"idioma":"fr","id":"fr-u595","tipo":"frase","requer":"fr-p457","fr":"J'ai une couronne sur cette dent.","en":"I have a crown on this tooth.","aceitasEn":["i have a crown on this tooth","ive got a crown on this tooth","i have a crown on that tooth","this tooth has a crown"],"distratoresEn":["I have a cavity in this tooth.","I have a stain on this tooth.","I have a crack in this tooth.","I have a filling in this tooth."],"nivel":"B2","tags":["saúde","corpo"],"notaEn":"Same word as the king's crown: the dental crown is also «la couronne». A filling is «le plombage»; a cavity, «la carie».","requerTodas":["fr-p002","fr-p457","fr-p362"],"v":"9adea78c"},{"idioma":"fr","id":"fr-u596","tipo":"frase","requer":"fr-p457","fr":"La couronne du roi est au musée.","en":"The king's crown is in the museum.","aceitasEn":["the kings crown is in the museum","the kings crown is at the museum","the crown of the king is in the museum"],"distratoresEn":["The king's sword is in the museum.","The king's bed is in the museum.","The king's letter is in the museum.","The king's robe is in the museum."],"nivel":"B2","tags":["cultura"],"notaEn":"Feminine: «la couronne». «Au musée», in the museum: «à» + «le» contracts to «au». With a capital, «la Couronne» is the monarchy.","requerTodas":["fr-p457","fr-p514","fr-p001","fr-p234"],"v":"84c65e43"},{"idioma":"fr","id":"fr-u597","tipo":"frase","requer":"fr-p458","fr":"On ne sait pas qui est le tueur.","en":"Nobody knows who the killer is.","aceitasEn":["nobody knows who the killer is","no one knows who the killer is","we dont know who the killer is","its not known who the killer is","nobody knows who the murderer is","no one knows who the murderer is","we dont know who the murderer is"],"distratoresEn":["Nobody knows who the thief is.","Nobody knows who the owner is.","Nobody knows who the father is.","Nobody knows who the winner is."],"nivel":"B2","tags":["mídia"],"notaEn":"«Le tueur» comes from «tuer», to kill. «Un tueur en série», a serial killer; «un tueur à gages», a hitman. «On ne sait pas»: nobody knows.","requerTodas":["fr-p008","fr-p001","fr-p458"],"v":"e9e46871"},{"idioma":"fr","id":"fr-u598","tipo":"frase","requer":"fr-p459","fr":"C'était une journée ordinaire.","en":"It was an ordinary day.","aceitasEn":["it was an ordinary day","it was a normal day","it was just an ordinary day","it was a day like any other","it was a regular day","it was a typical day","it was an average day"],"distratoresEn":["It was a long day.","It was a sad day.","It was a hard day.","It was a perfect day."],"nivel":"B2","tags":["cotidiano"],"notaEn":"«Ordinaire», ordinary, everyday. «Une journée» is the day as it is lived, from morning to night; «un jour» is the day as a unit.","requerTodas":["fr-p001","fr-p137","fr-p459"],"v":"3b48650b"},{"idioma":"fr","id":"fr-u599","tipo":"frase","requer":"fr-p460","fr":"La vie est parfois cruelle.","en":"Life is sometimes cruel.","aceitasEn":["life is sometimes cruel","sometimes life is cruel","life is cruel sometimes","life can be cruel","life can be cruel sometimes","sometimes life can be cruel"],"distratoresEn":["Life is sometimes hard.","Life is sometimes sad.","Life is sometimes strange.","Life is sometimes funny."],"nivel":"B2","tags":["social"],"notaEn":"Feminine «cruelle», with a double «l». «La vie», life: French puts the article before abstract nouns.","requerTodas":["fr-p250","fr-p001","fr-p204","fr-p460"],"v":"b1e22f51"},{"idioma":"fr","id":"fr-u600","tipo":"frase","requer":"fr-p461","fr":"On a trouvé une bombe près de la gare.","en":"They found a bomb near the station.","aceitasEn":["they found a bomb near the station","they found a bomb near the train station","a bomb was found near the station","a bomb has been found near the station","someone found a bomb near the station","we found a bomb near the station"],"distratoresEn":["They found a suitcase near the station.","They found a gun near the station.","They found a wallet near the station.","They found a bag near the station."],"nivel":"B2","tags":["mídia","cidade"],"notaEn":"«On» with no face: they, someone. «La gare» is the train station; a metro station is «la station».","requerTodas":["fr-p002","fr-p193","fr-p461","fr-p246","fr-p188"],"v":"c45e4e32"},{"idioma":"fr","id":"fr-u601","tipo":"frase","requer":"fr-p461","fr":"J'ai acheté une bombe de peinture.","en":"I bought a can of spray paint.","aceitasEn":["i bought a can of spray paint","i bought some spray paint","i bought spray paint","i bought a spray can","i bought a spray paint can","i bought a spray can of paint","ive bought a can of spray paint"],"distratoresEn":["I bought a bucket of paint.","I bought a pot of paint.","I bought a gallon of paint.","I bought a tube of paint."],"nivel":"B2","tags":["compras","casa"],"notaEn":"Besides the one that explodes, «la bombe» is an aerosol can: «une bombe de peinture», spray paint; «une bombe anti-moustiques», bug spray.","requerTodas":["fr-p002","fr-p075","fr-p461","fr-p528"],"v":"dfa4a6cc"},{"idioma":"fr","id":"fr-u602","tipo":"frase","requer":"fr-p462","fr":"C'est un client régulier.","en":"He's a regular customer.","aceitasEn":["hes a regular customer","he is a regular customer","hes a regular","he is a regular","hes a regular client","its a regular customer","thats a regular customer"],"distratoresEn":["He's a new customer.","He's a difficult customer.","He's a rich customer.","He's an annoying customer."],"nivel":"B2","tags":["compras","trabalho"],"notaEn":"Feminine «régulière»: «une cliente régulière». In a café, a regular is also «un habitué».","requerTodas":["fr-p001","fr-p391","fr-p462"],"v":"7d1fdf64"},{"idioma":"fr","id":"fr-u603","tipo":"frase","requer":"fr-p462","fr":"Mange à heures régulières.","aceitasFr":["Mangez à heures régulières.","Mange à des heures régulières.","Mangez à des heures régulières."],"en":"Eat at regular times.","aceitasEn":["eat at regular times","eat at regular hours","eat at set times","eat at fixed times","always eat at the same time","eat at the same times every day"],"distratoresEn":["Eat at different times.","Eat at odd times.","Eat at random times.","Eat at unusual times."],"nivel":"B2","tags":["saúde","comida"],"notaEn":"«À heures régulières», at regular times, takes no article. «Mange», with no «-s», is the «tu» imperative; the «vous» form is «mangez».","requerTodas":["fr-p013","fr-p129","fr-p462"],"v":"e75b1db0"},{"idioma":"fr","id":"fr-u604","tipo":"frase","requer":"fr-p463","fr":"J'ai acheté ce livre à la librairie.","en":"I bought this book at the bookstore.","aceitasEn":["i bought this book at the bookstore","i bought this book at the bookshop","i bought this book in the bookstore","i bought this book in the bookshop","i bought the book at the bookstore","i got this book at the bookstore"],"distratoresEn":["I bought this book at the library.","I bought this book at the newsstand.","I bought this book at the fair.","I bought this book at the station."],"nivel":"B2","tags":["compras","cultura"],"notaEn":"False friend: «la librairie» sells books; it's a bookstore. The library, where you borrow them, is «la bibliothèque».","requerTodas":["fr-p002","fr-p075","fr-p033","fr-p463"],"v":"6c3dd616"},{"idioma":"fr","id":"fr-u605","tipo":"frase","requer":"fr-p464","fr":"N'oublie pas de mettre le verrou.","aceitasFr":["N'oubliez pas de mettre le verrou.","N'oublie pas de pousser le verrou.","N'oubliez pas de pousser le verrou."],"en":"Don't forget to bolt the door.","aceitasEn":["dont forget to bolt the door","do not forget to bolt the door","dont forget to slide the bolt","dont forget to put the bolt on","dont forget the bolt","remember to bolt the door"],"distratoresEn":["Don't forget to paint the door.","Don't forget to clean the door.","Don't forget to close the door.","Don't forget to open the door."],"nivel":"B2","tags":["casa"],"notaEn":"To bolt the door is «mettre le verrou», or «pousser le verrou». A keyed lock is «la serrure». «N'oublie pas de» + infinitive: don't forget to.","requerTodas":["fr-p197","fr-p167","fr-p464"],"v":"36369c9c"},{"idioma":"fr","id":"fr-u606","tipo":"frase","requer":"fr-p464","fr":"Il est sous les verrous.","en":"He's behind bars.","aceitasEn":["hes behind bars","he is behind bars","hes in jail","he is in jail","hes in prison","he is in prison","hes locked up","he is locked up"],"distratoresEn":["He's behind the door.","He's behind the curtain.","He's behind the scenes.","He's behind schedule."],"nivel":"B2","tags":["jurídico","expressão"],"notaEn":"«Sous les verrous», literally under the bolts, is behind bars. «Mettre quelqu'un sous les verrous», to put someone behind bars.","requerTodas":["fr-p001","fr-p464"],"v":"50df7b9d"},{"idioma":"fr","id":"fr-u607","tipo":"frase","requer":"fr-p465","fr":"Regarde le prix sur l'étiquette.","aceitasFr":["Regardez le prix sur l'étiquette."],"en":"Look at the price on the tag.","aceitasEn":["look at the price on the tag","look at the price on the label","check the price on the tag","check the price on the label","look at the price tag","check the price tag","see the price on the tag"],"distratoresEn":["Look at the price on the screen.","Look at the price on the receipt.","Look at the price on the menu.","Look at the price on the box."],"nivel":"B2","tags":["compras"],"notaEn":"The price is «sur l'étiquette», on the tag. «L'étiquette» is the price tag, the clothing label and the bottle label.","requerTodas":["fr-p172","fr-p192","fr-p465"],"v":"051dfd9d"},{"idioma":"fr","id":"fr-u608","tipo":"frase","requer":"fr-p465","fr":"Lisez l'étiquette avant de prendre ce médicament.","aceitasFr":["Lis l'étiquette avant de prendre ce médicament."],"en":"Read the label before taking this medicine.","aceitasEn":["read the label before taking this medicine","read the label before you take this medicine","read the label before taking this medication","read the label before you take this medication","read the label before taking this drug"],"distratoresEn":["Read the manual before taking this medicine.","Read the receipt before taking this medicine.","Read the leaflet before taking this medicine.","Read the prescription before taking this medicine."],"nivel":"B2","tags":["saúde"],"notaEn":"On bottles and boxes, «l'étiquette» is the label. The leaflet inside is «la notice». You «prendre» medicine: take it.","requerTodas":["fr-p076","fr-p465","fr-p011","fr-p265"],"v":"12e01070"},{"idioma":"fr","id":"fr-u609","tipo":"frase","requer":"fr-p466","fr":"Ce restaurant exploite ses serveurs.","en":"This restaurant exploits its waiters.","aceitasEn":["this restaurant exploits its waiters","that restaurant exploits its waiters","this restaurant exploits its servers","that restaurant exploits its servers","this restaurant exploits the waiters"],"distratoresEn":["This restaurant pays its waiters.","This restaurant trains its waiters.","This restaurant hires its waiters.","This restaurant fires its waiters."],"nivel":"B2","tags":["trabalho","economia"],"notaEn":"To exploit someone is «exploiter»; to explore a place is «explorer». «Ses serveurs», its waiters: «ses» serves for his, her and its.","requerTodas":["fr-p098","fr-p466","fr-p367"],"v":"9c30e00d"},{"idioma":"fr","id":"fr-u610","tipo":"frase","requer":"fr-p466","fr":"Mes parents exploitent un petit hôtel.","en":"My parents run a small hotel.","aceitasEn":["my parents run a small hotel","my parents run a little hotel","my parents manage a small hotel","my parents operate a small hotel"],"distratoresEn":["My parents want a small hotel.","My parents rent a small hotel.","My parents book a small hotel.","My parents visit a small hotel."],"nivel":"B2","tags":["trabalho","viagem"],"notaEn":"With a business, «exploiter» simply means to run it: a hotel, a restaurant, a farm. The operator is «l'exploitant». Nothing negative here.","requerTodas":["fr-p247","fr-p466","fr-p038","fr-p227"],"v":"9d66ee78"},{"idioma":"fr","id":"fr-u611","tipo":"frase","requer":"fr-p467","fr":"Nous avons eu recours à un avocat.","aceitasFr":["On a eu recours à un avocat."],"en":"We turned to a lawyer.","aceitasEn":["we turned to a lawyer","we resorted to a lawyer","we went to a lawyer","we had recourse to a lawyer","we called on a lawyer","we have turned to a lawyer"],"distratoresEn":["We replied to a lawyer.","We listened to a lawyer.","We lied to a lawyer.","We wrote to a lawyer."],"nivel":"B2","tags":["jurídico"],"notaEn":"To turn to someone is «avoir recours à», with no article before «recours». «L'avocat» is the lawyer, and also the avocado.","requerTodas":["fr-p002","fr-p467","fr-p368"],"v":"088e971f"},{"idioma":"fr","id":"fr-u612","tipo":"frase","requer":"fr-p467","fr":"C'est notre dernier recours.","en":"It's our last resort.","aceitasEn":["its our last resort","it is our last resort","this is our last resort","thats our last resort","its our last option"],"distratoresEn":["It's our last day.","It's our last request.","It's our last game.","It's our last wish."],"nivel":"B2","tags":["cotidiano"],"notaEn":"«Le dernier recours», the last resort; «en dernier recours», as a last resort. Resources, as in natural resources, are «les ressources».","requerTodas":["fr-p001","fr-p510","fr-p467"],"v":"76e69790"},{"idioma":"fr","id":"fr-u613","tipo":"frase","requer":"fr-p468","fr":"Il pleut ; toutefois, nous sortons.","en":"It's raining; however, we're going out.","aceitasEn":["its raining however were going out","its raining however we are going out","its raining however were still going out","its raining nevertheless were going out","its raining nonetheless were going out","its raining even so were going out","its raining but were still going out","its raining still were going out"],"distratoresEn":["It's raining; therefore, we're going out.","It's raining; so, we're going out.","It's raining; besides, we're going out.","It's raining; moreover, we're going out."],"nivel":"B2","tags":["formal","escola"],"notaEn":"«Toutefois» is more formal than «mais» or «pourtant», and mostly written. It comes from «toutes fois», but it doesn't mean every time.","requerTodas":["fr-p171","fr-p468","fr-p108"],"v":"be55c679"},{"idioma":"fr","id":"fr-u614","tipo":"frase","requer":"fr-p469","fr":"Ça affecte la vie de tout le monde.","en":"This affects everyone's life.","aceitasEn":["this affects everyones life","that affects everyones life","it affects everyones life","this affects everybodys life","this affects everyones lives","this affects the lives of everyone"],"distratoresEn":["This improves everyone's life.","This simplifies everyone's life.","This changes everyone's life.","This saves everyone's life."],"nivel":"B2","tags":["social"],"notaEn":"«Affecter», to affect, usually for the worse: «la crise affecte l'économie». «Tout le monde» is everyone; the whole world is «le monde entier».","requerTodas":["fr-p469","fr-p250","fr-p070","fr-p154"],"v":"f5081dbf"},{"idioma":"fr","id":"fr-u615","tipo":"frase","requer":"fr-p469","fr":"Ce film m'a beaucoup affecté.","aceitasFr":["Ce film m'a beaucoup affectée."],"en":"That movie really affected me.","aceitasEn":["that movie really affected me","that film really affected me","this movie really affected me","that movie affected me a lot","that movie affected me deeply","that movie really moved me","that movie really touched me","that movie really got to me"],"distratoresEn":["That movie really annoyed me.","That movie really bored me.","That movie really scared me.","That movie really amused me."],"nivel":"B2","tags":["cultura","social"],"notaEn":"With people, «affecter» means to affect deeply, to shake: «sa mort l'a beaucoup affecté». A woman writes «affectée», since «me» comes before the verb.","requerTodas":["fr-p100","fr-p002","fr-p067","fr-p469"],"v":"ac5ad836"},{"idioma":"fr","id":"fr-u616","tipo":"frase","requer":"fr-p470","fr":"Tu as une suggestion ?","aceitasFr":["Vous avez une suggestion ?","As-tu une suggestion ?","Avez-vous une suggestion ?","Tu as des suggestions ?"],"en":"Do you have any suggestions?","aceitasEn":["do you have any suggestions","do you have a suggestion","do you have any suggestion","have you got any suggestions","have you got a suggestion","any suggestions"],"distratoresEn":["Do you have any questions?","Do you have any doubts?","Do you have any complaints?","Do you have any news?"],"nivel":"B2","tags":["trabalho","social"],"notaEn":"Same word as in English, but feminine: «une suggestion». To make a suggestion is «faire une suggestion»; to suggest, «suggérer».","requerTodas":["fr-p002","fr-p470"],"v":"3c76b866"},{"idioma":"fr","id":"fr-u617","tipo":"frase","requer":"fr-p471","fr":"Le chef ne tolère aucun retard.","en":"The boss doesn't tolerate any lateness.","aceitasEn":["the boss doesnt tolerate any lateness","the boss doesnt tolerate lateness","the boss doesnt tolerate any delays","the boss wont tolerate any lateness","the boss tolerates no lateness","the boss doesnt accept any lateness","the boss wont put up with any lateness","the boss doesnt put up with lateness"],"distratoresEn":["The boss doesn't record any lateness.","The boss doesn't notice any lateness.","The boss doesn't explain any lateness.","The boss doesn't report any lateness."],"nivel":"B2","tags":["trabalho"],"notaEn":"«Aucun» is already negative and goes with «ne», without «pas»: «ne… aucun», not any. The accent shifts: «tolérer», but «il tolère».","requerTodas":["fr-p263","fr-p471","fr-p085"],"v":"6c33c553"},{"idioma":"fr","id":"fr-u618","tipo":"frase","requer":"fr-p472","fr":"Il a menti pour une raison quelconque.","en":"He lied for some reason.","aceitasEn":["he lied for some reason","he lied for some reason or other","he lied for some reason or another","he lied for one reason or another","he lied for whatever reason"],"distratoresEn":["He lied for a silly reason.","He lied for a serious reason.","He lied for a simple reason.","He lied for a strange reason."],"nivel":"B2","tags":["social"],"notaEn":"After the noun, «quelconque» means some ... or other: «une raison quelconque». With «très» it turns negative: «un film très quelconque», a very mediocre film.","requerTodas":["fr-p002","fr-p402","fr-p141","fr-p472"],"v":"4a965d39"},{"idioma":"fr","id":"fr-u619","tipo":"frase","requer":"fr-p472","fr":"C'est un restaurant très quelconque.","en":"It's a very mediocre restaurant.","aceitasEn":["its a very mediocre restaurant","its a really mediocre restaurant","its a pretty mediocre restaurant","its a very ordinary restaurant","its a really ordinary restaurant","its a very average restaurant","its a really average restaurant","its a very unremarkable restaurant"],"distratoresEn":["It's a very expensive restaurant.","It's a very noisy restaurant.","It's a very famous restaurant.","It's a very small restaurant."],"nivel":"B2","tags":["comida","cotidiano"],"notaEn":"With «très», or after «être», «quelconque» is dismissive: run-of-the-mill, nothing special. «Ce restaurant est quelconque», it's nothing to write home about.","requerTodas":["fr-p001","fr-p098","fr-p043","fr-p472"],"v":"8dbaf17e"},{"idioma":"fr","id":"fr-u620","tipo":"frase","requer":"fr-p473","fr":"Il faut protéger le consommateur.","en":"We need to protect the consumer.","aceitasEn":["we need to protect the consumer","we need to protect consumers","we have to protect the consumer","we must protect the consumer","the consumer needs to be protected","the consumer must be protected","consumers need to be protected"],"distratoresEn":["We need to protect the seller.","We need to protect the producer.","We need to protect the driver.","We need to protect the pedestrian."],"nivel":"B2","tags":["economia","compras"],"notaEn":"Masculine; the feminine is «consommatrice». To consume is «consommer»; consumption, «la consommation».","requerTodas":["fr-p122","fr-p394","fr-p473"],"v":"f7c54792"},{"idioma":"fr","id":"fr-u621","tipo":"frase","requer":"fr-p473","fr":"Les toilettes sont réservées aux consommateurs.","en":"The restrooms are for customers only.","aceitasEn":["the restrooms are for customers only","the restrooms are only for customers","the restroom is for customers only","the toilets are for customers only","the toilets are only for customers","the bathroom is for customers only","the restrooms are reserved for customers","restrooms for customers only","toilets for customers only"],"distratoresEn":["The restrooms are for staff only.","The restrooms are for children only.","The restrooms are for women only.","The restrooms are for guests only."],"nivel":"B2","tags":["comida","cidade"],"notaEn":"In a café, «le consommateur» is whoever buys something: a customer. «Les toilettes», the restroom, is always plural.","requerTodas":["fr-p525","fr-p001","fr-p174","fr-p473"],"v":"88bf4774"},{"idioma":"fr","id":"fr-u622","tipo":"frase","requer":"fr-p474","fr":"On a navigué toute la nuit.","aceitasFr":["Nous avons navigué toute la nuit."],"en":"We sailed all night.","aceitasEn":["we sailed all night","we sailed all night long","we sailed the whole night","we were sailing all night","we sailed through the night"],"distratoresEn":["We danced all night.","We talked all night.","We drove all night.","We studied all night."],"nivel":"B2","tags":["viagem"],"notaEn":"«On a navigué», we sailed: in spoken French, «on» is the everyday we. «Naviguer» is also to browse online.","requerTodas":["fr-p002","fr-p474","fr-p070","fr-p030"],"v":"eee43252"},{"idioma":"fr","id":"fr-u623","tipo":"frase","requer":"fr-p474","fr":"Le soir, je navigue sur Internet.","en":"In the evening, I surf the internet.","aceitasEn":["in the evening i surf the internet","in the evening i browse the internet","in the evening i surf the web","in the evening i browse the web","in the evenings i surf the internet","i surf the internet in the evening","i browse the internet in the evening","at night i surf the internet"],"distratoresEn":["In the evening, I shop on the internet.","In the evening, I study on the internet.","In the evening, I play on the internet.","In the evening, I work on the internet."],"nivel":"B2","tags":["tecnologia","cotidiano"],"notaEn":"To surf the internet is «naviguer sur Internet», with «sur» and usually no article. «Le soir», with the article, means in the evenings, as a habit.","requerTodas":["fr-p160","fr-p474"],"v":"a27dff83"},{"idioma":"fr","id":"fr-u624","tipo":"frase","requer":"fr-p475","fr":"Il est très naïf.","en":"He's very naive.","aceitasEn":["hes very naive","he is very naive","hes really naive","he is really naive","hes so naive"],"distratoresEn":["He's very stubborn.","He's very shy.","He's very vain.","He's very jealous."],"nivel":"B2","tags":["social"],"notaEn":"English borrowed this word: «naïf» has the same diaeresis. The feminine is «naïve».","requerTodas":["fr-p001","fr-p043","fr-p475"],"v":"ee583adb"},{"idioma":"fr","id":"fr-u625","tipo":"frase","requer":"fr-p475","fr":"C'est une question naïve.","en":"That's a naive question.","aceitasEn":["thats a naive question","that is a naive question","its a naive question","it is a naive question"],"distratoresEn":["That's a strange question.","That's a curious question.","That's a delicate question.","That's an indiscreet question."],"nivel":"B2","tags":["social"],"notaEn":"In the feminine, «naïf» becomes «naïve», just as «neuf» becomes «neuve». It follows the noun: «une question naïve».","requerTodas":["fr-p001","fr-p140","fr-p475"],"v":"f485d0be"},{"idioma":"fr","id":"fr-u626","tipo":"frase","requer":"fr-p476","fr":"Mon père ne veut pas se remarier.","aceitasFr":["Mon père veut pas se remarier."],"en":"My father doesn't want to remarry.","aceitasEn":["my father doesnt want to remarry","my dad doesnt want to remarry","my father does not want to remarry","my father doesnt want to get married again","my dad doesnt want to get married again","my father doesnt want to marry again","my dad doesnt want to marry again"],"distratoresEn":["My father doesn't want to retire.","My father doesn't want to move.","My father doesn't want to travel.","My father doesn't want to divorce."],"nivel":"C1","tags":["família"],"notaEn":"Just like English, «re-» means again: «se remarier», to remarry. In French the verb is reflexive: «il se remarie».","requerTodas":["fr-p103","fr-p007","fr-p476"],"v":"f70dc610"},{"idioma":"fr","id":"fr-u627","tipo":"frase","requer":"fr-p476","fr":"Ma mère s'est remariée.","en":"My mother remarried.","aceitasEn":["my mother remarried","my mom remarried","my mum remarried","my mother has remarried","my mother got married again","my mom got married again","my mother married again"],"distratoresEn":["My mother retired.","My mother moved.","My mother divorced.","My mother graduated."],"nivel":"C1","tags":["família"],"notaEn":"Reflexive verbs take «être» in the passé composé, and the participle agrees with the subject: «elle s'est remariée», «il s'est remarié».","requerTodas":["fr-p063","fr-p001","fr-p476"],"v":"ea5c95a1"},{"idioma":"fr","id":"fr-u628","tipo":"frase","requer":"fr-p477","fr":"Le tirage, c'est ce soir !","aceitasFr":["Le tirage est ce soir !","Le tirage a lieu ce soir !","C'est ce soir, le tirage !"],"en":"The draw is tonight!","aceitasEn":["the draw is tonight","the draw is this evening","the drawing is tonight","the draw will be tonight","the lottery draw is tonight"],"distratoresEn":["The auction is tonight!","The game is tonight!","The parade is tonight!","The rehearsal is tonight!"],"nivel":"C1","tags":["cotidiano","mídia"],"notaEn":"«Le tirage» comes from «tirer», to pull: it is the draw, in full «le tirage au sort». It is also a newspaper's or a book's print run.","requerTodas":["fr-p477","fr-p001","fr-p160"],"v":"9b752716"},{"idioma":"fr","id":"fr-u629","tipo":"frase","requer":"fr-p477","fr":"Le premier tirage s'est vendu en une semaine.","aceitasFr":["Le premier tirage a été vendu en une semaine.","Le premier tirage s'est épuisé en une semaine."],"en":"The first print run sold out in a week.","aceitasEn":["the first print run sold out in a week","the first print run sold out in one week","the first printing sold out in a week","the first printing sold out in one week","the first run sold out in a week"],"distratoresEn":["The first shipment sold out in a week.","The first collection sold out in a week.","The first season sold out in a week.","The first harvest sold out in a week."],"nivel":"C1","tags":["mídia"],"notaEn":"«Le tirage» is a print run; a paper «à grand tirage» has a large circulation. «Se vendre», to sell, takes «être»: «s'est vendu».","requerTodas":["fr-p211","fr-p477","fr-p001","fr-p182","fr-p190"],"v":"f3a4f029"},{"idioma":"fr","id":"fr-u630","tipo":"frase","requer":"fr-p478","fr":"Leurs fiançailles ont duré deux ans.","en":"Their engagement lasted two years.","aceitasEn":["their engagement lasted two years","their engagement lasted for two years","their engagement has lasted two years","they were engaged for two years","they were engaged two years"],"distratoresEn":["Their marriage lasted two years.","Their contract lasted two years.","Their trip lasted two years.","Their friendship lasted two years."],"nivel":"B2","tags":["família"],"notaEn":"«Les fiançailles» is always plural (and feminine): «leurs fiançailles», with a plural verb. To get engaged is «se fiancer»; the fiancé is «le fiancé».","requerTodas":["fr-p478","fr-p002","fr-p522","fr-p120","fr-p052"],"v":"ad544653"},{"idioma":"fr","id":"fr-u631","tipo":"frase","requer":"fr-p478","fr":"Elle m'a montré sa bague de fiançailles.","en":"She showed me her engagement ring.","aceitasEn":["she showed me her engagement ring","shes shown me her engagement ring","she has shown me her engagement ring","she showed her engagement ring to me"],"distratoresEn":["She showed me her wedding ring.","She showed me her gold ring.","She showed me her silver ring.","She showed me her ruby ring."],"nivel":"B2","tags":["família"],"notaEn":"«La bague de fiançailles» is the engagement ring; the wedding band is «l'alliance». «Sa bague» means her ring or his ring: the possessive agrees with the thing owned, not the owner.","requerTodas":["fr-p002","fr-p329","fr-p532","fr-p478"],"v":"68ffdfce"},{"idioma":"fr","id":"fr-u632","tipo":"frase","requer":"fr-p479","fr":"Il veut faire du journalisme.","en":"He wants to go into journalism.","aceitasEn":["he wants to go into journalism","he wants to get into journalism","he wants to work in journalism","he wants to do journalism","he wants to be a journalist","he wants to become a journalist"],"distratoresEn":["He wants to go into theater.","He wants to go into film.","He wants to go into law.","He wants to go into tourism."],"nivel":"B2","tags":["mídia","trabalho"],"notaEn":"«Faire du journalisme» is to work as a journalist, with the partitive «du», like «faire du théâtre». To study it is «faire des études de journalisme».","requerTodas":["fr-p007","fr-p004","fr-p479"],"v":"535432a2"},{"idioma":"fr","id":"fr-u633","tipo":"frase","requer":"fr-p480","fr":"J'aime beaucoup la cuisine égyptienne.","en":"I really like Egyptian food.","aceitasEn":["i really like egyptian food","i really like egyptian cuisine","i like egyptian food a lot","i like egyptian cuisine a lot","i like egyptian food very much","i love egyptian food"],"distratoresEn":["I really like Lebanese food.","I really like Moroccan food.","I really like Turkish food.","I really like Greek food."],"nivel":"B1","tags":["cultura","comida"],"notaEn":"In the feminine, «-ien» doubles the n: «égyptien», «égyptienne», like «brésilien», «brésilienne». «La cuisine» is both the kitchen and the cuisine.","requerTodas":["fr-p015","fr-p067","fr-p088","fr-p480"],"v":"1bcbcfc9"},{"idioma":"fr","id":"fr-u634","tipo":"frase","requer":"fr-p480","fr":"Mon voisin est égyptien.","en":"My neighbor is Egyptian.","aceitasEn":["my neighbor is egyptian","my neighbour is egyptian","my neighbor is from egypt","my neighbour is from egypt"],"distratoresEn":["My neighbor is Lebanese.","My neighbor is Moroccan.","My neighbor is Turkish.","My neighbor is Greek."],"nivel":"B1","tags":["cultura","social"],"notaEn":"Unlike English, the nationality adjective is lowercase: «il est égyptien». Only the noun is capitalized: «un Égyptien». The country is «l'Égypte».","requerTodas":["fr-p072","fr-p001","fr-p480"],"v":"408a3e0c"},{"idioma":"fr","id":"fr-u635","tipo":"frase","requer":"fr-p481","fr":"Tu es trop susceptible.","aceitasFr":["Vous êtes trop susceptible."],"en":"You're too touchy.","aceitasEn":["youre too touchy","you are too touchy","youre way too touchy","youre too sensitive","you are too sensitive","youre oversensitive","you get offended too easily"],"distratoresEn":["You're too demanding.","You're too impatient.","You're too arrogant.","You're too selfish."],"nivel":"B2","tags":["social"],"notaEn":"French «susceptible» usually means touchy, quick to take offense. With «de», it means liable to: «susceptible de changer», subject to change.","requerTodas":["fr-p001","fr-p061","fr-p481"],"v":"8e459f61"},{"idioma":"fr","id":"fr-u636","tipo":"frase","requer":"fr-p482","fr":"La participation a été très forte.","aceitasFr":["La participation a été très élevée."],"en":"Turnout was very high.","aceitasEn":["turnout was very high","the turnout was very high","turnout was really high","the turnout was really high","turnout has been very high","the turnout has been very high","participation was very high"],"distratoresEn":["Abstention was very high.","Inflation was very high.","Demand was very high.","Unemployment was very high."],"nivel":"B2","tags":["política","social"],"notaEn":"In an election, «la participation» is the turnout; its opposite is «l'abstention». It is «forte» or «faible», high or low.","requerTodas":["fr-p482","fr-p002","fr-p001","fr-p043","fr-p294"],"v":"53367fc6"},{"idioma":"fr","id":"fr-u637","tipo":"frase","requer":"fr-p482","fr":"La participation est gratuite.","en":"Participation is free.","aceitasEn":["participation is free","participation is free of charge","taking part is free","its free to take part","it is free to take part","its free to participate"],"distratoresEn":["Registration is free.","Entry is free.","Delivery is free.","Parking is free."],"nivel":"B2","tags":["social","cotidiano"],"notaEn":"You take part «à» something: «la participation à un concours», «participer à la réunion». «Une participation aux frais» is a contribution to costs.","requerTodas":["fr-p482","fr-p001","fr-p526"],"v":"28eb47d0"},{"idioma":"fr","id":"fr-u638","tipo":"frase","requer":"fr-p483","fr":"Les arbres commencent à fleurir.","en":"The trees are starting to bloom.","aceitasEn":["the trees are starting to bloom","the trees are beginning to bloom","the trees are starting to blossom","the trees are beginning to blossom","the trees are starting to flower","the trees start to bloom"],"distratoresEn":["The trees are starting to dry out.","The trees are starting to grow.","The trees are starting to wilt.","The trees are starting to turn yellow."],"nivel":"B2","tags":["natureza"],"notaEn":"«Fleurir» is conjugated like «finir»: «ils fleurissent». It comes from «la fleur», the flower. «Commencer à» takes «à» before the infinitive.","requerTodas":["fr-p520","fr-p196","fr-p483"],"v":"1eecec2b"},{"idioma":"fr","id":"fr-u639","tipo":"frase","requer":"fr-p484","fr":"J'ai acheté un nouvel agenda.","aceitasFr":["Je me suis acheté un nouvel agenda."],"en":"I bought a new planner.","aceitasEn":["i bought a new planner","ive bought a new planner","i got a new planner","i bought a new diary","i bought a new datebook","i bought myself a new planner"],"distratoresEn":["I bought a new backpack.","I bought a new wallet.","I bought a new pen.","I bought a new bag."],"nivel":"B1","tags":["trabalho","compras"],"notaEn":"«Un agenda» is a planner or datebook, and it is masculine. A meeting agenda is «l'ordre du jour». Before a vowel, «nouveau» becomes «nouvel».","requerTodas":["fr-p002","fr-p075","fr-p039","fr-p484"],"v":"7181354e"},{"idioma":"fr","id":"fr-u640","tipo":"frase","requer":"fr-p485","fr":"Platon était le disciple de Socrate.","aceitasFr":["Platon était un disciple de Socrate.","Platon a été le disciple de Socrate."],"en":"Plato was a disciple of Socrates.","aceitasEn":["plato was a disciple of socrates","plato was the disciple of socrates","plato was socrates disciple","plato was socratess disciple","plato was a student of socrates","plato was socrates student","plato was a pupil of socrates"],"distratoresEn":["Plato was a rival of Socrates.","Plato was a teacher of Socrates.","Plato was a neighbor of Socrates.","Plato was a son of Socrates."],"nivel":"C1","tags":["cultura","filosofia"],"notaEn":"«Le disciple» works for both genders: «une disciple». Its counterpart is «le maître», the master. «Était» is the imperfect of «être».","requerTodas":["fr-p001","fr-p485"],"v":"c046f01b"},{"idioma":"fr","id":"fr-u641","tipo":"frase","requer":"fr-p486","fr":"Il est resté humble.","en":"He stayed humble.","aceitasEn":["he stayed humble","he remained humble","hes stayed humble","he has stayed humble","hes remained humble","he has remained humble"],"distratoresEn":["He stayed shy.","He stayed friendly.","He stayed generous.","He stayed single."],"nivel":"B2","tags":["social"],"notaEn":"«Rester», to stay or remain, takes «être» in the passé composé: «il est resté». «Humble» is the same in both genders. «À mon humble avis», in my humble opinion.","requerTodas":["fr-p001","fr-p269","fr-p486"],"v":"3653a572"},{"idioma":"fr","id":"fr-u642","tipo":"frase","requer":"fr-p486","fr":"Elle vient d'une famille humble.","aceitasFr":["Elle est issue d'une famille humble."],"en":"She comes from a humble family.","aceitasEn":["she comes from a humble family","she comes from a humble background","shes from a humble family","she is from a humble family","she has humble origins"],"distratoresEn":["She comes from a large family.","She comes from a rich family.","She comes from a religious family.","She comes from a traditional family."],"nivel":"B2","tags":["social","família"],"notaEn":"As in English, «humble» also describes modest origins: «une famille humble», «des origines humbles». «Venir de», to come from.","requerTodas":["fr-p009","fr-p105","fr-p486"],"v":"422b53e5"},{"idioma":"fr","id":"fr-u643","tipo":"frase","requer":"fr-p487","fr":"Il a sollicité mon aide.","en":"He requested my help.","aceitasEn":["he requested my help","he has requested my help","he asked for my help","hes asked for my help","he has asked for my help","he sought my help","he asked me for help"],"distratoresEn":["He refused my help.","He accepted my help.","He appreciated my help.","He praised my help."],"nivel":"C1","tags":["trabalho","formal"],"notaEn":"«Solliciter» (double l) is to formally request: «solliciter un rendez-vous», «solliciter un emploi». Unlike English «solicit», it has no shady sense. Someone «très sollicité» is in high demand.","requerTodas":["fr-p002","fr-p487","fr-p213"],"v":"1c8757b2"},{"idioma":"fr","id":"fr-u644","tipo":"frase","requer":"fr-p488","fr":"On a vu la destruction de la ville.","aceitasFr":["Nous avons vu la destruction de la ville."],"en":"We saw the destruction of the city.","aceitasEn":["we saw the destruction of the city","we saw the citys destruction","weve seen the destruction of the city","we have seen the destruction of the city","we saw the destruction of the town","we witnessed the destruction of the city"],"distratoresEn":["We saw the rebuilding of the city.","We saw the flooding of the city.","We saw the evacuation of the city.","We saw the occupation of the city."],"nivel":"B2","tags":["cidade"],"notaEn":"French nouns in «-tion» are feminine: «la destruction». The verb is «détruire», with an «é»: «détruit», destroyed.","requerTodas":["fr-p002","fr-p010","fr-p488","fr-p028"],"v":"a1704ced"},{"idioma":"fr","id":"fr-u645","tipo":"frase","requer":"fr-p489","fr":"Il y a de l'eau dans le conduit.","en":"There's water in the duct.","aceitasEn":["theres water in the duct","there is water in the duct","theres water inside the duct","there is water inside the duct"],"distratoresEn":["There's water in the basement.","There's water in the engine.","There's water in the tank.","There's water in the sink."],"nivel":"C1","tags":["casa"],"notaEn":"«Le conduit» is a duct or flue: «le conduit de cheminée», «le conduit d'aération». Don't confuse it with «la conduite», driving or behavior.","requerTodas":["fr-p002","fr-p026","fr-p489"],"v":"02c070c0"},{"idioma":"fr","id":"fr-u646","tipo":"frase","requer":"fr-p490","fr":"L'automobile a changé nos villes.","en":"The automobile changed our cities.","aceitasEn":["the automobile changed our cities","the automobile has changed our cities","the car changed our cities","the car has changed our cities","cars changed our cities","cars have changed our cities"],"distratoresEn":["The subway changed our cities.","The train changed our cities.","The airplane changed our cities.","The phone changed our cities."],"nivel":"B2","tags":["cidade"],"notaEn":"«L'automobile» is feminine: «une automobile». It is the formal or historical word; the everyday car is «la voiture».","requerTodas":["fr-p490","fr-p002","fr-p511","fr-p028"],"v":"b08dd3b2"},{"idioma":"fr","id":"fr-u647","tipo":"frase","requer":"fr-p490","fr":"Il travaille dans l'automobile.","en":"He works in the car industry.","aceitasEn":["he works in the car industry","he works in the auto industry","he works in the automotive industry","he works in the automobile industry","he works in the motor industry"],"distratoresEn":["He works in the textile industry.","He works in the pharmaceutical industry.","He works in the shipbuilding industry.","He works in the chemical industry."],"nivel":"B2","tags":["trabalho","economia"],"notaEn":"On its own, with the article, «l'automobile» is the whole industry: «travailler dans l'automobile». It is also an adjective: «l'industrie automobile».","requerTodas":["fr-p017","fr-p490"],"v":"36f48e62"},{"idioma":"fr","id":"fr-u648","tipo":"frase","requer":"fr-p491","fr":"Il a infiltré le groupe pendant deux ans.","en":"He infiltrated the group for two years.","aceitasEn":["he infiltrated the group for two years","he was undercover in the group for two years"],"distratoresEn":["He led the group for two years.","He funded the group for two years.","He watched the group for two years.","He trained the group for two years."],"nivel":"C1","tags":["política"],"notaEn":"As in English, «infiltrer un groupe» takes a direct object. You can also say «s'infiltrer dans un groupe». Duration is «pendant»: «pendant deux ans».","requerTodas":["fr-p002","fr-p491","fr-p516","fr-p120","fr-p052"],"v":"e4eb3488"},{"idioma":"fr","id":"fr-u649","tipo":"frase","requer":"fr-p491","fr":"L'eau s'est infiltrée dans le mur.","en":"Water seeped into the wall.","aceitasEn":["water seeped into the wall","the water seeped into the wall","water has seeped into the wall","water got into the wall","the water got into the wall","water leaked into the wall","water soaked into the wall"],"distratoresEn":["Water spread across the wall.","Water collected in the wall.","Water condensed on the wall.","Water froze in the wall."],"nivel":"C1","tags":["casa"],"notaEn":"For water, the verb is reflexive and takes «être» in the passé composé, agreeing with «l'eau»: «s'est infiltrée». A leak is «une infiltration». «Le mur», the wall.","requerTodas":["fr-p001","fr-p026","fr-p491","fr-p519"],"v":"b3982f43"},{"idioma":"fr","id":"fr-u650","tipo":"frase","requer":"fr-p492","fr":"Ces deux rues sont parallèles.","en":"These two streets are parallel.","aceitasEn":["these two streets are parallel","those two streets are parallel","the two streets are parallel"],"distratoresEn":["These two streets are perpendicular.","These two streets are narrow.","These two streets are long.","These two streets are busy."],"nivel":"B2","tags":["cidade","escola"],"notaEn":"Spelling: «parallèle», with a grave accent on the second-to-last «e». It is the same in masculine and feminine; plural «parallèles». «Parallèle à», parallel to.","requerTodas":["fr-p120","fr-p032","fr-p001","fr-p492"],"v":"f066dc0b"},{"idioma":"fr","id":"fr-u651","tipo":"frase","requer":"fr-p492","fr":"Je fais les deux en parallèle.","aceitasFr":["Je fais les deux choses en parallèle."],"en":"I do both in parallel.","aceitasEn":["i do both in parallel","i do both at the same time","i do both things at the same time","i do both things in parallel","i do them both at the same time","i do the two at the same time","i do both simultaneously"],"distratoresEn":["I do both at home.","I do both calmly.","I do both in the morning.","I do both for free."],"nivel":"B2","tags":["cotidiano","trabalho"],"notaEn":"«En parallèle» means at the same time, side by side. «Les deux» on its own means both.","requerTodas":["fr-p004","fr-p120","fr-p492"],"v":"ac19102d"},{"idioma":"fr","id":"fr-u652","tipo":"frase","requer":"fr-p493","fr":"Elle porte une robe en dentelle.","aceitasFr":["Elle porte une robe de dentelle."],"en":"She's wearing a lace dress.","aceitasEn":["shes wearing a lace dress","she is wearing a lace dress","she wears a lace dress","shes in a lace dress","shes got a lace dress on"],"distratoresEn":["She's wearing a silk dress.","She's wearing a wool dress.","She's wearing a linen dress.","She's wearing a velvet dress."],"nivel":"C1","tags":["roupa"],"notaEn":"The fabric takes «en» or «de»: «une robe en dentelle». «La robe» is a dress. Someone who «ne fait pas dans la dentelle» doesn't bother with subtlety.","requerTodas":["fr-p232","fr-p142","fr-p493"],"v":"55891051"},{"idioma":"fr","id":"fr-u653","tipo":"frase","requer":"fr-p494","fr":"On a un accord verbal.","aceitasFr":["Nous avons un accord verbal."],"en":"We have a verbal agreement.","aceitasEn":["we have a verbal agreement","weve got a verbal agreement","we have an oral agreement","weve got an oral agreement","we have a spoken agreement"],"distratoresEn":["We have a written agreement.","We have a trade agreement.","We have a secret agreement.","We have a temporary agreement."],"nivel":"B2","tags":["trabalho","jurídico"],"notaEn":"«Verbal» means spoken, not on paper; it is also the grammar sense: «une forme verbale». «L'accord», agreement, is the one in «d'accord».","requerTodas":["fr-p002","fr-p521","fr-p494"],"v":"e5ece06c"},{"idioma":"fr","id":"fr-u656","tipo":"frase","requer":"fr-p495","fr":"Elle l'a imploré de rester.","en":"She begged him to stay.","aceitasEn":["she begged him to stay","she implored him to stay","she pleaded with him to stay","she beseeched him to stay","she begged for him to stay"],"distratoresEn":["She forbade him to stay.","She ordered him to stay.","She allowed him to stay.","She advised him to stay."],"nivel":"C2","tags":["social"],"notaEn":"«Implorer quelqu'un de» + infinitive: the person is a direct object, and the action takes «de», as in «implore him to». In everyday speech, «supplier» is more common: «je t'en supplie», I'm begging you.","requerTodas":["fr-p002","fr-p495","fr-p269"],"v":"4730bcbc"},{"idioma":"fr","id":"fr-u657","tipo":"frase","requer":"fr-p495","fr":"Il a imploré l'aide de ses voisins.","en":"He begged for his neighbors' help.","aceitasEn":["he begged for his neighbors help","he begged for his neighbours help","he begged his neighbors for help","he begged his neighbours for help","he implored his neighbors for help","he pleaded for his neighbors help","he begged for help from his neighbors","he implored the help of his neighbors"],"distratoresEn":["He refused his neighbors' help.","He accepted his neighbors' help.","He turned down his neighbors' help.","He welcomed his neighbors' help."],"nivel":"C2","tags":["social"],"notaEn":"With a direct object, «implorer» names what is begged for, with no «for»: «implorer l'aide», «implorer le pardon», «implorer la pitié». It's a formal, mostly written word.","requerTodas":["fr-p002","fr-p495","fr-p213","fr-p072"],"v":"fa863469"},{"idioma":"fr","id":"fr-u658","tipo":"frase","requer":"fr-p496","fr":"Je vais chez le coiffeur demain.","aceitasFr":["Demain, je vais chez le coiffeur."],"en":"I'm going to the hairdresser tomorrow.","aceitasEn":["im going to the hairdresser tomorrow","im going to the hairdressers tomorrow","i am going to the hairdresser tomorrow","i am going to the hairdressers tomorrow","im going to the hair salon tomorrow","tomorrow im going to the hairdresser"],"distratoresEn":["I'm going to the dentist tomorrow.","I'm going to the doctor tomorrow.","I'm going to the mechanic tomorrow.","I'm going to the tailor tomorrow."],"nivel":"A2","tags":["profissões","cotidiano"],"notaEn":"You go «chez» the person, like the English «'s»: «aller chez le coiffeur», to the hairdresser's; «chez le médecin», to the doctor's. The salon itself is «le salon de coiffure».","requerTodas":["fr-p003","fr-p496","fr-p059"],"v":"e7791f6e"},{"idioma":"fr","id":"fr-u659","tipo":"frase","requer":"fr-p496","fr":"Mon frère est coiffeur.","en":"My brother is a hairdresser.","aceitasEn":["my brother is a hairdresser","my brother is a hairstylist","my brother is a hair stylist","my brother is a stylist"],"distratoresEn":["My brother is a cook.","My brother is a mail carrier.","My brother is a gardener.","My brother is a baker."],"nivel":"A2","tags":["profissões","família"],"notaEn":"After «être», a job takes no article, unlike English: «il est coiffeur», he is a hairdresser. With «c'est», the article returns: «c'est un coiffeur». Feminine: «coiffeuse».","requerTodas":["fr-p078","fr-p001","fr-p496"],"v":"c2c79ee1"},{"idioma":"fr","id":"fr-u660","tipo":"frase","requer":"fr-p497","fr":"Elle a vécu deux ans en France de façon clandestine.","en":"She lived in France illegally for two years.","aceitasEn":["she lived in france illegally for two years","she lived illegally in france for two years","she lived in france clandestinely for two years","she lived clandestinely in france for two years","she lived in france undocumented for two years","she lived undocumented in france for two years","she lived in france for two years illegally","for two years she lived in france illegally","she lived two years in france illegally"],"distratoresEn":["She lived in France legally for two years.","She lived in France quietly for two years.","She lived in France happily for two years.","She lived in France comfortably for two years."],"nivel":"B2","tags":["política","viagem"],"notaEn":"The adjective agrees with «façon», which is feminine: «de façon clandestine». «Un travailleur clandestin» is an undocumented worker; the official phrase today is «en situation irrégulière».","requerTodas":["fr-p002","fr-p293","fr-p120","fr-p052","fr-p387","fr-p497"],"v":"a50013cd"},{"idioma":"fr","id":"fr-u661","tipo":"frase","requer":"fr-p497","fr":"Il a voyagé en passager clandestin.","en":"He traveled as a stowaway.","aceitasEn":["he traveled as a stowaway","he travelled as a stowaway","he was a stowaway","he stowed away","he traveled clandestinely","he travelled clandestinely"],"distratoresEn":["He traveled as a tourist.","He traveled as a pilot.","He traveled as a guide.","He traveled as a sailor."],"nivel":"B2","tags":["viagem","política"],"notaEn":"«Un passager clandestin» is a stowaway, hidden aboard a ship, plane or train. Here «en» means «as»: «en passager clandestin», as a stowaway; «en touriste», as a tourist.","requerTodas":["fr-p002","fr-p183","fr-p530","fr-p497"],"v":"0308fa26"},{"idioma":"fr","id":"fr-u662","tipo":"frase","requer":"fr-p498","fr":"Il s'est aventuré loin de la ville.","en":"He ventured far from the city.","aceitasEn":["he ventured far from the city","he ventured far from town","he ventured a long way from the city","he ventured out far from the city"],"distratoresEn":["He got lost far from the city.","He hid far from the city.","He settled far from the city.","He took refuge far from the city."],"nivel":"C1","tags":["viagem","cidade"],"notaEn":"A reflexive verb, so the past tense takes «être» and the participle agrees: «il s'est aventuré», «elle s'est aventurée». For going into a place, use «dans»: «s'aventurer dans la forêt».","requerTodas":["fr-p001","fr-p498","fr-p164","fr-p028"],"v":"72399634"},{"idioma":"fr","id":"fr-u663","tipo":"frase","requer":"fr-p498","fr":"Je ne m'aventurerais pas à le dire.","aceitasFr":["Je ne m'aventurerais pas à dire ça.","Je ne m'aventurerais pas à dire cela."],"en":"I wouldn't venture to say so.","aceitasEn":["i wouldnt venture to say so","i would not venture to say so","i wouldnt venture to say that","i wouldnt venture to say","i wouldnt dare to say that","i wouldnt dare say that","i wouldnt dare say so","i wouldnt risk saying that","i wouldnt risk saying so"],"distratoresEn":["I wouldn't get tired of saying so.","I wouldn't forget to say so.","I wouldn't mind saying so.","I wouldn't refuse to say so."],"nivel":"C1","tags":["social"],"notaEn":"«S'aventurer à» + infinitive means to venture to do or say something. In the conditional, «je ne m'aventurerais pas», it's a polite way of declining to give an opinion.","requerTodas":["fr-p498","fr-p005"],"v":"1dafda2b"},{"idioma":"fr","id":"fr-u664","tipo":"frase","requer":"fr-p499","fr":"Je lis toujours la rubrique sport.","aceitasFr":["Je lis toujours la rubrique sports.","Je lis toujours la rubrique des sports.","Je lis toujours la rubrique sportive."],"en":"I always read the sports section.","aceitasEn":["i always read the sports section","i always read the sport section","i always read the sports page","i always read the sports pages","i always read the sports column"],"distratoresEn":["I always read the sports magazine.","I always read the sports headlines.","I always read the sports schedule.","I always read the sports encyclopedia."],"nivel":"B2","tags":["mídia","falso-amigo"],"notaEn":"«La rubrique» is a regular section of a newspaper, magazine, radio show or website: «la rubrique sport», «la rubrique culture». It's not a grading rubric, which is «une grille d'évaluation».","requerTodas":["fr-p076","fr-p046","fr-p499","fr-p161"],"v":"4886535f"},{"idioma":"fr","id":"fr-u665","tipo":"frase","requer":"fr-p500","fr":"Le professeur a fait l'éloge de son travail.","en":"The teacher praised his work.","aceitasEn":["the teacher praised his work","the teacher praised her work","the teacher praised their work","the professor praised his work","the professor praised her work","the teacher sang the praises of his work","the teacher spoke highly of his work"],"distratoresEn":["The teacher criticized his work.","The teacher ignored his work.","The teacher corrected his work.","The teacher rejected his work."],"nivel":"C2","tags":["escola","social"],"notaEn":"«Faire l'éloge de», to praise highly, often publicly; literally to make the praise of. «L'éloge» is masculine despite the «-e». A casual compliment on an outfit is «un compliment».","requerTodas":["fr-p366","fr-p002","fr-p004","fr-p500","fr-p029"],"v":"d433d74c"},{"idioma":"fr","id":"fr-u666","tipo":"frase","requer":"fr-p500","fr":"Ce film a reçu beaucoup d'éloges.","en":"This film received a lot of praise.","aceitasEn":["this film received a lot of praise","this movie received a lot of praise","this film got a lot of praise","this movie got a lot of praise","this film received lots of praise","this film received much praise","this film was highly praised","this movie was highly praised","the film received a lot of praise"],"distratoresEn":["This film received a lot of awards.","This film received a lot of attacks.","This film received a lot of comments.","This film received a lot of viewers."],"nivel":"C2","tags":["cultura","mídia"],"notaEn":"In the plural, «les éloges» is the praise someone or something receives: «recevoir des éloges», «couvrir d'éloges», to shower with praise. Unlike English «praise», it's countable.","requerTodas":["fr-p100","fr-p002","fr-p512","fr-p067","fr-p500"],"v":"f0617b77"},{"idioma":"fr","id":"fr-u667","tipo":"frase","requer":"fr-p501","fr":"Ce livre est une bonne initiation à la cuisine française.","en":"This book is a good introduction to French cooking.","aceitasEn":["this book is a good introduction to french cooking","this book is a good introduction to french cuisine","this book is a good initiation into french cooking","this book is a good initiation to french cooking","this book is a good primer on french cooking","this book is a nice introduction to french cooking"],"distratoresEn":["This book is a good tribute to French cooking.","This book is a good ode to French cooking.","This book is a good response to French cooking.","This book is a good challenge to French cooking."],"nivel":"B2","tags":["escola","comida"],"notaEn":"«L'initiation à» is a first introduction to a subject: «une initiation à la photo», «au yoga», «à l'informatique». It takes «à», where English says «to» or «into».","requerTodas":["fr-p033","fr-p001","fr-p036","fr-p501","fr-p088","fr-p054"],"v":"600738dc"},{"idioma":"fr","id":"fr-u668","tipo":"frase","requer":"fr-p501","fr":"Le samedi, il y a un cours d'initiation.","aceitasFr":["Il y a un cours d'initiation le samedi."],"en":"On Saturdays there's an introductory class.","aceitasEn":["on saturdays theres an introductory class","on saturdays there is an introductory class","theres an introductory class on saturdays","there is an introductory class on saturdays","on saturdays theres a beginners class","on saturdays there is a beginners class","theres a beginners class on saturdays","on saturdays theres an introductory course","on saturdays there is an introductory course","on saturdays theres an intro class"],"distratoresEn":["On Saturdays there's a review class.","On Saturdays there's a remedial class.","On Saturdays there's a dance class.","On Saturdays there's a painting class."],"nivel":"B2","tags":["escola"],"notaEn":"«Un cours d'initiation» is a class or course for complete beginners; no article after «de». «Le samedi», with the article, means every Saturday.","requerTodas":["fr-p159","fr-p002","fr-p148","fr-p501"],"v":"6af8b196"},{"idioma":"fr","id":"fr-u669","tipo":"frase","requer":"fr-p502","fr":"C'est un vétéran du cinéma français.","en":"He's a veteran of French cinema.","aceitasEn":["hes a veteran of french cinema","he is a veteran of french cinema","hes a french cinema veteran","he is a french cinema veteran","hes a veteran of french film","he is a veteran of french film"],"distratoresEn":["He's a critic of French cinema.","He's a fan of French cinema.","He's a star of French cinema.","He's a student of French cinema."],"nivel":"C2","tags":["cultura"],"notaEn":"Besides a former soldier, «le vétéran» is anyone long established in a field: «un vétéran du cinéma», «de la politique». After «c'est», the article is needed: «c'est un vétéran».","requerTodas":["fr-p001","fr-p502","fr-p097","fr-p054"],"v":"77cae3a5"},{"idioma":"fr","id":"fr-u670","tipo":"frase","requer":"fr-p502","fr":"Mon père est un vétéran de la guerre d'Algérie.","en":"My father is a veteran of the Algerian War.","aceitasEn":["my father is a veteran of the algerian war","my dad is a veteran of the algerian war","my father is an algerian war veteran","my dad is an algerian war veteran","my father is a veteran of the war in algeria"],"distratoresEn":["My father is a deserter of the Algerian War.","My father is a hero of the Algerian War.","My father is a prisoner of the Algerian War.","My father is a survivor of the Algerian War."],"nivel":"C2","tags":["família","política"],"notaEn":"«La guerre d'Algérie» lasted from 1954 to 1962. In official language, a war veteran is «un ancien combattant», the term used in documents and ceremonies.","requerTodas":["fr-p103","fr-p001","fr-p502","fr-p517"],"v":"ad57dc76"},{"idioma":"fr","id":"fr-u671","tipo":"frase","requer":"fr-p503","fr":"La fabrication de cette voiture a pris deux ans.","en":"It took two years to make this car.","aceitasEn":["it took two years to make this car","it took two years to build this car","it took two years to manufacture this car","making this car took two years","building this car took two years","manufacturing this car took two years","the manufacture of this car took two years","the manufacturing of this car took two years","the production of this car took two years"],"distratoresEn":["It took two years to sell this car.","It took two years to deliver this car.","It took two years to repair this car.","It took two years to paint this car."],"nivel":"B2","tags":["trabalho","economia"],"notaEn":"«La fabrication» means making things, not making things up: a made-up story is «une invention». The factory is «l'usine». Time taken uses «prendre»: «ça a pris deux ans».","requerTodas":["fr-p503","fr-p034","fr-p002","fr-p011","fr-p120","fr-p052"],"v":"21d3ea4d"},{"idioma":"fr","id":"fr-u672","tipo":"frase","requer":"fr-p504","fr":"Honnêtement, je ne sais pas.","aceitasFr":["Honnêtement, je sais pas.","Je ne sais pas, honnêtement."],"en":"Honestly, I don't know.","aceitasEn":["honestly i dont know","honestly i do not know","to be honest i dont know","to be honest i do not know","frankly i dont know","i honestly dont know","i dont know honestly","truthfully i dont know"],"distratoresEn":["Luckily, I don't know.","Unfortunately, I don't know.","Apparently, I don't know.","Obviously, I don't know."],"nivel":"B1","tags":["cotidiano"],"notaEn":"At the start of a sentence, «honnêtement» works just like «honestly». In casual speech the «ne» drops: «honnêtement, je sais pas». Note the double «n» and the «ê».","requerTodas":["fr-p504","fr-p008"],"v":"0f526c3d"},{"idioma":"fr","id":"fr-u673","tipo":"frase","requer":"fr-p504","fr":"Il a gagné son argent honnêtement.","en":"He earned his money honestly.","aceitasEn":["he earned his money honestly","he made his money honestly","he earned his money in an honest way","he made his money in an honest way","he earned his money fair and square"],"distratoresEn":["He earned his money easily.","He earned his money quickly.","He earned his money illegally.","He earned his money quietly."],"nivel":"B1","tags":["trabalho","economia"],"notaEn":"After the verb, «honnêtement» says how something was done: in an honest way. «Gagner de l'argent» is to earn money; «gagner» also means to win.","requerTodas":["fr-p002","fr-p210","fr-p035","fr-p504"],"v":"a8216e0f"},{"idioma":"fr","id":"fr-u674","tipo":"frase","requer":"fr-p505","fr":"Elle met cent euros par mois sur son livret.","en":"She puts a hundred euros a month into her savings account.","aceitasEn":["she puts a hundred euros a month into her savings account","she puts one hundred euros a month into her savings account","she puts a hundred euros a month in her savings account","she puts a hundred euros a month into her savings","she puts a hundred euros a month into savings","she puts a hundred euros a month in savings","she pays a hundred euros a month into her savings account","she deposits a hundred euros a month into her savings account"],"distratoresEn":["She puts a hundred euros a month into the stock market.","She puts a hundred euros a month into her wallet.","She puts a hundred euros a month into her pension.","She puts a hundred euros a month into her car."],"nivel":"B2","tags":["economia"],"notaEn":"Money goes «sur» a livret, not «dans»: «mettre de l'argent sur son livret». «Le livret A» is France's most popular tax-free savings account. «Par mois», a month.","requerTodas":["fr-p167","fr-p273","fr-p128","fr-p286","fr-p505"],"v":"0b07daa9"},{"idioma":"fr","id":"fr-u675","tipo":"frase","requer":"fr-p506","fr":"À l'aéroport, le détecteur a sonné.","en":"At the airport, the detector went off.","aceitasEn":["at the airport the detector went off","the detector went off at the airport","at the airport the detector beeped","the detector beeped at the airport","at the airport the metal detector went off","at the airport the metal detector beeped","at the airport the detector rang","at the airport the detector sounded"],"distratoresEn":["At the airport, the phone went off.","At the airport, the alarm clock went off.","At the airport, the timer went off.","At the airport, the fire alarm went off."],"nivel":"B2","tags":["viagem","tecnologia"],"notaEn":"«Sonner» is to ring or go off: phones, alarm clocks, doorbells and detectors. At the airport it's «le détecteur de métaux»; at home, «le détecteur de fumée».","requerTodas":["fr-p365","fr-p506","fr-p002","fr-p523"],"v":"51765a5d"},{"idioma":"fr","id":"fr-u676","tipo":"frase","requer":"fr-p507","fr":"Je mets de la mayonnaise dans mon sandwich.","aceitasFr":["Je mets de la mayonnaise sur mon sandwich.","Je mets de la mayo dans mon sandwich."],"en":"I put mayonnaise on my sandwich.","aceitasEn":["i put mayonnaise on my sandwich","i put mayo on my sandwich","i put mayonnaise in my sandwich","i put mayo in my sandwich","i put some mayonnaise on my sandwich","i put some mayo on my sandwich"],"distratoresEn":["I put mustard on my sandwich.","I put butter on my sandwich.","I put pepper on my sandwich.","I put onion on my sandwich."],"nivel":"A2","tags":["comida"],"notaEn":"With things you can't count, French needs the partitive: «de la mayonnaise», «du beurre», where English uses nothing or «some». Informally, «la mayo».","requerTodas":["fr-p167","fr-p507","fr-p302"],"v":"23209bab"},{"idioma":"fr","id":"fr-u677","tipo":"frase","requer":"fr-p508","fr":"Ce sport est très en vogue.","en":"This sport is very much in vogue.","aceitasEn":["this sport is very much in vogue","this sport is very in vogue","this sport is really in vogue","this sport is in vogue","this sport is very fashionable","this sport is very trendy","this sport is really trendy","this sport is all the rage","this sport is very much in fashion"],"distratoresEn":["This sport is very much in decline.","This sport is very much in crisis.","This sport is very much in doubt.","This sport is very much in danger."],"nivel":"C1","tags":["cultura"],"notaEn":"Mostly in «en vogue», just as in English. Don't mix it up with «la vague», a wave; everyday fashion is «la mode».","requerTodas":["fr-p161","fr-p001","fr-p043","fr-p508"],"v":"0d724e45"},{"idioma":"fr","id":"fr-u678","tipo":"frase","requer":"fr-p509","fr":"Elle était au faîte de sa gloire.","aceitasFr":["Elle était au faîte de la gloire."],"en":"She was at the height of her glory.","aceitasEn":["she was at the height of her glory","she was at the height of her fame","she was at the peak of her glory","she was at the peak of her fame","she was at the pinnacle of her glory","she was at the pinnacle of her fame","she was at the zenith of her glory","she was at the summit of her glory","she was at the height of glory"],"distratoresEn":["She was at the beginning of her glory.","She was at the end of her glory.","She was at the dawn of her glory.","She was at the twilight of her glory."],"nivel":"C2","tags":["cultura"],"notaEn":"«Au faîte de» is literary and almost always figurative: «au faîte de la gloire», «au faîte du pouvoir». It sounds just like «la fête», a party; spelling and gender tell them apart: «le faîte», «la fête».","requerTodas":["fr-p001","fr-p509","fr-p533"],"v":"97839c85"},{"idioma":"fr","id":"fr-p510","tipo":"palavra","fr":"dernier","aceitasFr":["dernière"],"en":"last","aceitasEn":["last","final","latest"],"distratoresEn":["first","next","only","following"],"nivel":"A1","tags":["adjetivo","cotidiano"],"notaEn":"Feminine «dernière». Before the noun, it is the last in a series: «le dernier jour», the last day. After the noun, with time words, it is the one just gone: «la semaine dernière», last week. «Son dernier film», his latest film.","v":"eccfc916","pos":93},{"idioma":"fr","id":"fr-p511","tipo":"palavra","fr":"changer","en":"to change","aceitasEn":["to change","to alter","alter","to transform","transform","to modify","modify"],"distratoresEn":["to keep","to stop","to wait","to choose"],"nivel":"A1","tags":["verbo","cotidiano"],"notaEn":"Regular «-er» verb, but the «g» takes an «e» before «o»: «nous changeons». With «de» and no article: «changer de train», to change trains; «changer d'avis», to change one's mind. Loose change is «la monnaie».","v":"151834d1","transp":"parecida","pos":155},{"idioma":"fr","id":"fr-p512","tipo":"palavra","fr":"recevoir","en":"to receive","aceitasEn":["to receive","receive","to get","get","to welcome","welcome"],"distratoresEn":["to send","to give back","to ask for","to lend"],"nivel":"A1","tags":["verbo","cotidiano"],"notaEn":"Irregular: «je reçois», «nous recevons», «ils reçoivent»; past participle «reçu». The «ç» appears before «o» and «u». It is also to have guests over: «recevoir des amis à dîner».","v":"a1f9678e","pos":260},{"idioma":"fr","id":"fr-p513","tipo":"palavra","fr":"garder","en":"to keep","aceitasEn":["to keep","keep","to hold on to","to look after","look after","to guard","guard","to save","save"],"distratoresEn":["to lose","to give back","to sell","to lend"],"nivel":"A1","tags":["verbo","cotidiano"],"notaEn":"To keep, not let go: «gardez la monnaie», keep the change; «garder un secret», to keep a secret. With children, to look after: «garder les enfants». To put away is «ranger».","v":"42a6b208","pos":270},{"idioma":"fr","id":"fr-p514","tipo":"palavra","fr":"le roi","en":"the king","aceitasEn":["king","the king","monarch","the monarch"],"distratoresEn":["the prince","the duke","the count","the emperor"],"nivel":"A1","tags":["política"],"notaEn":"The queen is «la reine». At Epiphany the French eat «la galette des rois», and whoever finds the charm is crowned. «Louis XIV» is read «Louis Quatorze», with a plain number.","v":"eb2c43b9","pos":309},{"idioma":"fr","id":"fr-p515","tipo":"palavra","fr":"la photo","aceitasFr":["la photographie"],"en":"the photo","aceitasEn":["photo","the photo","photograph","the photograph","pic"],"distratoresEn":["the camera","the screen","the letter","the film"],"nivel":"A1","tags":["cultura"],"notaEn":"Feminine, short for «la photographie». To take a photo is «prendre une photo»; to pose, «prendre la pose». The camera is «l'appareil photo».","v":"dbcd52be","transp":"total","pos":310},{"idioma":"fr","id":"fr-p516","tipo":"palavra","fr":"le groupe","en":"the group","aceitasEn":["group","the group","band","the band"],"distratoresEn":["the nation","the pair","the club","the party"],"nivel":"A1","tags":["social"],"notaEn":"Masculine, with a final «-e»: «un groupe d'amis», a group of friends. In music it is a band: «un groupe de rock». «Le groupe sanguin», the blood type.","v":"55ae98d0","transp":"parecida","pos":374},{"idioma":"fr","id":"fr-p517","tipo":"palavra","fr":"la guerre","en":"war","aceitasEn":["war","the war","warfare"],"distratoresEn":["peace","battle","revolt","crisis"],"nivel":"A1","tags":["política"],"notaEn":"Feminine. The «gu» is a hard g, from the same Germanic root as English war. «La Seconde Guerre mondiale», World War II; «l'après-guerre», the postwar years. A battle is «la bataille».","v":"aa3e0522","pos":396},{"idioma":"fr","id":"fr-p518","tipo":"palavra","fr":"excuser","en":"to excuse","aceitasEn":["to excuse","to forgive","forgive","to pardon","pardon","to justify"],"distratoresEn":["to accuse","to thank","to bother","to blame"],"nivel":"A1","tags":["verbo","social"],"notaEn":"«Excusez-moi», excuse me: the polite way to get someone's attention or ask to get by; with «tu», «excuse-moi». To apologize is reflexive: «je m'excuse». An excuse is «l'excuse».","v":"94d202e3","transp":"parecida","pos":478},{"idioma":"fr","id":"fr-p519","tipo":"palavra","fr":"le mur","en":"the wall","aceitasEn":["wall","the wall"],"distratoresEn":["the door","the window","the fence","the staircase"],"nivel":"A1","tags":["casa"],"notaEn":"Masculine, for walls inside and out: «le mur de la chambre», «le mur de Berlin». A great stone rampart is «la muraille». With an accent, «mûr» means ripe.","v":"ba0e69aa","pos":547},{"idioma":"fr","id":"fr-p520","tipo":"palavra","fr":"l'arbre","en":"the tree","aceitasEn":["tree","the tree"],"distratoresEn":["the bush","the trunk","the forest","the grass"],"nivel":"A1","tags":["natureza"],"notaEn":"Masculine, with the article elided: «l'arbre», «un arbre». «L'arbre de Noël», the Christmas tree; «l'arbre généalogique», the family tree.","v":"c182669e","pos":592},{"idioma":"fr","id":"fr-p521","tipo":"palavra","fr":"l'accord","en":"the agreement","aceitasEn":["agreement","the agreement","deal","the deal","accord","the accord","pact","the pact","chord","the chord"],"distratoresEn":["the conflict","the record","the message","the request"],"nivel":"A1","tags":["social"],"notaEn":"Masculine. It is the «accord» in «d'accord», OK, agreed. «Un accord verbal», a verbal agreement. In music it is a chord; in grammar, agreement: «l'accord de l'adjectif».","v":"8816dffc","pos":681},{"idioma":"fr","id":"fr-p522","tipo":"palavra","fr":"durer","en":"to last","aceitasEn":["to last","to go on","go on"],"distratoresEn":["to end","to begin","to wait","to delay"],"nivel":"A2","tags":["verbo","cotidiano"],"notaEn":"Regular «-er» verb: «le film dure deux heures», the film lasts two hours. The length of time is «la durée»; «durable» means lasting, or sustainable.","v":"a2f25f9f","pos":814},{"idioma":"fr","id":"fr-p523","tipo":"palavra","fr":"sonner","en":"to ring","aceitasEn":["to ring","to go off","go off","to sound","sound","to beep","beep","to buzz"],"distratoresEn":["to answer","to hang up","to charge","to mute"],"nivel":"A2","tags":["verbo","cotidiano"],"notaEn":"For anything that rings or beeps: the phone, the alarm clock, the doorbell, a detector that «a sonné», went off. «Sonner à la porte», to ring the doorbell. In Belgium it also means to phone someone.","v":"e16feea9","pos":887},{"idioma":"fr","id":"fr-p524","tipo":"palavra","fr":"la date","en":"the date","aceitasEn":["date","the date"],"distratoresEn":["the time","the age","the week","the calendar"],"nivel":"A2","tags":["cotidiano"],"notaEn":"Feminine: «la date de naissance», date of birth. Only the calendar date: a romantic date is «un rendez-vous». The fruit is «la datte», with two t's.","v":"97a2e3a4","transp":"total","pos":1100},{"idioma":"fr","id":"fr-p525","tipo":"palavra","fr":"les toilettes","aceitasFr":["les WC","les W.-C."],"en":"the restroom","aceitasEn":["restroom","the restroom","the restrooms","the toilet","toilet","the toilets","the loo","the washroom","the lavatory"],"distratoresEn":["the hallway","the basement","the backyard","the attic"],"nivel":"A2","tags":["casa"],"notaEn":"Feminine and always plural: «les toilettes sont où ?», where's the restroom? In France the toilet is often in its own room, apart from «la salle de bains». Singular «la toilette» is washing up: «faire sa toilette».","v":"1ad20bd2","pos":1131},{"idioma":"fr","id":"fr-p526","tipo":"palavra","fr":"gratuit","aceitasFr":["gratuite"],"en":"free of charge","aceitasEn":["free of charge","for free","at no cost","complimentary","gratuitous","free","for nothing"],"distratoresEn":["full price","half price","very expensive","paid in advance"],"nivel":"A2","tags":["adjetivo","compras"],"notaEn":"Feminine «gratuite», where the «t» is sounded: «l'entrée est gratuite», admission is free. The opposite is «payant». Free as in freedom is «libre». Like gratuitous, it can mean uncalled-for: «une violence gratuite».","v":"9484478b","pos":1224},{"idioma":"fr","id":"fr-p527","tipo":"palavra","fr":"le bouton","en":"the button","aceitasEn":["button","the button"],"distratoresEn":["the zipper","the pocket","the cable","the thread"],"nivel":"A2","tags":["objetos"],"notaEn":"On clothes and on machines: «appuyer sur le bouton», to press the button. Also a pimple, and a flower bud: «un bouton de rose», a rosebud.","v":"72cd9c59","pos":1288},{"idioma":"fr","id":"fr-p528","tipo":"palavra","fr":"la peinture","en":"the paint","aceitasEn":["paint","the paint"],"distratoresEn":["the clay","the chalk","the glue","the ink"],"nivel":"A2","tags":["cultura"],"notaEn":"Feminine. Both the paint and the art of painting: «peinture fraîche», wet paint; «faire de la peinture», to paint as a hobby. A painting on the wall is usually «un tableau».","v":"1e6844aa","pos":1316},{"idioma":"fr","id":"fr-p529","tipo":"palavra","fr":"cuire","aceitasFr":["faire cuire"],"en":"to bake / to boil","aceitasEn":["to bake","bake","to boil","boil","to roast","roast","to cook","cook"],"distratoresEn":["to cut / to peel","to season / to taste","to mix / to stir","to chop / to slice"],"nivel":"B1","tags":["verbo","comida"],"notaEn":"The heat does the work: «le gâteau cuit», the cake is baking; «faire cuire les pâtes», to put the pasta on. Irregular like «conduire»: «je cuis», «nous cuisons», «cuit». «Bien cuit», well done. To cook a meal, as a person, is «cuisiner».","v":"71d0d835","pos":1831},{"idioma":"fr","id":"fr-p530","tipo":"palavra","fr":"le passager","aceitasFr":["la passagère"],"en":"the passenger","aceitasEn":["passenger","the passenger"],"distratoresEn":["the pilot","the driver","the pedestrian","the conductor"],"nivel":"B1","tags":["viagem"],"notaEn":"Feminine «la passagère». Also an adjective, passing, temporary: «une crise passagère», a passing crisis. A stowaway is «un passager clandestin».","v":"e8622da4","transp":"parecida","pos":1832},{"idioma":"fr","id":"fr-p531","tipo":"palavra","fr":"l'excuse","en":"the excuse","aceitasEn":["excuse","the excuse","apology","the apology","pretext","the pretext"],"distratoresEn":["the lie","the blame","the complaint","the promise"],"nivel":"B1","tags":["social"],"notaEn":"Feminine: «une bonne excuse», a good excuse. In the plural it is an apology: «présenter ses excuses», to apologize. To say sorry is «s'excuser».","v":"d1028f3f","transp":"total","pos":1861},{"idioma":"fr","id":"fr-p532","tipo":"palavra","fr":"la bague","en":"the ring","aceitasEn":["ring","the ring"],"distratoresEn":["the necklace","the earring","the brooch","the bracelet"],"nivel":"B1","tags":["objetos"],"notaEn":"Feminine: a finger ring, as in «une bague de fiançailles», an engagement ring. A wedding band is «l'alliance»; any ring shape, «l'anneau». For a phone or a bell, to ring is «sonner».","v":"63f3a9f3","pos":1917},{"idioma":"fr","id":"fr-p533","tipo":"palavra","fr":"la gloire","en":"glory","aceitasEn":["glory","the glory","fame"],"distratoresEn":["victory","wealth","courage","luck"],"nivel":"B2","tags":["cultura"],"notaEn":"Feminine: «au faîte de la gloire», at the height of glory. «Le jour de gloire est arrivé» comes from the Marseillaise. «Travailler pour la gloire», to work for nothing.","v":"db07ff0a","pos":2869},{"idioma":"fr","id":"fr-p534","tipo":"palavra","fr":"pleurer","en":"to cry","aceitasEn":["to cry","cry","to weep","weep"],"distratoresEn":["to laugh","to shout","to sigh","to tremble"],"nivel":"A1","tags":["verbo","cotidiano"],"notaEn":"Regular «-er» verb: «je pleure», «il pleure». «Pleurer de rire», to laugh till you cry. To shout is «crier», not to cry. Raining is «pleuvoir»: «il pleure» and «il pleut» are close, and Verlaine plays on it.","v":"844ab270","pos":412},{"idioma":"fr","id":"fr-p535","tipo":"palavra","fr":"le cœur","aceitasFr":["le coeur"],"en":"the heart","aceitasEn":["heart","the heart"],"distratoresEn":["the lung","the liver","the stomach","the brain"],"nivel":"A1","tags":["corpo"],"notaEn":"«Par cœur», by heart: «apprendre par cœur», the same image as in English. «Avoir mal au cœur» means to feel sick, not heart pain. «De bon cœur», willingly.","v":"8d1ba93b","pos":257},{"idioma":"fr","id":"fr-p536","tipo":"palavra","fr":"pénétrer","en":"to penetrate","aceitasEn":["to penetrate","penetrate","to enter","enter","to get into","get into","to go into","go into"],"distratoresEn":["to leave","to retreat","to float","to break"],"nivel":"B2","tags":["verbo","cotidiano"],"notaEn":"More formal than «entrer»: «pénétrer dans une maison», to enter a house. Figuratively, to sink deep: the sadness «qui pénètre mon cœur», in Verlaine. The accent shifts: «je pénètre», «nous pénétrons».","v":"a88acc93","pos":2511},{"idioma":"fr","id":"fr-p537","tipo":"palavra","fr":"le bruit","en":"the noise","aceitasEn":["noise","the noise","the sound","sound","the rumor","rumor"],"distratoresEn":["the silence","the smell","the glow","the echo"],"nivel":"A1","tags":["cidade","cotidiano"],"notaEn":"«Faire du bruit», to make noise; «sans bruit», silently. It is also a rumor: «le bruit court que…», rumor has it that… The final «t» is silent.","v":"641df052","pos":506},{"idioma":"fr","id":"fr-p538","tipo":"palavra","fr":"doux","aceitasFr":["douce"],"en":"soft / sweet","aceitasEn":["soft","sweet","gentle","mild","tender","smooth"],"distratoresEn":["bitter / rough","strong / harsh","sour / hard","salty / rude"],"nivel":"A2","tags":["adjetivo","cotidiano"],"notaEn":"Feminine «douce». «Une voix douce», a soft voice; «il fait doux», it's mild; «l'eau douce», fresh water. Sweet as in sugary is usually «sucré».","v":"a501b525","pos":807},{"idioma":"fr","id":"fr-p539","tipo":"palavra","fr":"la pluie","en":"the rain","aceitasEn":["rain","the rain"],"distratoresEn":["the snow","the fog","the frost","the storm"],"nivel":"A2","tags":["natureza"],"notaEn":"From «pleuvoir», to rain: «il pleut». «Sous la pluie», in the rain (literally under it). «Une pluie de…», a shower of, figuratively.","v":"920b06c0","pos":1151},{"idioma":"fr","id":"fr-p540","tipo":"palavra","fr":"la terre","en":"the earth","aceitasEn":["earth","the earth","the ground","ground","soil","the soil","land","the land"],"distratoresEn":["the sand","the stone","the mud","the grass"],"nivel":"A1","tags":["natureza"],"notaEn":"«Par terre», on the ground or floor: «tomber par terre», to fall down. «La Terre», capitalized, is the planet. «La pomme de terre», the potato: the earth apple.","v":"864379a6","pos":196},{"idioma":"fr","id":"fr-p541","tipo":"palavra","fr":"le toit","en":"the roof","aceitasEn":["roof","the roof"],"distratoresEn":["the chimney","the wall","the floor","the balcony"],"nivel":"A2","tags":["casa"],"notaEn":"The outside covering: «sous le même toit», under the same roof. The ceiling inside a room is «le plafond».","v":"2dcf4709","pos":1104},{"idioma":"fr","id":"fr-p542","tipo":"palavra","fr":"ennuyer","en":"to bore / to bother","aceitasEn":["to bore","bore","to bother","bother","to annoy","annoy","to trouble","trouble"],"distratoresEn":["to amuse / to please","to scare / to hurt","to distract / to calm","to wait / to invite"],"nivel":"A2","tags":["verbo","cotidiano"],"notaEn":"Reflexive «s'ennuyer» is to be bored: «je m'ennuie», I'm bored; in Verlaine, «un cœur qui s'ennuie». Without «se», it is to bother: «ça t'ennuie si j'ouvre ?», do you mind if I open it? English «ennui» comes from the same root.","v":"f2d6ae3e","pos":985},{"idioma":"fr","id":"fr-p543","tipo":"palavra","fr":"le chant","en":"the singing","aceitasEn":["singing","the singing","the song","song","the chant","chant"],"distratoresEn":["the shouting","the crying","the whistling","the whispering"],"nivel":"B1","tags":["cultura"],"notaEn":"Singing, as an act and an art: «des cours de chant», singing lessons; «le chant des oiseaux», birdsong; «le chant de la pluie», in Verlaine. A song is usually «la chanson».","v":"1e2133dd","pos":1778},{"idioma":"fr","id":"fr-p544","tipo":"palavra","fr":"la trahison","en":"the betrayal","aceitasEn":["betrayal","the betrayal","treason","treachery"],"distratoresEn":["the revenge","the lie","the guilt","the escape"],"nivel":"C1","tags":["social"],"notaEn":"From «trahir», to betray. «Haute trahison», high treason. The middle «h» is silent: «tra-i-zon».","v":"82c19544","pos":4620},{"idioma":"fr","id":"fr-p545","tipo":"palavra","fr":"pire","en":"worse","aceitasEn":["worse","worst","the worst"],"distratoresEn":["better","smaller","bigger","equal"],"nivel":"A2","tags":["adjetivo","cotidiano"],"notaEn":"Comparative of «mauvais»: «c'est pire», it's worse; «le pire», the worst. With a verb, worse is «plus mal»: «il chante plus mal», he sings worse. The old «pis» survives in «tant pis», too bad.","v":"c16061e3","pos":1013},{"idioma":"fr","id":"fr-p546","tipo":"palavra","fr":"la peine","en":"the sorrow / the trouble","aceitasEn":["sorrow","trouble","grief","pain","sadness","effort","the effort","penalty","punishment","sentence"],"distratoresEn":["the joy / the luck","the anger / the hurry","the shame / the fear","the laziness / the delay"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Two sides: sorrow («la pire peine», the worst pain, in Verlaine) and effort («ce n'est pas la peine», there's no need; «ça vaut la peine», it's worth it). It is also a legal sentence: «la peine de mort», the death penalty. «À peine», hardly: «je le connais à peine».","v":"095994e1","pos":358},{"idioma":"fr","id":"fr-p547","tipo":"palavra","fr":"l'amour","en":"love","aceitasEn":["love","the love"],"distratoresEn":["hatred","jealousy","pride","respect"],"nivel":"A1","tags":["social"],"notaEn":"Masculine, «un amour». «Mon amour», my love; «une lettre d'amour», a love letter. To fall in love is «tomber amoureux».","v":"6720c12e","pos":207},{"idioma":"fr","id":"fr-p548","tipo":"palavra","fr":"la haine","en":"hatred","aceitasEn":["hatred","hate","the hatred"],"distratoresEn":["love","fear","pride","jealousy"],"nivel":"B1","tags":["social"],"notaEn":"Feminine, «la haine», with an aspirated «h»: no elision («la haine», never «l'haine»). The verb is «haïr», to hate, though «détester» is more common in speech.","v":"a2914416","pos":2171},{"idioma":"fr","id":"fr-p549","tipo":"palavra","fr":"tant","en":"so much","aceitasEn":["so much","so many","that much","such"],"distratoresEn":["too much","so little","enough","almost"],"nivel":"A1","tags":["cotidiano"],"notaEn":"With a noun, «tant de», no article: «tant de peine», so much sorrow (Verlaine). «Tant pis», too bad; «tant mieux», so much the better; «en tant que», as. Before an adjective, so is «si»: «si beau».","v":"cafbac7c","pos":287},{"idioma":"fr","id":"fr-p550","tipo":"palavra","fr":"l'aube","en":"dawn","aceitasEn":["dawn","the dawn","daybreak","first light","sunrise"],"distratoresEn":["dusk","nightfall","noon","sunset"],"nivel":"B2","tags":["natureza"],"notaEn":"Feminine. «Dès l'aube», at first light, as in the opening of Hugo's poem. From Latin «alba», white: the hour when the sky turns pale.","v":"7280b0c4","pos":2861},{"idioma":"fr","id":"fr-p551","tipo":"palavra","fr":"blanchir","en":"to whiten","aceitasEn":["to whiten","whiten","to turn white","turn white","to go white","go white","to bleach","bleach"],"distratoresEn":["to darken","to yellow","to redden","to rust"],"nivel":"C1","tags":["verbo","cotidiano"],"notaEn":"Conjugated like «finir»: «il blanchit», «nous blanchissons». To make or turn white: «ses cheveux ont blanchi», his hair has turned white; «la campagne blanchit», the fields grow pale at daybreak, in Hugo. In cooking, to blanch.","v":"91398b5a","pos":4319},{"idioma":"fr","id":"fr-p552","tipo":"palavra","fr":"la forêt","en":"the forest","aceitasEn":["forest","the forest","the woods","woods","the wood"],"distratoresEn":["the field","the desert","the garden","the lake"],"nivel":"A2","tags":["natureza"],"notaEn":"Feminine; the circumflex marks a lost «s» (Old French «forest», like English). «Le bois» is a smaller wood.","v":"410d1d44","transp":"parecida","pos":999},{"idioma":"fr","id":"fr-p553","tipo":"palavra","fr":"la montagne","en":"the mountain","aceitasEn":["mountain","the mountain","the mountains","mountains"],"distratoresEn":["the hill","the plain","the beach","the island"],"nivel":"A2","tags":["natureza","viagem"],"notaEn":"«À la montagne», in the mountains (on holiday), like «à la mer», at the seaside. The «gn» sounds like the «ny» in «canyon».","v":"ec9b536e","pos":723},{"idioma":"fr","id":"fr-p554","tipo":"palavra","fr":"demeurer","en":"to remain / to reside","aceitasEn":["to remain","remain","to reside","reside","to stay","stay","to live","live","to dwell","dwell"],"distratoresEn":["to leave / to return","to flee / to go out","to rest / to sleep","to dream / to think"],"nivel":"B2","tags":["verbo","cotidiano"],"notaEn":"Formal for to stay, to remain («je ne puis demeurer loin de toi», in Hugo), and also to reside («il demeure à Paris»). In the first sense the past tense takes «être»; in the second, «avoir». «La demeure» is a residence.","v":"a2ba3599","pos":3012},{"idioma":"fr","id":"fr-p555","tipo":"palavra","fr":"fixer","en":"to fasten","aceitasEn":["to fasten","fasten","to fix","fix","to set","set","to attach","attach","to stare at","stare at"],"distratoresEn":["to loosen","to move","to erase","to forget"],"nivel":"A2","tags":["verbo","cotidiano"],"notaEn":"To fasten or to set: «fixer une date», to set a date; «fixer un prix», to fix a price. With a person as object, to stare at: «il me fixe», he's staring at me. It does not mean to repair, which is «réparer».","v":"19beb97a","pos":1179},{"idioma":"fr","id":"fr-p556","tipo":"palavra","fr":"la pensée","en":"the thought","aceitasEn":["thought","the thought","thinking","the idea","idea"],"distratoresEn":["the dream","the wish","the silence","the gesture"],"nivel":"B1","tags":["filosofia"],"notaEn":"Feminine, from «penser». «Perdu dans ses pensées», lost in thought; «une pensée pour toi», thinking of you. It is also the flower: English «pansy» comes from «pensée».","v":"b876db53","pos":1701},{"idioma":"fr","id":"fr-p557","tipo":"palavra","fr":"dehors","en":"outside","aceitasEn":["outside","outdoors","out","out there"],"distratoresEn":["inside","upstairs","downstairs","far away"],"nivel":"A2","tags":["casa"],"notaEn":"The opposite is «dedans», inside. «En dehors de», outside of, apart from; «Dehors !», get out!; «au dehors», on the outside, in Hugo. The «h» is silent.","v":"fd75e1e2","pos":739},{"idioma":"fr","id":"fr-p558","tipo":"palavra","fr":"entendre","en":"to hear","aceitasEn":["to hear","hear"],"distratoresEn":["to see","to speak","to smell","to touch"],"nivel":"A1","tags":["verbo","falso-amigo","cotidiano"],"notaEn":"«Entendre» is to hear; to listen is «écouter», and to understand is «comprendre». «Tu m'entends ?», can you hear me? «S'entendre avec quelqu'un», to get along with someone.","v":"72f97998","pos":71},{"idioma":"fr","id":"fr-p559","tipo":"palavra","fr":"inconnu","aceitasFr":["inconnue"],"en":"unknown","aceitasEn":["unknown","unfamiliar"],"distratoresEn":["known","famous","forgotten","hidden"],"nivel":"B1","tags":["adjetivo","social"],"notaEn":"Feminine «inconnue». From «connaître», to know. As a noun, a stranger: «ne parle pas aux inconnus», don't talk to strangers.","v":"86f06845","pos":1540},{"idioma":"fr","id":"fr-p560","tipo":"palavra","fr":"croiser","en":"to cross","aceitasEn":["to cross","cross","to run into","run into","to bump into","bump into","to pass","pass","to come across","come across"],"distratoresEn":["to separate","to stretch","to squeeze","to let go"],"nivel":"B1","tags":["verbo","cotidiano"],"notaEn":"To cross over each other: «croiser les bras», to fold one's arms; «les mains croisées», hands crossed, in Hugo. With a person, to run into someone: «je l'ai croisé hier». To cross a street is «traverser».","v":"c83ac45f","pos":1949},{"idioma":"fr","id":"fr-p561","tipo":"palavra","fr":"l'or","en":"gold","aceitasEn":["gold","the gold"],"distratoresEn":["iron","copper","bronze","lead"],"nivel":"A1","tags":["objetos"],"notaEn":"Masculine. «En or», made of gold: «une bague en or»; «un cœur d'or», a heart of gold. Silver is «l'argent», which also means money.","v":"76414fb4","pos":583},{"idioma":"fr","id":"fr-p562","tipo":"palavra","fr":"la voile","en":"the sail","aceitasEn":["sail","the sail","sailing"],"distratoresEn":["the oar","the mast","the rudder","the anchor"],"nivel":"B1","tags":["viagem"],"notaEn":"Feminine: a sail, and the sport: «faire de la voile», to go sailing. Masculine «le voile» is a veil.","v":"5e1a6832","pos":1906},{"idioma":"fr","id":"fr-p563","tipo":"palavra","fr":"la tombe","en":"the grave","aceitasEn":["grave","the grave","the tomb","tomb"],"distratoresEn":["the coffin","the cemetery","the altar","the funeral"],"nivel":"A2","tags":["cultura"],"notaEn":"Feminine. Not to be confused with «il tombe», he falls, from «tomber». A cemetery is «le cimetière».","v":"2e50a122","pos":1401},{"idioma":"fr","id":"fr-p564","tipo":"palavra","fr":"le bouquet","en":"the bouquet","aceitasEn":["bouquet","the bouquet","the bunch of flowers","bunch of flowers","the bunch","the posy"],"distratoresEn":["the vase","the basket","the flowerbed","the garden"],"nivel":"B2","tags":["objetos"],"notaEn":"«Un bouquet de fleurs», a bunch of flowers; also a wine's aroma. «C'est le bouquet !», that's the last straw! «Le bouquet final», the fireworks finale.","v":"642f39ec","transp":"total","pos":2803},{"idioma":"fr","id":"fr-p565","tipo":"palavra","fr":"la fleur","en":"the flower","aceitasEn":["flower","the flower","the bloom","the blossom"],"distratoresEn":["the leaf","the root","the seed","the branch"],"nivel":"A1","tags":["natureza"],"notaEn":"«En fleur», in bloom: «un arbre en fleur»; the verb is «fleurir», to bloom. «À la fleur de l'âge», in the prime of life.","v":"28500a80","pos":586},{"idioma":"fr","id":"fr-p566","tipo":"palavra","leitura":true,"fr":"la langueur","en":"languor","aceitasEn":["languor","the languor","listlessness","lassitude","weariness","melancholy"],"distratoresEn":["fury","haste","euphoria","courage"],"nivel":"C1","tags":["filosofia"],"notaEn":"A literary word: a sad weariness, without strength or cause, as in Verlaine. From «languir», to languish.","v":"343ea30a"},{"idioma":"fr","id":"fr-p567","tipo":"palavra","leitura":true,"fr":"écœurer","aceitasFr":["écoeurer"],"en":"to sicken / to dishearten","aceitasEn":["to sicken","sicken","to disgust","disgust","to nauseate","nauseate","to dishearten","dishearten","to discourage","discourage"],"distratoresEn":["to cheer / to delight","to calm / to comfort","to scare / to hurt","to forget / to lose"],"nivel":"C1","tags":["verbo","filosofia"],"notaEn":"Literally to take the heart («cœur») out of: to sicken, as with something too sweet, and figuratively to dishearten. In Verlaine, «ce cœur qui s'écœure» is a heart sick of itself.","v":"0afcccaa"},{"idioma":"fr","id":"fr-p568","tipo":"palavra","leitura":true,"fr":"le deuil","en":"mourning","aceitasEn":["mourning","the mourning","grief","the grief","bereavement"],"distratoresEn":["forgiveness","jealousy","pride","boredom"],"nivel":"B2","tags":["cultura"],"notaEn":"Grief for someone's death, and the mourning one keeps: «être en deuil», to be in mourning. «Faire son deuil de quelque chose», to accept losing it. In Verlaine, a grief «sans raison», without cause.","v":"5fb0fcff"},{"idioma":"fr","id":"fr-p569","tipo":"palavra","leitura":true,"fr":"courber","en":"to bend","aceitasEn":["to bend","bend","to curve","curve","to bow","bow","to stoop","stoop","to hunch","hunch"],"distratoresEn":["to straighten","to stretch","to lift","to turn"],"nivel":"B2","tags":["verbo","corpo"],"notaEn":"Rare in speech, which prefers «plier» or «se pencher». «Le dos courbé», his back bent, in Hugo; «courber la tête», to bow one's head.","v":"819c5731"},{"idioma":"fr","id":"fr-p570","tipo":"palavra","leitura":true,"fr":"le houx","en":"holly","aceitasEn":["holly","the holly"],"distratoresEn":["pine","oak","moss","cypress"],"nivel":"C2","tags":["natureza"],"notaEn":"An evergreen shrub with spiny leaves and red berries, a Christmas decoration. In Hugo, the lasting green laid on the grave.","v":"ad6d8998"},{"idioma":"fr","id":"fr-p571","tipo":"palavra","leitura":true,"fr":"la bruyère","en":"heather","aceitasEn":["heather","the heather","heath"],"distratoresEn":["fern","nettle","ivy","lavender"],"nivel":"C2","tags":["natureza"],"notaEn":"A low shrub of moors and poor soil, with small purple or pink flowers. «En fleur», in bloom, in Hugo.","v":"759436c1"},{"idioma":"fr","id":"fr-u679","tipo":"frase","requer":"fr-p534","fr":"Pourquoi tu pleures ?","aceitasFr":["Pourquoi pleures-tu ?","Pourquoi est-ce que tu pleures ?","Tu pleures pourquoi ?","Pourquoi vous pleurez ?","Pourquoi pleurez-vous ?"],"en":"Why are you crying?","aceitasEn":["why are you crying","why do you cry","what are you crying for","whats making you cry"],"distratoresEn":["Why are you laughing?","Why are you shouting?","Why are you running?","Why are you shaking?"],"nivel":"A1","tags":["social"],"notaEn":"«Pleurer» is a regular «-er» verb: «tu pleures», with a silent «-s». French has no continuous form: «tu pleures» is both you cry and you are crying.","requerTodas":["fr-p534"],"v":"cdcc4f60"},{"idioma":"fr","id":"fr-u680","tipo":"frase","requer":"fr-p535","fr":"Elle a bon cœur.","aceitasFr":["Elle a bon coeur.","Elle a un bon cœur.","Elle a un bon coeur."],"en":"She has a good heart.","aceitasEn":["she has a good heart","shes got a good heart","she is kindhearted","shes kindhearted","she is kind hearted","shes kind hearted"],"distratoresEn":["She has good taste.","She has a good sense of humor.","She has good sense.","She has a good eye."],"nivel":"A1","tags":["social"],"notaEn":"«Avoir bon cœur», without an article, is to be kind-hearted. «De bon cœur», willingly. «Bon» goes before the noun.","requerTodas":["fr-p002","fr-p036","fr-p535"],"v":"b5c84ca9"},{"idioma":"fr","id":"fr-u681","tipo":"frase","requer":"fr-p536","fr":"Personne ne peut pénétrer dans cette chambre.","en":"Nobody can enter this room.","aceitasEn":["nobody can enter this room","no one can enter this room","nobody can go into this room","no one can go into this room","nobody can get into this room","no one can get into this room","nobody may enter this room"],"distratoresEn":["Nobody can sleep in this room.","Nobody can smoke in this room.","Nobody can eat in this room.","Nobody can talk in this room."],"nivel":"B2","tags":["casa"],"notaEn":"«Pénétrer dans» is a formal «entrer dans», suggesting going deep inside or without leave. «Personne ne…», nobody: the «ne» goes with the verb.","requerTodas":["fr-p006","fr-p536","fr-p107"],"v":"b4b39a86"},{"idioma":"fr","id":"fr-u682","tipo":"frase","requer":"fr-p537","fr":"Il y a trop de bruit ici.","en":"It's too noisy here.","aceitasEn":["its too noisy here","it is too noisy here","theres too much noise here","there is too much noise here","its too loud here","it is too loud in here","its too noisy in here"],"distratoresEn":["It's too windy here.","It's too dirty here.","It's too hot here.","It's too busy here."],"nivel":"A1","tags":["cidade"],"notaEn":"«Trop de» + noun, no article: «trop de bruit», too much noise. «Il y a», there is. To make noise is «faire du bruit».","requerTodas":["fr-p002","fr-p061","fr-p537","fr-p048"],"v":"cfa7e114"},{"idioma":"fr","id":"fr-u683","tipo":"frase","requer":"fr-p538","fr":"Il fait doux aujourd'hui.","aceitasFr":["Aujourd'hui, il fait doux."],"en":"It's mild today.","aceitasEn":["its mild today","it is mild today","the weather is mild today","the weathers mild today","its nice and mild today","its mild out today"],"distratoresEn":["It's cold today.","It's hot today.","It's dry today.","It's humid today."],"nivel":"A2","tags":["natureza"],"notaEn":"Weather goes with «il fait»: «il fait doux», it's mild; «il fait froid», «il fait chaud». «Doux» is neither cold nor hot.","requerTodas":["fr-p004","fr-p538","fr-p049"],"v":"23453ddb"},{"idioma":"fr","id":"fr-u684","tipo":"frase","requer":"fr-p539","fr":"On a marché sous la pluie.","aceitasFr":["Nous avons marché sous la pluie."],"en":"We walked in the rain.","aceitasEn":["we walked in the rain","we went walking in the rain","we walked through the rain"],"distratoresEn":["We walked in the snow.","We walked in the sand.","We walked in the mud.","We walked on the beach."],"nivel":"A2","tags":["natureza"],"notaEn":"In the rain is under it in French: «sous la pluie». «On a marché», past tense with «avoir»; in speech, «on» stands for we.","requerTodas":["fr-p002","fr-p270","fr-p539"],"v":"3e0ede30"},{"idioma":"fr","id":"fr-u685","tipo":"frase","requer":"fr-p540","fr":"Il est tombé par terre.","en":"He fell on the ground.","aceitasEn":["he fell on the ground","he fell to the ground","he fell down","he fell on the floor","he fell over"],"distratoresEn":["He fell in the river.","He fell in the hole.","He fell on the sofa.","He fell in the sea."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Par terre», on the ground or floor, no article: «tomber par terre», to fall down. «Tomber» takes «être» in the past: «il est tombé».","requerTodas":["fr-p001","fr-p228","fr-p540"],"v":"d69751fa"},{"idioma":"fr","id":"fr-u686","tipo":"frase","requer":"fr-p541","fr":"Il y a un chat sur le toit.","en":"There's a cat on the roof.","aceitasEn":["theres a cat on the roof","there is a cat on the roof","a cat is on the roof"],"distratoresEn":["There's a cat on the wall.","There's a cat on the car.","There's a cat on the sofa.","There's a cat in the garden."],"nivel":"A2","tags":["casa","animais"],"notaEn":"«Sur le toit», on the roof. «Il y a», there is or there are, serves for singular and plural.","requerTodas":["fr-p002","fr-p187","fr-p541"],"v":"3e679f45"},{"idioma":"fr","id":"fr-u687","tipo":"frase","requer":"fr-p542","fr":"Les enfants s'ennuient à la maison.","en":"The kids are bored at home.","aceitasEn":["the kids are bored at home","the children are bored at home","the kids get bored at home","the children get bored at home"],"distratoresEn":["The kids are tired at home.","The kids are scared at home.","The kids are alone at home.","The kids are sick at home."],"nivel":"A2","tags":["família","casa"],"notaEn":"«S'ennuyer», to be bored, is reflexive: «je m'ennuie», «ils s'ennuient». The «y» turns to «i» before a silent «e». «À la maison», at home.","requerTodas":["fr-p023","fr-p542","fr-p020"],"v":"2cec45ab"},{"idioma":"fr","id":"fr-u688","tipo":"frase","requer":"fr-p543","fr":"Elle prend des cours de chant.","en":"She takes singing lessons.","aceitasEn":["she takes singing lessons","shes taking singing lessons","she is taking singing lessons","she has singing lessons","she takes voice lessons"],"distratoresEn":["She takes piano lessons.","She takes drawing lessons.","She takes acting lessons.","She takes French lessons."],"nivel":"B1","tags":["cultura","escola"],"notaEn":"To take lessons is «prendre des cours». «Le chant» is singing as an art; a song is «la chanson».","requerTodas":["fr-p011","fr-p148","fr-p543"],"v":"c8e007e0"},{"idioma":"fr","id":"fr-u689","tipo":"frase","requer":"fr-p544","fr":"C'est une trahison !","en":"That's a betrayal!","aceitasEn":["thats a betrayal","that is a betrayal","its a betrayal","it is a betrayal","this is a betrayal","thats treason","what a betrayal"],"distratoresEn":["That's a disgrace!","That's madness!","That's a lie!","That's a joke!"],"nivel":"C1","tags":["social"],"notaEn":"«C'est», it's, that's, introduces a judgment. «La trahison», from «trahir», to betray; the middle «h» is silent.","requerTodas":["fr-p001","fr-p544"],"v":"f6f2f476"},{"idioma":"fr","id":"fr-u690","tipo":"frase","requer":"fr-p545","fr":"Le film est pire que le livre.","en":"The movie is worse than the book.","aceitasEn":["the movie is worse than the book","the film is worse than the book","the movies worse than the book"],"distratoresEn":["The movie is better than the book.","The movie is shorter than the book.","The movie is more famous than the book.","The movie is older than the book."],"nivel":"A2","tags":["cultura"],"notaEn":"«Pire que», worse than: the comparative of «mauvais». The opposite is «meilleur que».","requerTodas":["fr-p100","fr-p001","fr-p545","fr-p033"],"v":"ca0db4e5"},{"idioma":"fr","id":"fr-u691","tipo":"frase","requer":"fr-p546","fr":"Ce n'est pas la peine de venir.","en":"There's no need to come.","aceitasEn":["theres no need to come","there is no need to come","no need to come","you dont need to come","you dont have to come","its not worth coming"],"distratoresEn":["You can't come.","You don't want to come.","You're not going to come.","You shouldn't come."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Ce n'est pas la peine de» + infinitive: there's no need to, it's not worth it. In speech the «ne» drops: «c'est pas la peine».","requerTodas":["fr-p001","fr-p546","fr-p009"],"v":"33116b93"},{"idioma":"fr","id":"fr-u692","tipo":"frase","requer":"fr-p547","fr":"C'est un film d'amour.","en":"It's a romance movie.","aceitasEn":["its a romance movie","its a love film","its a love movie","its a romantic film","its a romantic movie","its a romance","it is a romance movie","its a love story"],"distratoresEn":["It's a horror movie.","It's a war movie.","It's an action movie.","It's a suspense movie."],"nivel":"A1","tags":["cultura"],"notaEn":"«Un film d'amour», no article after «de», which elides before a vowel. Likewise «une histoire d'amour», a love story.","requerTodas":["fr-p001","fr-p100","fr-p547"],"v":"498030e5"},{"idioma":"fr","id":"fr-u693","tipo":"frase","requer":"fr-p548","fr":"Il a de la haine dans le cœur.","aceitasFr":["Il a de la haine dans le coeur.","Il a de la haine au cœur.","Il a de la haine au coeur."],"en":"He has hatred in his heart.","aceitasEn":["he has hatred in his heart","he has hate in his heart","hes got hatred in his heart","hes got hate in his heart","he carries hatred in his heart"],"distratoresEn":["He has love in his heart.","He has fear in his heart.","He has pride in his heart.","He has joy in his heart."],"nivel":"B1","tags":["social"],"notaEn":"«De la haine», some hatred, with the partitive. The «h» is aspirated: «de la haine», no elision. French says «the» heart, not «his»: «dans le cœur».","requerTodas":["fr-p002","fr-p548","fr-p535"],"v":"ff8a13e4"},{"idioma":"fr","id":"fr-u694","tipo":"frase","requer":"fr-p549","fr":"Il a tant changé !","en":"He has changed so much!","aceitasEn":["he has changed so much","hes changed so much","he changed so much","how he has changed","how hes changed"],"distratoresEn":["He has changed so little!","He has changed quickly!","He has changed too!","He has changed again!"],"nivel":"A1","tags":["social"],"notaEn":"«Tant» sits between the auxiliary and the participle: «il a tant changé». With a noun, «tant de»: «tant de choses», so many things.","requerTodas":["fr-p002","fr-p549","fr-p511"],"v":"ddb7bf10"},{"idioma":"fr","id":"fr-u695","tipo":"frase","requer":"fr-p550","fr":"Ils sont partis à l'aube.","aceitasFr":["Elles sont parties à l'aube."],"en":"They left at dawn.","aceitasEn":["they left at dawn","they left at daybreak","they set off at dawn","they set out at dawn","they left at first light","they went away at dawn"],"distratoresEn":["They left at nightfall.","They left at dusk.","They left at noon.","They left at sunset."],"nivel":"B2","tags":["viagem"],"notaEn":"«À l'aube», at dawn. «Partir», to leave, takes «être» in the past, and the participle agrees: «ils sont partis», «elles sont parties».","requerTodas":["fr-p001","fr-p083","fr-p550"],"v":"1da2ce56"},{"idioma":"fr","id":"fr-u696","tipo":"frase","requer":"fr-p551","fr":"La campagne blanchit sous la neige.","en":"The countryside turns white with snow.","aceitasEn":["the countryside turns white with snow","the countryside turns white under the snow","the countryside is turning white with snow","the countryside goes white with snow","the fields turn white with snow","the countryside whitens under the snow"],"distratoresEn":["The countryside turns dark with snow.","The countryside turns quiet with snow.","The countryside turns empty with snow.","The countryside turns muddy with snow."],"nivel":"C1","tags":["natureza"],"notaEn":"«Blanchir» with no object means to turn white, like «rougir», to turn red, and «grandir», to grow: all conjugate like «finir». «Sous la neige», under the snow.","requerTodas":["fr-p332","fr-p551","fr-p384"],"v":"07a6e2fe"},{"idioma":"fr","id":"fr-u697","tipo":"frase","requer":"fr-p552","fr":"On s'est perdus dans la forêt.","aceitasFr":["On s'est perdu dans la forêt.","Nous nous sommes perdus dans la forêt."],"en":"We got lost in the forest.","aceitasEn":["we got lost in the forest","we got lost in the woods","we lost our way in the forest","we lost our way in the woods","we were lost in the forest"],"distratoresEn":["We got lost in the city.","We got lost in the market.","We got lost in the crowd.","We got lost on the road."],"nivel":"A2","tags":["natureza","viagem"],"notaEn":"«Se perdre», to get lost, takes «être» in the past: «on s'est perdus». When «on» means we, the participle may take the plural.","requerTodas":["fr-p323","fr-p552"],"v":"b78e0a5b"},{"idioma":"fr","id":"fr-u698","tipo":"frase","requer":"fr-p553","fr":"Cet été, on va à la montagne.","aceitasFr":["Cet été, nous allons à la montagne.","On va à la montagne cet été."],"en":"This summer we're going to the mountains.","aceitasEn":["this summer were going to the mountains","this summer we are going to the mountains","were going to the mountains this summer","this summer were going to the mountain","this summer we go to the mountains"],"distratoresEn":["This summer we're going to the beach.","This summer we're going to the farm.","This summer we're going to the city.","This summer we're going to the island."],"nivel":"A2","tags":["viagem"],"notaEn":"«Aller à la montagne», to go to the mountains on holiday, like «aller à la mer», to the seaside. «Cet été», with «cet» before a vowel.","requerTodas":["fr-p285","fr-p003","fr-p553"],"v":"83c3a450"},{"idioma":"fr","id":"fr-u699","tipo":"frase","requer":"fr-p554","fr":"Il est demeuré seul.","en":"He remained alone.","aceitasEn":["he remained alone","he stayed alone","he remained on his own","he stayed on his own","he was left alone"],"distratoresEn":["He was born alone.","He died alone.","He arrived alone.","He left alone."],"nivel":"B2","tags":["social"],"notaEn":"«Demeurer» is a formal «rester», to stay, and in that sense takes «être» in the past: «il est demeuré». In speech one would say «il est resté seul».","requerTodas":["fr-p001","fr-p554","fr-p306"],"v":"5a2880bc"},{"idioma":"fr","id":"fr-u700","tipo":"frase","requer":"fr-p555","fr":"On a fixé la date de la réunion.","aceitasFr":["Nous avons fixé la date de la réunion."],"en":"We set the date of the meeting.","aceitasEn":["we set the date of the meeting","we set the date for the meeting","we set the meeting date","weve set the date for the meeting","we fixed the date of the meeting","we fixed the date for the meeting","we scheduled the meeting"],"distratoresEn":["We changed the date of the meeting.","We forgot the date of the meeting.","We postponed the date of the meeting.","We lost the date of the meeting."],"nivel":"A2","tags":["trabalho"],"notaEn":"«Fixer une date», to set a date; also «fixer un rendez-vous», to set up an appointment. To postpone is «reporter».","requerTodas":["fr-p002","fr-p555","fr-p524","fr-p261"],"v":"51faa462"},{"idioma":"fr","id":"fr-u701","tipo":"frase","requer":"fr-p556","fr":"Il était perdu dans ses pensées.","en":"He was lost in thought.","aceitasEn":["he was lost in thought","he was lost in his thoughts","he was deep in thought","he was miles away"],"distratoresEn":["He was lost in his papers.","He was lost in his books.","He was lost in his numbers.","He was lost in his maps."],"nivel":"B1","tags":["filosofia"],"notaEn":"«Perdu dans ses pensées», lost in thought; French uses the possessive. «Était» is the imperfect of «être», setting the scene.","requerTodas":["fr-p001","fr-p323","fr-p556"],"v":"1faccdf1"},{"idioma":"fr","id":"fr-u702","tipo":"frase","requer":"fr-p557","fr":"Les enfants jouent dehors.","en":"The kids are playing outside.","aceitasEn":["the kids are playing outside","the children are playing outside","the kids play outside","the children play outside","the kids are playing outdoors","the children are playing outdoors"],"distratoresEn":["The kids are playing inside.","The kids are playing upstairs.","The kids are playing downstairs.","The kids are playing nearby."],"nivel":"A2","tags":["família"],"notaEn":"«Jouer» is to play. «Dehors» comes after the verb; the opposite is «dedans», inside.","requerTodas":["fr-p023","fr-p073","fr-p557"],"v":"fbe521c8"},{"idioma":"fr","id":"fr-u703","tipo":"frase","requer":"fr-p558","fr":"Je n'entends rien.","aceitasFr":["J'entends rien."],"en":"I can't hear anything.","aceitasEn":["i cant hear anything","i cannot hear anything","i can not hear anything","i dont hear anything","i hear nothing","i cant hear a thing"],"distratoresEn":["I can't see anything.","I can't feel anything.","I'm not doing anything.","I'm not saying anything."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Entendre» is to hear; not understanding anything is «je ne comprends rien». «Ne… rien», nothing, wraps the verb; in speech the «ne» drops: «j'entends rien».","requerTodas":["fr-p558"],"v":"cd981269"},{"idioma":"fr","id":"fr-u704","tipo":"frase","requer":"fr-p559","fr":"Je suis dans une ville inconnue.","en":"I'm in an unfamiliar city.","aceitasEn":["im in an unfamiliar city","i am in an unfamiliar city","im in an unknown city","im in a strange city","im in a city i dont know"],"distratoresEn":["I'm in a big city.","I'm in a small city.","I'm in a beautiful city.","I'm in an empty city."],"nivel":"B1","tags":["viagem","cidade"],"notaEn":"The adjective agrees: «une ville inconnue», with a nearly silent «-e». It follows the noun.","requerTodas":["fr-p001","fr-p028","fr-p559"],"v":"85fa236d"},{"idioma":"fr","id":"fr-u705","tipo":"frase","requer":"fr-p560","fr":"Je l'ai croisé dans la rue.","en":"I ran into him in the street.","aceitasEn":["i ran into him in the street","i ran into him on the street","i bumped into him in the street","i bumped into him on the street","i passed him in the street","i passed him on the street","i came across him in the street"],"distratoresEn":["I fought with him in the street.","I talked to him in the street.","I danced with him in the street.","I argued with him in the street."],"nivel":"B1","tags":["cidade","social"],"notaEn":"«Croiser quelqu'un», to run into someone, with no preposition. «L'» is «le» before a vowel; for her, «je l'ai croisée».","requerTodas":["fr-p002","fr-p560","fr-p032"],"v":"b23cd280"},{"idioma":"fr","id":"fr-u706","tipo":"frase","requer":"fr-p561","fr":"Cette bague est en or.","en":"This ring is gold.","aceitasEn":["this ring is gold","this ring is made of gold","this is a gold ring","this rings gold"],"distratoresEn":["This ring is silver.","This ring is plastic.","This ring is glass.","This ring is iron."],"nivel":"A1","tags":["objetos"],"notaEn":"The material goes with «en»: «en or», gold; «en bois», wooden. «La bague» is feminine, hence «cette».","requerTodas":["fr-p532","fr-p001","fr-p561"],"v":"6e9ecc44"},{"idioma":"fr","id":"fr-u707","tipo":"frase","requer":"fr-p562","fr":"On a fait de la voile cet été.","aceitasFr":["Nous avons fait de la voile cet été.","Cet été, on a fait de la voile."],"en":"We went sailing this summer.","aceitasEn":["we went sailing this summer","this summer we went sailing","we sailed this summer","we did some sailing this summer"],"distratoresEn":["We went camping this summer.","We went fishing this summer.","We went diving this summer.","We went surfing this summer."],"nivel":"B1","tags":["viagem"],"notaEn":"Sports go with «faire de»: «faire de la voile», to go sailing; «faire du vélo», to go cycling. «Cet été», this summer.","requerTodas":["fr-p002","fr-p004","fr-p562","fr-p285"],"v":"11083b13"},{"idioma":"fr","id":"fr-u708","tipo":"frase","requer":"fr-p563","fr":"Ils ont mis des fleurs sur sa tombe.","en":"They put flowers on his grave.","aceitasEn":["they put flowers on his grave","they put flowers on her grave","they laid flowers on his grave","they laid flowers on her grave","they left flowers on his grave","they placed flowers on his grave","they put flowers on his tomb"],"distratoresEn":["They put flowers on his car.","They put flowers on his desk.","They put flowers on his doorstep.","They put flowers on his bed."],"nivel":"A2","tags":["cultura"],"notaEn":"«Mettre», to put, has an irregular participle: «mis». «Sa tombe» is his or her grave: the possessive agrees with the thing, not the owner.","requerTodas":["fr-p002","fr-p167","fr-p565","fr-p563"],"v":"346c94cb"},{"idioma":"fr","id":"fr-u709","tipo":"frase","requer":"fr-p564","fr":"Il m'a donné un bouquet de fleurs.","en":"He gave me a bouquet of flowers.","aceitasEn":["he gave me a bouquet of flowers","he gave me a bunch of flowers","he gave me a bouquet","he gave me flowers"],"distratoresEn":["He gave me a vase of flowers.","He gave me a basket of flowers.","He gave me a box of flowers.","He gave me a bag of flowers."],"nivel":"B2","tags":["objetos"],"notaEn":"«Un bouquet de fleurs», no article after «de». The pronoun goes before the auxiliary: «il m'a donné», he gave me.","requerTodas":["fr-p002","fr-p195","fr-p564","fr-p565"],"v":"a5b19fff"},{"idioma":"fr","id":"fr-u710","tipo":"frase","requer":"fr-p565","fr":"Les arbres sont en fleur.","aceitasFr":["Les arbres sont en fleurs."],"en":"The trees are in bloom.","aceitasEn":["the trees are in bloom","the trees are in flower","the trees are in blossom","the trees are blooming","the trees are blossoming","the trees are flowering"],"distratoresEn":["The trees are dry.","The trees are green.","The trees are bare.","The trees are pruned."],"nivel":"A1","tags":["natureza"],"notaEn":"«En fleur», in bloom, no article; Hugo brings «de la bruyère en fleur» to the grave. The verb is «fleurir», to bloom.","requerTodas":["fr-p520","fr-p001","fr-p565"],"v":"1b8afee0"}]};
